/* Quantumwake dashboard.
 *
 * No framework and no external requests: the page is served by the local
 * process and also loaded by the overlay's WebView2, so it stays dependency
 * free. Live updates arrive over Server-Sent Events, which every browser
 * supports natively. */

const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => Array.from(document.querySelectorAll(sel));

const params = new URLSearchParams(location.search);

/** True when hosted in the overlay shell, which wants a denser layout. */
const isOverlay = params.has('overlay');

/**
 * True for ?snapshot=1, which loads the data once and then leaves the page
 * still. The live event stream never closes, so a headless browser waits on it
 * forever and never reaches the load event - which is why documentation
 * screenshots could not be captured until this existed.
 */
const isSnapshot = params.has('snapshot');

const KIND_COLOURS = {
  City: '#7fe4ff',
  RestStop: '#4fd48a',
  Outpost: '#ffab3d',
  Research: '#b58cf0',
  DistributionCentre: '#ff5a4d',
  JumpPoint: '#eaf6ff',
  Mine: '#c78b4a',
  Asteroid: '#8fa0b6',
  Station: '#35c8f0',
  Planet: '#7796b0',
  Moon: '#46617a',
  NavPoint: '#46617a',
  MissionBeacon: '#ffab3d',
  Unknown: '#46617a',
};

/* Body order defines the ring layout, innermost first. */
const SYSTEMS = {
  Stanton: ['Hurston', 'Arial', 'Aberdeen', 'Magda', 'Ita', 'Crusader', 'Cellin', 'Daymar',
            'Yela', 'ArcCorp', 'Lyria', 'Wala', 'microTech', 'Calliope', 'Clio', 'Euterpe'],
  Pyro: ['Pyro I', 'Monox', 'Bloom', 'Pyro IV', 'Pyro V', 'Terminus'],
  Nyx: ['Delamar', 'Glaciem Ring', 'Keeger Belt'],
};

/* ---------- helpers ---------- */

const pad = (n) => String(n).padStart(2, '0');

function duration(seconds) {
  if (!seconds || seconds < 0) return '—';
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  if (h === 0) return `${m}m`;
  return `${h}h ${pad(m)}m`;
}

function clock(fromIso) {
  if (!fromIso) return '—';
  const secs = Math.max(0, (Date.now() - new Date(fromIso).getTime()) / 1000);
  const h = Math.floor(secs / 3600);
  const m = Math.floor((secs % 3600) / 60);
  const s = Math.floor(secs % 60);
  return `${pad(h)}:${pad(m)}:${pad(s)}`;
}

const timeOf = (iso) => new Date(iso).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
const shortTimeOf = (iso) => new Date(iso).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
const dateOf = (iso) => new Date(iso).toLocaleDateString([], { year: 'numeric', month: 'short', day: '2-digit' });

/**
 * A calendar day as it was written, not as the reader's clock re-reads it.
 *
 * A wipe is a day rather than a moment: it is stored at midnight UTC and typed
 * into a date field that means UTC. Formatting that in local time shows the day
 * before to everyone west of Greenwich - the Settings field said the 15th while
 * the notice beside it said the 14th, which is exactly how a date stops being
 * believed.
 */
const UTC_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
                    'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

// Assembled from the UTC parts rather than asked of Intl: a timeZone option is
// not honoured everywhere this page runs, and a date that quietly falls back to
// local time is the bug this exists to prevent.
const dayUtc = (iso) => {
  const at = new Date(iso);

  return `${UTC_MONTHS[at.getUTCMonth()]} ${String(at.getUTCDate()).padStart(2, '0')}, `
    + `${at.getUTCFullYear()}`;
};

/* Day and month only, for dense rows where a year wraps the line. */

const dayOf = (iso) => new Date(iso).toLocaleDateString([], { month: 'short', day: '2-digit' });

async function getJson(url) {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`${url} -> ${response.status}`);
  return response.json();
}

function el(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

/*
 * An answer is only as useful as knowing which evidence supports it.  These
 * four labels are deliberately small and fixed: every new view can use the
 * same language instead of quietly inventing another way to say "probably".
 */
const DATA_SOURCES = {
  logs: {
    label: 'GAME LOG',
    name: 'your game log',
    detail: 'Events written by Star Citizen to Game.log and its local backups.',
  },
  install: {
    label: 'GAME INSTALL',
    name: 'your game install',
    detail: 'Reference data read from the Star Citizen files installed on this PC.',
  },
  screenshot: {
    label: 'SCREENSHOT / OCR',
    name: 'a screenshot reading',
    detail: 'A saved screenshot read locally. It describes the moment it was captured.',
  },
  community: {
    label: 'COMMUNITY DATA',
    name: 'optional community data',
    detail: 'The optional community dataset you chose to download; it is not a live game feed.',
  },
};

// The dashboard's markup is also represented by a deliberately small test
// DOM, which creates nodes by id instead of parsing the whole document. Keep
// the first source-bearing answers listed here so browser and tests start from
// the same evidence contract; later dynamic views still use setSourceMarks.
const SOURCE_SLOT_IDS = [
  ['#now-location-source', ['logs']],
  ['#now-ship-source', ['logs']],
  ['#now-session-source', ['logs']],
  ['#now-feed-source', ['logs']],
  ['#now-stats-source', ['logs'], 'INFERRED'],
  ['#now-screen-source', ['screenshot']],
  ['#now-earning-source', ['logs', 'screenshot']],
  ['#hangar-data-sources', ['logs', 'install']],
  ['#help-data-sources', ['logs', 'install', 'screenshot', 'community']],
];

function sourceMarks(keys, qualifier = '') {
  const known = (Array.isArray(keys) ? keys : String(keys || '').split(/[\s,]+/))
    .map((key) => DATA_SOURCES[key]).filter(Boolean);
  const marks = el('span', 'data-sources');
  marks.setAttribute('role', 'note');
  marks.setAttribute('aria-label', `Data sources: ${known.map((source) => source.name).join(', ')}`);

  for (const source of known) {
    const mark = el('span', `data-source ${source.label.toLowerCase().replace(/[^a-z]+/g, '-')}`, source.label);
    mark.title = source.detail;
    marks.append(mark);
  }
  if (qualifier) marks.append(el('span', 'data-source data-source-qualifier', qualifier));
  return marks;
}

/** Fill declarative source slots in markup; dynamic views call this same helper. */
function setSourceMarks(node, keys, qualifier = '') {
  if (!node) return;
  node.textContent = '';
  const known = (Array.isArray(keys) ? keys : String(keys || '').split(/[\s,]+/))
    .filter((key) => DATA_SOURCES[key]);
  node.hidden = known.length === 0;
  if (known.length) node.append(sourceMarks(known, qualifier));
}

function hydrateSourceMarks() {
  for (const node of $$('.source-slot'))
    setSourceMarks(node, node.dataset.sources, node.dataset.sourceQualifier || '');
  for (const [id, keys, qualifier] of SOURCE_SLOT_IDS)
    setSourceMarks($(id), keys, qualifier || '');
}

hydrateSourceMarks();

/* ---------- period selector ---------- */

/**
 * The one definition of the time windows every view offers.
 *
 * Six views needed the same control, so it is built from here rather than
 * repeated in markup - adding a window means editing this list once.
 */
const PERIODS = [
  { days: 0, label: 'All time' },
  { days: 1, label: 'Last 24 hours' },
  { days: 3, label: 'Last 3 days' },
  { days: 7, label: 'Last 7 days' },
  { days: 30, label: 'Last 30 days' },
  { days: 90, label: 'Last 90 days' },
  { days: 180, label: 'Last 6 months' },
  { days: 365, label: 'Last year' },
];

/** Fills every `select.period`. A view can reword its all-time option via data-all. */
function buildPeriodSelects() {
  for (const select of $$('select.period')) {
    const allLabel = select.dataset.all || PERIODS[0].label;

    for (const period of PERIODS) {
      const option = document.createElement('option');
      option.value = String(period.days);
      option.textContent = period.days === 0 ? allLabel : period.label;
      select.append(option);
    }
  }
}

buildPeriodSelects();

/* ---------- tabs ---------- */

/** The pages where a stale price is a wrong number rather than a fact about a feed. */
const STALE_MATTERS_ON = new Set(['market', 'commodity', 'garage', 'jobs', 'routes']);

function showView(name) {
  // Assets merged into Fleet; old #assets links and habits still land somewhere.
  if (name === 'assets') name = 'fleet';

  // The stale-prices notice speaks in full only where old prices change the
  // answer - Market, Garage, Shopping, Routes and the commodity drill-down.
  // Everywhere else it is a chip: the fact stays in view, the paragraph and
  // the buttons do not crowd a page that is not about prices.
  $('#stale')?.classList.toggle('compact', !STALE_MATTERS_ON.has(name));

  const buttons = $$('#tabs button');

  // Commodity, Help and a share recap are drill-downs rather than tabs. Their
  // parent stays lit, but each has its own fragment so a saved HTML report is
  // not confused with the app's live dashboard.
  const target = buttons.find(
    (b) => b.dataset.view === (name === 'commodity' ? 'market' : name === 'help' ? 'about' : name === 'share' ? 'settings' : name));

  if (!target) return;

  // Leaving the drill-down forgets its subject. The name alone is not enough
  // for the hash handler to know the page is up: keep it after a tab click and
  // a later link back to the same commodity matches, returns, and moves the
  // fragment with Market still on screen.
  if (name !== 'commodity') openCommodityName = null;

  // The text overlay reads the game folder and rebuilds its plan, so it is read
  // on entry rather than cached: StarStrings may have been installed since, and
  // the plan is layered on whatever is actually there.
  if (name === 'labels') loadTextOverlay().catch(() => {});

  // The trading rate moves only when a session ends, so it is read on entry
  // rather than on every tick of the live stream.
  if (name === 'now') loadEarnings().catch(() => {});
  if (name === 'mining') {
    loadGameData().catch(() => {});
    loadMiningPlaces().catch(() => {});
    loadLikelyMined().catch(() => {});
    loadMiningLog().catch(() => {});
    loadCrackModel().catch(() => {});
    loadSalvage().catch(() => {});
    // A rock handed over from the Log opens on the calculator; otherwise the
    // page opens where it was left.
    showMiningPane(crackFromScan ? 'crack' : miningPane);
  }

  // Settings reflects live state (the tray can change it), so re-read on entry.
  if (name === 'settings') {
    renderSettings().catch(() => {});
    loadGameData().catch(() => {});
  }

  // A log is a live reference, not an Overlay setting. Read it when the pilot
  // opens its tab so pasted locations and screenshots stay together.
  if (name === 'log') {
    renderScreenPanel().catch(() => {});
    showLogPane(logPane);
  }

  // Jobs change from the Crafting page and from play, so re-read on entry too.
  // The keybinding profile is the game's file and changes under the app;
  // read on entry so the page is never a stale copy of it.
  if (name === 'controls') loadControls().catch(() => {});
  if (name === 'jobs' || name === 'blueprints') loadJobs().catch(() => {});
  if (name === 'checklists') loadChecklists().catch(() => {});
  if (name === 'imports') loadImports().catch(() => {});
  if (name === 'loadout') loadKits().catch(() => {});
  if (name === 'commodities') renderSharedReceipts().catch(() => {});
  if (name === 'blueprints') renderSharedBlueprints().catch(() => {});

  // These read live state or want the freshest prices, so they re-run on entry.
  if (name === 'routes') loadRoutes().catch(() => {});
  if (name === 'casualties') loadCasualties().catch(() => {});
  if (name === 'crew') loadCrew().catch(() => {});
  if (name === 'servers') loadServers().catch(() => {});
  if (name === 'garage') loadGarage().catch(() => {});
  if (name === 'armoury') loadArmoury().catch(() => {});
  if (name === 'points') loadPoints().catch(() => {});
  if (name === 'wikelo') loadWikelo().catch(() => {});

  // The overlay page shows live state from both halves of the app.
  if (name === 'overlay') {
    renderSettings().catch(() => {});
    renderOverlayLayout().catch(() => {});
    renderScreenPanel().catch(() => {});
  }

  buttons.forEach((b) => b.classList.toggle('active', b === target));
  $$('.view').forEach((v) => v.classList.toggle('active', v.id === `view-${name}`));

  // The scale drawing needs the deck's rendered width.  Fetch after making the
  // view visible: measuring it while display:none makes the fallback 1200 px
  // wide, which leaves a needless horizontal scrollbar on narrower windows.
  if (name === 'hangar') loadHangar().catch(() => {});

  // Both of the Fleet page's screenshot sections hang off this call, and
  // without it neither has ever been drawn outside a test: what each ship was
  // last photographed carrying, and where the Fleet Manager last showed each
  // one parked - the only source for that, since the logs never say where a
  // ship sits. They were written, documented and covered by tests, and the one
  // line that runs them was missing, so the headings stayed hidden and the
  // page looked like it had nothing to show.
  if (name === 'fleet') renderFleetFittings().catch(() => {});

  // A group lights up when the active view lives inside it, so the strip
  // still shows where you are even with the menu closed.
  $$('#tabs .tab-group').forEach((g) => {
    g.querySelector('.group-btn')?.classList
      .toggle('active', Boolean(g.querySelector('button.active[data-view]')));
  });

  // Switching view shows the top of it.
  //
  // The map's SVG is id="starmap" rather than the obvious id="map" for the same
  // reason: with the view in the fragment, #map would have matched that element
  // and the browser would anchor-scroll to it after load, leaving the header
  // stranded mid-screen. Fragments name views here, so no element may share a
  // view's name.
  window.scrollTo(0, 0);

  // Keep the active tab in view when the strip scrolls, as it does in overlay mode.
  target.scrollIntoView({ block: 'nearest', inline: 'center' });

  // replaceState, not assignment: cycling views with the arrow keys should not
  // fill the back button with thirty entries.
  if (location.hash !== `#${name}`) history.replaceState(null, '', `#${name}`);
}

/* The view lives in the URL fragment, so #map is a link that can be sent to
   someone and a page that survives a refresh. */
function viewFromHash() {
  const name = decodeURIComponent(location.hash.replace(/^#/, ''));
  // A recap is built on demand and lives only in this page, so a bookmarked
  // or refreshed #share has nothing to show; it lands where the button is.
  if (name === 'share') return shareReportData ? 'share' : 'settings';
  return name === 'help' || $$('#tabs button').some((b) => b.dataset.view === name) ? name : null;
}

/**
 * The commodity page carries its subject in the fragment - #commodity/Aluminum
 * - so a drill-down is a link like every other view, and survives a refresh.
 */
function commodityFromHash() {
  const raw = location.hash.replace(/^#/, '');
  return raw.startsWith('commodity/') ? decodeURIComponent(raw.slice('commodity/'.length)) : null;
}

window.addEventListener('hashchange', () => {
  const commodity = commodityFromHash();

  if (commodity) {
    if (commodity !== openCommodityName) openCommodity(commodity).catch(() => {});
    return;
  }

  const name = viewFromHash();
  if (name) showView(name);
});

$('#tabs').addEventListener('click', (event) => {
  const button = event.target.closest('button');
  if (!button || !button.dataset.view) return;

  showView(button.dataset.view);

  // Dropping focus lets a group menu close once a view is picked; otherwise
  // :focus-within pins it open over the page.
  button.blur();
});

// Help belongs under About rather than in a crowded navigation strip. Its
// fragment still works as a link, and About remains lit while it is open.
$('#about-open-help')?.addEventListener('click', () => showView('help'));
$('#help-back')?.addEventListener('click', () => showView('about'));

/**
 * The Help filter. Twenty-odd answers is past what anyone scrolls, so a word
 * narrows the page to the questions that mention it - question and answer
 * both, since "wipe" is in an answer whose question says "totals". A section
 * with nothing left folds away; nothing left at all says so and points at
 * the Discord, which is where an unanswered question goes.
 */
function filterHelp(query) {
  const words = (query || '').trim().toLowerCase().split(/\s+/).filter(Boolean);
  const root = $('#view-help');
  const items = root ? Array.from(root.querySelectorAll('.faq-item')) : [];
  let shown = 0;

  for (const item of items) {
    const text = item.textContent.toLowerCase();
    const hit = words.every((word) => text.includes(word));
    item.hidden = !hit;
    if (hit) shown++;
    // A match opens the answer: the word searched for is usually in it.
    if (hit && words.length) item.open = true;
  }

  for (const section of Array.from(root?.querySelectorAll('.help-section') || []))
    section.hidden = !Array.from(section.querySelectorAll('.faq-item')).some((item) => !item.hidden);

  const none = $('#help-none');
  if (none) none.hidden = shown > 0;

  const count = $('#help-count');
  if (count) count.textContent = words.length ? `${shown} of ${items.length}` : '';

  return shown;
}

/** Every visible answer open, or every one closed - whichever the button says. */
function expandHelp(open) {
  const root = $('#view-help');
  for (const item of Array.from(root?.querySelectorAll('.faq-item') || [])) if (!item.hidden) item.open = open;
  const button = $('#help-expand');
  if (button) button.textContent = open ? 'Collapse all' : 'Expand all';
}

$('#help-search')?.addEventListener('input', (event) => filterHelp(event.target.value));
$('#help-expand')?.addEventListener('click', () => {
  const button = $('#help-expand');
  expandHelp(button.textContent !== 'Collapse all');
});

/* Driven by the overlay shell's global hotkeys, so views can be changed without
   unlocking click-through. Also bound to the arrow keys for browser use. */
window.scCycleView = (delta) => {
  // In the overlay, only the tabs actually on show: it hides most of the
  // strip, and cycling into an invisible view would strand the widget
  // somewhere its own tab bar cannot reach. The dashboard cycles everything -
  // its group menus hide buttons without retiring the views behind them.
  const buttons = $$('#tabs button').filter((b) => b.dataset.view
    && (isOverlay ? b.offsetParent !== null : true));
  if (!buttons.length) return;

  const current = buttons.findIndex((b) => b.classList.contains('active'));
  const next = (current + delta + buttons.length) % buttons.length;
  showView(buttons[next].dataset.view);
};

window.scShowView = showView;

/* Driven by the overlay shell's fullscreen toggle: at full size the widget can
   afford the whole tab strip, so the six-tab whitelist lifts while expanded. */
window.scOverlayExpanded = (on) => {
  document.body.classList.toggle('expanded', Boolean(on));

  // Fullscreen shows everything; going back re-applies the chosen few.
  if (isOverlay) applyOverlayLayout().catch(() => {});
};

/* ---------- page stats collapse ----------
 *
 * A page whose analysis sits above its table pushes the newest rows below the
 * fold - Contracts leads with four tiles, a standing table with a paragraph of
 * caveat, and two charts before the first contract. Folding that away is a
 * per-reader preference, so it lives in localStorage next to the Now page's
 * card collapse rather than in server settings.
 *
 * Markup declares both halves: a button carrying data-stats-toggle="<name>"
 * and the panel it folds at id "<name>-stats". Adding this to another page is
 * then two attributes and no JavaScript. */

const STATS_COLLAPSED_KEY = 'qw-collapsed-page-stats';
let collapsedPageStats = new Set();

try {
  const saved = JSON.parse(localStorage.getItem(STATS_COLLAPSED_KEY) || '[]');
  if (Array.isArray(saved)) collapsedPageStats = new Set(saved);
} catch { /* a bad preference must not hide a page's summary for ever */ }

function saveCollapsedPageStats() {
  try { localStorage.setItem(STATS_COLLAPSED_KEY, JSON.stringify([...collapsedPageStats])); } catch { /* optional */ }
}

function initPageStatsCollapsers() {
  for (const button of $$('[data-stats-toggle]')) {
    const name = button.dataset.statsToggle;
    const panel = $(`#${name}-stats`);
    if (!name || !panel) continue;

    const apply = (collapsed) => {
      panel.hidden = collapsed;

      // Named rather than an arrow, because a button reading "Summary" gives no
      // clue which way it goes - and the summary is gone when it matters most.
      button.textContent = collapsed ? 'Show summary' : 'Hide summary';
      button.title = collapsed
        ? 'Show the summary, standing and charts again'
        : 'Hide the summary and go straight to the contracts';
      button.setAttribute('aria-label', button.title);
      button.setAttribute('aria-expanded', String(!collapsed));
    };

    button.type = 'button';
    button.addEventListener('click', () => {
      const collapsed = !panel.hidden;
      if (collapsed) collapsedPageStats.add(name);
      else collapsedPageStats.delete(name);
      saveCollapsedPageStats();
      apply(collapsed);
    });

    apply(collapsedPageStats.has(name));
  }
}

/* ---------- Now card collapse ---------- */

const NOW_COLLAPSED_KEY = 'qw-now-collapsed-cards';
const NOW_HIDDEN_KEY = 'qw-now-hidden-cards';
const NOW_ORDER_KEY = 'qw-now-card-order';
let collapsedNowCards = new Set();
let hiddenNowCards = new Set();
let nowCardOrder = [];
let draggedNowCard = null;

try {
  const saved = JSON.parse(localStorage.getItem(NOW_COLLAPSED_KEY) || '[]');
  if (Array.isArray(saved)) collapsedNowCards = new Set(saved);
} catch { /* a bad preference must not hide the dashboard */ }

try {
  const saved = JSON.parse(localStorage.getItem(NOW_HIDDEN_KEY) || '[]');
  if (Array.isArray(saved)) hiddenNowCards = new Set(saved);
} catch { /* a bad preference must not remove a dashboard card */ }

try {
  const saved = JSON.parse(localStorage.getItem(NOW_ORDER_KEY) || '[]');
  if (Array.isArray(saved)) nowCardOrder = saved.filter((n) => typeof n === 'string');
} catch { /* a bad preference must not scramble the dashboard */ }

function saveCollapsedNowCards() {
  try { localStorage.setItem(NOW_COLLAPSED_KEY, JSON.stringify([...collapsedNowCards])); } catch { /* optional */ }
}

function saveHiddenNowCards() {
  try { localStorage.setItem(NOW_HIDDEN_KEY, JSON.stringify([...hiddenNowCards])); } catch { /* optional */ }
}

function saveNowCardOrder() {
  try { localStorage.setItem(NOW_ORDER_KEY, JSON.stringify(nowCardOrder)); } catch { /* optional */ }
}

/**
 * The order to draw the cards in: the saved one, reconciled with the markup.
 *
 * A card the saved order never saw goes back where the markup puts it - beside
 * the neighbour it was designed to sit next to - rather than to the end. The
 * overlay's layout store makes the same promise for the same reason: a card
 * added in a later version must not read as one the reader arranged away, or
 * anyone who ever touched these controls would quietly stop seeing new work.
 */
function resolveNowOrder(natural, saved) {
  const seen = new Set(saved);
  const order = saved.filter((name) => natural.includes(name));

  natural.forEach((name, index) => {
    if (seen.has(name)) return;

    let at = order.length;
    for (let before = index - 1; before >= 0; before--) {
      const found = order.indexOf(natural[before]);
      if (found !== -1) { at = found + 1; break; }
    }
    order.splice(at, 0, name);
  });

  return order;
}

/** Moves one card so it sits before another, and answers with the new order. */
function moveNowCard(order, name, beforeName) {
  const without = order.filter((n) => n !== name);
  const at = beforeName === null ? without.length : without.indexOf(beforeName);
  if (at === -1) return order;

  without.splice(at, 0, name);
  return without;
}

/**
 * Moves a card one place, for the keyboard.
 *
 * Dragging is the obvious gesture and the only one some people cannot make, so
 * the grip is a real button that answers the arrow keys too.
 */
function nudgeNowCard(name, delta) {
  const order = [...nowCardOrder];
  const at = order.indexOf(name);
  if (at === -1) return;

  const to = at + delta;
  if (to < 0 || to >= order.length) return;

  nowCardOrder = moveNowCard(order, name, delta > 0 ? (order[to + 1] ?? null) : order[to]);
  saveNowCardOrder();
  applyNowCardOrder();
}

/** The card after this one, or null when it is the last. */
function nextNowCard(name) {
  const at = nowCardOrder.indexOf(name);
  return at === -1 ? null : (nowCardOrder[at + 1] ?? null);
}

/**
 * Puts a card in a position now, redrawing only if that is a change.
 *
 * Called from dragover, which fires continuously, so the guard is what keeps
 * the grid from being rebuilt hundreds of times a second - and what stops the
 * dragged card flickering under its own pointer.
 */
function placeNowCard(name, beforeName) {
  if (name === beforeName) return;

  const wanted = moveNowCard(nowCardOrder, name, beforeName);
  if (wanted.join() === nowCardOrder.join()) return;

  nowCardOrder = wanted;
  applyNowCardOrder();
}

/** Puts the grid in the saved order. Re-appending a card moves it. */
function applyNowCardOrder() {
  const grid = $('#view-now .now-grid');
  if (!grid) return;

  const cards = $$('#view-now .now-grid .card[data-card]');
  const natural = cards.map((card) => card.dataset.card);
  const byName = new Map(cards.map((card) => [card.dataset.card, card]));

  nowCardOrder = resolveNowOrder(natural, nowCardOrder);

  for (const name of nowCardOrder) {
    const card = byName.get(name);
    if (card) grid.append(card);
  }
}

function renderHiddenNowCards() {
  const tray = $('#now-card-visibility');
  const list = $('#now-hidden-card-list');
  if (!tray || !list) return;

  list.textContent = '';
  for (const card of $$('#view-now .card[data-card]')) {
    const name = card.dataset.card;
    if (!hiddenNowCards.has(name)) continue;

    const label = card.querySelector('.card-label')?.textContent.trim() || name;
    const show = el('button', 'ghost tiny', `Show ${label}`);
    show.type = 'button';
    show.addEventListener('click', () => {
      hiddenNowCards.delete(name);
      card.classList.remove('user-hidden');
      saveHiddenNowCards();
      renderHiddenNowCards();
    });
    list.append(show);
  }
  tray.hidden = !list.children.length;
}

function initNowCardCollapsers() {
  for (const card of $$('#view-now .card[data-card]')) {
    const name = card.dataset.card;
    if (!name || card.querySelector('.now-collapse')) continue;

    const actions = el('div', 'now-card-actions');
    const button = el('button', 'now-collapse now-card-action');
    button.type = 'button';
    button.title = 'Collapse this card';
    button.setAttribute('aria-label', 'Collapse this card');
    button.addEventListener('click', () => {
      const collapsed = !card.classList.contains('collapsed');
      card.classList.toggle('collapsed', collapsed);
      button.textContent = collapsed ? '⌄' : '⌃';
      button.title = collapsed ? 'Expand this card' : 'Collapse this card';
      button.setAttribute('aria-label', button.title);
      button.setAttribute('aria-expanded', String(!collapsed));
      if (collapsed) collapsedNowCards.add(name);
      else collapsedNowCards.delete(name);
      saveCollapsedNowCards();
    });

    const collapsed = collapsedNowCards.has(name);
    card.classList.toggle('collapsed', collapsed);
    button.textContent = collapsed ? '⌄' : '⌃';
    button.title = collapsed ? 'Expand this card' : 'Collapse this card';
    button.setAttribute('aria-label', button.title);
    button.setAttribute('aria-expanded', String(!collapsed));

    const hide = el('button', 'now-hide now-card-action', '×');
    hide.type = 'button';
    hide.title = 'Hide this card from the Now page';
    hide.setAttribute('aria-label', hide.title);
    hide.addEventListener('click', () => {
      hiddenNowCards.add(name);
      card.classList.add('user-hidden');
      saveHiddenNowCards();
      renderHiddenNowCards();
    });
    const grip = el('button', 'now-grip now-card-action', '⠿');
    grip.type = 'button';
    grip.title = 'Drag to move this card; the arrow keys move it too';
    grip.setAttribute('aria-label', grip.title);

    // The card is the thing that drags, but only while the grip is held:
    // draggable on the card itself would make every stretch of text in it
    // un-selectable.
    grip.addEventListener('mousedown', () => { card.draggable = true; });
    grip.addEventListener('mouseup', () => { card.draggable = false; });

    grip.addEventListener('keydown', (event) => {
      const delta = { ArrowLeft: -1, ArrowUp: -1, ArrowRight: 1, ArrowDown: 1 }[event.key];
      if (delta === undefined) return;

      event.preventDefault();
      nudgeNowCard(name, delta);
      // The grid was rebuilt around this button; it keeps the focus so the
      // next press carries on from where the last one left off.
      grip.focus();
    });

    card.addEventListener('dragstart', (event) => {
      draggedNowCard = name;
      card.classList.add('dragging');
      if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = 'move';
        // Firefox starts no drag at all unless something is carried.
        try { event.dataTransfer.setData('text/plain', name); } catch { /* not fatal */ }
      }
    });

    card.addEventListener('dragend', () => {
      draggedNowCard = null;
      card.draggable = false;
      card.classList.remove('dragging');
      // The order was kept true while dragging; this is where it is written
      // down, once, rather than on every twitch of the pointer.
      saveNowCardOrder();
    });

    // The cards move under the pointer rather than waiting for the drop. A
    // preview that only appears at the end is one the reader has to guess at,
    // and in a grid - where "after" can mean the next column or the next row -
    // guessing is exactly what goes wrong.
    card.addEventListener('dragover', (event) => {
      if (!draggedNowCard || draggedNowCard === name) return;
      event.preventDefault();
      if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';

      const box = card.getBoundingClientRect();
      const past = (event.clientX - box.left) > box.width / 2;

      placeNowCard(draggedNowCard, past ? nextNowCard(name) : name);
    });

    card.addEventListener('drop', (event) => {
      if (!draggedNowCard) return;
      // Already in place; this only stops the browser treating it as a
      // navigation.
      event.preventDefault();
    });

    actions.append(grip, hide, button);
    card.append(actions);

    card.classList.toggle('user-hidden', !isOverlay && hiddenNowCards.has(name));
  }

  // The gaps between cards, and the empty space at the end of the grid. Without
  // this the one place a card could not be dropped was the space after the last
  // one - which is exactly where a hand goes to send a card to the bottom.
  const grid = $('#view-now .now-grid');
  if (grid && !grid.dataset.reorderWired) {
    grid.dataset.reorderWired = '1';

    grid.addEventListener('dragover', (event) => {
      if (!draggedNowCard || event.target !== grid) return;
      event.preventDefault();
      placeNowCard(draggedNowCard, null);
    });

    grid.addEventListener('drop', (event) => {
      if (draggedNowCard) event.preventDefault();
    });
  }

  applyNowCardOrder();
  renderHiddenNowCards();
}

document.addEventListener('keydown', (event) => {
  if (!event.ctrlKey || !event.altKey) return;

  if (event.key === 'ArrowRight') { window.scCycleView(1); event.preventDefault(); }
  if (event.key === 'ArrowLeft') { window.scCycleView(-1); event.preventDefault(); }
});

/* ---------- live view ---------- */

let sessionStarted = null;
let nowState = null;
let briefingFor = null;
let pilotBriefing = null;

/*
 * How long a screenshot's disagreement with the logs leads the hub. It is a
 * finding, not a fault: the wallet check exists to find money the log never
 * saw, and a non-stock fitting is a fact about the ship. Nothing on the page
 * resolves it, so it must not sit above "Next stop" for the rest of the
 * evening - it used to, as "Screen needs review", until a newer frame was
 * read. Half an hour is long enough to notice and short enough to forget.
 */
const SCREEN_FOCUS_MS = 30 * 60 * 1000;

/** What the newest screenshot disagrees with the logs on, if it is recent and from this session. */
function recentScreenDisagreement(state) {
  const screen = state?.screen;
  const differs = (screen?.checks || []).find(check => check.verdict === 'differs');
  if (!differs) return null;

  // The shot's own time, against this session and the clock: a frame from
  // three days ago that happened to be re-read last is not the state of now.
  const at = new Date(screen.shotAt || 0).getTime();
  const started = state?.sessionStarted ? new Date(state.sessionStarted).getTime() : 0;
  if (!at || at < started || Date.now() - at > SCREEN_FOCUS_MS) return null;

  return `${differs.subject}: ${differs.note || differs.belief || differs.claim}`;
}

/**
 * The contract worth leading with. A hauling contract that names where it
 * goes leads with that, and points at Shopping, where the run is planned;
 * several hauls open say so, because one destination is not the picture.
 */
function contractFocus(contracts) {
  const hauls = contracts.filter((c) => c.hauling);

  if (hauls.length) {
    const ends = [...new Set(hauls.map((c) => c.delivery).filter(Boolean))];
    const detail = hauls.length === 1
      ? (hauls[0].delivery ? `Deliver to ${hauls[0].delivery}` : hauls[0].name)
      : `${hauls.length} hauls open${ends.length ? ` — to ${ends.join(', ')}` : ''}`;
    // Shopping keeps the run under the lists, off the bottom of the page
    // when a list is open: the button lands on the run, not on the header.
    return { title: hauls.length === 1 ? 'Hauling' : 'Hauling run', detail, view: 'jobs', action: 'Plan the run', anchor: '#jobs-contracts' };
  }

  return { title: 'Active contract', detail: contracts[0].name || 'Open contract', view: 'contracts', action: 'Contracts' };
}

/** The one decision worth leading the hub with, before the configurable cards. */
function renderNowFocus(state, briefing = pilotBriefing) {
  const strip = $('#now-focus');
  const title = $('#now-focus-title');
  const detail = $('#now-focus-detail');
  const open = $('#now-focus-open');
  if (!strip || !title || !detail || !open) return;

  const differing = recentScreenDisagreement(state);
  const nextStop = (briefing?.stops || []).find(stop => !stop.done);
  let focus = null;

  if (state?.travelling) focus = { title: 'In quantum', detail: state.travellingTo || 'Destination not identified', view: 'map', action: 'Map' };
  else if (differing) focus = { title: 'Screenshot differs from the logs', detail: differing, view: 'log', action: 'Log' };
  else if (nextStop) focus = { title: 'Next stop', detail: nextStop.place || briefing.tripTitle || 'Tracked flight plan', view: 'map', action: 'Map' };
  else if (state?.contracts?.length) focus = contractFocus(state.contracts);
  else if (state?.location) focus = { title: 'At location', detail: state.location, view: 'map', action: 'Map' };

  strip.hidden = !focus;
  if (!focus) return;
  title.textContent = focus.title;
  detail.textContent = focus.detail;
  open.hidden = false;
  open.textContent = focus.action;
  open.onclick = () => { jobsLandOn = focus.anchor || null; showView(focus.view); };
}

function renderNow(state) {
  nowState = state;
  $('#link').classList.toggle('live', !!state.connected);
  $('#link').title = state.connected ? 'live' : 'disconnected';

  $('#now-location').textContent = state.location || (state.inGame ? 'Unknown' : 'In menus');
  $('#now-location-sub').textContent = [state.locationBody, state.locationSystem].filter(Boolean).join(' · ');

  // The map follows the live feed, so the marker moves as the player does -
  // and shows the jump while it is happening, not only where it ended.
  setHere(state.locationId);
  setTravel(state.travelling ? state.travellingToId : null);
  tripArrived(state.locationId);

  // The trade card follows too, refreshing only when the place changes.
  refreshTradeAdvice(state.location).catch(() => {});
  refreshPilotBriefing(state).catch(() => {});

  const confidence = $('#now-confidence');
  confidence.textContent = state.location ? `${state.confidence.toLowerCase()} confidence` : '';
  confidence.className = `confidence ${(state.confidence || '').toLowerCase()}`;

  const travel = $('#now-travel');
  travel.hidden = !state.travelling;
  if (state.travelling) $('#now-travel-to').textContent = state.travellingTo || '';

  renderNowShip(state.ship);
  $('#now-handle').textContent = state.handle || '—';
  $('#now-version').textContent = state.gameVersion || '';
  $('#now-mode').textContent = state.inGame ? (state.gameRules || 'in game') : 'frontend / menus';
  $('#now-deaths').textContent = state.deaths ?? 0;
  $('#now-incaps').textContent = state.incapacitations ?? 0;

  // Be explicit about what each number is and is not. Deaths are inferred, so
  // the note is permanent rather than conditional: there is no state of the
  // game in which it stops being true. Kills are not shown at all - 4.9 and 4.10 log
  // nothing that names a killer, and a counter stuck at zero reads as broken
  // rather than absent. The About page says where they went.
  $('#combat-note').textContent =
    'Deaths are inferred from corpse item-recovery bursts — 4.9 and 4.10 no longer write '
    + '<Actor Death>, and an Incapacitated notification is not always raised.';

  sessionStarted = state.sessionStarted || null;

  renderNowParty(state);
  renderNowServer(state);

  // The Servers page lights the row you are on; a placement mid-visit moves it.
  if ((state.shard || null) !== serverCurrent && serverRows.length) {
    serverCurrent = state.shard || null;
    renderServers();
  }
  renderNowScreenCard(state.screen);
  renderNowFocus(state);

  raiseToasts(state.recentEvents);

  const feed = $('#now-feed');
  feed.textContent = '';

  if (!state.recentEvents || state.recentEvents.length === 0) {
    feed.append(el('li', 'empty', state.connected ? 'Nothing yet this session.' : 'Waiting for the game…'));
  } else {
    // The widget shows a short tail; the full feed belongs on the page.
    const entries = isOverlay ? state.recentEvents.slice(0, 12) : state.recentEvents;

    for (const entry of entries) {
      const li = el('li');
      li.append(el('span', 't', timeOf(entry.at)));
      li.append(el('span', `k ${entry.kind}`, entry.kind));
      li.append(el('span', 'x', entry.text));
      if (entry.detail) li.append(el('span', 'd', withoutMarkup(entry.detail)));
      feed.append(li);
    }
  }
}

/* ---------- live toasts ---------- */

/**
 * A contract title with StarStrings' markup taken off.
 *
 * The mod writes its additions inside the game's own <EM> tags, and the log
 * records the title with the tags still in it - so a contract reads as
 * "Rookie | <EM3>DIRECT</EM3> Extra Small Haul" everywhere the title is shown.
 * The bracket tags stay: "[BP]*" and "[150 Rep]" are the research the mod
 * exists for, and a player glancing at a toast wants them.
 */
function withoutMarkup(text) {
  return typeof text === 'string' ? text.replace(/<\/?EM\d*>/gi, '').trim() : text;
}

const TOAST_MS = 9000;

/**
 * Timeline kinds worth interrupting somebody for, and what to call them.
 *
 * Deliberately short. The feed carries everything; a toast is for the two
 * moments a player wants to see without looking away from the game, and a
 * notifier that fires on arrivals and medbeds trains people to ignore it.
 */
const TOAST_KINDS = {
  'contract-done': 'Contract complete',
  payout: 'Paid',

  // Only disagreements. A pilot photographing a loadout takes several frames
  // in a row, and a toast apiece would teach them to ignore the toasts.
  'screen-differs': 'Screenshot differs',
};

/**
 * The newest entry already toasted, as "at|kind|text".
 *
 * Null until a frame with something in it lands, which is the whole point: the
 * stream opens with up to 40 entries of history, and a client that toasted what
 * it found would replay the last hour of the session every time the page was
 * refreshed or the overlay reloaded. Null again after an empty frame, which
 * means the opposite - nothing to replay, so the next frame is all news.
 */
let lastToastKey = null;

/**
 * Whether any frame has been seen yet.
 *
 * Separate from lastToastKey because the first frame can legitimately be
 * empty - the dashboard opened at the game's menu, or a session whose timeline
 * has nothing in it yet - and anchoring only on a non-empty frame swallowed
 * the first thing that ever happened. For the screen readings that first thing
 * is the disagreement the toast exists to announce.
 */
let toastAnchored = false;

function toastKey(entry) {
  return `${entry.at}|${entry.kind}|${entry.text}`;
}

/**
 * Toast whatever arrived since the last frame.
 *
 * recentEvents is newest-first, so this walks forward to the previously seen
 * entry and then fires what it passed in the order it happened. Falling off the
 * end means more than 40 entries landed between frames - it toasts nothing
 * rather than the whole window, since the point is the moment, not the backlog.
 */
function raiseToasts(entries) {
  if (!entries || entries.length === 0) {
    // Nothing has happened yet, so there is no backlog to replay and whatever
    // arrives next is news. The null key says exactly that to the frame after.
    toastAnchored = true;
    lastToastKey = null;
    return;
  }

  const newest = toastKey(entries[0]);

  if (!toastAnchored) {
    toastAnchored = true;
    lastToastKey = newest;
    return;
  }

  if (lastToastKey === newest) return;

  const fresh = [];

  // A null key here is the empty frame above rather than a fresh page: there
  // was nothing to anchor on because there was nothing at all, so the whole
  // frame is new and none of it is history.
  let anchored = lastToastKey === null;

  if (anchored) {
    fresh.push(...entries);
  } else {
    for (const entry of entries) {
      if (toastKey(entry) === lastToastKey) {
        anchored = true;
        break;
      }

      fresh.push(entry);
    }
  }

  lastToastKey = newest;

  // The anchor is gone, so more happened between frames than the window holds -
  // after an EventSource reconnect, that is an hour of history. Toast nothing
  // rather than the whole window, which is what the rule above says and what
  // this had stopped doing.
  if (!anchored) return;

  for (const entry of fresh.reverse()) {
    const label = TOAST_KINDS[entry.kind];
    if (label) toast(entry.kind, entry.text, entry.detail);
  }
}

/**
 * One toast. Click dismisses; otherwise it fades on its own.
 *
 * The node is removed rather than hidden so a long session does not accumulate
 * a thousand dead divs behind the overlay.
 */
function toast(kind, text, detail) {
  const host = $('#toasts');
  if (!host) return;

  const card = el('div', `toast ${kind}`);
  card.append(el('span', 'toast-text', text));
  if (detail) card.append(el('span', 'toast-detail', withoutMarkup(detail)));

  card.addEventListener('click', () => card.remove());
  host.append(card);

  setTimeout(() => card.remove(), TOAST_MS);
}

/**
 * Who the party channel has named this session.
 *
 * Deliberately not called a roster. The game emits a toast when somebody
 * connects, drops, joins or leaves, and nothing at all for a member who was
 * already online when you grouped up and stayed to the end - so this card can
 * only ever say who was mentioned. The note is permanent rather than shown on
 * empty, because a short list is exactly when it would be misread as complete.
 *
 * The card hides itself when nobody has been named, rather than showing a zero:
 * flying alone and flying with a silent party look identical from here, and a
 * bare 0 would claim to tell them apart.
 */
/**
 * What trading makes per in-game hour, and how far that leaves the goal.
 *
 * The rate is deliberately not called credits per hour. Commodity sales are the
 * only income the logs carry - no contract, bounty or mission reward is written
 * anywhere - so for a hauler this is close to their whole rate and for someone
 * running contracts it is a fraction of it. Naming it "trading" is the
 * difference between a floor and a claim.
 */
async function loadEarnings() {
  const card = $('#now-earning-card');
  if (!card) return;

  const state = await getJson('/api/earnings').catch(() => null);
  if (!state) { card.hidden = true; return; }

  const rate = state.basis === 'recent' ? state.window : state.lifetime;

  // Nothing traded means no rate. A zero here would read as "you earn nothing
  // an hour" rather than "nothing has been sold yet".
  const noRate = !rate || rate.perHour <= 0;

  for (const id of ['#now-earning-rate', '#now-earning-sub', '#now-earning-note'])
    $(id).hidden = noRate;

  /*
   * The card stays, because the goal lives inside it. Hiding the whole thing
   * meant somebody who had never sold a commodity could not set a goal at all -
   * and a goal already set became invisible with no way to clear it. The rate
   * is what is missing here, not the card.
   */
  card.hidden = false;

  if (noRate) {
    $('#now-earning-rate').hidden = false;
    $('#now-earning-rate').textContent = 'No trading yet';
    renderGoal(state);
    return;
  }

  $('#now-earning-rate').textContent = `${money(rate.perHour)}/h`;
  $('#now-earning-sub').textContent = state.basis === 'recent'
    ? `trading profit, last ${rate.days} days · ${hoursOf(rate.inGame)} in game`
    : `trading profit, all time · ${hoursOf(rate.inGame)} in game`;

  $('#now-earning-note').textContent =
    'Commodity sales are the only income the logs record, so contracts, bounties '
    + 'and mission rewards are not in this. It is a floor on what you earn, and '
    + 'menu time is left out of the hours.';

  renderGoal(state);
}

/**
 * Cash on hand on the Now card, which the overlay shows while flying. The
 * same reading the Ledger card draws, in one line: the figure carried forward
 * by the ledger, called an estimate when anything has moved since the shot.
 * Nothing read yet hides the line - the Ledger explains how to get one; a
 * card in the overlay has no room to.
 */
function renderNowCash(read) {
  const line = $('#now-cash');
  const note = $('#now-cash-note');
  if (!line || !note) return;

  if (!read) {
    line.hidden = true;
    note.hidden = true;
    return;
  }

  const moved = Number(read.movementsSince) || 0;
  line.hidden = false;
  note.hidden = false;
  $('#now-cash-value').textContent = moved ? `about ${money(read.estimate)}` : money(read.balance);
  note.textContent = moved
    ? `Estimate: ${money(read.balance)} on a screenshot ${dateOf(read.shotAt)}, carried by ${moved} movement${moved === 1 ? '' : 's'} logged since.`
    : `From a screenshot ${dateOf(read.shotAt)}; nothing has moved in the logs since.`;
}

/** Turns an ISO-ish duration from the server into hours a person reads. */
function hoursOf(span) {
  const hours = typeof span === 'string' ? spanHours(span) : Number(span) || 0;
  return hours >= 10 ? `${Math.round(hours)}h` : `${hours.toFixed(1)}h`;
}

/** "1.02:03:04" and "02:03:04" both mean hours here. */
function spanHours(text) {
  const days = text.includes('.') && text.indexOf('.') < text.indexOf(':')
    ? Number(text.slice(0, text.indexOf('.'))) || 0
    : 0;
  const clock = days ? text.slice(text.indexOf('.') + 1) : text;
  const [h = 0, m = 0, sec = 0] = clock.split(':').map(Number);
  return days * 24 + h + m / 60 + (sec || 0) / 3600;
}

/**
 * The goal, as a distance in hours rather than a date nobody can hold to.
 *
 * There is deliberately no progress bar. The logs never state a balance, so how
 * far along you are is not something this can know - only how much trading the
 * whole thing is worth. A bar would have drawn a number that looks like progress
 * and is not.
 */
function renderGoal(state) {
  const goal = state.goal;
  const block = $('#now-goal');
  const form = $('#now-goal-form');
  const clear = $('#now-goal-clear');

  block.hidden = !goal;
  clear.hidden = !goal;

  if (!goal) {
    form.hidden = false;
    return;
  }

  form.hidden = true;
  $('#now-goal-input').value = goal.name;
  $('#now-goal-target').value = goal.target;

  $('#now-goal-name').textContent = `${goal.name} · ${money(goal.target)}`;

  // Hours of flying, not a calendar date. The app has no idea how often
  // somebody plays, and a date would be inventing that.
  $('#now-goal-eta').textContent = state.hoursToGoal
    ? `${hoursOf(state.hoursToGoal)} of trading`
    : 'no rate yet';

}

$('#now-goal-form')?.addEventListener('submit', async (e) => {
  e.preventDefault();

  const body = {
    name: $('#now-goal-input').value.trim(),
    target: Number($('#now-goal-target').value) || 0,
    setAt: new Date().toISOString(),
  };

  if (!body.name || body.target <= 0) return;

  await fetch('/api/goal', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  }).catch(() => {});

  await loadEarnings().catch(() => {});
});

$('#now-goal-clear')?.addEventListener('click', async () => {
  await fetch('/api/goal', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: 'null',
  }).catch(() => {});

  $('#now-goal-input').value = '';
  $('#now-goal-target').value = '';
  $('#now-goal-form').hidden = false;

  await loadEarnings().catch(() => {});
});

function renderNowParty(state) {
  const card = $('#now-party-card');
  if (!card) return;

  const party = state.party || [];
  card.hidden = party.length === 0;
  if (card.hidden) return;

  const list = $('#now-party-list');
  list.textContent = '';

  for (const member of party) {
    const li = el('li');
    li.append(el('span', 't', timeOf(member.at)));
    li.append(el('span', 'k party', member.moment));
    li.append(el('span', 'x', member.handle));
    list.append(li);
  }

  $('#now-party-note').textContent =
    `${party.length} ${party.length === 1 ? 'person' : 'people'} named by party `
    + 'notifications — a floor, not a roster. '
    + 'Someone already online when you grouped up is never announced'
    + (state.partyDisbanded ? '. The party has since disbanded.' : '.');
}

/**
 * The briefing answers the decisions that depend on a live location. It only
 * re-fetches when that location changes; actions explicitly invalidate it.
 */
async function refreshPilotBriefing(state) {
  const card = $('#now-briefing-card');

  // The ship is part of the key, not just the place. Swapping ships is
  // something you do standing still in your own hangar, so a key made only of
  // where you are meant the most common way to change the focus was the one
  // way that could not refresh it: the card kept the last ship's lane until
  // the pilot happened to fly somewhere else.
  const key = state?.inGame && state.location
    ? `${state.locationId || ''}|${state.location}|${state.ship || ''}`
    : null;

  if (!key) {
    card.hidden = true;
    briefingFor = null;
    pilotBriefing = null;
    renderNowFocus(state, null);
    return;
  }

  if (key === briefingFor) return;

  // Claiming the key before the fetch keeps concurrent renders to one request,
  // so it has to be given back when that request fails - otherwise the card
  // keeps the previous location's stops, shopping and stash on screen as
  // though they described where the player is now, and nothing tries again
  // until they travel somewhere else entirely.
  briefingFor = key;

  let briefing;
  try {
    // The chosen focus goes with the request: the mining and claim extras are
    // built server-side for whichever focus asked for them.
    briefing = await getJson('/api/briefing'
      + (briefingFocus ? `?focus=${encodeURIComponent(briefingFocus)}` : ''));
  } catch (err) {
    if (briefingFor === key) {
      briefingFor = null;
      card.hidden = true;
    }
    throw err;
  }

  if (key !== `${nowState?.locationId || ''}|${nowState?.location || ''}|${nowState?.ship || ''}`) return;

  renderPilotBriefing(briefing);
}

async function reloadPilotBriefing() {
  briefingFor = null;
  if (nowState) await refreshPilotBriefing(nowState);
}

function briefingMap(placeId, place) {
  showView('map');
  if (placeId) centreOn(placeId);
  else if (place) jumpToPlace(place);
}

async function addBriefingStop() {
  if (!nowState?.location) return;

  const button = $('#briefing-add-stop');
  button.disabled = true;
  try {
    await fetch('/api/trips/stops', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ placeId: nowState.locationId || '', place: nowState.location, note: null }),
    });
    await loadTrips();
    await reloadPilotBriefing();
  } finally {
    button.disabled = false;
  }
}

async function pinBriefingToOverlay() {
  const button = $('#briefing-overlay');
  const label = button.textContent;
  button.disabled = true;

  try {
    // visible is bound from the query, not from a body. And a refusal - which
    // is what the bare server always answers, having no overlay to show - is a
    // normal response rather than a thrown one, so it has to be looked at.
    const response = await fetch('/api/overlay?visible=true', { method: 'POST' });

    button.textContent = response.ok ? '✓ pinned' : 'no overlay';
    button.title = response.ok ? '' : 'The dashboard is running without the overlay.';
  } catch {
    button.textContent = 'failed';
  } finally {
    button.disabled = false;
  }

  // Long enough to be read, short enough that the button is a button again
  // before the next place is worth pinning.
  setTimeout(() => { button.textContent = label; button.title = ''; }, 4000);
}

function briefingStopRow(briefing, stop) {
  const row = el('div', 'briefing-row');
  const main = el('div', 'briefing-main');
  const name = el('button', 'briefing-link', stop.place);
  name.title = 'Show this stop on the map';
  name.addEventListener('click', () => briefingMap(stop.placeId, stop.place));
  main.append(name);
  if (stop.note) main.append(el('div', 'briefing-detail', stop.note));

  // What is still owed here. Without this the card keeps a landed stop on
  // screen and never says why it is keeping it, which reads as a stop that
  // will not cross off rather than as work outstanding.
  for (const action of stop.actions || []) {
    const quantity = action.quantity
      ? ` ${action.quantity.toLocaleString()}${action.unit ? ` ${action.unit}` : ''}`
      : '';
    main.append(el('div', 'briefing-detail', `${action.kind}${quantity} · ${action.text}`));
  }

  row.append(main);

  const done = el('button', 'ghost tiny', 'Mark collected');
  done.title = 'Cross this stop off';
  done.addEventListener('click', async () => {
    done.disabled = true;
    try {
      await tripCall(`/api/trips/${briefing.tripId}/stops/${stop.id}/toggle`);
      await reloadPilotBriefing();
    } finally {
      done.disabled = false;
    }
  });
  row.append(done);
  return row;
}

function briefingShoppingRow(item) {
  const row = el('div', 'briefing-row');
  const main = el('div', 'briefing-main');
  main.append(el('b', null, item.name));
  main.append(el('div', 'briefing-detail', `${item.needed} ${item.unit || 'needed'} · ${item.terminal} · ${money(item.price)}`));
  row.append(main);

  const map = el('button', 'ghost tiny', 'Map');
  map.title = 'Show this seller on the map';
  map.addEventListener('click', () => {
    showView('map');
    centreOnTerminal(item.terminal, null);
  });
  row.append(map);
  return row;
}

/* ---------- briefing focus ---------- */

/**
 * What the briefing leads with, and whose idea that was.
 *
 * The retrieved ship is the signal because nothing else is one: the logs carry
 * no mining, no salvage and no cargo, so what came out of the hangar is the
 * only statement of intent the app ever sees. That makes it a guess about
 * intent rather than a record of work, which is why the card says out loud what
 * it read and this chooser can overrule it. "off" is kept distinct from unset:
 * a pilot who wants the plain page must not have a ship swap hand them a focus
 * back.
 */
const BRIEFING_FOCUS_KEY = 'qw-briefing-focus';

let briefingFocus = '';
try {
  briefingFocus = localStorage.getItem(BRIEFING_FOCUS_KEY) || '';
} catch { /* a bad preference must not blank the briefing */ }

const FOCUS_LABELS = {
  freight: 'Freight',
  mining: 'Mining',
  combat: 'Combat',
  explore: 'Exploration',
};

/**
 * The sections each focus leads with. Deliberately partial: naming only the
 * two or three that change the answer leaves the rest in the order the markup
 * gives them, so a section added in a later version still appears rather than
 * being dropped by every focus that predates it.
 */
const BRIEFING_LEADS = {
  freight: ['trade', 'stops', 'shopping'],
  mining: ['mining', 'stops', 'services'],
  combat: ['claim', 'services', 'stops'],
  explore: ['stops', 'services', 'trade'],
};

/** Markup order, which is the arrangement with no focus in force. */
const BRIEFING_SECTIONS = ['stops', 'shopping', 'trade', 'services', 'stash', 'mining', 'claim'];

/** The order to draw the briefing's sections in, for one focus. */
function briefingOrder(focus) {
  const leads = BRIEFING_LEADS[focus] || [];
  return [...leads, ...BRIEFING_SECTIONS.filter((name) => !leads.includes(name))];
}

/** The focus in force: the pilot's choice, else the ship's, else none. */
function focusInForce(briefing) {
  if (briefingFocus === 'off') return null;
  return briefingFocus || briefing?.focus?.key || null;
}

/**
 * Reorders the sections rather than the cards.
 *
 * The Now grid is arranged by hand and that arrangement is saved; a focus that
 * moved cards would silently overwrite it every time the pilot changed ship.
 * Inside this one card there is no such promise to keep.
 */
function applyBriefingOrder(focus) {
  const grid = $('.briefing-grid');
  if (!grid) return;

  for (const name of briefingOrder(focus)) {
    const section = $(`#briefing-${name}-section`);
    if (section) grid.append(section);
  }
}

/**
 * Records the pilot's own choice of focus and draws the card again with it.
 *
 * Goes back through the briefing rather than re-rendering what is on screen:
 * the extras are built server-side for the focus that asked for them, so
 * switching to mining has to ask for the rocks rather than discover the card
 * has none.
 */
async function chooseBriefingFocus(value) {
  briefingFocus = value;
  try { localStorage.setItem(BRIEFING_FOCUS_KEY, value); } catch { /* optional */ }
  await reloadPilotBriefing();
}

function renderBriefingFocus(briefing) {
  const chooser = $('#briefing-focus');
  if (chooser) chooser.value = briefingFocus;

  const focus = focusInForce(briefing);
  const why = $('#briefing-why');
  const chosen = briefingFocus && briefingFocus !== 'off';

  if (!focus) {
    why.textContent = '';
  } else if (chosen) {
    why.textContent = `${FOCUS_LABELS[focus] || focus} — your choice, not your ship's.`;
  } else {
    // "a light mining ship", not "a light mining". The dataset's roles are noun
    // phrases that need the word after them, and the compound ones - "Starter /
    // Pathfinder" - need the slash spelled out to read as a sentence at all.
    const from = briefing.focus;
    const role = from.role ? from.role.toLowerCase().replaceAll(' / ', ' or ') : null;

    why.textContent = `${from.label} — you retrieved ${from.ship}`
      + (role ? `, a ${role} ship.` : '.');
  }

  why.hidden = !why.textContent;
  applyBriefingOrder(focus);
  return focus;
}

/**
 * Where to mine, for a mining ship.
 *
 * Never a claim that anything was mined. The rows are the game's own deposit
 * tables ranked by what a rock is worth, and the caveat says which question was
 * answered: the tables name a system for a body and nothing at all for the
 * Aaron Halo, so "best here" quietly becomes "best anywhere" often enough that
 * it has to be visible when it does.
 */
function renderBriefingMining(briefing, focus) {
  const section = $('#briefing-mining-section');
  const rows = focus === 'mining' ? (briefing.mining || []) : [];

  section.hidden = rows.length === 0;
  if (section.hidden) return;

  const list = $('#briefing-mining');
  list.textContent = '';

  for (const place of rows) {
    const row = el('div', 'briefing-row');
    const main = el('div', 'briefing-main');
    main.append(el('b', null, place.place));
    main.append(el('div', 'briefing-detail', [
      place.system,
      place.best ? `best: ${place.best}` : null,
      `${Math.round(place.ore)}% ore`,
    ].filter(Boolean).join(' · ')));
    row.append(main);
    row.append(el('span', 'inward', `${money(place.perRock)}/rock`));
    list.append(row);
  }

  list.append(el('div', 'briefing-caveat', rows[0].here
    ? 'What a rock is worth, from the game’s own deposit tables.'
    : 'The deposit tables place nothing in this system — these are the best anywhere.'));
}

/**
 * What losing this hull costs, for a combat ship.
 *
 * The one number 4.9 can honestly put in front of a fighter pilot. Kills are
 * not logged and deaths are inferred, so a scoreboard would be invention; a
 * claim fee and a wait are in the game's own tables and are the thing actually
 * worth knowing before undocking.
 */
function renderBriefingClaim(briefing, focus) {
  const section = $('#briefing-claim-section');
  const claim = focus === 'combat' ? briefing.claim : null;

  section.hidden = !claim;
  if (!claim) return;

  const list = $('#briefing-claim');
  list.textContent = '';

  const row = el('div', 'briefing-row');
  const main = el('div', 'briefing-main');
  main.append(el('b', null, claim.ship));
  main.append(el('div', 'briefing-detail', [
    claim.standardMinutes ? `standard ~${Math.round(claim.standardMinutes)}m` : null,
    claim.expeditedMinutes ? `expedited ~${Math.round(claim.expeditedMinutes)}m` : null,
  ].filter(Boolean).join(' · ') || 'The reference data gives no claim time.'));
  row.append(main);
  if (claim.expeditedCost) row.append(el('span', 'outward', money(claim.expeditedCost)));
  list.append(row);

  list.append(el('div', 'briefing-caveat',
    'From the game’s own tables. Game.log records no insurance claim, '
    + 'so this is what one costs — not one in progress.'));
}

function renderPilotBriefing(briefing) {
  const card = $('#now-briefing-card');
  if (!briefing?.location) {
    card.hidden = true;
    return;
  }

  $('#briefing-title').textContent = briefing.location;
  $('#briefing-sub').textContent = briefing.tripTitle
    ? `Active flight plan · ${briefing.tripTitle}`
    : 'No active flight plan';

  const stops = $('#briefing-stops');
  stops.textContent = '';
  for (const stop of briefing.stops || []) stops.append(briefingStopRow(briefing, stop));
  $('#briefing-stops-section').hidden = !(briefing.stops || []).length;

  const shopping = $('#briefing-shopping');
  shopping.textContent = '';
  for (const item of briefing.shopping || []) shopping.append(briefingShoppingRow(item));
  $('#briefing-shopping-section').hidden = !(briefing.shopping || []).length;

  const trade = $('#briefing-trade');
  trade.textContent = '';
  const cargoReady = !planningBlocksCargo();
  if (cargoReady) {
    for (const lead of briefing.trade || []) {
      const row = el('div', 'briefing-row');
      const main = el('div', 'briefing-main');
      const commodity = el('button', 'briefing-link', lead.commodity);
      commodity.title = 'Open this commodity in Market';
      commodity.addEventListener('click', () => openCommodity(lead.commodity));
      main.append(commodity);
      main.append(el('div', 'briefing-detail',
        `buy ${money(lead.buyHere)} → sell ${money(lead.sellThere)} at ${lead.sellTerminal}`));
      row.append(main);
      row.append(el('span', 'inward', `+${money(lead.marginPerScu)}/SCU`));
      trade.append(row);
    }
    if ((briefing.trade || []).length)
      trade.append(el('div', 'briefing-caveat', 'Leads only — cargo in your hold is not recorded by Game.log.'));
  }
  $('#briefing-trade-section').hidden = !cargoReady || !(briefing.trade || []).length;

  const services = $('#briefing-services');
  services.textContent = '';
  for (const service of briefing.services || []) {
    const key = serviceKey(service.name);
    const canMap = key && key !== 'repair' && service.dataEnabled;
    const chip = el(canMap ? 'button' : 'span',
      `briefing-service ${service.status.replaceAll(' ', '-')}`);
    if (canMap) {
      chip.type = 'button';
      chip.addEventListener('click', () => selectMapService(key, true));
    }
    chip.append(el('span', 'service-icon', SERVICE_META[key]?.icon || '•'));
    chip.append(el('span', 'service-text', `${service.name}: ${service.status}`));
    chip.title = canMap
      ? `Show ${SERVICE_META[key].label.toLowerCase()} on the map`
      : service.dataEnabled ? 'No map location is known for this service' : 'No installed data reports this service';
    services.append(chip);
  }
  $('#briefing-services-section').hidden = !(briefing.services || []).length;

  const stash = $('#briefing-stash');
  stash.textContent = '';
  for (const item of briefing.stash || []) {
    const row = el('div', 'briefing-row');
    const main = el('div', 'briefing-main');
    main.append(el('b', null, item.name));
    main.append(el('div', 'briefing-detail', item.category));
    row.append(main);
    stash.append(row);
  }
  $('#briefing-stash-section').hidden = !(briefing.stash || []).length;

  const focus = renderBriefingFocus(briefing);
  renderBriefingMining(briefing, focus);
  renderBriefingClaim(briefing, focus);

  $('#briefing-focus').onchange = () => chooseBriefingFocus($('#briefing-focus').value);

  $('#briefing-map').onclick = () => briefingMap(briefing.locationId, briefing.location);
  $('#briefing-add-stop').onclick = addBriefingStop;
  $('#briefing-overlay').onclick = pinBriefingToOverlay;
  $('#briefing-overlay').hidden = isOverlay;
  card.hidden = false;
  pilotBriefing = briefing;
  renderNowFocus(nowState, briefing);
}

setInterval(() => { $('#now-clock').textContent = clock(sessionStarted); }, 1000);

function connectStream() {
  const source = new EventSource('/api/stream');

  source.onmessage = (event) => {
    try {
      renderNow(JSON.parse(event.data));
    } catch { /* ignore a malformed frame */ }
  };

  source.onerror = () => {
    $('#link').classList.remove('live');
    // EventSource reconnects on its own; nothing to do here.
  };
}

/* ---------- entity drawer ---------- */

/**
 * One description of a thing, wherever it was clicked.
 *
 * Every view used to grow its own detail panel, and they disagreed: the map's
 * place card knew about visits and notes, the parts row knew about size and
 * volume, and neither could say whether you already owned the thing or add it
 * to a plan. This is the one surface, and the server builds the same shape for
 * every kind - what is known and who says so, whether it is already yours, what
 * it costs and how old that is, where to go, and what can be done now.
 *
 * A section with no answer is hidden rather than shown empty. "Not reported" is
 * a fact worth stating; a blank row is not.
 */
let entityShown = null;

let entityRequest = 0;

/**
 * Stamps a request, and answers whether its reply is still wanted.
 *
 * Two clicks in a row are two requests, and the first can land second - which
 * had the panel describing whatever was clicked before. Closing counts as
 * moving on too, so a reply still in flight cannot reopen a drawer the pilot
 * has just dismissed.
 *
 * A function rather than a comparison at the call site because that is the
 * half of this that can be tested: the stub answers in the order it is asked,
 * so the out-of-order landing itself cannot be staged here.
 */
function entityTicket() {
  const token = ++entityRequest;
  return () => token === entityRequest;
}

/** The map-only parts of a place card, which no other kind fills in. */
const PLACE_ONLY_NODES = [
  '#map-info-services', '#map-info-trade', '#map-info-notes',
  '#map-info-amenities', '#map-info-lore', '#map-info-sold',
];

const ENTITY_KICKER = {
  place: 'Place',
  commodity: 'Commodity',
  ship: 'Ship',
  part: 'Component',
};

async function openEntity(kind, id) {
  if (!kind || !id) return false;

  // Forgotten here rather than left pointing at whoever was open before: a note
  // typed into a place reached from search would otherwise be filed against the
  // last place opened from the map.
  mapInfoLocation = null;

  const drawer = $('#entity-drawer');

  // Clicking the same thing again closes it, which is what a second click on
  // an open panel has always meant here.
  if (entityShown === `${kind}|${id}` && !drawer.hidden) {
    closeEntity();
    return false;
  }

  const wanted = entityTicket();

  let card;
  try {
    card = await getJson(`/api/entity?kind=${encodeURIComponent(kind)}&id=${encodeURIComponent(id)}`);
  } catch {
    // Nothing known is not an error worth a dialog: the click simply has no
    // answer, and leaving the previous card up would answer for the wrong
    // thing. A failure for a request already superseded says nothing at all.
    if (wanted()) closeEntity();
    return false;
  }

  if (!wanted()) return false;

  entityShown = `${kind}|${id}`;
  renderEntity(card);
  return true;
}

function closeEntity() {
  entityRequest++;
  $('#entity-drawer').hidden = true;
  document.body.classList.remove('entity-open');
  entityShown = null;

  if ($('#view-map').classList.contains('active')) drawMap();
}

function renderEntity(card) {
  $('#entity-kicker').textContent = ENTITY_KICKER[card.kind] || card.kind;
  $('#entity-name').textContent = card.name;
  $('#entity-sub').textContent = card.subtitle || '';

  renderEntityHolding(card);
  renderEntityPrice(card);
  renderEntityBlurb(card);
  renderEntityFacts(card);
  renderEntityWhere(card);
  renderEntityActions(card);

  // Cleared every time, not only when the section is hidden. These renderers
  // append, and only showMapInfo refills them - so a place opened from search,
  // which calls openEntity directly, drew the new place's name over the last
  // place's services, lore and notes.
  const extra = $('#entity-place-extra');
  extra.hidden = card.kind !== 'place';
  for (const id of PLACE_ONLY_NODES) $(id).textContent = '';

  $('#entity-drawer').hidden = false;
  document.body.classList.add('entity-open');

  // The map sizes itself from the space it has, so it has to be told the space
  // just changed - otherwise the dots stay where they were and the place that
  // was clicked ends up under the drawer that describes it.
  if ($('#view-map').classList.contains('active')) drawMap();
}

/** Whether it is already yours, which changes every decision about it. */
function renderEntityHolding(card) {
  const node = $('#entity-holding');
  node.textContent = '';
  node.hidden = !card.holding;
  if (node.hidden) return;

  node.append(el('b', null, card.holding.status));
  if (card.holding.detail) node.append(el('div', 'entity-detail', card.holding.detail));
}

/**
 * The price, and how old it is.
 *
 * The age is not decoration. Every price here is somebody else's report of a
 * counter that may have moved since, and it is the one number on this card that
 * can cost real money if it is trusted further than it deserves.
 */
function renderEntityPrice(card) {
  const node = $('#entity-price');
  node.textContent = '';
  node.hidden = card.price === null || card.price === undefined
    || card.price.amount === null || card.price.amount === undefined;
  if (node.hidden) return;

  const price = card.price;
  node.append(el('b', 'entity-amount',
    `${money(price.amount)}${price.unit === 'aUEC/SCU' ? '/SCU' : ''}`));

  const detail = [
    price.where ? `at ${price.where}` : null,
    price.asOf ? `${price.source}, ${ageWord(price.asOf)}` : price.source,
  ].filter(Boolean).join(' · ');

  node.append(el('div', 'entity-detail', detail));
}

/** "collected 3 days ago", so a stale table reads as stale rather than as fact. */
function ageWord(at) {
  const days = Math.floor((Date.now() - new Date(at).getTime()) / 86400000);
  if (!Number.isFinite(days) || days < 0) return 'age unknown';
  if (days === 0) return 'collected today';
  if (days === 1) return 'collected yesterday';
  return `collected ${days} days ago`;
}

/**
 * What is known, each line carrying who is answerable for it.
 *
 * The source label is the whole point. This install's own logs and a community
 * price table deserve very different amounts of trust, and a card that mixed
 * them silently would give up the thing that makes the app worth having.
 */
function renderEntityFacts(card) {
  const list = $('#entity-facts');
  list.textContent = '';

  for (const fact of card.facts || []) {
    const row = el('div', 'entity-fact');
    row.append(el('span', 'entity-fact-label', fact.label));
    const value = el('span', 'entity-fact-value', fact.value);
    value.append(el('span', 'entity-source', fact.source));
    row.append(value);
    list.append(row);
  }
}

/**
 * What the game says about the thing, in its own words.
 *
 * Kept because the parts table had it and losing it would make this drawer a
 * downgrade for the one view it replaces first. The game writes these with a
 * literal backslash-n between the header lines, which is why the split is
 * looking for both.
 */
function renderEntityBlurb(card) {
  const blurb = $('#entity-blurb');
  blurb.textContent = '';
  blurb.hidden = !card.blurb;

  if (card.blurb) {
    for (const line of card.blurb.split(RegExp('\\\\n|\n'))) {
      if (line.trim()) blurb.append(el('p', 'part-blurb', line.trim()));
    }
  }

  const tags = $('#entity-tags');
  tags.textContent = '';
  tags.hidden = !(card.tags || []).length;
  for (const tag of card.tags || []) tags.append(el('span', 'tag', tag));
}

function renderEntityWhere(card) {
  const node = $('#entity-where');
  const places = card.places || [];
  node.textContent = '';
  node.hidden = places.length === 0;
  if (node.hidden) return;

  node.append(el('div', 'entity-label', 'Where'));

  for (const place of places) {
    const row = el('div', 'entity-where-row');

    // Only a place the atlas can actually find becomes a link; the rest are
    // UEX terminal names, which the map has no dot for.
    if (place.placeId) {
      const link = el('button', 'entity-link', place.name);
      link.type = 'button';
      link.title = 'Show this on the map';
      link.addEventListener('click', () => entityMap(place.placeId, place.name));
      row.append(link);
    } else {
      row.append(el('span', 'entity-where-name', place.name));
    }

    if (place.note) row.append(el('span', 'entity-detail', place.note));
    node.append(row);
  }
}

function entityMap(placeId, name) {
  showView('map');
  if (placeId) centreOn(placeId);
  else if (name) jumpToPlace(name);
}

/**
 * Where "show on map" goes, which is a different question for each kind.
 *
 * Only a place has a dot of its own; passing a commodity name or an item class
 * to centreOn looks for a place id that was never going to exist, and the
 * button did nothing at all. A commodity goes through the map's own commodity
 * search, which is what colours the counters that trade it. A component has no
 * dot either, so it goes to the nearest thing the map can find - the cheapest
 * seller the catalogue named - and is not offered the button without one.
 */
function showEntityOnMap(card) {
  showView('map');

  if (card.kind === 'place') {
    centreOn(card.id);
    return;
  }

  // searchCommodity rather than writing the box: it also drops whatever the
  // cargo panel was describing. Setting the term alone recoloured the map and
  // left the panel beside it still describing the station opened before.
  if (card.kind === 'commodity') {
    searchCommodity(card.name);
    return;
  }

  // A seller is a UEX terminal name and the atlas holds place names - "Platinum
  // Bay, Baijini Point" against "Baijini Point" - so an exact search finds
  // nothing. centreOnTerminal is the loose match the shading already joins on.
  const seller = (card.places || [])[0];
  if (seller) centreOnTerminal(seller.name, seller.placeId);
}

const ENTITY_ACTION_LABEL = {
  map: 'Show on map',
  stop: 'Add as a stop',
  shopping: 'Add to shopping',
  overlay: 'Pin to overlay',
  details: 'Open details',
};

function renderEntityActions(card) {
  const bar = $('#entity-actions');
  bar.textContent = '';

  for (const action of card.actions || []) {
    // The overlay is already the pinned window; it has nothing to pin into.
    if (action === 'overlay' && isOverlay) continue;

    const button = el('button', 'ghost tiny', ENTITY_ACTION_LABEL[action] || action);
    button.type = 'button';
    button.addEventListener('click', () => runEntityAction(action, card, button));
    bar.append(button);
  }
}

async function runEntityAction(action, card, button) {
  if (action === 'map') return showEntityOnMap(card);
  if (action === 'details') return openEntityDetails(card);

  button.disabled = true;
  try {
    if (action === 'stop') {
      await fetch('/api/trips/stops', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ placeId: card.id, place: card.name, note: null }),
      });
      await loadTrips();
      button.textContent = '✓ added';
      return;
    }

    if (action === 'shopping') {
      const result = await fetch('/api/jobs/collect', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: card.name, needed: 1, unit: '' }),
      }).then((r) => r.json());

      button.textContent = '✓ added';
      button.title = `On "${result.title}"`;
      return;
    }

    if (action === 'overlay') {
      // The endpoint binds visible from the query, so a JSON body was ignored
      // and answered 400 - which fetch does not throw for, so the button said
      // it had worked every time.
      const response = await fetch('/api/overlay?visible=true', { method: 'POST' });
      if (!response.ok) throw new Error('overlay refused');

      button.textContent = '✓ pinned';
    }
  } catch {
    button.textContent = 'failed';
    button.disabled = false;
  }
}

/** The full page for this kind, which the drawer summarises rather than replaces. */
function openEntityDetails(card) {
  if (card.kind === 'commodity') return openCommodity(card.name);
  if (card.kind === 'ship') return showView('fleet');
  if (card.kind === 'part') return showView('parts');
  return entityMap(card.id, card.name);
}

$('#entity-close')?.addEventListener('click', closeEntity);

/* ---------- charts ---------- */

function bars(container, rows, format) {
  const node = $(container);
  node.textContent = '';

  if (!rows || rows.length === 0) {
    node.append(el('p', 'muted', 'No data yet.'));
    return;
  }

  const max = Math.max(...rows.map((r) => r.value)) || 1;

  for (const row of rows) {
    const wrapper = el('div', 'bar-row');

    // Rows can carry a click-through - the places charts fly to the map.
    if (row.onClick) {
      const label = el('div', 'label');
      const link = el('button', 'place-link', row.label);
      link.type = 'button';
      link.title = 'Show on the map';
      link.addEventListener('click', row.onClick);
      label.append(link);
      wrapper.append(label);
    } else {
      wrapper.append(el('div', 'label', row.label));
    }

    const track = el('div', 'bar-track');
    const fill = el('div', 'bar-fill');
    fill.style.width = `${Math.max(1, (row.value / max) * 100)}%`;
    if (row.colour) fill.style.background = row.colour;
    track.append(fill);

    wrapper.append(track);

    const amount = el('div', 'amount', format(row.value));
    if (row.note) {
      amount.append(el('span', 'note-inline', ` ${row.note}`));
    }
    wrapper.append(amount);
    node.append(wrapper);
  }
}

/* ---------- history ---------- */

/**
 * Runs one view's render in isolation.
 *
 * Without this a single failing view takes every later one down with it - a
 * throw in the fleet chart left Loadout and Stash blank - and boot()'s retry
 * loop swallowed the error, so the page just sat empty with no clue why.
 */
function safeRender(name, render) {
  const report = (error) => {
    console.error(`${name} failed to render`, error);

    const banner = $('#render-errors');
    banner.hidden = false;
    banner.append(el('div', null, `${name}: ${error && error.message ? error.message : error}`));
  };

  try {
    // Some renders became async once they had to fetch their own view; a
    // rejected promise would otherwise escape this net entirely.
    const result = render();
    if (result && typeof result.catch === 'function') result.catch(report);
  } catch (error) {
    report(error);
  }
}

async function loadHistory() {
  const [stats, sessions] = await Promise.all([getJson('/api/stats'), getJson('/api/sessions')]);

  $('#render-errors').textContent = '';
  $('#render-errors').hidden = true;

  allSessions = sessions;
  sessionPage = 0;

  // A Points page opened straight from the URL drew its cards before the
  // sessions were known, and said no session spanned any of them.
  if (pointsAll.length) safeRender('Points', () => renderPoints());

  safeRender('Sessions', () => renderSessions());
  safeRender('Fleet', () => renderFleet(stats));
  safeRender('Spending', () => renderSpending(stats));
  safeRender('Loadout', () => renderLoadout(stats));
  safeRender('Stash', () => renderStash(stats));
  loadAtlas().catch((e) => console.error('map', e));
  safeRender('Contracts', () => renderContracts(stats));
  safeRender('Places', () => renderPlaces(stats));
  // Routes can start before the ledger returns; rerun once the owned holds are
  // known so a selected ship cannot leave the table priced as one SCU.
  loadRoutes().catch((e) => console.error('routes after history', e));

  // These fetch their own data, so they are kicked off rather than awaited.
  loadLedger().catch((e) => console.error('ledger', e));
  loadLogbook().catch((e) => console.error('logbook', e));
  await loadManufacturers();

  // Awaited, so the catalogue fetches below know whether the game files are
  // ready yet - and so the poll that refills them is running even for someone
  // who never opens Settings or Mining, which is where it used to start.
  await loadGameData().catch(() => {});
  loadShipsRef().catch((e) => console.error('ships', e));
  loadPartsRef().catch((e) => console.error('parts', e));
  loadMiningRef().catch((e) => console.error('mining', e));
  loadCraftingRef().catch((e) => console.error('crafting', e));
  loadJobs().catch((e) => console.error('jobs', e));
  loadChecklists().catch((e) => console.error('checklists', e));
  loadCasualties().catch((e) => console.error('casualties', e));
  loadCrew().catch((e) => console.error('crew', e));
  loadRespawn().catch((e) => console.error('respawn', e));
  loadOutfitting().catch((e) => console.error('outfitting', e));
  loadRoutes().catch((e) => console.error('routes', e));
  loadCargoReceipts().catch((e) => console.error('cargo receipts', e));
  loadTrips().catch((e) => console.error('trips', e));
  loadMapNotes().catch((e) => console.error('map notes', e));
  loadCommodities().catch((e) => console.error('cargo', e));
  loadMarket().catch((e) => console.error('market', e));
  loadLoot().catch((e) => console.error('loot', e));
  loadAssets().catch((e) => console.error('assets', e));
}

function renderContracts(stats) {
  // Failures get a tile only when there are any. Five in a whole install is
  // worth seeing; a permanent zero beside four real figures is furniture, and
  // it would read as "nothing ever went wrong" on an install too new to know.
  const contractTiles = [
    ['Contracts seen', stats.contractsSeen],
    ['Completed', stats.contractsCompleted],
    ['Abandoned', stats.contractsAbandoned],
  ];

  if (stats.contractsFailed > 0) contractTiles.push(['Failed', stats.contractsFailed]);

  contractTiles.push(['Completion rate', stats.contractsSeen
    ? `${Math.round((stats.contractsCompleted / stats.contractsSeen) * 100)}%`
    : '—']);

  tiles('#contract-summary', contractTiles);

  renderContractsPaid(stats).catch(() => {});

  bars('#issuers-chart',
    stats.contractIssuers.slice(0, 15).map((c) => ({ label: c.name, value: c.count })),
    (v) => `${v}`);

  bars('#types-chart',
    stats.contractTypes.slice(0, 15).map((c) => ({ label: c.name, value: c.count })),
    (v) => `${v}`);

  loadContractList().catch((e) => console.error('contracts', e));
  loadStanding().catch((e) => console.error('standing', e));
}

/**
 * The contract list, with the objective progress the game pushes but never
 * showed anywhere: how many journal steps a contract had and how many closed.
 */
/**
 * Work done per faction.
 *
 * Deliberately not called reputation. Nothing in the logs carries a rep value -
 * the client opens a channel to a reputation service and the numbers live on
 * the other side of it - so this counts the thing that moves it instead. Where
 * a text mod has written the reward onto a contract's title, that number is
 * shown as what it is: something somebody else worked out, on the few contracts
 * they got to.
 */
async function loadStanding() {
  const days = Number($('#contracts-period').value) || 0;
  const rows = await getJson(`/api/standing?days=${days}`).catch(() => []);
  const body = $('#standing-table tbody');

  if (!body) return;
  body.textContent = '';

  if (!rows.length) {
    const tr = el('tr');
    const td = el('td', 'muted', 'No contracts in that range.');
    td.colSpan = 6;
    tr.append(td);
    body.append(tr);
    return;
  }

  for (const row of rows) {
    const tr = el('tr');
    tr.append(el('td', null, row.issuer));
    tr.append(el('td', 'num', String(row.contracts)));

    const done = el('td', 'num');
    done.append(el('span', row.completed ? 'done' : 'muted', String(row.completed)));

    // Finishing rate is the part that reads as standing: nine of ten is a
    // different relationship from nine of thirty.
    if (row.contracts > 0)
      done.append(el('span', 'muted', ` · ${Math.round((row.completed / row.contracts) * 100)}%`));

    tr.append(done);
    const dropped = el('td', row.abandoned ? 'num outward' : 'num muted', String(row.abandoned));

    // Failures ride the abandoned column rather than adding a fifth that is
    // empty for every issuer but one. The count is there when it is not zero.
    if (row.failed > 0) dropped.append(el('span', 'muted', ` · ${row.failed} failed`));

    tr.append(dropped);

    // Never a bare zero: no annotated title is "nobody wrote it down", which is
    // not the same as "this pays nothing".
    const rep = el('td', 'num');

    if (row.repFrom > 0) {
      rep.append(el('span', null, row.rep.toLocaleString()));
      rep.append(el('span', 'muted', ` · from ${row.repFrom}`));
      rep.title = `Read from ${row.repFrom} contract title${row.repFrom === 1 ? '' : 's'} the StarStrings mod has annotated`;
    } else {
      rep.append(el('span', 'muted', '—'));
      rep.title = 'No annotated title among these, so nobody has written down what they pay';
    }

    tr.append(rep);

    const span = el('td', 'muted');
    span.textContent = row.first === row.last
      ? dateOf(row.first)
      : `${dateOf(row.first)} → ${dateOf(row.last)}`;
    tr.append(span);

    body.append(tr);
  }
}

async function loadContractList() {
  const days = Number($('#contracts-period').value) || 0;
  const rows = await getJson(`/api/contracts?days=${days}`);
  const body = $('#contracts-table tbody');
  body.textContent = '';

  if (!rows.length) {
    const tr = el('tr');
    const td = el('td', 'muted', 'No contracts in that range.');
    td.colSpan = 9;
    tr.append(td);
    body.append(tr);
    return;
  }

  const OUTCOMES = {
    Completed: ['done', 'completed'],
    Abandoned: ['outward', 'abandoned'],

    // Worded as something that happened to you rather than something you did,
    // because that is the distinction the game is drawing and the whole reason
    // this is not filed as an abandonment.
    Failed: ['outward', 'failed'],
    InProgress: ['muted', 'in progress'],
    Unknown: ['muted', '—'],
  };

  for (const row of rows.slice(0, 400)) {
    const tr = el('tr');
    tr.append(el('td', null, dateOf(row.at)));

    // The composed name repeats issuer, type and difficulty, so the columns
    // carry those and the full name rides the row's tooltip.
    tr.append(el('td', null, row.issuer || '—'));
    tr.append(el('td', 'muted', row.type || '—'));
    tr.append(el('td', 'muted', row.difficulty || '—'));
    tr.append(el('td', 'muted', row.system || '—'));
    tr.title = row.name;

    const [cls, label] = OUTCOMES[row.outcome] || OUTCOMES.Unknown;
    tr.append(el('td', cls === 'done' ? 'inward' : cls, label));

    // What the title says it pays, when a text mod has annotated it. Silence
    // is the honest default: most titles say nothing, and a zero would read as
    // "this pays nothing" rather than "nobody wrote it down".
    const pays = el('td');

    if (row.rep) {
      const chip = el('span', 'tag-rep', `${row.rep.toLocaleString()} rep`);
      chip.title = 'From the contract title, annotated by the StarStrings mod';
      pays.append(chip);
    }

    if (row.blueprint) {
      const chip = el('span', 'tag-bp', 'BP');
      chip.title = 'Tagged as awarding a blueprint';
      pays.append(chip);
    }

    if (!row.rep && !row.blueprint) pays.append(el('span', 'muted', '—'));

    tr.append(pays);

    // Steps only exist for missions whose objectives were pushed while the
    // log was being written; older contracts honestly show nothing.
    const steps = el('td', 'num');
    if (row.steps > 0) {
      steps.textContent = `${row.stepsDone} / ${row.steps}`;
      if (row.stepsDone < row.steps) steps.classList.add('muted');
    } else {
      steps.textContent = '—';
      steps.classList.add('muted');
    }
    tr.append(steps);

    tr.append(el('td', 'num muted', row.minutes
      ? (row.minutes < 60 ? `${Math.round(row.minutes)}m` : `${(row.minutes / 60).toFixed(1)}h`)
      : '—'));

    body.append(tr);
  }
}

function renderPlaces(stats) {
  libraryStats = stats;

  const term = ($('#places-search').value || '').trim().toLowerCase();
  const match = (name) => !term || name.toLowerCase().includes(term);

  bars('#places-chart',
    stats.locations.filter((l) => match(l.name)).slice(0, 25).map((l) => ({
      label: l.name,
      value: l.visits,
      colour: KIND_COLOURS[l.kind],
      onClick: () => jumpToPlace(l.name),
    })),
    (v) => `${v}`);

  bars('#dests-chart',
    stats.destinations.filter((d) => match(d.name)).slice(0, 25)
      .map((d) => ({ label: d.name, value: d.visits, onClick: () => jumpToPlace(d.name) })),
    (v) => `${v}`);
}

/* .NET serialises TimeSpan as "hh:mm:ss" or "d.hh:mm:ss". */
function toSeconds(timespan) {
  if (typeof timespan === 'number') return timespan;
  if (!timespan) return 0;

  const [head, ...rest] = String(timespan).split('.');
  let days = 0;
  let clockPart = timespan;

  if (rest.length && head.indexOf(':') === -1) {
    days = parseInt(head, 10);
    clockPart = rest.join('.');
  }

  const [h = 0, m = 0, s = 0] = String(clockPart).split(':').map(parseFloat);
  return days * 86400 + h * 3600 + m * 60 + s;
}

/* ---------- sessions ---------- */

const SESSIONS_PER_PAGE = 25;
let allSessions = [];
let sessionPage = 0;
let expandedSessionId = null;
const sessionDetails = new Map();

/** Applies the period and search filters. */
function filteredSessions() {
  const term = ($('#sessions-search').value || '').trim().toLowerCase();
  const days = Number($('#sessions-period').value) || 0;
  const cutoff = days ? Date.now() - days * 86400000 : null;

  return allSessions.filter((s) => {
    if (cutoff && new Date(s.startedAt).getTime() < cutoff) return false;

    if (term) {
      const haystack = `${s.primaryShip || ''} ${s.lastLocation || ''}`.toLowerCase();
      if (!haystack.includes(term)) return false;
    }

    return true;
  });
}

async function toggleSessionDebrief(id) {
  if (expandedSessionId === id) {
    expandedSessionId = null;
    renderSessions();
    return;
  }

  expandedSessionId = id;
  renderSessions();

  if (!sessionDetails.has(id)) {
    try {
      sessionDetails.set(id, await getJson(`/api/sessions/${encodeURIComponent(id)}`));
    } catch {
      sessionDetails.set(id, { error: true });
    }
  }

  if (expandedSessionId === id) renderSessions();
}

function sessionRoute(detail) {
  const usefulQuantumTarget = (name) => name
    && !/^(PartyMemberMarker_|MISSION_)/i.test(name)
    && !/\.socpak$/i.test(name)
    && !['Nav Point', 'Rest Stop', 'Mission Beacon'].includes(name);

  const points = [
    ...(detail.locations || []).map((place) => ({ ...place, routeKind: 'arrival' })),
    ...(detail.jumps || []).filter((jump) => usefulQuantumTarget(jump.toName)).map((jump) => ({
      at: jump.at,
      rawId: jump.toId,
      displayName: jump.toName,
      system: null,
      body: null,
      routeKind: 'quantum',
    })),
  ].sort((a, b) => new Date(a.at) - new Date(b.at));

  return points.filter((place, index) => {
    if (index === 0) return true;
    const previous = points[index - 1];
    return place.rawId !== previous.rawId
      && place.displayName.toLowerCase() !== previous.displayName.toLowerCase();
  });
}

async function repeatSessionRoute(detail) {
  const route = sessionRoute(detail);
  if (!route.length) return;

  await planTrip(`Repeat ${dateOf(detail.startedAt)} route`, route.map((place) => ({
    placeId: place.rawId || '',
    place: place.displayName,
    note: `${place.routeKind === 'quantum' ? 'Quantum target' : 'Arrival'} logged at ${shortTimeOf(place.at)}`,
  })));
}

function sessionMetric(label, value, cls = '') {
  const metric = el('div', `session-metric ${cls}`.trim());
  metric.append(el('div', 'session-metric-value', value));
  metric.append(el('div', 'session-metric-label', label));
  return metric;
}

/**
 * The server a session row names: the last shard it was on, and how many
 * others came before it. A session that never left the menu has none, and a
 * dash says so rather than a blank that could be a session summarised before
 * shards were read.
 */
function sessionShardLabel(session) {
  if (!session.shard) return '—';
  const more = (session.shards || 1) - 1;
  return more > 0 ? `${session.shard} +${more}` : session.shard;
}

/** Every stay in a debrief, in order, each with how it ended. */
function sessionShardText(detail) {
  const stays = detail.shards || [];
  if (!stays.length) return 'None recorded';

  return stays.map((stay) => {
    const mins = Math.round((new Date(stay.leftAt) - new Date(stay.joinedAt)) / 60000);
    return `${stay.shard} · ${duration(mins * 60)} · ${endingLabel(stay.ending)}`;
  }).join('\n');
}

function renderSessionDebrief(summary) {
  const row = el('tr', 'session-detail-row');
  const cell = el('td');
  cell.colSpan = 10;
  row.append(cell);

  const detail = sessionDetails.get(summary.id);
  if (!detail) {
    cell.append(el('div', 'session-debrief-loading muted', 'Building session debrief…'));
    return row;
  }

  if (detail.error) {
    cell.append(el('div', 'session-debrief-loading outward', 'This session detail could not be read.'));
    return row;
  }

  const debrief = el('article', 'session-debrief');
  const head = el('div', 'session-debrief-head');
  const title = el('div');
  title.append(el('div', 'session-debrief-title', `${dateOf(detail.startedAt)} debrief`));
  title.append(el('div', 'muted', `${shortTimeOf(detail.startedAt)} → ${shortTimeOf(detail.endedAt)} · ${detail.gameVersion || 'version unknown'}`));
  head.append(title);

  const route = sessionRoute(detail);
  const repeat = el('button', 'ghost tiny', 'Repeat these stops');
  repeat.type = 'button';
  repeat.disabled = route.length === 0;
  repeat.title = route.length
    ? 'Create a new flight plan from the places reached in this session'
    : 'No named locations were recorded in this session';
  repeat.addEventListener('click', () => repeatSessionRoute(detail));
  head.append(repeat);
  debrief.append(head);

  const ships = (detail.ships || []).map((ship) =>
    `${ship.displayName || ship.model}${ship.sorties ? ` · ${ship.sorties} sortie${ship.sorties === 1 ? '' : 's'}` : ''}`);
  const contracts = detail.contracts || [];
  const completed = contracts.filter((contract) => contract.outcome === 'Completed').length;
  const party = new Set((detail.partyNotes || []).map((note) => note.handle).filter(Boolean));
  const tradeCount = (detail.trades || []).length;
  const movementCount = (detail.purchases || []).length + tradeCount;
  const net = Number(detail.income || 0) - Number(detail.spend || 0) - Number(detail.commoditySpend || 0);

  const metrics = el('div', 'session-debrief-metrics');
  metrics.append(
    sessionMetric('In game', duration(summary.inGame)),
    sessionMetric('Ship', ships.join(' · ') || 'On foot'),
    sessionMetric('Recorded route', `${route.length} point${route.length === 1 ? '' : 's'} · ${(detail.jumps || []).length} jump${(detail.jumps || []).length === 1 ? '' : 's'}`),
    sessionMetric('Contracts', contracts.length ? `${completed} / ${contracts.length} completed` : 'None recorded'),
    sessionMetric(tradeCount ? 'Recorded net*' : 'Recorded net', movementCount
      ? `${net < 0 ? '−' : '+'}${tradeCount ? '~' : ''}${money(Math.abs(net))}`
      : 'No movements recorded', movementCount ? (net < 0 ? 'outward' : 'inward') : ''),
    sessionMetric('Crew observed*', party.size ? `${party.size} named` : 'None named'),
    sessionMetric(detail.shards?.length > 1 ? 'Servers' : 'Server', sessionShardText(detail), 'session-metric-shards'),
  );
  debrief.append(metrics);

  const content = el('div', 'session-debrief-grid');

  const routeSection = el('section', 'session-debrief-section session-route-section');
  routeSection.append(el('h3', null, 'Chronological route'));
  const routeList = el('ol', 'session-route');
  route.forEach((place) => {
    const item = el('li');
    item.append(el('span', 'session-route-time', shortTimeOf(place.at)));
    item.append(placeLink(place.displayName));
    const context = place.routeKind === 'quantum'
      ? 'quantum destination'
      : [place.body, place.system].filter(Boolean).join(' · ');
    if (context) item.append(el('span', 'muted', context));
    routeList.append(item);
  });
  if (!route.length) routeList.append(el('li', 'muted', 'No named locations were written in this session.'));
  routeSection.append(routeList);
  content.append(routeSection);

  const commerceSection = el('section', 'session-debrief-section');
  commerceSection.append(el('h3', null, 'Recorded economy'));
  const commerce = [
    ...(detail.purchases || []).map((purchase) => ({
      at: purchase.at,
      label: `${prettyItem(purchase.item)}${purchase.quantity > 1 ? ` ×${purchase.quantity}` : ''}`,
      amount: -Number(purchase.total ?? purchase.price ?? 0),
      approximate: !purchase.confirmed,
    })),
    ...(detail.trades || []).map((trade) => ({
      at: trade.at,
      label: `${trade.isSell ? 'Cargo sold' : 'Cargo bought'} · ${trade.quantity} SCU`,
      amount: (trade.isSell ? 1 : -1) * Number(trade.amount || 0),
      approximate: true,
    })),
  ].sort((a, b) => new Date(a.at) - new Date(b.at));
  const commerceList = el('ul', 'session-debrief-list');
  commerce.slice(-8).forEach((entry) => {
    const item = el('li');
    item.append(el('span', 'muted', shortTimeOf(entry.at)));
    item.append(el('span', null, entry.label));
    item.append(el('span', entry.amount >= 0 ? 'inward' : 'outward',
      `${entry.amount >= 0 ? '+' : '−'}${entry.approximate ? '~' : ''}${money(Math.abs(entry.amount))}`));
    commerceList.append(item);
  });
  if (!commerce.length) commerceList.append(el('li', 'muted', 'No purchases or cargo trades recorded.'));
  commerceSection.append(commerceList);
  content.append(commerceSection);

  const contractSection = el('section', 'session-debrief-section');
  contractSection.append(el('h3', null, 'Contracts'));
  const contractList = el('ul', 'session-debrief-list');
  contracts.slice(0, 8).forEach((contract) => {
    const item = el('li');
    item.append(el('span', contract.outcome === 'Completed' ? 'inward' : 'muted', contract.outcome || 'Unknown'));
    item.append(el('span', null, contract.displayName || contract.raw || 'Unnamed contract'));
    if (contract.steps > 0) item.append(el('span', 'muted', `${contract.stepsDone} / ${contract.steps} steps`));
    contractList.append(item);
  });
  if (!contracts.length) contractList.append(el('li', 'muted', 'No contracts recorded.'));
  contractSection.append(contractList);
  content.append(contractSection);

  const highlightSection = el('section', 'session-debrief-section');
  highlightSection.append(el('h3', null, 'Latest highlights'));
  const highlights = (detail.timeline || [])
    .filter((entry) => !['party', 'location', 'quantum', 'login'].includes(entry.kind))
    .slice(-10);
  const highlightList = el('ul', 'session-debrief-list');
  highlights.forEach((entry) => {
    const item = el('li');
    item.append(el('span', 'muted', shortTimeOf(entry.at)));
    item.append(el('span', null, entry.text));
    if (entry.detail) item.append(el('span', 'muted', entry.detail));
    highlightList.append(item);
  });
  if (!highlights.length) highlightList.append(el('li', 'muted', 'No additional highlights recorded.'));
  highlightSection.append(highlightList);
  content.append(highlightSection);

  debrief.append(content);
  const limits = el('p', 'session-debrief-note muted',
    '* Cargo amounts are kiosk requests, not confirmed settlements. Crew observed is a floor from party notifications, not a roster.');
  debrief.append(limits);
  cell.append(debrief);
  return row;
}

/** Paged because a real library runs to well over a hundred sessions. */
function renderSessions() {
  const body = $('#sessions-table tbody');
  body.textContent = '';

  const sessions = filteredSessions();

  // Totals reflect the selected period, so the tiles answer "how much did I
  // play this month" rather than always restating the lifetime figures.
  summariseSessions(sessions);

  const pages = Math.max(1, Math.ceil(sessions.length / SESSIONS_PER_PAGE));
  sessionPage = Math.min(Math.max(0, sessionPage), pages - 1);

  const start = sessionPage * SESSIONS_PER_PAGE;
  const page = sessions.slice(start, start + SESSIONS_PER_PAGE);

  if (page.length === 0) {
    const tr = el('tr');
    const td = el('td', 'muted', 'No sessions in that range.');
    td.colSpan = 10;
    tr.append(td);
    body.append(tr);
  }

  for (const session of page) {
    const tr = el('tr', 'session-row');
    const open = expandedSessionId === session.id;
    tr.classList.toggle('open', open);
    tr.tabIndex = 0;
    tr.setAttribute('aria-expanded', String(open));
    tr.title = open ? 'Close session debrief' : 'Open session debrief';
    tr.addEventListener('click', () => toggleSessionDebrief(session.id));
    tr.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        toggleSessionDebrief(session.id);
      }
    });
    const cells = [
      duration(session.inGame),
      duration(session.menu),
      session.primaryShip || '—',
      session.lastLocation || '—',
      sessionShardLabel(session),
    ];
    const date = el('td');
    date.append(el('span', 'session-row-toggle', open ? '⌄' : '›'));
    date.append(el('span', null, dateOf(session.startedAt)));
    tr.append(date);
    cells.forEach((text) => tr.append(el('td', null, text)));
    [session.jumps, session.contracts, session.deaths ?? 0, session.incapacitations]
      .forEach((n) => tr.append(el('td', 'num', String(n))));
    body.append(tr);
    if (open) body.append(renderSessionDebrief(session));
  }

  renderPager(pages, start, page.length, sessions.length);
}

function summariseSessions(sessions) {
  const sum = (pick) => sessions.reduce((total, s) => total + (pick(s) || 0), 0);

  tiles('#lib-summary', [
    ['Sessions', sessions.length],
    ['In game', duration(sum((s) => s.inGame))],
    ['In menus', duration(sum((s) => s.menu))],
    ['Quantum jumps', sum((s) => s.jumps)],
    ['Contracts', sum((s) => s.contracts)],
    ['Deaths', sum((s) => s.deaths)],
  ]);
}

function renderPager(pages, start, shown, total) {
  const pager = $('#sessions-pager');
  pager.textContent = '';

  if (total === 0) return;

  pager.append(el('span', 'pager-info', `${start + 1}–${start + shown} of ${total}`));

  const nav = el('div', 'pager-nav');

  const step = (label, delta, disabled) => {
    const button = el('button', 'pager-btn', label);
    button.disabled = disabled;
    button.addEventListener('click', () => { sessionPage += delta; renderSessions(); });
    return button;
  };

  nav.append(step('‹ Newer', -1, sessionPage === 0));
  nav.append(el('span', 'pager-page', `${sessionPage + 1} / ${pages}`));
  nav.append(step('Older ›', 1, sessionPage >= pages - 1));

  pager.append(nav);
}

/* ---------- ledger ---------- */

const LEDGER_PER_PAGE = 40;
let ledgerEntries = [];
let ledgerPage = 0;

/** Kinds the reader has switched off. Empty means everything, which is the default. */
let ledgerHidden = new Set();

/**
 * The kinds present, in the order the ledger itself uses.
 *
 * Built from the rows rather than from a fixed list: a toggle for something
 * that never happens is a control that empties the table and teaches nothing.
 */
function ledgerKinds() {
  return [...new Set(ledgerEntries.map((entry) => entry.kind))].sort();
}

function renderLedgerKinds() {
  const row = $('#ledger-kinds');
  if (!row) return;

  row.textContent = '';

  const kinds = ledgerKinds();

  // One kind is not a choice.
  if (kinds.length < 2) return;

  for (const kind of kinds) {
    const on = !ledgerHidden.has(kind);
    const button = el('button', on ? 'ghost' : 'ghost off', kind);
    button.type = 'button';
    button.dataset.kind = kind;
    button.title = on ? `Hide ${kind}` : `Show ${kind}`;

    button.addEventListener('click', () => {
      if (on) ledgerHidden.add(kind);
      else ledgerHidden.delete(kind);

      ledgerPage = 0;
      renderLedger();
    });

    row.append(button);
  }
}

async function loadLedger() {
  const days = Number($('#ledger-period').value) || 0;
  ledgerEntries = await getJson(`/api/ledger?days=${days}`);

  // A filter is an answer about the rows currently on screen. Keeping it when
  // the period fetches a different set can hide the only kind in that range;
  // with one kind there is no toggle to bring it back, so the page would say
  // there were no transactions when it had just fetched one.
  ledgerHidden.clear();
  ledgerPage = 0;
  renderLedger();

  // After the table, so a balance that will not load never costs the ledger.
  await loadLedgerWallet();
}

/** The screenshot the cash card was last drawn from, so the stream can say when there is a newer one. */
let ledgerWalletShot = null;

/**
 * Cash on hand, which no line in Game.log ever states. The last screenshot
 * that showed the balance is the figure, and the ledger's movements since
 * carry it forward. The carried figure is called an estimate because it is
 * one: the logs miss insurance claims, hangar fees and anything the parser
 * does not recognise, and only the next screenshot says by how much.
 */
async function loadLedgerWallet() {
  const card = $('#ledger-wallet');
  if (!card) return;

  let got;

  try {
    got = await getJson('/api/ledger/wallet');
  } catch {
    card.hidden = true;
    return;
  }

  renderLedgerWallet(got.read);
}

function renderLedgerWallet(read) {
  renderNowCash(read);

  const card = $('#ledger-wallet');
  if (!card) return;

  card.textContent = '';
  card.hidden = false;

  // Marked only when there is a shot to mark: an empty answer must not
  // forget the frame that just asked, or the next frame asks again.
  if (read?.shot) ledgerWalletShot = read.shot;

  if (!read) {
    card.append(el('div', 'l', 'Cash on hand'));
    card.append(el('div', 'muted',
      'No screenshot has shown your balance yet. A commodity kiosk prints it in full — photograph one and the figure lands here.'));
    return;
  }

  const figure = el('div', 'wallet-figure');
  figure.append(el('div', 'n', money(read.balance)));
  figure.append(el('div', 'l', 'Cash on hand'));
  card.append(figure);

  const body = el('div', 'wallet-body');
  body.append(el('div', null, `Last updated ${new Date(read.shotAt).toLocaleString()}, from ${read.shot || 'a screenshot'}.`));

  const moved = Number(read.movedSince) || 0;
  const lines = Number(read.movementsSince) || 0;

  if (lines === 0) {
    body.append(el('div', 'muted', 'Nothing has moved in the logs since, so that is the latest word.'));
  } else {
    const sign = moved > 0 ? '+' : moved < 0 ? '−' : '';
    body.append(el('div', 'muted',
      `Since then the logs record ${lines} movement${lines === 1 ? '' : 's'} netting ${sign}${money(Math.abs(moved))}, `
      + `so about ${money(read.estimate)} now — an estimate, because money that moved without a line in the log is not in it.`));
  }

  card.append(body);
}

function renderLedger() {
  const body = $('#ledger-table tbody');
  body.textContent = '';

  renderLedgerKinds();

  const visible = ledgerEntries.filter((entry) => !ledgerHidden.has(entry.kind));

  const inbound = visible.filter((e) => e.amount > 0);
  const outbound = visible.filter((e) => e.amount < 0);

  const sum = (rows) => rows.reduce((total, e) => total + Number(e.amount), 0);
  const net = sum(visible);

  const days = Number($('#ledger-period').value) || 0;

  /*
   * The totals follow the filter, because a contract total is the reason to
   * filter at all - but the "why this number?" does not. The server explains
   * the whole figure, and offering it over a filtered one would answer a
   * question nobody asked with records that do not add up to what is on
   * screen. So the control is there when everything is shown and gone when it
   * is not, and the line below says why.
   */
  const filtered = ledgerHidden.size > 0;

  tiles('#ledger-summary', [
    ['Money in', money(sum(inbound)), filtered ? null : 'ledger.in', days],
    ['Money out', money(Math.abs(sum(outbound))), filtered ? null : 'ledger.out', days],
    [net >= 0 ? 'Net gain' : 'Net loss', money(Math.abs(net)), filtered ? null : 'ledger.net', days],
    ['Movements', visible.length],
  ]);

  const filterNote = $('#ledger-kinds');

  if (filtered && filterNote) {
    filterNote.append(el('span', 'muted',
      'Totals cover only what is shown. Turn everything back on to ask where a figure came from.'));
  }

  const pages = Math.max(1, Math.ceil(visible.length / LEDGER_PER_PAGE));
  ledgerPage = Math.min(Math.max(0, ledgerPage), pages - 1);

  const start = ledgerPage * LEDGER_PER_PAGE;
  const page = visible.slice(start, start + LEDGER_PER_PAGE);

  if (!page.length) {
    const tr = el('tr');
    const td = el('td', 'muted', 'No transactions in that range.');
    td.colSpan = 7;
    tr.append(td);
    body.append(tr);
  }

  for (const entry of page) {
    const tr = el('tr');
    const inward = Number(entry.amount) > 0;

    tr.append(el('td', null, dateOf(entry.at)));
    tr.append(el('td', null, entry.kind));
    tr.append(el('td', null, prettyItem(entry.what)));
    tr.append(tdPlace(entry.where));
    tr.append(el('td', 'muted', entry.shop));

    // Unconfirmed amounts are marked rather than silently presented as settled.
    const amount = el('td', `num ${inward ? 'inward' : 'outward'}`,
      `${inward ? '+' : '−'}${entry.confirmed ? '' : '~'}${money(Math.abs(entry.amount))}`);
    tr.append(amount);

    tr.append(el('td', 'num muted', money(entry.running)));
    body.append(tr);
  }

  renderLedgerPager(pages, start, page.length, visible.length);
}

function renderLedgerPager(pages, start, shown, total) {
  const pager = $('#ledger-pager');
  pager.textContent = '';

  if (!total) return;

  pager.append(el('span', 'pager-info',
    `${start + 1}–${start + shown} of ${total}`));

  const nav = el('div', 'pager-nav');
  const step = (label, delta, disabled) => {
    const button = el('button', 'pager-btn', label);
    button.disabled = disabled;
    button.addEventListener('click', () => { ledgerPage += delta; renderLedger(); });
    return button;
  };

  nav.append(step('‹ Newer', -1, ledgerPage === 0));
  nav.append(el('span', 'pager-page', `${ledgerPage + 1} / ${pages}`));
  nav.append(step('Older ›', 1, ledgerPage >= pages - 1));

  pager.append(nav);
}

/* ---------- cargo trading ---------- */

async function loadCommodities() {
  const days = Number($('#commodities-period').value) || 0;
  renderCommodities(await getJson(`/api/commodities?days=${days}`));
  refreshCommunityOffer().catch(() => {});
}

/**
 * The opt-in that names the cargo. The offer is shown only while the dataset is
 * absent; enabling it is a deliberate click, and the app's one network request.
 */
async function refreshCommunityOffer() {
  const community = await getJson('/api/community');

  $('#community-offer').hidden = community.enabled;

  if (community.enabled) {
    $('#cargo-caption').textContent =
      'Volume, price and place come straight from the kiosk. Commodity names come '
      + 'from your own install, falling back to the community dataset '
      + `(${community.commodities} commodities, StarCitizenWiki / scunpacked-data) `
      + 'for anything it does not name.';
  }
}

async function setCommunity(enabled, statusNode, button) {
  button.disabled = true;
  statusNode.textContent = enabled ? 'downloading…' : 'removing…';

  try {
    const result = await fetch(`/api/community/${enabled ? 'enable' : 'disable'}`, { method: 'POST' });
    if (!result.ok) {
      // The endpoint puts the cause in `detail` - which file, which status -
      // and showing only the title made every one of eleven downloads fail
      // with the same sentence and nothing to act on.
      const problem = await result.json().catch(() => ({}));
      throw new Error([problem.title || result.statusText, problem.detail]
        .filter(Boolean).join(' '));
    }

    statusNode.textContent = '';
    await loadCommodities();
    await loadHistory();       // the ledger names its cargo rows too
    await renderSettings();
  } catch (e) {
    statusNode.textContent = `failed: ${e.message}`;
  } finally {
    button.disabled = false;
  }
}

$('#community-enable').addEventListener('click', (e) =>
  setCommunity(true, $('#community-status'), e.currentTarget));

// Refresh is the same call as enable: EnableAsync re-downloads and overwrites
// every digest, so there was nothing to add underneath - only a button saying
// so, because Download hidden behind 'already downloaded' left no way to ask
// for newer files short of deleting the copy you had.
$('#settings-community-refresh').addEventListener('click', (e) =>
  setCommunity(true, $('#settings-community-status'), e.currentTarget));

/* ---------- diagnostics ---------- */

/**
 * The short version of the report, as text for a clipboard: the app, the
 * game data, the price feeds and the parser, in the words a support thread
 * needs first. Built from the same lists the full report is - nothing here
 * is read from a log - so it carries no handle, id, path or key either.
 */
function diagnosticSummary(version, gamedata, uex, feeds, report) {
  const age = (iso) => (iso ? ago(iso) : 'never');
  const lines = [`Quantum Wake ${version?.version || '?'} (${version?.build || 'build unknown'})`];
  lines.push(`Taken ${new Date(report?.takenAt || Date.now()).toISOString()}`);
  lines.push('');

  const install = report?.install || {};
  lines.push(`Install: ${install.found ? `${install.channel || 'unknown channel'}, Game.log ${install.hasGameLog ? 'present' : 'absent'}, ${install.backups ?? 0} backup logs` : 'not found'}`);
  const gd = gamedata || {};
  const counts = gd.counts ? Object.entries(gd.counts).map(([k, v]) => `${k} ${v}`).join(', ') : '';
  // The one free-text field: an exception's message, which on a file error
  // carries the path it failed on, user name and all. Redacted, not trusted.
  lines.push(`Game data: ${gd.state || 'unknown'}${gd.problem ? ` - ${redactPaths(gd.problem)}` : ''}${gd.finishedAt ? `, read ${age(gd.finishedAt)}` : ''}${counts ? ` (${counts})` : ''}`);

  const data = report?.data || {};
  lines.push(`Community dataset: ${data.community ? `on, dump ${data.communityDump || '?'}` : 'off'}`);
  lines.push(`UEX prices: ${uex?.enabled ? `on, ${uex.prices ?? 0} prices, fetched ${age(uex.fetchedAt)}` : 'off'}${data.uexKeysStored ? ', keys stored' : ''}`);
  const on = (feeds || []).filter((f) => f.enabled);
  lines.push(`UEX feeds: ${on.length ? on.map((f) => `${f.key} ${age(f.fetchedAt)}`).join(', ') : 'none'}`);
  lines.push('');

  const lib = report?.library || {};
  lines.push(`Sessions: ${lib.sessions ?? 0} read, ${lib.counted ?? 0} counted${lib.first ? `, ${String(lib.first).slice(0, 10)} to ${String(lib.last).slice(0, 10)}` : ''}`);
  if (lib.builds?.length) lines.push(`Game builds: ${lib.builds.map((b) => `${b.build} (${b.sessions})`).join(', ')}`);
  const parser = report?.parser || {};
  lines.push(`Parser: ${parser.unread ? `${parser.unread} unreadable line${parser.unread === 1 ? '' : 's'} across ${(parser.tags || []).length} tag${(parser.tags || []).length === 1 ? '' : 's'}` : 'nothing unreadable'}`);
  const views = report?.views || {};
  lines.push(`Counts: ${Object.entries(views).map(([k, v]) => `${k} ${v}`).join(', ')}`);
  const wipe = report?.wipe || {};
  if (wipe.at) lines.push(`Wipe line: ${String(wipe.at).slice(0, 10)}${wipe.patch ? ` (${wipe.patch})` : ''}, ${wipe.hidden ?? 0} sessions before it`);
  return lines.join('\n');
}

/**
 * Every file path in a piece of text, replaced with a marker. Windows paths
 * with a drive or a UNC root, and Unix ones from a root or a home, however
 * they are quoted; what is left says the kind of failure without the name of
 * the person it failed for.
 */
function redactPaths(text) {
  return String(text ?? '')
    .replace(/[A-Za-z]:[\\/](?:[^\\/:*?"'<>|\r\n]+[\\/])*[^\\/:*?"'<>|\r\n]*/g, '<path>')
    .replace(/\\\\[^\\/\s]+(?:[\\/][^\\/:*?"'<>|\r\n]*)+/g, '<path>')
    .replace(/(?:^|[\s'"(])(?:\/(?:home|Users|tmp|var|etc|opt|mnt|media|root)|~)\/[^\s'")]*/g, (m) => m[0].match(/[\s'"(]/) ? `${m[0]}<path>` : '<path>');
}

/** Builds the summary from live answers and puts it on the clipboard; shows it when the clipboard is not to be had. */
async function copyDiagnosticSummary(button) {
  const status = $('#diag-status');
  button.disabled = true;
  status.textContent = 'Building the summary…';
  try {
    const [version, gamedata, uex, feeds, report] = await Promise.all([
      getJson('/api/version').catch(() => null),
      getJson('/api/gamedata').catch(() => null),
      getJson('/api/uex').catch(() => null),
      getJson('/api/uex/feeds').catch(() => []),
      getJson('/api/diagnostics?samples=false'),
    ]);
    const text = diagnosticSummary(version, gamedata, uex, feeds, report);
    let copied = false;
    try {
      if (navigator.clipboard?.writeText) { await navigator.clipboard.writeText(text); copied = true; }
    } catch { copied = false; }
    const box = $('#diag-summary');
    if (box) { box.value = text; box.hidden = copied; }
    status.textContent = copied
      ? 'Copied. Paste it into the issue or the thread; read it first if you like - it is the text below the report.'
      : 'The clipboard is not available here; the summary is shown below to copy by hand.';
  } catch (err) {
    status.textContent = `The summary could not be built: ${err.message}`;
  } finally {
    button.disabled = false;
  }
}

$('#diag-copy')?.addEventListener('click', (e) => copyDiagnosticSummary(e.currentTarget));

/**
 * What a bug report would carry, said before it is written.
 *
 * The same rule the export block follows: the reader sees what would go
 * before there is a file to send. Here it matters more, because the thing
 * being weighed is privacy rather than size - "nothing personal is in it" is
 * a claim, and a claim is worth less than the counts sitting next to it.
 */
/** Example lines are raw log text, so they are asked for rather than assumed. */
const wantsSamples = () => $('#diag-samples').checked === true;

async function renderDiagnostics() {
  const preview = $('#diag-preview');

  try {
    const report = await getJson(`/api/diagnostics?samples=${wantsSamples()}`);
    diagnosticsReport = report;

    const unread = report.parser.unread
      ? `${report.parser.unread} unreadable ${report.parser.unread === 1 ? 'line' : 'lines'}`
        + ` across ${report.parser.tags.length} tag${report.parser.tags.length === 1 ? '' : 's'}`
      : 'nothing unreadable in what was parsed this run';

    preview.textContent = [
      `${report.library.sessions} session${report.library.sessions === 1 ? '' : 's'}`,
      `${report.library.builds.length} game build${report.library.builds.length === 1 ? '' : 's'}`,
      unread,
      report.parser.samples && report.parser.unread
        ? 'with an example of each'
        : null,
    ].filter(Boolean).join(' · ');
  } catch {
    preview.textContent = '';
  }
}

async function renderDiagnosticTrace() {
  const toggle = $('#diag-trace-enabled');
  const save = $('#diag-trace-save');
  const status = $('#diag-trace-status');

  try {
    const trace = await getJson('/api/diagnostics/trace');
    toggle.checked = trace.enabled === true;
    save.hidden = !(trace.bytes > 0);
    status.textContent = trace.enabled
      ? `${trace.bytes.toLocaleString()} bytes recorded locally; restart to trace startup.`
      : trace.bytes > 0
        ? `${trace.bytes.toLocaleString()} bytes kept locally from an earlier trace.`
        : 'Off — turn it on before reproducing a crash.';
  } catch {
    status.textContent = 'Trace status is unavailable.';
  }
}

let diagnosticsReport = null;

$('#diag-samples').addEventListener('change', () => renderDiagnostics());

$('#diag-trace-enabled').addEventListener('change', async (e) => {
  const toggle = e.currentTarget;
  const status = $('#diag-trace-status');
  toggle.disabled = true;

  try {
    const trace = await getJson2(`/api/diagnostics/trace?enabled=${toggle.checked}`);
    status.textContent = trace.enabled
      ? 'Detailed tracing is on. Restart now to include startup.'
      : 'Detailed tracing is off; the existing trace is kept until you save it.';
  } catch (err) {
    status.textContent = `Trace setting could not be saved: ${err.message}`;
  } finally {
    toggle.disabled = false;
    renderDiagnosticTrace();
  }
});

$('#diag-trace-save').addEventListener('click', async (e) => {
  const button = e.currentTarget;
  const status = $('#diag-trace-status');
  button.disabled = true;

  try {
    const response = await fetch('/api/diagnostics/trace/file', { method: 'POST' });
    if (!response.ok) throw new Error((await response.json()).message || response.statusText);
    const url = URL.createObjectURL(await response.blob());
    const link = el('a');
    link.href = url;
    link.download = 'quantumwake-trace.log';
    link.click();
    URL.revokeObjectURL(url);
    status.textContent = 'Saved quantumwake-trace.log. Read it before sharing.';
  } catch (err) {
    status.textContent = `Trace could not be saved: ${err.message}`;
  } finally {
    button.disabled = false;
  }
});

$('#diag-save').addEventListener('click', async (e) => {
  const button = e.currentTarget;
  const status = $('#diag-status');

  button.disabled = true;
  status.textContent = 'Building the report…';

  let url = null;

  try {
    // Fetched again rather than saving what the preview held: the preview may
    // have been drawn before a scan finished, and a report is worth nothing if
    // it describes a moment other than the one being reported.
    const report = await getJson(`/api/diagnostics?samples=${wantsSamples()}`);
    diagnosticsReport = report;

    const stamp = String(report.takenAt).slice(0, 10);
    const name = `quantumwake-report-${stamp}.json`;

    const blob = new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' });
    url = URL.createObjectURL(blob);

    const link = el('a');
    link.href = url;
    link.download = name;
    link.click();

    status.textContent = `Saved ${name}. Read it, then attach it to an issue.`;
  } catch (err) {
    status.textContent = `The report could not be built: ${err.message}`;
  } finally {
    if (url) URL.revokeObjectURL(url);
    button.disabled = false;
  }
});

/* ---------- trade advice ---------- */

let adviceFor = null;

/**
 * The "trade from here" card on the Now page and the overlay: what this
 * place's terminal sells cheap and where it fetches the most. Fetched only
 * when the place changes, and only while UEX is enabled - the card simply
 * stays hidden otherwise.
 */
async function refreshTradeAdvice(place) {
  const card = $('#trade-advice-card');

  // A local planning choice is more useful than a generic margin when the
  // chosen hull cannot carry a commodity at all. The source prices remain on
  // Market; only this actionable card is withheld.
  if (!place || planningBlocksCargo()) {
    card.hidden = true;
    adviceFor = null;
    return;
  }

  if (place === adviceFor)
    return;

  adviceFor = place;

  const advice = await getJson(`/api/trade/advice?place=${encodeURIComponent(place)}`);

  if (!advice.terminal || !advice.opportunities.length) {
    card.hidden = true;
    return;
  }

  $('#trade-advice-sub').textContent =
    `${advice.terminal} · best margins per SCU, UEX community prices`;

  const list = $('#trade-advice');
  list.textContent = '';

  for (const o of advice.opportunities) {
    const li = el('li');
    li.append(el('b', null, o.commodity));
    li.append(el('span', 'muted', ` buy ${money(o.buyHere)} → sell ${money(o.sellThere)} at ${o.sellTerminal} `));
    li.append(el('span', 'inward', `+${money(o.marginPerScu)}/SCU`));
    list.append(li);
  }

  card.hidden = false;
}

/* ---------- market ---------- */

/** The community catalogue, cached for the map's commodity search too. */
let marketEntries = [];

/**
 * Whether Market rows show each price's age. On by default - a trader judges
 * a number by how old it is - and switchable from Settings for anyone who
 * finds the extra line noise.
 */
let showPriceAge = true;
try { showPriceAge = localStorage.getItem('qw-uex-age') !== '0'; } catch { /* fine */ }

/** Fine-grained "how long ago" for prices, where days are too coarse. */
function ago(iso) {
  if (!iso) return 'unknown';

  const mins = Math.floor((Date.now() - new Date(iso).getTime()) / 60000);
  if (mins < 1) return 'just now';
  if (mins < 60) return `${mins}m ago`;

  const hours = Math.floor(mins / 60);
  if (hours < 48) return `${hours}h ago`;

  const days = Math.floor(hours / 24);
  if (days < 60) return `${days}d ago`;

  return `${Math.round(days / 30)}mo ago`;
}

async function loadMarket() {
  try {
    marketEntries = await getJson('/api/market');
  } catch {
    marketEntries = [];
  }

  // Fuel, when that feed is on: cheapest refill per terminal.
  try {
    const fuel = await getJson('/api/uex/fuel');
    $('#fuel-block').hidden = fuel.length === 0;

    const fuelBody = $('#fuel-table tbody');
    fuelBody.textContent = '';

    // Only the cheapest few of each fuel. Every terminal that sells hydrogen
    // is two hundred rows nobody reads, and it buried the commodities this
    // page is actually about.
    const perFuel = 8;
    const byFuel = new Map();

    for (const row of [...fuel].sort((a, b) => a.price - b.price)) {
      if (!byFuel.has(row.fuel)) byFuel.set(row.fuel, []);
      byFuel.get(row.fuel).push(row);
    }

    for (const [name, rows] of [...byFuel].sort((a, b) => a[0].localeCompare(b[0]))) {
      for (const row of rows.slice(0, perFuel)) {
        const tr = el('tr');
        tr.append(el('td', null, name));
        tr.append(tdPlace(row.terminal, 'muted'));
        tr.append(el('td', 'num', money(row.price)));
        fuelBody.append(tr);
      }
    }

    const hidden = fuel.length - [...byFuel.values()].reduce((n, r) => n + Math.min(perFuel, r.length), 0);
    $('#fuel-count').textContent = hidden > 0
      ? `Cheapest ${perFuel} per fuel shown; ${hidden.toLocaleString()} dearer terminals not listed.`
      : '';
  } catch { $('#fuel-block').hidden = true; }

  // The snapshot's own age and the shortcut to renew it, next to the search -
  // the Settings page should not be the only road to a fresh number.
  try {
    const uex = await getJson('/api/uex');
    $('#market-refresh').hidden = !uex.enabled;
    $('#market-age').textContent = uex.enabled && uex.fetchedAt
      ? `prices fetched ${ago(uex.fetchedAt)}`
      : '';
  } catch { /* leave the header as it is */ }

  // The group dropdown offers every group the catalogue actually uses,
  // rebuilt on load and keeping the user's pick when it still exists.
  const groupSelect = $('#market-group');
  const previous = groupSelect.value;
  const groups = [...new Set(marketEntries.flatMap((e) => e.groups))].sort();

  groupSelect.textContent = '';
  groupSelect.append(new Option('All groups', ''));
  for (const group of groups) groupSelect.append(new Option(group, group));
  if (groups.includes(previous)) groupSelect.value = previous;

  renderMarket();

  // The map's commodity search reads this catalogue, and the map usually draws
  // first. A search already standing (a ?q= link opened cold) would have found
  // nothing; redraw it now the names exist.
  if (($('#map-search')?.value || '').trim() && atlas.length) drawMap();
}

/* ---------- where a commodity actually trades ---------- */

/**
 * Every terminal for one commodity, fetched once and kept.
 *
 * The table's UEX column answers "what is the best price anywhere", which is
 * one number and often a bad plan: the best price can be four jumps into
 * lawless space, or be a counter that wants nine SCU. The choice belongs to the
 * player, so the rows behind that number are shown and ranked, with what it
 * would cost to take each one.
 */
const terminalCache = new Map();

async function terminalsFor(commodity) {
  if (!terminalCache.has(commodity)) {
    terminalCache.set(commodity,
      getJson(`/api/uex/market?commodity=${encodeURIComponent(commodity)}`).catch(() => []));
  }

  return terminalCache.get(commodity);
}

/** What the open detail is showing, so the controls can redraw it. */
const detailView = { commodity: null, buying: false, monitoredOnly: false };

/**
 * Demand small enough that the trip is the wrong shape.
 *
 * Not a hard rule - a hauler carrying two SCU is fine - but a counter wanting
 * 12 SCU is not where a full hold goes, and the number alone does not say so
 * at a glance.
 */
const THIN_SCU = 64;

function toggleMarketDetail(entry, row) {
  const open = row.nextElementSibling?.classList.contains('market-detail');

  // One at a time: two open tables in one page is a page nobody reads.
  $$('#market-table tr.market-detail').forEach((n) => n.remove());
  $$('#market-table tr.expanded').forEach((n) => n.classList.remove('expanded'));

  if (open) {
    detailView.commodity = null;
    return;
  }

  detailView.commodity = entry.name;
  row.classList.add('expanded');

  const holder = el('tr', 'market-detail');
  const cell = el('td');
  cell.colSpan = 8;
  holder.append(cell);
  row.after(holder);

  renderMarketDetail(entry, cell);
}

async function renderMarketDetail(entry, cell) {
  cell.textContent = '';

  const head = el('div', 'detail-head');
  head.append(el('b', null, `${entry.name} — every counter UEX knows`));

  const side = el('div', 'seg');
  for (const [value, label] of [['sell', 'Where to sell'], ['buy', 'Where to buy']]) {
    const button = el('button', (value === 'buy') === detailView.buying ? 'active' : null, label);
    button.addEventListener('click', () => {
      detailView.buying = value === 'buy';
      renderMarketDetail(entry, cell);
    });
    head.append(button);
    side.append(button);
  }

  head.textContent = '';
  head.append(el('b', null, `${entry.name} — every counter UEX knows`));

  // Beside the title rather than at the far end: the detail table is wider than
  // the panel, so anything pushed right is pushed off the edge.
  const more = el('button', 'ghost detail-more', 'Full picture ↗');
  more.title = 'Price and demand over time, both counter lists, and your receipts';
  more.addEventListener('click', () => openCommodity(entry.name));
  head.append(more);

  head.append(side);

  const safe = el('label', 'toggle');
  const box = el('input');
  box.type = 'checkbox';
  box.checked = detailView.monitoredOnly;
  box.addEventListener('change', () => {
    detailView.monitoredOnly = box.checked;
    renderMarketDetail(entry, cell);
  });

  safe.append(box);
  safe.append(el('span', null, 'Monitored space only'));
  head.append(safe);
  cell.append(head);

  // The strip goes in before the table is awaited, so the panel does not sit
  // empty while a fetch per counter runs. It fills itself in afterwards.
  const strip = el('div', 'detail-spark');
  cell.append(strip);
  drawDetailSpark(strip, entry.name).catch(() => strip.remove());

  const all = await terminalsFor(entry.name);
  const priceOf = (r) => (detailView.buying ? r.buy : r.sell);
  const scuOf = (r) => (detailView.buying ? r.buyScu : r.sellScu);

  const rows = all
    .filter((r) => priceOf(r) > 0)
    .filter((r) => !detailView.monitoredOnly || r.security === 'monitored')
    .sort((a, b) => (detailView.buying ? priceOf(a) - priceOf(b) : priceOf(b) - priceOf(a)));

  if (!rows.length) {
    cell.append(el('div', 'muted detail-empty', all.length
      ? 'Nothing left after that filter — every counter for this is outside monitored space.'
      : 'No prices for this commodity. UEX may be off, or nobody has reported one.'));
    return;
  }

  const best = priceOf(rows[0]);

  const table = el('table', 'detail-table');
  const header = el('tr');
  for (const [label, cls] of [['Terminal', null], ['Where', null], ['Space', null],
    [detailView.buying ? 'Buy' : 'Sell', 'num'], ['vs best', 'num'],
    [detailView.buying ? 'In stock' : 'Wanted', 'num'], ['Seen', 'num']]) {
    header.append(el('th', cls, label));
  }
  table.append(header);

  for (const row of rows.slice(0, 40)) {
    const tr = el('tr');
    const price = priceOf(row);
    const scu = Math.round(scuOf(row));

    const name = el('td');
    const jump = el('button', 'place-link', row.terminal);
    jump.title = row.placeId ? 'Show it on the map' : 'The map cannot place this terminal';
    jump.disabled = !row.placeId;
    jump.addEventListener('click', () => {
      showView('map');
      centreOnTerminal(row.terminal, row.placeId);
    });
    name.append(jump);
    tr.append(name);

    tr.append(el('td', 'muted', row.place || '—'));

    const space = el('td');
    space.append(el('span', `sec sec-${row.security}`, row.security));
    if (row.system) space.append(el('span', 'muted sec-system', ` ${row.system}`));
    tr.append(space);

    tr.append(el('td', 'num', money(price)));

    // What choosing this one costs against the best on offer, which is the
    // number the single "best price" column never showed.
    const gap = detailView.buying ? (price - best) / best : (best - price) / best;
    tr.append(el('td', gap > 0.001 ? 'num outward' : 'num muted',
      gap > 0.001 ? `−${(gap * 100).toFixed(0)}%` : 'best'));

    const stock = el('td', 'num');
    if (scu > 0) {
      stock.append(el('span', scu < THIN_SCU ? 'outward' : null, `${scu.toLocaleString()} SCU`));
      if (scu < THIN_SCU) {
        stock.title = detailView.buying
          ? 'Thin stock — a full hold will not be filled here'
          : 'Small demand — this counter will not take a full hold';
      }
    } else {
      stock.append(el('span', 'muted', '—'));
    }
    tr.append(stock);

    tr.append(el('td', 'num muted', row.seenAt ? ago(row.seenAt) : '—'));
    table.append(tr);
  }

  cell.append(table);

  const shown = Math.min(rows.length, 40);
  const note = detailView.monitoredOnly
    ? `${shown} of ${all.length} counters — lawless space hidden.`
    : `${shown} of ${all.length} counters.`;

  cell.append(el('div', 'muted detail-note',
    `${note} Security is by system: Stanton is policed, Pyro and Nyx are not. `
    + 'Nothing in the game logs threat, so this is where a place is, not what happened there.'));
}

// What the two sources can each answer, said plainly. The install list is the
// counters UEX has actually seen a price at, which is a floor; the dataset
// lists the economy simulation's own facilities, priced or not. Showing the
// shorter list under the longer list's wording would read as a shrinking
// economy rather than a narrower source.
const MARKET_CAPTIONS = {
  install: 'Every commodity your game install names, with your own trading record '
    + 'against each. "Sellable at" counts the counters UEX has seen a price at, so it '
    + 'is a floor and it moves. Enable the community dataset in Settings to also see '
    + 'facilities nobody has priced yet, and to group commodities.',
  dataset: 'Every commodity the community dataset knows, with your own trading record '
    + 'against each. Sellable at counts facilities in the economy simulation itself, '
    + 'and show on map lights the ones the star map can place. Static availability, not '
    + 'live prices.',
};

function renderMarket() {
  $('#market-offer').hidden = marketEntries.length > 0;

  const caption = $('#market-caption');
  const source = marketEntries[0]?.source;
  if (caption && MARKET_CAPTIONS[source]) caption.textContent = MARKET_CAPTIONS[source];
  // Market deliberately combines the reference catalogue with what the pilot
  // actually sold. The chips make that join visible before a price-like count
  // is mistaken for an event the log recorded.
  setSourceMarks($('#market-data-sources'), source === 'install'
    ? ['install', 'logs']
    : source === 'dataset' ? ['community', 'logs'] : []);

  const term = ($('#market-search').value || '').trim().toLowerCase();
  const group = $('#market-group').value;
  const body = $('#market-table tbody');
  body.textContent = '';

  const rows = marketEntries.filter((e) =>
    (!group || e.groups.includes(group))
    && (!term
      || e.name.toLowerCase().includes(term)
      || e.groups.some((g) => g.toLowerCase().includes(term))));

  // Say how many matched, so picking a group visibly does something without
  // scrolling to the table to find out.
  const counter = $('#market-count');
  if (counter) {
    counter.textContent = marketEntries.length && (group || term)
      ? `${rows.length} of ${marketEntries.length}`
      : '';
  }

  if (!rows.length) {
    const tr = el('tr');
    const td = el('td', 'muted', marketEntries.length
      ? 'No commodities match that search.'
      : 'Enable UEX, or the community dataset, on the Settings page to fill this in.');
    td.colSpan = 8;
    tr.append(td);
    body.append(tr);
    return;
  }

  // The UEX column exists only while that integration is on.
  const anyUex = marketEntries.some((e) => e.uex);
  $('.uex-col').hidden = !anyUex;

  for (const entry of rows) {
    const tr = el('tr');

    // The name is the way in: one best price is an answer, and the rows behind
    // it are the choice.
    const nameCell = el('td');
    const opener = el('button', 'place-link commodity-open', entry.name);
    opener.title = 'Every counter that trades this, and what each one costs you';
    opener.addEventListener('click', () => toggleMarketDetail(entry, tr));
    nameCell.append(opener);

    // The row below answers "where"; the page answers "and what has it been
    // doing". Kept as a second control so the quick look stays one click.
    const drill = el('button', 'drill', '↗');
    drill.title = 'Open the full picture: price and demand over time';
    drill.setAttribute('aria-label', `Open ${entry.name} in full`);
    drill.addEventListener('click', () => openCommodity(entry.name));
    nameCell.append(drill);

    tr.append(nameCell);
    tr.append(el('td', 'muted', entry.groups.join(', ')));
    tr.append(el('td', 'num', entry.sold.length ? String(entry.sold.length) : '—'));
    tr.append(el('td', 'num', entry.bought.length ? String(entry.bought.length) : '—'));
    tr.append(el('td', 'num', entry.myScuSold ? entry.myScuSold.toLocaleString() : '—'));
    tr.append(el('td', 'num inward', entry.myRevenue ? money(entry.myRevenue) : '—'));

    if (anyUex) {
      const cell = el('td', 'num');
      if (entry.uex?.bestSell > 0) {
        cell.append(el('span', 'inward', money(entry.uex.bestSell)));

        // Against the 15-day average: is now a good moment to sell this?
        if (entry.uex.avgSell > 0) {
          const trend = ((entry.uex.bestSell - entry.uex.avgSell) / entry.uex.avgSell) * 100;
          if (Math.abs(trend) >= 1) {
            const arrow = el('span', trend > 0 ? 'inward' : 'outward',
              ` ${trend > 0 ? '▲' : '▼'}${Math.abs(trend).toFixed(0)}%`);
            arrow.title = `15-day average: ${money(entry.uex.avgSell)}/SCU`;
            cell.append(arrow);
          }
        }

        if (entry.uex.bestSellTerminal)
          cell.append(el('div', 'muted uex-terminal', entry.uex.bestSellTerminal));

        // How old the number is - the difference between a price and a rumour.
        // Ambers past three days, reds past two weeks.
        if (showPriceAge && entry.uex.seenAt) {
          const age = Date.now() - new Date(entry.uex.seenAt).getTime();
          const cls = age > 14 * 86400000 ? 'price-age stale'
            : age > 3 * 86400000 ? 'price-age old'
            : 'price-age';
          cell.append(el('div', cls, `seen ${ago(entry.uex.seenAt)}`));
        }
      } else {
        cell.textContent = '—';
      }
      tr.append(cell);
    }

    // Two map links, because "where is it" has two answers: where you can
    // sell what you hold, and where the shops stock it for buying.
    const actions = el('td', 'num map-links');

    const link = (label, query, title) => {
      const show = el('button', 'ghost', label);
      show.title = title;
      show.addEventListener('click', () => {
        $('#map-search').value = query;
        showView('map');
        drawMap();
      });
      actions.append(show);
    };

    if (entry.sold.length)
      link('sell on map', entry.name, 'Light every place that buys this from you');
    if (entry.bought.length)
      link('buy on map', `buy:${entry.name}`, 'Light every place that stocks this for sale');

    actions.append(trackButton(entry.name, 1, 'SCU'));
    tr.append(actions);

    body.append(tr);
  }
}

onInput('#market-search', renderMarket);
$('#market-group')?.addEventListener('change', renderMarket);

// The shortcut: re-fetch the whole UEX snapshot from right here.
$('#market-refresh')?.addEventListener('click', (e) =>
  uexAction('/api/uex/enable', $('#market-age'), e.currentTarget));

// The Settings switch for price ages, live on both pages at once.
const uexAgeToggle = $('#uex-age-toggle');
if (uexAgeToggle) {
  uexAgeToggle.checked = showPriceAge;
  uexAgeToggle.addEventListener('change', () => {
    showPriceAge = uexAgeToggle.checked;
    try { localStorage.setItem('qw-uex-age', showPriceAge ? '1' : '0'); } catch { /* fine */ }
    renderMarket();
  });
}

/**
 * Facility keys to search tokens the atlas can meet. The class name
 * DC_Stan_Hurston_S1_Farnesway carries exactly one atlas-matchable word;
 * everything else is scaffolding, listed here so it never becomes a token.
 */
const FACILITY_NOISE = new Set([
  'dc', 'outpost', 'reststop', 'landingzone', 'junksite', 'ugf', 'hangar',
  'spaceport', 'portolisar', 'inhabited', 'planet', 'distributioncentre',
  'stan', 'stanton', 'pyro', 'nyx', 'outlaw', 'sublocation',
  'hurston', 'microtech', 'crusader', 'arccorp',
  'admin', 'gate', 'habs', 'medical', 'metrostation', 'store', 'lobby',
]);

function facilityTokens(keys) {
  const tokens = new Set();

  for (const key of keys) {
    for (const part of key.split('_')) {
      const compact = part.toLowerCase().replace(/[^a-z0-9]/g, '');
      if (compact.length >= 4 && !FACILITY_NOISE.has(compact) && !/^s\d+$/.test(compact))
        tokens.add(compact);
    }
  }

  return tokens;
}

/**
 * If the map search term names a commodity, the nodes to light are the ones
 * whose name matches a facility token for that commodity. Null when the term
 * is not a commodity, in which case the search means places, as it always did.
 *
 * A "buy:" prefix flips the question - where the commodity is stocked for
 * buying, rather than where it can be sold. The Market page's two map links
 * write both forms into the search box, so they survive as shareable ?q= urls.
 */
/**
 * The commodity a typed term means.
 *
 * Exact names only was too strict to use: "medical" found nothing because the
 * commodity is "Medical Supplies", and nothing on the map offered the full
 * name, so the search looked broken. A prefix or a contained word now counts,
 * shortest name first so "gold" means Gold rather than Golden Medmon - but
 * only when no place answers to the same term, since a typed place name
 * should still find the place.
 */
function matchCommodity(name) {
  const lower = name.trim().toLowerCase();
  if (!lower) return null;

  const exact = marketEntries.find((e) => e.name.toLowerCase() === lower);
  if (exact) return exact;

  if (atlas.some((l) => l.name.toLowerCase().includes(lower)))
    return null;

  const byLength = (a, b) => a.name.length - b.name.length;

  return marketEntries.filter((e) => e.name.toLowerCase().startsWith(lower)).sort(byLength)[0]
    ?? marketEntries.filter((e) => e.name.toLowerCase().includes(lower)).sort(byLength)[0]
    ?? null;
}

function commoditySites(term) {
  const buying = term.startsWith('buy:');
  const entry = matchCommodity(buying ? term.slice(4) : term);
  if (!entry) return null;

  const keys = buying ? entry.bought : entry.sold;
  return keys.length ? facilityTokens(keys) : null;
}

/* ---------- loot ---------- */

async function loadLoot() {
  const days = Number($('#loot-period').value) || 0;
  renderLoot(await getJson(`/api/loot?days=${days}`));
}

/**
 * Fills a filter with what the rows actually contain.
 *
 * Only what is there, rather than every category the classifier knows: a
 * dropdown offering "Containers" on an install that has never seen one is a
 * filter that can only disappoint. The chosen value is kept across a redraw
 * when it still exists, and quietly falls back to everything when it does not -
 * which happens when the date window moves and takes the last of something
 * with it.
 */
function fillLootFilter(select, all, label) {
  if (!select) return '';

  const chosen = select.value;
  const values = [...new Set(all.filter(Boolean))].sort((a, b) => a.localeCompare(b));

  select.textContent = '';

  const any = document.createElement('option');
  any.value = '';
  any.textContent = label;
  select.append(any);

  for (const value of values) {
    const option = document.createElement('option');
    option.value = value;
    option.textContent = value;
    select.append(option);
  }

  select.value = values.includes(chosen) ? chosen : '';
  return select.value;
}

/**
 * What an item usually costs, or an explanation of why it does not say.
 *
 * A blank cell would read as "worthless" and a zero as "free", and neither is
 * what an unpriced row means: UEX reports 64 of this install's 109 looted item
 * classes, and the rest are simply not sold anywhere it can see. So the gap
 * gets a dash and a reason rather than a number nobody should act on.
 */
function lootPriceCell(pickup) {
  if (!(pickup.price > 0)) {
    const td = el('td', 'num muted', '—');
    td.title = 'No terminal UEX knows about stocks this, so it has no price to report.';
    return td;
  }

  return el('td', 'num', money(pickup.price));
}

function renderLoot(pickups) {
  const term = ($('#loot-search').value || '').trim().toLowerCase();

  // Built from everything the window holds, not from what survives the other
  // filters - or choosing a kind would empty the place list and strand you.
  const kind = fillLootFilter($('#loot-kind'), pickups.map((p) => p.category), 'Any kind');
  const place = fillLootFilter($('#loot-place'), pickups.map((p) => p.place), 'Anywhere');

  const rows = pickups.filter((p) =>
    (!term || p.item.toLowerCase().includes(term) || p.place.toLowerCase().includes(term))
    && (!kind || p.category === kind)
    && (!place || p.place === place));

  tiles('#loot-summary', [
    ['New items', rows.length],
    ['Last 7 days', rows.filter((p) => Date.now() - new Date(p.at).getTime() < 7 * 86400000).length],
    ['Places', new Set(rows.map((p) => p.place)).size],

    // What share carries a price, rather than a total: these are first
    // sightings, so summing them would value a wardrobe nobody owns twice over.
    ['Priced', `${rows.filter((p) => p.price > 0).length} of ${rows.length}`],
  ]);

  const body = $('#loot-table tbody');
  body.textContent = '';

  if (!rows.length) {
    const tr = el('tr');

    // Name the filter that emptied it. "Nothing in that range" is the wrong
    // explanation for a table a dropdown hid every row from.
    const td = el('td', 'muted', kind || place
      ? `Nothing matching ${[kind, place].filter(Boolean).join(' at ')} in that range.`
      : 'Nothing in that range.');

    td.colSpan = 5;
    tr.append(td);
    body.append(tr);
    lastLootRows = pickups;
    return;
  }

  for (const pickup of rows) {
    const tr = el('tr');
    tr.append(el('td', null, dateOf(pickup.at)));
    tr.append(el('td', null, prettyItem(pickup.item)));
    tr.append(el('td', 'muted', pickup.category));
    tr.append(lootPriceCell(pickup));
    tr.append(tdPlace(pickup.place, 'muted'));
    body.append(tr);
  }

  lastLootRows = pickups;
}

let lastLootRows = [];

onInput('#loot-search', () => renderLoot(lastLootRows));
onInput('#loot-period', loadLoot);

// The two filters redraw what is already loaded; only the date window refetches.
$('#loot-kind')?.addEventListener('change', () => renderLoot(lastLootRows));
$('#loot-place')?.addEventListener('change', () => renderLoot(lastLootRows));

/* ---------- reference catalogues: ships, parts ---------- */

let shipCatalogue = [];
let partCatalogue = [];

async function loadShipsRef() {
  try {
    shipCatalogue = await getJson('/api/reference/ships');
  } catch {
    shipCatalogue = [];
  }

  const careers = [...new Set(shipCatalogue.map((s) => s.career).filter(Boolean))].sort();
  const select = $('#ships-career');
  const previous = select.value;

  select.textContent = '';
  select.append(new Option('All careers', ''));
  for (const career of careers) select.append(new Option(career, career));
  if (careers.includes(previous)) select.value = previous;

  renderShipsRef();
}

function renderShipsRef() {
  const term = ($('#ships-search').value || '').trim().toLowerCase();
  const career = $('#ships-career').value;
  const body = $('#ships-table tbody');
  body.textContent = '';

  const rows = shipCatalogue.filter((s) =>
    (!career || s.career === career)
    && (!term || s.name.toLowerCase().includes(term)
      || (s.role || '').toLowerCase().includes(term)));

  if (!rows.length) {
    const tr = el('tr');
    const td = el('td', 'muted', shipCatalogue.length
      ? 'No ships match that filter.'
      : 'Enable the community dataset on the Settings page to fill this in.');
    td.colSpan = 14;
    tr.append(td);
    body.append(tr);
    return;
  }

  for (const ship of rows) {
    const tr = el('tr');
    const name = el('td', null, ship.name);
    if (!ship.isSpaceship) name.append(el('span', 'note-inline', ' · ground'));
    tr.append(name);

    tr.append(el('td', 'muted', ship.career ?? '—'));
    tr.append(el('td', 'muted', ship.role ?? '—'));
    tr.append(el('td', 'num', ship.crew > 0 ? String(ship.crew) : '—'));

    // The spec sheet: zeros mean a cache digested before the fields existed,
    // shown as dashes rather than lies.
    tr.append(el('td', 'num', ship.cargoScu > 0 ? `${ship.cargoScu} SCU` : '—'));
    tr.append(el('td', 'num muted', ship.scmSpeed > 0
      ? `${Math.round(ship.scmSpeed)} / ${Math.round(ship.maxSpeed)}`
      : '—'));
    tr.append(el('td', 'num muted', ship.shieldHp > 0 ? ship.shieldHp.toLocaleString() : '—'));
    tr.append(el('td', 'num muted', ship.health > 0 ? ship.health.toLocaleString() : '—'));

    tr.append(el('td', 'num muted', ship.expeditedCost > 0 ? money(ship.expeditedCost) : '—'));
    tr.append(el('td', 'num muted', ship.standardClaimTime > 0 ? `~${Math.round(ship.standardClaimTime)}m` : '—'));
    // Every shop and every rental desk sit on the hover, cheapest first: the
    // cheapest is the number, but the nearest is usually the one wanted.
    const shops = ship.shops || [];
    const buy = el('td', ship.price ? 'num' : 'num muted', ship.price ? money(ship.price.price) : 'not sold');
    const where = el('td', 'muted', ship.price?.terminal ?? '—');
    if (shops.length > 1) where.append(el('span', 'note-inline', ` +${shops.length - 1}`));
    if (shops.length) buy.title = where.title = placeList('Sold at', shops);
    tr.append(buy, where);

    // Rentals only exist when that feed is on; otherwise the column is dashes.
    const rentals = ship.rentals || [];
    const rent = el('td', ship.rental ? 'num' : 'num muted',
      ship.rental ? money(ship.rental.price) : '—');
    if (ship.rental) {
      rent.title = placeList('Rents at', rentals.length ? rentals : [ship.rental]);
      if (rentals.length > 1) rent.append(el('span', 'note-inline', ` +${rentals.length - 1}`));
    }
    tr.append(rent);

    body.append(tr);
  }
}

/** A hover list of places and prices, one a line, cheapest first as given. */
function placeList(heading, places) {
  return `${heading} (${places.length}):\n${places.map((p) => `${p.terminal} — ${money(p.price)}`).join('\n')}`;
}

async function loadPartsRef() {
  try {
    partCatalogue = await getJson('/api/reference/items');
  } catch {
    partCatalogue = [];
  }

  const types = [...new Set(partCatalogue.map((p) => p.type).filter(Boolean))].sort();
  const select = $('#parts-type');
  const previous = select.value;

  select.textContent = '';
  select.append(new Option('All types', ''));
  for (const type of types) select.append(new Option(prettyType(type), type));
  if (types.includes(previous)) select.value = previous;

  // The two sources agree item for item, so the caption says which is answering
  // rather than warning about a difference there is not one of. What does
  // change is the size of the list: the install describes more than twice what
  // the download does, and a reader comparing counts deserves to know why.
  const caption = $('#parts-caption');
  if (caption && partCatalogue.length) {
    caption.textContent = partCatalogue[0].source === 'install'
      ? `${partCatalogue.length.toLocaleString()} ship components and pieces of personal gear, `
        + `read from your game install with type, size, grade and maker, and UEX in-game `
        + `prices where a shop stocks one.`
      : `Every ship component and piece of personal gear in the community digest, with type, `
        + `size, grade and maker, and UEX in-game prices where a shop stocks one.`;
  }

  renderPartsRef();
}

/**
 * A component grade as the game writes it: A, B, C, D.
 *
 * The files store an ordinal and the game shows a letter, so a page printing
 * the ordinal is asking the reader to know a mapping nobody published. "G3"
 * beside "S2" reads like a second size, and gives no clue that lower is better.
 *
 * The mapping was checked rather than assumed: the AEGS coolers come out 1, 2,
 * 3, 4 exactly where StarStrings independently calls them A, B, C and D. Only
 * those four are translated. A handful of items carry 5 and above, which is
 * outside anything the game shows, so those keep their number instead of being
 * given a letter that means nothing.
 */
function gradeLetter(grade) {
  const n = Number(grade) || 0;
  if (n < 1) return '—';
  return n <= 4 ? 'ABCD'[n - 1] : String(n);
}

/** "Char_Clothing_Hat" -> "Clothing Hat": the digest's type keys, made legible. */
const prettyType = (type) => (type ? type.replace(/^Char_/, '').replace(/_/g, ' ') : '—');

/** The digest holds thousands of items; rendering caps so the page stays quick. */
const PARTS_CAP = 500;

function renderPartsRef() {
  const term = ($('#parts-search').value || '').trim().toLowerCase();
  const type = $('#parts-type').value;
  const body = $('#parts-table tbody');
  body.textContent = '';

  const rows = partCatalogue.filter((p) =>
    (!type || p.type === type)
    && (!term
      || p.className.toLowerCase().includes(term)
      || (p.name || '').toLowerCase().includes(term)
      || prettyItem(p.className).toLowerCase().includes(term)
      || (p.manufacturer || '').toLowerCase().includes(term)))

    // Priced items first: the ones a shop actually stocks are the ones worth
    // reading about; header sorting still reorders freely.
    .sort((a, b) => Number(Boolean(b.price)) - Number(Boolean(a.price))
      || a.className.localeCompare(b.className));

  const counter = $('#parts-count');
  counter.textContent = rows.length > PARTS_CAP
    ? `Showing ${PARTS_CAP.toLocaleString()} of ${rows.length.toLocaleString()} matches — refine the search or pick a type.`
    : '';

  if (!rows.length) {
    const tr = el('tr');
    const td = el('td', 'muted', partCatalogue.length
      ? 'Nothing matches that filter.'
      : gameDataExcuse() || 'No parts were found in your game files.');
    td.colSpan = 9;
    tr.append(td);
    body.append(tr);
    return;
  }

  for (const part of rows.slice(0, PARTS_CAP)) {
    const tr = el('tr');

    // The localised name when the data carries one; my class-name
    // prettification is the fallback, not the headline. The track button
    // shares the cell rather than claiming a tenth column.
    const shown = part.name || prettyItem(part.className);
    const label = el('td', 'with-track');

    // Every part has a card now - what it is, whether it is already yours, what
    // it costs and where - so the name always opens one, where it used to open
    // only for the items the game happened to write a paragraph about.
    const open = el('button', 'place-link commodity-open', shown);
    open.title = 'What Quantum Wake knows about this';
    open.addEventListener('click', () => openEntity('part', part.className));
    label.append(open);

    label.append(trackButton(shown));
    if (part.name) label.title = part.className;
    tr.append(label);
    tr.append(el('td', 'muted', prettyType(part.type)));
    // An item with no sub-type arrives as an empty string from the install and
    // as null from the download, and both mean the same nothing.
    tr.append(el('td', 'muted', part.subType || '—'));
    tr.append(el('td', 'num', part.size > 0 ? String(part.size) : '—'));
    tr.append(el('td', 'num', gradeLetter(part.grade)));
    tr.append(el('td', 'muted', part.manufacturer ?? '—'));
    tr.append(el('td', part.price ? 'num' : 'num muted', part.price ? money(part.price) : '—'));

    // Where a part is actually stocked; the full shop list rides the tooltip.
    const stocked = el('td', 'num muted', part.stockedAt > 0 ? String(part.stockedAt) : '—');
    if (part.terminals?.length) stocked.title = part.terminals.join('\n');
    tr.append(stocked);
    tr.append(el('td', 'muted', part.cheapestAt ?? '—'));

    body.append(tr);
  }
}

/**
 * The game's own paragraph about an item, and its own labels for it.
 *
 * Opened rather than shown inline because 9,401 of the 26,028 items carry one
 * and they run to several lines. The tags are the game's, not ours: flightReady
 * is how it marks what has actually shipped, which is worth seeing beside a
 * price for something you cannot buy yet.
 */
/**
 * Room taken, from millionths of an SCU into something readable.
 *
 * A pistol is a few thousand of these and a ship component is millions, so one
 * unit cannot serve both without printing either 0.000004 SCU or 12,000,000.
 */
function volume(microScu) {
  if (microScu >= 1e6) return `${(microScu / 1e6).toFixed(microScu >= 1e7 ? 0 : 2)} SCU`;
  if (microScu >= 1e4) return `${(microScu / 1e4).toFixed(1)} centiSCU`;
  return `${microScu.toLocaleString()} µSCU`;
}

onInput('#ships-search', renderShipsRef);
$('#ships-career')?.addEventListener('change', renderShipsRef);
onInput('#parts-search', renderPartsRef);
$('#parts-type')?.addEventListener('change', renderPartsRef);

/* ---------- mining and salvage spawns ---------- */

let miningCatalogue = [];

/**
 * What a SCU of a rock is worth once it is sold.
 *
 * The middle of the ore range times the best price anything pays. Deliberately
 * the middle rather than the top: ice runs 9.7% to 84.3% depending on the rock,
 * and quoting the ceiling would rank every wide band above every reliable one.
 *
 * There is no per-hour version of this, and there cannot be one from here -
 * nothing in the logs says how long a rock takes to mine. Respawn is how long
 * it takes to come back, which is a different question and has its own column.
 */
function oreWorth(spawn) {
  if (!spawn.bestSell || spawn.minPercent == null || spawn.maxPercent == null) return null;

  const middle = (spawn.minPercent + spawn.maxPercent) / 2;
  return middle > 0 ? (middle / 100) * spawn.bestSell : null;
}

const KIND_LABELS = {
  mineable: 'Mineable',
  cave_harvestable: 'Cave harvestable',
  harvestable: 'Harvestable',
  salvageable: 'Salvageable',
};

/**
 * Ore sold that was never bought.
 *
 * The logs record no mining whatsoever - no extraction, no scan, no refinery
 * job - so this is the only trace that something was dug up rather than hauled.
 * It is an inference and the note says so: buying somewhere the app never read
 * a log for would look exactly the same.
 */
/**
 * Where the rocks are rich, and what one is worth when you find it.
 *
 * Rich and valuable are different questions and both are answered: a place can
 * be full of ore nobody pays for, or hold a trace of something precious. Per
 * rock multiplies them out, and is per rock rather than per hour because
 * nothing says how long a rock takes to mine.
 */
/**
 * The mining record the pilot keeps, because the game keeps none.
 *
 * Kept visibly apart from everything else on the page. The figures above are
 * read from logs and can be checked; these are typed from memory, and adding
 * the two together would make one number out of two different kinds of claim.
 */
/**
 * What a haul is waiting on, and what to press next.
 *
 * Stage is the server's word; these are the reader's. "Ready" in particular
 * needs saying carefully - the app has not been told the job finished, it has
 * only noticed that the time the pilot expected has gone by.
 */
const MINING_STAGE = {
  Extracted: ['In your hold', 'Send to a refinery'],
  Submitted: ['At a refinery', 'Collect it'],
  Ready: ['Due back by now', 'Collect it'],
  Collected: ['Back in your hold', 'Record what it sold for'],
  Sold: ['Sold', null],
};

/**
 * The nine refining methods as UEX rates them - the game's own three-point
 * pips for yield, cost and speed - so a run can be read against the method
 * it went in under. The percentages behind the pips are the server's and
 * are in no file or feed this app reads, which the note says.
 */
function renderMiningMethods() {
  const box = $('#mining-methods');
  const body = $('#mining-methods-table tbody');
  if (!box || !body) return;
  const methods = crackModel?.methods || [];
  box.hidden = !crackModel?.methodsKnown || methods.length === 0;
  if (box.hidden) return;
  body.textContent = '';
  const pips = (n) => '●'.repeat(Math.max(0, Math.min(3, n))) + '○'.repeat(3 - Math.max(0, Math.min(3, n)));
  for (const m of [...methods].sort((a, b) => b.yieldRating - a.yieldRating || a.costRating - b.costRating || a.name.localeCompare(b.name))) {
    const tr = el('tr');
    tr.append(el('td', null, m.name));
    tr.append(el('td', 'muted', m.code));
    tr.append(el('td', 'num', pips(m.yieldRating)));
    tr.append(el('td', 'num', pips(m.costRating)));
    tr.append(el('td', 'num', pips(m.speedRating)));
    body.append(tr);
  }
  $('#mining-methods-note').textContent = 'UEX’s ratings, which are the game’s own pips: three is the most yield, the dearest, the fastest. The percentages behind them are the server’s - the install names the nine methods and nothing more, and no feed carries them - so a run’s estimate above is before the method.';
}

async function loadMiningPending() {
  const panel = $('#mining-pending');
  if (!panel) return;

  const waiting = await getJson('/api/mining/pending').catch(() => null);
  miningPendingJobs = waiting;
  renderMiningWorkspaceHeader();

  if (!waiting) {
    panel.hidden = true;
    return;
  }

  panel.hidden = waiting.length === 0;
  if (!waiting.length) return;

  $('#mining-pending-note').textContent = waiting[0].caveat;

  const list = $('#mining-pending-list');
  list.textContent = '';

  for (const run of waiting) {
    const row = el('div', 'mining-waiting');

    row.append(el('span', 'name', `${run.scu} SCU ${run.resource}`));
    row.append(el('span', 'muted', run.refinery.place || 'Refinery not named'));

    // The two states read differently on purpose: one is waiting, the other is
    // the app pointing out that your own estimate has passed.
    row.append(el('span', `${run.stage === 'Ready' ? 'want' : 'muted'} mining-waiting-time`,
      run.refinery.expectedAt
        ? (run.stage === 'Ready'
          ? `you expected it by ${dateOf(run.refinery.expectedAt)}`
          : `due ${dateOf(run.refinery.expectedAt)}`)
        : 'no time given'));

    const detail = [
      run.refinery.method ? `Method · ${run.refinery.method}` : null,
      run.refinery.cost != null ? `Job cost · ${money(run.refinery.cost)}` : null,
    ].filter(Boolean).join(' · ');
    if (detail) row.append(el('span', 'mining-waiting-detail', detail));

    // What it might come back as - a ceiling, and said as one: the SCU that
    // went in at UEX's best refined price, the station's bonus on top where
    // the yields feed reports one, before the method's own yield and the
    // refinery's charge, neither of which is published anywhere.
    const e = run.estimate;
    if (e) {
      const method = run.method
        ? ` under ${run.method.name} (yield ${run.method.yieldRating}/3, cost ${run.method.costRating}/3, speed ${run.method.speedRating}/3)`
        : (run.refinery.method ? ` under ${run.refinery.method}` : '');
      const bonus = e.bonusPercent != null
        ? `, ${e.bonusPercent >= 0 ? '+' : ''}${e.bonusPercent} % station bonus at ${e.bonusAt} makes ${fmtInt(e.withBonus)}`
        : e.bonusKnown ? ', no station bonus reported for this ore here' : '';
      row.append(el('span', 'muted small mining-estimate',
        `≤ ${fmtInt(e.gross)} aUEC at ${fmtInt(e.perScu)}/SCU refined${e.sellAt ? ` (${e.sellAt})` : ''}${bonus}${method} — before the method’s own yield and the fee, which nobody publishes`));
    }

    list.append(row);
  }
}

/**
 * The inline form for whichever stage comes next.
 *
 * A row rather than a dialog: a browser prompt blocks everything, and the
 * overlay's WebView is the worst place in the app to find that out.
 */
function miningStageForm(run) {
  const row = el('tr', 'mining-stage-form');
  const cell = el('td');
  cell.colSpan = 9;

  const form = el('div', 'mining-form');
  const inputs = {};

  function field(key, label, placeholder, type = 'text') {
    const wrap = el('label', 'mining-stage-field');
    wrap.append(el('span', null, label));
    const input = el('input', 'search');
    input.type = type;
    input.placeholder = placeholder;
    if (type === 'number') input.step = 'any';
    inputs[key] = input;
    wrap.append(input);
    form.append(wrap);
    return input;
  }

  if (run.stage === 'Extracted') {
    field('place', 'Refinery', 'e.g. ArcCorp 141');
    field('method', 'Method (optional)', 'e.g. Dinyx Solventation');
    field('cost', 'Job cost (optional)', 'aUEC', 'number');
    field('expectedAt', 'Expected ready time (optional)', 'yyyy-mm-dd hh:mm');
  } else if (run.stage === 'Submitted' || run.stage === 'Ready') {
    field('yield', 'SCU that came back', 'e.g. 24', 'number');
  } else if (run.stage === 'Collected') {
    field('revenue', 'Sold for', 'aUEC', 'number');
  }

  const save = el('button', 'ghost', 'Save');

  save.addEventListener('click', async () => {
    if (run.stage === 'Extracted') {
      const when = inputs.expectedAt.value.trim();
      const expected = when ? new Date(when.replace(' ', 'T')) : null;

      await fetch(`/api/mining/log/${encodeURIComponent(run.id)}/submit`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          place: inputs.place.value.trim(),
          method: inputs.method.value.trim(),
          cost: inputs.cost.value === '' ? null : Number(inputs.cost.value),

          // An unreadable date is sent as nothing rather than as now: a job
          // with no expected time never claims to be ready, which is the
          // honest state when nobody has said when it is due.
          expectedAt: expected && !isNaN(expected) ? expected.toISOString() : null,
        }),
      });
    } else if (run.stage === 'Collected') {
      const value = inputs.revenue.value.trim();
      await fetch(`/api/mining/log/${encodeURIComponent(run.id)}/sell`
        + (value === '' ? '' : `?revenue=${encodeURIComponent(value)}`), { method: 'POST' });
    } else {
      const value = inputs.yield.value.trim();
      await fetch(`/api/mining/log/${encodeURIComponent(run.id)}/collect`
        + (value === '' ? '' : `?yield=${encodeURIComponent(value)}`), { method: 'POST' });
    }

    await loadMiningLog().catch(() => {});
    await loadMiningPending().catch(() => {});
  });

  form.append(save);
  cell.append(form);
  row.append(cell);
  return row;
}

async function loadMiningLog() {
  loadMiningPending().catch(() => {});

  const body = $('#mining-log tbody');
  const note = $('#mining-log-note');
  if (!body) return;

  const runs = await getJson('/api/mining/log').catch(() => []);
  body.textContent = '';

  if (!runs.length) {
    note.textContent = 'Nothing recorded yet.';
    return;
  }

  for (const run of runs) {
    const tr = el('tr');
    tr.append(el('td', 'muted', dayOf(run.at)));
    tr.append(el('td', null, run.resource));
    tr.append(el('td', 'muted', run.place));
    tr.append(el('td', 'num', String(run.scu)));

    // What went in stays beside what came back: the difference is the number
    // worth knowing, and a single column would hide it.
    tr.append(el('td', 'num muted',
      run.refinery?.yield === null || run.refinery?.yield === undefined
        ? '—'
        : String(run.refinery.yield)));

    tr.append(el('td', 'num muted', run.quality ? String(run.quality) : '—'));
    tr.append(el('td', run.revenue ? 'num inward' : 'num muted',
      run.revenue ? money(run.revenue) : '—'));

    const [words, next] = MINING_STAGE[run.stage] || [run.stage, null];

    const stage = el('td', run.stage === 'Ready' ? 'want' : 'muted', words);
    tr.append(stage);

    const step = el('td');

    if (next) {
      let form = null;
      const advance = el('button', 'ghost small', next);

      advance.addEventListener('click', () => {
        // Toggling rather than stacking: pressing it twice should close the
        // form, not leave two of them arguing over the same haul. The open one
        // is held here rather than found by walking siblings, which is both
        // shorter and does not care what else the table inserts.
        if (form) {
          form.remove();
          form = null;
          return;
        }

        form = miningStageForm(run);
        tr.after(form);
      });

      step.append(advance);
    }

    tr.append(step);

    const drop = el('td', 'num');
    const remove = el('button', 'ghost small', 'Remove');
    remove.addEventListener('click', async () => {
      await fetch(`/api/mining/log/${run.id}`, { method: 'DELETE' }).catch(() => {});
      await loadMiningLog().catch(() => {});
    });
    drop.append(remove);
    tr.append(drop);

    body.append(tr);
  }

  const scu = runs.reduce((sum, r) => sum + r.scu, 0);
  const earned = runs.reduce((sum, r) => sum + (r.revenue || 0), 0);

  const waiting = runs.filter((r) => r.stage === 'Submitted' || r.stage === 'Ready').length;

  note.textContent = `${runs.length} run${runs.length === 1 ? '' : 's'}, `
    + `${scu.toLocaleString()} SCU`
    + (earned > 0 ? `, ${money(earned)}` : '')
    + (waiting > 0 ? `, ${waiting} still at a refinery` : '')
    + ' — your own record, kept apart from the log-derived figures above.';
}

$('#mining-log-form')?.addEventListener('submit', async (e) => {
  e.preventDefault();

  const body = {
    resource: $('#mining-log-resource').value.trim(),
    place: $('#mining-log-place').value.trim(),
    scu: Number($('#mining-log-scu').value) || 0,
    quality: Number($('#mining-log-quality').value) || null,
    revenue: Number($('#mining-log-revenue').value) || null,
  };

  if (!body.resource || body.scu <= 0) return;

  await fetch('/api/mining/log', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  }).catch(() => {});

  for (const id of ['#mining-log-resource', '#mining-log-place', '#mining-log-scu',
    '#mining-log-quality', '#mining-log-revenue']) {
    $(id).value = '';
  }

  await loadMiningLog().catch(() => {});
});

/* ---------- salvage: the equipment and the rules, not the wreck ---------- */

let salvageModel = null;

/**
 * The salvage pane: each salvage hull's controller, the scraper modules and
 * heads, priced by UEX. What a hull is worth scraped is not here and the
 * brief says why; nothing on this pane is derived from a wreck.
 */
async function loadSalvage() {
  const unready = $('#salvage-unready');
  if (!$('#mining-pane-salvage')) return;
  try {
    salvageModel = await getJson('/api/salvage/model');
  } catch {
    salvageModel = null;
  }
  const tables = ['#salvage-ships', '#salvage-modules', '#salvage-heads'].map((id) => $(id));
  if (!salvageModel?.ready) {
    if (unready) {
      unready.hidden = false;
      unready.textContent = gameDataExcuse() || 'The install has not been read yet - Settings says when the game data is ready.';
    }
    for (const t of tables) if (t) t.hidden = true;
    return;
  }
  if (unready) unready.hidden = true;
  for (const t of tables) if (t) t.hidden = false;

  const price = (market) => market?.price ? `${fmtInt(market.price)} aUEC` : '—';
  const where = (market) => {
    const best = market?.shops?.[0];
    if (!best) return salvageModel.itemPricesKnown ? 'no terminal recorded' : 'prices need UEX (Settings)';
    const place = best.place && !best.terminal.toLowerCase().includes(best.place.toLowerCase()) ? `, ${best.place}` : '';
    return `${best.terminal}${place}${market.shops.length > 1 ? ` +${market.shops.length - 1}` : ''}`;
  };

  const ships = $('#salvage-ships tbody');
  ships.textContent = '';
  for (const s of salvageModel.ships || []) {
    const tr = el('tr');
    const name = el('td', null, s.name);
    if (s.flown) name.append(el('span', 'chip count', ' flown'));
    tr.append(name);
    tr.append(el('td', 'num', String(s.heads)));
    tr.append(el('td', null, s.scrapesTo || '—'));
    tr.append(el('td', 'num', s.scuPerCubicMetre > 0 ? `${s.scuPerCubicMetre} SCU/m³ of ${s.disintegratesTo}` : '—'));
    tr.append(el('td', 'num', s.hold > 0 ? `${fmt1(s.hold)} SCU` : (salvageModel.holdsKnown ? '—' : 'needs the dataset')));
    tr.append(el('td', 'num', s.fullHoldOfScrape ? `${fmtInt(s.fullHoldOfScrape)} aUEC` : '—'));
    const cm = el('td', 'num', s.fullHoldOfPieces ? `${fmtInt(s.fullHoldOfPieces)} aUEC` : '—');
    if (s.pieces && s.disintegratesTo && s.pieces.commodity !== s.disintegratesTo) cm.title = `UEX prices ${s.disintegratesTo} as ${s.pieces.commodity}`;
    tr.append(cm);
    ships.append(tr);
  }
  const first = (salvageModel.ships || []).find((s) => s.scrape);
  const firstCm = (salvageModel.ships || []).find((s) => s.pieces);
  $('#salvage-ships-note').textContent = [
    first ? `RMC at UEX's best sell: ${fmtInt(first.scrape.perScu)} aUEC a SCU at ${first.scrape.at}.` : (salvageModel.itemPricesKnown ? 'UEX has no price for RMC.' : 'Prices need UEX, in Settings.'),
    firstCm ? `Construction material: ${fmtInt(firstCm.pieces.perScu)} a SCU at ${firstCm.pieces.at}; the game's Construction Salvage, Rubble and Pieces are sold as that one commodity.` : '',
    'A full hold is a ceiling on a trip, before the fuel and before the finding.',
  ].filter(Boolean).join(' ');

  const modules = $('#salvage-modules tbody');
  modules.textContent = '';
  for (const m of [...(salvageModel.modules || [])].sort((a, b) => b.radius - a.radius)) {
    const tr = el('tr');
    const name = el('td', null, m.name);
    if (m.manufacturer) name.append(el('div', 'armoury-kind', m.manufacturer));
    tr.append(name);
    tr.append(el('td', 'num', String(m.speed)));
    tr.append(el('td', 'num', `${m.radius} m`));
    tr.append(el('td', 'num', `${Math.round(m.efficiency * 100)}%`));
    tr.append(el('td', 'num', price(m.market)));
    tr.append(el('td', 'muted', where(m.market)));
    modules.append(tr);
  }

  const heads = $('#salvage-heads tbody');
  heads.textContent = '';
  for (const h of salvageModel.heads || []) {
    const tr = el('tr');
    tr.append(el('td', null, h.name));
    tr.append(el('td', 'num', String(h.slots)));
    tr.append(el('td', 'num', price(h.market)));
    tr.append(el('td', 'muted', where(h.market)));
    heads.append(tr);
  }

  const k = salvageModel.constants;
  $('#salvage-note').textContent = `${k ? `The game's rule: a beam takes ${Math.round(k.hullThicknessMetres * 1000)} mm of hull, with a material factor of ${k.ammoToMaterialFactor}. ` : ''}${salvageModel.perHull}`;
  renderMiningWorkspaceHeader();
}

/* ---------- the Mining page's four panes ---------- */

/**
 * Prospecting, mining fit, haul and refinery, salvage: four questions that
 * had grown into one long page. The pane is remembered in this browser, and the
 * deposit filters in the header belong to the first alone.
 */
const MINING_PANES = ['go', 'crack', 'runs', 'salvage'];
let miningPane = 'go';
let miningReferenceMatches = null;
let miningPendingJobs = null;
let miningFitStatus = 'Fit data has not been read yet.';
try {
  const kept = localStorage.getItem('qw-mining-pane');
  if (MINING_PANES.includes(kept)) miningPane = kept;
} catch { /* private browsing keeps the default */ }

function showMiningPane(name) {
  if (!MINING_PANES.includes(name)) name = 'go';
  miningPane = name;
  try { localStorage.setItem('qw-mining-pane', name); } catch { /* as above */ }

  for (const id of ['#mining-pane-go', '#mining-pane-crack', '#mining-pane-runs', '#mining-pane-salvage']) {
    const pane = $(id);
    if (pane) pane.classList.toggle('active', id === `#mining-pane-${name}`);
  }
  for (const button of $('#mining-tabs')?.querySelectorAll('button') || [])
    button.classList.toggle('active', button.dataset.pane === name);

  // The kind, system and search filters shape the deposit tables and nothing else.
  for (const id of ['#mining-kind', '#mining-system', '#mining-search']) {
    const control = $(id);
    if (control) control.hidden = name !== 'go';
  }
  renderMiningWorkspaceHeader();
}

/* The header is the page's one stable piece of chrome. Let it name the job the
   current pane performs and report only a count or fit the pane already owns. */
function renderMiningWorkspaceHeader() {
  const heading = $('#mining-workspace-title');
  const status = $('#mining-workspace-status');
  const bar = $('#view-mining .section-bar');
  if (!heading || !status || !bar) return;

  if (miningPane === 'crack') {
    heading.textContent = 'Mining fit';
    bar.dataset.workspace = 'MINING FIT';
    bar.dataset.workspaceIcon = 'fit';
    status.textContent = miningFitStatus;
    return;
  }

  if (miningPane === 'runs') {
    heading.textContent = 'Haul & refinery';
    bar.dataset.workspace = 'HAUL // REFINERY';
    bar.dataset.workspaceIcon = '';
    if (miningPendingJobs === null) status.textContent = 'Refinery job status is unavailable.';
    else status.textContent = miningPendingJobs.length
      ? `${miningPendingJobs.length} refinery job${miningPendingJobs.length === 1 ? '' : 's'} await your update.`
      : 'No refinery jobs await your update.';
    return;
  }

  const count = (n, noun) => `${n} ${noun}${n === 1 ? '' : 's'}`;

  // Both lines of work reached the header in the same release: the salvage
  // pane arrived on one and the workspace header on the other, and without
  // this the wrecks page calls itself Prospecting.
  if (miningPane === 'salvage') {
    heading.textContent = 'Salvage';
    bar.dataset.workspace = 'SALVAGE';
    bar.dataset.workspaceIcon = '';
    status.textContent = salvageModel?.ready
      ? `${count(salvageModel.ships?.length ?? 0, 'salvage hull')}, ${count(salvageModel.modules?.length ?? 0, 'scraper module')}, from the install.`
      : 'Hulls, scrapers and heads, as far as the game files go.';
    return;
  }

  heading.textContent = 'Prospecting';
  bar.dataset.workspace = 'PROSPECTING';
  bar.dataset.workspaceIcon = '';
  if (miningReferenceMatches === null) {
    status.textContent = 'Loading reference locations…';
    return;
  }
  const locations = new Set(miningReferenceMatches.map((spawn) => spawn.location).filter(Boolean)).size;
  const salvage = $('#mining-kind')?.value === 'salvageable';
  status.textContent = locations
    ? `${locations} ${salvage ? 'salvage ' : ''}location${locations === 1 ? '' : 's'} ${locations === 1 ? 'matches' : 'match'} current filters.`
    : 'No locations match current filters.';
}

for (const button of $('#mining-tabs')?.querySelectorAll('button') || [])
  button.addEventListener('click', () => showMiningPane(button.dataset.pane));

/* ---------- can it be cracked? ---------- */

/**
 * The rock calculator. The model comes from the server once per page - the
 * lasers, modules, gadgets, minerals and ships as the install has them - and
 * every change to the form asks the server for the verdict, because the rule
 * lives in one place there and is tested there. The ship picked decides how
 * many heads there are and what size; each head starts as the laser the ship
 * ships with and takes as many modules as that head has slots for - one on
 * the Arbor MH1, three on the Helix II - read from the head's own item ports.
 */
let crackModel = null;

/** A scanned rock handed over from the Log tab, taken up once the model is in. */
let crackFromScan = null;

/**
 * The form filled from a scan-results reading: mass, resistance, the
 * primary mineral, and the deposit when one preset's likeliest mineral is
 * the rock's. Instability is left alone - the panel prints it as a figure
 * like 1.75 and the community rule takes a percentage, and the two are not
 * known to be the same scale; the note says so. Each figure lands only
 * where the engine read it.
 */
function fillCrackFromScan(scan) {
  if (!scan || !crackModel) return;
  if (scan.massKg != null) $('#crack-mass').value = String(Math.round(scan.massKg));
  if (scan.resistancePercent != null) $('#crack-resistance').value = String(Math.round(scan.resistancePercent));

  const primary = scan.primary || scan.parts?.find((p) => p.mineral && p.mineral !== 'Inert materials')?.mineral;
  const mineral = primary ? crackModel.minerals.find((m) => m.name.toLowerCase() === primary.toLowerCase()) : null;
  if (mineral) $('#crack-mineral').value = mineral.class;

  const say = $('#crack-scan-note');
  if (say) {
    const missing = [scan.massKg == null ? 'mass' : null, scan.resistancePercent == null ? 'resistance' : null].filter(Boolean);
    say.hidden = false;
    say.textContent = `From the scan read on the Log tab: ${scan.primary || scan.primaryRead || 'a rock'}`
      + (scan.scu != null ? `, ${scan.scu} SCU by the game's own count` : '')
      + `. ${missing.length ? `The panel's ${missing.join(' and ')} did not read and the field is as it was. ` : ''}`
      + `Instability is left as typed: the panel prints ${scan.instability ?? 'a figure'} and the rule wants a percentage, and nothing measured says they are the same scale.`;
  }
}

async function loadCrackModel() {
  const box = $('#crack');
  const unready = $('#crack-unready');
  if (!box) return;

  try {
    crackModel = await getJson('/api/mining/model');
  } catch {
    crackModel = null;
  }

  if (!crackModel?.ready) {
    miningFitStatus = 'Fit data has not been read yet.';
    renderMiningWorkspaceHeader();
    box.hidden = true;
    if (unready) {
      unready.hidden = false;
      unready.textContent = gameDataExcuse() || 'The install has not been read yet - Settings says when the game data is ready.';
    }
    return;
  }
  if (unready) unready.hidden = true;
  box.hidden = false;

  const rule = $('#crack-rule');
  if (rule && crackModel.rule) rule.textContent = `${crackModel.rule.requiredWattsPerKg} W per kilogram at zero resistance, breaking solo from ${Math.round(crackModel.rule.soloRatio * 100)}% and with a gadget from ${Math.round(crackModel.rule.gadgetRatio * 100)}% (${crackModel.rule.source})`;

  // Ships you have flown first, then the rest of the mining hulls.
  const ship = $('#crack-ship');
  const keep = ship.value;
  ship.textContent = '';
  const ships = [...crackModel.ships].sort((a, b) => (b.flown - a.flown) || a.name.localeCompare(b.name));
  for (const s of ships) {
    const heads = s.heads.length;
    ship.append(new Option(`${s.name} · ${heads} S${s.heads[0]?.size ?? '?'} head${heads === 1 ? '' : 's'}${s.flown ? ' · flown' : ''}`, s.class));
  }
  ship.value = keep && ships.some((s) => s.class === keep) ? keep : (ships[0]?.class || '');

  const mineral = $('#crack-mineral');
  mineral.textContent = '';
  mineral.append(new Option('Not said', ''));
  for (const m of crackModel.minerals) mineral.append(new Option(m.name, m.class));

  const gadget = $('#crack-gadget');
  gadget.textContent = '';
  gadget.append(new Option('None', ''));
  for (const g of crackModel.gadgets) gadget.append(new Option(`${g.name} · ${describeModifiers(g.modifiers) || 'no figures'}`, g.class));

  // The deposits: the HUD's name for the kind, and where several presets
  // share it, the mineral the class names - Asteroid (P-Type) · copper.
  const deposit = $('#crack-deposit');
  deposit.textContent = '';
  deposit.append(new Option('Not said', ''));
  for (const c of crackModel.compositions || []) {
    const bits = c.class.split('_');
    const shared = (crackModel.compositions || []).filter((o) => o.name === c.name).length > 1;
    const twin = shared && bits.length > 2 ? ` · ${bits.slice(2).join(' ').toLowerCase()}` : shared ? ` · ${bits.slice(1).join(' ').toLowerCase() || 'plain'}` : '';
    deposit.append(new Option(`${c.name}${twin}`, c.class));
  }

  renderCrackHeads();
  renderMiningMethods();
  renderCrackDeposit();
  renderCrackFittings();
  if (crackFromScan) { fillCrackFromScan(crackFromScan); crackFromScan = null; renderCrackDeposit(); }
  await assessCrack();
}

/** The newest rock scan on the Log, into the form. */
async function useLastScan() {
  let got;
  try {
    got = await getJson('/api/screen/readings?take=50');
  } catch {
    return;
  }
  const scan = (got.readings || []).filter((s) => s.mining && !s.dismissed).sort((a, b) => new Date(b.shotAt) - new Date(a.shotAt))[0];
  const say = $('#crack-scan-note');
  if (!scan) {
    if (say) { say.hidden = false; say.textContent = 'No rock scan has been read yet. Screenshot the scan-results panel with a rock selected; with Watch screenshots on (Log tab) it is read as it lands.'; }
    return;
  }
  fillCrackFromScan(scan.mining);
  renderCrackDeposit();
  await assessCrack();
}

$('#crack-use-scan')?.addEventListener('click', () => useLastScan().catch(() => {}));

/** "55,100 aUEC" or a dash: UEX's cheapest terminal for the item, or none recorded. */
function crackPrice(market) {
  return market?.price ? `${fmtInt(market.price)} aUEC` : '—';
}

function crackWhere(market) {
  const best = market?.shops?.[0];
  if (!best) return crackModel?.itemPricesKnown ? 'no terminal recorded' : 'prices need UEX (Settings)';
  return `${best.terminal}${best.place && best.place !== best.terminal ? `, ${best.place}` : ''}${market.shops.length > 1 ? ` +${market.shops.length - 1}` : ''}`;
}

/**
 * Every head, module and gadget with the game's figures and UEX's price:
 * what to buy, before the calculator says what it would do on a rock.
 */
function renderCrackFittings() {
  if (!crackModel) return;
  const heads = $('#crack-heads-table tbody');
  if (!heads) return;
  heads.textContent = '';
  for (const l of [...crackModel.lasers].sort((a, b) => a.size - b.size || b.power - a.power)) {
    const tr = el('tr');
    tr.append(el('td', null, l.name));
    tr.append(el('td', 'num', `S${l.size}`));
    tr.append(el('td', 'num', fmtInt(l.power)));
    tr.append(el('td', 'num', fmtInt(l.extractionPower)));
    tr.append(el('td', 'num', String(l.slots)));
    tr.append(el('td', 'num', `${l.filterModifier}%`));
    tr.append(el('td', 'num', `${Math.round(l.throttleMinimum * 100)}%`));
    tr.append(el('td', null, describeModifiers(l.modifiers) || '—'));
    tr.append(el('td', 'num', crackPrice(l.market)));
    tr.append(el('td', 'muted', crackWhere(l.market)));
    heads.append(tr);
  }

  const modules = $('#crack-modules-table tbody');
  modules.textContent = '';
  for (const m of crackModel.modules) {
    const tr = el('tr');
    tr.append(el('td', null, m.name));
    tr.append(el('td', null, m.active ? 'active' : 'passive'));
    tr.append(el('td', 'num', `×${m.powerMultiplier}`));
    tr.append(el('td', 'num', `×${m.extractionMultiplier}`));
    tr.append(el('td', null, describeModifiers(m.modifiers) || '—'));
    tr.append(el('td', 'num', m.filterModifier ? `+${m.filterModifier}%` : '—'));
    tr.append(el('td', 'num', m.active ? `${m.lifetime}s × ${m.charges}` : '—'));
    tr.append(el('td', 'num', crackPrice(m.market)));
    tr.append(el('td', 'muted', crackWhere(m.market)));
    modules.append(tr);
  }

  const gadgets = $('#crack-gadgets-table tbody');
  gadgets.textContent = '';
  for (const g of crackModel.gadgets) {
    const tr = el('tr');
    tr.append(el('td', null, g.name));
    tr.append(el('td', null, describeModifiers(g.modifiers) || '—'));
    tr.append(el('td', 'num', crackPrice(g.market)));
    tr.append(el('td', 'muted', crackWhere(g.market)));
    gadgets.append(tr);
  }
}

/**
 * The deposit's mix, as the game's preset has it: each mineral's share when
 * present and its chance of being present, with UEX's refined price a SCU
 * beside it. Value per rock is not given: the HUD's mass is kilograms and
 * nothing read says what a kilogram of this rock is in SCU.
 */
function renderCrackDeposit() {
  const panel = $('#crack-deposit-panel');
  if (!panel || !crackModel) return;
  const chosen = (crackModel.compositions || []).find((c) => c.class === $('#crack-deposit').value);
  panel.hidden = !chosen;
  if (!chosen) return;

  const body = $('#crack-mix tbody');
  body.textContent = '';
  const parts = [...chosen.parts].sort((a, b) => (b.probability * (b.minPercent + b.maxPercent)) - (a.probability * (a.minPercent + a.maxPercent)));
  for (const pt of parts) {
    const mineral = crackModel.minerals.find((m) => m.class === pt.element);
    const tr = el('tr');
    tr.append(el('td', null, pt.name));
    tr.append(el('td', 'num', `${fmtInt(pt.minPercent)}–${fmtInt(pt.maxPercent)}%`));
    tr.append(el('td', 'num', `${Math.round(pt.probability * 100)}%`));
    tr.append(el('td', 'num', pt.sellPerScu ? fmtInt(pt.sellPerScu) : '—'));
    tr.append(el('td', 'num', pt.rawPerScu ? fmtInt(pt.rawPerScu) : '—'));
    const yieldCell = el('td', 'num', pt.yield ? `${pt.yield > 0 ? '+' : ''}${Math.round(pt.yield)}%` : '—');
    if (pt.yieldAt) yieldCell.title = `Best station bonus on the method's yield, at ${pt.yieldAt}`;
    tr.append(yieldCell);
    tr.append(el('td', 'num', mineral ? `res ${mineral.resistance} · inst ${fmtInt(mineral.instability)}` : '—'));
    body.append(tr);
  }

  // A rough worth of a SCU of the mix, each way it can be sold: refined, at
  // the refined price before the refinery's own yield - the method's yield
  // is the server's and in no file or feed, only a station's bonus on it -
  // or raw. Each mineral's middle share, times its chance, times the price.
  // Rough because the shares of the minerals present are normalised by the
  // game and are not here, and because the price is the best on offer.
  const weight = (pt) => ((pt.minPercent + pt.maxPercent) / 200) * pt.probability;
  const refinedParts = parts.filter((pt) => pt.sellPerScu);
  const refined = refinedParts.reduce((sum, pt) => sum + weight(pt) * Number(pt.sellPerScu), 0);
  const rawParts = parts.filter((pt) => pt.rawPerScu);
  const raw = rawParts.reduce((sum, pt) => sum + weight(pt) * Number(pt.rawPerScu), 0);
  const worth = [];
  if (refinedParts.length) worth.push(`Roughly ${fmtInt(refined)} aUEC a SCU of the mix at refined prices, before the refinery's yield`);
  if (rawParts.length) worth.push(`${worth.length ? '' : 'Roughly '}${fmtInt(raw)} aUEC sold raw`);
  $('#crack-mix-note').textContent = `${chosen.name}: at least ${chosen.minimumDistinctElements} mineral${chosen.minimumDistinctElements === 1 ? '' : 's'} a rock. `
    + (worth.length
      ? `${worth.join(', ')} - middle share × chance × price, ${refinedParts.length} of ${parts.length} minerals priced. `
      : 'No UEX prices for these minerals (Settings). ')
    + 'Per rock is not given: the HUD’s mass is in kilograms and nothing read says what a kilogram of rock is in SCU.';

  // The likeliest mineral is the one the notes speak to, unless the pilot picked one.
  const mineral = $('#crack-mineral');
  if (mineral && !mineral.value && parts[0]) mineral.value = parts[0].element;
}

/** "-30% resistance, +40% window" - the game's percentage points, in the game's numbers. */
function describeModifiers(m) {
  if (!m) return '';
  const signed = (v) => `${v > 0 ? '+' : '−'}${Math.abs(v)}%`;
  return [
    m.resistance ? `${signed(m.resistance)} resistance` : null,
    m.instability ? `${signed(m.instability)} instability` : null,
    m.windowSize ? `${signed(m.windowSize)} window` : null,
    m.windowRate ? `${signed(m.windowRate)} charge rate` : null,
    m.catastrophicRate ? `${signed(m.catastrophicRate)} overcharge` : null,
    m.shatterDamage ? `${signed(m.shatterDamage)} shatter` : null,
    m.clusterFactor ? `${signed(m.clusterFactor)} cluster` : null,
  ].filter(Boolean).join(', ');
}

/** One row per head on the picked ship: its laser, and three module slots. */
function renderCrackHeads() {
  const host = $('#crack-heads');
  if (!host) return;
  if (!crackModel) {
    renderCrackFitSummary();
    return;
  }
  const ship = crackModel.ships.find((s) => s.class === $('#crack-ship').value);
  host.textContent = '';
  if (!ship) {
    renderCrackFitSummary();
    return;
  }

  ship.heads.forEach((head, i) => {
    const row = el('div', 'crack-head');
    row.append(el('span', 'crack-head-label', `Head ${i + 1} · S${head.size}`));

    const laser = document.createElement('select');
    laser.className = 'select crack-laser';
    const locked = head.editable === false || head.editable === null;
    for (const l of crackModel.lasers.filter((l) => locked ? l.class === head.stock
      : l.size === head.size && !l.bespoke)) {
      laser.append(new Option(`${l.name} · ${fmtInt(l.power)} · ${describeModifiers(l.modifiers) || 'no modifiers'}`, l.class));
    }
    if (head.stock && [...laser.options].some((o) => o.value === head.stock)) laser.value = head.stock;
    if (!laser.options.length && head.stock) laser.append(new Option(`${head.stock} · figures unavailable`, head.stock));
    laser.disabled = locked;
    laser.title = head.note || 'The head; the ship\'s own is picked first';
    laser.addEventListener('change', () => {
      renderCrackSlots(row);
      renderCrackFitSummary();
      assessCrack().catch(() => {});
    });
    row.append(laser);
    if (head.note) row.append(el('span', 'crack-head-note', head.note));
    renderCrackSlots(row);
    host.append(row);
  });
  renderCrackFitSummary();
}

/* The selector rows say what is fitted; this one-line summary says whether the
   calculator is assessing one head or an entire multi-head ship before the
   verdict turns the same fit into a rock-specific number. */
function renderCrackFitSummary() {
  const summary = $('#crack-fit-summary');
  const rows = [...($('#crack-heads')?.querySelectorAll('.crack-head') || [])];
  if (!summary) return;

  const lasers = rows.map((row) => crackModel?.lasers.find((laser) =>
    laser.class === row.querySelector('.crack-laser')?.value)).filter(Boolean);
  const capacity = lasers.reduce((total, laser) => total + Number(laser.slots || 0), 0);
  const fitted = rows.reduce((total, row) => total
    + [...row.querySelectorAll('.crack-module')].filter((module) => module.value).length, 0);
  miningFitStatus = lasers.length
    ? `Current fit · ${lasers.length} head${lasers.length === 1 ? '' : 's'} · ${fitted}/${capacity} module slot${capacity === 1 ? '' : 's'} fitted`
    : crackModel?.ready ? 'Choose a mining head to inspect its fit.' : 'Fit data has not been read yet.';
  summary.textContent = miningFitStatus;
  renderMiningWorkspaceHeader();
}

/** As many module slots as the head has: the Arbor MH1's one, the Helix II's three. Picks stay where a slot remains. */
function renderCrackSlots(row) {
  const laser = crackModel.lasers.find((l) => l.class === row.querySelector('.crack-laser')?.value);
  const slots = laser?.slots ?? 0;
  const kept = [...row.querySelectorAll('.crack-module')].map((m) => m.value);
  for (const old of [...row.querySelectorAll('.crack-module')]) old.remove();
  for (const old of [...row.querySelectorAll('.crack-noslots')]) old.remove();

  if (slots === 0) {
    row.append(el('span', 'muted crack-noslots', 'no module slots'));
    return;
  }
  for (let slot = 0; slot < slots; slot++) {
    const module = document.createElement('select');
    module.className = 'select tiny crack-module';
    module.append(new Option(slot === 0 ? 'No module' : '—', ''));
    for (const m of crackModel.modules) {
      module.append(new Option(`${m.active ? '⚡ ' : ''}${m.name} · ×${m.powerMultiplier} power${m.modifiers ? (describeModifiers(m.modifiers) ? ', ' + describeModifiers(m.modifiers) : '') : ''}${m.active ? ` · ${m.lifetime}s × ${m.charges}` : ''}`, m.class));
    }
    if (kept[slot] && crackModel.modules.some((m) => m.class === kept[slot])) module.value = kept[slot];
    module.title = 'A module in this head\'s slot; an active one counts as switched on';
    module.addEventListener('change', () => {
      renderCrackFitSummary();
      assessCrack().catch(() => {});
    });
    row.append(module);
  }
}

function crackRequest() {
  const heads = [...($('#crack-heads')?.querySelectorAll('.crack-head') || [])].map((row) => ({
    laser: row.querySelector('.crack-laser')?.value || '',
    modules: [...row.querySelectorAll('.crack-module')].map((s) => s.value).filter(Boolean),
  }));
  return {
    ship: $('#crack-ship').value || null,
    massKg: Number($('#crack-mass').value) || 0,
    resistance: Number($('#crack-resistance').value) || 0,
    instability: Number($('#crack-instability').value) || 0,
    heads,
    gadget: $('#crack-gadget').value || null,
  };
}

const CRACK_VERDICTS = {
  solo: ['Breaks on this fit', 'good'],
  gadget: ['Needs a gadget or an active', 'warn'],
  crew: ['Not this fit', 'bad'],
  none: ['No laser', 'bad'],
};

async function assessCrack() {
  const out = $('#crack-verdict');
  if (!out || !crackModel?.ready) return;
  const request = crackRequest();

  let got;
  try {
    const response = await fetch('/api/mining/crack', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(request),
    });
    if (!response.ok) throw new Error(`${response.status}`);
    got = await response.json();
  } catch (err) {
    out.textContent = '';
    out.append(el('p', 'muted', `Could not assess the rock: ${err.message}`));
    return;
  }

  const v = got.verdict;
  const [label, tone] = CRACK_VERDICTS[v.verdict] || [v.verdict, ''];
  out.textContent = '';

  const head = el('div', `crack-call ${tone}`);
  head.append(el('b', null, label));
  head.append(el('span', 'muted', ` · ${fmtInt(v.powerDelivered)} delivered against ${fmtInt(v.powerRequired)} needed · ${Math.round(v.ratio * 100)}% · estimate, community rule`));
  out.append(head);

  const facts = el('div', 'crack-facts');
  const fact = (k, val, title) => { const f = el('span'); f.append(el('span', 'k', k), el('b', null, val)); if (title) f.title = title; facts.append(f); };
  fact('Resistance after fit', `${v.effectiveResistancePercent}%`, 'The HUD figure scaled by the heads\', modules\' and gadget\'s resistance points');
  fact('Instability after fit', `${v.effectiveInstabilityPercent}%`);
  fact('Window', `${v.windowPercent}% of gauge`, 'The game\'s optimal window, widened or narrowed by the fit');
  fact('Breaks up to', `${fmtInt(v.maxCrackableMassKg)} kg`, 'At this resistance, on this fit');
  if (v.energyCapacity) fact('Rock holds', `${fmtInt(v.energyCapacity)} · sheds ${fmtInt(v.energyDecayPerSecond)}/s`, 'By the game\'s own constants: capacity per kilogram and decay per kilogram a second');
  out.append(facts);

  // The mineral is for the notes: what the game says about it, in its own figures.
  const mineral = crackModel.minerals.find((m) => m.class === $('#crack-mineral').value);
  const notes = [...(v.notes || [])];
  if (mineral) {
    notes.push(`${mineral.name}: element resistance ${mineral.resistance}, instability ${mineral.instability}, window at ${Math.round(mineral.windowMidpoint * 100)}%±${Math.round(mineral.windowRandomness * 100)} of the gauge, overcharge blast ×${mineral.explosionMultiplier}${mineral.instability >= 600 ? ' - an overcharge here is the rock gone' : ''}.`);
  }
  if (notes.length) {
    const list = el('ul', 'crack-notes');
    for (const n of notes) list.append(el('li', null, n));
    out.append(list);
  }

  const body = $('#crack-matrix tbody');
  body.textContent = '';
  for (const r of got.matrix || []) {
    const tr = el('tr');
    if (request.heads.some((h) => h.laser === r.laser)) tr.classList.add('current');
    const [rl, rt] = CRACK_VERDICTS[r.verdict] || [r.verdict, ''];
    tr.append(el('td', null, r.name));
    tr.append(el('td', 'num', fmtInt(r.power)));
    tr.append(el('td', 'num', fmtInt(r.powerDelivered)));
    tr.append(el('td', 'num', `${Math.round(r.ratio * 100)}%`));
    tr.append(el('td', 'num', fmtInt(r.maxCrackableMassKg)));
    const verdict = el('td', null, rl);
    verdict.classList.add(`crack-${rt}`);
    tr.append(verdict);
    tr.append(el('td', 'num muted', crackPrice(crackModel.lasers.find((l) => l.class === r.laser)?.market)));
    body.append(tr);
  }
  const heads = request.heads.length;
  const hull = crackModel.ships.find((s) => s.class === $('#crack-ship').value);
  $('#crack-matrix-note').textContent = hull?.heads.some((h) => h.editable === false || h.editable === null)
    ? 'Stock head only: this fit has a fixed head or its replacement compatibility is not yet known. Modules and gadgets still affect the estimate.'
    : `Compatible S${hull?.heads[0]?.size ?? '?'} heads on this rock, ${heads} to a fit with the same modules; only the laser changes, and a module is carried over even where the other head has no slot for it.`;
}

$('#crack-ship')?.addEventListener('change', () => { renderCrackHeads(); assessCrack().catch(() => {}); });
for (const id of ['#crack-mass', '#crack-resistance', '#crack-instability']) $(id)?.addEventListener('input', () => assessCrack().catch(() => {}));
for (const id of ['#crack-mineral', '#crack-gadget']) $(id)?.addEventListener('change', () => assessCrack().catch(() => {}));
$('#crack-deposit')?.addEventListener('change', () => { $('#crack-mineral').value = ''; renderCrackDeposit(); assessCrack().catch(() => {}); });

async function loadMiningPlaces() {
  const body = $('#mining-places tbody');
  const note = $('#mining-places-note');
  if (!body) return;

  const places = await getJson('/api/mining/places').catch(() => []);
  body.textContent = '';

  if (!places.length) {
    note.textContent = gameDataExcuse()
      ?? 'No deposit tables could be read from your install.';
    return;
  }

  // Worth needs UEX; richness does not. Saying which is missing beats a column
  // of dashes that looks like the page failed.
  const priced = places.some((p) => p.perRock > 0);

  for (const place of places.slice(0, 40)) {
    const tr = el('tr');
    tr.append(tdPlace(place.place));
    tr.append(el('td', 'muted', place.system || '—'));
    tr.append(el('td', 'num', `${place.ore.toFixed(place.ore >= 10 ? 0 : 1)}%`));

    // A place that beats the usual floor is the interesting one, so it is
    // marked the same way the deposit table marks it.
    const quality = el('td', place.quality?.local ? 'num' : 'num muted',
      place.quality ? `${place.quality.min}+${place.quality.local ? '*' : ''}` : '—');
    tr.append(quality);

    tr.append(el('td', place.perRock > 0 ? 'num inward' : 'num muted',
      place.perRock > 0 ? money(place.perRock) : '—'));
    tr.append(el('td', 'num muted', String(place.ores)));
    tr.append(el('td', 'muted', place.best.map((b) => b.resource).join(', ')));
    tr.append(el('td', 'num muted', place.respawn ? craftTime(place.respawn) : '—'));
    body.append(tr);
  }

  note.textContent = `${places.length} places, read from your install. `
    + 'The community dataset knows 234, so this is the part of the map your game '
    + 'files describe rather than all of it.'
    + (priced ? '' : ' Turn on UEX in Settings to price what a rock is worth; '
      + 'how rich the rocks are needs nothing but your install.');
}

async function loadLikelyMined() {
  const strip = $('#mining-mine');
  const note = $('#mining-mine-note');
  if (!strip || !note) return;

  const rows = await getJson('/api/mining/mine').catch(() => []);

  if (!rows.length) {
    strip.textContent = '';
    note.hidden = true;
    return;
  }

  tiles('#mining-mine', rows.slice(0, 4).map((r) => [r.name, `${r.scu} SCU`]));

  const total = rows.reduce((sum, r) => sum + r.revenue, 0);
  note.textContent = `${money(total)} from ore you sold and never bought — `
    + 'the closest thing to a mining record these logs allow, since nothing '
    + 'writes down a rock being mined. Bought somewhere unread, it would look the same.';
  note.hidden = false;
}

async function loadMiningRef() {
  try {
    miningCatalogue = await getJson('/api/reference/resources');
  } catch {
    miningCatalogue = [];
  }

  const fill = (selector, values, allLabel, labelOf = (v) => v) => {
    const select = $(selector);
    const previous = select.value;
    select.textContent = '';
    select.append(new Option(allLabel, ''));
    for (const value of values) select.append(new Option(labelOf(value), value));
    if (values.includes(previous)) select.value = previous;
  };

  fill('#mining-kind',
    [...new Set(miningCatalogue.map((s) => s.kind))].sort(),
    'All kinds', (k) => KIND_LABELS[k] || k);

  fill('#mining-system',
    [...new Set(miningCatalogue.map((s) => s.system).filter(Boolean))].sort(),
    'All systems');

  renderMiningRef();
}

const MINING_CAP = 500;

function renderMiningRef() {
  const term = ($('#mining-search').value || '').trim().toLowerCase();
  const kind = $('#mining-kind').value;
  const system = $('#mining-system').value;
  const body = $('#mining-table tbody');
  body.textContent = '';

  // The prospect board has a deliberately mining-specific score: ore share ×
  // price. Salvage has neither, so keeping the board visible would dress a row
  // of dashes up as a recommendation.
  const salvage = kind === 'salvageable';
  $('#mining-prospect-board').hidden = salvage;
  $('#mining-salvage-brief').hidden = !salvage;
  $('#mining-table').classList.toggle('salvage-table', salvage);

  // The two sources mean different things by "chance". The download carried a
  // real probability; the game stores a weight whose scale is its own business,
  // so the install's is that group's share of what spawns at the place. Both
  // are useful and neither is the other.
  const note = $('#mining-source');
  if (note && miningCatalogue.length) {
    note.textContent = miningCatalogue[0].source === 'install'
      ? 'Read from your game install; chance is the group’s share of what spawns there. '
      : 'From the community dataset; chance is the spawn group’s own probability. ';
  }

  const rows = miningCatalogue.filter((s) =>
    (!kind || s.kind === kind)
    && (!system || s.system === system)
    && (!term
      || s.resource.toLowerCase().includes(term)
      || s.location.toLowerCase().includes(term)
      || (s.deposit || '').toLowerCase().includes(term)))

    // What a SCU of the rock is worth, then how likely it is to be there. A
    // high price on an ore that is 2% of the rock is not a good rock, which is
    // what sorting on best sell alone used to say.
    .sort((a, b) => (oreWorth(b) ?? 0) - (oreWorth(a) ?? 0)
      || (b.groupChance * b.share) - (a.groupChance * a.share));
  miningReferenceMatches = rows;
  renderMiningWorkspaceHeader();

  const counter = $('#mining-count');
  counter.textContent = rows.length > MINING_CAP
    ? `Showing ${MINING_CAP.toLocaleString()} of ${rows.length.toLocaleString()} matches — refine the search or filters.`
    : '';

  if (!rows.length) {
    const tr = el('tr');
    const td = el('td', 'muted', miningCatalogue.length
      ? 'Nothing matches that filter.'
      : gameDataExcuse() || 'No deposits were found in your game files.');
    td.colSpan = 13;
    tr.append(td);
    body.append(tr);
    return;
  }

  const percent = (v) => `${(v * 100).toFixed(v * 100 >= 10 ? 0 : 1)}%`;

  // A band rather than a number, because it is one: the game gives a rock a
  // range and rolls within it. A single figure would read as a promise.
  // Everything tops out at 1000, so the ceiling says nothing and the floor says
  // most of it: ship mining never yields below 501, hand mining below 201, and
  // ground mining or gathering can give you anything at all.
  const qualityFloor = (spawn) =>
    (spawn.quality ? `${spawn.quality.min}+${spawn.quality.local ? '*' : ''}` : '—');

  const oreShare = (spawn) => {
    if (spawn.minPercent == null || spawn.maxPercent == null) return '—';
    const low = spawn.minPercent.toFixed(spawn.minPercent >= 10 ? 0 : 1);
    const high = spawn.maxPercent.toFixed(spawn.maxPercent >= 10 ? 0 : 1);
    return low === high ? `${high}%` : `${low}–${high}%`;
  };

  for (const spawn of rows.slice(0, MINING_CAP)) {
    const tr = el('tr');

    // The track button rides in the name cell here: the table already carries
    // eleven columns and a twelfth falls off the screen.
    const name = el('td', 'with-track');
    name.append(el('span', null, spawn.resource));
    name.append(trackButton(spawn.resource, 1, spawn.kind === 'mineable' ? 'SCU' : ''));
    tr.append(name);
    tr.append(el('td', 'muted', spawn.deposit ?? '—'));

    // How much of the rock this ore is. Only the install knows it, and only for
    // mineables, so everything else is a dash rather than a zero.
    tr.append(el('td', 'num muted', oreShare(spawn)));

    // The floor is the number a recipe's quality requirement is measured
    // against, so it leads; the rest of the distribution rides the tooltip. A
    // place that overrides the class default is marked, because that is the
    // whole point - it means here is not the same as everywhere.
    const quality = el('td', spawn.quality?.local ? 'num' : 'num muted', qualityFloor(spawn));
    if (spawn.quality) {
      quality.title = `${spawn.quality.min}–${spawn.quality.max}, `
        + `average ${Math.round(spawn.quality.mean)}, spread ${Math.round(spawn.quality.spread)}`
        + (spawn.quality.local ? ' — this place differs from the usual' : '');
    }
    tr.append(quality);

    // Worth its own column rather than a footnote: it is the difference between
    // planning a circuit and planning a stop.
    tr.append(el('td', 'num muted',
      spawn.respawnSeconds ? craftTime(spawn.respawnSeconds) : '—'));

    tr.append(el('td', 'muted', KIND_LABELS[spawn.kind] || spawn.kind));
    tr.append(tdPlace(spawn.location));
    tr.append(el('td', 'muted', spawn.system ?? '—'));
    tr.append(el('td', 'muted', spawn.group));
    // The two odds multiplied: what share of everything spawning here is this.
    // Kept as one number with the parts on the tooltip, because a miner asks
    // "how much of this place is Tin", not "what is the group probability".
    const find = el('td', 'num muted', percent(spawn.groupChance * spawn.share));
    find.title = `${percent(spawn.groupChance)} of what spawns here is `
      + `${spawn.group}, and ${percent(spawn.share)} of that is this`;
    tr.append(find);

    const worth = oreWorth(spawn);
    const worthCell = el('td', worth ? 'num inward' : 'num muted', worth ? money(worth) : '—');
    if (worth) {
      worthCell.title = 'A SCU of this rock, at the middle of its ore range, '
        + 'sold at the best price UEX knows';
    }
    tr.append(worthCell);

    const sell = el('td', spawn.bestSell ? 'num inward' : 'num muted',
      spawn.bestSell ? money(spawn.bestSell) : '—');
    if (spawn.bestSellTerminal) sell.title = `at ${spawn.bestSellTerminal}`;
    tr.append(sell);

    // Raw ore price and refinery yield: both from optional feeds, so both are
    // dashes until those are switched on.
    const raw = el('td', spawn.rawSell ? 'num' : 'num muted',
      spawn.rawSell ? money(spawn.rawSell) : '—');
    if (spawn.rawTerminal) raw.title = `at ${spawn.rawTerminal}`;
    tr.append(raw);

    // A station's bonus on the method's yield, signed - not the yield itself,
    // which is the server's and in no feed. Read unsigned it looked like
    // nine percent of the ore coming back.
    const yieldCell = el('td', spawn.refineryYield ? 'num' : 'num muted',
      spawn.refineryYield ? `${spawn.refineryYield > 0 ? '+' : ''}${spawn.refineryYield.toFixed(0)}%` : '—');
    if (spawn.refineryTerminal) yieldCell.title = `best station bonus, at ${spawn.refineryTerminal}`;
    tr.append(yieldCell);

    body.append(tr);
  }
}

onInput('#mining-search', renderMiningRef);
$('#mining-kind')?.addEventListener('change', renderMiningRef);
$('#mining-system')?.addEventListener('change', renderMiningRef);

/* ---------- the armoury: guns and armour, read from the install ---------- */

let armouryModel = null;
let armouryPane = 'guns';
let armouryOpenGun = null;
let armouryOpenSet = null;

const ARMOURY_PANES = ['guns', 'armour', 'attachments', 'grenades', 'knives'];
try {
  const kept = localStorage.getItem('qw-armoury-pane');
  if (ARMOURY_PANES.includes(kept)) armouryPane = kept;
} catch { /* a private window has no memory, which is fine */ }

function showArmouryPane(name) {
  if (!ARMOURY_PANES.includes(name)) name = 'guns';
  armouryPane = name;
  try { localStorage.setItem('qw-armoury-pane', name); } catch { /* as above */ }
  for (const id of ARMOURY_PANES.map((p) => `#armoury-pane-${p}`)) {
    const pane = $(id);
    if (pane) pane.classList.toggle('active', id === `#armoury-pane-${name}`);
  }
  for (const button of $('#armoury-tabs')?.querySelectorAll('button') || [])
    button.classList.toggle('active', button.dataset.pane === name);
}

$('#armoury-tabs')?.addEventListener('click', (e) => {
  const button = e.target.closest('button[data-pane]');
  if (button) showArmouryPane(button.dataset.pane);
});

async function loadArmoury() {
  const unready = $('#armoury-unready');
  try {
    armouryModel = await getJson('/api/armoury');
  } catch {
    armouryModel = null;
  }

  const panes = [...ARMOURY_PANES.map((p) => $(`#armoury-pane-${p}`)), $('#armoury-tabs')];
  if (!armouryModel?.ready) {
    for (const p of panes) if (p) p.hidden = true;
    if (unready) {
      unready.hidden = false;
      unready.textContent = gameDataExcuse() || 'The install has not been read yet - Settings says when the game data is ready.';
    }
    return;
  }
  if (unready) unready.hidden = true;
  for (const p of panes) if (p) p.hidden = false;

  // The kind filter lists what the install actually has, in the order a
  // holster would: pistols first, the shouldered things last.
  const order = ['Pistol', 'SMG', 'Rifle', 'Shotgun', 'Sniper rifle', 'Crossbow', 'LMG', 'Grenade launcher', 'Heavy'];
  const kinds = [...new Set(armouryModel.weapons.map((w) => w.kind))]
    .sort((a, b) => (order.indexOf(a) + 1 || 99) - (order.indexOf(b) + 1 || 99) || a.localeCompare(b));
  const kind = $('#armoury-gun-kind');
  if (kind) {
    const keep = kind.value;
    kind.textContent = '';
    kind.append(new Option('Every kind', ''));
    for (const k of kinds) kind.append(new Option(k, k));
    kind.value = kinds.includes(keep) ? keep : '';
  }

  const slotOrder = ['Helmet', 'Core', 'Arms', 'Legs', 'Undersuit', 'Backpack'];
  const slots = [...new Set(armouryModel.armour.map((a) => a.slot))]
    .sort((a, b) => (slotOrder.indexOf(a) + 1 || 99) - (slotOrder.indexOf(b) + 1 || 99) || a.localeCompare(b));
  const slot = $('#armoury-armour-slot');
  if (slot) {
    const keep = slot.value;
    slot.textContent = '';
    slot.append(new Option('Every slot', ''));
    for (const s of slots) slot.append(new Option(s, s));
    slot.value = slots.includes(keep) ? keep : '';
  }

  showArmouryPane(armouryPane);
  renderArmouryGuns();
  renderArmouryArmour();
  renderArmouryKit();
}

/* ---------- attachments, grenades, knives ---------- */

/**
 * An attachment's effect as words: only what the files change, each as the
 * multiplier written, so ×0.66 sound and ×1.2 spread read as the trade they
 * are. A sight leads with its zoom, since that is what it is for.
 */
function armouryEffectWords(e) {
  if (!e) return [];
  const words = [];
  const mul = (value, word, better) => {
    if (value == null || value === 1) return;
    const span = el('span', `armoury-effect ${(better === 'low' ? value < 1 : better === 'high' ? value > 1 : true) ? 'gain' : 'cost'}`, `×${Math.round(value * 1000) / 1000} ${word}`);
    words.push(span);
  };
  if (e.zoom > 0) words.push(el('span', 'armoury-effect gain', `×${e.zoom}${e.secondZoom > 0 ? ` / ×${e.secondZoom}` : ''} zoom`));
  if (e.zeroingMax > 0) words.push(el('span', 'armoury-effect', `zero to ${fmtInt(e.zeroingMax)} m by ${fmtInt(e.zeroingStep)}`));
  mul(e.damage, 'damage', 'high');
  mul(e.fireRate, 'rate', 'high');
  mul(e.spread, 'spread', 'low');
  mul(e.recoilStrength, 'recoil', 'low');
  mul(e.recoilTime, 'recoil time', 'low');
  mul(e.sound, 'sound', 'low');
  mul(e.heat, 'heat', 'low');
  mul(e.ammoCost, 'ammo per shot', 'low');
  mul(e.chargeTime, 'charge time', 'low');
  mul(e.projectileSpeed, 'projectile speed', 'high');
  mul(e.zoomTime, 'aim-down time', 'low');
  if (e.pellets) words.push(el('span', `armoury-effect ${e.pellets > 0 ? 'gain' : 'cost'}`, `${e.pellets > 0 ? '+' : ''}${e.pellets} pellets`));
  if (e.burstShots) words.push(el('span', `armoury-effect ${e.burstShots > 0 ? 'gain' : 'cost'}`, `${e.burstShots > 0 ? '+' : ''}${e.burstShots} burst shots`));
  return words;
}

/**
 * The "cheapest at" cell, with the rest of the terminals on hover: the row
 * has room for one, and "where else" should not cost a click.
 */
function armouryWhereCell(market) {
  const td = el('td', 'muted', armouryWhere(market));
  const others = (market?.shops || []).slice(1);
  if (others.length) {
    td.title = `Also at ${others.map((s) => `${s.terminal}${s.place && !s.terminal.toLowerCase().includes(s.place.toLowerCase()) ? `, ${s.place}` : ''} · ${fmtInt(s.price)} aUEC`).join('\n')}`;
    td.classList.add('armoury-more');
  }
  return td;
}

/** Every terminal UEX records for the item, cheapest first, or why there are none. */
function armouryShopTable(market) {
  const wrap = el('div');
  wrap.append(el('h4', null, `Sold at${market?.shops?.length ? ` (${market.shops.length})` : ''}`));
  if (!market?.shops?.length) {
    wrap.append(el('p', 'muted small', armouryModel?.itemPricesKnown ? 'UEX records no terminal selling this.' : 'Prices and terminals need UEX, in Settings.'));
    return wrap;
  }
  const table = el('table');
  const head = el('thead');
  const hr = el('tr');
  for (const [label, cls] of [['Terminal', null], ['Place', null], ['System', null], ['Price', 'num']]) hr.append(el('th', cls, label));
  head.append(hr);
  table.append(head);
  const body = el('tbody');
  for (const s of market.shops) {
    const tr = el('tr');
    tr.append(el('td', null, s.terminal));
    tr.append(el('td', null, s.place || '—'));
    tr.append(el('td', 'muted', s.system || '—'));
    tr.append(el('td', 'num', `${fmtInt(s.price)} aUEC`));
    body.append(tr);
  }
  table.append(body);
  wrap.append(table);
  wrap.append(el('p', 'muted small', 'UEX\'s price at each terminal, cheapest first; across the item\'s finishes where UEX files them under the same name.'));
  return wrap;
}

/**
 * One knife, grenade or attachment opened under its row: the wiki's
 * picture, every figure the files give it, every terminal that sells it,
 * and its finishes - a click on a finish swaps the picture, as a gun's does.
 */
function armouryKitDetail(item, noun, facts) {
  const inner = el('div', 'armoury-detail');
  inner.append(el('div', 'panel-title', item.name));
  inner.append(el('div', 'panel-sub', [item.family, item.kind, item.manufacturer || 'maker unnamed', item.class].filter(Boolean).join(' · ')));
  let picture = armouryPicture(item.uuid, item.name, item.pictured);
  if (item.pictured) picture.append(el('span', 'muted small', "The game's own icon of it."));
  inner.append(picture);

  inner.append(el('h4', null, 'From the files'));
  const list = el('dl', 'armoury-facts');
  for (const [label, value] of facts) {
    if (value == null || value === '') continue;
    list.append(el('dt', null, label));
    const dd = el('dd');
    if (Array.isArray(value)) for (const node of value) dd.append(node);
    else dd.textContent = String(value);
    list.append(dd);
  }
  inner.append(list);

  inner.append(armouryShopTable(item.market));

  inner.append(el('h4', null, `Finishes${item.finishes?.length ? ` (${item.finishes.length})` : ''}`));
  if (!item.finishes?.length) inner.append(el('p', 'muted small', `The plain ${noun} only.`));
  else {
    const chips = el('div', 'armoury-finishes');
    for (const f of item.finishes) {
      const chip = el('span', 'armoury-finish clickable', f.name);
      chip.title = 'Show this finish';
      chip.addEventListener('click', () => { picture = armouryShowPicture(picture, f.uuid, f.name, f.pictured); });
      chip.append(el('span', 'muted', f.market?.price ? `${fmtInt(f.market.price)} aUEC · ${armouryWhere(f.market)}` : 'no terminal recorded'));
      chips.append(chip);
    }
    inner.append(chips);
    inner.append(el('p', 'muted small', `A finish is the same ${noun} in another colour: same figures, its own price.`));
  }
  return inner;
}

function armouryAttachmentDetail(a) {
  const e = a.effect || {};
  // The zoom and the zeroing have lines of their own above the chips.
  const words = armouryEffectWords({ ...e, zoom: 0, secondZoom: 0, zeroingMax: 0 });
  return armouryKitDetail(a, a.kind === 'Sight' ? 'sight' : a.kind === 'Barrel' ? 'barrel' : 'piece', [
    ['Slot', `${a.kind}, size ${a.size}`],
    ['Zoom', e.zoom > 1 ? `×${e.zoom}${e.secondZoom > 0 ? `, second setting ×${e.secondZoom}` : ''}` : e.zoom === 1 ? 'none: a 1x sight' : null],
    ['Zeroes to', e.zeroingMax > 0 ? `${fmtInt(e.zeroingMax)} m, in steps of ${fmtInt(e.zeroingStep)}` : null],
    ['Does', words.length ? words : 'nothing the files put a number on'],
    ['Mass', a.mass ? `${a.mass} kg` : null],
  ]);
}

function armouryGrenadeDetail(g) {
  return armouryKitDetail(g, 'grenade', [
    ['Sets off', g.trigger === 'timer' ? `a ${g.fuseSeconds} s fuse` : g.trigger === 'impact' ? 'on impact' : null],
    ['Blast', g.blast ? `${armouryHit(g.blast.damage)}, full to ${g.blast.radius} m, none past ${g.blast.outerRadius} m` : 'none'],
    ['Pressure', g.pressure > 0 ? `${fmtInt(g.pressure)}, the game\'s own unit for what it throws` : null],
    ['Leaves', g.hazard ? `${armouryHit(g.hazard.perHit)} every ${g.hazard.periodSeconds} s within ${g.hazard.radius} m, for as long as it lasts - the files put no number on that` : 'nothing'],
    ['Mass', g.mass ? `${g.mass} kg` : null],
  ]);
}

function armouryKnifeDetail(k) {
  return armouryKitDetail(k, 'knife', [
    ['Slash', armouryHit(k.slash)],
    ['Stab', armouryHit(k.stab)],
    ['Impulse', k.impulse ? `${k.impulse}, the game\'s own unit for the push a hit gives` : null],
    ['Read from', `${k.config}, the melee table the knife points at`],
    ['Mass', k.mass ? `${k.mass} kg` : null],
  ]);
}

let armouryOpenKit = null;

/**
 * The three tabs after guns and armour. One render for all of them: the
 * search box and the size and price filters apply across the attachment
 * tables, and the grenade and knife tables are small enough that redrawing
 * them with the rest costs nothing.
 */
function renderArmouryKit() {
  if (!armouryModel?.ready) return;
  const q = ($('#armoury-search')?.value || '').trim().toLowerCase();
  const matches = (text) => !q || text.toLowerCase().includes(q);
  const priceCells = (tr, market) => {
    tr.append(el('td', 'num', armouryPrice(market)));
    tr.append(armouryWhereCell(market));
  };
  const open = (tr, key, detail, columns) => {
    tr.dataset.class = key;
    if (armouryOpenKit === key) tr.classList.add('open');
    tr.addEventListener('click', () => { armouryOpenKit = armouryOpenKit === key ? null : key; renderArmouryKit(); });
    return armouryOpenKit === key ? armouryExpansion(detail(), columns) : null;
  };
  const named = (item, sub) => {
    const td = el('td', null, item.name);
    if (sub) td.append(el('div', 'armoury-kind', sub));
    return td;
  };
  const chips = (td, words, none) => {
    if (words.length) for (const w of words) td.append(w);
    else td.append(el('span', 'muted', none));
    return td;
  };

  renderArmouryAttachments(q, matches, priceCells, open, named, chips);
  renderArmouryGrenades(matches, priceCells, open, named);
  renderArmouryKnives(matches, priceCells, open, named);
}

/** Sights, barrels and underbarrel pieces, each its own table; the sight's zoom gets columns rather than chips. */
function renderArmouryAttachments(q, matches, priceCells, open, named, chips) {
  const size = $('#armoury-kit-size')?.value || '';
  const priced = $('#armoury-kit-priced')?.checked;
  const all = armouryModel.attachments || [];
  const shown = all.filter((a) =>
    (!size || String(a.size) === size) && (!priced || a.market?.price)
    && matches(`${a.name} ${a.kind} ${a.family} ${a.manufacturer}`));

  const count = $('#armoury-kit-count');
  if (count) {
    const c = armouryModel.counts || {};
    count.textContent = `${shown.length} of ${all.length} attachments; the install describes ${c.attachments ?? '?'} counting every finish. `
      + (armouryModel.itemPricesKnown ? `UEX prices ${all.filter((a) => a.market?.price).length} of them.` : 'Prices need UEX, in Settings.');
  }

  // Sights: the zoom, the zeroing and the aim time are columns, and only
  // what is left over - a compensating sight would be news - goes in chips.
  const sights = shown.filter((a) => a.kind === 'Sight');
  const sBody = $('#armoury-sights tbody');
  if (sBody) {
    sBody.textContent = '';
    const sightCount = $('#armoury-sights-count');
    if (sightCount) sightCount.textContent = `· ${sights.length}`;
    if (!sights.length) sBody.append(armouryEmptyRow(q ? 'No sight matches.' : 'The install describes no sight.', 9));
    for (const a of sights) {
      const e = a.effect || {};
      const tr = el('tr');
      tr.append(named(a, [a.family, a.manufacturer].filter(Boolean).join(' · ')));
      tr.append(el('td', 'num', String(a.size)));
      tr.append(el('td', 'num', e.zoom > 0 ? `×${e.zoom}${e.secondZoom > 0 ? ` / ×${e.secondZoom}` : ''}` : '—'));
      tr.append(el('td', 'num', e.zeroingMax > 0 ? `${fmtInt(e.zeroingMax)} m by ${fmtInt(e.zeroingStep)}` : '—'));
      const aim = el('td', 'num', e.zoomTime && e.zoomTime !== 1 ? `×${e.zoomTime}` : '—');
      if (e.zoomTime && e.zoomTime !== 1) aim.classList.add(e.zoomTime < 1 ? 'armoury-gain' : 'armoury-cost');
      tr.append(aim);
      tr.append(chips(el('td'), armouryEffectWords({ ...e, zoom: 0, secondZoom: 0, zeroingMax: 0, zoomTime: 1 }), '—'));
      tr.append(el('td', 'num', a.finishes?.length ? String(a.finishes.length) : '—'));
      priceCells(tr, a.market);
      const expansion = open(tr, `a:${a.class}`, () => armouryAttachmentDetail(a), 9);
      sBody.append(tr);
      if (expansion) sBody.append(expansion);
    }
  }

  // Barrels and underbarrel pieces share a shape: what it is, what it does.
  for (const [kind, id, noun] of [['Barrel', '#armoury-barrels', 'barrel'], ['Underbarrel', '#armoury-underbarrel', 'piece']]) {
    const body = $(`${id} tbody`);
    if (!body) continue;
    body.textContent = '';
    const rows = shown.filter((a) => a.kind === kind);
    const counter = $(`${id}-count`);
    if (counter) counter.textContent = `· ${rows.length}`;
    if (!rows.length) body.append(armouryEmptyRow(q ? `No ${noun} matches.` : `The install describes no ${noun} for this slot.`, 7));
    for (const a of rows) {
      const tr = el('tr');
      tr.append(named(a, a.manufacturer));
      tr.append(el('td', null, a.family));
      tr.append(el('td', 'num', String(a.size)));
      tr.append(chips(el('td'), armouryEffectWords(a.effect), 'nothing the files put a number on'));
      tr.append(el('td', 'num', a.finishes?.length ? String(a.finishes.length) : '—'));
      priceCells(tr, a.market);
      const expansion = open(tr, `a:${a.class}`, () => armouryAttachmentDetail(a), 7);
      body.append(tr);
      if (expansion) body.append(expansion);
    }
  }
}

function armouryEmptyRow(text, columns) {
  const td = el('td', 'muted', text);
  td.colSpan = columns;
  const tr = el('tr');
  tr.append(td);
  return tr;
}

/** Grenades: what sets it off, what it does, what it leaves. */
function renderArmouryGrenades(matches, priceCells, open, named) {
  const body = $('#armoury-grenades tbody');
  if (!body) return;
  body.textContent = '';
  const q = ($('#armoury-search')?.value || '').trim();
  const grenades = (armouryModel.throwables || []).filter((g) => matches(`${g.name} ${g.manufacturer}`));
  if (!grenades.length) body.append(armouryEmptyRow(q ? 'No grenade matches.' : 'The install describes no grenade with a blast.', 9));
  for (const g of grenades) {
    const tr = el('tr');
    tr.append(named(g, g.manufacturer));
    tr.append(el('td', null, g.trigger === 'timer' ? `${g.fuseSeconds} s fuse` : g.trigger === 'impact' ? 'impact' : '—'));
    tr.append(el('td', null, g.blast ? armouryHit(g.blast.damage) : 'none'));
    tr.append(el('td', 'num', g.blast ? `${g.blast.radius}–${g.blast.outerRadius} m` : '—'));
    tr.append(el('td', 'num', g.pressure > 0 ? fmtInt(g.pressure) : '—'));
    tr.append(el('td', null, g.hazard
      ? `${armouryHit(g.hazard.perHit)} every ${g.hazard.periodSeconds} s within ${g.hazard.radius} m`
      : 'nothing'));
    tr.append(el('td', 'num', g.mass ? String(g.mass) : '—'));
    priceCells(tr, g.market);
    const expansion = open(tr, `g:${g.class}`, () => armouryGrenadeDetail(g), 9);
    body.append(tr);
    if (expansion) body.append(expansion);
  }
}

/** Knives, with the finding said once above the table rather than down a column. */
function renderArmouryKnives(matches, priceCells, open, named) {
  const all = armouryModel.melee || [];
  const note = $('#armoury-knife-note');
  if (note) {
    const first = all[0];
    note.textContent = !all.length ? 'The install describes no knife.'
      : armouryModel.meleeConfigs === 1 && first
        ? `Every knife the install sells reads from one melee table, ${first.config}: ${armouryHit(first.slash)} a slash, ${armouryHit(first.stab)} a stab. They differ in look, maker and price, and in nothing the files put a number on.`
        : `The knives read from ${armouryModel.meleeConfigs} melee tables, so their figures differ; each row is its own.`;
  }
  const body = $('#armoury-knives tbody');
  if (!body) return;
  body.textContent = '';
  const q = ($('#armoury-search')?.value || '').trim();
  const knives = all.filter((k) => matches(`${k.name} ${k.manufacturer}`));
  if (!knives.length && q) body.append(armouryEmptyRow('No knife matches.', 8));
  for (const k of knives) {
    const tr = el('tr');
    tr.append(named(k, k.manufacturer));
    tr.append(el('td', 'num', armouryHit(k.slash)));
    tr.append(el('td', 'num', armouryHit(k.stab)));
    tr.append(el('td', 'num', k.impulse ? String(k.impulse) : '—'));
    tr.append(el('td', 'num', k.mass ? String(k.mass) : '—'));
    tr.append(el('td', 'num', k.finishes?.length ? String(k.finishes.length) : '—'));
    priceCells(tr, k.market);
    const expansion = open(tr, `k:${k.class}`, () => armouryKnifeDetail(k), 8);
    body.append(tr);
    if (expansion) body.append(expansion);
  }
}

for (const id of ['#armoury-kit-size', '#armoury-kit-priced'])
  $(id)?.addEventListener('change', renderArmouryKit);

/** A detail row under the one clicked, spanning the table, so the figures open where the eye is. */
function armouryExpansion(inner, columns) {
  const tr = el('tr', 'armoury-expand');
  const td = el('td');
  td.colSpan = columns;
  td.append(inner);
  tr.append(td);
  // A click inside the expansion is reading, not closing.
  tr.addEventListener('click', (e) => e.stopPropagation());
  return tr;
}

/** "4,138 aUEC" or a dash: UEX's cheapest terminal for the item, or none recorded. */
function armouryPrice(market) {
  return market?.price ? `${fmtInt(market.price)} aUEC` : '—';
}

function armouryWhere(market) {
  const best = market?.shops?.[0];
  if (!best) return armouryModel?.itemPricesKnown ? 'no terminal recorded' : 'prices need UEX (Settings)';
  // "Guns Checkmate, Checkmate" says the place twice; the terminal name
  // carries it, so the place is added only when it adds something.
  const place = best.place && !best.terminal.toLowerCase().includes(best.place.toLowerCase()) ? `, ${best.place}` : '';
  return `${best.terminal}${place}${market.shops.length > 1 ? ` +${market.shops.length - 1}` : ''}`;
}

/** "12 ballistic", "32.5 energy + 7.5 distortion + 1 stun": one hit, by kind. */
function armouryHit(d) {
  if (!d) return '—';
  const parts = [
    ['physical', 'ballistic'], ['energy', 'energy'], ['distortion', 'distortion'], ['thermal', 'thermal'], ['biochemical', 'biochemical'], ['stun', 'stun'],
  ].filter(([k]) => d[k] > 0).map(([k, word]) => `${fmtDamage(d[k])} ${word}`);
  return parts.length ? parts.join(' + ') : '—';
}

function fmtDamage(n) {
  const v = Number(n) || 0;
  return v >= 100 ? fmtInt(v) : String(Math.round(v * 100) / 100);
}

/** The mode in one line: "AUTO 810 rpm", "BURST 3 × 900 rpm", "CHARGE ×2 after 3.5 s", "BEAM 225/s to 10 m". */
function armouryMode(m) {
  let text;
  if (m.kind === 'Beam') {
    const reach = m.beamFullRange >= m.beamZeroRange ? `to ${fmtInt(m.beamZeroRange)} m` : `to ${fmtInt(m.beamFullRange)} m, none past ${fmtInt(m.beamZeroRange)} m`;
    text = `${m.name} ${fmtDamage(m.beamDamagePerSecond?.total)}/s ${reach}`;
  } else if (m.kind === 'Charge') {
    text = `${m.name} ×${m.chargeDamageMultiplier}${m.chargePellets > 0 ? ` in ${m.chargePellets}` : ''} after ${m.chargeSeconds} s${m.chargeAmmoMultiplier > 1 ? `, ${m.chargeAmmoMultiplier} rounds` : ''}`;
  } else if (m.kind === 'Burst') {
    text = `${m.name} ${m.burstShots} × ${fmtInt(m.roundsPerMinute)} rpm`;
  } else {
    text = `${m.name} ${fmtInt(m.roundsPerMinute)} rpm`;
  }
  if (m.pellets > 1 && m.kind !== 'Charge') text += ` × ${m.pellets}`;
  return text;
}

/** The mode a pilot would hold the trigger on: the highest derived DPS. */
/**
 * The wiki's picture of an item, by the game's uuid, in a frame that says
 * why it is blank when it is: the community dataset off, or the wiki has
 * none. The game files hold no photograph of a gun or a helmet - a 64-pixel
 * loadout glyph and one generic icon per armour class are all there is.
 */
/**
 * The item's picture. The install's own where it has one - the attachment
 * icons, which need no network and no consent - and the wiki's otherwise,
 * which is asked only once the community dataset is on.
 */
function armouryPicture(uuid, name, fromInstall) {
  const frame = el('div', 'armoury-picture');
  const note = el('span', 'muted small');
  if (!armouryModel?.picturesKnown && !fromInstall) {
    note.textContent = 'Pictures come from the Star Citizen Wiki once the community dataset is on (Settings).';
    frame.append(note);
    return frame;
  }
  if (!uuid) {
    note.textContent = 'No id to ask the wiki with.';
    frame.append(note);
    return frame;
  }
  const img = el('img');
  img.alt = name;
  img.loading = 'lazy';
  img.src = `/api/armoury/picture/${encodeURIComponent(uuid)}`;
  img.addEventListener('error', () => {
    img.remove();
    note.textContent = 'The wiki has no picture of this one.';
    frame.append(note);
  });
  frame.append(img);
  return frame;
}

/** Points the expansion's picture at another colour or finish of the same thing. */
function armouryShowPicture(frame, uuid, name, fromInstall) {
  const fresh = armouryPicture(uuid, name, fromInstall);
  frame.replaceWith(fresh);
  return fresh;
}

function armouryBestMode(w) {
  return [...(w.modes || [])].sort((a, b) => b.damagePerSecond - a.damagePerSecond)[0] || null;
}

function armouryGunsFiltered() {
  if (!armouryModel) return [];
  const kind = $('#armoury-gun-kind')?.value || '';
  const damage = $('#armoury-gun-damage')?.value || '';
  const sort = $('#armoury-gun-sort')?.value || 'dps';
  const priced = $('#armoury-gun-priced')?.checked;
  const q = ($('#armoury-search')?.value || '').trim().toLowerCase();

  const rows = armouryModel.weapons.filter((w) => {
    if (kind && w.kind !== kind) return false;
    if (damage && (w.damage?.dominant || '') !== damage) return false;
    if (priced && !w.market?.price) return false;
    if (q && !`${w.name} ${w.kind} ${w.manufacturer}`.toLowerCase().includes(q)) return false;
    return true;
  });
  const best = (w) => armouryBestMode(w)?.damagePerSecond || 0;
  const hit = (w) => armouryBestMode(w)?.damagePerShot || 0;
  rows.sort((a, b) => {
    switch (sort) {
      case 'hit': return hit(b) - hit(a) || a.name.localeCompare(b.name);
      case 'mag': return (armouryBestMode(b)?.damagePerMagazine || 0) - (armouryBestMode(a)?.damagePerMagazine || 0) || a.name.localeCompare(b.name);
      case 'reach': return (b.dropStart || 1e9) - (a.dropStart || 1e9) || a.name.localeCompare(b.name);
      case 'price': return (a.market?.price || 1e12) - (b.market?.price || 1e12) || a.name.localeCompare(b.name);
      case 'name': return a.name.localeCompare(b.name);
      default: return best(b) - best(a) || a.name.localeCompare(b.name);
    }
  });
  return rows;
}

function renderArmouryGuns() {
  const body = $('#armoury-guns tbody');
  if (!body || !armouryModel?.ready) return;
  body.textContent = '';
  const rows = armouryGunsFiltered();
  const count = $('#armoury-gun-count');
  if (count) {
    const c = armouryModel.counts || {};
    count.textContent = `${rows.length} of ${c.plain ?? armouryModel.weapons.length} guns; the install describes ${c.weapons ?? '?'} counting every finish. `
      + `${armouryModel.itemPricesKnown ? `UEX prices ${armouryModel.weapons.filter((w) => w.market?.price).length} of them.` : 'Prices need UEX, in Settings.'}`;
  }
  for (const w of rows) {
    const best = armouryBestMode(w);
    const tr = el('tr');
    tr.dataset.class = w.class;
    if (armouryOpenGun === w.class) tr.classList.add('open');
    const name = el('td', null, w.name);
    if (w.manufacturer) name.append(el('div', 'armoury-kind', w.manufacturer));
    tr.append(name);
    const kind = el('td', null, w.kind);
    kind.append(el('div', 'armoury-kind', `${w.weight} holster`));
    tr.append(kind);
    tr.append(el('td', 'num', w.damage?.total > 0
      ? armouryHit(w.damage) : (w.explosion ? `blast ${armouryHit(w.explosion.damage)}` : '—')));
    const modes = el('td');
    const list = el('div', 'armoury-modes');
    for (const m of w.modes) {
      const line = el('span', null, armouryMode(m));
      if (m.condition) line.append(el('span', 'armoury-when', ` when ${m.condition}`));
      list.append(line);
    }
    modes.append(list);
    tr.append(modes);
    tr.append(el('td', 'num', best ? fmtInt(best.damagePerSecond) : '—'));
    tr.append(el('td', 'num', w.magazine > 0 ? String(w.magazine) : '—'));
    tr.append(el('td', 'num', best && w.magazine > 0 ? fmtInt(best.damagePerMagazine) : '—'));
    tr.append(el('td', 'num', w.dropStart > 0 ? `${fmtInt(w.dropStart)} m → ${fmtDamage(w.dropFloor)}` : 'none'));
    tr.append(el('td', 'num', armouryPrice(w.market)));
    tr.append(el('td', 'muted', armouryWhere(w.market)));
    tr.addEventListener('click', () => {
      armouryOpenGun = armouryOpenGun === w.class ? null : w.class;
      renderArmouryGuns();
    });
    body.append(tr);
    if (armouryOpenGun === w.class) body.append(armouryExpansion(renderArmouryGunDetail(w), 11));
  }
}

/** Every mode's figures for one gun, its drop curve, its blast, and every finish with a price. */
function renderArmouryGunDetail(w) {
  const inner = el('div', 'armoury-detail');
  inner.append(el('div', 'panel-title', w.name));
  inner.append(el('div', 'panel-sub', `${w.kind} · ${w.weight} holster · ${w.manufacturer || 'maker unnamed'} · ${w.class}`));
  let picture = armouryPicture(w.uuid, w.name);
  inner.append(picture);

  inner.append(el('h4', null, 'Fire modes, trigger held'));
  const table = el('table');
  const head = el('thead');
  const hr = el('tr');
  for (const [label, cls] of [['Mode', null], ['Per shot', 'num'], ['Cyclic', 'num'], ['Sustained', 'num'], ['DPS', 'num'], ['Per mag', 'num'], ['Empties in', 'num'], ['Heat', 'num']])
    hr.append(el('th', cls, label));
  head.append(hr);
  table.append(head);
  const tb = el('tbody');
  for (const m of w.modes) {
    const tr = el('tr');
    const label = el('td', null, armouryMode(m));
    if (m.condition) label.append(el('span', 'armoury-when', ` when ${m.condition}`));
    if (m.secondaryAmmo) label.append(el('span', 'armoury-when', ' · the magazine’s second load'));
    tr.append(label);
    tr.append(el('td', 'num', m.kind === 'Beam' ? `${fmtDamage(m.damagePerSecond)}/s` : `${fmtDamage(m.damagePerShot)} (${armouryHit(m.hit)}${m.pellets > 1 || m.chargePellets > 0 ? ` × ${m.chargePellets > 0 && m.kind === 'Charge' ? m.chargePellets : m.pellets}` : ''}${m.kind === 'Charge' ? ` × ${m.chargeDamageMultiplier}` : ''})`));
    tr.append(el('td', 'num', m.roundsPerMinute > 0 ? `${fmtInt(m.roundsPerMinute)} rpm` : '—'));
    tr.append(el('td', 'num', m.sustainedRoundsPerMinute > 0 ? `${fmtInt(m.sustainedRoundsPerMinute)} rpm` : '—'));
    tr.append(el('td', 'num', fmtInt(m.damagePerSecond)));
    tr.append(el('td', 'num', w.magazine > 0 ? fmtInt(m.damagePerMagazine) : '—'));
    tr.append(el('td', 'num', m.secondsToEmpty > 0 ? `${Math.round(m.secondsToEmpty * 10) / 10} s` : '—'));
    tr.append(el('td', 'num', m.heatPerShot > 0 ? String(m.heatPerShot) : '—'));
    tb.append(tr);
  }
  table.append(tb);
  inner.append(table);

  const notes = [];
  notes.push(`Projectile ${fmtInt(w.projectileSpeed)} m/s for ${w.projectileLifetime} s (${fmtInt(w.projectileSpeed * w.projectileLifetime)} m before it is gone).`);
  if (w.dropStart > 0) notes.push(`Damage holds to ${fmtInt(w.dropStart)} m, then loses ${w.dropPerMetre} a metre down to ${fmtDamage(w.dropFloor)} at ${fmtInt(w.floorAt)} m.`);
  else notes.push('No damage drop with distance.');
  if (w.explosion) notes.push(`On arrival: ${armouryHit(w.explosion.damage)} over ${w.explosion.radius}${w.explosion.outerRadius > w.explosion.radius ? `–${w.explosion.outerRadius}` : ''} m.`);
  if (w.magazine > 0) notes.push(`Magazine ${w.magazine} rounds (${w.magazineClass}).`);
  else notes.push('The files give this magazine no round count.');
  notes.push(`${Math.round(w.mass * 100) / 100} kg.`);
  inner.append(el('p', 'muted small', notes.join(' ')));

  inner.append(armouryShopTable(w.market));

  inner.append(el('h4', null, `Finishes${w.finishes?.length ? ` (${w.finishes.length})` : ''}`));
  if (!w.finishes?.length) inner.append(el('p', 'muted small', 'The plain gun only.'));
  else {
    const list = el('div', 'armoury-finishes');
    for (const f of w.finishes) {
      const chip = el('span', 'armoury-finish', f.name);
      chip.classList.add('clickable');
      chip.title = 'Show this finish';
      chip.addEventListener('click', () => { picture = armouryShowPicture(picture, f.uuid, f.name); });
      chip.append(el('span', 'muted', f.market?.price ? `${fmtInt(f.market.price)} aUEC · ${armouryWhere(f.market)}` : 'no terminal recorded'));
      list.append(chip);
    }
    inner.append(list);
    inner.append(el('p', 'muted small', 'A finish is the same gun in another colour: same figures, its own price.'));
  }
  return inner;
}

function armouryArmourFiltered() {
  if (!armouryModel) return [];
  const slot = $('#armoury-armour-slot')?.value || '';
  const weight = $('#armoury-armour-weight')?.value || '';
  const sort = $('#armoury-armour-sort')?.value || 'name';
  const priced = $('#armoury-armour-priced')?.checked;
  const q = ($('#armoury-search')?.value || '').trim().toLowerCase();

  const rows = armouryModel.armour.filter((a) => {
    if (slot && a.slot !== slot) return false;
    if (weight && a.weight !== weight) return false;
    if (priced && !a.market?.price) return false;
    if (q && !`${a.family} ${a.name} ${a.slot} ${a.manufacturer} ${(a.pieces || []).map((p) => p.name).join(' ')}`.toLowerCase().includes(q)) return false;
    return true;
  });
  const byName = (a, b) => a.family.localeCompare(b.family) || a.slot.localeCompare(b.slot) || a.name.localeCompare(b.name);
  rows.sort((a, b) => {
    switch (sort) {
      case 'cold': return a.temperatureMin - b.temperatureMin || byName(a, b);
      case 'hot': return b.temperatureMax - a.temperatureMax || byName(a, b);
      case 'carry': return b.capacityMicroScu - a.capacityMicroScu || byName(a, b);
      case 'quiet': return (a.emSignature + a.irSignature) - (b.emSignature + b.irSignature) || byName(a, b);
      case 'light': return a.mass - b.mass || byName(a, b);
      case 'price': return (a.market?.price || 1e12) - (b.market?.price || 1e12) || byName(a, b);
      default: return byName(a, b);
    }
  });
  return rows;
}

/** "70%" - what a hit leaves after the class's multiplier; the same for every piece of the class. */
function armouryTakes(r) {
  if (!r) return '—';
  return `${Math.round(r.physical * 100)}%${Math.abs(r.energy - r.physical) > 0.001 ? ` / ${Math.round(r.energy * 100)}% energy` : ''}`;
}

function renderArmouryArmour() {
  const body = $('#armoury-armour tbody');
  if (!body || !armouryModel?.ready) return;
  body.textContent = '';
  const rows = armouryArmourFiltered();
  const count = $('#armoury-armour-count');
  if (count) {
    const c = armouryModel.counts || {};
    count.textContent = `${rows.length} of ${c.sets ?? armouryModel.armour.length} sets, from ${c.armour ?? '?'} pieces in the install. `
      + `${armouryModel.itemPricesKnown ? `UEX prices ${armouryModel.armour.filter((a) => a.market?.price).length} of the sets.` : 'Prices need UEX, in Settings.'}`;
  }
  const note = $('#armoury-armour-note');
  if (note) {
    // Said once, above the table, so a column of identical figures is not
    // mistaken for a finding: the resistance is the class's, not the piece's.
    const macros = new Map();
    for (const a of armouryModel.armour) if (a.resistances) macros.set(a.resistances.macro, a.resistances);
    const light = macros.get('LightArmor'), medium = macros.get('MediumArmor'), heavy = macros.get('HeavyArmor');
    note.textContent = light && medium && heavy
      ? `Resistance is by class, not by piece: every light piece lets ${Math.round(light.physical * 100)}% of a hit through, every medium ${Math.round(medium.physical * 100)}%, every heavy ${Math.round(heavy.physical * 100)}% (stun ${Math.round(light.stun * 100)} / ${Math.round(medium.stun * 100)} / ${Math.round(heavy.stun * 100)}%). What differs between two pieces of a class is the rest of the row.`
      : 'Resistance is by class, not by piece; what differs between two pieces of a class is the rest of the row.';
  }
  for (const a of rows) {
    const tr = el('tr');
    const key = `${a.slot}|${a.name}`;
    tr.dataset.key = key;
    if (armouryOpenSet === key) tr.classList.add('open');
    const name = el('td', null, a.family);
    if (a.manufacturer) name.append(el('div', 'armoury-kind', a.manufacturer));
    tr.append(name);
    tr.append(el('td', null, a.slot));
    tr.append(el('td', null, a.weight || (a.resistances?.macro === 'CombatFlightsuitArmor' ? 'Flight suit' : '—')));
    tr.append(el('td', 'num', armouryTakes(a.resistances)));
    tr.append(el('td', 'num', a.resistances ? `${Math.round(a.resistances.stun * 100)}%` : '—'));
    tr.append(el('td', 'num', a.temperatureMin || a.temperatureMax ? `${fmtInt(a.temperatureMin)} to ${fmtInt(a.temperatureMax)} °C` : '—'));
    tr.append(el('td', 'num', a.radiationCapacity > 0 ? `${fmtInt(a.radiationCapacity)} · ${a.radiationDissipation}/s` : '—'));
    tr.append(el('td', 'num', a.capacityMicroScu > 0 ? `${fmtInt(a.capacityMicroScu / 1000)} mSCU` : '—'));
    tr.append(el('td', 'num', a.emSignature > 0 || a.irSignature > 0 ? `${a.emSignature}${a.irSignature > 0 ? ` · IR ${a.irSignature}` : ''}` : '0'));
    tr.append(el('td', 'num', String(Math.round(a.mass * 100) / 100)));
    tr.append(el('td', 'num', String(a.pieces?.length || 1)));
    tr.append(el('td', 'num', armouryPrice(a.market)));
    tr.append(el('td', 'muted', armouryWhere(a.market)));
    tr.addEventListener('click', () => {
      armouryOpenSet = armouryOpenSet === key ? null : key;
      renderArmouryArmour();
    });
    body.append(tr);
    if (armouryOpenSet === key) body.append(armouryExpansion(renderArmouryArmourDetail(a), 13));
  }
}

/** Every colour of one set with its own price, and the figures the row could not fit. */
function renderArmouryArmourDetail(a) {
  const inner = el('div', 'armoury-detail');
  inner.append(el('div', 'panel-title', `${a.family} · ${a.slot}`));
  inner.append(el('div', 'panel-sub', `${a.kind || a.slot}${a.weight ? ` · ${a.weight}` : ''} · ${a.manufacturer || 'maker unnamed'}`));
  let picture = armouryPicture(a.pieces?.[0]?.uuid, a.pieces?.[0]?.name || a.name);
  inner.append(picture);

  const facts = [];
  if (a.resistances) {
    const r = a.resistances;
    facts.push(`Takes ${Math.round(r.physical * 100)}% of ballistic, ${Math.round(r.energy * 100)}% of energy, ${Math.round(r.distortion * 100)}% of distortion, ${Math.round(r.thermal * 100)}% of thermal, ${Math.round(r.biochemical * 100)}% of biochemical and ${Math.round(r.stun * 100)}% of stun damage, ${Math.round(r.impact * 100)}% of an impact's force - the ${r.macro} table, shared by every piece that reads it.`);
  } else facts.push('No resistance block: it stops nothing.');
  if (a.protects?.length) facts.push(`Covers ${a.protects.join(', ')}.`);
  if (a.gForceResistance) facts.push(`G tolerance ${a.gForceResistance > 0 ? '+' : ''}${a.gForceResistance}.`);
  if (a.motionPenalty > 0 || a.viewPenalty > 0) facts.push(`Restriction penalty ${Math.round(a.motionPenalty * 100)}% movement, ${Math.round(a.viewPenalty * 100)}% view - the game's own figure; what puts the piece into that state is not read.`);
  inner.append(el('p', 'muted small', facts.join(' ')));

  inner.append(el('h4', null, `Colours and editions (${a.pieces?.length || 0})`));
  const list = el('div', 'armoury-finishes');
  for (const p of a.pieces || []) {
    const chip = el('span', 'armoury-finish', p.name);
    chip.classList.add('clickable');
    chip.title = 'Show this colour';
    chip.addEventListener('click', () => { picture = armouryShowPicture(picture, p.uuid, p.name); });
    chip.append(el('span', 'muted', p.market?.price ? `${fmtInt(p.market.price)} aUEC · ${armouryWhere(p.market)}` : 'no terminal recorded'));
    list.append(chip);
  }
  inner.append(list);
  return inner;
}

for (const id of ['#armoury-gun-kind', '#armoury-gun-damage', '#armoury-gun-sort', '#armoury-gun-priced'])
  $(id)?.addEventListener('change', renderArmouryGuns);
for (const id of ['#armoury-armour-slot', '#armoury-armour-weight', '#armoury-armour-sort', '#armoury-armour-priced'])
  $(id)?.addEventListener('change', renderArmouryArmour);
onInput('#armoury-search', () => { renderArmouryGuns(); renderArmouryArmour(); renderArmouryKit(); });


/* ---------- crafting blueprints ---------- */

let craftingCatalogue = [];

async function loadCraftingRef() {
  try {
    craftingCatalogue = await getJson('/api/reference/blueprints');
  } catch {
    craftingCatalogue = [];
  }

  const types = [...new Set(craftingCatalogue.map((b) => b.type).filter(Boolean))].sort();
  const select = $('#crafting-type');
  const previous = select.value;

  select.textContent = '';
  select.append(new Option('All types', ''));
  for (const type of types) select.append(new Option(prettyType(type), type));
  if (types.includes(previous)) select.value = previous;

  renderCraftingRef();
}

const CRAFTING_CAP = 500;

/** "540 s" is nobody's unit; craft times read as minutes and hours. */
function craftTime(seconds) {
  if (seconds <= 0) return '—';
  // Rounding a ten-second recipe to minutes printed "0m", which reads as a
  // missing number rather than as something that is quick.
  if (seconds < 60) return `${Math.round(seconds)}s`;
  if (seconds < 3600) return `${Math.round(seconds / 60)}m`;
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.round((seconds % 3600) / 60);
  return minutes ? `${hours}h ${minutes}m` : `${hours}h`;
}

function renderCraftingRef() {
  // Both sources describe the same recipes, so this says which is answering
  // rather than warning about a difference. The install is current with the
  // patch, which is the part that matters here: two recipes on this install
  // have already changed since the download was built.
  const note = $('#crafting-source');
  if (note && craftingCatalogue.length) {
    note.textContent = craftingCatalogue[0].source === 'install'
      ? 'Read from your game install. '
      : 'From the community dataset. ';
  }

  const term = ($('#crafting-search').value || '').trim().toLowerCase();
  const type = $('#crafting-type').value;
  const obtained = $('#crafting-obtained').value;
  const body = $('#crafting-table tbody');
  body.textContent = '';

  const rows = craftingCatalogue.filter((b) =>
    (!type || b.type === type)
    && (!obtained
      || (obtained === 'owned' && b.owned)
      || (obtained === 'default' && b.default)
      || (obtained === 'reward' && !b.default))
    && (!term
      || b.output.toLowerCase().includes(term)
      || b.materials.some((m) => m.toLowerCase().includes(term))));

  const counter = $('#crafting-count');
  counter.textContent = rows.length > CRAFTING_CAP
    ? `Showing ${CRAFTING_CAP.toLocaleString()} of ${rows.length.toLocaleString()} matches — refine the search or filters.`
    : '';

  if (!rows.length) {
    const tr = el('tr');
    const td = el('td', 'muted', craftingCatalogue.length
      ? 'Nothing matches that filter.'
      : gameDataExcuse() || 'No recipes were found in your game files.');
    td.colSpan = 8;
    tr.append(td);
    body.append(tr);
    return;
  }

  // Yours first: a blueprint you hold is one you can actually start.
  rows.sort((a, b) => Number(Boolean(b.owned)) - Number(Boolean(a.owned)));

  for (const bp of rows.slice(0, CRAFTING_CAP)) {
    const tr = el('tr');

    const makes = el('td');
    makes.append(el('span', null, bp.output));

    if (bp.owned) {
      const badge = el('span', 'job-kind owned', 'yours');
      badge.title = `Received ${relative(bp.receivedAt)}`;
      makes.append(badge);
    }
    tr.append(makes);
    tr.append(el('td', 'muted', prettyType(bp.type)));
    tr.append(el('td', 'num', gradeLetter(bp.grade)));
    tr.append(el('td', 'num muted', craftTime(bp.craftSeconds)));
    tr.append(el('td', 'muted materials', bp.materials.length ? bp.materials.join(', ') : '—'));

    // How you get the blueprint; the pool names ride the tooltip.
    const how = el('td', 'muted', bp.default
      ? 'Known by default'
      : bp.rewardPools.length
        ? `${bp.rewardPools.length} reward pool${bp.rewardPools.length === 1 ? '' : 's'}`
        : '—');
    if (bp.rewardPools.length) how.title = bp.rewardPools.join('\n');
    tr.append(how);

    tr.append(el('td', bp.shopPrice ? 'num' : 'num muted',
      bp.shopPrice ? money(bp.shopPrice) : 'not sold'));

    // Turning a recipe into a job is the whole point of having both pages.
    const plan = el('td', 'num');
    if (bp.materials.length) {
      const button = el('button', 'ghost', 'Plan');
      button.title = 'Track this build on the Jobs page';

      button.addEventListener('click', async () => {
        button.disabled = true;
        button.textContent = 'planned';

        await fetch('/api/jobs', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            title: `Craft ${bp.output}`,
            kind: 'craft',
            source: `${bp.output} blueprint · ${craftTime(bp.craftSeconds)} to craft`,
            items: parseJobItems(bp.materials.join('\n')),
          }),
        }).catch(() => { button.textContent = 'failed'; });
      });

      plan.append(button);
    }
    tr.append(plan);

    body.append(tr);
  }
}

onInput('#crafting-search', renderCraftingRef);
$('#crafting-type')?.addEventListener('change', renderCraftingRef);
$('#crafting-obtained')?.addEventListener('change', renderCraftingRef);

/* ---------- overlay layout ---------- */

/** Pretty names for the views and cards the layout page offers. */
const OVERLAY_LABELS = {
  now: 'Now', jobs: 'Jobs', map: 'Map', commodities: 'Cargo', market: 'Market',
  loadout: 'Loadout', stash: 'Stash', logbook: 'Logbook', fleet: 'Fleet', places: 'Places',
  location: 'Location', ship: 'Ship', session: 'Session', handle: 'Handle',
  feed: 'Live feed', stats: 'This session', job: 'Job in hand', trade: 'Trade from here',
  checklist: 'Checklist',
};

/**
 * The overlay layout editor, on its own page under Settings. Saving is
 * immediate - there is no Save button because there is nothing to lose by a
 * tick going straight through, and the widget picks it up on its next poll.
 */
/**
 * The screen panel: what the app is allowed to read, and what it found.
 *
 * Two separate permissions rather than one, because they are different sizes
 * of thing. Reading the clipboard is reading what somebody deliberately
 * copied; reading a screenshot is reading a picture of their game. Both are
 * off until asked for, and the server enforces that as well - a panel switched
 * off should stay off however the request arrives.
 */
let screenSettings = {
  mode: 'Off', watch: false, watchScreenshots: false,
  canReadScreenshots: false, canReadClipboard: false, folder: null,
};

/**
 * How long a finding stays up.
 *
 * Long enough to read a tooltip's worth of detail and get back to flying,
 * short enough that the panel is not still showing the last thing when you
 * come back to it. Each scan replaces the one before rather than queueing.
 */
const SCREEN_HOLD_MS = 30000;

let screenHold = null;
let screenWatcher = null;

/** The newest reading the page has seen, so the list only redraws on a new one. */
let screenLatestShot = null;

async function renderScreenPanel() {
  try {
    screenSettings = await getJson('/api/screen/settings');
  } catch {
    // The panel is not the page; a failure here must not take the rest down.
    return;
  }

  const desktop = screenSettings.canReadClipboard || screenSettings.canReadScreenshots;
  const unavailable = $('#screen-unavailable');
  if (unavailable) unavailable.hidden = desktop;

  const mode = $('#screen-mode');

  if (mode) {
    mode.value = screenSettings.mode;
    mode.disabled = !desktop;
  }

  const watch = $('#screen-watch');
  if (watch) watch.checked = !!screenSettings.watch;

  const folder = $('#screen-watch-folder');
  if (folder) folder.checked = !!screenSettings.watchScreenshots;

  applyScreenMode();
  renderScreenLog().catch(() => {});
}

/** Shows the controls the chosen mode actually has. */
function applyScreenMode() {
  const on = screenSettings.mode !== 'Off';
  const shots = screenSettings.mode === 'Screenshots';

  const controls = $('#screen-controls');
  if (controls) controls.hidden = !on;

  // The screenshot button appears with the mode that allows it rather than
  // being greyed out: a control that is there and refuses is worse than one
  // that is not there yet.
  const scan = $('#screen-scan');
  if (scan) scan.hidden = !shots;

  const folderLabel = $('#screen-watch-folder-label');
  if (folderLabel) folderLabel.hidden = !shots;

  // The watch reads the archive itself, newest first, so the button for the
  // older ones is for the pilot who has the watch off: a one-off read, by
  // count, and no button at all when there is nothing waiting.
  const unread = Number(screenSettings.unread) || 0;
  const watching = shots && screenSettings.watchScreenshots;
  const older = $('#screen-read-older');
  if (older) {
    older.hidden = !shots || !screenSettings.canReadScreenshots || watching || unread === 0;
    older.textContent = `Read ${unread} older screenshot${unread === 1 ? '' : 's'}`;
  }

  // The folder being followed, named. The pilot is agreeing to a directory
  // being read and should be able to see which one, and how much of it is
  // still to come.
  const folder = $('#screen-folder');
  if (folder) {
    const named = watching && screenSettings.folder;
    folder.hidden = !named;
    folder.textContent = named
      ? `Reading every screenshot in ${screenSettings.folder}, the ones already there and each new one as it lands.`
        + (unread
          ? ` ${unread} still to read, newest first.`
          : ' Nothing is waiting.')
        + ' Untick Watch screenshots to stop; invalidate a reading below to have nothing believed from it.'
      : '';
  }

  const status = $('#screen-mode-status');
  if (status) {
    status.textContent =
      shots ? (screenSettings.watchScreenshots ? 'clipboard and every screenshot' : 'clipboard and screenshots')
      : screenSettings.mode === 'CopyOnly' ? 'clipboard only'
      : 'off';
  }

  startScreenWatch();
}

async function saveScreenSettings(mode, watch, watchScreenshots) {
  screenSettings = {
    ...screenSettings,
    ...await getJson2(
      `/api/screen/settings?mode=${encodeURIComponent(mode)}&watch=${watch ? 'true' : 'false'}`
      + `&watchScreenshots=${watchScreenshots ? 'true' : 'false'}`),
  };

  applyScreenMode();
}

/**
 * The clipboard and the readings, on a timer, when asked for.
 *
 * Polled rather than pushed because there is no event for "somebody copied
 * something" that reaches a web page, and the folder watch lives in the
 * server. Three seconds is slower than a person types /showlocation and
 * alt-tabs, and slow enough not to be a spin.
 */
function startScreenWatch() {
  if (screenWatcher) {
    clearInterval(screenWatcher);
    screenWatcher = null;
  }

  if (screenSettings.mode === 'Off') return;

  // Only the clipboard is polled. Screenshots arrive on the live stream,
  // because the server watches the folder and the snapshot carries the
  // newest reading to every client, widget included.
  if (!$('#screen-watch')?.checked) return;

  screenWatcher = setInterval(() => {
    // Quietly: a watcher that announced "nothing copied" every three seconds
    // would be unusable.
    parseClipboard(true).catch(() => {});
  }, 3000);
}

function screenSay(message) {
  const status = $('#screen-status');
  if (status) status.textContent = message;
}

/**
 * Puts a finding up, and takes it down again after a while.
 *
 * Replacing rather than appending: the panel answers the last thing asked,
 * and a pile of old answers is a log, which this is not.
 */
function screenShow(build) {
  const box = $('#screen-result');
  if (!box) return;

  box.textContent = '';
  build(box);

  if (screenHold) clearTimeout(screenHold);

  screenHold = setTimeout(() => {
    box.textContent = '';
    screenSay('');
  }, SCREEN_HOLD_MS);
}

async function parseClipboard(quiet = false) {
  if (!quiet) screenSay('reading what you copied…');

  const found = await getJson2(`/api/screen/clipboard${quiet ? '?watched=true' : ''}`);

  if (!found.found) {
    if (!quiet) {
      screenSay(found.trouble || 'nothing to read');
      screenShow(() => {});
    }
    return;
  }

  screenSay('');

  screenShow((box) => {
    box.append(el('div', 'strong', `${found.gigametresFromCentre.toFixed(4)} Gm from the system centre`));

    // The raw numbers stay visible. They are the thing the game gave and the
    // only part of this that is exact.
    box.append(el('div', 'muted',
      `x ${Math.round(found.x).toLocaleString()} · `
      + `y ${Math.round(found.y).toLocaleString()} · `
      + `z ${Math.round(found.z).toLocaleString()}`));

    box.append(el('div', 'muted',
      'Which system this is in comes from your logs, not from the reading.'));

    // The first thing a coordinate is good for: how far the things you marked
    // are. Three at most here; the Points page measures every one.
    if (found.nearest?.length) {
      const list = el('div', 'screen-nearest');
      list.append(el('div', 'muted', 'Nearest of your points:'));
      for (const near of found.nearest) list.append(nearPointLine(near));
      box.append(list);
    }
  });

  // Only when the pilot asked. The watcher calls this every three seconds with
  // the same clipboard, and a list that rebuilds itself that often cannot be
  // read - which is what this function's own doc comment says.
  if (!quiet) renderScreenLog().catch(() => {});
}

/** What kind of screen a reading was, in words a pilot would use. */
const SCREEN_KINDS = {
  Tooltip: 'item',
  Loadout: 'loadout',
  Map: 'map',
  Contracts: 'contracts',
  Fleet: 'fleet',
  Reputation: 'reputation',
  Kiosk: 'kiosk',
  Mining: 'rock scan',
  MobiGlas: 'mobiGlas',
  Unknown: 'unread',
};

/** A check's verdict, worded for a reader. */
const SCREEN_VERDICTS = {
  agrees: 'agrees',
  differs: 'differs',
  new: 'new',
  unchecked: 'not checked',
};

/** One check as a feed row: the verdict, then what the screen said beside what the app thought. */
function screenCheckRow(check) {
  const li = el('li');
  li.append(el('span', `k ${check.verdict}`, SCREEN_VERDICTS[check.verdict] || check.verdict));

  const what = el('span', 'what', `${check.subject}: ${check.claim}`);
  li.append(what);

  // The belief is shown whatever the verdict: an agreement with nothing
  // beside it looks like a screen that was taken on trust.
  li.append(el('span', 'd', ` · logs: ${check.belief}`));

  if (check.note) li.append(el('span', 'd', ` · ${check.note}`));
  return li;
}

/** Everything a reading says, into a box. Shared by the panel and the list. */
function renderSighting(box, s, { full = true } = {}) {
  if (s.item) {
    if (s.item.name) {
      box.append(el('div', 'strong', s.item.name));

      for (const [label, value] of Object.entries(s.item.fields || {}))
        box.append(el('div', 'muted', `${label}: ${value}`));
    }

    for (const match of s.item.matches || []) {
      const line = el('div', null, match.name);

      if (match.agrees?.length)
        line.append(el('span', 'muted', ` · ${match.agrees.join(', ')} agree`));

      if (match.disagrees?.length)
        line.append(el('span', 'outward', ` · ${match.disagrees.join(', ')} do not`));

      box.append(line);
    }

    // Said out loud rather than left to be inferred from an empty space.
    if (s.item.trouble) box.append(el('div', 'muted', s.item.trouble));

    const named = (s.item.named || []).filter((n) => n.exact);

    if (!s.item.name && named.length) {
      box.append(el('div', 'muted', `Also on this frame: ${named.length} named`));
      for (const line of named.slice(0, 8))
        box.append(el('div', 'muted', line.candidates[0] || line.text));
    }
  }

  if (s.loadout) {
    const ship = s.loadout.ship
      || (s.loadout.looksLike?.length
        ? `read as “${s.loadout.shipRead}”, looks like ${s.loadout.looksLike.join(' or ')}`
        : `read as “${s.loadout.shipRead || '?'}”`);

    box.append(el('div', 'strong', ship));

    // The game's own caveat, carried through as written: this is the ships
    // at one place, not the fleet.
    if (s.loadout.scope) box.append(el('div', 'muted', s.loadout.scope));

    if (full) {
      const list = el('ul', 'feed screen-fittings');

      for (const f of s.loadout.fittings || []) {
        const li = el('li');
        li.append(el('span', 'what', f.slot));

        if (f.nothingRead) {
          li.append(el('span', 'd', ' · nothing read under it'));
        } else if (f.tier === 'Empty') {
          li.append(el('span', 'd', ' · empty, so the game says'));
        } else if (f.name) {
          li.append(el('span', 'd', ` · ${f.name}`));
          if (f.stock === false) li.append(el('span', 'k differs', 'not stock'));
          if (f.stock === true) li.append(el('span', 'k agrees', 'stock'));
          if (f.tier !== 'Exact') li.append(el('span', 'd', ` · read “${f.read}”`));
        } else {
          li.append(el('span', 'd', ` · read “${f.read}”, matched nothing`));
        }

        list.append(li);
      }

      box.append(list);
    }
  }

  if (s.kiosk) {
    const k = s.kiosk;
    const rows = k.rows || [];
    box.append(el('div', 'strong',
      `a kiosk ${k.buying === false ? 'selling' : 'buying'}, ${rows.length} commodit${rows.length === 1 ? 'y' : 'ies'}`));

    if (k.ship || k.cargoCapacity != null) {
      box.append(el('div', 'muted',
        `${k.ship || k.shipRead || 'a ship'}${k.cargoCapacity != null ? ` · ${k.cargoUsed ?? 0} / ${k.cargoCapacity} SCU` : ''}`));
    }

    if (full) {
      const list = el('ul', 'feed screen-fittings');

      for (const row of rows) {
        const li = el('li');
        li.append(el('span', 'what', row.commodity || `read as “${row.read}”`));

        // The unit stays welded to the price. They are not the same quantity
        // and nothing here converts one into the other.
        if (row.price != null)
          li.append(el('span', 'd', ` · ${Number(row.price).toLocaleString()} per ${row.priceUnit}`));

        if (row.quantity != null)
          li.append(el('span', 'd', ` · ${Number(row.quantity).toLocaleString()} ${row.quantityUnit || ''} in stock`));

        if (row.state) li.append(el('span', 'd', ` · ${row.state.toLowerCase()}`));
        list.append(li);
      }

      box.append(list);
    }

    // Said either way. Some kiosks round the balance and some print every
    // digit; only the second kind becomes a figure, and the wallet check
    // above says what was made of it.
    if (k.balance != null)
      box.append(el('div', 'muted', `Balance on screen: ${Number(k.balance).toLocaleString()} aUEC, printed in full.`));
    else if (k.balanceRead)
      box.append(el('div', 'muted', `Balance on screen: ${k.balanceRead}, abbreviated — no figure is taken from it.`));
  }

  // A scanned rock: the panel's figures, each said only where it read, and a
  // way to the calculator with them already in the form.
  if (s.mining) {
    const m = s.mining;
    box.append(el('div', 'strong', `a rock scanned: ${m.primary || m.primaryRead || 'mineral unread'}`));
    const facts = [
      m.massKg != null ? `${Number(m.massKg).toLocaleString()} kg` : 'mass did not read',
      m.resistancePercent != null ? `${m.resistancePercent}% resistance` : 'resistance did not read',
      m.instability != null ? `instability ${m.instability}` : 'instability did not read',
      m.scu != null ? `${m.scu} SCU` : null,
      m.difficulty ? m.difficulty.toLowerCase() : null,
    ].filter(Boolean);
    box.append(el('div', 'muted', facts.join(' · ')));

    if (full && (m.parts || []).length) {
      const list = el('ul', 'feed screen-fittings');
      for (const part of m.parts) {
        const li = el('li');
        li.append(el('span', 'what', part.mineral || `read as “${part.read}”`));
        li.append(el('span', 'd', ` · ${part.percent ? `${part.percent}%` : 'share did not read'}${part.quality != null ? ` · quality ${part.quality}` : ''}`));
        list.append(li);
      }
      box.append(list);
    }

    const go = el('button', 'ghost tiny', 'Mining fit');
    go.type = 'button';
    go.title = 'Open the Mining page with this rock in the calculator';
    go.addEventListener('click', () => { crackFromScan = m; showView('mining'); });
    box.append(go);
  }

  if (s.contracts) {
    const c = s.contracts;
    box.append(el('div', 'strong',
      c.accepted != null ? `${c.accepted} accepted${c.capacity != null ? ` of ${c.capacity}` : ''}` : `${(c.cards || []).length} contracts read`));

    if (full) {
      const list = el('ul', 'feed screen-fittings');

      for (const card of c.cards || []) {
        const li = el('li');
        li.append(el('span', 'what', card.title));
        if (card.reward) li.append(el('span', 'd', ` · ${card.reward}`));
        if (card.issuer) li.append(el('span', 'd', ` · ${card.issuer}`));
        list.append(li);
      }

      box.append(list);

      if (c.selectedTitle) {
        box.append(el('div', null, c.selectedTitle));
        const facts = [];
        if (c.selectedReward != null) facts.push(`${Number(c.selectedReward).toLocaleString()} aUEC`);
        if (c.selectedIssuer) facts.push(`by ${c.selectedIssuer}`);
        if (facts.length) box.append(el('div', 'muted', facts.join(' · ')));
        for (const o of c.objectives || []) box.append(el('div', 'muted', `◇ ${o}`));
      }
    }
  }

  if (s.fleet) {
    const rows = s.fleet.ships || [];
    box.append(el('div', 'strong', `${rows.length} ship${rows.length === 1 ? '' : 's'} at the Fleet Manager`));

    if (full) {
      const list = el('ul', 'feed screen-fittings');
      for (const row of rows) list.append(fleetRow(row));
      box.append(list);
    }
  }

  if (s.reputation) {
    const r = s.reputation;
    box.append(el('div', 'strong', r.organisation
      ? `${r.organisation}${r.standing ? `: ${r.standing}` : ''}`
      : 'the Rep app'));

    // Said in words: the rank is a highlighted card, and a highlight is not text.
    box.append(el('div', 'muted', 'The rank is drawn as a highlight and does not read.'));

    if (full && r.organisations?.length)
      box.append(el('div', 'muted', `Listed: ${r.organisations.join(', ')}`));
  }

  if (s.map) {
    const place = s.map.placeRead
      ? (s.map.systemRead ? `${s.map.systemRead} > ${s.map.placeRead}` : s.map.placeRead)
      : 'no place read off the footer';

    box.append(el('div', 'strong', place));

    // The trail down to the place, when the footer printed one.
    if (s.map.pathRead) box.append(el('div', 'muted', s.map.pathRead));

    if (s.map.gigametres != null) {
      box.append(el('div', 'muted',
        `${s.map.latitude}° ${s.map.longitude}° · ${s.map.gigametres} Gm`));
    }
  }

  if (s.wallet) {
    box.append(el('div', 'muted', s.wallet.balance != null
      ? `Wallet: ${Number(s.wallet.balance).toLocaleString()} aUEC`
      : `Wallet: ${s.wallet.trouble}`));
  }

  if (s.kind === 'MobiGlas' || s.kind === 'Unknown') {
    box.append(el('div', 'muted', s.summary));

    // The text is the whole point for a screen with no reader: it is what a
    // reader gets written from.
    if (full && s.lines?.length) {
      const text = el('details');
      text.append(el('summary', 'muted', `${s.lines.length} lines read`));
      for (const line of s.lines.slice(0, 60)) text.append(el('div', 'muted', line));
      box.append(text);
    }
  }

  if (s.checks?.length) {
    const list = el('ul', 'feed screen-checks');
    for (const check of s.checks) list.append(screenCheckRow(check));
    box.append(list);
  }
}

async function scanScreenshot() {
  screenSay('reading your last screenshot…');
  screenShow(() => {});

  const s = await getJson2('/api/screen/scan');

  if (!s.shot) {
    screenSay(s.summary || 'nothing read');
    return;
  }

  screenSay(`${s.shot} · ${SCREEN_KINDS[s.kind] || s.kind} · read in ${s.tookMs} ms`);
  screenShow((box) => renderSighting(box, s));
  renderScreenLog().catch(() => {});
}

/**
 * The archive, a batch at a time. Each press reads the newest forty the app
 * has never read and says what came of them and how many are left; the
 * button relabels itself from the settings answer rather than counting
 * down here, so what it says is what the folder holds.
 */
async function readOlderScreenshots() {
  const unread = Number(screenSettings.unread) || 0;
  screenSay(`reading ${Math.min(unread, 40)} of ${unread} older screenshot${unread === 1 ? '' : 's'}…`);
  screenShow(() => {});

  const got = await getJson2('/api/screen/readings/older?take=40');
  const read = got.read || [];
  const kinds = new Map();
  for (const s of read) kinds.set(s.kind, (kinds.get(s.kind) || 0) + 1);
  const told = [...kinds].map(([kind, n]) => `${n} ${SCREEN_KINDS[kind] || kind}`).join(', ');

  screenSay(`${read.length} read${told ? ` (${told})` : ''}`
    + (got.remaining ? ` · ${got.remaining} older still unread` : ' · nothing older left unread'));

  try {
    screenSettings = await getJson('/api/screen/settings');
  } catch { /* the button keeps its last count; the next open corrects it */ }
  applyScreenMode();
  renderScreenLog().catch(() => {});
}

/**
 * The log: everything the app has been shown, newest first.
 *
 * One list for both, because to the pilot a paste and a screenshot are the
 * same act - a thing they showed the app - and only the app cares that one
 * came through an engine and the other through the clipboard. The newest
 * entry is shown in full and the rest as a line each, so a session's worth
 * can be scanned without scrolling past one reading's detail.
 *
 * Not polled. It is redrawn when the page is opened, after a scan or a paste,
 * and when the live stream reports a shot this page has not seen.
 */
async function renderScreenLog() {
  const list = $('#screen-readings');
  if (!list) return;

  let got;

  try {
    got = await getJson('/api/screen/readings?take=50');
  } catch {
    return;
  }

  const entries = [
    ...(got.readings || []).map((s) => ({ at: s.shotAt, shot: s })),
    ...(got.clipboard || []).map((c) => ({ at: c.at, paste: c })),
  ].sort((a, b) => new Date(b.at) - new Date(a.at));
  const pins = got.pins || [];
  const pinnedAt = new Set(pins.map((pin) => pin.sourceAt));

  screenLatestShot = (got.readings || [])[0]?.shot || null;

  list.textContent = '';

  const counts = $('#screen-log-counts');

  if (counts) {
    counts.textContent = entries.length
      ? `${got.total} screenshot${got.total === 1 ? '' : 's'} read, ${got.pastes} paste${got.pastes === 1 ? '' : 's'}${pins.length ? ` · ${pins.length} pinned` : ''}`
      : '';
  }

  renderPinnedLocations(pins);
  renderScreenReviewInbox(got.readings || []);

  if (!entries.length) {
    list.append(el('p', 'muted', 'Nothing read yet. Screenshots and pastes both land here.'));
    return;
  }

  let first = true;

  for (const entry of entries) {
    const row = el('div', 'screen-reading');

    if (entry.paste) {
      const p = entry.paste;
      const repeats = Math.max(1, Number(p.timesSeen) || 1);
      const lastSeen = p.lastSeenAt && repeats > 1
        ? ` · seen ${repeats} times, last ${new Date(p.lastSeenAt).toLocaleString()}` : '';
      row.append(el('div', 'muted', `${new Date(p.at).toLocaleString()} · pasted${lastSeen}`));
      row.append(el('div', 'strong', `${p.gigametres.toFixed(4)} Gm from the system centre`));

      // The raw numbers are the exact part and the only part.
      row.append(el('div', 'muted',
        `x ${Math.round(p.x).toLocaleString()} · y ${Math.round(p.y).toLocaleString()} · z ${Math.round(p.z).toLocaleString()}`));

      // Where the logs put you then. The reading itself names nowhere.
      row.append(el('div', 'muted', p.believed
        ? `Your logs had you at ${p.system ? `${p.system} > ` : ''}${p.believed}.`
        : 'Your logs had no session running, so there is nothing to place it against.'));

      const action = document.createElement('button');
      action.type = 'button';
      action.className = 'ghost pin-location';
      const saved = pinnedAt.has(p.at);
      action.textContent = saved ? 'Pinned as POI' : 'Pin as POI';
      action.disabled = saved;
      if (!saved) action.addEventListener('click', () => pinClipboardLocation(p, action));
      row.append(action);
    } else {
      const s = entry.shot;
      if (s.dismissed) row.classList.add('dismissed');
      row.append(el('div', 'muted',
        `${new Date(s.shotAt).toLocaleString()} · ${SCREEN_KINDS[s.kind] || s.kind} · ${s.shot}${s.dismissed ? ' · invalidated' : ''}`));
      renderSighting(row, s, { full: first });
      first = false;

      // Kept in the log either way: the misreading is worth seeing, and the
      // file must not be read a second time. What changes is whether the
      // wallet, the fleet and the fittings believe it.
      if (s.dismissed)
        row.append(el('div', 'muted', 'Invalidated — kept here, believed by nothing.'));

      const action = document.createElement('button');
      action.type = 'button';
      action.className = 'ghost screen-dismiss';
      action.textContent = s.dismissed ? 'Believe it again' : 'Invalidate';
      action.title = s.dismissed
        ? 'Let the wallet, fleet and fittings use this reading again'
        : 'Keep this reading in the log, but stop the wallet, fleet and fittings using it';
      action.addEventListener('click', () => dismissReading(s, !s.dismissed, action));

      // Through the reader as it is now. The frame that taught a reader is
      // the first one worth reading again, and the log otherwise keeps the
      // old reading of it for good.
      const again = document.createElement('button');
      again.type = 'button';
      again.className = 'ghost screen-reread';
      again.textContent = 'Read again';
      again.title = 'Put this screenshot through the reader again and replace this reading';
      again.addEventListener('click', () => rereadReading(s, again));

      const actions = el('div', 'screen-actions');
      actions.append(action, again);
      row.append(actions);
    }

    list.append(row);
  }
}

/** The saved locations are separate from the disposable reading history. */
function renderPinnedLocations(pins) {
  const list = $('#screen-pins');
  const count = $('#screen-pin-count');
  if (!list) return;

  list.textContent = '';
  if (count) count.textContent = pins.length ? `${pins.length} saved` : '';

  if (!pins.length) {
    list.append(el('p', 'muted', 'Pin a copied location below to keep it here.'));
    return;
  }

  for (const pin of pins) {
    const row = el('div', 'pinned-location');
    row.append(el('div', 'strong', pin.label || [pin.system, pin.believed].filter(Boolean).join(' > ') || 'Copied location'));
    row.append(el('div', 'muted', pin.category || 'General'));
    // The reason is edited on the Points page; here it is only read, so the
    // aside stays the glance it is.
    if (pin.note) row.append(el('div', 'pin-note', pin.note));
    row.append(el('div', 'muted', `${Number(pin.gigametres).toFixed(4)} Gm from system centre`));
    row.append(el('div', 'muted',
      `x ${Math.round(pin.x).toLocaleString()} · y ${Math.round(pin.y).toLocaleString()} · z ${Math.round(pin.z).toLocaleString()}`));
    const fields = el('div', 'pin-fields');
    const label = document.createElement('input');
    label.type = 'text'; label.className = 'search'; label.value = pin.label || '';
    label.setAttribute('aria-label', 'Point of interest name');
    const category = document.createElement('select');
    category.className = 'select'; category.setAttribute('aria-label', 'Point of interest category');
    for (const choice of POINT_CATEGORIES) {
      const option = new Option(choice, choice);
      option.selected = choice === (pin.category || 'General');
      category.append(option);
    }
    const save = document.createElement('button');
    save.type = 'button'; save.className = 'ghost'; save.textContent = 'Save';
    save.addEventListener('click', () => savePinnedLocation(pin, label.value, category.value, save));
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'ghost pin-remove';
    remove.textContent = 'Remove';
    remove.addEventListener('click', () => unpinLocation(pin, remove));
    fields.append(label, category, save, remove);
    row.append(fields);
    list.append(row);
  }
}

/** Screens held for the next reader, with the capture beside the OCR evidence. */
function renderScreenReviewInbox(readings) {
  const box = $('#screen-review');
  const list = $('#screen-review-list');
  const count = $('#screen-review-count');
  if (!box || !list) return;

  const unknown = readings.filter(reading => ['MobiGlas', 'Unknown'].includes(reading.kind));
  box.hidden = unknown.length === 0;
  list.textContent = '';
  if (count) count.textContent = unknown.length ? `${unknown.length} queued` : '';

  for (const reading of unknown.slice(0, 12)) {
    const item = document.createElement('details');
    item.className = 'screen-review-item';
    const summary = document.createElement('summary');
    summary.textContent = `${reading.shot} · ${new Date(reading.shotAt).toLocaleString()}`;
    item.append(summary, el('p', 'muted', reading.summary));
    const image = document.createElement('a');
    image.href = `/api/screen/shots/${encodeURIComponent(reading.shot)}`;
    image.target = '_blank'; image.rel = 'noopener'; image.className = 'ghost'; image.textContent = 'Open screenshot';
    item.append(image);
    if ((reading.lines || []).length) item.append(el('pre', null, reading.lines.join('\n')));
    list.append(item);
  }
}

async function pinClipboardLocation(paste, button) {
  button.disabled = true;
  button.textContent = 'Pinning…';

  try {
    const response = await fetch('/api/screen/clipboard/pin', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ at: paste.at }),
    });
    if (!response.ok) throw new Error(`pin -> ${response.status}`);
    screenSay('Pinned as a point of interest.');
    await renderScreenLog();
  } catch {
    screenSay('could not pin that copied location');
    button.disabled = false;
    button.textContent = 'Pin as POI';
  }
}

/** The same file through the reader it has now; the fresh reading replaces the old one. */
async function rereadReading(reading, button) {
  button.disabled = true;
  button.textContent = 'Reading…';

  try {
    const response = await fetch('/api/screen/readings/reread', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ shot: reading.shot }),
    });
    // The server says why it would not, in the pilot's words, and that is
    // the message: no engine in this copy is a different fix from a file
    // the game has since deleted.
    if (!response.ok) {
      const why = await response.json().catch(() => null);
      throw new Error(why?.trouble || 'could not read that screenshot again - is it still in the game\'s folder?');
    }
    const got = await response.json();
    screenSay(`Read again: ${got.summary}`);
    await renderScreenLog();
    loadLedgerWallet().catch(() => {});
  } catch (e) {
    screenSay(e.message || 'could not read that screenshot again');
    button.disabled = false;
    button.textContent = 'Read again';
  }
}

/** A reading the pilot has looked at and does not want believed - or wants believed again. */
async function dismissReading(reading, dismissed, button) {
  button.disabled = true;

  try {
    const response = await fetch('/api/screen/readings/dismiss', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ shot: reading.shot, dismissed }),
    });
    if (!response.ok) throw new Error(`dismiss -> ${response.status}`);
    screenSay(dismissed ? 'Invalidated. Nothing will use that reading.' : 'That reading counts again.');
    await renderScreenLog();

    // The cash card may have been drawn from the very reading just set aside.
    loadLedgerWallet().catch(() => {});
  } catch {
    screenSay(dismissed ? 'could not invalidate that reading' : 'could not restore that reading');
    button.disabled = false;
  }
}

async function savePinnedLocation(pin, label, category, button) {
  button.disabled = true;
  try {
    const response = await fetch('/api/screen/pins', {
      method: 'PUT', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sourceAt: pin.sourceAt, label, category }),
    });
    if (!response.ok) throw new Error(`pin update -> ${response.status}`);
    screenSay('Point of interest saved.');
    await renderScreenLog();
  } catch {
    screenSay('could not save that point of interest');
    button.disabled = false;
  }
}

async function unpinLocation(pin, button) {
  button.disabled = true;

  try {
    const response = await fetch(`/api/screen/pins?at=${encodeURIComponent(pin.sourceAt)}`, { method: 'DELETE' });
    if (!response.ok) throw new Error(`unpin -> ${response.status}`);
    screenSay('Removed point of interest.');
    await renderScreenLog();
  } catch {
    screenSay('could not remove that point of interest');
    button.disabled = false;
  }
}

/* ---- The hangar: the fleet drawn to one scale ----
   The silhouettes are the game's own vehicle icons and the sizes are the
   game's bounding boxes, so a Pisces beside an Idris is the real difference,
   which is the whole point of drawing them together. */

// svgEl and SVG_NS are the map's, declared beside it further down.
let hangarShips = null;
const HANGAR_SHIP_GAP = 28;

async function loadHangar() {
  const canvas = $('#hangar-canvas');
  if (!canvas) return;

  let got;
  try {
    got = await getJson('/api/fleet/hangar');
  } catch {
    canvas.textContent = '';
    canvas.append(el('p', 'muted', 'Could not load the fleet — is the app still running?'));
    return;
  }

  hangarShips = got;
  renderHangar();

  // Gallery resolves its stand-in paints card by card. The scale drawing has
  // one SVG instead, so redraw it once those same game paints are known.
  const hulls = got.ships.filter((s) => s.className).map((s) => s.className);
  Promise.all(hulls.map(paintsForHull)).then(() => {
    if (hangarShips === got && $('#hangar-mode')?.value === 'scale') renderHangar();
  });
}

/** Ships in the chosen order; the unsized ones are set aside for the note below the drawing. */
function hangarOrdered() {
  // The Fleet roster tick rules here too: a rental or a ship since sold is
  // unticked there, and a hangar that still showed it would be a second
  // opinion about what the pilot owns.
  const ships = (hangarShips?.ships || []).filter((s) =>
    !excludedShips.has(s.name) && (!hangarComparison.size || hangarComparison.has(s.name)));
  const sort = $('#hangar-sort')?.value || 'length';

  ships.sort((a, b) => {
    if (sort === 'sorties') return (b.sorties || 0) - (a.sorties || 0);
    if (sort === 'recent') return new Date(b.lastFlown) - new Date(a.lastFlown);
    return (b.length || 0) - (a.length || 0);
  });

  return ships;
}

function renderHangar() {
  const canvas = $('#hangar-canvas');
  if (!canvas) return;

  canvas.textContent = '';
  const count = $('#hangar-count');
  const scaleBox = $('#hangar-scale');
  const unsized = $('#hangar-unsized');
  if (scaleBox) scaleBox.textContent = '';
  if (unsized) { unsized.hidden = true; unsized.textContent = ''; }

  if (!hangarShips?.available) {
    if (count) count.textContent = '';
    canvas.append(el('p', 'muted',
      'The sizes and silhouettes come from the game files, and this install has not been read yet — '
      + 'Settings says when the game data is ready.'));
    return;
  }

  const ships = hangarOrdered();
  const sized = ships.filter((s) => s.length > 0 && s.beam > 0);
  // A general scale deck only uses top-down game icons. In a picked pair,
  // though, leaving a hull out because the install has no such icon makes a
  // comparison look broken even when the game supplies its gallery render.
  // That render is visibly labelled below but fits the same verified box, so
  // the dimensions remain honest and both selected vessels stay present.
  const comparing = hangarComparison.size === 2;
  const canDrawToScale = (ship) => ship.icon || (comparing && Boolean(hangarPaintFor(ship)));
  const pictured = sized.filter(canDrawToScale);
  const iconless = sized.filter((s) => !canDrawToScale(s));
  const missing = ships.filter((s) => !(s.length > 0 && s.beam > 0));

  const unticked = (hangarShips?.ships || []).length - ships.length;
  if (count) {
    count.textContent = `${ships.length} ship${ships.length === 1 ? '' : 's'}`
      + (unticked ? ` · ${unticked} unticked on Fleet` : '');
  }

  const mode = $('#hangar-mode')?.value || 'gallery';
  const zoomSelect = $('#hangar-zoom');
  const layoutSelect = $('#hangar-layout');
  if (zoomSelect) zoomSelect.hidden = mode !== 'scale';
  if (layoutSelect) layoutSelect.hidden = mode !== 'scale';

  // The pair and its side-by-side belong to both modes: the gallery narrows
  // to the two cards as the deck narrows to the two silhouettes.
  renderHangarCompareBar();
  renderHangarComparison().catch(() => { /* the panel says what it could not fetch */ });

  if (mode === 'gallery') {
    setHangarExportVisible(false);
    renderHangarGallery(canvas, ships);
    return;
  }

  setHangarExportVisible(pictured.length > 0);

  if (!pictured.length) {
    canvas.append(el('p', 'muted', ships.length
      ? comparing
        ? 'Neither selected ship has a top-down game icon or gallery render, so there is nothing to draw to scale.'
        : 'None of the ships flown has a top-down game icon, so there is nothing to draw to scale.'
      : 'No ship has been flown in the logs yet, so there is nothing to draw.'));
    showScaleOmissions(unsized, iconless, missing);
    return;
  }

  // One scale for everything. The longest ship takes half the width, times
  // the zoom; smaller ships come out as small as they really are, which is
  // the honest picture and also why zoom exists. Half rather than all of it
  // because a ship is as wide as it is long more often than not, and one
  // 90 m hull at full width is a 60 m tall row with the rest below the fold.
  const width = Math.max(600, canvas.clientWidth || 1200);
  const zoom = Number($('#hangar-zoom')?.value) || 1;
  const longest = Math.max(...pictured.map((s) => s.length));
  // The two widest cells also need the gap between them. Without taking it
  // out here, their right edges exceed the deck by the gap and the second
  // ship silently wraps onto its own oversized shelf.
  let scale = ((width - 40 - HANGAR_SHIP_GAP) / 2 / longest) * zoom;   // px per metre

  // A comparison is drawn to fit: every pictured member stays on one shelf
  // whatever the zoom, and never blows up past what the pictures can stand.
  // This deliberately follows the picked pair rather than pictured.length:
  // a ship without a game icon is listed below as an omission, but used to
  // leave its visible counterpart subject to the normal full-deck scale.
  // That read as one enormous, blurred ship instead of an honest partial
  // comparison. The cap is the paint render's own 256 px at one and a half
  // times; past that the finish is a blur and the silhouette gains nothing.
  if (comparing) {
    const across = pictured.reduce((sum, s) => sum + Math.max(s.length, 90 / scale), 0);
    const fit = (width - 40 - HANGAR_SHIP_GAP) / across;
    const cap = 384 / Math.max(...pictured.map((s) => Math.max(s.length, s.beam)));
    scale = Math.min(fit, cap);
  }
  if (zoomSelect) zoomSelect.hidden = comparing || mode !== 'scale';
  if (layoutSelect) layoutSelect.hidden = comparing || mode !== 'scale';

  const groups = comparing ? [['Compared', pictured]] : hangarScaleGroups(pictured);

  // Ships on one shelf and ground vehicles on another, at the same scale. A
  // missing game icon is a missing shape, not permission to invent one or to
  // turn its full bounding box into an empty slab on the deck.
  for (const [title, group] of groups) {
    if (!group.length) continue;
    canvas.append(el('h3', 'hangar-group', `${title} · ${group.length}`));
    canvas.append(drawToScale(group, width, scale));
  }

  // The bar says what a length on the page is worth in metres: 10, 50 or
  // 100 m, whichever comes out at a readable width.
  if (scaleBox) {
    const metres = [10, 25, 50, 100, 200].find((m) => m * scale >= 60) || 200;
    const bar = svgEl('svg', { class: 'hangar-bar', width: metres * scale + 4, height: 14, viewBox: `0 0 ${metres * scale + 4} 14` });
    bar.append(svgEl('line', { x1: 2, y1: 7, x2: metres * scale + 2, y2: 7 }));
    bar.append(svgEl('line', { x1: 2, y1: 2, x2: 2, y2: 12 }));
    bar.append(svgEl('line', { x1: metres * scale + 2, y1: 2, x2: metres * scale + 2, y2: 12 }));
    scaleBox.append(bar);
    scaleBox.append(el('span', 'muted', ` ${metres} m — sizes are the game's bounding boxes. Silhouettes are its own vehicle icons, tinted by maker; in a comparison, a hull without one may use its Gallery render inside that same box and is labelled below its name.`));
  }

  showScaleOmissions(unsized, iconless, missing);
}

/* ---------- two ships side by side ---------- */

/**
 * The pair to compare, chosen here or on the Fleet cards. The selects list
 * the roster the deck draws - a ship unticked on Fleet is not offered, for
 * the same reason it is not drawn.
 */
function renderHangarCompareBar() {
  const a = $('#hangar-compare-a');
  const b = $('#hangar-compare-b');
  const clear = $('#hangar-compare-clear');
  if (!a || !b || !clear) return;

  const names = (hangarShips?.ships || []).filter((s) => !excludedShips.has(s.name)).map((s) => s.name)
    .sort((x, y) => x.localeCompare(y));
  const chosen = [...hangarComparison];

  for (const [select, index] of [[a, 0], [b, 1]]) {
    select.textContent = '';
    select.append(new Option(index === 0 ? 'a ship…' : 'another…', ''));
    for (const name of names) select.append(new Option(name, name));
    select.value = chosen[index] && names.includes(chosen[index]) ? chosen[index] : '';
  }
  clear.hidden = hangarComparison.size === 0;
}

function chooseHangarComparison(index, name) {
  const chosen = [...hangarComparison];
  // Keep the two slots apart: picking the first ship again in the second
  // select is one ship, not a comparison.
  chosen[index] = name && name !== chosen[1 - index] ? name : undefined;
  hangarComparison = new Set(chosen.filter(Boolean));
  renderHangar();
  try { renderFleetShips(); } catch { /* Fleet not drawn yet: its cards read the set when they are */ }
}

/** The Garage's sheet for a hull, fetched once per page; null when the dataset cannot draw it. */
const compareSheets = new Map();
function compareSheetFor(cls) {
  if (!cls) return Promise.resolve(null);
  if (!compareSheets.has(cls))
    compareSheets.set(cls, getJson(`/api/garage/${encodeURIComponent(cls)}`).then((d) => (d && d.known ? d : null)).catch(() => null));
  return compareSheets.get(cls);
}
let compareCatalogue = null;

/**
 * The rows of the side-by-side, each saying which way is better - so a
 * heavier ship is not marked as winning on mass - and where the figure comes
 * from. A row both ships lack is left out rather than drawn as two dashes.
 */
function hangarComparisonRows(left, right) {
  const rows = [];
  const row = (group, label, pick, format, better = null, source = 'dataset') => {
    const values = [left, right].map((side) => {
      try { const v = pick(side); return Number.isFinite(v) ? v : (v ?? null); } catch { return null; }
    });
    if (values.every((v) => v === null || v === undefined)) return;
    rows.push({ group, label, values, text: values.map((v, i) => (v === null || v === undefined ? '—' : format(v, [left, right][i]))), better, source, format });
  };

  const m = (n) => `${fmt1(n)} m`;
  row('Size', 'Length', (s) => s.ship.length, m, null, 'install');
  row('Size', 'Beam', (s) => s.ship.beam, m, null, 'install');
  row('Size', 'Height', (s) => s.ship.height, m, null, 'install');

  row('Your use', 'Sorties', (s) => s.ship.sorties, fmtInt, null, 'logs');
  row('Your use', 'Hours aboard', (s) => s.ship.hours, (n) => `${fmt1(n)} h`, null, 'logs');
  row('Your use', 'Last flown', (s) => s.ship.lastFlown, (d) => relative(d), null, 'logs');

  row('Hull', 'Hull HP', (s) => s.sheet.ship.health, fmtInt, 'more');
  row('Hull', 'Mass, stock', (s) => s.sheet.sheet.mass, (n) => `${fmtInt(n)} kg`, 'less');
  row('Hull', 'Crew', (s) => s.sheet.ship.crew, fmtInt);
  row('Hull', 'Cargo', (s) => s.sheet.ship.cargoScu, (n) => `${fmtInt(n)} SCU`, 'more');
  row('Hull', 'Quantum fuel', (s) => s.sheet.ship.quantumFuel, fmtInt, 'more');
  row('Hull', 'Hydrogen fuel', (s) => s.sheet.ship.hydrogenFuel, fmtInt, 'more');

  row('Flight', 'SCM', (s) => s.sheet.ship.flight.scm, (n) => `${fmtInt(n)} m/s`, 'more');
  row('Flight', 'Boost', (s) => s.sheet.ship.flight.boost, (n) => `${fmtInt(n)} m/s`, 'more');
  row('Flight', 'Max', (s) => s.sheet.ship.flight.max, (n) => `${fmtInt(n)} m/s`, 'more');
  row('Flight', 'Pitch · yaw · roll', (s) => s.sheet.ship.flight.pitch + s.sheet.ship.flight.yaw + s.sheet.ship.flight.roll,
    (_, s) => `${fmtInt(s.sheet.ship.flight.pitch)} · ${fmtInt(s.sheet.ship.flight.yaw)} · ${fmtInt(s.sheet.ship.flight.roll)} °/s`, 'more');

  row('Defence', 'Shield HP', (s) => s.sheet.sheet.shield.hp, fmtInt, 'more');
  row('Defence', 'Shield regen', (s) => s.sheet.sheet.shield.regen, (n) => `${fmtInt(n)}/s`, 'more');

  row('Weapons', 'Pilot DPS', (s) => s.sheet.sheet.weapons.fixedDps, fmt1, 'more');
  row('Weapons', 'Alpha', (s) => s.sheet.sheet.weapons.fixedAlpha, fmt1, 'more');
  row('Weapons', 'Pips', (s) => s.sheet.sheet.weapons.pips, fmtInt, 'less');
  row('Weapons', 'Turret DPS', (s) => s.sheet.sheet.weapons.turretDps, fmt1, 'more');
  row('Weapons', 'Missiles', (s) => s.sheet.sheet.weapons.missiles, fmtInt, 'more');
  row('Weapons', 'Missile damage', (s) => s.sheet.sheet.weapons.missileDamage, fmtInt, 'more');

  row('Quantum', 'Drive', (s) => s.sheet.sheet.quantumDrive?.drive ?? null, (d) => d);
  row('Quantum', 'Speed', (s) => s.sheet.sheet.quantumDrive?.speed, fmtSpeed, 'more');
  row('Quantum', 'Range', (s) => s.sheet.sheet.quantumDrive?.range, fmtDistance, 'more');
  row('Quantum', 'Spool', (s) => s.sheet.sheet.quantumDrive?.spoolTime, (n) => `${fmt1(n)} s`, 'less');

  row('Signature', 'EM, shields up', (s) => s.sheet.sheet.shields.em, fmtInt, 'less');
  row('Signature', 'IR, shields up', (s) => s.sheet.sheet.shields.ir, fmtInt, 'less');
  row('Signature', 'EM, in quantum', (s) => s.sheet.sheet.quantum.em, fmtInt, 'less');

  row('Power', 'Available', (s) => s.sheet.sheet.power.available, (n) => `${fmtInt(n)} seg`, 'more');
  row('Power', 'Drawn, shields up', (s) => s.sheet.sheet.power.usedShields, (n) => `${fmt1(n)} seg`, 'less');
  row('Power', 'Cooling generated', (s) => s.sheet.sheet.cooling.generated, (n) => `${fmtInt(n)} seg`, 'more');

  row('Money', 'Buy, UEX', (s) => s.ref?.price?.price ?? null, money, 'less', 'uex');
  row('Money', 'Rent, UEX', (s) => s.ref?.rental?.price ?? null, money, 'less', 'uex');
  row('Money', 'Claim wait', (s) => s.ref?.standardClaimTime ?? null, (n) => `${fmt1(n)} min`, 'less');
  row('Money', 'Expedite fee', (s) => s.ref?.expeditedCost ?? null, money, 'less');

  return rows;
}

/**
 * The side-by-side under the deck. The figures are the Garage's own
 * recomputed sheet for each hull - the same arithmetic the dataset's totals
 * come from - beside the install's dimensions and the logs' record of use;
 * a hull the dataset cannot draw gets its size and use and a sentence about
 * the rest, not a column of dashes.
 */
async function renderHangarComparison() {
  const box = $('#hangar-compare');
  if (!box) return;
  const names = [...hangarComparison];
  const ships = names.map((n) => (hangarShips?.ships || []).find((s) => s.name === n)).filter(Boolean);
  if (ships.length !== 2) { box.hidden = true; return; }

  box.hidden = false;
  $('#hangar-compare-title').textContent = `${ships[0].name} vs ${ships[1].name}`;
  $('#hangar-compare-note').textContent = 'Fetching the sheets…';

  const [sheets, catalogue] = await Promise.all([
    Promise.all(ships.map((s) => compareSheetFor(s.className))),
    (compareCatalogue ??= getJson('/api/reference/ships').catch(() => [])),
  ]);
  // The pair changed under the fetch; that answer belongs to a comparison that is gone.
  if ([...hangarComparison].join('|') !== names.join('|')) return;

  const sides = ships.map((ship, i) => ({
    ship, sheet: sheets[i],
    ref: catalogue.find((r) => r.name === ship.name) || null,
  }));
  const rows = hangarComparisonRows(sides[0], sides[1]);

  const head = $('#hangar-compare-table thead');
  head.textContent = '';
  const hr = el('tr');
  hr.append(el('th', null, ''));
  for (const side of sides) hr.append(el('th', 'num', side.ship.name));
  hr.append(el('th', 'num', 'Difference'));
  head.append(hr);

  const body = $('#hangar-compare-table tbody');
  body.textContent = '';
  let group = null;
  for (const r of rows) {
    if (r.group !== group) {
      group = r.group;
      const gr = el('tr', 'compare-group');
      const td = el('td', null, group);
      td.colSpan = 4;
      gr.append(td);
      body.append(gr);
    }
    const tr = el('tr');
    tr.append(el('td', null, r.label));
    const [a, b] = r.values;
    const numeric = typeof a === 'number' && typeof b === 'number';
    const winner = r.better && numeric && a !== b ? ((r.better === 'more') === (a > b) ? 0 : 1) : null;
    r.text.forEach((text, i) => tr.append(el('td', winner === i ? 'num better' : 'num', String(text))));
    // The difference is the second ship against the first, signed, and only
    // where both are numbers - a date or a drive's name has no difference.
    let diff = '—';
    if (numeric && a !== b) {
      const d = b - a;
      const pct = a !== 0 ? ` (${d > 0 ? '+' : '−'}${Math.abs(Math.round((d / a) * 100))}%)` : '';
      // In the row's own unit - a quantum speed differs in km/s, not in the
      // metres per second the sheet keeps; a formatter that needs the whole
      // side (pitch · yaw · roll) falls back to the bare number.
      let amount;
      try { amount = r.format(Math.abs(d)); } catch { amount = fmtSmart(Math.abs(d)); }
      diff = `${d > 0 ? '+' : '−'}${amount}${pct}`;
    }
    tr.append(el('td', 'num muted', diff));
    body.append(tr);
  }

  const missing = sides.filter((s) => !s.sheet).map((s) => s.ship.name);
  const parts = ['Size from the game files; sorties and hours from the logs; the rest recomputed from each hull\'s stock parts by the Garage, with UEX prices where it has them. The better figure for its row is lit - less mass, less signature, more of everything else.'];
  if (missing.length) parts.push(`${missing.join(' and ')}: the community dataset cannot draw ${missing.length === 1 ? 'its' : 'their'} sheet, so only size and use are shown (Settings › community data).`);
  $('#hangar-compare-note').textContent = parts.join(' ');
}

$('#hangar-compare-a')?.addEventListener('change', (e) => chooseHangarComparison(0, e.currentTarget.value));
$('#hangar-compare-b')?.addEventListener('change', (e) => chooseHangarComparison(1, e.currentTarget.value));
$('#hangar-compare-clear')?.addEventListener('click', () => {
  hangarComparison = new Set();
  renderHangar();
  try { renderFleetShips(); } catch { /* as above */ }
});

/** The same global scale can be read in the most useful arrangement for the question at hand. */
function hangarScaleGroups(pictured) {
  const layout = $('#hangar-layout')?.value || 'type';

  if (layout === 'deck') return [['All vehicles', pictured]];

  if (layout === 'size') {
    const bands = [
      ['Under 10 m', (s) => s.length < 10],
      ['10–25 m', (s) => s.length >= 10 && s.length < 25],
      ['25–50 m', (s) => s.length >= 25 && s.length < 50],
      ['50 m+', (s) => s.length >= 50],
    ];
    return bands.map(([title, includes]) => [title, pictured.filter(includes)]);
  }

  return [
    ['Ships', pictured.filter((s) => s.kind === 'Spaceship' || !s.kind)],
    ['Ground vehicles', pictured.filter((s) => s.kind && s.kind !== 'Spaceship')],
  ];
}

function setHangarExportVisible(visible) {
  for (const id of ['hangar-export-png', 'hangar-export-svg']) {
    const button = $(`#${id}`);
    if (button) button.hidden = !visible;
  }
}

/**
 * A saved deck must carry its game pictures with it. Leaving local API URLs in
 * the SVG made a download look right only while Quantum Wake was still open.
 */
async function inlineHangarPictures(svg) {
  const pictures = [...svg.querySelectorAll('image')];
  await Promise.all(pictures.map(async (picture) => {
    const href = picture.getAttribute('href');
    if (!href || href.startsWith('data:')) return;

    const response = await fetch(new URL(href, location.href));
    if (!response.ok) throw new Error(`ship picture -> ${response.status}`);
    picture.setAttribute('href', await blobDataUrl(await response.blob()));
  }));
}

function blobDataUrl(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(reader.error || new Error('could not read ship picture'));
    reader.readAsDataURL(blob);
  });
}

/** Build one self-contained SVG from the visible scale groups. */
async function hangarPictureSvg() {
  const decks = [...document.querySelectorAll('#hangar-canvas .hangar-svg')];
  if (!decks.length) throw new Error('there is no scale deck to export');

  const width = Math.max(...decks.map((deck) => Number(deck.getAttribute('width')) || 0));
  const note = $('#hangar-unsized')?.hidden ? '' : ($('#hangar-unsized')?.textContent || '');
  const groups = decks.map((deck) => ({
    deck,
    title: deck.previousElementSibling?.textContent || 'Vehicles',
    height: Number(deck.getAttribute('height')) || 0,
  }));
  const noteLines = wrapHangarExportText(note, Math.max(50, Math.floor((width - 40) / 7)));
  const height = 28 + groups.reduce((total, group) => total + 28 + group.height + 18, 0)
    + noteLines.length * 16 + (noteLines.length ? 18 : 0);
  const exported = svgEl('svg', {
    xmlns: SVG_NS, width, height, viewBox: `0 0 ${width} ${height}`, role: 'img',
  });
  exported.append(svgEl('title', {}));
  exported.lastChild.textContent = 'Quantum Wake Hangar — fleet to scale';
  exported.append(svgEl('style', {}));
  exported.lastChild.textContent = '.hangar-name{fill:#dcebf7;font-size:11px;font-family:ui-monospace,Consolas,monospace}.hangar-dims{fill:#7691a8;font-size:10px}.hangar-export-heading{fill:#8be7ff;font-size:12px;font-family:ui-monospace,Consolas,monospace;letter-spacing:2px}.hangar-export-note{fill:#7691a8;font-size:11px;font-family:ui-monospace,Consolas,monospace}';
  exported.append(svgEl('rect', { x: 0, y: 0, width, height, fill: '#070c14' }));

  let y = 20;
  for (const group of groups) {
    const heading = svgEl('text', { class: 'hangar-export-heading', x: 20, y });
    heading.textContent = group.title.toUpperCase();
    exported.append(heading);
    y += 8;

    const copy = group.deck.cloneNode(true);
    copy.setAttribute('x', 0);
    copy.setAttribute('y', y);
    await inlineHangarPictures(copy);
    exported.append(copy);
    y += group.height + 28;
  }

  for (const line of noteLines) {
    const text = svgEl('text', { class: 'hangar-export-note', x: 20, y });
    text.textContent = line;
    exported.append(text);
    y += 16;
  }

  return exported;
}

function wrapHangarExportText(text, maxChars) {
  if (!text) return [];
  const lines = [];
  let line = '';
  for (const word of text.split(/\s+/)) {
    if (`${line} ${word}`.trim().length > maxChars && line) {
      lines.push(line);
      line = word;
    } else line = `${line} ${word}`.trim();
  }
  if (line) lines.push(line);
  return lines;
}

function saveHangarBlob(blob, extension) {
  const stamp = new Date().toISOString().slice(0, 10);
  const url = URL.createObjectURL(blob);
  const link = el('a');
  link.href = url;
  link.download = `quantumwake-hangar-${stamp}.${extension}`;
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 30000);
}

async function exportHangarPicture(kind, button) {
  const label = button.textContent;
  button.disabled = true;
  button.textContent = 'Exporting…';

  try {
    const svg = await hangarPictureSvg();
    const source = new Blob([new XMLSerializer().serializeToString(svg)], { type: 'image/svg+xml;charset=utf-8' });

    if (kind === 'svg') {
      saveHangarBlob(source, 'svg');
    } else {
      const url = URL.createObjectURL(source);
      try {
        const image = new Image();
        await new Promise((resolve, reject) => {
          image.onload = resolve;
          image.onerror = () => reject(new Error('could not draw the scale deck'));
          image.src = url;
        });
        const resolution = 2;
        const canvas = document.createElement('canvas');
        canvas.width = Number(svg.getAttribute('width')) * resolution;
        canvas.height = Number(svg.getAttribute('height')) * resolution;
        const context = canvas.getContext('2d');
        context.scale(resolution, resolution);
        context.drawImage(image, 0, 0);
        const png = await new Promise((resolve, reject) => canvas.toBlob(
          (blob) => blob ? resolve(blob) : reject(new Error('could not make the PNG')), 'image/png'));
        saveHangarBlob(png, 'png');
      } finally {
        URL.revokeObjectURL(url);
      }
    }
    button.textContent = 'Saved';
  } catch (error) {
    button.textContent = 'Could not export';
    console.error(error);
  } finally {
    setTimeout(() => { button.textContent = label; button.disabled = false; }, 1800);
  }
}

/** States why a hull is absent from the physical drawing instead of inventing its shape. */
function showScaleOmissions(note, iconless, missing) {
  if (!note || (!iconless.length && !missing.length)) return;

  const parts = [];
  if (iconless.length) {
    const names = iconless.map((s) => `${s.name} (${s.length} × ${s.beam} × ${s.height} m)`);
    parts.push(`No top-down game icon, so not drawn to scale: ${names.join(', ')}.`);
  }
  if (missing.length)
    parts.push(`Not in the install's vehicle table, so not drawn: ${missing.map((s) => s.name).join(', ')}.`);

  note.hidden = false;
  note.textContent = parts.join(' ');
}

/**
 * The gallery: one card per ship, with the game's own render of it in the
 * paint the pilot chose on Fleet, or its silhouette tinted by maker. Not to
 * scale, and the page says which mode it is in - a three-quarter render drawn
 * "to scale" would be a lie, which is what the other mode is for.
 */
function renderHangarGallery(canvas, ships) {
  if (!ships.length) {
    canvas.append(el('p', 'muted', 'No ship has been flown in the logs yet, so there is nothing to show.'));
    return;
  }

  const grid = el('div', 'hangar-gallery');

  for (const ship of ships) {
    const maker = makerOf(ship.name);
    const card = el('article', 'hangar-card');
    card.dataset.className = ship.className;

    if (ship.className) card.append(shipPicture(ship, maker));

    const body = el('div', 'hangar-card-body');
    body.append(el('div', 'hangar-card-name', ship.name));

    const facts = [];
    if (ship.length > 0) facts.push(`${ship.length} × ${ship.beam} × ${ship.height} m`);
    facts.push(`${ship.sorties} sortie${ship.sorties === 1 ? '' : 's'}`);
    if (ship.hours > 0) facts.push(`~${ship.hours} h aboard`);
    body.append(el('div', 'muted', facts.join(' · ')));

    if (!(ship.length > 0)) body.append(el('div', 'muted', 'not in the install\'s vehicle table — no size'));

    // The same offer as the Fleet card, under the same rule: ground vehicles
    // have no ports anyone sells parts for, so the Garage is not offered.
    if (ship.kind === 'Spaceship' || !ship.kind) {
      const garage = el('button', 'ghost ship-upgrade', 'Garage');
      garage.type = 'button';
      garage.title = `${ship.name}'s numbers, what fits it, and what a part would change`;
      garage.addEventListener('click', () => openGarageFor(ship.className || ship.name));
      body.append(garage);
    }
    card.append(body);
    grid.append(card);
  }

  canvas.append(grid);
}

/**
 * One group of ships drawn to one scale: a flow layout, left to right,
 * wrapping when the row is full. Each ship's box is its bounding box in
 * metres times the scale; the silhouette sits inside it, so the drawn
 * footprint is the real one.
 */
function drawToScale(ships, width, scale) {
  const gap = HANGAR_SHIP_GAP;
  const label = 40;

  // Flow layout: left to right, wrapping when the row is full. Each ship's
  // box is its bounding box in metres times the scale; the silhouette sits
  // inside it, so the drawn footprint is the real one.
  let x = 20;
  let y = 20;
  let rowHeight = 0;
  const placed = [];

  for (const ship of ships) {
    const w = Math.max(6, ship.length * scale);
    const h = Math.max(4, ship.beam * scale);
    const cell = Math.max(w, 90);   // room for the name under a small ship

    if (x + cell > width - 20 && x > 20) {
      x = 20;
      y += rowHeight + label + gap;
      rowHeight = 0;
    }

    placed.push({ ship, x, y, w, h, cell });
    rowHeight = Math.max(rowHeight, h);
    x += cell + gap;
  }

  const height = y + rowHeight + label + 20;
  const svg = svgEl('svg', { class: 'hangar-svg', viewBox: `0 0 ${width} ${height}`, width, height, role: 'img' });
  svg.setAttribute('aria-label', 'The fleet drawn to scale');

  for (const { ship, x: sx, y: sy, w, h, cell } of placed) {
    const group = svgEl('g', { class: 'hangar-ship', transform: `translate(${sx} ${sy})` });
    const title = svgEl('title', {});
    group.append(title);
    title.textContent = `${ship.name} · ${ship.length} × ${ship.beam} × ${ship.height} m · ${ship.sorties} sortie${ship.sorties === 1 ? '' : 's'}`
      + (!ship.icon ? ' · Gallery render fitted to this scale box; no top-down icon is installed' : '');

    // Centred in the cell so a small ship's name does not hang off its left edge.
    const offset = (cell - w) / 2;
    const top = (rowHeightOf(placed, sy) - h);   // ships in a row share a baseline

    const paint = hangarPaintFor(ship);
    if (paint) {
      // The picture's perspective does not change the bounding box: the SVG
      // cell remains the installed length and beam, while the finish matches
      // the paint visible on the Gallery card.
      group.append(svgEl('image', {
        href: `/api/fleet/paints/${encodeURIComponent(paint)}/render`,
        x: offset, y: top, width: w, height: h, preserveAspectRatio: 'xMidYMid meet',
      }));
    } else {
      // The game's icon is white; the maker's tint is the app's, and the
      // legend says so. feFlood through SourceAlpha keeps the shape exact.
      const tintId = `hangar-tint-${ship.className.replace(/[^A-Za-z0-9_-]/g, '')}`;
      const filter = svgEl('filter', { id: tintId });
      filter.append(svgEl('feFlood', { 'flood-color': makerTint(makerOf(ship.name).code) }));
      filter.append(svgEl('feComposite', { in2: 'SourceAlpha', operator: 'in' }));
      // The glow rides in the same chain: a CSS filter on the image would win
      // over this attribute and put the tint back to white.
      filter.append(svgEl('feDropShadow', { dx: 0, dy: 0, stdDeviation: 3, 'flood-color': '#35c8f0', 'flood-opacity': 0.3 }));
      group.append(filter);
      group.append(svgEl('image', {
        href: `/api/fleet/icons/${encodeURIComponent(ship.className)}`,
        x: offset, y: top, width: w, height: h, preserveAspectRatio: 'xMidYMid meet',
        filter: `url(#${tintId})`,
      }));
    }

    const baseline = rowHeightOf(placed, sy) + 14;
    const name = svgEl('text', { class: 'hangar-name', x: cell / 2, y: baseline, 'text-anchor': 'middle' });
    name.textContent = ship.name;
    group.append(name);

    const dims = svgEl('text', { class: 'hangar-dims', x: cell / 2, y: baseline + 13, 'text-anchor': 'middle' });
    dims.textContent = `${ship.length} m · ${ship.sorties} sortie${ship.sorties === 1 ? '' : 's'}`
      + (!ship.icon ? ' · gallery render' : '');
    group.append(dims);

    // What the picture is, said on the picture: a top-down icon is the
    // hull's real footprint, a gallery render is a three-quarter view fitted
    // into that footprint's box. In a comparison the two can sit side by
    // side, and a caption under the name is not where the eye is.
    if (hangarComparison.size === 2) {
      const kind = paint ? 'gallery render' : 'top-down icon';
      const badge = svgEl('g', { class: `hangar-source ${paint ? 'render' : 'icon'}`, transform: `translate(${offset + 4} ${top + 4})` });
      badge.append(svgEl('rect', { x: 0, y: 0, width: kind.length * 6.2 + 16, height: 16, rx: 3 }));
      const label = svgEl('text', { x: 8, y: 11.5 });
      label.textContent = kind;
      badge.append(label);
      const why = svgEl('title', {});
      why.textContent = paint
        ? 'The game\'s gallery render of this hull, fitted into its installed bounding box - a three-quarter view, not the footprint.'
        : 'The game\'s own top-down vehicle icon, at the installed bounding box: the real footprint.';
      badge.append(why);
      group.append(badge);
    }

    svg.append(group);
  }


  return svg;
}

/** The tallest ship in the row a ship was placed on, so the row shares one baseline. */
function rowHeightOf(placed, y) {
  return Math.max(...placed.filter((p) => p.y === y).map((p) => p.h));
}

$('#hangar-mode')?.addEventListener('change', () => renderHangar());
$('#hangar-sort')?.addEventListener('change', () => renderHangar());
$('#hangar-zoom')?.addEventListener('change', () => renderHangar());
$('#hangar-layout')?.addEventListener('change', () => renderHangar());
$('#hangar-export-svg')?.addEventListener('click', async (e) => {
  await exportHangarPicture('svg', e.currentTarget);
});
$('#hangar-export-png')?.addEventListener('click', async (e) => {
  await exportHangarPicture('png', e.currentTarget);
});
window.addEventListener('resize', () => {
  // SVG width is fixed at render time. Without rebuilding a visible scale
  // drawing after a window resize, it keeps the old deck width and creates
  // the same horizontal overflow as one first measured while hidden.
  if (hangarShips && $('#view-hangar')?.classList.contains('active')
    && $('#hangar-mode')?.value === 'scale') renderHangar();
});

/* ---- Wikelo's emporium: what he trades, from the game files, against the stash ----
   Every number on this page is the installed patch's. What the page cannot
   know is the pilot's standing with him, so a rank gate is said, not judged. */

const WIKELO_GROUPS = { vehicles: 'Ships & vehicles', favours: 'Favors & the way in', items: 'Armour & weapons' };

let wikeloAll = null;
let wikeloGroup = 'vehicles';
let wikeloGoalId = null;
try {
  wikeloGoalId = localStorage.getItem('qw-wikelo-goal') || null;
} catch { /* private browsing keeps the pin only for this visit */ }

function rememberWikeloGoal(id) {
  wikeloGoalId = id || null;
  try {
    if (wikeloGoalId) localStorage.setItem('qw-wikelo-goal', wikeloGoalId);
    else localStorage.removeItem('qw-wikelo-goal');
  } catch { /* as above */ }
}

async function loadWikelo() {
  const list = $('#wikelo-list');
  if (!list) return;

  try {
    wikeloAll = await getJson('/api/wikelo');
  } catch {
    list.textContent = '';
    list.append(el('p', 'muted', 'Could not load the emporium — is the app still running?'));
    return;
  }

  renderWikelo();
}

function wikeloTrades() {
  return (wikeloAll?.trades || []).filter((t) => !t.retired);
}

function renderWikeloGroups() {
  const row = $('#wikelo-groups');
  if (!row) return;

  row.textContent = '';
  const trades = wikeloTrades();

  for (const [key, label] of Object.entries(WIKELO_GROUPS)) {
    const count = trades.filter((t) => t.group === key).length;
    if (!count) continue;
    const button = el('button', wikeloGroup === key ? 'ghost' : 'ghost off', `${label} · ${count}`);
    button.type = 'button';
    button.dataset.group = key;
    button.addEventListener('click', () => { wikeloGroup = key; renderWikelo(); });
    row.append(button);
  }
}

/** The one trade the pilot chose to keep in view, even after changing groups. */
function renderWikeloGoal(trades) {
  const goal = $('#wikelo-goal');
  if (!goal) return;

  goal.textContent = '';
  const trade = trades.find((t) => t.id === wikeloGoalId);
  if (!trade) {
    if (wikeloGoalId) rememberWikeloGoal(null);
    goal.hidden = true;
    return;
  }

  goal.hidden = false;
  goal.append(el('span', 'strong', 'Current goal'));
  goal.append(el('span', null, trade.title));
  const clear = el('button', 'ghost tiny wikelo-goal-clear', 'Clear');
  clear.type = 'button';
  clear.addEventListener('click', () => { rememberWikeloGoal(null); renderWikelo(); });
  goal.append(clear);
}

function renderWikelo() {
  const list = $('#wikelo-list');
  if (!list) return;

  list.textContent = '';
  renderWikeloGroups();

  const count = $('#wikelo-count');

  if (!wikeloAll?.available) {
    renderWikeloGoal([]);
    if (count) count.textContent = '';
    list.append(el('p', 'muted',
      'The emporium is read from the game files, and this install has not been read yet — '
      + 'Settings says when the game data is ready. Nothing here comes from a website.'));
    return;
  }

  const trades = wikeloTrades();
  renderWikeloGoal(trades);
  const retired = (wikeloAll.trades || []).length - trades.length;
  if (count) {
    count.textContent = `${trades.length} trades`
      + (retired ? ` · ${retired} retired in the file, not shown` : '');
  }

  const query = ($('#wikelo-search')?.value || '').trim().toLowerCase();
  const shown = trades.filter((t) => {
    if (!query && t.group !== wikeloGroup) return false;
    if (!query) return true;
    const haystack = `${t.title} ${t.description} ${t.rewards.map((r) => r.name).join(' ')} `
      + t.requirements.map((r) => r.name).join(' ');
    return haystack.toLowerCase().includes(query);
  });

  if (!shown.length) {
    list.append(el('p', 'muted', query ? 'No trade matches that.' : 'Nothing in this group.'));
    return;
  }

  for (const trade of shown) list.append(wikeloCard(trade));
}

/** The rank a trade needs, in the file's own words with its threshold. */
function wikeloGate(trade) {
  if (!trade.minStanding) return null;
  const standing = (wikeloAll?.standings || []).find((s) => s.id === trade.minStanding);
  return standing ? `${standing.name} (${standing.minReputation.toLocaleString()} rep) or better` : `rank ${trade.minStanding}`;
}

/** One trade's card - new, or redrawn in place once it is tracked, so the message under it survives. */
function wikeloCard(trade, into = null) {
  const card = into || el('article', 'point-card wikelo-card');
  card.textContent = '';
  card.dataset.id = trade.id;
  if (trade.id === wikeloGoalId) card.classList.add('wikelo-current');
  else card.classList.remove('wikelo-current');

  const head = el('div', 'wikelo-head');
  head.append(el('div', 'point-name-read', trade.title));
  const held = trade.requirements.filter((r) => r.have).length;
  head.append(el('div', 'muted', trade.requirements.length
    ? `${held} of ${trade.requirements.length} seen in your stash`
    : ''));
  card.append(head);

  if (trade.description) card.append(el('div', 'muted wikelo-desc', trade.description));

  const gives = el('div', 'wikelo-gives');
  if (trade.rewards.length) {
    gives.append(el('span', 'strong', trade.rewards.map((r) => `${r.count > 1 ? `${r.count}× ` : ''}${r.name}`).join(', ')));
  } else {
    gives.append(el('span', 'muted', 'a reward the file does not name — a blueprint or food pool'));
  }
  if (trade.reputation) gives.append(el('span', 'muted', ` · +${trade.reputation} rep`));
  card.append(gives);

  const gate = wikeloGate(trade);
  if (gate) card.append(el('div', 'muted warn wikelo-gate', `Needs ${gate}. Your standing is not in the logs, so this is a fact about the trade, not about you.`));

  const wants = el('ul', 'wikelo-wants');
  for (const r of trade.requirements) {
    const li = el('li', r.have ? 'have' : 'lack');
    li.append(el('span', 'mark', r.have ? '✓' : '○'));
    li.append(el('span', 'what', `${r.unit === 'SCU' ? `${r.count} SCU` : `${r.count}×`} ${r.name}`));
    if (r.have) li.append(el('span', 'muted', ` · seen at ${r.where.join(', ')}`));
    wants.append(li);
  }
  card.append(wants);

  const actions = el('div', 'point-actions');
  const said = el('span', 'muted point-said');

  const pin = el('button', 'ghost wikelo-pin', trade.id === wikeloGoalId ? 'Current goal' : 'Set current goal');
  pin.type = 'button';
  pin.title = trade.id === wikeloGoalId ? 'Clear this as the current goal' : 'Keep this trade above the emporium while you work on it';
  pin.addEventListener('click', () => {
    rememberWikeloGoal(trade.id === wikeloGoalId ? null : trade.id);
    renderWikelo();
  });
  actions.append(pin);

  if (trade.trackedJobId) {
    const open = el('button', 'ghost wikelo-open', 'Tracking — open the list');
    open.type = 'button';
    open.addEventListener('click', () => showView('jobs'));
    actions.append(open);
  } else {
    const track = el('button', 'ghost wikelo-track', trade.trackedDone ? 'Track again' : 'Track as a goal');
    track.type = 'button';
    track.title = 'Make a shopping list of everything this trade wants';
    track.addEventListener('click', () => trackWikelo(trade, card, track, said));
    actions.append(track);
  }

  actions.append(said);
  card.append(actions);
  return card;
}

async function trackWikelo(trade, card, button, said) {
  button.disabled = true;
  said.textContent = 'Making the list…';

  try {
    const response = await fetch(`/api/wikelo/${encodeURIComponent(trade.id)}/track`, { method: 'POST' });
    const answer = await response.json().catch(() => null);
    if (!response.ok) throw new Error(answer?.trouble || `track -> ${response.status}`);

    // The card alone is redrawn as tracked; the rest of the page keeps its
    // scroll and its search, and the sentence below the button stays put.
    trade.trackedJobId = answer.job?.id || 'tracked';
    wikeloCard(trade, card);
    card.querySelector('.point-said').textContent = answer.existed
      ? 'Already tracking — the list is on Jobs.'
      : 'Listed on Jobs. Pin it there to see it on Now and the MFD.';
    loadJobs().catch(() => {});
  } catch (e) {
    said.textContent = e.message || 'Could not make the list.';
    button.disabled = false;
  }
}

$('#wikelo-search')?.addEventListener('input', () => renderWikelo());

/* ---- Points of interest: the pilot's own marks, and why ----
   Places is what the logs saw. This is what the pilot chose to keep - exact
   coordinates copied from /showlocation, which the game never names - and the
   one thing no log line carries: the reason anyone was there. */

/** The categories a point can carry; one list, so the Log aside and this page never disagree. */
const POINT_CATEGORIES = ['General', 'Navigation', 'Mining', 'Salvage', 'Meet point'];

let pointsAll = [];
/** null is every category; the chips narrow it. */
let pointsCategory = null;
/** Where the pilot last copied a location, and every point measured from it; null until one has been. */
let pointsFrom = null;

async function loadPoints() {
  await loadOwnPoints();
  renderSharedPoints().catch(() => {});
}

/** The pilot's own points, and the distances; the shared block is left as it stands. */
async function loadOwnPoints() {
  const list = $('#points-list');
  if (!list) return;

  try {
    pointsAll = await getJson('/api/screen/pins');
  } catch {
    list.textContent = '';
    list.append(el('p', 'muted', 'Could not load your points — is the app still running?'));
    return;
  }

  // The distances are a second answer and the page stands without them: a
  // card with no "from here" line is a card, not a failure.
  try {
    const here = await getJson('/api/screen/pins/nearest');
    pointsFrom = here?.from ? { from: here.from, byId: new Map(here.points.map((p) => [p.sourceAt, p])) } : null;
  } catch {
    pointsFrom = null;
  }

  // A category that no longer has a point would filter the page to nothing
  // with no chip to click back out of.
  if (pointsCategory && !pointsAll.some((pin) => (pin.category || 'General') === pointsCategory))
    pointsCategory = null;

  renderPoints();
}

function pointName(pin) {
  return pin.label || [pin.system, pin.believed].filter(Boolean).join(' > ') || 'Copied location';
}

/** The session the copy fell inside, when the library has one that spans it. */
function sessionAround(iso) {
  const at = new Date(iso).getTime();
  return (allSessions || []).find((s) =>
    new Date(s.startedAt).getTime() <= at && at <= new Date(s.endedAt).getTime()) || null;
}

function renderPointCategories() {
  const row = $('#points-categories');
  if (!row) return;

  row.textContent = '';

  const counts = new Map();
  for (const pin of pointsAll) {
    const category = pin.category || 'General';
    counts.set(category, (counts.get(category) || 0) + 1);
  }

  // One category is not a choice.
  if (counts.size < 2) return;

  const chip = (label, category) => {
    const on = pointsCategory === category;
    const button = el('button', on ? 'ghost' : 'ghost off', label);
    button.type = 'button';
    button.dataset.category = category ?? '';
    button.addEventListener('click', () => {
      pointsCategory = category;
      renderPoints();
    });
    row.append(button);
  };

  chip(`All · ${pointsAll.length}`, null);
  for (const [category, count] of [...counts].sort((a, b) => a[0].localeCompare(b[0])))
    chip(`${category} · ${count}`, category);
}

/** A distance in the unit a pilot would say it in: metres up close, kilometres in the main, gigametres across a system. */
function distanceWord(metres) {
  const m = Number(metres) || 0;
  if (m < 1000) return `${Math.round(m).toLocaleString()} m`;
  if (m < 1e9) return `${(m / 1000).toLocaleString(undefined, { maximumFractionDigits: m < 1e5 ? 1 : 0 })} km`;
  return `${(m / 1e9).toFixed(3)} Gm`;
}

/**
 * One saved point at a distance. Across two systems the number is arithmetic
 * on two unrelated frames - the same coordinates mean different places in
 * Stanton and Pyro - so it is named as not comparable rather than printed
 * as a range.
 */
function nearPointLine(near) {
  const line = el('div', 'near-point');
  line.append(el('span', 'strong', near.label));
  if (near.sameSystem) {
    line.append(el('span', null, ` · ${distanceWord(near.metres)}`));
  } else {
    line.append(el('span', 'muted',
      ` · ${near.system ? `in ${near.system}` : 'system unknown'} — a different frame, so no distance can be given`));
  }
  return line;
}

/** Where the last copy was, in words: when, and where the logs put it. */
function renderPointsFromHere() {
  const box = $('#points-from');
  if (!box) return;

  box.textContent = '';
  box.hidden = !pointsFrom || !pointsAll.length;
  if (box.hidden) return;

  const from = pointsFrom.from;
  const placed = [from.system, from.believed].filter(Boolean).join(' › ');
  box.append(el('span', null,
    `Distances are from where you last copied a location — ${dateOf(from.at)}, ${shortTimeOf(from.at)}`
    + `${placed ? `, believed to be ${placed}` : ', which the logs could not place'}. `));
  box.append(el('span', 'muted', 'Copy a new /showlocation in the game and they move with you.'));
}

function renderPoints() {
  const list = $('#points-list');
  if (!list) return;

  renderPointCategories();
  renderPointsFromHere();
  list.textContent = '';

  const count = $('#points-count');
  if (count) count.textContent = pointsAll.length ? `${pointsAll.length} kept` : '';

  if (!pointsAll.length) {
    list.append(el('p', 'muted',
      'No points yet. Copy a /showlocation in the game, then pin it from the Log — it lands here with room for a note.'));
    return;
  }

  const query = ($('#points-search')?.value || '').trim().toLowerCase();
  const shown = pointsAll.filter((pin) => {
    if (pointsCategory && (pin.category || 'General') !== pointsCategory) return false;
    if (!query) return true;
    const haystack = `${pointName(pin)} ${pin.note || ''} ${pin.category || ''} ${pin.system || ''} ${pin.believed || ''}`.toLowerCase();
    return haystack.includes(query);
  });

  if (!shown.length) {
    list.append(el('p', 'muted', 'No point matches that.'));
    return;
  }

  for (const pin of shown) list.append(renderPointCard(pin));
}

/**
 * What the app thought the place was when the copy happened, and what that
 * rested on. A /showlocation names no system, so this line is the only thing
 * that places the numbers - and it is a belief, graded by its evidence: an
 * arrival four minutes before the copy is not a quantum jump forty minutes
 * before it, and the line says which rather than hiding both behind a word.
 */
function pointBeliefLine(pin) {
  const line = el('span', 'point-belief');

  if (pin.systemByPilot) {
    line.append(el('span', null, `in ${pin.system}, as you set it`));
    if (pin.believed) line.append(el('span', 'muted', ` · the logs had said ${pin.believed}`));
    return line;
  }

  const believed = [pin.system, pin.believed].filter(Boolean).join(' › ');
  if (!believed) {
    line.append(el('span', 'warn', 'the logs could not place this copy — set the system above'));
    return line;
  }

  line.append(el('span', null, `believed to be ${believed} when copied`));

  if (pin.believedBy && pin.believedAt) {
    const minutes = Math.max(0, Math.round((new Date(pin.sourceAt) - new Date(pin.believedAt)) / 60000));
    const ago = minutes < 1 ? 'moments' : minutes < 120 ? `${minutes} min` : `${Math.round(minutes / 60)} h`;
    const basis = pin.believedBy === 'Jump'
      ? `a quantum jump ${ago} earlier — where the ship was going, not that it arrived`
      : `a location signal ${ago} earlier`;
    line.append(el('span', 'muted', `, from ${basis}`));
  } else {
    line.append(el('span', 'muted', ', on evidence this copy did not record'));
  }

  return line;
}

/** One card - new, or after a save redrawn in place so its neighbours keep their typing. */
function renderPointCard(pin, into = null) {
  const card = into || el('article', 'point-card');
  card.textContent = '';
  card.classList.remove('dirty');
  card.dataset.sourceAt = pin.sourceAt;

  const head = el('div', 'point-head');
  const name = document.createElement('input');
  name.type = 'text';
  name.className = 'search point-name';
  name.value = pin.label || '';
  name.placeholder = pointName(pin);
  name.setAttribute('aria-label', 'Point name');
  const category = document.createElement('select');
  category.className = 'select point-category';
  category.setAttribute('aria-label', 'Point category');
  for (const choice of POINT_CATEGORIES) category.append(new Option(choice, choice));
  category.value = POINT_CATEGORIES.includes(pin.category) ? pin.category : 'General';

  // The system is the pilot's to say. The coordinates are relative to it, so
  // a point without one means nothing - and the app's belief is inferred,
  // sometimes wrong and sometimes absent.
  const system = document.createElement('select');
  system.className = 'select point-system';
  system.setAttribute('aria-label', 'Which system this point is in');
  system.title = pin.systemByPilot ? 'The system, as you set it' : 'The system, as the logs believed it - change it if they were wrong';
  system.append(new Option('System?', ''));
  const systems = Object.keys(SYSTEMS);
  if (pin.system && !systems.includes(pin.system)) systems.push(pin.system);
  for (const choice of systems) system.append(new Option(choice, choice));
  system.value = pin.system || '';

  head.append(name, system, category);
  card.append(head);

  // Where, in the game's own numbers, and what the app believed the place
  // was when the copy happened - a belief, and said to be one.
  const facts = el('div', 'point-facts muted');
  facts.append(el('span', 'mono',
    `x ${Math.round(pin.x).toLocaleString()} · y ${Math.round(pin.y).toLocaleString()} · z ${Math.round(pin.z).toLocaleString()}`));
  facts.append(el('span', null, `${Number(pin.gigametres).toFixed(4)} Gm from system centre`));
  facts.append(pointBeliefLine(pin));
  card.append(facts);

  // From wherever the pilot last copied, when there is such a place.
  const near = pointsFrom?.byId.get(pin.sourceAt);
  if (near) {
    const here = el('div', 'point-here');
    here.append(near.sameSystem
      ? el('span', null, `${distanceWord(near.metres)} from where you last copied`)
      : el('span', 'muted', 'not measurable from where you last copied — a different system, so a different frame'));
    card.append(here);
  }

  const when = el('div', 'point-when muted');
  when.append(el('span', null, `Copied ${dateOf(pin.sourceAt)}, ${shortTimeOf(pin.sourceAt)}`));
  const session = sessionAround(pin.sourceAt);
  if (session) {
    const open = el('button', 'link', `during the session of ${dateOf(session.startedAt)}${session.primaryShip ? ` · ${session.primaryShip}` : ''}`);
    open.type = 'button';
    open.title = 'Open that session';
    open.addEventListener('click', () => {
      showView('sessions');
      if (expandedSessionId !== session.id) toggleSessionDebrief(session.id).catch(() => {});
    });
    when.append(el('span', null, ' · '), open);
  } else {
    when.append(el('span', null, ' · no session in the library spans that moment'));
  }
  card.append(when);

  const note = document.createElement('textarea');
  note.className = 'point-note';
  note.rows = 3;
  note.maxLength = 2000;
  note.value = pin.note || '';
  note.placeholder = 'Why were you there? What is here, who you met, what to bring next time…';
  note.setAttribute('aria-label', 'Why you were there');
  card.append(note);

  const actions = el('div', 'point-actions');
  const said = el('span', 'muted point-said');
  const save = el('button', 'ghost point-save', 'Save');
  save.type = 'button';
  save.addEventListener('click', () => savePoint(pin, card, {
    label: name.value,
    category: category.value,
    note: note.value,
    // Sent only when changed: an unchanged select would otherwise mark the
    // logs' own belief as the pilot's word.
    system: system.value !== (pin.system || '') ? system.value : null,
  }, save, said));

  const copy = el('button', 'ghost point-copy', 'Copy coordinates');
  copy.type = 'button';
  copy.title = 'Copy x y z to the clipboard';
  copy.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(`${pin.x} ${pin.y} ${pin.z}`);
      said.textContent = 'Coordinates copied.';
    } catch {
      said.textContent = 'The browser would not let the page write to the clipboard.';
    }
  });

  const remove = el('button', 'ghost danger point-remove', 'Remove');
  remove.type = 'button';
  remove.title = 'Forget this point; the copied reading it came from stays in the Log';
  remove.addEventListener('click', () => removePoint(pin, remove, said));

  actions.append(save, copy, remove, said);
  card.append(actions);

  // Typing marks the card so an unsaved reason is visible as such.
  for (const field of [name, system, category, note])
    field.addEventListener('input', () => card.classList.add('dirty'));

  return card;
}

async function savePoint(pin, card, fields, button, said) {
  button.disabled = true;
  said.textContent = 'Saving…';

  try {
    const response = await fetch('/api/screen/pins', {
      method: 'PUT', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ sourceAt: pin.sourceAt, ...fields }),
    });
    if (!response.ok) throw new Error(`pin update -> ${response.status}`);

    const saved = await response.json();
    pointsAll = pointsAll.map((p) => (p.sourceAt === pin.sourceAt ? saved : p));

    // Only this card is redrawn. Redrawing the list would throw away a note
    // half-typed on the card beside it, and there is no undo for that. The
    // category chips do get redrawn, since a save can move a point between them.
    renderPointCard(saved, card);
    card.querySelector('.point-said').textContent = 'Saved.';
    renderPointCategories();

    // The Log aside shows the same points, and is cheap to keep honest.
    renderScreenLog().catch(() => {});
  } catch {
    said.textContent = 'Could not save — is the app still running?';
    button.disabled = false;
  }
}

async function removePoint(pin, button, said) {
  button.disabled = true;

  try {
    const response = await fetch(`/api/screen/pins?at=${encodeURIComponent(pin.sourceAt)}`, { method: 'DELETE' });
    if (!response.ok) throw new Error(`unpin -> ${response.status}`);

    pointsAll = pointsAll.filter((p) => p.sourceAt !== pin.sourceAt);
    renderPoints();
    renderScreenLog().catch(() => {});
  } catch {
    said.textContent = 'Could not remove that point.';
    button.disabled = false;
  }
}

$('#points-search')?.addEventListener('input', () => renderPoints());

/**
 * Points other pilots sent, under the pilot's own. Read-only: they are
 * somebody else's marks, kept apart so removing the file takes them away and
 * leaves your own untouched. "Keep as mine" copies one across, deliberately.
 *
 * Unlike the blueprints page this one says when shared points are being
 * hidden by the imports filter: a friend's points are the whole reason to
 * open the file, and a page that silently showed none would read as the
 * import having failed.
 */
async function renderSharedPoints() {
  const host = $('#points-shared');
  if (!host) return;

  host.textContent = '';

  const rows = await getJson(`/api/imports/points${importedQuery()}`).catch(() => []);
  if (!rows.length) return;

  if (showImported === 'none') {
    const line = el('p', 'muted');
    line.append(el('span', null,
      `${rows.length} point${rows.length === 1 ? '' : 's'} from files you were sent ${rows.length === 1 ? 'is' : 'are'} not shown. `));
    const show = el('button', 'ghost tiny', 'Show them');
    show.addEventListener('click', () => setShowImported('all'));
    line.append(show);
    host.append(line);
    return;
  }

  const block = el('section', 'shared-block');
  block.append(el('h3', null, 'Shared by others'));
  block.append(el('p', 'muted', 'Points from the files you were sent. The coordinates are exact; '
    + 'the system is what the sender\'s logs believed unless they set it themselves, and the '
    + 'note is theirs. Keep one and it becomes your own point, backed up and edited like the rest.'));

  const list = el('div', 'points-list');
  for (const row of rows) list.append(sharedPointCard(row));
  block.append(list);
  host.append(block);
}

function sharedPointCard(row) {
  const card = el('article', 'point-card shared');

  const head = el('div', 'point-head shared');
  head.append(el('div', 'point-name-read', row.label));
  head.append(el('div', 'muted', `${row.category || 'General'} · from ${row.imported?.handle || 'someone'}`));
  card.append(head);

  const facts = el('div', 'point-facts muted');
  facts.append(el('span', 'mono',
    `x ${Math.round(row.x).toLocaleString()} · y ${Math.round(row.y).toLocaleString()} · z ${Math.round(row.z).toLocaleString()}`));
  facts.append(el('span', null, `${Number(row.gigametres).toFixed(4)} Gm from system centre`));
  if (row.system) {
    facts.append(el('span', null, row.systemByPilot
      ? `in ${row.system}, as they set it`
      : `in ${row.system}, as their logs believed${row.believed ? ` (near ${row.believed})` : ''}`));
  } else {
    facts.append(el('span', 'warn', 'system unknown — their logs could not place it'));
  }
  card.append(facts);

  if (row.metres != null) {
    const here = el('div', 'point-here');
    here.append(row.sameSystem
      ? el('span', null, `${distanceWord(row.metres)} from where you last copied`)
      : el('span', 'muted', 'not measurable from where you last copied — a different system, so a different frame'));
    card.append(here);
  }

  card.append(el('div', 'point-when muted', `They copied it ${dateOf(row.at)}, ${shortTimeOf(row.at)}`));
  if (row.note) card.append(el('div', 'pin-note', row.note));

  const actions = el('div', 'point-actions');
  const said = el('span', 'muted point-said');
  const keep = el('button', 'ghost point-keep', 'Keep as mine');
  keep.type = 'button';
  keep.title = 'Copy this point into your own, with a note saying who shared it';
  keep.addEventListener('click', async () => {
    keep.disabled = true;
    try {
      const response = await fetch(
        `/api/imports/${encodeURIComponent(row.imported.id)}/points/keep?at=${encodeURIComponent(row.at)}`,
        { method: 'POST' });
      const answer = await response.json().catch(() => null);
      if (!response.ok) throw new Error(answer?.trouble || `keep -> ${response.status}`);
      said.textContent = 'Kept — it is in your points above.';
      loadOwnPoints().catch(() => {});
    } catch (e) {
      said.textContent = e.message || 'Could not keep that point.';
      keep.disabled = false;
    }
  });
  actions.append(keep, said);
  card.append(actions);

  return card;
}

/** One Fleet Manager row: the ship, or the reading when the terminal's face beat the engine. */
function fleetRow(row) {
  const li = el('li');
  li.append(el('span', 'what', row.ship || `read as “${row.read}”`));

  const facts = [];
  if (row.location) facts.push(`at ${row.location}`);
  if (row.state) facts.push(row.state.toLowerCase());
  if (row.focus) facts.push(row.focus);
  if (row.cargo != null) facts.push(`${row.cargo} SCU`);
  if (facts.length) li.append(el('span', 'd', ` · ${facts.join(' · ')}`));

  if (!row.ship && row.looksLike?.length)
    li.append(el('span', 'd', ` · looks like ${row.looksLike.join(' or ')}`));

  return li;
}

/** The newest reading where a pilot is looking while they play. */
function renderNowScreenCard(s) {
  const card = $('#now-screen-card');
  if (!card) return;

  if (!s) {
    card.hidden = true;
    return;
  }

  card.hidden = false;

  // The log is not polled, so a reading arriving on the stream is what tells
  // it to redraw - and only when somebody is looking at it. The shot is marked
  // seen here rather than left to the redraw: renderScreenLog gives up quietly
  // when the fetch fails, and a shot that stayed unseen would ask again on
  // every frame of the stream, once a second, for as long as the page was open.
  if (s.shot !== screenLatestShot && $('#view-overlay')?.classList.contains('active')) {
    screenLatestShot = s.shot;
    renderScreenLog().catch(() => {});
  }

  // The cash card is drawn once, at boot, and a kiosk photographed since is
  // exactly the thing it is waiting for. Only a frame whose wallet actually
  // read moves it, and only once per frame.
  if (s.shot !== ledgerWalletShot
    && (s.checks || []).some((c) => c.subject === 'Wallet' && c.verdict !== 'unchecked')) {
    ledgerWalletShot = s.shot;
    loadLedgerWallet().catch(() => {});
  }

  $('#now-screen-summary').textContent = s.summary;
  $('#now-screen-when').textContent =
    `${SCREEN_KINDS[s.kind] || s.kind} · ${new Date(s.shotAt).toLocaleTimeString()} · ${s.shot}`;

  const checks = $('#now-screen-checks');
  checks.textContent = '';
  for (const check of s.checks || []) checks.append(screenCheckRow(check));

  const differs = (s.checks || []).filter((c) => c.verdict === 'differs').length;

  $('#now-screen-note').textContent =
    differs ? `${differs} thing${differs === 1 ? '' : 's'} the screen and the logs disagree on.`
    : (s.checks || []).length ? 'The logs and the screen agree on everything checked.'
    : 'Nothing on this screen the logs could be checked against.';
}

/**
 * What each ship was last photographed carrying, on the fleet page.
 *
 * Dated, every time: a screenshot is a moment and not a state, and a loadout
 * from last week shown as the loadout is lying by a week.
 */
async function renderFleetFittings() {
  const title = $('#fleet-fittings-title');
  const caption = $('#fleet-fittings-caption');
  const grid = $('#fleet-fittings');
  if (!grid) return;

  let ships = [];

  try {
    ships = await getJson('/api/screen/fittings');
  } catch {
    ships = [];
  }

  photographedFleetShips = ships
    .filter((ship) => ship.ship)
    .map((ship) => ({
      name: ship.ship,
      className: ship.className || '',
      sorties: 0,
      estimatedTime: '00:00:00',
      lastFlown: null,
      photographedAt: ship.shotAt
    }));
  if (libraryStats) renderFleet(libraryStats);

  grid.textContent = '';
  const any = ships.length > 0;
  if (title) title.hidden = !any;
  if (caption) caption.hidden = !any;

  renderFleetBerths().catch(() => {});

  if (!any) return;

  for (const s of ships) {
    const card = el('article', 'ship-card');
    card.append(el('div', 'strong', s.ship));
    card.append(el('div', 'muted', `as photographed ${new Date(s.shotAt).toLocaleString()}`));
    if (s.scope) card.append(el('div', 'muted', s.scope));

    const list = el('ul', 'feed screen-fittings');

    for (const f of s.fittings || []) {
      const li = el('li');
      li.append(el('span', 'what', f.slot));

      if (f.nothingRead) li.append(el('span', 'd', ' · nothing read under it'));
      else if (f.name) {
        li.append(el('span', 'd', ` · ${f.name}`));
        if (f.stock === false) li.append(el('span', 'k differs', 'not stock'));
        if (f.stock === true) li.append(el('span', 'k agrees', 'stock'));
      } else li.append(el('span', 'd', ` · read “${f.read}”, matched nothing`));

      list.append(li);
    }

    card.append(list);
    grid.append(card);
  }
}

/**
 * Where each ship was, the last time the Fleet Manager was photographed.
 *
 * Nothing in the logs says where a ship is stored, so this is the only
 * source, and it is dated for the same reason the fittings are.
 */
async function renderFleetBerths() {
  const title = $('#fleet-berths-title');
  const list = $('#fleet-berths');
  if (!list) return;

  let got = { ships: [] };

  try {
    got = await getJson('/api/screen/fleet');
  } catch {
    got = { ships: [] };
  }

  list.textContent = '';
  const rows = got.ships || [];
  if (title) title.hidden = rows.length === 0;
  if (!rows.length) return;

  list.append(el('p', 'muted', `As photographed ${new Date(got.shotAt).toLocaleString()} · ${got.shot}`));

  const feed = el('ul', 'feed screen-fittings');
  for (const row of rows) feed.append(fleetRow(row));
  list.append(feed);

  // A ship the terminal lists that the logs never saw fly has no card above -
  // the cards are sorties - so it gets one here that says exactly that, with
  // the terminal's word on where it is and the Garage a click away. Without
  // this the Ironclad was in the reading and on no card anywhere.
  const unflown = rows.filter((row) => row.ship && !row.flown);
  if (!unflown.length) return;

  list.append(el('h3', 'spaced', `Owned, never flown in the logs · ${unflown.length}`));
  list.append(el('p', 'muted caption', 'Listed at the Fleet Manager and never seen aboard in a session: no sorties, no hours, no photographed fit. The numbers a card would carry are all zero, so it carries the terminal\'s instead.'));
  const grid = el('div', 'ship-grid');
  for (const row of unflown) {
    const card = el('article', 'ship-card unflown');
    const maker = makerOf(row.ship);
    if (row.className) card.append(shipPicture({ name: row.ship, className: row.className }, maker));
    const body = el('div', 'ship-body');
    body.append(el('div', 'ship-name', row.ship));
    const facts = [row.location ? `at ${row.location}` : null, row.state ? row.state.toLowerCase() : null, row.focus, row.cargo != null ? `${row.cargo} SCU` : null].filter(Boolean);
    body.append(el('div', 'ship-ref muted', facts.join(' · ') || 'no berth read'));
    body.append(el('div', 'ship-ref muted', 'never flown in the logs'));
    if (row.className) {
      const garage = el('button', 'ghost ship-upgrade', 'Garage');
      garage.type = 'button';
      garage.title = `${row.ship}'s numbers, what fits it, and what a part would change`;
      garage.addEventListener('click', () => openGarageFor(row.className));
      body.append(garage);
    }
    card.append(body);
    grid.append(card);
  }
  list.append(grid);
}

$('#screen-log-refresh')?.addEventListener('click', () => {
  (logPane === 'files' ? loadScanHistory() : renderScreenLog()).catch(() => {});
});

/* ---------- controls: sticks, bindings, backups ---------- */

/**
 * The Controls page reads the game's keybinding profile against the
 * catalogue the archive holds, and draws each stick's bindings on a
 * picture of it. The picture is a Joystick Diagrams template: an SVG with
 * a photograph and text placeholders - Button_7, POV_1_U, AXIS_X - where
 * the controls are, so drawing the bindings is writing the action's name
 * into the right text node. Nothing else about the picture is understood.
 */
let controlsModel = null;
let controlsPane = 'devices';
let controlsDevice = null;
try { controlsDevice = localStorage.getItem('qw-controls-stick') || null; } catch { /* fine */ }
let controlsBackups = [];
let controlsDiffPick = [];
let controlsExportSource = null;
const CONTROLS_PANES = ['devices', 'actions', 'backups', 'pictures', 'check'];
let controlsChecklistPins = [];

try {
  const kept = localStorage.getItem('qw-controls-pane');
  if (CONTROLS_PANES.includes(kept)) controlsPane = kept;
} catch { /* a private window has no memory, which is fine */ }

try {
  const kept = JSON.parse(localStorage.getItem('qw-controls-checklist-pins') || '[]');
  if (Array.isArray(kept)) controlsChecklistPins = kept.filter((p) => p && p.actionMap && p.action);
} catch { /* an older or private browser starts with an empty checklist */ }

function controlsSaveChecklistPins() {
  try { localStorage.setItem('qw-controls-checklist-pins', JSON.stringify(controlsChecklistPins)); }
  catch { /* the checklist remains useful for this visit when storage is off */ }
}

function showControlsPane(name) {
  if (!CONTROLS_PANES.includes(name)) name = 'devices';
  controlsPane = name;
  try { localStorage.setItem('qw-controls-pane', name); } catch { /* as above */ }
  for (const pane of CONTROLS_PANES) $(`#controls-pane-${pane}`)?.classList.toggle('active', pane === name);
  for (const button of $('#controls-tabs')?.querySelectorAll('button') || [])
    button.classList.toggle('active', button.dataset.pane === name);
  if (name === 'backups') loadControlsBackups().catch(() => {});
  if (name === 'check') loadControlsCheck().catch(() => {});
  if (name === 'devices' && controlsModel?.ready) controlsLiveStart(); else controlsLiveStop();
}

$('#controls-tabs')?.addEventListener('click', (e) => {
  const button = e.target.closest('button[data-pane]');
  if (button) showControlsPane(button.dataset.pane);
});

async function loadControls() {
  const unready = $('#controls-unready');
  try {
    controlsModel = await getJson('/api/controls');
  } catch {
    controlsModel = null;
  }

  const panes = [...CONTROLS_PANES.map((p) => $(`#controls-pane-${p}`)), $('#controls-tabs')];
  if (!controlsModel) {
    for (const p of panes) if (p) p.hidden = true;
    if (unready) { unready.hidden = false; unready.textContent = 'The controls could not be read.'; }
    return;
  }
  if (!controlsModel.ready) {
    for (const p of panes) if (p) p.hidden = true;
    if (unready) {
      unready.hidden = false;
      unready.textContent = gameDataExcuse() || 'The install has not been read yet - Settings says when the game data is ready.';
    }
    return;
  }
  if (unready) unready.hidden = true;
  for (const p of panes) if (p) p.hidden = false;

  const status = $('#controls-status');
  if (status) {
    const m = controlsModel;
    status.textContent = m.profileFound
      ? `${m.profile.devices.filter((d) => d.type === 'joystick' && d.product).length} sticks and ${m.profile.bindings.filter((b) => b.input.device === 'js' && b.input.kind !== 'none').length} joystick bindings in the game's profile · ${m.catalogue.actions.length} actions the game can bind · ${m.backupCount} version${m.backupCount === 1 ? '' : 's'} kept${m.backups ? `, the latest written ${relative(m.backups.writtenAt)}` : ''}.`
      : m.problem
        ? `The game's profile could not be read: ${m.problem}`
        : 'The game has not written a keybinding profile yet - it appears after the first time the keybinding screen is used.';
  }

  renderControlsDevices();
  renderControlsActions();
  renderControlsPictures();
  renderControlsPending();
  showControlsPane(controlsPane);
}

/* ---------- the sticks ---------- */

/** The joysticks the profile knows, with a product; empty instances are not sticks. */
function controlsSticks() {
  return (controlsModel?.profile?.devices || []).filter((d) => d.type === 'joystick' && d.product);
}

function renderControlsDevices() {
  const strip = $('#controls-devices');
  if (!strip) return;
  strip.textContent = '';
  const sticks = controlsSticks();
  if (!sticks.length) {
    strip.append(el('p', 'muted', controlsModel?.profileFound
      ? 'The profile names no joystick. Bind something to a stick in the game and it appears here.'
      : 'No profile yet.'));
    $('#controls-device').hidden = true;
    return;
  }
  if (!sticks.some((d) => d.key === controlsDevice)) controlsDevice = sticks[0].key;
  for (const d of sticks) {
    const button = el('button', `controls-stick${d.key === controlsDevice ? ' active' : ''}`);
    button.type = 'button';
    button.append(el('span', 'controls-stick-key', d.key));
    button.append(el('span', 'controls-stick-name', d.product));
    button.append(el('span', 'controls-stick-count muted', `${d.bindings} bound`));
    button.addEventListener('click', () => {
      controlsDevice = d.key;
      try { localStorage.setItem('qw-controls-stick', d.key); } catch { /* fine */ }
      renderControlsDevices();
    });
    strip.append(button);
  }
  renderControlsDevice();
}

/**
 * A template's placeholder for an input, and back: Button_7 is button7,
 * POV_1_U is hat1_up, AXIS_RZ is rotz. Joystick Diagrams' spelling, since
 * the pictures are theirs.
 */
const CONTROLS_AXIS_NAMES = { x: 'x', y: 'y', z: 'z', rx: 'rotx', ry: 'roty', rz: 'rotz', slider1: 'slider1', slider_1: 'slider1', slider2: 'slider2', slider_2: 'slider2' };
const CONTROLS_HAT_DIRS = { u: 'up', d: 'down', l: 'left', r: 'right' };

function controlsPlaceholderToControl(text) {
  const t = String(text || '').trim();
  let m = /^button_(\d+)$/i.exec(t);
  if (m) return `button${Number(m[1])}`;
  m = /^pov_(\d+)_([udlr])$/i.exec(t);
  if (m) return `hat${Number(m[1])}_${CONTROLS_HAT_DIRS[m[2].toLowerCase()]}`;
  m = /^axis_([a-z]+_?\d?)$/i.exec(t);
  if (m) return CONTROLS_AXIS_NAMES[m[1].toLowerCase()] || m[1].toLowerCase();
  return null;
}

/** The bindings on one stick, keyed by control, each a list (a button can do two things in two modes). */
function controlsBindingsOf(deviceKey, bindings) {
  const map = new Map();
  for (const b of bindings || []) {
    if (b.input.deviceKey !== deviceKey || b.input.kind === 'none') continue;
    // A chord is listed under its final control, with the modifier in the label.
    const key = b.input.control;
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(b);
  }
  return map;
}

function controlsBindingWords(b) {
  const held = b.input.modifiers?.length ? `${b.input.modifiers.map((m) => controlsShortInput(m)).join(' + ')} + ` : '';
  return `${held}${b.label}`;
}

/** "js2 button 5" for a modifier's raw input. */
function controlsShortInput(raw) {
  const m = /^js(\d+)_button(\d+)$/i.exec(raw);
  if (m) return `button ${m[2]}`;
  return raw.replace(/^[a-z]{2}\d+_/, '');
}

function controlsModeWord(mode) {
  return { tap: 'tap', hold: 'hold', press: 'press', double_tap: 'double tap', double_tap_nonblocking: 'double tap', delayed_press: 'long press', delayed_press_long: 'long press', delayed_press_medium: 'long press', delayed_press_quicker: 'long press', tap_quicker: 'tap', press_quicker: 'press', hold_no_retrigger: 'hold', all: '' }[mode] ?? (mode || '');
}

async function renderControlsDevice() {
  const box = $('#controls-device');
  const device = controlsSticks().find((d) => d.key === controlsDevice);
  if (!box || !device) { if (box) box.hidden = true; return; }
  box.hidden = false;

  $('#controls-device-title').textContent = `${device.product} · ${device.key}`;
  const usb = device.usb ? `USB ${device.usb.vendor.toString(16).padStart(4, '0')}:${device.usb.product.toString(16).padStart(4, '0')}` : 'no USB id';
  $('#controls-device-note').textContent = `${usb} · ${device.guid || ''}`;

  // The layout the game ships for this stick, beside the pilot's, if any.
  const select = $('#controls-layout');
  const keep = select?.value;
  if (select) {
    select.textContent = '';
    select.append(new Option(device.layouts?.length ? 'Nothing' : 'The game ships no layout for this stick', ''));
    for (const file of device.layouts || []) {
      const layout = controlsModel.layouts.find((l) => l.file === file);
      select.append(new Option(layout?.name || file, file));
    }
    select.disabled = !(device.layouts?.length);
    select.value = (device.layouts || []).includes(keep) ? keep : '';
  }

  const bound = controlsBindingsOf(device.key, controlsModel.profile.bindings);
  let reference = null;
  if (select?.value) {
    try {
      const layout = await getJson(`/api/controls/layouts/${encodeURIComponent(select.value)}`);
      // The layout names the stick by its own instance; match it by product.
      const theirs = (layout.devices || []).find((d) => d.guid && device.guid && d.guid.toLowerCase() === device.guid.toLowerCase());
      if (theirs) reference = controlsBindingsOf(theirs.key, layout.bindings);
    } catch { reference = null; }
  }
  $('#controls-layout-head').hidden = !reference;

  // The table: every control the picture names, then anything bound that
  // the picture does not name, so nothing bound is ever hidden.
  const svgControls = await renderControlsPicture(device, bound);
  const q = ($('#controls-search')?.value || '').trim().toLowerCase();
  const controls = [...svgControls];
  for (const key of bound.keys()) if (!controls.includes(key)) controls.push(key);
  if (reference) for (const key of reference.keys()) if (!controls.includes(key)) controls.push(key);
  controls.sort(controlsControlOrder);

  const body = $('#controls-buttons tbody');
  body.textContent = '';
  let shown = 0;
  for (const control of controls) {
    const here = bound.get(control) || [];
    const there = reference?.get(control) || [];
    const words = here.map((b) => `${controlsBindingWords(b)} ${b.map}`).join(' ');
    if (q && !`${control} ${words}`.toLowerCase().includes(q)) continue;
    shown++;
    const tr = el('tr', here.length ? null : 'controls-unbound');
    tr.dataset.control = control;
    tr.append(el('td', 'controls-control', controlsControlLabel(control)));
    const to = el('td');
    if (!here.length) to.append(el('span', 'muted', 'nothing'));
    for (const b of here) {
      const line = el('div', 'controls-bound');
      line.append(el('span', null, controlsBindingWords(b)));
      line.append(el('span', 'armoury-kind', ` ${b.map}${b.category ? ` · ${b.category}` : ''}`));
      if (!b.known) line.append(el('span', 'controls-unknown', ' not in this build\'s catalogue'));
      to.append(line);
    }
    tr.append(to);
    tr.append(el('td', 'num muted', here.map((b) => controlsModeWord(b.activationMode)).filter(Boolean).join(', ')));
    if (reference) {
      const ref = el('td', there.length ? null : 'muted');
      ref.textContent = there.length ? there.map(controlsBindingWords).join(', ') : '—';
      tr.append(ref);
    }
    // Change: give the control an action, with a mode if wanted, or take its binding off.
    const change = el('td', 'controls-change');
    const mode = controlsModePicker();
    const pick = controlsActionPicker(here, (choice) => {
      const input = `${device.key}_${control}`;
      if (choice === '__remove__') {
        for (const b of here) controlsStage({ actionMap: b.actionMap, action: b.action, input: b.input.raw, remove: true, label: b.label });
      } else {
        controlsStage({ actionMap: choice.actionMap, action: choice.name, input, label: choice.label, activationMode: mode.value || null });
      }
    });
    change.append(pick, mode);
    tr.append(change);
    tr.addEventListener('mouseenter', () => controlsHighlight(control, true));
    tr.addEventListener('mouseleave', () => controlsHighlight(control, false));
    body.append(tr);
  }
  if (!shown) {
    const td = el('td', 'muted', q ? 'Nothing on this stick matches.' : 'Nothing is bound to this stick and its picture names no controls.');
    td.colSpan = 5;
    const tr = el('tr');
    tr.append(td);
    body.append(tr);
  }

  renderControlsAxes(device, bound);
}

/**
 * The axes as an editor: for each axis the stick binds, the curve the
 * profile sets on the action's option group (exponent and invert) and the
 * dead zone on the axis, with a preview, and Apply. The game keeps the
 * curve per option group - flight_move_pitch, not "y" - so an axis that
 * drives two groups gets two rows and a group nothing drives gets none.
 */
function renderControlsAxes(device, bound) {
  const box = $('#controls-axes');
  box.textContent = '';
  const catalogue = controlsModel.catalogue;
  const rows = [];
  for (const [control, list] of bound) {
    if (/^(button|hat)/.test(control)) continue;
    for (const b of list) {
      const action = catalogue.actions.find((a) => a.actionMap === b.actionMap && a.name === b.action);
      rows.push({ axis: control, binding: b, group: action?.optionGroup || '' });
    }
  }
  if (!rows.length) return;

  box.append(el('h4', null, 'Axes'));
  box.append(el('p', 'muted small', 'The curve is the game\'s exponent on the action\'s axis group: 1 is straight, above it the centre goes softer and the ends sharper. The dead zone is on the axis itself. What you set here is written the way a restore is.'));
  const table = el('table', 'controls-axes-table');
  const head = el('tr');
  for (const [label, cls] of [['Axis', null], ['Drives', null], ['Curve', 'num'], ['Invert', null], ['Dead zone', 'num'], ['', null]]) head.append(el('th', cls, label));
  const thead = el('thead');
  thead.append(head);
  table.append(thead);
  const body = el('tbody');
  const seenAxis = new Set();
  for (const r of rows) {
    const curve = (device.curves || []).find((c) => c.option === r.group) || {};
    const tr = el('tr');
    tr.dataset.axis = r.axis;
    tr.dataset.group = r.group;
    tr.append(el('td', 'controls-control', `${r.axis} axis`));
    const drives = el('td', null, r.binding.label);
    drives.append(el('div', 'armoury-kind', r.group ? r.group.replace(/^flight_/, '').replace(/_/g, ' ') : 'no curve group: the game keeps no curve for this action'));
    tr.append(drives);

    // An exponent is not a thing anyone has an intuition for. The slider is
    // the handle, the presets are the answers most people want, and the line
    // underneath says what the number does in the only terms that matter:
    // how much you get for half a push.
    const curveCell = el('td', 'controls-curve-cell');
    const exponent = el('input', 'controls-exponent');
    exponent.type = 'number';
    exponent.min = '0.2';
    exponent.max = '5';
    exponent.step = '0.05';
    exponent.value = String(Math.round((curve.exponent ?? 1) * 100) / 100);
    exponent.disabled = !r.group;

    const slider = el('input', 'controls-curve-slider');
    slider.type = 'range';
    slider.min = '0.4';
    slider.max = '3';
    slider.step = '0.05';
    slider.value = String(Math.min(3, Math.max(0.4, Number(exponent.value) || 1)));
    slider.disabled = !r.group;
    slider.title = 'Drag for a softer or sharper centre; the box beside it takes anything the game allows';

    const presets = el('div', 'controls-curve-presets');
    for (const [name, value] of CONTROLS_CURVE_PRESETS) {
      const chip = el('button', 'controls-curve-preset', name);
      chip.type = 'button';
      chip.dataset.value = String(value);
      chip.disabled = !r.group;
      presets.append(chip);
    }

    const words = el('div', 'controls-curve-words muted');
    const handle = el('div', 'controls-curve-handle');
    handle.append(slider, exponent);
    curveCell.append(handle, presets, words);
    tr.append(curveCell);

    const invertCell = el('td');
    const invert = el('input', 'controls-invert');
    invert.type = 'checkbox';
    invert.checked = !!curve.inverted;
    invert.disabled = !r.group;
    invertCell.append(invert);
    tr.append(invertCell);

    const dzCell = el('td', 'num');
    const dz = el('input', 'controls-deadzone');
    dz.type = 'number';
    dz.min = '0';
    dz.max = '50';
    dz.step = '0.5';
    const dzNow = device.deadzones?.[r.axis];
    dz.value = String(dzNow != null ? Math.round(dzNow * 1000) / 10 : 0);
    // One dead zone per axis: a second row on the same axis shows it, and
    // the first row's is the one sent.
    if (seenAxis.has(r.axis)) dz.disabled = true; else seenAxis.add(r.axis);
    dzCell.append(dz);
    dzCell.append(el('span', 'muted', ' %'));
    tr.append(dzCell);

    const preview = el('td');
    // The chart gets its own holder so redrawing is a replaceChildren on it
    // rather than a replaceChild against the cell's first node: the live
    // reading sits in the same cell and would be counted.
    const chart = el('div', 'controls-curve-holder');
    chart.append(controlsCurvePreview(Number(exponent.value), invert.checked, Number(dz.value) / 100));
    preview.append(chart);
    preview.append(el('span', 'controls-axis-live muted'));
    const redraw = () => {
      const e = Number(exponent.value) || 1;
      const zone = (Number(dz.value) || 0) / 100;
      chart.replaceChildren(controlsCurvePreview(e, invert.checked, zone));
      words.textContent = controlsCurveWords(e, zone);
      for (const chip of presets.querySelectorAll('.controls-curve-preset'))
        chip.classList.toggle('on', Math.abs(Number(chip.dataset.value) - e) < 0.026);
    };
    slider.addEventListener('input', () => { exponent.value = slider.value; redraw(); });
    exponent.addEventListener('input', () => {
      const e = Number(exponent.value);
      if (e >= 0.4 && e <= 3) slider.value = String(e);
      redraw();
    });
    for (const chip of presets.querySelectorAll('.controls-curve-preset'))
      chip.addEventListener('click', () => { exponent.value = chip.dataset.value; slider.value = chip.dataset.value; redraw(); });
    invert.addEventListener('change', redraw);
    dz.addEventListener('input', redraw);
    redraw();
    tr.append(preview);
    body.append(tr);
  }
  table.append(body);
  box.append(table);

  const bar = el('div', 'controls armoury-filters');
  const apply = el('button', 'ghost', controlsModel.gameRunning ? 'Apply as an import file' : 'Apply to the profile');
  apply.type = 'button';
  apply.title = controlsModel.gameRunning
    ? 'Star Citizen is running: the change is written as a file the keybinding screen imports'
    : 'Written into the game\'s profile, after keeping it as it is';
  apply.addEventListener('click', () => controlsApplyAxes(device, apply));
  bar.append(apply);
  bar.append(el('span', 'muted small controls-axes-note'));
  box.append(bar);
}

/** A small graph of output against input for a curve, with the dead zone as a flat start. */
/**
 * The curves worth having, in the app's words rather than the game's.
 * Below 1 the centre is sharper and the ends softer, which is what a pilot
 * flying with a short-throw stick asks for; above 1 is the usual fine-control
 * trade, more room around centre paid for at the stops.
 */
const CONTROLS_CURVE_PRESETS = [
  ['sharper', 0.7],
  ['straight', 1],
  ['soft', 1.3],
  ['softer', 1.8],
  ['very soft', 2.5],
];

/**
 * What an exponent does, in the only terms that mean anything at the stick:
 * how far the ship goes for half a push, and for most of one. The dead zone
 * is in it because it moves both, and a reading that ignored it would be
 * wrong by exactly the amount the pilot just set.
 */
function controlsCurveWords(exponent, deadzone) {
  const out = (x) => {
    const past = Math.max(0, x - deadzone) / Math.max(0.0001, 1 - deadzone);
    return Math.round(Math.pow(past, exponent > 0 ? exponent : 1) * 100);
  };
  const half = out(0.5);
  const most = out(0.8);
  if (Math.abs(exponent - 1) < 0.026 && !deadzone) return 'Straight through: half a push is half the output.';
  return `Half a push gives ${half}%, four fifths gives ${most}%.`;
}

function controlsCurvePreview(exponent, inverted, deadzone) {
  const ns = 'http://www.w3.org/2000/svg';
  const make = (tag) => (typeof document.createElementNS === 'function' ? document.createElementNS(ns, tag) : el(tag));
  const svg = make('svg');
  svg.setAttribute('viewBox', '0 0 64 64');
  svg.setAttribute('class', 'controls-curve');
  const axis = make('path');
  axis.setAttribute('d', 'M0 64 L64 64 M0 0 L0 64 M0 64 L64 0');
  axis.setAttribute('class', 'controls-curve-axis');
  svg.append(axis);
  const points = [];
  for (let i = 0; i <= 32; i++) {
    const x = i / 32;
    const past = Math.max(0, x - deadzone) / Math.max(0.0001, 1 - deadzone);
    let y = Math.pow(past, exponent > 0 ? exponent : 1);
    if (inverted) y = -y;
    points.push(`${(x * 64).toFixed(1)},${(64 - y * 64).toFixed(1)}`);
  }
  const line = make('polyline');
  line.setAttribute('points', points.join(' '));
  line.setAttribute('class', 'controls-curve-line');
  svg.append(line);
  // Where the axis is now, once something is reading it. Pushing the pedal
  // and watching the dot climb the curve is the whole explanation of what an
  // exponent does, and it needs no words at all.
  const dot = make('circle');
  dot.setAttribute('r', '3.5');
  dot.setAttribute('class', 'controls-curve-dot');
  dot.setAttribute('cx', '-10');
  dot.setAttribute('cy', '-10');
  svg.append(dot);
  return svg;
}

async function controlsApplyAxes(device, button) {
  const note = $('#controls-axes .controls-axes-note');
  const curves = [];
  const deadzones = {};
  for (const tr of $('#controls-axes')?.querySelectorAll?.('tr') || []) {
    if (!tr.dataset?.axis) continue;
    const exponent = tr.querySelector('.controls-exponent');
    const invert = tr.querySelector('.controls-invert');
    const dz = tr.querySelector('.controls-deadzone');
    if (tr.dataset.group && exponent && !exponent.disabled)
      curves.push({ option: tr.dataset.group, exponent: Number(exponent.value) || 1, inverted: !!invert?.checked });
    if (dz && !dz.disabled) deadzones[tr.dataset.axis] = Math.max(0, Number(dz.value) || 0) / 100;
  }
  button.disabled = true;
  try {
    const response = await fetch('/api/controls/axes', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ instance: device.instance, curves, deadzones, how: controlsModel.gameRunning ? 'export' : 'live' }),
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok) { note.textContent = result.message || result.title || `Could not apply (${response.status}).`; return; }
    note.textContent = result.how === 'live'
      ? 'Written to the profile; the game reads it at its next start. The profile as it was is kept under Backups.'
      : `Written as ${result.mappings}. In the game: Options → Keybindings → import "${result.name}", or at the console: ${result.command}.`;
    if (result.how === 'live') await loadControls();
  } catch (err) {
    note.textContent = `Could not apply: ${err.message}`;
  } finally {
    button.disabled = false;
  }
}

function controlsControlOrder(a, b) {
  const rank = (c) => (/^button/.test(c) ? 0 : /^hat/.test(c) ? 1 : 2);
  const num = (c) => Number((/(\d+)/.exec(c) || [0, 0])[1]);
  return rank(a) - rank(b) || num(a) - num(b) || a.localeCompare(b);
}

function controlsControlLabel(control) {
  let m = /^button(\d+)$/.exec(control);
  if (m) return `Button ${m[1]}`;
  m = /^hat(\d+)_(\w+)$/.exec(control);
  if (m) return `Hat ${m[1]} ${m[2]}`;
  return `${control} axis`;
}

/**
 * Draws the stick. The SVG is fetched as text and parsed here rather than
 * shown in an img, because the bindings have to be written into it: every
 * text node whose content is a placeholder gets the action bound to that
 * control, or a dash. Returns the controls the picture names.
 */
async function renderControlsPicture(device, bound) {
  const holder = $('#controls-svg');
  const note = $('#controls-picture-note');
  holder.textContent = '';
  if (!device.template) {
    // The fix is offered where the gap is: fetch the library from here, or
    // pick a picture from here, rather than a pointer to another pane.
    note.textContent = '';
    const t = controlsModel.templates || {};
    if (!t.enabled && !(t.available || []).length) {
      note.append(el('span', null, 'No picture yet: the library is off. '));
      const fetchButton = el('button', 'ghost small', 'Fetch the pictures');
      fetchButton.type = 'button';
      fetchButton.title = 'Joystick Diagrams\' template library, 45 sticks, throttles and panels - fetched from GitHub and kept';
      fetchButton.addEventListener('click', () => controlsFetchLibrary(fetchButton));
      note.append(fetchButton);
    } else {
      note.append(el('span', null, 'No picture matched to this stick. '));
      const pick = el('select', 'select');
      pick.append(new Option('Pick one…', ''));
      let maker = null;
      let group = null;
      for (const x of t.available || []) {
        if (x.maker !== maker) { maker = x.maker; group = el('optgroup'); group.label = maker || 'Library'; pick.append(group); }
        group.append(new Option(x.name, x.key));
      }
      pick.addEventListener('change', async () => {
        if (!pick.value) return;
        await fetch('/api/controls/templates/assign', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ guid: device.guid, key: pick.value }) });
        await loadControls();
      });
      note.append(pick);
    }
    return controlsDrawGrid(holder, device, bound);
  }
  note.textContent = `${device.template.name} · ${device.template.maker === 'yours' ? 'your own picture' : 'Joystick Diagrams'}`;

  let text;
  try {
    // Older responses were cached for a day and had not been sanitized.
    const response = await fetch(`/api/controls/template?key=${encodeURIComponent(device.template.key)}&safe=1`, { cache: 'no-store' });
    if (!response.ok) throw new Error(String(response.status));
    text = await response.text();
  } catch {
    note.textContent = `${device.template.name} · the picture could not be fetched`;
    return [];
  }

  const drawn = controlsDrawSvg(holder, text, bound, device.product);
  const misfit = controlsPictureMisfit(device, drawn, bound, controlsLiveDevice(device));
  if (misfit) {
    const warn = el('div', 'controls-picture-misfit');
    warn.append(el('span', null, misfit + ' '));
    const drop = el('button', 'ghost small', 'take the picture off');
    drop.type = 'button';
    drop.title = "Draw the numbered grid from this stick's own counts instead";
    drop.addEventListener('click', async () => {
      await fetch('/api/controls/templates/assign', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ guid: device.guid, key: '' }) });
      await loadControls();
    });
    warn.append(drop);
    note.append(warn);
  }
  return drawn;
}

/**
 * The checklist holds two different promises apart: the actions a pilot says
 * matter, and defaults the game recommends for this hardware. Calling both
 * "mandatory" would make a pilot's preference sound like a game requirement.
 *
 * The counts are shown even - especially - when the list is empty, because
 * "nothing missing" out of 119 reference bindings is an answer and "nothing
 * missing" out of nothing is a bug, and the two look identical otherwise.
 */
async function loadControlsCheck() {
  const list = $('#controls-check-list');
  const counts = $('#controls-check-counts');
  const note = $('#controls-check-note');
  const again = $('#controls-check-again');
  if (!list) return;
  list.textContent = '';
  counts.textContent = '';
  note.textContent = 'Reading the profile…';

  let result;
  try { result = await getJson('/api/controls/check'); }
  catch { note.textContent = 'The check could not be run.'; return; }

  if (!result.ready) { note.textContent = result.reason || 'Not ready.'; return; }

  const c = result.counts || {};
  const names = result.names || {};
  const against = (result.sources || []).map((f) => names[f] || f);
  note.textContent = against.length
    ? `Against ${against.join(' and ')}.`
    : 'The game ships no reference layout for any stick in your profile, so there is nothing to check against.';

  const pins = controlsChecklistPins.map((pin) => {
    const action = controlsModel?.catalogue?.actions?.find((a) => a.actionMap === pin.actionMap && a.name === pin.action);
    const map = controlsModel?.catalogue?.maps?.find((m) => m.name === pin.actionMap);
    const bindings = (controlsModel?.profile?.bindings || []).filter((b) => b.actionMap === pin.actionMap && b.action === pin.action && b.input?.device === 'js' && b.input.kind !== 'none');
    return { ...pin, label: action?.label || pin.label || pin.action, map: map?.label || pin.map || pin.actionMap, bindings };
  });
  const pinGaps = pins.filter((pin) => !pin.bindings.length);
  const gaps = result.gaps || [];

  for (const [label, value, why, hot] of [
    ['important to you', pins.length, 'actions you chose to keep in view', false],
    ['important unassigned', pinGaps.length, 'important actions with no joystick binding', pinGaps.length > 0],
    ['game defaults missing', gaps.length, 'actions in the game’s layout that your profile does not bind', gaps.length > 0],
    ['already bound', c.bound, 'game-layout defaults you have somewhere on your sticks', false],
    ['you took off', c.cleared, 'defaults you cleared on purpose, so they are not suggestions', false],
    ['renamed since', c.undefined, 'layout actions this patch no longer knows by that name', false],
    ['layouts checked', c.reference, 'bindings in the game’s own layouts for your sticks', false],
  ]) {
    if (value === undefined) continue;
    const cell = el('div', `controls-check-count${hot ? ' hot' : ''}`);
    cell.append(el('b', null, String(value)));
    cell.append(el('span', null, label));
    cell.title = why;
    counts.append(cell);
  }

  again.hidden = !(c.dismissed > 0);

  const dashboard = el('div', 'controls-check-dashboard');
  const important = el('section', 'controls-check-section controls-check-important');
  important.append(el('h4', null, 'Important to you'));
  important.append(el('p', 'muted small', 'Choose the actions you want to find quickly. They stay here with their joystick status.'));
  const add = controlsActionPicker([], (action) => {
    if (!controlsChecklistPins.some((pin) => pin.actionMap === action.actionMap && pin.action === action.name)) {
      controlsChecklistPins.push({ actionMap: action.actionMap, action: action.name, label: action.label });
      controlsSaveChecklistPins();
    }
    loadControlsCheck().catch(() => {});
  });
  add.classList.add('controls-check-add');
  important.append(add);
  const importantList = el('div', 'controls-check-important-list');
  if (!pins.length) {
    importantList.append(el('p', 'muted small', 'No important actions chosen yet. Search or browse above to add one.'));
  }
  for (const pin of pins) {
    const row = el('div', `controls-check-priority-row${pin.bindings.length ? '' : ' unassigned'}`);
    const head = el('div', 'controls-check-what');
    head.append(el('b', null, pin.label));
    head.append(el('span', 'armoury-kind', ` ${pin.map}`));
    row.append(head);
    const status = pin.bindings.length
      ? pin.bindings.map((b) => `${controlsSticks().find((d) => d.key === b.input.deviceKey)?.product || b.input.deviceKey} · ${controlsInputWords(b.input.raw)}`).join(', ')
      : 'Not assigned to a joystick';
    row.append(el('div', `controls-check-where${pin.bindings.length ? '' : ' controls-check-unassigned'}`, status));
    const doing = el('div', 'controls-check-do');
    if (!pin.bindings.length) {
      const assign = el('button', 'ghost small', 'find it');
      assign.type = 'button';
      assign.title = 'Open the Actions page filtered to this action';
      assign.addEventListener('click', () => {
        const search = $('#controls-search');
        if (search) search.value = pin.label;
        renderControlsActions();
        showControlsPane('actions');
      });
      doing.append(assign);
    }
    const remove = el('button', 'ghost small', 'remove');
    remove.type = 'button';
    remove.title = 'Remove this action from your important-controls list';
    remove.addEventListener('click', () => {
      controlsChecklistPins = controlsChecklistPins.filter((p) => !(p.actionMap === pin.actionMap && p.action === pin.action));
      controlsSaveChecklistPins();
      loadControlsCheck().catch(() => {});
    });
    doing.append(remove);
    row.append(doing);
    importantList.append(row);
  }
  important.append(importantList);
  dashboard.append(important);

  const defaults = el('section', 'controls-check-section controls-check-defaults');
  defaults.append(el('h4', null, 'Game-recommended defaults'));
  defaults.append(el('p', 'muted small', against.length
    ? 'The game puts these on your hardware in its own layout. Stage only the ones you want.'
    : 'The game ships no reference layout for your sticks, so there is nothing to compare.'));
  const defaultsList = el('div', 'controls-check-defaults-list');
  if (!gaps.length && against.length) {
    defaultsList.append(el('p', 'muted small', 'Nothing missing. Every default the game recommends is either assigned or one you removed on purpose.'));
  }
  for (const gap of gaps) {
    const row = el('div', 'controls-check-row');
    const head = el('div', 'controls-check-what');
    head.append(el('b', null, gap.label));
    head.append(el('span', 'armoury-kind', ` ${gap.map}`));
    row.append(head);
    row.append(el('div', 'controls-check-where', `${gap.product || gap.deviceKey} · the game puts it on ${controlsInputWords(gap.suggested)}`));

    const doing = el('div', 'controls-check-do');
    const add = el('button', 'ghost small', 'stage it');
    add.type = 'button';
    add.title = 'Add it to the pending changes, to apply with everything else';
    add.addEventListener('click', () => {
      controlsStage({ actionMap: gap.actionMap, action: gap.action, input: gap.suggested, label: gap.label });
      add.disabled = true;
      add.textContent = 'staged';
    });
    doing.append(add);

    const no = el('label', 'controls-check-no');
    const box = el('input');
    box.type = 'checkbox';
    box.addEventListener('change', async () => {
      await fetch('/api/controls/check/dismiss', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ key: `${gap.deviceKey}/${gap.actionMap}/${gap.action}`, dismissed: box.checked }),
      });
      await loadControlsCheck();
    });
    no.append(box, el('span', null, 'I do not want this'));
    doing.append(no);
    row.append(doing);
    defaultsList.append(row);
  }
  defaults.append(defaultsList);
  dashboard.append(defaults);
  list.append(dashboard);
}

$('#controls-check-again')?.addEventListener('click', async () => {
  await fetch('/api/controls/check/ask-again', { method: 'POST' });
  await loadControlsCheck();
});

/** An input as the game writes it, in words a pilot reads: js4_button10 -> button 10. */
function controlsInputWords(raw) {
  const m = /^(?:js|kb|mo|gp)\d*_(.*)$/.exec(String(raw || ''));
  const control = m ? m[1] : String(raw || '');
  const button = /^button(\d+)$/.exec(control);
  if (button) return `button ${button[1]}`;
  const hat = /^hat(\d+)_(\w+)$/.exec(control);
  if (hat) return `hat ${hat[1]} ${hat[2]}`;
  return control || 'nothing';
}

/**
 * Whether the picture is of this stick at all, in words, or null when
 * nothing says otherwise.
 *
 * A picture is chosen by hand and nothing stopped a rudder being given a
 * joystick: a Virpil grip drew thirty empty buttons over a T-Pendular-Rudder,
 * whose profile binds three axes and no button at all, and the page said only
 * which picture it was. The library has no pedals in it, so for that stick
 * there is no right answer and the app should say so rather than draw a
 * confident wrong one.
 *
 * The live counts settle it when they are there. Without them the profile is
 * the only witness and it can only ever be a doubt - a stick can carry buttons
 * nobody has bound - so the wording stays a doubt and names what would settle it.
 */
function controlsPictureMisfit(device, drawn, bound, live) {
  const named = (drawn || []).filter((c) => /^button\d+$/.test(c)).length;
  if (!named) return null;
  const product = device.product || 'this stick';
  if (live && Number.isFinite(live.buttonCount)) {
    if (live.buttonCount === 0)
      return `This picture draws ${named} buttons and ${product} reports none, so it is a picture of a different device.`;
    if (named > live.buttonCount)
      return `This picture draws ${named} buttons and ${product} reports ${live.buttonCount}, so some of it belongs to a different device.`;
    return null;
  }
  const keys = [...(bound?.keys?.() || [])];
  const buttons = keys.filter((c) => /^button\d+$/.test(c)).length;
  const axes = keys.filter((c) => !/^(button|hat)/.test(c)).length;
  if (buttons || !axes) return null;
  return `This picture draws ${named} buttons, and nothing on ${product} is bound to a button - only ${axes} ${axes === 1 ? 'axis' : 'axes'}. It may be a picture of a different device; the live read would say for certain.`;
}

/**
 * The stand-in for a stick nobody has drawn: the numbered buttons of the
 * Windows game-controller panel, lit where something is bound, with the
 * hats as crosses and the axes as bars. How many buttons the stick has is
 * not known without the live read, so the grid runs to the highest number
 * the profile mentions, rounded to a full row, and says so.
 */
function controlsDrawGrid(holder, device, bound) {
  const controls = [];
  const buttons = [...bound.keys()].map((c) => /^button(\d+)$/.exec(c)).filter(Boolean).map((m) => Number(m[1]));
  const hats = [...new Set([...bound.keys()].map((c) => /^hat(\d+)_/.exec(c)).filter(Boolean).map((m) => Number(m[1])))];
  const axes = [...bound.keys()].filter((c) => !/^(button|hat)/.test(c));
  const highest = buttons.length ? Math.max(...buttons) : 0;
  // The live read knows the true count; without it, the highest number the
  // profile mentions, rounded to a row.
  //
  // But the floor of 8 was a joystick talking. A rudder has three axes and no
  // buttons at all, and the stand-in drew it eight empty ones and put its
  // pedals underneath as a footnote - the same wrong shape the Virpil picture
  // gave it. Nothing bound and nothing read means no button grid: the axes are
  // the device, so they are all it draws.
  const live = controlsLiveDevice(device);
  const count = live ? live.buttonCount : (buttons.length ? Math.max(8, Math.ceil(highest / 8) * 8) : 0);
  const liveHats = live ? live.hatCount : 0;

  const grid = el('div', 'controls-grid');
  if (count > 0) grid.append(el('div', 'controls-grid-title', live
    ? `Buttons · ${count}, as Windows reports the stick`
    : `Buttons · to ${count}, the highest your profile mentions being ${highest || 'none'}`));
  const cells = el('div', 'controls-grid-buttons');
  for (let i = 1; i <= count; i++) {
    const control = `button${i}`;
    controls.push(control);
    const here = bound.get(control) || [];
    const cell = el('div', `controls-grid-button${here.length ? ' bound' : ''}`, String(i));
    cell.dataset.control = control;
    cell.title = here.length ? here.map(controlsBindingWords).join(' / ') : 'nothing bound';
    if (here.length) cell.append(el('span', 'controls-grid-label', here.map((b) => b.label).join(' / ')));
    cells.append(cell);
  }
  if (count > 0) grid.append(cells);

  for (let h = 1; h <= liveHats; h++) if (!hats.includes(h)) hats.push(h);
  hats.sort((a, b) => a - b);
  for (const hat of hats) {
    const cross = el('div', 'controls-grid-hat');
    cross.append(el('div', 'controls-grid-title', `Hat ${hat}`));
    const pad = el('div', 'controls-grid-cross');
    for (const dir of ['up', 'left', 'right', 'down']) {
      const control = `hat${hat}_${dir}`;
      controls.push(control);
      const here = bound.get(control) || [];
      const cell = el('div', `controls-grid-button ${dir}${here.length ? ' bound' : ''}`, { up: '▲', down: '▼', left: '◀', right: '▶' }[dir]);
      cell.dataset.control = control;
      cell.title = here.length ? here.map(controlsBindingWords).join(' / ') : 'nothing bound';
      pad.append(cell);
    }
    cross.append(pad);
    grid.append(cross);
  }

  // The live read knows every axis the device has; without it only the bound
  // ones are known to exist, so the two lists are unioned rather than one
  // replacing the other.
  const shown = [...axes];
  if (live) for (const name of CONTROLS_AXIS_ORDER.slice(0, live.axisCount || 0))
    if (!shown.includes(name)) shown.push(name);
  shown.sort((a, b) => CONTROLS_AXIS_ORDER.indexOf(a) - CONTROLS_AXIS_ORDER.indexOf(b));

  if (shown.length) {
    const bars = el('div', 'controls-grid-axes');
    bars.append(el('div', 'controls-grid-title', live
      ? `Axes · ${live.axisCount}, as Windows reports the device`
      : `Axes · ${shown.length} your profile binds`));
    for (const axis of shown) {
      controls.push(axis);
      bars.append(controlsAxisGauge(device, axis, bound.get(axis) || []));
    }
    grid.append(bars);
  }

  grid.append(el('p', 'muted small', controlsGridWords(count, axes.length, live)));
  holder.append(grid);
  return controls;
}

/**
 * What the stand-in is, in a sentence that matches what it actually drew.
 * A rudder gets no button grid, so telling it the buttons are numbered as
 * Windows numbers them would be describing a thing that is not on the page.
 */
function controlsGridWords(buttons, axes, live) {
  if (!buttons && axes)
    return live
      ? 'A stand-in until a picture is chosen. Windows reports no buttons on this device, so its axes are all there is to draw.'
      : 'A stand-in until a picture is chosen. Nothing on this device is bound to a button - only axes - so only its axes are drawn. The live read would say whether it has buttons nobody has used.';
  if (!buttons && !axes)
    return live
      ? 'Windows reports no buttons and no axes on this device.'
      : 'Nothing in your profile binds anything on this device, and the sticks cannot be read here, so there is nothing to draw yet.';
  return live
    ? 'A stand-in until a picture is chosen: the buttons as Windows numbers them, red where your profile binds something, outlined while pressed.'
    : 'A stand-in until a picture is chosen: the buttons as Windows numbers them, lit where your profile binds something. Only the ones the profile mentions are certain; the stick may have more.';
}

/** The order Windows reports axes in, which is how a live reading is indexed. */
const CONTROLS_AXIS_ORDER = ['x', 'y', 'z', 'rotx', 'roty', 'rotz', 'slider1', 'slider2'];

/** An axis in words: the game's name is terse and the same for every device. */
function controlsAxisWords(axis) {
  const rot = /^rot([xyz])$/.exec(axis);
  if (rot) return `rotation ${rot[1].toUpperCase()}`;
  const slider = /^slider(\d+)$/.exec(axis);
  if (slider) return `slider ${slider[1]}`;
  return /^[xyz]$/.test(axis) ? `${axis.toUpperCase()} axis` : axis;
}

/**
 * One axis drawn rather than listed: a track with its centre marked, the
 * dead zone the profile sets shaded around it, and a needle the live read
 * moves.
 *
 * A rudder is three axes and nothing else, so a two-column list of names was
 * the whole of its picture, and it read as a table of contents for a page
 * that was not there. This is the same information as a shape, and it costs
 * a joystick nothing - its axes were drawn the same flat way.
 */
function controlsAxisGauge(device, axis, here) {
  const row = el('div', `controls-axis-gauge${here.length ? ' bound' : ''}`);
  row.dataset.control = axis;
  row.append(el('div', 'controls-axis-gauge-name', controlsAxisWords(axis)));

  const track = el('div', 'controls-axis-track');
  const dead = Number(device.deadzones?.[axis]) || 0;
  if (dead > 0) {
    // The game's dead zone is a fraction of the half-travel either side of
    // centre, which is why it is drawn from the middle outwards both ways.
    const band = el('div', 'controls-axis-dead');
    band.style.left = `${Math.max(0, 50 - dead * 50)}%`;
    band.style.width = `${Math.min(100, dead * 100)}%`;
    band.title = `dead zone ${Math.round(dead * 1000) / 10}%`;
    track.append(band);
  }
  track.append(el('div', 'controls-axis-centre'));
  const needle = el('div', 'controls-axis-needle');
  needle.hidden = true;
  track.append(needle);
  row.append(track);

  row.append(el('div', `controls-axis-gauge-what${here.length ? '' : ' muted'}`,
    here.length ? here.map((b) => b.label).join(' / ') : 'nothing bound'));
  return row;
}

/**
 * Fits a name into the template's box. The boxes were drawn for a word or
 * two; the font shrinks to what the width allows, and below a readable
 * size the name is cut with an ellipsis instead - the table has it whole,
 * and the full name is the hover.
 */
function controlsFitLabel(node, words) {
  const isSvg = node.namespaceURI === 'http://www.w3.org/2000/svg';
  // draw.io shows the HTML label inside a foreignObject when it can and the
  // SVG text otherwise; the box width is the foreignObject's, or the rect
  // beside the text.
  // draw.io puts the box's width on an inline style a few divs up from the
  // HTML label, and the box itself is a rect a few groups up from either.
  let width = 0;
  if (!isSvg) {
    for (let up = node, i = 0; up && i < 6; up = up.parentElement, i++) {
      const w = parseFloat(up.style?.width);
      if (w > 0) { width = w; break; }
    }
  }
  // The walk can reach past the label's own box to the diagram's background -
  // 827x1168 on the Warthog throttle - and a "box" that size makes every label
  // look like it fits, so an SVG label never shrank at all. A label box is a
  // small part of the drawing; anything above a third of it is not one.
  const root = node.closest?.('svg') || node.ownerSVGElement || null;
  const diagram = root
    ? Number(root.getAttribute('width')) || Number((root.getAttribute('viewBox') || '').split(/[\s,]+/)[2]) || 0
    : 0;
  for (let up = node.parentElement, i = 0; up && i < 8; up = up.parentElement, i++) {
    const rect = [...up.children || []].find((c) => c.nodeName.toLowerCase() === 'rect');
    if (!rect) continue;
    const w = Number(rect.getAttribute('width')) || 0;
    if (diagram && w > diagram / 3) break;
    if (!width) width = w;
    break;
  }
  if (!width) width = 90;
  const usable = Math.max(20, width - 8);
  const perChar = 0.56;
  // SVG text cannot wrap; an HTML label can take a second line when the box is tall enough.
  // An HTML label wraps and an SVG text cannot, and that is the whole of it.
  // The box's own height is not reachable: draw.io leaves it off the label and
  // the walk upwards finds the diagram's background rect instead, so reading a
  // height there once said every box was 1168 tall.
  const maxLines = isSvg ? 1 : 2;
  // Dividing the whole string by the line width says "Landing System (Toggle)"
  // is two lines in 70px. A browser cannot break a word, so it is three, and
  // the third spilled out of the box. Pack word by word the way one does.
  const fits = (size) => {
    const em = perChar * size;
    let lines = 1;
    let run = 0;
    for (const word of String(words).split(/\s+/).filter(Boolean)) {
      const w = word.length * em;
      if (w > usable) return false; // a word wider than the line spills whatever we do
      if (!run) run = w;
      else if (run + em + w <= usable) run += em + w;
      else { lines++; run = w; }
    }
    return lines <= maxLines;
  };
  let size = 10;
  while (size > 6.5 && !fits(size)) size -= 0.5;
  let text = words;
  if (!fits(size)) {
    const chars = Math.max(4, Math.floor((usable * maxLines) / (perChar * size)) - 1);
    if (chars < words.length) text = `${words.slice(0, chars).trimEnd()}…`;
  }
  node.textContent = text;
  const px = `${Math.round(size * 10) / 10}px`;
  if (isSvg) {
    node.setAttribute('font-size', px);
    const title = node.ownerDocument.createElementNS('http://www.w3.org/2000/svg', 'title');
    title.textContent = words;
    node.append(title);
  } else {
    node.style.fontSize = px;
    node.style.lineHeight = '1.1';
    node.style.whiteSpace = 'normal';
    node.style.overflowWrap = 'anywhere';
    node.title = words;
  }
}

/** Writes the bindings into a template's placeholders; the part a test can drive with a string. */
function controlsDrawSvg(holder, svgText, bound, deviceName) {
  // The test harness has no parser; the placeholder mapping is tested on its own.
  if (typeof DOMParser === 'undefined') return [];
  const parsed = new DOMParser().parseFromString(svgText, 'image/svg+xml');
  const svg = parsed.documentElement;
  if (!svg || svg.nodeName.toLowerCase() !== 'svg') return [];
  // draw.io exports both the rich HTML label and a plain SVG fallback in each
  // switch. A browser that can render foreignObject must see only the rich
  // label: rewriting both puts two copies of a long device name in one box.
  for (const choice of svg.querySelectorAll('switch')) {
    if (!choice.querySelector('foreignObject')) continue;
    for (const fallback of [...choice.children])
      if (fallback.nodeName.toLowerCase() === 'text') fallback.remove();
  }
  const controls = [];
  const texts = [...svg.querySelectorAll('text, tspan, div, span')].filter((n) => !n.children.length || n.nodeName.toLowerCase() === 'text');
  for (const node of texts) {
    if (String(node.textContent).trim() === 'TEMPLATE_NAME') { controlsFitLabel(node, deviceName || ''); continue; }
    const control = controlsPlaceholderToControl(node.textContent);
    if (!control) continue;
    if (!controls.includes(control)) controls.push(control);
    const here = bound.get(control) || [];
    node.setAttribute('data-control', control);
    node.classList?.add('controls-slot');
    if (here.length) {
      controlsFitLabel(node, here.map(controlsBindingWords).join(' / '));
      node.classList?.add('bound');
    } else {
      node.textContent = '—';
      node.classList?.add('empty');
    }
  }
  svg.removeAttribute('width');
  svg.removeAttribute('height');
  svg.setAttribute('preserveAspectRatio', 'xMidYMin meet');
  holder.append(document.adoptNode ? document.adoptNode(svg) : svg);
  return controls;
}

function controlsHighlight(control, on) {
  // By class then by data attribute, rather than an attribute selector: the
  // grid cells and the template's labels both carry the class, and the
  // test harness has no attribute selectors.
  const holder = $('#controls-svg');
  for (const cls of ['.controls-grid-button', '.controls-slot', '.controls-grid-axis'])
    for (const node of holder?.querySelectorAll?.(cls) || [])
      if ((node.dataset?.control ?? node.getAttribute?.('data-control')) === control) node.classList?.toggle('lit', on);
  for (const tr of $('#controls-buttons tbody')?.children || [])
    if (tr.dataset?.control === control) tr.classList?.toggle('lit', on);
}

/* ---------- the live read ---------- */

/**
 * While the Sticks pane is open, the sticks are read ten times a second
 * and whatever is pressed lights on the picture and in the table. Under
 * the bare server there is nothing to read, and the pane says so once.
 * The read is matched to the open stick by product GUID; two sticks of
 * one product cannot be told apart and the pane says that too.
 */
let controlsLive = null;
let controlsLiveTimer = null;
let controlsLiveLit = new Set();

function controlsLiveWanted() {
  // Ten reads a second is cheap to look at and not cheap to leave running: a
  // second-screen dashboard gets left open, and a hidden tab cannot show a lit
  // button to anyone. document.hidden is read defensively - the WebTests' stub
  // document has no visibility to report, and a missing one means visible.
  if (typeof document !== 'undefined' && document.hidden === true) return false;
  return controlsPane === 'devices' && $('#view-controls')?.classList.contains('active') && !!controlsModel?.ready;
}

async function controlsLiveTick() {
  if (!controlsLiveWanted()) { controlsLiveStop(); return; }
  try {
    controlsLive = await getJson('/api/controls/live');
  } catch {
    controlsLive = null;
  }
  paintControlsLive();
  if (controlsLiveWanted()) controlsLiveTimer = setTimeout(controlsLiveTick, controlsLive?.available ? 100 : 5000);
}

function controlsLiveStart() {
  if (controlsLiveTimer) return;
  controlsLiveTimer = setTimeout(controlsLiveTick, 0);
}

// Hiding the tab stops the poll, so showing it again has to start one: the
// tick that noticed the tab was hidden cleared the timer on its way out and
// nothing else on the page is watching for it to come back.
document.addEventListener?.('visibilitychange', () => {
  if (controlsLiveWanted()) controlsLiveStart(); else controlsLiveStop();
});

function controlsLiveStop() {
  if (controlsLiveTimer) clearTimeout(controlsLiveTimer);
  controlsLiveTimer = null;
  for (const control of controlsLiveLit) controlsHighlight(control, false);
  controlsLiveLit = new Set();
}

/** The live device for the open stick, or null; two of one product is ambiguous and reads as none. */
function controlsLiveDevice(device) {
  if (!controlsLive?.available || !device?.guid) return null;
  const same = (controlsLive.devices || []).filter((d) => d.guid && d.guid.toLowerCase() === device.guid.toLowerCase());
  return same.length === 1 ? same[0] : null;
}

/** What a reading says is active on a stick, as the game's control names. */
function controlsLiveControls(reading) {
  const controls = [];
  for (const b of reading.pressed || []) controls.push(`button${b}`);
  (reading.hats || []).forEach((h, i) => {
    if (!h) return;
    for (const dir of h.split('-')) controls.push(`hat${i + 1}_${dir}`);
  });
  return controls;
}

function paintControlsLive() {
  const note = $('#controls-live-note');
  const device = controlsSticks().find((d) => d.key === controlsDevice);
  if (!note) return;
  if (!controlsLive) { note.textContent = ''; return; }
  if (!controlsLive.available) {
    note.textContent = controlsLive.reason || 'The sticks cannot be read here.';
    return;
  }
  const live = controlsLiveDevice(device);
  const twins = device?.guid ? (controlsLive.devices || []).filter((d) => d.guid?.toLowerCase() === device.guid.toLowerCase()).length : 0;
  if (!live) {
    note.textContent = twins > 1
      ? `Two of this product are plugged in; Windows cannot say which is ${device.key}, so nothing is lit.`
      : device?.guid ? 'This stick is not plugged in right now.' : '';
    for (const control of controlsLiveLit) controlsHighlight(control, false);
    controlsLiveLit = new Set();
    return;
  }
  const active = new Set(controlsLiveControls(live));
  const words = [...active].map(controlsControlLabel);
  note.textContent = `Live · ${live.buttonCount} buttons, ${live.axisCount} axes, ${live.hatCount} hat${live.hatCount === 1 ? '' : 's'} · ${words.length ? `pressed: ${words.join(', ')}` : 'press a button to see it'}`;
  for (const control of controlsLiveLit) if (!active.has(control)) controlsHighlight(control, false);
  for (const control of active) if (!controlsLiveLit.has(control)) controlsHighlight(control, true);
  controlsLiveLit = active;
  // Axis values, on the editor's rows.
  const names = CONTROLS_AXIS_ORDER;
  const reading = (axis) => {
    const i = names.indexOf(axis);
    return i >= 0 && i < (live.axes || []).length ? live.axes[i] : null;
  };
  for (const tr of $('#controls-axes')?.querySelectorAll?.('tr') || []) {
    if (!tr.dataset?.axis) continue;
    const meter = tr.querySelector('.controls-axis-live');
    if (!meter) continue;
    const value = reading(tr.dataset.axis);
    meter.textContent = value == null ? '' : value.toFixed(2);
    const dot = tr.querySelector('.controls-curve-dot');
    if (dot) {
      // The preview draws one half; the curve is symmetric, so how far the
      // axis is from centre is all it needs.
      const away = value == null ? null : Math.min(1, Math.abs(value));
      const e = Number(tr.querySelector('.controls-exponent')?.value) || 1;
      const zone = (Number(tr.querySelector('.controls-deadzone')?.value) || 0) / 100;
      if (away == null) { dot.setAttribute('cx', '-10'); dot.setAttribute('cy', '-10'); }
      else {
        const past = Math.max(0, away - zone) / Math.max(0.0001, 1 - zone);
        dot.setAttribute('cx', (away * 64).toFixed(1));
        dot.setAttribute('cy', (64 - Math.pow(past, e > 0 ? e : 1) * 64).toFixed(1));
      }
    }
  }
  // ...and the needle on the stand-in's gauges, when there is no picture.
  for (const row of $('#controls-svg')?.querySelectorAll?.('.controls-axis-gauge') || []) {
    const needle = row.querySelector('.controls-axis-needle');
    if (!needle) continue;
    const value = reading(row.dataset?.control);
    needle.hidden = value == null;
    if (value != null) needle.style.left = `${Math.min(100, Math.max(0, (value + 1) * 50))}%`;
  }
}

/* ---------- changing bindings ---------- */

/**
 * Changes are staged, from either pane, and written together: one write
 * to the profile with the game closed, or one import file with it open.
 * A change is keyed by action and device, since the game keeps one binding
 * per device per action - staging a second control for the same action on
 * the same stick replaces the first.
 */
let controlsPending = [];

function controlsStage(change) {
  const key = (c) => `${c.actionMap}/${c.action}/${ControlInput_deviceKey(c.input)}`;
  controlsPending = controlsPending.filter((c) => key(c) !== key(change));
  controlsPending.push(change);
  renderControlsPending();
}

/** js4 from js4_button7, without parsing the rest. */
function ControlInput_deviceKey(raw) {
  const m = /^([a-z]{2}\d+)_/i.exec(raw || '');
  return m ? m[1].toLowerCase() : '';
}

function controlsUnstage(index) {
  controlsPending.splice(index, 1);
  renderControlsPending();
}

/** What a control on a stick is bound to right now, as words, for the pending list. */
function controlsBoundNow(input) {
  return (controlsModel?.profile?.bindings || []).filter((b) => b.input.raw.toLowerCase() === input.toLowerCase()).map((b) => b.label);
}

function renderControlsPending() {
  const box = $('#controls-pending');
  if (!box) return;
  box.hidden = !controlsPending.length;
  if (!controlsPending.length) return;
  $('#controls-pending-title').textContent = `${controlsPending.length} change${controlsPending.length === 1 ? '' : 's'} to apply`;
  const list = $('#controls-pending-list');
  list.textContent = '';
  const sticks = new Map(controlsSticks().map((d) => [d.key, d]));
  controlsPending.forEach((c, i) => {
    const li = el('li');
    const stick = sticks.get(ControlInput_deviceKey(c.input));
    const where = `${stick ? stick.product : ControlInput_deviceKey(c.input)} ${c.input.replace(/^[a-z]{2}\d+_/, '').replace('_', ' ')}`;
    li.append(el('span', null, c.remove ? `${c.label}: unbind from ${where}` : `${where} → ${c.label}${c.activationMode ? ` (${controlsModeWord(c.activationMode)})` : ''}`));
    if (!c.remove) {
      // The game flags two actions on one control in the same group; say so before it does.
      const also = (controlsModel?.profile?.bindings || []).filter((b) => b.input.raw.toLowerCase() === c.input.toLowerCase() && b.actionMap === c.actionMap && b.action !== c.action);
      if (also.length) li.append(el('span', 'controls-warn', ` also ${also.map((b) => b.label).join(', ')} in the same group - the game will flag the clash`));
      const now = controlsBoundNow(c.input).filter((l) => l !== c.label);
      if (now.length && !also.length) li.append(el('span', 'muted', ` (was ${now.join(', ')})`));
    }
    const undo = el('button', 'ghost small', 'undo');
    undo.type = 'button';
    undo.addEventListener('click', () => controlsUnstage(i));
    li.append(undo);
    list.append(li);
  });
  $('#controls-pending-apply').textContent = controlsModel?.gameRunning ? 'Apply as an import file' : 'Apply to the profile';
  $('#controls-pending-note').textContent = controlsModel?.gameRunning
    ? 'Star Citizen is running: the changes are written as a file the keybinding screen imports.'
    : 'Written into the game\'s profile, after keeping it as it is; the game reads it at its next start.';
}

async function controlsApplyBindings(button) {
  if (!controlsPending.length) return;
  const note = $('#controls-pending-note');
  button.disabled = true;
  try {
    const response = await fetch('/api/controls/bindings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        changes: controlsPending.map((c) => ({ actionMap: c.actionMap, action: c.action, input: c.input, remove: !!c.remove, activationMode: c.activationMode || null })),
        how: controlsModel?.gameRunning ? 'export' : 'live',
      }),
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok) { note.textContent = result.message || result.title || `Could not apply (${response.status}).`; return; }
    controlsPending = [];
    if (result.how === 'live') {
      await loadControls();
      $('#controls-status').textContent += ' Bindings written; the profile as it was is kept under Backups.';
    } else {
      renderControlsPending();
      $('#controls-status').textContent = `Written as ${result.mappings}. In the game: Options → Keybindings → import "${result.name}", or at the console: ${result.command}.`;
    }
  } catch (err) {
    note.textContent = `Could not apply: ${err.message}`;
  } finally {
    button.disabled = false;
  }
}

$('#controls-pending-apply')?.addEventListener('click', (e) => controlsApplyBindings(e.currentTarget));
$('#controls-pending-discard')?.addEventListener('click', () => { controlsPending = []; renderControlsPending(); });

/** The modes a binding can be given; blank keeps the action's own. */
const CONTROLS_MODES = [['', 'the action\'s own'], ['tap', 'tap'], ['press', 'press'], ['hold', 'hold'], ['double_tap', 'double tap'], ['delayed_press', 'long press'], ['delayed_press_long', 'longer press']];

function controlsModePicker() {
  const select = el('select', 'select controls-mode-pick');
  select.title = 'How the binding fires; the action\'s own unless you say';
  for (const [value, label] of CONTROLS_MODES) select.append(new Option(label, value));
  return select;
}

/**
 * A narrow, searchable action finder. Rendering every game action in every
 * control row made a six-stick profile a forest of tens of thousands of
 * options; only matching actions are rendered here, when the pilot asks.
 *
 * Search alone was not enough: it answers "where is Self destruct" but not
 * "what can I put here", and the grouped select it replaced did answer the
 * second. So an empty box browses - the maps first, then one map's actions -
 * and two letters switches to searching across all of them.
 */
function controlsActionPicker(current, choose) {
  const wrap = el('div', 'controls-action-picker');
  const search = el('input', 'search controls-action-search');
  search.type = 'search';
  search.placeholder = 'Find action, or browse…';
  search.autocomplete = 'off';
  search.spellcheck = false;
  search.title = 'Type at least two letters to search, or open the box to browse by group';
  const results = el('div', 'controls-action-results');
  results.hidden = true;
  const maps = new Map((controlsModel?.catalogue?.maps || []).map((map) => [map.name, map]));
  const actions = controlsModel?.catalogue?.actions || [];
  // Which map is being browsed, when nothing is typed; null is the map list.
  let group = null;

  const mapLabel = (map, fallback) => `${map?.label || fallback}${map?.category ? ` · ${map.category}` : ''}`;

  const close = () => {
    group = null;
    results.textContent = '';
    results.className = 'controls-action-results';
    results.hidden = true;
  };

  const actionRow = (action) => {
    const map = maps.get(action.actionMap);
    const button = el('button', 'controls-action-result');
    button.type = 'button';
    button.append(el('span', 'controls-action-result-label', action.label));
    button.append(el('span', 'controls-action-result-map', mapLabel(map, action.actionMap)));
    button.addEventListener('click', () => { choose(action); search.value = ''; close(); });
    return button;
  };

  const render = () => {
    const query = search.value.trim().toLowerCase();
    results.textContent = '';
    results.className = 'controls-action-results';
    results.hidden = false;

    if (query.length >= 2) {
      const matches = actions.filter((action) => {
        const map = maps.get(action.actionMap);
        return `${action.label} ${action.name} ${map?.label || ''} ${map?.category || ''}`.toLowerCase().includes(query);
      }).slice(0, 12);
      if (!matches.length) {
        results.className = 'controls-action-results muted small';
        results.textContent = 'No action matches that search.';
        return;
      }
      for (const action of matches) results.append(actionRow(action));
      return;
    }

    // Nothing typed: browse. One map's actions if one is open, else the maps.
    if (group) {
      const back = el('button', 'controls-action-back', `‹ all groups`);
      back.type = 'button';
      back.addEventListener('click', () => { group = null; render(); search.focus(); });
      results.append(back);
      const map = maps.get(group);
      const mine = actions.filter((a) => a.actionMap === group);
      if (!mine.length) results.append(el('div', 'muted small', `${mapLabel(map, group)} binds nothing.`));
      for (const action of mine) results.append(actionRow(action));
      return;
    }

    const groups = [...maps.values()].filter((map) => actions.some((a) => a.actionMap === map.name));
    if (!groups.length) { close(); return; }
    for (const map of groups) {
      const count = actions.filter((a) => a.actionMap === map.name).length;
      const button = el('button', 'controls-action-group');
      button.type = 'button';
      button.append(el('span', 'controls-action-result-label', mapLabel(map, map.name)));
      button.append(el('span', 'controls-action-result-map', `${count} action${count === 1 ? '' : 's'}`));
      button.addEventListener('click', () => { group = map.name; render(); });
      results.append(button);
    }
  };

  search.addEventListener('input', render);
  search.addEventListener('focus', render);
  search.addEventListener('keydown', (event) => {
    // Escape closes the list rather than clearing the row, which is what a
    // search input does by itself and would lose a half-typed query.
    if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); close(); return; }
    if (event.key !== 'Enter') return;
    const first = results.querySelector('.controls-action-result');
    if (first) { event.preventDefault(); first.click(); }
  });
  // A list left open over the row below it is read as that row's. The blur is
  // deferred because it lands before the click that chose an action.
  search.addEventListener('blur', () => setTimeout(() => {
    if (!wrap.contains(document.activeElement)) close();
  }, 150));
  wrap.append(search, results);
  if (current?.length) {
    const remove = el('button', 'ghost small controls-action-remove', 'unbind');
    remove.type = 'button';
    remove.title = 'Unbind everything now on this control';
    remove.addEventListener('click', () => choose('__remove__'));
    wrap.append(remove);
  }
  return wrap;
}

/** A stick and one of its controls, composed into the input the game writes. */
function controlsInputPicker() {
  const wrap = el('span', 'controls-input-pick');
  const stick = el('select', 'select');
  for (const d of controlsSticks()) stick.append(new Option(d.product, d.key));
  const control = el('select', 'select');
  for (let i = 1; i <= 32; i++) control.append(new Option(`button ${i}`, `button${i}`));
  for (const h of [1, 2]) for (const dir of ['up', 'down', 'left', 'right']) control.append(new Option(`hat ${h} ${dir}`, `hat${h}_${dir}`));
  for (const a of ['x', 'y', 'z', 'rotx', 'roty', 'rotz', 'slider1', 'slider2']) control.append(new Option(`${a} axis`, a));
  wrap.append(stick, control);
  wrap.value = () => `${stick.value}_${control.value}`;
  wrap.stick = stick;
  wrap.control = control;
  return wrap;
}

/* ---------- the actions ---------- */

function renderControlsActions() {
  const body = $('#controls-actions tbody');
  if (!body || !controlsModel?.ready) return;
  const catalogue = controlsModel.catalogue;
  const profile = controlsModel.profile;

  const categories = [...new Set(catalogue.maps.map((m) => m.category).filter(Boolean))].sort();
  const select = $('#controls-category');
  if (select && select.options.length !== categories.length + 1) {
    const keep = select.value;
    select.textContent = '';
    select.append(new Option('Every category', ''));
    for (const c of categories) select.append(new Option(c, c));
    select.value = categories.includes(keep) ? keep : '';
  }
  const category = select?.value || '';
  const unboundOnly = $('#controls-unbound')?.checked;
  const reboundOnly = $('#controls-rebound')?.checked;
  const q = ($('#controls-search')?.value || '').trim().toLowerCase();

  // What the profile binds, per action, split by device kind.
  const byAction = new Map();
  for (const b of profile?.bindings || []) {
    const key = `${b.actionMap}/${b.action}`;
    if (!byAction.has(key)) byAction.set(key, []);
    byAction.get(key).push(b);
  }
  const sticks = new Map(controlsSticks().map((d) => [d.key, d]));

  body.textContent = '';
  let shown = 0;
  let total = 0;
  for (const map of catalogue.maps) {
    if (category && map.category !== category) continue;
    for (const a of catalogue.actions.filter((x) => x.actionMap === map.name)) {
      total++;
      const mine = byAction.get(`${map.name}/${a.name}`) || [];
      const onSticks = mine.filter((b) => b.input.device === 'js' && b.input.kind !== 'none');
      const cleared = mine.some((b) => b.input.device === 'js' && b.input.kind === 'none');
      const keyboard = mine.filter((b) => b.input.device === 'kb').map((b) => b.input.label);
      if (unboundOnly && onSticks.length) continue;
      if (reboundOnly && !mine.length) continue;
      if (q && !`${a.label} ${a.name} ${map.label} ${onSticks.map(controlsBindingWords).join(' ')}`.toLowerCase().includes(q)) continue;
      shown++;
      const tr = el('tr', onSticks.length ? null : 'controls-unbound');
      const name = el('td', null, a.label);
      if (a.description && a.description !== a.label) name.title = a.description;
      name.append(el('div', 'armoury-kind', a.name));
      tr.append(name);
      tr.append(el('td', 'muted', `${map.label}${map.category ? ` · ${map.category}` : ''}`));
      const on = el('td');
      if (!onSticks.length) on.append(el('span', 'muted', cleared ? 'cleared - the default was taken off' : a.joystick ? `default: ${a.joystick}` : 'nothing'));
      for (const b of onSticks) {
        const line = el('div', 'controls-bound');
        const stick = sticks.get(b.input.deviceKey);
        line.append(el('span', 'controls-stick-tag', stick ? stick.product : b.input.deviceKey));
        line.append(el('span', null, ` ${b.input.label}`));
        on.append(line);
      }
      tr.append(on);
      tr.append(el('td', 'muted', keyboard.length ? keyboard.join(', ') : a.keyboard ? `default: ${a.keyboard}` : '—'));
      tr.append(el('td', 'num muted', controlsModeWord((onSticks[0] || mine[0])?.activationMode || a.activationMode)));
      // Bind: a stick and a control for this action; × on a binding takes it off.
      const bind = el('td', 'controls-bind-cell');
      for (const b of onSticks) {
        const off = el('button', 'ghost small', `× ${b.input.label}`);
        off.type = 'button';
        off.title = `Take this action off ${sticks.get(b.input.deviceKey)?.product || b.input.deviceKey}`;
        off.addEventListener('click', () => controlsStage({ actionMap: map.name, action: a.name, input: b.input.raw, remove: true, label: a.label }));
        bind.append(off);
      }
      if (controlsSticks().length) {
        const add = el('button', 'ghost small', 'Bind to…');
        add.type = 'button';
        add.addEventListener('click', () => {
          add.hidden = true;
          const picker = controlsInputPicker();
          const mode = controlsModePicker();
          const ok = el('button', 'ghost small', 'Stage');
          ok.type = 'button';
          ok.addEventListener('click', () => {
            controlsStage({ actionMap: map.name, action: a.name, input: picker.value(), label: a.label, activationMode: mode.value || null });
            picker.remove();
            mode.remove();
            ok.remove();
            add.hidden = false;
          });
          bind.append(picker, mode, ok);
        });
        bind.append(add);
      }
      tr.append(bind);
      body.append(tr);
    }
  }
  $('#controls-actions-count').textContent = `${shown} of ${total} actions${category ? ` in ${category}` : ''}${unboundOnly ? ' on no stick' : ''}${reboundOnly ? ' you rebound' : ''}.`;
}

for (const id of ['#controls-category', '#controls-unbound', '#controls-rebound'])
  $(id)?.addEventListener('change', renderControlsActions);
$('#controls-layout')?.addEventListener('change', () => { renderControlsDevice().catch(() => {}); });
onInput('#controls-search', () => { renderControlsActions(); renderControlsDevice().catch(() => {}); });
$('#controls-refresh')?.addEventListener('click', () => { loadControls().catch(() => {}); });

/* ---------- backups ---------- */

async function loadControlsBackups() {
  try {
    controlsBackups = await getJson('/api/controls/backups');
  } catch {
    controlsBackups = [];
  }
  renderControlsBackups();
}

function renderControlsBackups() {
  const body = $('#controls-backups tbody');
  if (!body) return;
  body.textContent = '';
  const note = $('#controls-backups-note');
  if (!controlsBackups.length) {
    note.textContent = 'Nothing kept yet. The first copy is taken when the game has written a profile.';
    $('#controls-diff').hidden = true;
    return;
  }
  note.textContent = `${controlsBackups.length} version${controlsBackups.length === 1 ? '' : 's'} kept. Tick two to see what changed between them; tick one to see what changed since.`;

  controlsBackups.forEach((b, i) => {
    const tr = el('tr');
    const pick = el('td');
    const box = el('input');
    box.type = 'checkbox';
    box.checked = controlsDiffPick.includes(b.id);
    box.addEventListener('change', () => {
      controlsDiffPick = box.checked ? [...controlsDiffPick, b.id].slice(-2) : controlsDiffPick.filter((x) => x !== b.id);
      renderControlsBackups();
      showControlsDiff().catch(() => {});
    });
    pick.append(box);
    tr.append(pick);
    const when = el('td', null, `${dateOf(b.writtenAt)} ${shortTimeOf(b.writtenAt)}`);
    if (i === 0) when.append(el('span', 'controls-latest', ' latest'));
    tr.append(when);
    tr.append(el('td', 'muted', relative(b.takenAt)));
    tr.append(el('td', 'num', `${Math.round(b.bytes / 1024)} KB`));
    const since = el('td', 'muted');
    const previous = controlsBackups[i + 1];
    since.textContent = previous ? 'see the diff' : 'first kept';
    if (previous) {
      const link = el('button', 'ghost small', 'Since the one before');
      link.type = 'button';
      link.addEventListener('click', () => { controlsDiffPick = [previous.id, b.id]; renderControlsBackups(); showControlsDiff().catch(() => {}); });
      since.textContent = '';
      since.append(link);
    }
    tr.append(since);
    const act = el('td', 'controls-backup-actions');
    const restore = el('button', 'ghost small', 'Restore');
    restore.type = 'button';
    restore.title = 'Write this version back over the game\'s profile - with the game closed';
    restore.addEventListener('click', () => controlsRestore(b, restore));
    act.append(restore);
    const export_ = el('button', 'ghost small', 'Export');
    export_.type = 'button';
    export_.title = 'Write this version as a file the game imports, with the sticks retargeted if they moved';
    export_.addEventListener('click', () => { controlsExportSource = b.id; renderControlsExport(); });
    act.append(export_);
    const download = el('a', 'ghost small', 'Download');
    download.href = `/api/controls/backups/${encodeURIComponent(b.id)}/file`;
    download.setAttribute('download', `actionmaps-${b.id}.xml`);
    download.title = 'This version as a file, to keep anywhere';
    act.append(download);
    tr.append(act);
    body.append(tr);
  });
}

/**
 * The restore itself. The server refuses while the game runs and says
 * why; the page repeats it and points at the export, which works with
 * the game open. A confirm first: this is the one button on the page
 * that writes over something the game owns.
 */
async function controlsRestore(backup, button) {
  const note = $('#controls-backups-note');
  const when = `${dateOf(backup.writtenAt)} ${shortTimeOf(backup.writtenAt)}`;
  if (typeof confirm === 'function' && !confirm(`Write the version of ${when} over the game's keybinding profile? The profile as it is now is kept first.`)) return;
  button.disabled = true;
  try {
    const response = await fetch('/api/controls/restore', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ source: backup.id }) });
    const result = await response.json().catch(() => ({}));
    if (!response.ok) {
      note.textContent = result.message || result.title || `The restore failed (${response.status}).`;
      return;
    }
    note.textContent = `Restored the version of ${when}. The game reads it at its next start.${result.keptBefore ? ' The profile as it was is kept above it.' : ''}`;
    await loadControlsBackups();
    await loadControls();
  } catch (err) {
    note.textContent = `The restore failed: ${err.message}`;
  } finally {
    button.disabled = false;
  }
}

$('#controls-import-pick')?.addEventListener('click', () => $('#controls-import-file')?.click());

$('#controls-import-file')?.addEventListener('change', (event) => {
  const file = event.target.files && event.target.files[0];
  if (!file) return;
  controlsImportFile(file)
    .catch((err) => { $('#controls-backups-note').textContent = `That file could not be added: ${err.message}`; })
    // Cleared so that picking the same file twice still fires a change.
    .finally(() => { event.target.value = ''; });
});

async function controlsImportFile(file) {
  const note = $('#controls-backups-note');
  const response = await fetch('/api/controls/backups/import', {
    method: 'POST',
    headers: { 'Content-Type': 'application/xml', 'X-File-Modified': new Date(file.lastModified || Date.now()).toISOString() },
    body: file,
  });
  const result = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(result.message || String(response.status));
  note.textContent = result.taken
    ? `Added: ${result.bindings} bindings on ${result.devices} devices.`
    : 'Already kept: that file is one of the versions here.';
  await loadControlsBackups();
}

$('#controls-keep')?.addEventListener('click', async (e) => {
  const button = e.currentTarget;
  button.disabled = true;
  try {
    const kept = await getJson2('/api/controls/backups');
    $('#controls-backups-note').textContent = kept.taken ? 'Kept.' : 'Already kept: the profile has not changed since the latest copy.';
    await loadControlsBackups();
  } catch {
    $('#controls-backups-note').textContent = 'Could not keep a copy.';
  } finally {
    button.disabled = false;
  }
});

async function showControlsDiff() {
  const box = $('#controls-diff');
  if (!controlsDiffPick.length) { box.hidden = true; return; }
  const [a, b] = controlsDiffPick.length === 2
    ? [...controlsDiffPick].sort()
    : [controlsDiffPick[0], 'live'];
  let changes;
  try {
    changes = await getJson(`/api/controls/backups/${encodeURIComponent(a)}/diff/${encodeURIComponent(b)}`);
  } catch {
    box.hidden = true;
    return;
  }
  box.hidden = false;
  const name = (id) => id === 'live' ? 'the profile as it is now' : `the copy of ${dateOf(controlsBackups.find((x) => x.id === id)?.writtenAt || Date.now())}`;
  $('#controls-diff-title').textContent = `From ${name(a)} to ${name(b)}`;
  $('#controls-diff-count').textContent = changes.length ? `${changes.length} action${changes.length === 1 ? '' : 's'} changed` : 'no binding changed';
  const body = $('#controls-diff-table tbody');
  body.textContent = '';
  for (const c of changes) {
    const tr = el('tr');
    const action = el('td', null, c.label);
    action.append(el('div', 'armoury-kind', c.map));
    tr.append(action);
    tr.append(el('td', c.before.length ? 'controls-was' : 'muted', c.before.length ? c.before.join(', ') : 'nothing'));
    tr.append(el('td', c.after.length ? 'controls-now' : 'muted', c.after.length ? c.after.join(', ') : 'nothing'));
    body.append(tr);
  }
}

function renderControlsExport() {
  const box = $('#controls-export');
  if (!box) return;
  box.hidden = false;
  const source = controlsExportSource || 'live';
  $('#controls-export-source').textContent = source === 'live' ? 'from the profile as it is now' : `from the copy ${source}`;
  $('#controls-export-result').textContent = '';
  $('#controls-export-install').hidden = true;

  // One select per stick: which number it is now. Left alone, nothing moves.
  const retarget = $('#controls-retarget');
  retarget.textContent = '';
  const sticks = controlsSticks();
  for (const d of sticks) {
    const row = el('label', 'controls-retarget-row');
    row.append(el('span', null, `${d.product} was ${d.key}, now`));
    const select = el('select', 'select');
    select.dataset.from = String(d.instance);
    for (let i = 1; i <= Math.max(8, sticks.length); i++) select.append(new Option(`js${i}`, String(i)));
    select.value = String(d.instance);
    row.append(select);
    retarget.append(row);
  }
}

async function controlsWriteExport(install) {
  const name = $('#controls-export-name')?.value || 'quantumwake';
  const retarget = {};
  for (const select of $('#controls-retarget')?.querySelectorAll('select') || [])
    if (select.value !== select.dataset.from) retarget[select.dataset.from] = Number(select.value);
  const result = $('#controls-export-result');
  try {
    const response = await fetch('/api/controls/export', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ source: controlsExportSource || 'live', name, retarget, install }),
    });
    if (!response.ok) throw new Error(String(response.status));
    const written = await response.json();
    result.textContent = written.installed
      ? `In the game's folder as ${written.mappings}. In the game: Options → Keybindings → import "${written.name}", or at the console: ${written.command}.`
      : `Written to ${written.path}. Not yet where the game reads: press the second button to copy it there, or copy it yourself.`;
    $('#controls-export-install').hidden = written.installed;
  } catch (err) {
    result.textContent = `The export failed: ${err.message}`;
  }
}

$('#controls-export-write')?.addEventListener('click', () => controlsWriteExport(false));
$('#controls-export-install')?.addEventListener('click', () => controlsWriteExport(true));

/* ---------- pictures ---------- */

function renderControlsPictures() {
  const t = controlsModel?.templates;
  if (!t) return;
  $('#controls-templates-status').textContent = t.enabled
    ? `on · ${t.available.filter((x) => x.maker !== 'yours').length} in the library${t.fetchedAt ? `, listed ${relative(t.fetchedAt)}` : ''}`
    : t.available.length ? 'off · what was fetched is kept' : 'off';
  $('#controls-templates-enable').hidden = t.enabled;
  $('#controls-templates-disable').hidden = !t.enabled;
  const folder = $('#controls-folder');
  if (folder && document.activeElement !== folder) folder.value = t.folder || '';
  $('#controls-folder-note').textContent = t.folder
    ? `${t.available.filter((x) => x.maker === 'yours').length} SVG${t.available.filter((x) => x.maker === 'yours').length === 1 ? '' : 's'} in ${t.folder}`
    : '';

  const box = $('#controls-assign');
  box.textContent = '';
  const sticks = controlsSticks();
  if (!sticks.length) { box.append(el('p', 'muted', 'No stick in the profile to give a picture to.')); return; }
  if (!t.available.length) { box.append(el('p', 'muted', 'No pictures to choose from yet.')); return; }
  for (const d of sticks) {
    const row = el('label', 'controls-assign-row');
    row.append(el('span', 'controls-assign-name', `${d.product} (${d.key})`));
    const select = el('select', 'select');
    select.append(new Option(d.template && !t.assignments[d.guid] ? `Matched: ${d.template.name}` : 'None', ''));
    let maker = null;
    let group = null;
    for (const x of t.available) {
      if (x.maker !== maker) { maker = x.maker; group = el('optgroup'); group.label = maker || 'Library'; select.append(group); }
      group.append(new Option(x.name, x.key));
    }
    select.value = t.assignments[d.guid] || '';
    select.addEventListener('change', async () => {
      await fetch('/api/controls/templates/assign', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ guid: d.guid, key: select.value }) });
      await loadControls();
    });
    row.append(select);
    box.append(row);
  }
}

/** Turns the library on and reloads; the button that asked is disabled while it happens. */
async function controlsFetchLibrary(button) {
  button.disabled = true;
  button.textContent = 'Fetching…';
  try {
    await getJson2('/api/controls/templates/enable');
    await loadControls();
  } catch (err) {
    button.textContent = 'Fetch the pictures';
    button.disabled = false;
    const status = $('#controls-templates-status');
    if (status) status.textContent = `could not fetch the library: ${err.message}`;
    const note = $('#controls-picture-note');
    if (note) note.append(el('span', 'muted', ` Could not fetch the library: ${err.message}`));
  }
}

$('#controls-templates-enable')?.addEventListener('click', (e) => controlsFetchLibrary(e.currentTarget));

$('#controls-templates-disable')?.addEventListener('click', async () => {
  await getJson2('/api/controls/templates/disable');
  await loadControls();
});

$('#controls-folder-save')?.addEventListener('click', async () => {
  const response = await fetch('/api/controls/templates/folder', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ folder: $('#controls-folder').value }) });
  if (!response.ok) { $('#controls-folder-note').textContent = 'No such folder.'; return; }
  await loadControls();
});

/* ---------- the Log page's two panes ---------- */

/**
 * Readings is what the pilot showed the app; Game logs is what the app read
 * on its own. They share a page because both answer "what does Quantum Wake
 * know, and where from" - but a screenshot log and a file table are different
 * shapes, so they take turns rather than stacking.
 */
const LOG_PANES = ['readings', 'files'];
let logPane = 'readings';
try {
  const kept = localStorage.getItem('qw-log-pane');
  if (LOG_PANES.includes(kept)) logPane = kept;
} catch { /* private browsing keeps the default */ }

const LOG_CAPTIONS = {
  readings: 'What you have shown Quantum Wake, and the coordinates you chose to keep.',
  files: 'Every log the game has written, and whether Quantum Wake has read it as it stands.',
};

function showLogPane(name) {
  if (!LOG_PANES.includes(name)) name = 'readings';
  logPane = name;
  try { localStorage.setItem('qw-log-pane', name); } catch { /* as above */ }

  for (const pane of LOG_PANES) $(`#log-pane-${pane}`)?.classList.toggle('active', pane === name);
  for (const button of $('#log-tabs')?.querySelectorAll('button') || [])
    button.classList.toggle('active', button.dataset.pane === name);

  // Clearing readings and scanning logs each belong to one pane; the header
  // shows the button for the pane on screen and not the other one.
  const clear = $('#screen-log-clear');
  if (clear) clear.hidden = name !== 'readings';
  const scan = $('#scan-now');
  if (scan) scan.hidden = name !== 'files';
  const caption = $('#log-caption');
  if (caption) caption.textContent = LOG_CAPTIONS[name];

  if (name === 'files') loadScanHistory().catch(() => {});
}

for (const button of $('#log-tabs')?.querySelectorAll('button') || [])
  button.addEventListener('click', () => showLogPane(button.dataset.pane));

/** Megabytes to one place; a log is 2-4 MB and the whole folder ~400. */
function megabytes(bytes) {
  if (bytes == null) return '—';
  const mb = bytes / 1048576;
  return `${mb.toLocaleString(undefined, { maximumFractionDigits: mb < 10 ? 1 : 0 })} MB`;
}

/** Date and time in one short cell: "Sep 14, 2026 21:03". */
const stampOf = (iso) => (iso ? `${dateOf(iso)} ${shortTimeOf(iso)}` : '—');

/** What a file's state means to someone reading the table, not to the scanner. */
const FILE_STATES = {
  current: ['read', 'Summarised as it stands on disk'],
  changed: ['grown', 'Has changed since it was read; the next scan re-reads it'],
  unread: ['not read', 'In the folder but never scanned'],
  gone: ['gone', 'The game has deleted this backup; its session is kept from the last read'],
  parsing: ['parsing…', 'Being read right now'],
};

/** The scan in progress, as the bar last polled it; null between scans. */
let scanNow = null;

/** The runs as last fetched, kept so a poll can redraw the table with the live row on top. */
let scanRunsSeen = [];

function paintFileState(cell, state) {
  const [label, why] = FILE_STATES[state] || [state, ''];
  cell.className = `scan-state ${state}`;
  cell.textContent = label;
  cell.title = why;
}

/**
 * One poll of a scan, on the file table.
 *
 * The rows are not re-fetched mid-scan: sessions land in batches of 25, so
 * the store would describe a pass half committed. The table keeps what it
 * last read and only the row being parsed changes, back to its resting
 * state once the scan has moved on; the finish reloads everything.
 */
function paintScanFiles(status) {
  scanNow = status && status.running ? status : null;

  const body = $('#scan-files-table tbody');
  if (!body) return;

  for (const tr of body.children || []) {
    const cell = tr.querySelector?.('.scan-state');
    if (!cell || !tr.dataset) continue;
    const parsing = !!scanNow && tr.dataset.file === scanNow.file;
    paintFileState(cell, parsing ? 'parsing' : tr.dataset.state);
  }

  renderScanRuns(scanRunsSeen);
}

async function loadScanHistory() {
  const table = $('#scan-files-table tbody');
  if (!table) return;

  let history;
  try {
    history = await getJson('/api/scan/history');
  } catch {
    $('#scan-files-summary').textContent = 'could not read the scan history';
    return;
  }

  renderScanFiles(history);
  renderScanRuns(history.runs || []);
}

function renderScanFiles(history) {
  const body = $('#scan-files-table tbody');
  body.textContent = '';
  const files = history.files || [];

  const read = files.filter((f) => f.state === 'current').length;
  const gone = files.filter((f) => f.state === 'gone').length;
  const parts = [`${history.onDisk ?? 0} in the folder`, megabytes(history.bytes || 0), `${read} read as they stand`];
  if (gone) parts.push(`${gone} gone`);
  $('#scan-files-summary').textContent = parts.join(' · ');

  if (!files.length) {
    const td = el('td', 'muted', history.root
      ? 'No Game.log in this install yet. The game writes one the first time it runs.'
      : 'No install found, so there is nothing to read. Point the app at one from Settings.');
    td.colSpan = 8;
    const tr = el('tr');
    tr.append(td);
    body.append(tr);
    return;
  }

  for (const file of files) {
    const tr = el('tr', file.state === 'gone' ? 'gone' : file.live ? 'live' : null);

    const name = el('td');
    name.append(el('span', 'scan-file', file.name));
    if (file.live) name.append(el('span', 'scan-live', 'live'));
    name.title = file.path;
    tr.append(name);

    // Remembered on the row so a poll can mark it parsing and put it back.
    tr.dataset.file = file.name;
    tr.dataset.state = file.state;
    const state = el('td');
    paintFileState(state, scanNow && scanNow.file === file.name ? 'parsing' : file.state);
    tr.append(state);

    tr.append(el('td', 'num', megabytes(file.bytes)));
    tr.append(el('td', null, stampOf(file.writtenAt)));

    // The session is the log's own clock; the file's write time is the OS's.
    // They differ by a rotation and a time zone, and both are shown so a row
    // can be matched against the Sessions page or against Explorer.
    tr.append(el('td', null, file.startedAt ? `${dateOf(file.startedAt)} ${shortTimeOf(file.startedAt)} → ${shortTimeOf(file.endedAt)}` : '—'));
    tr.append(el('td', 'num', file.startedAt
      ? duration((new Date(file.endedAt) - new Date(file.startedAt)) / 1000)
      : '—'));
    tr.append(el('td', null, file.handle || '—'));

    const when = el('td', 'muted', file.scannedAt ? relative(file.scannedAt) : file.sessionId ? 'before 0.14.10' : '—');
    if (file.scannedAt) when.title = stampOf(file.scannedAt);
    else if (file.sessionId) when.title = 'Read by a build that did not yet record when';
    tr.append(when);

    body.append(tr);
  }
}

function renderScanRuns(runs) {
  scanRunsSeen = runs;
  const body = $('#scan-runs-table tbody');
  body.textContent = '';

  const latest = runs[0];
  $('#scan-runs-summary').textContent = scanNow
    ? `running · ${scanNow.done} of ${scanNow.total} checked · ${scanNow.parsed} read so far`
    : latest
      ? `last ${relative(latest.finishedAt)} · ${latest.parsed} of ${latest.files} read`
      : '';

  // The pass under way sits above the ones that finished, with the file it
  // is on: the same facts the bar at the top shows, kept beside the history
  // they are about to join.
  if (scanNow) {
    const tr = el('tr', 'running');
    tr.append(el('td', null, 'now'));
    tr.append(el('td', 'num', String(scanNow.total)));
    tr.append(el('td', 'num', String(scanNow.parsed)));
    tr.append(el('td', 'num', `${scanNow.elapsedSeconds}s`));
    tr.append(el('td', 'scan-state parsing', `parsing ${scanNow.done} / ${scanNow.total}${scanNow.file ? ` · ${scanNow.file}` : ''}`));
    body.append(tr);
  }

  if (!runs.length && !scanNow) {
    const td = el('td', 'muted', 'No scan recorded yet. Scans are kept from 0.14.10 on; the first one lands on the next start.');
    td.colSpan = 5;
    const tr = el('tr');
    tr.append(td);
    body.append(tr);
    return;
  }

  for (const run of runs) {
    const tr = el('tr');
    const when = el('td', null, stampOf(run.startedAt));
    when.title = relative(run.startedAt);
    tr.append(when);
    tr.append(el('td', 'num', String(run.files)));
    tr.append(el('td', 'num', String(run.parsed)));
    const seconds = Math.max(0, (new Date(run.finishedAt) - new Date(run.startedAt)) / 1000);
    tr.append(el('td', 'num', seconds < 1 ? '<1s' : `${Math.round(seconds)}s`));
    tr.append(el('td', run.forced ? 'scan-forced' : 'muted', run.forced ? 'full re-read' : run.parsed ? 'new logs' : 'unchanged'));
    body.append(tr);
  }
}

// A routine pass, not the forced re-read Settings offers: unchanged backups
// are skipped, so this is seconds, and it is what picks up a log the game
// rotated while the app was already running.
$('#scan-now')?.addEventListener('click', async (e) => {
  const button = e.currentTarget;
  button.disabled = true;
  try {
    await getJson2('/api/scan');
    await loadScanHistory();
  } catch {
    $('#scan-files-summary').textContent = 'the scan could not be started';
  } finally {
    button.disabled = false;
  }
});

/**
 * Clearing is deliberate and immediate.
 *
 * No confirmation: everything in the log can be produced again by taking the
 * screenshot again, and a dialog in front of a harmless button is the kind of
 * thing that trains people to click through the ones that matter.
 */
$('#screen-log-clear')?.addEventListener('click', async (e) => {
  const button = e.currentTarget;
  button.disabled = true;

  try {
    await fetch('/api/screen/readings', { method: 'DELETE' });
    screenLatestShot = null;
    await renderScreenLog();
  } catch {
    screenSay('could not clear the log');
  } finally {
    button.disabled = false;
  }
});

