async function renderOverlayLayout() {
  let data;
  try {
    data = await getJson('/api/overlay/layout');
  } catch {
    return;
  }

  const draw = (host, names, chosen) => {
    const node = $(host);
    node.textContent = '';

    for (const name of names) {
      const label = el('label', 'toggle');
      const box = document.createElement('input');
      box.type = 'checkbox';
      box.value = name;
      box.checked = chosen.includes(name);
      box.addEventListener('change', saveOverlayLayout);

      label.append(box);
      label.append(el('span', null, OVERLAY_LABELS[name] || name));
      node.append(label);
    }
  };

  draw('#overlay-tabs', data.tabs, data.current.tabs);
  draw('#overlay-cards', data.cards, data.current.cards);

  for (const radio of $$('#overlay-density input')) {
    radio.checked = radio.value === data.current.density;
    radio.onchange = saveOverlayLayout;
  }

  $('#overlay-layout-status').textContent = '';
}

$('#install-path-save')?.addEventListener('click', async (e) => {
  const status = $('#install-path-status');
  const path = $('#install-path').value.trim();

  if (!path) {
    status.textContent = 'Type the folder first.';
    return;
  }

  e.currentTarget.disabled = true;
  status.textContent = 'checking…';

  try {
    const response = await fetch('/api/install/path', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ path }),
    });

    const result = await response.json();

    status.textContent = response.ok
      ? `Found ${result.channel}. Restart Quantum Wake to read it.`
      : result.message || 'That folder does not hold Star Citizen logs.';

    if (response.ok) status.classList.add('inward');
  } catch {
    status.textContent = 'Could not reach the server.';
  } finally {
    e.currentTarget.disabled = false;
  }
});

$('#overlay-reload')?.addEventListener('click', async (e) => {
  const status = $('#overlay-layout-status');
  e.currentTarget.disabled = true;

  try {
    await fetch('/api/overlay/reload', { method: 'POST' });
    status.textContent = 'the widget will reload within a few seconds';
  } catch {
    status.textContent = 'could not reach the server';
  } finally {
    e.currentTarget.disabled = false;
  }
});

async function saveOverlayLayout() {
  const pick = (host) => $$(`${host} input:checked`).map((b) => b.value);
  const density = $$('#overlay-density input').find((r) => r.checked)?.value || 'normal';

  const status = $('#overlay-layout-status');
  status.textContent = 'saving…';

  try {
    await fetch('/api/overlay/layout', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ tabs: pick('#overlay-tabs'), cards: pick('#overlay-cards'), density }),
    });
    status.textContent = 'saved';
  } catch {
    status.textContent = 'could not save';
  }
}

/**
 * In the widget, applies the chosen layout: which tabs appear, which Now cards
 * appear, and the type scale. Polled rather than pushed, because the overlay
 * is a separate browser and a few seconds of lag costs nothing.
 */
let lastReloadToken = null;

async function applyOverlayLayout() {
  let data;
  try {
    data = await getJson('/api/overlay/layout');
  } catch {
    return;
  }

  // A reload asked for from the dashboard: anything a fresh page load would
  // pick up, without hunting for the widget's window.
  if (lastReloadToken !== null && data.reloadToken !== lastReloadToken) {
    location.reload();
    return;
  }
  lastReloadToken = data.reloadToken;

  const layout = data.current;

  const expanded = document.body.classList.contains('expanded');

  for (const button of $$('#tabs button[data-view]'))
    button.hidden = !expanded && !layout.tabs.includes(button.dataset.view);

  for (const card of $$('#view-now [data-card]')) {
    const wanted = expanded || layout.cards.includes(card.dataset.card);
    card.classList.toggle('layout-off', !wanted);
  }

  document.body.classList.remove('density-compact', 'density-tiny');
  if (layout.density !== 'normal') document.body.classList.add(`density-${layout.density}`);

  // The active view may have just been hidden; fall back to the first shown.
  const active = $('#tabs button.active[data-view]');
  if (active?.hidden) {
    const first = $$('#tabs button[data-view]').find((b) => !b.hidden);
    if (first) showView(first.dataset.view);
  }
}

/* ---------- trade routes ---------- */

/**
 * The route planner. UEX ranks margins; this ranks runs - the difference is
 * a hold and a wallet, which are the two things only your own logs know.
 */
let routeRequest = 0;

/*
 * The retrieved ship says what is in use right now, but planning often starts
 * while standing in a hangar. Keep that deliberate choice locally: Game.log
 * cannot prove ownership or which hull is currently on a pad, and a saved
 * choice must not turn either into a claim.
 */
const PLANNING_SHIP_KEY = 'qw-planning-ship';

/* Three states, not two. null is "never chosen", and the planner picks the
 * ship in use or the last flown. '' is "on foot", chosen on purpose, and it
 * has to survive every re-render: the first version folded it into "not a
 * candidate" and snapped straight back to a ship, so the one option that gave
 * the per-SCU table could be clicked but never kept. */
let planningShipName = null;
try { planningShipName = localStorage.getItem(PLANNING_SHIP_KEY); } catch { /* optional */ }

/* The install identifies a hull and whether it flies, but does not currently
 * expose its cargo grid. Keep a pilot-entered hold separate from reference
 * data so an unavailable optional catalogue cannot make a known freighter
 * unusable, and never present that number as installed or community evidence. */
const PLANNING_MANUAL_CARGO_KEY = 'qw-planning-manual-cargo';
let planningManualCargo = {};
try { planningManualCargo = JSON.parse(localStorage.getItem(PLANNING_MANUAL_CARGO_KEY) || '{}'); } catch { /* optional */ }

const planningShipKey = (name) => String(name || '').toLowerCase().replace(/[^a-z0-9]/g, '');

/* The reference rides on the fleet row itself: the server resolves it by class
 * name, with the variant fallback, and it is in libraryStats from the first
 * tick. Matching the display name against /api/reference/ships instead was
 * tried and undone - that list is one entry per name, so a Hammerhead GS read
 * as the 40 SCU base hull, a hull whose display name differs from the
 * community name lost its grid altogether, and every ship read "cargo
 * capacity needed" until the catalogue landed, a good half minute after the
 * game data on a cold start. */
function planningCandidates() {
  return (libraryStats?.ships || [])
    .filter((ship) => !excludedShips.has(ship.name))
    .map((ship) => ({
      ship,
      reference: ship.reference || null,
      install: (hangarShips?.ships || []).find((known) => known.className === ship.className) || null,
    }))
    .sort((a, b) => new Date(b.ship.lastFlown || 0) - new Date(a.ship.lastFlown || 0));
}

/* The name the plan resolves to, without writing it anywhere: a choice that
 * was never made falls to the ship in use or the last flown, a saved name no
 * longer in the roster does the same, and '' stays on foot. */
function resolvedPlanningShipName(candidates = planningCandidates()) {
  if (planningShipName === '') return '';
  if (candidates.some((candidate) => candidate.ship.name === planningShipName)) return planningShipName;
  const current = nowState?.ship;
  return candidates.find((candidate) => planningShipKey(candidate.ship.name) === planningShipKey(current))?.ship.name
    || candidates[0]?.ship.name || '';
}

function activePlanningShip() {
  const candidates = planningCandidates();
  const name = resolvedPlanningShipName(candidates);
  return candidates.find((candidate) => candidate.ship.name === name) || null;
}

function planningCargoKey(candidate) {
  return planningShipKey(candidate?.ship?.className || candidate?.ship?.name);
}

function planningManualCargoFor(candidate = activePlanningShip()) {
  return Number(planningManualCargo[planningCargoKey(candidate)]) || 0;
}

function planningCargo(candidate = activePlanningShip()) {
  return Number(candidate?.reference?.cargoScu) || Number(candidate?.install?.cargoScu) || planningManualCargoFor(candidate);
}

function planningCargoSource(candidate = activePlanningShip()) {
  return Number(candidate?.reference?.cargoScu) > 0 ? 'community'
    : Number(candidate?.install?.cargoScu) > 0 ? 'screenshot'
    : planningManualCargoFor(candidate) > 0 ? 'manual' : null;
}

function planningIsSpaceship(candidate = activePlanningShip()) {
  if (!candidate) return false;
  if (typeof candidate.reference?.isSpaceship === 'boolean') return candidate.reference.isSpaceship;
  return String(candidate.install?.kind || '').toLowerCase() === 'spaceship';
}

function planningIsGroundVehicle(candidate = activePlanningShip()) {
  if (!candidate) return false;
  if (typeof candidate.reference?.isSpaceship === 'boolean') return !candidate.reference.isSpaceship;
  const kind = String(candidate.install?.kind || '').toLowerCase();
  return kind === 'ground' || kind === 'gravlev';
}

function planningHasCargo(candidate = activePlanningShip()) {
  return planningCargo(candidate) > 0;
}

/* Whether anything at all has said how big the hold is. A reference row
 * carries a figure even when it is zero - a fighter, a rover - and that zero
 * is a fact to act on. No reference, no screenshot and no entry is a different
 * thing: the hold is unknown, not absent. */
function planningCargoKnown(candidate = activePlanningShip()) {
  return !!candidate?.reference
    || Number(candidate?.install?.cargoScu) > 0
    || planningManualCargoFor(candidate) > 0;
}

/* The one case where cargo routes are withheld: the hold is known and it is
 * nothing. An unknown hold falls back to the per-SCU table the page always
 * had, sized per unit and saying so, because hiding every route from a
 * pilot whose catalogue is off or still loading was a regression, not a
 * safeguard. */
function planningBlocksCargo(candidate = activePlanningShip()) {
  if (!candidate) return false;
  // A ground vehicle is excluded whatever its grid says: the community
  // catalogue gives the UTV 1 SCU, and that was enough to put a table of
  // one-SCU hauls under a card saying trade routes are excluded.
  if (planningIsGroundVehicle(candidate)) return true;
  return planningCargoKnown(candidate) && !planningHasCargo(candidate);
}

const cargoSourceName = (source) => ({
  community: 'Community data', screenshot: 'Screenshot/OCR', manual: 'Local entry',
}[source] || 'No source');

function setRouteReadiness(kind, label, detail = '') {
  const badge = $('#route-readiness');
  if (!badge) return;
  badge.className = `route-readiness ${kind}`;
  badge.textContent = label;
  badge.title = detail;
}

/** Keep the decision-critical ship evidence in the route header, even while its table is loading. */
function renderRouteHeader() {
  const context = $('#route-ship-context');
  if (!context) return;
  const active = activePlanningShip();
  if (!active) {
    context.textContent = 'No ship selected · SCU unknown · no source';
    setRouteReadiness('needs-cargo', 'Needs cargo SCU', 'Choose a cargo ship or add a locally verified hold size.');
    return;
  }

  const cargo = planningCargo(active);
  const source = planningCargoSource(active);
  const read = source === 'screenshot' && active.install?.cargoReadAt
    ? ` · read ${ago(active.install.cargoReadAt)}`
    : ' · last read unavailable';
  context.textContent = cargo > 0
    ? `${active.ship.name} · ${cargo.toLocaleString()} SCU · ${cargoSourceName(source)}${read}`
    : `${active.ship.name} · SCU unknown · no capacity source`;
  setRouteReadiness(cargo > 0 ? 'ready' : 'needs-cargo', cargo > 0 ? 'Ready' : 'Needs cargo SCU',
    cargo > 0 ? 'The selected ship has a cargo constraint, so routes can be sized.' : 'No verified cargo capacity is available for the selected ship.');
}

let planningHangarLoad = null;
async function loadPlanningInstallData() {
  if (hangarShips) return hangarShips;
  if (!planningHangarLoad) {
    planningHangarLoad = getJson('/api/fleet/hangar')
      .then((ships) => (hangarShips = ships))
      // A missing install description still leaves the conservative reference
      // path intact; it must not make the route page wait or fabricate a hull.
      .catch(() => (hangarShips = { ships: [] }))
      .finally(() => { planningHangarLoad = null; });
  }
  return planningHangarLoad;
}

function planningCapability(label, detail, source) {
  const card = el('div', 'ship-plan-option');
  card.append(el('b', null, label));
  card.append(el('span', 'muted', detail));
  if (source) card.append(sourceMarks(source));
  return card;
}

/** Draw the options that this selected hull can actually support. */
function renderShipPlan() {
  const select = $('#routes-ship');
  const title = $('#ship-plan-title');
  const options = $('#ship-plan-options');
  const limit = $('#ship-plan-limit');
  if (!select || !title || !options || !limit) return;

  const candidates = planningCandidates();
  const resolved = resolvedPlanningShipName(candidates);

  select.textContent = '';
  select.append(new Option('On foot / no ship selected', ''));
  for (const candidate of candidates) {
    const cargo = planningCargo(candidate);
    const suffix = candidate.reference
      ? cargo > 0 ? `${cargo.toLocaleString()} SCU` : planningIsSpaceship(candidate) ? 'no cargo grid' : 'ground vehicle'
      : cargo > 0 ? `${cargo.toLocaleString()} SCU · ${planningCargoSource(candidate) === 'screenshot' ? 'screenshot' : 'manual'}` : 'cargo capacity needed';
    select.append(new Option(`${candidate.ship.name} · ${suffix}`, candidate.ship.name));
  }
  select.value = resolved;

  const active = activePlanningShip();
  options.textContent = '';
  if (!active) {
    title.textContent = candidates.length ? 'Choose a flown ship to constrain this plan' : 'No flown ships are available yet';
    limit.textContent = 'This selection stays in this browser. It does not change your fleet or claim a ship is currently retrieved.';
    renderRouteHeader();
    return;
  }

  const cargo = planningCargo(active);
  const cargoSource = planningCargoSource(active);
  const crew = Number(active.reference?.crew) || 0;
  const spacefaring = planningIsSpaceship(active);
  title.textContent = active.ship.name;

  if (cargo > 0 && !planningIsGroundVehicle(active)) {
    options.append(planningCapability('Trade & cargo',
      cargoSource === 'manual'
        ? `Routes use your local ${cargo.toLocaleString()} SCU hold entry. Verify it against the vehicle terminal; it is not reference data.`
        : cargoSource === 'screenshot'
          ? `Routes use the ${cargo.toLocaleString()} SCU hold shown in your latest commodity-terminal screenshot${active.install?.cargoReadAt ? ` (${ago(active.install.cargoReadAt)})` : ''}.`
        : `Routes are sized to this ${cargo.toLocaleString()} SCU cargo grid.`,
      cargoSource === 'community' ? ['community'] : cargoSource === 'screenshot' ? ['screenshot'] : null));
  }
  if (spacefaring) {
    options.append(planningCapability('Map & flight plans',
      'Star-map stops and multi-stop flight plans are available for this spaceship.', ['install']));
  }
  if (crew > 1) {
    options.append(planningCapability('Crew',
      `Reference capacity: up to ${crew} people. Party notifications remain a floor, not a roster.`, ['community', 'logs']));
  }
  if (planningIsGroundVehicle(active)) {
    options.append(planningCapability('Ground vehicle',
      'Ground-only planning is available; trade routes and quantum navigation are excluded.', ['install']));
  }
  if (spacefaring && !active.reference) {
    const manual = el('label', 'ship-plan-manual');
    manual.append(el('span', 'muted', 'Cargo SCU (local):'));
    const input = el('input', 'search');
    input.type = 'number';
    input.min = '1';
    input.step = '1';
    input.value = planningManualCargoFor(active) || '';
    input.placeholder = 'Enter hold size';
    input.title = 'Local planning value only. Confirm this ship’s cargo grid in game before relying on routes.';
    input.addEventListener('change', () => {
      const value = Math.max(0, Math.floor(Number(input.value) || 0));
      const key = planningCargoKey(active);
      if (value) planningManualCargo[key] = value;
      else delete planningManualCargo[key];
      try { localStorage.setItem(PLANNING_MANUAL_CARGO_KEY, JSON.stringify(planningManualCargo)); } catch { /* optional */ }
      renderShipPlan();
      loadRoutes().catch(() => {});
    });
    manual.append(input);
    options.append(manual);
  }
  if (!options.childElementCount) {
    options.append(planningCapability('No documented planning capability',
      'This hull has no cargo, crew, or movement reference that can safely constrain a plan yet.', null));
  }

  limit.textContent = !active.reference && cargoSource === 'manual'
    ? 'The game install confirms this is a spaceship; its cargo size above is your browser-only entry. Enable the community ship dataset in Settings to replace it with reference data.'
    : !active.reference
    ? 'The game install confirms this is a spaceship but has no cargo-capacity field here. Enter the vehicle terminal’s hold size above for a local route constraint, or enable the community ship dataset.'
    : 'Quantum fuel/range and vehicle-bay fit are not present in the installed or community reference data, so this planner does not guess either one.';
  renderRouteHeader();
}

function choosePlanningShip(name) {
  planningShipName = name || '';
  try { localStorage.setItem(PLANNING_SHIP_KEY, planningShipName); } catch { /* optional */ }
  renderShipPlan();
  refreshTradeAdvice(nowState?.location).catch(() => {});
  reloadPilotBriefing().catch(() => {});
  loadRoutes().catch(() => {});
}

/* Local route memory is deliberately separate from flight plans. A plan is an
 * authored shared object; a preset, watch and save count are private browser
 * conveniences and must not claim the game or another device knows them. */
const ROUTE_PROFILES_KEY = 'qw-route-profiles';
const ROUTE_HISTORY_KEY = 'qw-route-history';
const ROUTE_WATCH_KEY = 'qw-route-watches';
const readRouteMemory = (key) => { try { return JSON.parse(localStorage.getItem(key) || '[]'); } catch { return []; } };
let routeProfiles = readRouteMemory(ROUTE_PROFILES_KEY);
let routeHistory = readRouteMemory(ROUTE_HISTORY_KEY);
let routeWatches = readRouteMemory(ROUTE_WATCH_KEY);
let highlightBestRoute = false;
const writeRouteMemory = (key, value) => { try { localStorage.setItem(key, JSON.stringify(value)); } catch { /* optional */ } };
const routeKey = (route) => [route.commodity, route.buyAt, route.sellAt].map(planningShipKey).join('|');

function routeRepeatability(route) {
  const availability = route.availability === 'reported-full' ? 3
    : route.availability === 'reported-partial' ? 2 : 1;
  const freshness = route.freshness === 'fresh' ? 3 : route.freshness === 'aging' ? 2 : 1;
  return availability + freshness + Math.min(2, route.fallbackSells?.length || 0);
}

function routeRisk(route) {
  const endpoints = [route.buySecurity, route.sellSecurity];
  const lawless = endpoints.filter((security) => security === 'lawless').length;
  const unknown = endpoints.filter((security) => !security || security === 'unknown').length;
  return lawless ? ['higher', `${lawless} lawless endpoint${lawless === 1 ? '' : 's'}`]
    : unknown ? ['uncertain', `${unknown} endpoint${unknown === 1 ? '' : 's'} unmatched`]
      : ['lower', 'monitored endpoints'];
}

/* A partial primary buyer does not mean the hold has to leave empty. We only
 * offer this when the source can fill the proposed hold and recorded demand at
 * named alternate buyers accounts for every SCU; it is a price-report plan,
 * never a promise that counters will still accept those amounts on arrival. */
function splitTradeRoute(route) {
  const target = Math.floor(Number(route.desiredUnits || route.units || 0));
  if (target <= Math.floor(Number(route.units || 0)) || (Number(route.buyStockScu) > 0 && Number(route.buyStockScu) < target)) return [];
  const buyers = [
    { terminal: route.sellAt, placeId: route.sellAtId, sellPrice: route.sellPrice, demandScu: route.sellDemandScu },
    ...(route.fallbackSells || []),
  ];
  let remaining = target;
  const portions = [];
  for (const buyer of buyers) {
    const demand = Math.floor(Number(buyer.demandScu || 0));
    if (!demand || !remaining) continue;
    const units = Math.min(remaining, demand);
    portions.push({ ...buyer, units });
    remaining -= units;
  }
  return remaining === 0 && portions.length > 1 ? portions : [];
}

function renderRouteProfiles() {
  const select = $('#routes-profile');
  if (!select) return;
  const previous = select.value;
  select.textContent = '';
  select.append(new Option('Route presets…', ''));
  for (const profile of routeProfiles) select.append(new Option(profile.name, profile.id));
  select.value = routeProfiles.some((profile) => profile.id === previous) ? previous : '';
}

function applyRouteProfile(profile) {
  if (!profile) return;
  $('#routes-capital').value = profile.capital || '';
  $('#routes-ranking').value = profile.ranking || 'reliable';
  $('#routes-evidence').value = profile.evidence || 'reported';
  $('#routes-safety').value = profile.safety || 'any';
  $('#routes-pad').value = profile.pad || 'any';
  $('#routes-here').checked = !!profile.here;
  $('#routes-fresh-only').checked = !!profile.fresh;
  // The ship goes through the same door as the selector, so it is kept for
  // the next load and the Now page's advice follows it. Setting the variable
  // alone left the Now page advising for the previous hull and a reload
  // quietly reverting the preset's ship.
  choosePlanningShip(typeof profile.ship === 'string' ? profile.ship : resolvedPlanningShipName());
}

function saveRouteProfile() {
  const name = window.prompt('Name this local route preset:', `Preset ${routeProfiles.length + 1}`)?.trim();
  if (!name) return;
  const profile = {
    id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, name,
    ship: resolvedPlanningShipName(), capital: $('#routes-capital').value,
    ranking: $('#routes-ranking').value, evidence: $('#routes-evidence').value,
    safety: $('#routes-safety').value, pad: $('#routes-pad').value,
    here: $('#routes-here').checked, fresh: $('#routes-fresh-only').checked,
  };
  routeProfiles = [...routeProfiles.filter((saved) => saved.name !== name), profile].slice(-12);
  writeRouteMemory(ROUTE_PROFILES_KEY, routeProfiles);
  renderRouteProfiles();
  $('#routes-profile').value = profile.id;
}

function rememberRoute(route, kind = 'route') {
  const key = routeKey(route);
  const now = new Date().toISOString();
  const item = { key, kind, commodity: route.commodity, buyAt: route.buyAt, sellAt: route.sellAt,
    profit: Number(route.profit || route.totalProfit || 0), outlay: Number(route.outlay || 0), at: now };
  routeHistory = [item, ...routeHistory].slice(0, 40);
  const snapshot = { ...item, margin: Number(route.marginPerScu || 0) };
  routeWatches = [snapshot, ...routeWatches.filter((watch) => watch.key !== key)].slice(0, 24);
  writeRouteMemory(ROUTE_HISTORY_KEY, routeHistory);
  writeRouteMemory(ROUTE_WATCH_KEY, routeWatches);
}

function routeWatchNote(route) {
  const watch = routeWatches.find((saved) => saved.key === routeKey(route));
  if (!watch) return null;
  const before = Number(watch.profit);
  const now = Number(route.profit);
  if (before <= 0) return `Saved ${ago(watch.at)}.`;
  const change = (now - before) / before;
  return Math.abs(change) >= .05
    ? `Since saved ${ago(watch.at)}: ${change > 0 ? '+' : ''}${Math.round(change * 100)}% projected profit.`
    : `Saved ${ago(watch.at)} · projected profit within 5%.`;
}

function renderRouteDashboard(rows) {
  const panel = $('#route-dashboard');
  if (!panel) return;
  const watched = rows.filter((route) => routeWatches.some((watch) => watch.key === routeKey(route)));
  panel.hidden = !(routeHistory.length || watched.length);
  if (panel.hidden) return;
  $('#route-dashboard-summary').textContent = `${routeHistory.length} locally saved route${routeHistory.length === 1 ? '' : 's'} · ${watched.length} currently visible watch${watched.length === 1 ? '' : 'es'}`;
  const watches = $('#route-watch-list');
  watches.textContent = '';
  for (const route of watched.slice(0, 4)) watches.append(el('div', 'route-watch', `${route.commodity}: ${routeWatchNote(route)}`));
  const history = $('#route-history-list');
  history.textContent = '';
  for (const saved of routeHistory.slice(0, 5)) history.append(el('div', 'route-history', `${saved.commodity} · ${saved.buyAt} → ${saved.sellAt} · saved ${ago(saved.at)}`));
}

/* The query the table was built from, so the panels under it answer the same
 * question. Circuits once asked with only the load and the money and quietly
 * dropped the safety, pad, freshness and evidence filters the table honoured,
 * which put a Pyro loop under a table set to Monitored only. */
function routeQuery({ scu, capital, from, ranking, freshOnly, evidence, safety, pad }) {
  return `scu=${scu}&capital=${capital}&from=${encodeURIComponent(from)}`
    + `&ranking=${encodeURIComponent(ranking)}&freshOnly=${freshOnly}`
    + `&evidence=${encodeURIComponent(evidence)}`
    + (safety !== 'any' ? `&safety=${encodeURIComponent(safety)}` : '')
    + (pad !== 'any' ? `&pad=${encodeURIComponent(pad)}` : '');
}

let circuitRequest = 0;

async function loadRouteCircuits(query) {
  const panel = $('#route-circuits');
  const list = $('#route-circuit-list');
  if (!panel || !list || !query.scu) { if (panel) panel.hidden = true; return; }
  // Same guard as the table: typing in the capital box fires one of these per
  // keystroke, and without it the last to land won rather than the last sent.
  const request = ++circuitRequest;
  let circuits = [];
  try { circuits = await getJson(`/api/routes/circuits?${routeQuery(query)}`); } catch { /* UEX off */ }
  if (request !== circuitRequest) return;
  list.textContent = '';
  for (const circuit of circuits.slice(0, 6)) {
    const card = el('article', 'route-circuit');
    card.append(el('b', null, `${circuit.commodity} → ${circuit.returnCommodity}`));
    card.append(el('div', 'muted', `${circuit.buyAt} → ${circuit.sellAt} → ${circuit.returnSellAt}`));
    card.append(el('div', 'inward', `~${money(circuit.totalProfit)} total projected profit`));
    const save = el('button', 'ghost tiny', 'Save circuit');
    save.title = 'Save all three circuit stops as an editable flight plan';
    save.addEventListener('click', () => {
      rememberRoute({ commodity: `${circuit.commodity} / ${circuit.returnCommodity}`, buyAt: circuit.buyAt,
        sellAt: circuit.returnSellAt, totalProfit: circuit.totalProfit }, 'circuit');
      planTrip(`${circuit.commodity} ⇄ ${circuit.returnCommodity}`, [
        { placeId: circuit.buyAtId, place: circuit.buyAt, note: `Buy ${Math.floor(circuit.units)} SCU ${circuit.commodity}` },
        { placeId: circuit.sellAtId, place: circuit.sellAt, note: `Sell ${circuit.commodity}; buy ${circuit.returnCommodity}` },
        { placeId: circuit.returnSellAtId, place: circuit.returnSellAt, note: `Sell ${circuit.returnCommodity} · +${money(circuit.returnProfit)}` },
      ]);
    });
    card.append(save);
    list.append(card);
  }
  panel.hidden = circuits.length === 0;
}

/** Save either the best buyer or a named alternate as the same editable flight plan. */
function saveTradeRoute(route, sellAt, sellAtId, sellPrice, label = '') {
  rememberRoute({ ...route, sellAt, sellPrice }, label ? 'alternate' : 'route');
  planTrip(`${route.commodity} run${label}`, [
    {
      placeId: route.buyAtId || placeIdForTerminal(route.buyAt),
      place: route.buyAt,
      note: `Buy ${Math.floor(route.units).toLocaleString()} SCU at ${money(route.buyPrice)}`,
    },
    {
      placeId: sellAtId || placeIdForTerminal(sellAt),
      place: sellAt,
      note: `Sell at ${money(sellPrice)} · +${money((Number(sellPrice) - Number(route.buyPrice)) * Number(route.units))}`,
    },
  ]);
}

function saveSplitTradeRoute(route, portions) {
  const units = portions.reduce((sum, portion) => sum + portion.units, 0);
  const profit = portions.reduce((sum, portion) => sum
    + ((Number(portion.sellPrice) - Number(route.buyPrice)) * portion.units), 0);
  rememberRoute({ ...route, sellAt: `${portions.length} buyers`, profit, outlay: Number(route.buyPrice) * units }, 'split load');
  planTrip(`${route.commodity} split load`, [
    { placeId: route.buyAtId || placeIdForTerminal(route.buyAt), place: route.buyAt,
      note: `Buy ${units.toLocaleString()} SCU at ${money(route.buyPrice)}` },
    ...portions.map((portion) => ({ placeId: portion.placeId || placeIdForTerminal(portion.terminal), place: portion.terminal,
      note: `Sell ${portion.units.toLocaleString()} SCU at ${money(portion.sellPrice)} · +${money((Number(portion.sellPrice) - Number(route.buyPrice)) * portion.units)}` })),
  ]);
}

/** Finds a safer first choice without silently changing a pilot's explicit safety or pad requirement. */
function chooseBestSafeRoute() {
  const active = activePlanningShip();
  if (planningBlocksCargo(active)) {
    renderRouteHeader();
    return;
  }
  $('#routes-ranking').value = 'reliable';
  // Any security is an absence of a preference, so make the safe default
  // explicit. A pilot's chosen avoid/only-lawless mode stays untouched.
  if (!$('#routes-safety').value || $('#routes-safety').value === 'any') $('#routes-safety').value = 'prefer-monitored';
  if ($('#routes-evidence').value === 'any') $('#routes-evidence').value = 'reported';
  highlightBestRoute = true;
  return loadRoutes().catch(() => {});
}

async function loadRoutes() {
  const select = $('#routes-ship');
  if (!select) return;

  if (libraryStats) renderShipPlan();
  let active = activePlanningShip();
  // The Hangar page may never have been opened this session. Fetch the same
  // installed hull record here so an optional-community-data outage does not
  // erase the one fact the install does prove: this is a spaceship.
  if (active && !active.reference && !hangarShips) {
    await loadPlanningInstallData();
    if (libraryStats) renderShipPlan();
    active = activePlanningShip();
  }
  // The raw number remains accepted for the tiny test harness and for a page
  // whose fleet request has not landed yet. Real use replaces it with the
  // selected hull's documented cargo grid as soon as that roster is known.
  const scu = planningCargo(active) || Number(select.value) || 0;
  const capital = Number($('#routes-capital').value) || 0;
  const ranking = $('#routes-ranking').value || 'reliable';
  const freshOnly = $('#routes-fresh-only').checked;
  const evidence = $('#routes-evidence').value || 'reported';
  const safety = $('#routes-safety').value || 'any';
  const pad = $('#routes-pad').value || 'any';
  // "From here" reads the live location the Now page is already showing.
  const here = $('#now-location').textContent.trim();
  const from = $('#routes-here').checked && here && here !== '—' && !here.startsWith('In menus')
    ? here
    : '';
  const originNote = $('#routes-origin-note');
  // A ship whose hold nobody has stated gets the per-SCU table, and the note
  // says why the units are what they are, rather than an empty table asking
  // for a number the pilot may not have to hand.
  const unsized = active && !planningCargoKnown(active);
  originNote.textContent = (from
    ? ` Origin: ${from}; results require UEX to match this terminal.`
    : '')
    + (unsized ? ` Sized per SCU: ${active.ship.name}'s hold is not on record. Enter it above to size a full load.` : '');

  const body = $('#routes-table tbody');
  body.textContent = '';
  const request = ++routeRequest;
  const query = { scu, capital, from, ranking, freshOnly, evidence, safety, pad };

  // A hull known to have no cargo grid cannot make a cargo run. This is
  // deliberately handled before the community-price request: returning a
  // per-SCU table would look like a viable haul despite the selected ship.
  // Only a known zero does this; an unknown hold is sized per SCU above.
  if (planningBlocksCargo(active)) {
    const tr = el('tr');
    const td = el('td', 'muted', planningIsGroundVehicle(active)
      ? `${active.ship.name} is a ground vehicle, so cargo routes are hidden for this plan.`
      : `${active.ship.name} has no documented cargo grid, so cargo routes are hidden for this plan.`);
    td.colSpan = 12;
    tr.append(td);
    body.append(tr);
    setRouteReadiness('needs-cargo', 'No cargo grid', 'The selected hull carries no cargo, so there is nothing to size a route for.');
    highlightBestRoute = false;
    // The panels below the table describe the previous ship's plan otherwise.
    renderRouteDashboard([]);
    const circuits = $('#route-circuits');
    if (circuits) circuits.hidden = true;
    return;
  }

  let rows = [];
  try {
    rows = await getJson(`/api/routes?${routeQuery(query)}`);
  } catch { /* UEX off */ }

  // The initial per-SCU request often leaves before the fleet has loaded. It
  // must not win the race back and overwrite the later request for the ship
  // now shown in the selector.
  if (request !== routeRequest) return;

  if (!rows.length) {
    const tr = el('tr');
    // Name the filter that emptied the table. "No route from here" is the
    // wrong explanation for a table that a tickbox hid every row from, and
    // there are now two tickboxes that can do it.
    const td = el('td', 'muted', safety === 'monitored'
      ? 'No route keeps both ends in monitored space. Try Avoid lawless or Any security.'
      : safety === 'avoid-lawless'
        ? 'No route keeps both ends out of lawless space. Try Any security.'
      : safety === 'lawless'
        ? 'No route touches a lawless system in the available price reports.'
        : pad === 'xl'
          ? 'No route has an XL landing-pad amenity recorded at both ends. Any landing record may show more.'
          : pad === 'known'
            ? 'No route has recorded landing-pad amenities at both ends. Any landing record may show more.'
      : freshOnly
      ? 'Nothing quoted in the last day. Untick "Fresh only" to see older prices.'
      : from
        ? 'No route starts from where you are - or UEX has no terminal here.'
        : evidence === 'full'
          ? 'No route has both sides reporting enough capacity for this load. Try Reported capacity or Include unknown capacity.'
          : evidence === 'reported'
            ? 'No route has stock and demand reported on both sides. Try Include unknown capacity to see price-only estimates.'
            : 'Nothing to show. Enable UEX prices on the Settings page.');
    td.colSpan = 12;
    tr.append(td);
    body.append(tr);
    setRouteReadiness(pad !== 'any' ? 'no-pad' : 'no-prices',
      pad !== 'any' ? 'No viable landing pad' : 'No current prices',
      pad !== 'any' ? 'No returned route has the landing-pad evidence requested at both endpoints.' : 'No route currently meets the selected ship, wallet, evidence, and safety criteria.');
    highlightBestRoute = false;
    renderRouteDashboard(rows);
    loadRouteCircuits(query).catch(() => {});
    return;
  }

  for (const [index, route] of rows.entries()) {
    const tr = el('tr');
    const best = highlightBestRoute && index === 0;
    if (best) tr.classList.add('best-route');
    tr.append(el('td', null, route.commodity));
    tr.append(tdPlace(route.buyAt, 'muted'));
    tr.append(el('td', 'num muted', money(route.buyPrice)));
    tr.append(tdPlace(route.sellAt, 'muted'));
    tr.append(el('td', 'num muted', money(route.sellPrice)));
    tr.append(el('td', 'num', `+${money(route.marginPerScu)}`));
    tr.append(el('td', 'num', Math.floor(route.units).toLocaleString()));
    tr.append(el('td', 'num outward', money(route.outlay)));
    const projected = el('td', 'num inward', `~${money(route.profit)}`);
    projected.title = 'Arithmetic from the two UEX prices, not a promise of live availability.';
    tr.append(projected);

    const report = el('td', 'route-report');
    if (best) report.append(el('div', 'route-best', 'Best safe match'));
    const availabilityWord = route.availability === 'reported-full'
      ? `Reported full load · ${Math.floor(route.desiredUnits).toLocaleString()} SCU`
      : route.availability === 'reported-partial'
        ? `Reported partial · ${Math.floor(route.units).toLocaleString()} / ${Math.floor(route.desiredUnits).toLocaleString()} SCU`
        : `Capacity unknown · projected ${Math.floor(route.units).toLocaleString()} SCU`;
    report.append(el('div', `route-feasibility ${route.availability || 'capacity-unknown'}`, availabilityWord));
    const reportWord = route.freshness === 'fresh' ? 'Fresh reports'
      : route.freshness === 'aging' ? 'Aging reports'
        : route.freshness === 'stale' ? 'Stale reports' : 'Report age unknown';
    report.append(el('div', `route-freshness ${route.freshness || 'unknown'}`, reportWord));
    const age = (at) => at ? ago(at) : 'unknown';
    report.append(el('div', 'muted route-age', `Buy ${age(route.buySeenAt)} · sell ${age(route.sellSeenAt)}`));
    const capacity = [];
    capacity.push(route.buyStockScu > 0
      ? `buy stock ${Math.floor(route.buyStockScu)} SCU (${route.buyAvailability})`
      : 'buy stock unknown');
    capacity.push(route.sellDemandScu > 0
      ? `sell demand ${Math.floor(route.sellDemandScu)} SCU (${route.sellAvailability})`
      : 'sell demand unknown');
    report.append(el('div', 'muted route-capacity', capacity.join(' · ')));

    const access = el('div', 'route-access');
    const security = (value) => value || 'unknown';
    access.append(el('span', 'muted', 'Space: '));
    access.append(el('span', `sec sec-${security(route.buySecurity)}`, security(route.buySecurity)));
    access.append(el('span', 'muted', ' → '));
    access.append(el('span', `sec sec-${security(route.sellSecurity)}`, security(route.sellSecurity)));
    const padNames = (pads) => Array.isArray(pads) && pads.length ? pads.join(', ') : 'no pad record';
    access.append(el('div', 'muted route-pad', `Pads: ${padNames(route.buyLandingPads)} → ${padNames(route.sellLandingPads)}`));
    const usefulAmenities = (items) => (items || []).filter((item) => /refuel|fuel|repair/i.test(item));
    const services = (items) => usefulAmenities(items).length ? usefulAmenities(items).join(', ') : 'no refuel/repair record';
    access.append(el('div', 'muted route-services', `Turnaround: ${services(route.buyAmenities)} → ${services(route.sellAmenities)}`));
    access.append(el('div', 'muted route-timing', 'Time: not estimated — no quantum-drive, fuel, or route-time source is available.'));
    report.append(access);

    const [riskLevel, riskDetail] = routeRisk(route);
    const score = el('div', `route-score ${riskLevel}`,
      `Repeatability ${routeRepeatability(route)}/8 · ${riskDetail} · ${money(route.outlay)} cargo exposure`);
    score.title = 'Repeatability combines UEX quote freshness, reported stock/demand, and alternate buyers. Exposure is the projected purchase cost, not an insurance estimate.';
    report.append(score);

    if (route.fallbackSells?.length) {
      const alternatives = el('div', 'route-alternatives');
      alternatives.append(el('div', 'route-fallback', 'Alternate buyers'));
      for (const fallback of route.fallbackSells) {
        const alternate = el('div', 'route-alternate');
        alternate.append(el('span', 'muted', `${fallback.terminal} · ${money(fallback.sellPrice)} · ${security(fallback.security)}`));
        const save = el('button', 'ghost tiny', 'Save alternate');
        save.title = 'Save this buyer as an editable flight plan';
        save.addEventListener('click', () => saveTradeRoute(
          route, fallback.terminal, fallback.placeId, fallback.sellPrice, ' · alternate buyer'));
        alternate.append(save);
        alternatives.append(alternate);
      }
      const portions = splitTradeRoute(route);
      if (portions.length) {
        const split = el('div', 'route-split');
        split.append(el('span', 'muted', `Split load ${portions.reduce((sum, portion) => sum + portion.units, 0).toLocaleString()} SCU: ${portions.map((portion) => `${portion.terminal} ${portion.units.toLocaleString()}`).join(' · ')}`));
        const saveSplit = el('button', 'ghost tiny', 'Save split');
        saveSplit.title = 'Save the recorded multi-buyer allocation as an editable flight plan';
        saveSplit.addEventListener('click', () => saveSplitTradeRoute(route, portions));
        split.append(saveSplit);
        alternatives.append(split);
      }
      report.append(alternatives);
    }
    tr.append(report);

    // Saving makes a normal editable flight plan: a route is advice until the
    // pilot chooses it, and the plan is where it can be changed or tracked.
    const plan = el('td');
    const button = el('button', 'ghost tiny', route.mapReady ? 'Save route' : 'Save text route');
    button.title = route.mapReady
      ? 'Save this run as an editable flight plan and draw both stops on the map'
      : 'Save the stops as an editable flight plan without claiming both can be drawn on the map';
    button.addEventListener('click', () => saveTradeRoute(route, route.sellAt, route.sellAtId, route.sellPrice));
    plan.append(button);

    const capped = el('td', 'muted', route.limitedBy);
    capped.title = route.limitedBy === 'capital'
      ? 'Your capital runs out before the hold does'
      : route.limitedBy === 'stock'
        ? 'The shop does not stock enough to fill the hold'
        : route.limitedBy === 'demand'
          ? 'The buyer does not report enough demand to take the full run'
        : 'The hold is the limit - the good case';
    tr.append(capped);
    tr.append(plan);

    body.append(tr);
  }

  setRouteReadiness('ready', 'Ready', 'At least one route meets the selected ship, wallet, safety, pad, and evidence filters.');
  highlightBestRoute = false;
  renderRouteDashboard(rows);
  loadRouteCircuits(query).catch(() => {});
}

onInput('#routes-capital', loadRoutes);
$('#routes-ship')?.addEventListener('change', () => choosePlanningShip($('#routes-ship').value));
$('#routes-here')?.addEventListener('change', loadRoutes);
$('#routes-ranking')?.addEventListener('change', loadRoutes);
$('#routes-evidence')?.addEventListener('change', loadRoutes);
$('#routes-fresh-only')?.addEventListener('change', loadRoutes);
$('#routes-safety')?.addEventListener('change', loadRoutes);
$('#routes-pad')?.addEventListener('change', loadRoutes);
$('#routes-profile')?.addEventListener('change', () => {
  applyRouteProfile(routeProfiles.find((profile) => profile.id === $('#routes-profile').value));
});
$('#routes-profile-save')?.addEventListener('click', saveRouteProfile);
$('#routes-best-safe')?.addEventListener('click', chooseBestSafeRoute);
$('#routes-history-clear')?.addEventListener('click', () => {
  routeHistory = [];
  routeWatches = [];
  writeRouteMemory(ROUTE_HISTORY_KEY, routeHistory);
  writeRouteMemory(ROUTE_WATCH_KEY, routeWatches);
  renderRouteDashboard([]);
});
renderRouteProfiles();

/**
 * "Wake up at" on the dashboard: where the last death put you, which is as
 * close as the logs get to naming your regen point. Hidden until there is an
 * answer, and honest about how sure it is.
 */
async function loadRespawn() {
  const card = $('#now-respawn-card');
  if (!card) return;

  let data;
  try {
    data = await getJson('/api/respawn');
  } catch {
    card.hidden = true;
    return;
  }

  if (!data.known) {
    card.hidden = true;
    return;
  }

  // Two signals, neither promoted over the other: a bed is where a regen
  // location gets set, but the same toast fires when one is used only to
  // heal; waking somewhere proves only where you woke. Both are shown and
  // labelled, and the headline is whichever happened last.
  const bedIsNewer = data.bed && (!data.at || new Date(data.bed.at) > new Date(data.at));

  $('#now-respawn').textContent = bedIsNewer ? data.bed.place : (data.place ?? data.bed?.place ?? '—');

  // Each line names its own place. The headline is only the more recent of
  // the two, and saying "woke there" under a different place read as though
  // both signals agreed when they do not.
  $('#now-respawn-sub').textContent = data.bed
    ? `last medical bed · ${data.bed.place}, ${relative(data.bed.at)}`
    : '';

  // "Deaths" would be wrong for the commoner case: most wake-ups follow an
  // incapacitation rather than a corpse recovery, so both read as "times down".
  $('#now-respawn-bed').textContent = data.place
    ? (data.settled
      ? `last woke · ${data.place}, ${data.agreeing} of your last ${data.of} times down`
      : `last woke · ${data.place}, ${relative(data.at)}`)
    : '';

  card.hidden = false;
}

/* ---------- casualties ---------- */

async function loadCasualties() {
  const days = Number($('#casualties-period').value) || 0;

  let data;
  try {
    data = await getJson(`/api/casualties?days=${days}`);
  } catch {
    return;
  }

  tiles('#casualties-summary', [
    ['Deaths', data.deaths],
    ['Incapacitations', data.incapacitations],
    ['Sessions with a death', data.sessionsWithDeaths],
    ['Claim fees*', data.estimatedFees > 0 ? money(data.estimatedFees) : '—'],
  ]);

  bars('#casualties-places',
    data.byPlace.map((p) => ({
      label: p.place, value: p.deaths, onClick: () => jumpToPlace(p.place),
    })),
    (v) => `${v}`);

  bars('#casualties-ships',
    data.byShip.map((s) => ({ label: s.ship, value: s.deaths })),
    (v) => `${v}`);

  bars('#casualties-woke',
    (data.wokeAt || []).map((w) => ({
      label: w.place, value: w.times, onClick: () => jumpToPlace(w.place),
    })),
    (v) => `${v}`);

  bars('#casualties-beds',
    (data.bedsUsed || []).map((b) => ({
      label: b.afterDeath ? `${b.place} · ${b.afterDeath} after a death` : b.place,
      value: b.times,
      onClick: () => jumpToPlace(b.place),
    })),
    (v) => `${v}`);

  // The logins are counted and shown rather than hidden: leaving them out
  // silently would make the totals look wrong to anyone who remembers using a
  // bed more often than this.
  const kinds = data.bedKinds;

  if (kinds) {
    const parts = [];
    if (kinds.afterDeath) parts.push(`${kinds.afterDeath} after a death or incapacitation`);
    if (kinds.heal) parts.push(`${kinds.heal} used mid-session, which could be either`);
    if (kinds.hab) parts.push(`${kinds.hab} at places with no clinic, so hab beds - not counted above`);
    if (kinds.wake) parts.push(`${kinds.wake} were waking up at login, not counted above`);

    // The directory can only rule a bed out, and only if it is on disk. Say so
    // rather than leaving the mid-session pile unexplained.
    if (!kinds.clinicsKnown) {
      parts.push('enable the place directory in Settings to rule out beds at places with no clinic');
    }

    $('#beds-kinds').textContent = parts.join(' · ');
  }

  $('#casualties-woke-note').textContent = data.lastWokeAt
    ? `Last woke at ${data.lastWokeAt}, ${relative(data.lastWokeWhen)}. Inferred, `
      + 'not read: the game logs no respawn point, so this is the first place '
      + 'named after each death.'
    : 'Nothing to infer yet. This reads the first place named after a death, '
      + 'because the game logs no respawn point of its own.';

  const body = $('#casualties-fees tbody');
  body.textContent = '';

  // Guarded like every other read on this page: one absent array should not
  // take the whole page down when the rest of the answer arrived intact.
  for (const fee of data.fees || []) {
    const tr = el('tr');
    tr.append(el('td', null, fee.name));
    tr.append(el('td', 'num outward', money(fee.fee)));
    body.append(tr);
  }
}

onInput('#casualties-period', loadCasualties);

/* ---------- crew ---------- */

/**
 * The ships you and somebody else were both aboard.
 *
 * The party channel says who was online while grouped with you; this says who
 * was actually in the vehicle, and whose it was. It is the only thing in these
 * logs that ties a person to a ship.
 *
 * Deliberately counted in boardings rather than hours. There is no leave line
 * for you, a channel opens when somebody gets in rather than when the ship
 * flies, and a parked Cyclone reads the same as a crossing - so the caption
 * says so instead of letting a number imply time spent together.
 */
async function renderSharedShips(days) {
  const host = $('#crew-ships');
  if (!host) return;

  host.textContent = '';

  let ships;
  try {
    ships = await getJson(`/api/crew/ships?days=${days}`);
  } catch {
    return;
  }

  if (!ships.length) return;

  const card = el('section', 'shared-block');
  card.append(el('h3', null, 'Ships you have shared'));
  card.append(el('p', 'muted', 'Who was aboard which ship, from its comms channel — the only '
    + 'lines that put a person in a vehicle. Counted in boardings, not hours: nothing records '
    + 'how long anyone stayed, and a parked ship looks the same as a crossing.'));

  const table = el('table', 'data');
  const head = el('thead');
  const headRow = el('tr');
  for (const label of ['Pilot', 'Ship', 'Whose', 'Boardings', 'First', 'Last']) {
    headRow.append(el('th', label === 'Boardings' ? 'num' : null, label));
  }
  head.append(headRow);
  table.append(head);

  const body = el('tbody');
  const mine = ships.filter((s) => s.owner === s.handle).length;

  for (const ship of ships) {
    const tr = el('tr');
    tr.append(el('td', null, ship.handle));
    tr.append(el('td', null, ship.ship));

    // Whose ship it was is the interesting half: crewing for somebody is a
    // different evening from having them aboard yours.
    tr.append(el('td', 'muted', ship.owner === ship.handle ? 'theirs' : 'yours'));

    tr.append(el('td', 'num', String(ship.times)));
    tr.append(el('td', 'muted', dateOf(ship.first)));
    tr.append(el('td', 'muted', dateOf(ship.last)));
    body.append(tr);
  }

  table.append(body);
  card.append(table);

  card.append(el('p', 'muted', `${ships.length} pairing${ships.length === 1 ? '' : 's'}`
    + `${mine ? `, ${mine} of them in a ship that was not yours` : ''}.`));

  host.append(card);
}


/**
 * The people the party channel has named.
 *
 * The counts are arrivals and departures, not time together, and the page says
 * so rather than dressing them up as a friends list. Anyone who was already
 * online when you grouped up and stayed to the end never produced a toast, so
 * absence from this table means nothing at all - which is exactly why the
 * summary counts what was *seen* rather than claiming a total.
 */
async function loadCrew() {
  const table = $('#crew-table');
  if (!table) return;

  const days = Number($('#crew-period').value) || 0;

  let rows;
  try {
    rows = await getJson(`/api/crew?days=${days}`);
  } catch {
    return;
  }

  renderSharedShips(days).catch(() => {});

  const joins = rows.reduce((total, r) => total + (r.joined || 0), 0);
  const arrivals = rows.reduce((total, r) => total + r.connected, 0);

  tiles('#crew-summary', [
    ['People named', rows.length],

    // Joins rather than arrivals: this is the one that counts somebody who was
    // not there a moment before, which is what "flew with" means.
    ['Joined your party', joins],
    ['Came online', arrivals],
    ['Most flown with', rows.length ? rows[0].handle : '—'],
  ]);

  bars('#crew-chart',
    rows.slice(0, 12).map((r) => ({
      label: r.handle,
      value: r.sessions,
      note: `${r.connected} arrival${r.connected === 1 ? '' : 's'}`,
    })),
    (v) => `${v} session${v === 1 ? '' : 's'}`);

  const body = table.querySelector('tbody');
  body.textContent = '';

  if (!rows.length) {
    const tr = el('tr');
    const td = el('td', 'muted',
      'Nobody named in that range — the game only says so when someone joins, '
      + 'leaves, or connects while you are partied with them.');
    td.colSpan = 9;
    tr.append(td);
    body.append(tr);
    return;
  }

  for (const row of rows) {
    const tr = el('tr');
    tr.append(el('td', null, row.handle));
    tr.append(el('td', 'num', String(row.sessions)));

    // Blank rather than zero throughout: these are four different facts and a
    // zero in one of them is usually "the game did not say", not "never".
    tr.append(el('td', row.joined ? 'num' : 'num muted', row.joined || '—'));
    tr.append(el('td', row.left ? 'num' : 'num muted', row.left || '—'));
    tr.append(el('td', 'num', String(row.connected)));
    tr.append(el('td', 'num', String(row.dropped)));

    tr.append(el('td', row.ledParty ? 'num' : 'num muted', row.ledParty || '—'));

    tr.append(el('td', 'muted', dateOf(row.first)));
    tr.append(el('td', 'muted', dateOf(row.last)));
    body.append(tr);
  }
}

onInput('#crew-period', loadCrew);

/* ---------- servers ---------- */

/** The last /api/servers answer, kept so a star or a note can redraw without a round trip. */
let serverRows = [];
let serverNewestDeployment = null;

/** The shard the live stream says the client is on, so the row can be lit and re-lit as it changes. */
let serverCurrent = null;

/** What each ending means to a pilot, and whether it counts against the server. */
const SHARD_ENDINGS = {
  Left: ['left', false],
  Idle: ['idle kick', false],
  Quit: ['quit to desktop', false],
  Backend: ['back-end gave up', true],
  LogEnded: ['log ended', true],
  Replaced: ['moved by the game', true],
  Open: ['on it now', false],
};

function endingLabel(ending) {
  return (SHARD_ENDINGS[ending] || [String(ending || '').toLowerCase(), false])[0];
}

/**
 * The servers this install has been placed on, with the pilot's own notes.
 *
 * The default filter is the current deployment, because that is the only set
 * a note can still act on: a shard from a retired deployment cannot be joined
 * again, and showing it first would put advice about nowhere at the top. The
 * old ones are one untick away, greyed, with their notes intact.
 */
async function loadServers() {
  const table = $('#servers-table');
  if (!table) return;

  let data;
  try {
    data = await getJson('/api/servers');
  } catch {
    return;
  }

  serverRows = data.servers || [];
  serverNewestDeployment = data.newestDeployment || null;
  serverCurrent = data.current || null;

  fillServerRegions(serverRows);
  renderServers();
}

/** Region choices come from the data: this install has seen four, another may see one. */
function fillServerRegions(rows) {
  const select = $('#servers-region');
  if (!select) return;

  const keep = select.value;
  const regions = [...new Set(rows.map((r) => r.region))].sort();

  select.textContent = '';
  const all = el('option', null, 'All regions');
  all.value = '';
  select.append(all);

  for (const region of regions) {
    const option = el('option', null, region);
    option.value = region;
    select.append(option);
  }

  select.value = regions.includes(keep) ? keep : '';
}

function filteredServers() {
  const term = ($('#servers-search')?.value || '').trim().toLowerCase();
  const region = $('#servers-region')?.value || '';
  const currentOnly = !!$('#servers-current')?.checked;
  const starredOnly = !!$('#servers-starred')?.checked;
  const troubledOnly = !!$('#servers-troubled')?.checked;

  return serverRows.filter((r) => {
    if (currentOnly && !r.current) return false;
    if (starredOnly && !r.favorite) return false;
    if (troubledOnly && !(r.endings?.Backend > 0)) return false;
    if (region && r.region !== region) return false;
    if (term) {
      const hay = `${r.shard} ${r.seenName || ''} ${r.disposition || ''} ${r.region} ${r.note || ''} ${(r.places || []).map((p) => p.name).join(' ')}`.toLowerCase();
      if (!hay.includes(term)) return false;
    }
    return true;
  });
}

function renderServers() {
  const table = $('#servers-table');
  if (!table) return;

  const rows = filteredServers();
  const all = serverRows;

  // Favourites first, then the most recent - so a starred shard from tonight
  // beats a starred one from last week, and both beat everything else.
  // The shard you are on right now leads whatever else is true of it: it is
  // the one row a pilot came to the page to find. Then favourites, then newest.
  rows.sort((a, b) => ((b.shard === serverCurrent) - (a.shard === serverCurrent))
    || (b.favorite - a.favorite) || (new Date(b.last) - new Date(a.last)));

  const current = all.filter((r) => r.current);
  const visits = all.reduce((total, r) => total + r.visits, 0);
  const backendEnds = all.reduce((total, r) => total + (r.endings?.Backend || 0), 0);

  tiles('#servers-summary', [
    ['Shards visited', all.length],
    ['Still running', current.length],
    ['Placements', visits],
    ['Back-end ends', backendEnds],
    ['Favourites', all.filter((r) => r.favorite).length],
    ['Marked avoid', all.filter((r) => r.disposition === 'avoid').length],
    ['On now', serverCurrent || 'not on a shard'],
    ['Newest deployment', serverNewestDeployment || '—'],
  ]);

  const body = table.querySelector('tbody');
  body.textContent = '';

  if (!rows.length) {
    const tr = el('tr');
    const td = el('td', 'muted', all.length
      ? 'Nothing matches those filters. Untick "Current deployment only" to see shards from earlier deployments.'
      : 'No shard joins yet. The game writes one <Join PU> line each time it places you; '
        + 'sessions summarised before this build read it will show up after a rescan.');
    td.colSpan = 10;
    tr.append(td);
    body.append(tr);
    return;
  }

  for (const row of rows) body.append(serverRow(row));
}

function serverRow(row) {
  const tr = el('tr', row.current ? null : 'gone');
  tr.dataset.shard = row.shard;
  if (row.shard === serverCurrent) tr.classList.add('here');

  const starCell = el('td');
  const star = el('button', `ghost tiny star${row.favorite ? ' on' : ''}`, row.favorite ? '★' : '☆');
  star.type = 'button';
  star.title = row.favorite ? 'Remove from favourites' : 'Add to favourites';
  star.addEventListener('click', () => setServerFavorite(row.shard, !row.favorite).catch(() => {}));
  starCell.append(star);
  tr.append(starCell);

  tr.append(dispositionCell(row));

  const shard = el('td', 'shard');
  shard.append(document.createTextNode(row.shard));
  if (row.shard === serverCurrent) shard.append(el('span', 'here-badge', 'on now'));
  shard.append(seenNameText(row));
  shard.append(serverActions(row));
  shard.append(el('small', null, row.current
    ? `deployment ${row.deployment}`
    : `deployment ${row.deployment} — retired`));
  tr.append(shard);

  tr.append(el('td', null, row.region));
  tr.append(el('td', 'num', row.visits ? String(row.visits) : '—'));
  tr.append(el('td', 'num', row.time ? duration(row.time) : '—'));

  const last = el('td', 'muted', row.visits ? relative(row.last) : 'never seen here');
  last.title = row.visits
    ? dateOf(row.last)
    : 'This note arrived from a backup; the logs on this machine never joined it.';
  tr.append(last);

  tr.append(endingCell(row));
  tr.append(placesCell(row));

  const note = el('td', 'note-cell');
  note.append(noteText(row));
  tr.append(note);

  return tr;
}

/** A personal marker is advice, not evidence about the game or a public rating. */
function dispositionCell(row) {
  const td = el('td', 'server-disposition');
  const select = el('select', `select tiny${row.disposition ? ` ${row.disposition}` : ''}`);
  for (const [value, label] of [['', '—'], ['good', 'Good'], ['avoid', 'Avoid']]) {
    const option = el('option', null, label);
    option.value = value;
    select.append(option);
  }
  select.value = row.disposition || '';
  select.title = 'Your personal server marker';
  select.addEventListener('change', () => setServerDisposition(row.shard, select.value).catch(() => {
    select.value = row.disposition || '';
  }));
  td.append(select);
  return td;
}

function seenNameText(row) {
  const text = el('small', `seen-name${row.seenName ? '' : ' empty'}`,
    row.seenName ? `Seen in game: ${row.seenName}` : 'Add game label…');
  text.title = 'Click to record the name the game showed you';
  text.tabIndex = 0;
  text.addEventListener('click', () => editServerSeenName(row, text));
  text.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') { e.preventDefault(); editServerSeenName(row, text); }
  });
  return text;
}

function editServerSeenName(row, text) {
  const box = el('input', 'search');
  box.type = 'text';
  box.value = row.seenName || '';
  box.maxLength = 80;
  box.placeholder = 'amazing_view';

  let done = false;
  const finish = (save) => {
    if (done) return;
    done = true;
    if (save && box.value.trim() !== (row.seenName || '')) {
      saveServerSeenName(row.shard, box.value).catch(() => box.replaceWith(seenNameText(row)));
    } else box.replaceWith(seenNameText(row));
  };
  box.addEventListener('blur', () => finish(true));
  box.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') finish(false);
    if (e.key === 'Enter') finish(true);
  });
  text.replaceWith(box);
  box.focus();
}

function serverActions(row) {
  const actions = el('div', 'server-actions');
  const copy = el('button', 'ghost tiny', 'Copy ID');
  copy.type = 'button';
  copy.addEventListener('click', () => copyServerText(row.shard, copy));
  const report = el('button', 'ghost tiny', 'Copy report');
  report.type = 'button';
  report.addEventListener('click', () => copyServerText(serverReport(row), report));
  actions.append(copy, report);
  return actions;
}

function serverReport(row) {
  // A note-only row - a shard these logs never joined - has no visit to
  // report. The cells say "never seen here"; the pasted line must not invent
  // a date and an ending the table itself refuses to show.
  if (!row.visits) return `Quantumwake server report: shard ${row.shard}; region ${row.region}; no visit recorded on this machine.`;
  const ending = row.shard === serverCurrent ? 'still connected' : endingLabel(row.lastEnding);
  const when = row.shard === serverCurrent ? 'now' : dateOf(row.last);
  const stay = row.lastDuration ? ` after ${duration(row.lastDuration)}` : '';
  return `Quantumwake server report: shard ${row.shard}; region ${row.region}; ${when}; ${ending}${stay}.`;
}

/**
 * Puts text on the clipboard and says so on the button.
 *
 * navigator.clipboard exists only in a secure context, and the app has a LAN
 * mode: on the tablet at http://192.168.x.x the API is simply absent, so the
 * old-style selection copy is the fallback rather than a silent nothing. A
 * refusal - document not focused, permission denied - is reported the same
 * way, on the button, because an unhandled rejection tells the pilot nothing.
 */
async function copyServerText(value, button) {
  const was = button.textContent;
  const say = (text) => {
    button.textContent = text;
    setTimeout(() => { button.textContent = was; }, 1200);
  };

  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(value);
    } else {
      const box = el('textarea');
      box.value = value;
      box.setAttribute('readonly', '');
      box.style.position = 'fixed';
      box.style.opacity = '0';
      document.body.append(box);
      box.select();
      const ok = document.execCommand && document.execCommand('copy');
      box.remove();
      if (!ok) throw new Error('copy refused');
    }
    say('Copied');
  } catch {
    say('Could not copy');
  }
}

/**
 * How the stays ended. The last ending is what a pilot remembers about a
 * server, so it leads; the tally behind it says whether that was the pattern
 * or the exception.
 */
function endingCell(row) {
  const td = el('td', 'ending');
  if (!row.visits) {
    td.append(el('span', 'muted', '—'));
    return td;
  }

  const [label, bad] = SHARD_ENDINGS[row.lastEnding] || [String(row.lastEnding).toLowerCase(), false];
  td.append(el('span', bad ? 'bad' : null, label));

  if (row.visits > 1) {
    const rest = Object.entries(row.endings || {})
      .filter(([kind]) => kind !== 'Open')
      .sort((a, b) => b[1] - a[1])
      .map(([kind, n]) => `${n}× ${endingLabel(kind)}`)
      .join(', ');
    if (rest) td.append(el('small', 'muted', ` · ${rest}`));
  }

  return td;
}

/**
 * Where the pilot went while on this shard: the latest place, and a button
 * for the rest. An evening on one shard can touch a dozen places, and a
 * column that listed them all would be a route, not a cell - so the most
 * recent one stands for the stay, and the rest unfold in place on request.
 */
function placesCell(row) {
  const td = el('td', 'places');
  const places = row.places || [];

  if (!places.length) {
    td.append(el('span', 'muted', row.visits ? 'nowhere named' : '—'));
    td.title = row.visits
      ? 'No arrival was logged while on this shard - a stay spent in a ship, or too short to land.'
      : '';
    return td;
  }

  const [latest, ...rest] = places;
  td.append(el('span', 'place', latest.name));
  if (latest.visits > 1) td.append(el('small', 'muted', ` ×${latest.visits}`));

  if (!rest.length) return td;

  const list = el('ul', 'place-list');
  list.hidden = true;
  for (const p of rest) {
    const li = el('li', null, p.name);
    if (p.visits > 1) li.append(el('small', 'muted', ` ×${p.visits}`));
    list.append(li);
  }

  const more = el('button', 'ghost tiny more', `+${rest.length} more`);
  more.type = 'button';
  more.addEventListener('click', () => {
    list.hidden = !list.hidden;
    more.textContent = list.hidden ? `+${rest.length} more` : 'fewer';
  });

  td.append(more, list);
  return td;
}

function noteText(row) {
  const text = el('div', `note-text${row.note ? '' : ' empty'}`, row.note || 'Add a note…');
  text.title = 'Click to edit';
  text.tabIndex = 0;
  text.addEventListener('click', () => editServerNote(row, text));
  text.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') { e.preventDefault(); editServerNote(row, text); }
  });
  return text;
}

/** Swaps the text for a box; Escape abandons, blur or Ctrl+Enter saves. */
function editServerNote(row, text) {
  const box = el('textarea');
  box.value = row.note || '';
  box.maxLength = 1000;
  box.placeholder = 'Laggy elevators, two 30ks, good for bunkers…';

  let done = false;
  const finish = (save) => {
    if (done) return;
    done = true;
    if (save && box.value.trim() !== (row.note || '')) {
      saveServerNote(row.shard, box.value).catch(() => box.replaceWith(noteText(row)));
    } else {
      box.replaceWith(noteText(row));
    }
  };

  box.addEventListener('blur', () => finish(true));
  box.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') finish(false);
    if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) finish(true);
  });

  text.replaceWith(box);
  box.focus();
}

async function saveServerNote(shard, note) {
  const res = await fetch(`/api/servers/${encodeURIComponent(shard)}/note`, {
    method: 'PUT', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ note }),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);

  const saved = await res.json();
  applyServerChange(shard, saved);
}

async function setServerFavorite(shard, favorite) {
  const res = await fetch(`/api/servers/${encodeURIComponent(shard)}/favorite`, {
    method: 'PUT', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ favorite }),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);

  const saved = await res.json();
  applyServerChange(shard, saved);
}

async function saveServerSeenName(shard, name) {
  const res = await fetch(`/api/servers/${encodeURIComponent(shard)}/seen-name`, {
    method: 'PUT', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ name }),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  applyServerChange(shard, await res.json());
}

async function setServerDisposition(shard, disposition) {
  const res = await fetch(`/api/servers/${encodeURIComponent(shard)}/disposition`, {
    method: 'PUT', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ disposition }),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  applyServerChange(shard, await res.json());
}

/** Folds a saved change into the rows in hand and redraws both places that show it. */
function applyServerChange(shard, change) {
  const row = serverRows.find((r) => r.shard === shard);
  if (row) Object.assign(row, change);
  renderServers();

  if (nowState && nowState.shard === shard) {
    nowState = { ...nowState,
      shardNote: change.note || null,
      shardFavorite: !!change.favorite,
      shardSeenName: change.seenName || null,
      shardDisposition: change.disposition || null };
    renderNowServer(nowState);
  }
}

/**
 * The Now card: which server you are on, and what you said about it last time.
 *
 * Shown from the moment of placement, because that is when the information
 * is worth having - once you have flown out to a bunker, "you noted this one
 * as unstable" is a complaint rather than a warning.
 */
function renderNowServer(state) {
  const card = $('#now-server-card');
  if (!card) return;

  card.hidden = !state.shard;
  if (card.hidden) return;

  $('#now-server').textContent = state.shardSeenName || state.shardShort || state.shard;
  $('#now-server-name').textContent = state.shard;

  const before = state.shardVisitsBefore || 0;
  const parts = [before === 0
    ? 'First time on this shard.'
    : `Placed here ${before} time${before === 1 ? '' : 's'} before.`];
  if (state.shardSeenName) parts.push(`Name shown by the game: “${state.shardSeenName}”.`);
  if (state.shardDisposition === 'avoid') parts.push('You marked this shard avoid.');
  if (state.shardDisposition === 'good') parts.push('You marked this shard good.');
  if (state.shardNote) parts.push(`Your note: “${state.shardNote}”`);

  const note = $('#now-server-note');
  note.textContent = parts.join(' ');
  note.className = `note${state.shardNote || state.shardDisposition === 'avoid' ? ' warn' : ''}`;

  const star = $('#now-server-star');
  star.textContent = state.shardFavorite ? '★ Favourite' : '☆ Favourite';
  star.className = `ghost tiny${state.shardFavorite ? ' on' : ''}`;
  star.onclick = () => setServerFavorite(state.shard, !state.shardFavorite).catch(() => {});

  $('#now-server-open').onclick = () => {
    const search = $('#servers-search');
    if (search) search.value = state.shard;
    const current = $('#servers-current');
    if (current) current.checked = false;
    showView('servers');
  };
}

onInput('#servers-search', renderServers);
onInput('#servers-region', renderServers);
onInput('#servers-current', renderServers);
onInput('#servers-starred', renderServers);

/* ---------- garage ---------- */

/** The ship on the bench, by class, and the last sheet drawn for it. */
let garageClass = null;
let garageStock = null;
let garageSheet = null;

/** Ports named for the game's files; this is what a pilot calls them. */
const GARAGE_GROUP_WORDS = {
  QuantumDrive: 'Quantum drive',
  Shield: 'Shield generator',
  PowerPlant: 'Power plant',
  Cooler: 'Cooler',
  WeaponGun: 'Gun',
  Turret: 'Gun mount',
  TurretBase: 'Turret',
  MissileLauncher: 'Missile rack',
  Missile: 'Missile',
  Radar: 'Radar',
  EMP: 'EMP',
  QuantumInterdictionGenerator: 'Quantum interdiction',
  WeaponMining: 'Mining laser',
  SalvageHead: 'Salvage head',
  Armor: 'Armour',
  LifeSupportGenerator: 'Life support',
  FlightController: 'Flight controller',
  FuelTank: 'Fuel tank',
  QuantumFuelTank: 'Quantum fuel tank',
  WeaponDefensive: 'Countermeasures',
  TractorBeam: 'Tractor beam',
  Misc: 'Utility',
};

const garageWord = (group) => GARAGE_GROUP_WORDS[group] || String(group || '').replace(/([a-z])([A-Z])/g, '$1 $2');

/** A hardpoint name as a pilot reads it: hardpoint_shield_generator_left → shield generator left. */
function garagePortName(hardpoint) {
  return String(hardpoint || '')
    .replace(/^hardpoint_/i, '')
    .replace(/_attach$/i, '')
    .replace(/_/g, ' ');
}

const fmtInt = (n) => Math.round(Number(n) || 0).toLocaleString();
const fmt1 = (n) => (Math.round((Number(n) || 0) * 10) / 10).toLocaleString(undefined, { maximumFractionDigits: 1 });

/** Metres to the unit a pilot uses: Gm for ranges, km for anything shorter. */
function fmtDistance(metres) {
  const m = Number(metres) || 0;
  if (m >= 1e9) return `${(m / 1e9).toLocaleString(undefined, { maximumFractionDigits: 1 })} Gm`;
  if (m >= 1e6) return `${(m / 1e6).toLocaleString(undefined, { maximumFractionDigits: 1 })} Mm`;
  return `${(m / 1e3).toLocaleString(undefined, { maximumFractionDigits: 1 })} km`;
}

/** Drive speed, in km/s - the figure the in-game drive screen shows. */
const fmtSpeed = (mps) => `${Math.round((Number(mps) || 0) / 1000).toLocaleString()} km/s`;

async function loadGarage() {
  const mine = $('#garage-mine');
  if (!mine) return;

  let data;
  try {
    data = await getJson('/api/garage');
  } catch {
    return;
  }

  const unavailable = $('#garage-unavailable');
  if (!data.known) {
    unavailable.hidden = false;
    unavailable.textContent = 'The reference data predates the garage. Refresh the community dataset in Settings '
      + 'and this page fills in - it needs the part figures the older download did not keep.';
    return;
  }
  unavailable.hidden = true;

  fillGaragePicker(mine, 'Your fleet…', data.mine.map((s) => [s.class, `${s.name} · ${s.sorties} sortie${s.sorties === 1 ? '' : 's'}`]));
  fillGaragePicker($('#garage-all'), 'Any ship…', data.all.map((s) => [s.class, `${s.name}${s.role ? ` · ${s.role}` : ''}`]));

  // Open the ship already on the bench, else the one flown most, else nothing.
  const first = garageClass || data.mine[0]?.class || null;
  if (first) await openGarage(first);
}

function fillGaragePicker(select, prompt, entries) {
  if (!select) return;
  const keep = select.value;
  select.textContent = '';
  const head = el('option', null, prompt);
  head.value = '';
  select.append(head);
  for (const [value, label] of entries) {
    const option = el('option', null, label);
    option.value = value;
    select.append(option);
  }
  select.value = entries.some(([v]) => v === keep) ? keep : '';
}

/*
 * Every fetch on this page is answered later than it was asked, and the pilot
 * can change ship, port or fit in between. Each of the three asks carries a
 * ticket; an answer whose ticket is no longer the newest is dropped, so a slow
 * sheet for the Corsair cannot land on a bench that has moved on to the Cutlass
 * - which it did, and a build saved then carried the wrong ship's ports.
 */
let garageRequest = 0;
let benchRequest = 0;
let refitRequest = 0;

/** Puts a ship on the bench: its stock sheet, and its ports. */
async function openGarage(cls) {
  const request = ++garageRequest;
  garageClass = cls;
  // A new ship is a clean bench: swaps belong to the ship they were made on.
  garageSwaps = {};
  garageSelectedPort = null;
  garageOptions = null;
  $('#garage-optimise-status').textContent = '';
  for (const id of ['#garage-mine', '#garage-all']) {
    const select = $(id);
    if (select && [...select.options].some((o) => o.value === cls)) select.value = cls;
    else if (select) select.value = '';
  }

  let data;
  try {
    data = await getJson(`/api/garage/${encodeURIComponent(cls)}`);
  } catch {
    if (request !== garageRequest) return;
    const unavailable = $('#garage-unavailable');
    unavailable.hidden = false;
    unavailable.textContent = `The reference does not know a ship called ${cls}.`;
    return;
  }
  if (request !== garageRequest) return;

  garageStock = data;
  garageSheet = data.sheet;
  garageOpenBuild = null;
  garageCompare = '';
  garageSheetCache.clear();
  renderGarage(data, null);
  await loadBuilds();
  loadGarageMarket(cls).catch(() => { /* the panel says the feed is off or unread */ });
  loadGaragePhoto(cls).catch(() => { /* no reading of this ship: the offer stays hidden */ });
  loadGarageCargo(cls).catch(() => { /* the panel hides itself when the hull has no grids to draw */ });
}

/* ---------- cargo fit: does a load of crates fit this hull? ---------- */

let garageCargo = null;
let garageCargoResult = null;
const CARGO_CRATE_SIZES = [1, 2, 4, 8, 16, 24, 32];
const CARGO_CRATE_COLOURS = { 1: '#6bbaff', 2: '#57d8ac', 4: '#e8b35e', 8: '#f27f68', 16: '#bc8cff', 24: '#35c8f0', 32: '#ff9ad5' };

/** The counts typed in, by crate size; kept across ships so the same load can be tried on the next hull. */
let garageCargoLoad = {};
try {
  const kept = JSON.parse(localStorage.getItem('qw-cargo-load') || '{}');
  if (kept && typeof kept === 'object') garageCargoLoad = kept;
} catch { /* a private window has no memory, which is fine */ }

/** The ship's grids, drawn empty; the load inputs; the fleet answer only once asked. */
async function loadGarageCargo(cls) {
  const box = $('#garage-cargo');
  if (!box) return;
  garageCargoResult = null;
  try {
    garageCargo = await getJson(`/api/cargo/${encodeURIComponent(cls)}`);
  } catch {
    garageCargo = null;
  }
  if (!garageCargo) { box.hidden = true; return; }
  box.hidden = false;

  const sub = $('#garage-cargo-sub');
  const grids = garageCargo.grids || [];
  if (!garageCargo.gridsKnown) {
    sub.textContent = 'The reference data predates cargo grids. Refresh the community dataset in Settings and this hull’s holds will be drawn.';
  } else if (grids.length === 0) {
    sub.textContent = `The dataset places no cargo grid on the ${garageCargo.name}${garageCargo.cargoScu ? ` though it credits it with ${fmt1(garageCargo.cargoScu)} SCU` : ''} — nothing to pack into.`;
  } else {
    const kinds = new Map();
    for (const g of grids) kinds.set(g.class, (kinds.get(g.class) || 0) + 1);
    sub.textContent = `${grids.length} grid${grids.length === 1 ? '' : 's'}, ${fmt1(grids.reduce((a, g) => a + g.scu, 0))} SCU by the dataset’s own placement: `
      + [...kinds].map(([k, n]) => { const g = grids.find((x) => x.class === k); return `${n > 1 ? `${n} × ` : ''}${fmt1(g.x)} × ${fmt1(g.y)} × ${fmt1(g.z)} m`; }).join(', ')
      + '. Type a load and see where each crate would go.';
  }

  renderCargoLoadInputs();
  renderCargoGrids(grids.map(cargoEmpty), null);
  const fleet = $('#garage-cargo-fleet');
  if (fleet) { fleet.hidden = true; fleet.textContent = ''; }
  $('#garage-cargo-verdict').textContent = '';
  $('#garage-cargo-note').textContent = garageCargo.cratesFromInstall
    ? 'Crate sizes are read from your install: 1 SCU is 1.25 m cubed, and the 16, 24 and 32 are one lane wide and 5, 7.5 and 10 m long. A crate keeps its top up and may turn on the spot; anything stacks on anything; nothing hangs over an edge. The packing is this app’s, largest crate first: a fit found is real, a fit not found is not proof.'
    : 'The install has not been read yet, so the crate sizes are the table read from it on 16 Sep 2026. The packing is this app’s, largest crate first: a fit found is real, a fit not found is not proof.';

  // A load already typed - or brought from another hull's answer - is tried
  // straight away, so the fleet list is a link and not a form.
  if (garageCargo.gridsKnown && grids.length && Object.keys(cargoLoadNow()).length) await fitCargo();
}

function cargoCells(g) {
  return { w: Math.round(g.x / 1.25), l: Math.round(g.y / 1.25), h: Math.round(g.z / 1.25) };
}

/** The empty drawing, before a fit: the same one-cell-rule line the packer draws, so the caption does not change under the crates. */
function cargoEmpty(g) {
  const one = g.maxBox && Math.round(g.maxBox.x / 1.25) === 1 && Math.round(g.maxBox.y / 1.25) === 1 && Math.round(g.maxBox.z / 1.25) === 1;
  return { grid: g, cells: cargoCells(g), placed: [], usedScu: 0, ruleIgnored: !!one && g.scu >= 16 };
}

function renderCargoLoadInputs() {
  const box = $('#garage-cargo-load');
  if (!box) return;
  box.textContent = '';
  for (const size of CARGO_CRATE_SIZES) {
    const field = el('label', 'garage-cargo-crate');
    const swatch = el('span', 'garage-cargo-swatch');
    swatch.style.background = CARGO_CRATE_COLOURS[size];
    field.append(swatch, el('span', 'garage-cargo-size', `${size} SCU`));
    const input = el('input');
    input.type = 'number';
    input.min = '0';
    input.max = '999';
    input.inputMode = 'numeric';
    input.dataset.size = String(size);
    input.value = garageCargoLoad[size] ? String(garageCargoLoad[size]) : '';
    input.placeholder = '0';
    input.setAttribute('aria-label', `${size} SCU crates`);
    input.addEventListener('input', () => {
      garageCargoLoad[size] = Math.max(0, parseInt(input.value, 10) || 0);
      try { localStorage.setItem('qw-cargo-load', JSON.stringify(garageCargoLoad)); } catch { /* as above */ }
      renderCargoTotal();
    });
    field.append(input);
    box.append(field);
  }
  box.append(el('span', 'garage-cargo-total muted', ''));
  renderCargoTotal();
}

function cargoLoadNow() {
  const crates = {};
  for (const size of CARGO_CRATE_SIZES) if (garageCargoLoad[size] > 0) crates[size] = garageCargoLoad[size];
  return crates;
}

function renderCargoTotal() {
  const total = $('#garage-cargo-load')?.querySelector('.garage-cargo-total');
  if (!total) return;
  const crates = cargoLoadNow();
  const scu = Object.entries(crates).reduce((a, [s, n]) => a + Number(s) * n, 0);
  const count = Object.values(crates).reduce((a, n) => a + n, 0);
  total.textContent = count ? `${count} crate${count === 1 ? '' : 's'}, ${fmtInt(scu)} SCU` : '';
}

/** The load as the panel has it, into this hull and every other. */
async function fitCargo() {
  const crates = cargoLoadNow();
  const verdict = $('#garage-cargo-verdict');
  if (!Object.keys(crates).length) { verdict.textContent = 'Type how many crates of each size.'; verdict.className = 'garage-cargo-verdict'; return; }
  if (!garageCargo) return;

  let data;
  try {
    const response = await fetch('/api/cargo/fit', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ship: garageCargo.class, crates }),
    });
    data = await response.json();
    if (!response.ok) { verdict.textContent = data.message || 'The fit could not be worked out.'; verdict.className = 'garage-cargo-verdict'; return; }
  } catch {
    verdict.textContent = 'The fit could not be worked out.';
    verdict.className = 'garage-cargo-verdict';
    return;
  }
  garageCargoResult = data;
  renderCargoVerdict(data);
  if (data.ship) renderCargoGrids(data.ship.grids, data.ship);
  renderCargoFleet(data);
}

function renderCargoVerdict(data) {
  const verdict = $('#garage-cargo-verdict');
  const s = data.ship;
  if (!s) { verdict.textContent = ''; return; }
  const load = data.load;
  if (s.fits) {
    verdict.className = 'garage-cargo-verdict fits';
    verdict.textContent = `Fits: ${load.count} crate${load.count === 1 ? '' : 's'}, ${fmtInt(load.scu)} of ${fmtInt(s.capacityScu)} SCU, with ${fmtInt(s.capacityScu - s.placedScu)} SCU to spare.`;
  } else {
    verdict.className = 'garage-cargo-verdict no';
    const left = Object.entries(s.left || {}).sort((a, b) => Number(b[0]) - Number(a[0])).map(([size, n]) => `${n} × ${size} SCU`).join(', ');
    const byRule = (s.reasons || []).length > 0;
    verdict.textContent = load.scu > s.capacityScu
      ? `Does not fit: ${fmtInt(load.scu)} SCU asked of a ${fmtInt(s.capacityScu)} SCU hold. Left out: ${left}.`
      : byRule
        ? `Does not fit: ${left} left out. ${s.reasons.join(' ')}`
        : `No packing found for ${left}: ${fmtInt(s.placedScu)} of ${fmtInt(load.scu)} SCU placed in ${fmtInt(s.capacityScu)}. The volume is there; this packer, largest crate first, could not arrange the rest, which is not proof it cannot be done.`;
  }
}

/**
 * Each grid as layers seen from above, one square a cell, crates coloured by
 * size with the size written on them. Layers because the holds are two
 * cells high and a crate on top hides the one under it.
 */
function renderCargoGrids(grids, fit) {
  const box = $('#garage-cargo-grids');
  if (!box) return;
  box.textContent = '';
  const cell = 14;
  for (const g of grids || []) {
    const card = el('div', 'garage-cargo-grid');
    const cells = g.cells;
    const title = el('div', 'garage-cargo-grid-title',
      `${g.grid.class.replace(/^.*?_CargoGrid_?|^.*?_CargoInventory_?/i, '') || g.grid.class} — ${cells.w} × ${cells.l} × ${cells.h} cells, ${fmtInt(cells.w * cells.l * cells.h)} SCU${g.grid.external ? ', outside the hull' : ''}`);
    card.append(title);
    const rule = g.grid.maxBox;
    const ruleText = g.ruleIgnored
      ? 'The dataset gives this grid a largest box of one cell, a placeholder on a hold this size; packed by its geometry instead.'
      : rule && rule.x > 0 ? `Takes a crate up to ${fmt1(rule.x)} × ${fmt1(rule.y)} × ${fmt1(rule.z)} m.` : '';
    if (ruleText) card.append(el('div', 'muted small', ruleText));
    const layers = el('div', 'garage-cargo-layers');
    for (let z = 0; z < cells.h; z++) {
      const layer = el('div', 'garage-cargo-layer');
      layer.append(el('div', 'muted small', cells.h > 1 ? (z === 0 ? 'Floor' : `Layer ${z + 1}`) : ''));
      const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
      const width = cells.w * cell, height = cells.l * cell;
      svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
      svg.setAttribute('width', String(width));
      svg.setAttribute('height', String(height));
      svg.classList.add('garage-cargo-svg');
      const back = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      back.setAttribute('width', String(width)); back.setAttribute('height', String(height));
      back.setAttribute('class', 'cargo-floor');
      svg.append(back);
      for (let x = 1; x < cells.w; x++) { const l = document.createElementNS('http://www.w3.org/2000/svg', 'line'); l.setAttribute('x1', String(x * cell)); l.setAttribute('x2', String(x * cell)); l.setAttribute('y1', '0'); l.setAttribute('y2', String(height)); l.setAttribute('class', 'cargo-line'); svg.append(l); }
      for (let y = 1; y < cells.l; y++) { const l = document.createElementNS('http://www.w3.org/2000/svg', 'line'); l.setAttribute('y1', String(y * cell)); l.setAttribute('y2', String(y * cell)); l.setAttribute('x1', '0'); l.setAttribute('x2', String(width)); l.setAttribute('class', 'cargo-line'); svg.append(l); }
      for (const p of g.placed || []) {
        if (z < p.z || z >= p.z + p.dz) continue;
        const r = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
        r.setAttribute('x', String(p.x * cell + 1)); r.setAttribute('y', String(p.y * cell + 1));
        r.setAttribute('width', String(p.dx * cell - 2)); r.setAttribute('height', String(p.dy * cell - 2));
        r.setAttribute('rx', '2');
        r.setAttribute('fill', CARGO_CRATE_COLOURS[p.scu] || '#888');
        r.setAttribute('class', `cargo-crate${z > p.z ? ' cargo-crate-upper' : ''}`);
        const t = document.createElementNS('http://www.w3.org/2000/svg', 'title');
        t.textContent = `${p.scu} SCU at ${p.x + 1}, ${p.y + 1}, layer ${p.z + 1}`;
        r.append(t);
        svg.append(r);
        if (z === p.z) {
          const label = document.createElementNS('http://www.w3.org/2000/svg', 'text');
          label.setAttribute('x', String(p.x * cell + p.dx * cell / 2));
          label.setAttribute('y', String(p.y * cell + p.dy * cell / 2 + 3));
          label.setAttribute('text-anchor', 'middle');
          label.setAttribute('class', 'cargo-label');
          label.textContent = String(p.scu);
          svg.append(label);
        }
      }
      layer.append(svg);
      layers.append(layer);
    }
    card.append(layers);
    if (fit) card.append(el('div', 'muted small', `${fmtInt(g.usedScu)} of ${fmtInt(cells.w * cells.l * cells.h)} SCU used`));
    box.append(card);
  }
}

/** Your ships that take the load, then the smallest in the reference that do. */
function renderCargoFleet(data) {
  const box = $('#garage-cargo-fleet');
  if (!box) return;
  box.textContent = '';
  box.hidden = false;
  const mine = data.yours || [];
  const line = (s) => {
    const li = el('li', s.fits ? 'fits' : 'no');
    const link = el('a', null, s.name);
    link.href = `#garage`;
    link.addEventListener('click', (e) => { e.preventDefault(); openGarageShipForCargo(s.class); });
    li.append(link, el('span', 'muted', ` — ${s.fits ? 'fits' : `${fmtInt(s.placedScu)} of ${fmtInt(data.load.scu)} SCU`}, ${fmtInt(s.cargoScu)} SCU hold${s.flown && s.hours ? `, flown ${s.hours} h` : ''}`));
    return li;
  };
  const fitting = mine.filter((s) => s.fits);
  const not = mine.filter((s) => !s.fits);
  if (mine.length) {
    box.append(el('h4', null, 'Your ships'));
    if (fitting.length) {
      const ul = el('ul', 'garage-cargo-ships');
      for (const s of fitting) ul.append(line(s));
      box.append(ul);
    } else {
      box.append(el('p', 'muted small', 'None of the ships the logs have seen you fly takes this load.'));
    }
    // The rest in one line, hold sizes attached, so the list is what fits
    // and not a roll-call of fighters with a 2 SCU boot.
    if (not.length) box.append(el('p', 'muted small', `Not in: ${not.map((s) => `${s.name} (${fmtInt(s.cargoScu)} SCU)`).join(', ')}.`));
  } else {
    box.append(el('p', 'muted small', 'None of the ships the logs have seen you fly has a cargo grid in the dataset.'));
  }
  const smallest = data.smallest || [];
  if (smallest.length) {
    box.append(el('h4', null, 'Smallest hulls in the reference that take it'));
    const ul = el('ul', 'garage-cargo-ships');
    for (const s of smallest) ul.append(line(s));
    box.append(ul);
  }
}

/** Opens the Garage on another hull and runs the same load there. */
function openGarageShipForCargo(cls) {
  const pick = $('#garage-all');
  if (pick) { pick.value = cls; pick.dispatchEvent(new Event('change')); }
}

$('#garage-cargo-fit')?.addEventListener('click', () => fitCargo().catch(() => {}));
$('#garage-cargo-clear')?.addEventListener('click', () => {
  garageCargoLoad = {};
  try { localStorage.removeItem('qw-cargo-load'); } catch { /* as above */ }
  renderCargoLoadInputs();
  $('#garage-cargo-verdict').textContent = '';
  const fleet = $('#garage-cargo-fleet');
  if (fleet) { fleet.hidden = true; fleet.textContent = ''; }
  if (garageCargo) renderCargoGrids((garageCargo.grids || []).map(cargoEmpty), null);
});

/* ---------- the photographed fit ---------- */

/**
 * The ship's fit as last photographed, offered as a place to start the bench
 * from. Never applied on its own: the logs do not name a ship's parts, a
 * screenshot is a moment rather than a state, and the ports are matched to
 * the screen's labels by kind and order - a starting point, dated, that the
 * pilot chooses. Hidden when no loadout reading is of this ship.
 */
let garagePhoto = null;
let garagePhotoApplied = false;

/**
 * Whether a ship opens on the bench as its newest photograph showed it. On
 * unless the pilot says otherwise, kept in this browser with the other
 * bench habits: the photograph is the one thing that says what the ship is
 * carrying, and a bench that opened at stock until a button was pressed
 * was a bench nobody pressed. The way out is the tick, not a press a ship.
 */
let garageFromPhoto = true;
try {
  garageFromPhoto = localStorage.getItem('qw-garage-from-photo') !== 'no';
} catch { /* private browsing keeps the default */ }

function rememberGarageFromPhoto(on) {
  garageFromPhoto = on;
  try { localStorage.setItem('qw-garage-from-photo', on ? 'yes' : 'no'); } catch { /* as above */ }
}

async function loadGaragePhoto(cls) {
  const box = $('#garage-photo');
  if (!box) return;
  garagePhoto = null;
  garagePhotoApplied = false;
  box.hidden = true;

  let fit = null;
  try {
    fit = await getJson(`/api/garage/${encodeURIComponent(cls)}/photographed`);
  } catch {
    // No reading of this ship. The section stays, with the reason: a bench
    // that never mentions photographs looks like it cannot use one.
  }
  if (cls !== garageClass) return;

  garagePhoto = fit;
  renderGaragePhoto();

  // A bench nobody has touched yet takes the photograph itself. One the
  // pilot has already changed, or opened a saved build on, is theirs.
  if (garageFromPhoto && fit?.applied && !garageOpenBuild && Object.keys(garageSwaps).length === 0)
    await applyGaragePhoto();
}

function renderGaragePhoto() {
  const box = $('#garage-photo');
  if (!box) return;
  const fit = garagePhoto;
  const tools = $('#garage-photo-tools');
  box.hidden = false;

  if (!fit) {
    const name = garageStock?.ship?.name || 'this ship';
    $('#garage-photo-title').textContent = `No photograph of the ${name} has been read`;
    $('#garage-photo-sub').textContent = `Open it at a Vehicle Loadout Manager, or its loadout estimate at a Fleet Manager, `
      + `and take a screenshot; with Watch screenshots on (Log tab) it is read as it lands, `
      + `the ones already in the folder included, and the bench can start from what the screen shows.`;
    $('#garage-photo-unsettled').textContent = '';
    if (tools) tools.hidden = true;
    return;
  }
  if (tools) tools.hidden = false;

  const when = new Date(fit.shotAt).toLocaleString();
  $('#garage-photo-title').textContent = `${fit.ship}, as photographed ${when}`;

  const unsettled = (fit.ports || []).filter((p) => !p.applied);
  const sub = [];
  sub.push(`${fit.applied} of ${fit.ports.length} port${fit.ports.length === 1 ? '' : 's'} read as one part`);
  sub.push(fit.changed ? `${fit.changed} differ${fit.changed === 1 ? 's' : ''} from stock` : 'none differ from stock');
  if (unsettled.length) sub.push(`${unsettled.length} not settled by the screenshot and left as stock`);
  if (fit.scope) sub.push(fit.scope);
  sub.push(`from ${fit.shot}`);
  $('#garage-photo-sub').textContent = `${sub.join(' · ')}. Ports are matched to the screen's labels by kind and order; a screenshot is a moment, not a state.`;

  const list = $('#garage-photo-unsettled');
  list.textContent = '';
  for (const port of unsettled) {
    const li = el('li');
    li.append(el('span', 'what', port.slot));
    li.append(el('span', 'd', ` · ${port.why}`));
    list.append(li);
  }

  const auto = $('#garage-photo-auto');
  if (auto) auto.checked = garageFromPhoto;
  const apply = $('#garage-photo-apply');
  apply.disabled = garagePhotoApplied || !fit.applied;
  // With the tick on, the button is the same act as opening the ship, so it
  // stays only for the pilot who took the tick off.
  apply.hidden = garageFromPhoto && garagePhotoApplied;
  $('#garage-photo-state').textContent = garagePhotoApplied
    ? `The bench started from this photograph; ${fit.changed} part${fit.changed === 1 ? '' : 's'} differ from stock. Reset to stock takes it back.`
    : fit.applied ? '' : 'Nothing on the screenshot settled a port the bench can change.';
}

/** The photographed parts become the bench's swaps, and the sheet moves to match. */
async function applyGaragePhoto() {
  if (!garagePhoto || !garageStock) return;
  garageSwaps = { ...garagePhoto.swaps };
  garagePhotoApplied = true;
  $('#garage-optimise-status').textContent = '';
  await refitGarage();
  renderGaragePhoto();
}

$('#garage-photo-apply')?.addEventListener('click', () => applyGaragePhoto().catch(() => {}));

// The tick acts at once as well as from now on: off takes this bench back to
// stock, on fits the photograph - so what is on screen is what the tick says.
$('#garage-photo-auto')?.addEventListener('change', (e) => {
  rememberGarageFromPhoto(e.target.checked);
  if (garageFromPhoto && garagePhoto?.applied && !garagePhotoApplied && Object.keys(garageSwaps).length === 0) {
    applyGaragePhoto().catch(() => {});
  } else if (!garageFromPhoto && garagePhotoApplied) {
    resetGarage().catch(() => {});
  } else {
    renderGaragePhoto();
  }
});

/**
 * One player's advertisement, as a line the bench and the market panel share:
 * the ask, who, where, and the way to UEX - which is where the buying is
 * arranged, not here.
 */
function listingLine(listing, more = 0) {
  const line = el('span', 'listing');
  line.append(acquisitionChip('players', 'Player listing',
    'A player\'s advertisement on UEX\'s marketplace: an asking price, not a market price. Buying is arranged with the seller on UEX.'));
  line.append(el('b', null, `${fmtInt(listing.price)} aUEC`));
  const where = [listing.seller ? `by ${listing.seller}` : '', listing.location ? `at ${listing.location}` : ''].filter(Boolean).join(' ');
  line.append(document.createTextNode(` · ${where || 'place not given'}${listing.inStock > 1 ? ` · ${listing.inStock} in stock` : ''}${more > 0 ? ` +${more}` : ''} `));
  const link = el('a', 'uex-link', 'UEX ↗');
  link.href = listing.url;
  link.target = '_blank';
  link.rel = 'noopener';
  link.title = listing.title;
  line.append(link);
  return line;
}

/**
 * The panel under the bench: parts fit for this ship that players are
 * offering on UEX's marketplace this week. Off until the pilot fetches the
 * feed - the panel says so rather than hiding, because "nobody is selling"
 * and "you have not looked" are different answers and only one is true.
 */
async function loadGarageMarket(cls) {
  const box = $('#garage-market');
  const body = $('#garage-market-body');
  const note = $('#garage-market-note');
  if (!box || !body || !note) return;

  let data;
  try {
    data = await getJson(`/api/garage/${encodeURIComponent(cls)}/market`);
  } catch {
    box.hidden = true;
    return;
  }
  // The ship changed under the fetch: this answer is for a bench that is gone.
  if (cls !== garageClass) return;

  box.hidden = false;
  body.textContent = '';
  const shipName = garageStock?.ship?.name || cls;

  if (!data.enabled) {
    note.textContent = 'Player listings are off. Fetch the Player marketplace feed under UEX in Settings to see who is offering parts for this ship on uexcorp.space.';
    return;
  }

  const fetched = data.fetchedAt ? `fetched ${ago(data.fetchedAt)}` : 'never fetched';
  if (!data.listings.length) {
    note.textContent = `Nobody has advertised a part that fits the ${shipName} in the newest ${fmtInt(data.total)} UEX marketplace listings (${data.components} of them are ship components at all) · ${fetched}. That is a week's advertisements, not a verdict on the market.`;
    return;
  }

  note.textContent = `${data.listings.length} of the newest ${fmtInt(data.total)} UEX marketplace listings are parts that fit the ${shipName} · asking prices, not market prices · ${fetched}.`;

  for (const row of data.listings) {
    const { listing, part } = row;
    const rowEl = el('div', 'candidate market-row');
    rowEl.append(partMark(part));

    const mid = el('div');
    const name = el('div', 'c-name', part.name);
    name.append(partChip(part));
    mid.append(name);
    mid.append(el('div', 'c-maker', `${part.manufacturer || part.makerCode || ''}${listing.title && listing.title !== part.name ? ` · listed as “${listing.title}”` : ''}`));
    const shop = el('div', 'c-shop');
    shop.append(listingLine(listing));
    shop.append(document.createTextNode(` · posted ${ago(listing.added)}`));
    mid.append(shop);
    rowEl.append(mid);

    const act = el('div', 'c-act');
    if (row.ports && row.ports.length) {
      const open = el('button', 'ghost tiny', 'Bench');
      open.type = 'button';
      open.title = 'Open the port this part fits, with what else fits it';
      open.addEventListener('click', () => selectBenchPort(row.ports[0], true).catch(() => {}));
      act.append(open);
    }
    rowEl.append(act);
    body.append(rowEl);
  }
}

/**
 * Draws the sheet. With a stock sheet to compare against, every figure that
 * moved shows the old one struck beside it.
 */
function renderGarage(data, stock) {
  const head = $('#garage-head');
  head.hidden = false;
  $('#garage-title').textContent = data.ship.name;
  const discipline = garageShipDiscipline(data.ship.career, data.ship.role);
  const sub = $('#garage-sub');
  sub.textContent = '';
  const badge = el('span', `garage-duty ${discipline.key}`, discipline.label);
  badge.dataset.discipline = discipline.key;
  badge.title = `Inferred from the community career / role: ${discipline.basis}`;
  sub.append(badge, el('span', 'garage-subline', [data.ship.manufacturer, data.ship.role, data.ship.career,
    `size ${data.ship.size}`, `crew ${data.ship.crew}`].filter(Boolean).join(' · ')));
  $('#garage-source').textContent = `Community dataset${data.dump ? ` · dump ${data.dump}` : ''} · recomputed from the fitted parts`;
  renderGarageRig(data);

  const s = data.sheet;
  const o = stock?.sheet || null;
  const ship = data.ship;

  const sheet = $('#garage-sheet');
  sheet.textContent = '';

  sheet.append(sheetGroup('Hull', 'ships.json', [
    row('Hull HP', fmtInt(ship.health)),
    row('Mass', `${fmtInt(s.mass)} kg`, 'The dataset’s stock figure, moved by what you changed.', o ? [o.mass, s.mass, ' kg'] : null),
    s.crossSection.x || s.crossSection.y || s.crossSection.z
      ? row('Cross-section', `${fmtInt(s.crossSection.x)} · ${fmtInt(s.crossSection.y)} · ${fmtInt(s.crossSection.z)}`,
        'Front · side · top. Geometry: parts do not change it.')
      : row('Cross-section', '—', 'The dataset carries none for this hull.'),
    row('Cargo', ship.cargoScu ? `${fmt1(ship.cargoScu)} SCU` : '—'),
    row('Fuel', `${fmtInt(ship.hydrogenFuel)} H · ${fmtInt(ship.quantumFuel)} Q`),
  ]));

  const f = ship.flight;
  sheet.append(sheetGroup('Flight', 'ships.json', [
    row('SCM', `${fmtInt(f.scm)} m/s`),
    row('Boost', `${fmtInt(f.boost)} m/s`),
    row('Max', `${fmtInt(f.max)} m/s`),
    row('Pitch · yaw · roll', `${fmtInt(f.pitch)} · ${fmtInt(f.yaw)} · ${fmtInt(f.roll)} °/s`),
  ]));

  const w = s.weapons;
  const ow = o?.weapons;
  sheet.append(sheetGroup('Weapons', 'parts', [
    // The caveat rides on both rows it moves guns between: the split is the
    // one figure read from a port name, and on seven hulls the dump disagrees.
    row('Pilot DPS', fmt1(w.fixedDps), [w.guns.length ? w.guns.join(', ') : 'No guns the pilot fires.', w.caveat].filter(Boolean).join(' · '), ow ? [ow.fixedDps, w.fixedDps] : null),
    row('Sustained', fmt1(w.fixedSustainedDps), null, ow ? [ow.fixedSustainedDps, w.fixedSustainedDps] : null, true),
    row('Alpha', fmt1(w.fixedAlpha), null, ow ? [ow.fixedAlpha, w.fixedAlpha] : null, true),
    // One lead indicator per projectile speed: two speeds is two pips on the
    // HUD, and a lead that lands one gun misses the other. Said in the row,
    // not only in the notes, because it is the figure a gun swap changes.
    pipsRow(w, ow),
    row('Turret DPS', w.turretDps ? fmt1(w.turretDps) : '—', [w.turretDps ? 'Crewed or remote turrets; somebody else fires these.' : null, w.caveat ? 'See the pilot row: the split between the two is the uncertain part.' : null].filter(Boolean).join(' ') || null, ow ? [ow.turretDps, w.turretDps] : null),
    row('Missiles', w.missiles ? `${w.missiles} · ${fmtInt(w.missileDamage)} dmg` : '—', null, ow ? [ow.missileDamage, w.missileDamage] : null),
  ]));

  const sh = s.shield;
  const osh = o?.shield;
  sheet.append(sheetGroup('Defence', 'parts', [
    row('Shield HP', fmtInt(sh.hp), sh.poolLimit && sh.generators > sh.poolLimit
      ? `${sh.generators} generators fitted, ${sh.poolLimit} online: the pool caps it.` : null, osh ? [osh.hp, sh.hp] : null),
    row('Shield regen', `${fmtInt(sh.regen)} /s`, null, osh ? [osh.regen, sh.regen] : null),
    row('Generators', sh.poolLimit ? `${sh.generators} of ${sh.poolLimit}` : String(sh.generators)),
    row('Armour', `EM ×${s.armorSignals.em} · IR ×${s.armorSignals.ir}`, 'The hull’s signal multipliers; every signature below carries them.'),
  ]));

  const sig = s.shields;
  const osig = o?.shields;
  const groups = Object.entries(sig.emByGroup || {}).sort((a, b) => b[1] - a[1]);
  sheet.append(sheetGroup('Signature', 'model', [
    row('EM, shields up', fmtInt(sig.em), 'Every part at maximum, quantum drive idle.', osig ? [osig.em, sig.em, '', true] : null),
    ...groups.map(([g, v]) => row(garageWord(g), fmtInt(v), null,
      osig ? [osig.emByGroup?.[g] || 0, v, '', true] : null, true)),
    row('IR, shields up', fmtInt(sig.ir), 'Every part’s IR × armour × cooling load.', osig ? [osig.ir, sig.ir, '', true] : null),
    row('EM · IR, in quantum', `${fmtInt(s.quantum.em)} · ${fmtInt(s.quantum.ir)}`, 'Drive spooled, shields down.',
      o ? [o.quantum.em, s.quantum.em, '', true] : null),
  ]));

  const p = s.power;
  const c = s.cooling;
  const op = o?.power;
  const oc = o?.cooling;
  sheet.append(sheetGroup('Systems', 'parts', [
    row('Power available', `${p.available} seg`, null, op ? [op.available, p.available] : null),
    row('Drawn, shields up', `${fmt1(p.usedShields)} seg`, p.overShields ? 'Over budget: the game will brown something out.' : null,
      op ? [op.usedShields, p.usedShields, '', true] : null),
    row('Drawn, in quantum', `${fmt1(p.usedQuantum)} seg`, p.overQuantum ? 'Over budget in quantum.' : null,
      op ? [op.usedQuantum, p.usedQuantum, '', true] : null),
    row('Cooling generated', `${fmtInt(c.generated)} seg`, null, oc ? [oc.generated, c.generated] : null),
    row('Cooling load', `${Math.round(c.loadShields * 100)}%`, c.loadShields > 1 ? 'Above 100%: the coolers cannot keep up at full draw.' : 'Used over generated, shields up. Lower is quieter.',
      oc ? [oc.loadShields * 100, c.loadShields * 100, '%', true] : null),
  ]));

  const q = s.quantumDrive;
  const oq = o?.quantumDrive;
  sheet.append(sheetGroup('Quantum', 'parts', q ? [
    row('Drive', q.drive),
    row('Speed', fmtSpeed(q.speed), null, oq ? [oq.speed, q.speed, '', false, fmtSpeed] : null),
    row('Spool · cooldown', `${fmt1(q.spoolTime)} s · ${fmt1(q.cooldown)} s`, null, oq ? [oq.spoolTime, q.spoolTime, ' s', true] : null),
    row('Range', fmtDistance(q.range), 'Full tank over the drive’s fuel rate.', oq ? [oq.range, q.range, '', false, fmtDistance] : null),
    row('Fuel per Gm', fmt1(q.fuelPerGm), null, oq ? [oq.fuelPerGm, q.fuelPerGm, '', true] : null),
  ] : [row('Drive', 'None fitted')]));

  const notes = $('#garage-notes');
  notes.textContent = '';
  notes.hidden = !(s.notes && s.notes.length);
  for (const note of s.notes || []) notes.append(el('div', null, note));
  if (data.industrialPortsKnown === false && /mining|salvage/i.test(`${ship.role || ''} ${ship.career || ''}`)) {
    notes.hidden = false;
    notes.append(el('div', null, 'Replacement choices for mining and salvage heads are missing from this cached loadout. Refresh the community dataset in Settings to check their compatibility.'));
  }

  renderBench(data);
}

// The reference calls this a career and role, not a ship allegiance. This is a
// compact reading aid for the Garage, so the tooltip keeps the source visible
// instead of claiming that every expedition or freighter is officially civil.
function garageShipDiscipline(career, role) {
  const basis = [career, role].filter(Boolean).join(' · ') || 'no career / role recorded';
  const words = basis.toLowerCase();
  if (/combat|fighter|bomber|gunship|destroyer|frigate|interceptor|interdiction/.test(words))
    return { key: 'military', label: 'Military', basis };
  if (/industrial|mining|salvage|repair|recovery|refuel|science/.test(words))
    return { key: 'industrial', label: 'Industrial', basis };
  return { key: 'civilian', label: 'Civilian', basis };
}

/**
 * The bench is where alternatives are compared; this is the fitted ship at a
 * glance. Ports stay as real, clickable cards rather than being painted onto
 * an approximate hull drawing - the data knows attachment names, not 3D
 * coordinates, and inventing coordinates would make a useful fit look exact.
 */
function renderGarageRig(data) {
  const rig = $('#garage-rig');
  const ports = (data.ports || []).filter((p) => BENCH_KINDS.includes(p.group));
  rig.hidden = ports.length === 0;
  if (!ports.length) return;

  const left = $('#garage-rig-left');
  const right = $('#garage-rig-right');
  left.textContent = '';
  right.textContent = '';

  const leftKinds = new Set(['PowerPlant', 'Cooler', 'Shield', 'QuantumDrive', 'Radar', 'EMP', 'QuantumInterdictionGenerator']);
  const rows = benchGroups(benchRows(ports));
  for (const [kind, group] of rows) {
    const side = leftKinds.has(kind) ? left : right;
    for (const port of group) side.append(garageRigSlot(port, data.ship));
  }

  const model = $('#garage-ship-model');
  model.textContent = '';
  const code = makerAliases.get(String(data.ship.manufacturer || '').toLowerCase())
    || String(data.ship.class || '').split('_')[0];
  const maker = { code, name: MANUFACTURERS[code] || data.ship.manufacturer || 'Unknown maker' };
  model.append(shipPicture({ name: data.ship.name, className: data.ship.class }, maker));

  $('#garage-rig-count').textContent = `${ports.length} fitted port${ports.length === 1 ? '' : 's'}`;
  const summary = $('#garage-ship-summary');
  summary.textContent = '';
  const power = data.sheet.power;
  const powerHeadroom = power.available - power.usedShields;
  for (const [label, value] of [
    ['Shield', `${fmtInt(data.sheet.shield.hp)} HP`],
    ['Pilot DPS', fmt1(data.sheet.weapons.fixedDps)],
    ['Quantum', data.sheet.quantumDrive?.drive || '—'],
    ['Power', power.overShields ? `${fmt1(Math.abs(powerHeadroom))} short` : `${fmt1(powerHeadroom)} spare`],
  ]) {
    const unhealthy = label === 'Power' && power.overShields;
    const stat = el('div', `garage-ship-stat${unhealthy ? ' alert' : ''}`);
    stat.append(el('span', null, label), el('b', null, value));
    summary.append(stat);
  }
}

function garageRigSlot(port, ship) {
  const selected = port.portIds.includes(garageSelectedPort);
  const button = el('button', `garage-rig-slot${port.changed ? ' changed' : ''}${selected ? ' selected' : ''}`);
  button.type = 'button';
  button.dataset.port = port.portIds[0];
  button.setAttribute('aria-pressed', String(selected));
  const many = port.portIds.length > 1;
  const name = port.name || port.class || 'Empty port';
  button.title = `${garageWord(port.group)} · ${garagePortName(port.hardpoint)} · ${name}`;
  button.disabled = !!port.fixedReason;
  if (port.fixedReason) button.title = port.fixedReason;
  button.append(partMark(port.fitted, true));

  const body = el('span', 'garage-rig-slot-body');
  body.append(el('span', 'garage-rig-slot-kind', garageWord(port.group)));
  const part = el('span', 'garage-rig-slot-name', name);
  if (port.fitted) part.append(partChip(port.fitted));
  if (many) part.append(el('span', 'chip count', `×${port.portIds.length}`));
  body.append(part);
  if (port.fixedReason) body.append(el('span', 'garage-rig-slot-spec', port.fixedReason));
  const figures = partFigures(port.fitted, ship).slice(0, 2);
  if (figures.length) body.append(el('span', 'garage-rig-slot-spec', figures.map((f) => `${f[2]} ${f[0]}`).join(' · ')));
  button.append(body);
  button.addEventListener('click', () => selectBenchPort(port.portIds[0], true).catch(() => {}));
  return button;
}

function sheetGroup(title, source, rows) {
  const group = el('section', 'sheet-group');
  const groupKey = title.toLowerCase();
  group.dataset.group = groupKey;
  const h = el('h3');
  const label = el('span', 'sheet-title');
  label.append(garageSheetIcon(groupKey), document.createTextNode(title));
  h.append(el('span', 'src', source === 'model' ? 'signature model' : source));
  h.prepend(label);
  group.append(h);
  for (const r of rows) if (r) group.append(r);
  return group;
}

// These are diagrammatic system marks rather than imported game artwork: they
// distinguish the questions the sheet answers while keeping the numbers as the
// information a pilot is actually here to read.
const SHEET_GROUP_ICON_SHAPES = {
  hull: [['polygon', { points: '12,2 20,7 20,17 12,22 4,17 4,7' }], ['path', { d: 'M4 7l8 5 8-5M12 12v10' }]],
  flight: [['path', { d: 'M3 13 12 3l9 10-6-1-3 9-3-9z' }]],
  weapons: [['circle', { cx: 12, cy: 12, r: 4 }], ['circle', { cx: 12, cy: 12, r: 9 }], ['path', { d: 'M12 1v4m0 14v4M1 12h4m14 0h4' }]],
  defence: [['path', { d: 'M12 2 20 5v6c0 5.4-3.3 9.2-8 11-4.7-1.8-8-5.6-8-11V5z' }], ['path', { d: 'm8.5 12 2.2 2.2 4.8-5' }]],
  signature: [['circle', { cx: 12, cy: 12, r: 9 }], ['circle', { cx: 12, cy: 12, r: 3 }], ['path', { d: 'M12 12 19 5M12 3v2M3 12h2' }]],
  systems: [['path', { d: 'M4 7h6V4h4v5h6M4 17h6v3h4v-5h6' }], ['circle', { cx: 4, cy: 7, r: 1.5 }], ['circle', { cx: 20, cy: 17, r: 1.5 }]],
  quantum: [['path', { d: 'M3 12h14M11 7l6 5-6 5M4 7h6M4 17h6' }], ['circle', { cx: 4, cy: 12, r: 1.5 }]],
};

function garageSheetIcon(group) {
  const icon = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  icon.setAttribute('class', 'sheet-icon');
  icon.setAttribute('viewBox', '0 0 24 24');
  icon.setAttribute('aria-hidden', 'true');
  icon.dataset.icon = group;
  for (const [tag, attrs] of SHEET_GROUP_ICON_SHAPES[group] || SHEET_GROUP_ICON_SHAPES.hull) {
    const shape = document.createElementNS('http://www.w3.org/2000/svg', tag);
    for (const [name, value] of Object.entries(attrs)) shape.setAttribute(name, value);
    icon.append(shape);
  }
  return icon;
}

/**
 * One line of the sheet.
 *
 * @param delta [was, now, unit, lowerIsBetter, format] - when the bench has
 *   changed something, the old figure is struck beside the new one and the new
 *   one coloured by whether it got better, which depends on the figure.
 */
/**
 * The chip on a gun the bench offers when fitting it would put a second pip
 * on the HUD: its projectile speed matches none of the pilot's other guns.
 * The other guns are the sheet's, less the one in this port - so a gun that
 * is alone at its speed is not warned against every replacement. A port the
 * sheet does not count as the pilot's (a crewed turret) gets no chip, since
 * its pip is somebody else's.
 */
function pipChip(part, fittedPart) {
  const speed = part?.weapon?.ammoSpeed;
  if (!(speed > 0) || !garageSheet?.weapons?.speeds) return null;
  const pilotGuns = garageSheet.weapons.guns || [];
  if (fittedPart && !pilotGuns.includes(fittedPart.name)) return null;

  const others = new Set();
  for (const s of garageSheet.weapons.speeds) {
    const names = [...s.guns];
    if (fittedPart) {
      const i = names.indexOf(fittedPart.name);
      if (i >= 0) names.splice(i, 1);
    }
    if (names.length) others.add(Math.round(s.speed));
  }
  if (!others.size || others.has(Math.round(speed))) return null;

  const chip = el('span', 'chip pip', `+1 pip`);
  chip.title = `${fmtInt(speed)} m/s against ${[...others].map(fmtInt).join(' and ')} m/s on the other pilot guns: the HUD would draw a second lead indicator, and a lead that lands one gun misses the other.`;
  return chip;
}

/** "CF-447 Rhino Repeater ×4" - a speed's guns, named once each and counted. */
function gunsAtSpeed(names) {
  const counts = new Map();
  for (const n of names) counts.set(n, (counts.get(n) || 0) + 1);
  return [...counts].map(([n, c]) => (c > 1 ? `${n} ×${c}` : n)).join(', ');
}

/**
 * The projectile-speed row of the Weapons card. One speed is the figure;
 * more than one is the count of pips, marked as a problem, with each speed's
 * guns in the note - the compared figure is the pip count, fewer being better.
 */
function pipsRow(w, ow) {
  const speeds = w.speeds || [];
  const pips = speeds.length;
  const was = ow ? (ow.speeds || []).length : null;
  const value = pips === 0 ? '—' : pips === 1 ? `${fmtInt(speeds[0].speed)} m/s` : `${pips} speeds · ${pips} pips`;
  const note = pips > 1
    ? `${speeds.map((s) => `${gunsAtSpeed(s.guns)} at ${fmtInt(s.speed)} m/s`).join('; ')}. The HUD draws a pip per speed, and a lead that lands one gun misses the other.`
    : pips === 1 ? 'Every pilot gun at one speed: one pip.' : null;
  const r = row('Projectile speed', value, note, was !== null && was !== pips ? [was, pips, '', true] : null);
  if (pips > 1) r.classList.add('alert');
  return r;
}

function row(label, value, note, delta, sub = false) {
  const r = el('div', `sheet-row${sub ? ' sub' : ''}`);
  r.dataset.key = label;
  r.append(el('span', 'k', label));

  const v = el('span', 'v');
  if (delta && Number.isFinite(delta[0]) && Number.isFinite(delta[1]) && Math.abs(delta[0] - delta[1]) > 1e-9) {
    const [was, now, unit = '', lowerIsBetter = false, format = null] = delta;
    const wasText = format ? format(was) : `${fmtSmart(was)}${unit}`;
    v.append(el('span', 'was', wasText));
    const better = lowerIsBetter ? now < was : now > was;
    v.classList.add(better ? 'up' : 'down');
  }
  v.append(document.createTextNode(value));
  r.append(v);

  if (note) r.append(el('span', 'n', note));
  return r;
}

const fmtSmart = (n) => Number.isInteger(n) ? fmtInt(n) : fmt1(n);

/* ---------- the bench ---------- */

/** Port id → class fitted instead of stock. Empty means the stock fit. */
let garageSwaps = {};
let garageSelectedPort = null;
let garageOptions = null;

/** The kinds in the order a pilot thinks about them, and the figure that heads each. */
const BENCH_KINDS = ['PowerPlant', 'Cooler', 'Shield', 'QuantumDrive', 'WeaponGun', 'MissileLauncher', 'Missile', 'Radar',
  'EMP', 'QuantumInterdictionGenerator', 'WeaponMining', 'SalvageHead'];


/**
 * The maker's mark for a part: the Fankit logo where the app has one, and a
 * monogram of the maker's code otherwise. The game files hold no picture of a
 * component, so this is the only face a cooler has.
 */
function partMark(part, small = false) {
  const mark = el('span', `part-mark${small ? ' small' : ''}`);
  const code = part?.makerCode || null;
  const name = part?.manufacturer || code || '';
  mark.title = part?.name ? `${part.name}${name ? ` - ${name}` : ''}` : name;

  // The maker's face: the Fankit logo where the app has one (the hull
  // makers), the wiki's logo for the component makers the Fankit does not
  // cover, a monogram when the wiki has none either - or when it answers
  // 404, which swaps the monogram in after the fact.
  const mono = () => el('span', 'mono-mark', monogram(code, name));
  const maker = () => {
    if (!code) return mono();
    const img = document.createElement('img');
    img.alt = name;
    img.loading = 'lazy';
    if (MANUFACTURER_LOGOS.has(code)) {
      img.src = `assets/manufacturers/${code}.png`;
    } else {
      img.className = 'maker-pic';
      img.src = `/api/garage/maker/${encodeURIComponent(code)}`;
      img.addEventListener('error', () => img.replaceWith(mono()));
    }
    return img;
  };

  // The part itself where the wiki has a picture of it, which is about half
  // of the bench; the 404 for the other half is the cue to show the maker
  // instead, so a radar without a picture is not a broken image.
  if (part?.uuid) {
    const pic = document.createElement('img');
    pic.className = 'part-pic';
    pic.src = `/api/garage/picture/${encodeURIComponent(part.uuid)}`;
    pic.alt = part.name || '';
    pic.loading = 'lazy';
    pic.addEventListener('error', () => { mark.classList.remove('pic'); pic.replaceWith(maker()); });
    mark.classList.add('pic');
    mark.append(pic);
  } else {
    mark.append(maker());
  }
  return mark;
}


/** A maker's code, else the initials of its name: Wen-Cassel Propulsion → WCP. */
function monogram(code, name) {
  if (code) return code.toUpperCase().slice(0, 4);
  const initials = String(name || '').split(/[\s\-&]+/).filter(Boolean).map((w) => w[0]).join('');
  return (initials || '?').toUpperCase().slice(0, 4);
}

/** The size-and-grade chip: S2 · B. */
function partChip(part) {
  const grade = gradeLetter(part?.grade);
  return el('span', `chip${/^[A-D]$/.test(grade) ? ` grade-${grade.toLowerCase()}` : ''}`, `S${part?.size ?? '?'} · ${grade}`);
}

/** The game's class line makes a part's intended discipline visible on the bench. */
function componentClassChip(componentClass) {
  if (!componentClass) return null;
  const key = String(componentClass).toLowerCase();
  const chip = el('span', `component-class ${key}`, componentClass);
  chip.title = 'Component class from the game\'s item description';
  return chip;
}

/**
 * A stealth label needs a measured meaning. The game no longer consistently
 * classifies components as "Stealth", so mark the quietest compatible choice
 * only when the installed data gives both of its signatures and the choices
 * actually differ.
 */
function stealthPickChip(part, choices) {
  const score = (candidate) => Number.isFinite(candidate?.em) && Number.isFinite(candidate?.ir)
    ? candidate.em + candidate.ir : null;
  const scores = choices.map(score).filter((value) => value !== null);
  const here = score(part);
  if (here === null || scores.length < 2) return null;

  const lowest = Math.min(...scores);
  if (here !== lowest || !scores.some((value) => value > lowest)) return null;

  const chip = el('span', 'chip stealth', 'Stealth pick');
  chip.title = 'Lowest combined EM + IR among the compatible parts shown; lower signatures are quieter.';
  return chip;
}

/** A route is useful only when its kind is stated: a shop and a recipe answer different plans. */
function acquisitionChip(kind, text, title) {
  const chip = el('span', `acquisition ${kind}`, text);
  chip.title = title;
  return chip;
}

/**
 * The figures that matter for a kind, as [label, value, formatted, lowerIsBetter].
 * These head the port row and the candidate rows, so the two read alike.
 */
function partFigures(part, ship) {
  if (!part) return [];
  const t = part.type;
  if (part.weapon) {
    return [['DPS', part.weapon.dps, fmt1(part.weapon.dps)], ['alpha', part.weapon.alpha, fmt1(part.weapon.alpha)],
      ['range', part.weapon.range, `${fmtInt(part.weapon.range)} m`], ['sustained', part.weapon.sustainedDps, fmt1(part.weapon.sustainedDps)],
      ...(part.weapon.ammoSpeed > 0 ? [['m/s', part.weapon.ammoSpeed, fmtInt(part.weapon.ammoSpeed)]] : [])];
  }
  if (part.shield) {
    return [['HP', part.shield.hp, fmtInt(part.shield.hp)], ['regen', part.shield.regen, `${fmtInt(part.shield.regen)}/s`],
      ['EM', part.em, fmtInt(part.em), true], ['draw', part.powerUseMax, `${fmt1(part.powerUseMax)} seg`, true]];
  }
  if (part.quantum) {
    const range = ship?.quantumFuel && part.quantum.fuelRate ? ship.quantumFuel / part.quantum.fuelRate : null;
    return [['speed', part.quantum.speed, fmtSpeed(part.quantum.speed)], ['spool', part.quantum.spoolTime, `${fmt1(part.quantum.spoolTime)} s`, true],
      ...(range ? [['range', range, fmtDistance(range)]] : []), ['EM', part.em, fmtInt(part.em), true]];
  }
  if (part.missile) {
    return [['dmg', part.missile.damage, fmtInt(part.missile.damage)], ['speed', part.missile.speed, `${fmtInt(part.missile.speed)} m/s`],
      ['lock', part.missile.lockTime, `${fmt1(part.missile.lockTime)} s`, true], ['range', part.missile.range, fmtDistance(part.missile.range)]];
  }
  if (t === 'Cooler') {
    return [['coolant', part.coolantGen, fmtInt(part.coolantGen)], ['IR', part.ir, fmtInt(part.ir), true], ['EM', part.em, fmtInt(part.em), true],
      ['draw', part.powerUseMax, `${fmt1(part.powerUseMax)} seg`, true]];
  }
  if (t === 'PowerPlant') {
    return [['power', part.powerGen, `${fmtInt(part.powerGen)} seg`], ['EM', part.em, fmtInt(part.em), true], ['HP', part.health, fmtInt(part.health)]];
  }
  const bits = [];
  if (part.em) bits.push(['EM', part.em, fmtInt(part.em), true]);
  if (part.ir) bits.push(['IR', part.ir, fmtInt(part.ir), true]);
  if (part.powerUseMax) bits.push(['draw', part.powerUseMax, `${fmt1(part.powerUseMax)} seg`, true]);
  if (part.health) bits.push(['HP', part.health, fmtInt(part.health)]);
  return bits;
}

/** The one figure a port row leads with. */
function headFigure(part, ship) {
  const [first] = partFigures(part, ship);
  return first ? `${first[2]} ${first[0]}` : '';
}

/** Ports by kind, in bench order, then by hardpoint name so two coolers sit together. */
function benchGroups(ports) {
  const order = new Map(BENCH_KINDS.map((k, i) => [k, i]));
  const groups = new Map();
  for (const port of ports) {
    const kind = port.group;
    if (!groups.has(kind)) groups.set(kind, []);
    groups.get(kind).push(port);
  }
  return [...groups.entries()]
    .sort((a, b) => (order.get(a[0]) ?? 99) - (order.get(b[0]) ?? 99))
    .map(([kind, list]) => [kind, list.sort((a, b) => a.hardpoint.localeCompare(b.hardpoint))]);
}

/**
 * Identical ports fold into one row. Sixteen missile ports carrying the same
 * missile are one decision, not sixteen: the row says ×16, and a part fitted
 * from it goes on all of them. Two coolers with different parts stay apart.
 */
function benchRows(ports) {
  const rows = new Map();
  for (const port of ports) {
    const key = [port.group, port.minSize, port.maxSize, port.stockClass || '', port.class || ''].join('|');
    if (!rows.has(key)) rows.set(key, { ...port, portIds: [] });
    rows.get(key).portIds.push(port.portId);
  }
  return [...rows.values()];
}

/** The bench's ports as last drawn - the current fit, not stock. */
let garageBenchPorts = [];

/**
 * Every port folded into the row that holds this one - the row as it is on
 * screen. The rows fold by what is fitted now, so two coolers that started
 * alike and were changed apart are two rows; deciding from the stock fit put
 * a part meant for cooler 1 on cooler 2 as well.
 */
function siblingsOf(portId) {
  const current = benchRows(garageBenchPorts).find((r) => r.portIds.includes(portId));
  if (current) return current.portIds;
  const stock = benchRows((garageStock?.ports || []).filter((p) => BENCH_KINDS.includes(p.group)));
  return stock.find((r) => r.portIds.includes(portId))?.portIds || [portId];
}

function renderBench(data) {
  const ports = (data.ports || []).filter((p) => BENCH_KINDS.includes(p.group));
  garageBenchPorts = ports;
  const optimizer = $('#garage-optimizer');
  const bar = $('#garage-bench-bar');
  const bench = $('#garage-bench');
  const caption = $('#garage-bench-caption');
  optimizer.hidden = bar.hidden = bench.hidden = caption.hidden = ports.length === 0;
  if (!ports.length) return;

  const changed = ports.filter((p) => p.changed).length;
  $('#garage-changes').textContent = changed ? `${changed} part${changed === 1 ? '' : 's'} changed` : 'Stock fit';
  $('#garage-changes').className = changed ? 'changed' : 'muted';
  $('#garage-reset').hidden = !changed;
  $('#garage-shop').hidden = !changed;

  const list = $('#garage-bench-ports');
  list.textContent = '';

  for (const [kind, group] of benchGroups(ports)) {
    list.append(el('div', 'bench-kind', `${garageWord(kind)}${group.length > 1 ? ` · ${group.length}` : ''}`));
    for (const port of benchRows(group)) {
      const many = port.portIds.length > 1;
      const selected = port.portIds.includes(garageSelectedPort);
      const rowEl = el('div', `bench-port${port.changed ? ' changed' : ''}${selected ? ' selected' : ''}`);
      rowEl.dataset.port = port.portIds[0];
      rowEl.dataset.count = String(port.portIds.length);
      rowEl.append(partMark(port.fitted));

      const mid = el('div');
      const name = el('div', 'part-name', port.name || (port.class ? port.class : 'empty'));
      if (port.fitted) name.append(partChip(port.fitted));
      if (many) name.append(el('span', 'chip count', `×${port.portIds.length}`));
      mid.append(name);
      const sub = el('div', 'port-name', many ? `${garagePortName(port.hardpoint)} and ${port.portIds.length - 1} more` : garagePortName(port.hardpoint));
      if (port.changed) sub.append(el('span', 'was', `was ${port.stockName || port.stockClass || 'empty'}`));
      mid.append(sub);
      if (port.fixedReason) mid.append(el('span', 'muted small', port.fixedReason));
      rowEl.append(mid);

      const figure = el('div', 'figure');
      const [first, second] = partFigures(port.fitted, data.ship);
      if (first) figure.append(el('b', null, `${first[2]} ${first[0]}`));
      if (second) figure.append(document.createTextNode(`${second[2]} ${second[0]}`));
      rowEl.append(figure);

      if (!port.fixedReason) rowEl.addEventListener('click', () => selectBenchPort(port.portIds[0]).catch(() => {}));
      list.append(rowEl);
    }
  }
}

/** Opens the candidates for one port. */
async function selectBenchPort(portId, revealChoices = false) {
  if (garageBenchPorts.find((p) => p.portId === portId)?.fixedReason) return;
  const request = ++benchRequest;
  const cls = garageClass;
  garageSelectedPort = portId;
  for (const rowEl of $$('#garage-bench-ports .bench-port')) rowEl.classList.toggle('selected', rowEl.dataset.port === portId);
  // The fitted-layout cards are another way into this same port, so the
  // selected state must move in both views rather than leaving two answers.
  renderGarageRig(garageStock);

  const panel = $('#garage-bench-panel');
  panel.textContent = '';
  panel.append(el('p', 'muted', 'Looking up what fits…'));

  let options;
  try {
    options = await getJson(`/api/garage/${encodeURIComponent(cls)}/options?port=${encodeURIComponent(portId)}`);
  } catch {
    if (request !== benchRequest || cls !== garageClass) return;
    panel.textContent = '';
    panel.append(el('p', 'muted', 'Could not read what fits this port.'));
    return;
  }
  // A later pick, or another ship, has taken the panel; this answer is for a port nobody is looking at.
  if (request !== benchRequest || cls !== garageClass) return;

  garageOptions = options;
  renderBenchPanel();
  if (revealChoices) revealGarageChoices(panel);
}

/** A card in the fitted layout opens a result well below the fold. Move to
 * that answer once it has rendered; without this, the click can look inert. */
function revealGarageChoices(panel) {
  panel.tabIndex = -1;
  panel.focus({ preventScroll: true });
  panel.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function renderBenchPanel() {
  const panel = $('#garage-bench-panel');
  if (!garageOptions || !garageStock) { panel.textContent = ''; return; }

  // The search box stays where it is while its results redraw: rebuilding it
  // on every keystroke took the focus with it, and typing "cold" left "c".
  // Head, tools and the list are three boxes; only what changed is redrawn,
  // and the box is a new one only when the port is.
  const sameport = panel.dataset.port === garageOptions.port.portId && panel.querySelector('.bench-search');
  if (!sameport) {
    panel.textContent = '';
    panel.dataset.port = garageOptions.port.portId;
  }

  const port = (garageStock.ports || []).find((p) => p.portId === garageOptions.port.portId) || null;
  const current = currentClassOf(port);
  const fittedPart = garageOptions.options.find((o) => o.part.class === current)?.part || port?.fitted || null;
  const ship = garageStock.ship;
  const terminalOnly = $('#garage-optimise-buyable').checked;
  const term = (garageOptions.filter || '').trim().toLowerCase();
  const keyIndex = 0;
  // Keep the fitted part in view even when it has no known terminal seller:
  // the Bench is still where a pilot compares its current component before
  // choosing a purchasable replacement.
  const rows = garageOptions.options
    .filter((o) => !terminalOnly || o.shops?.length || o.part.class === current)
    .filter((o) => !term || `${o.part.name} ${o.part.manufacturer || ''} ${o.part.makerCode || ''}`.toLowerCase().includes(term))
    .sort((a, b) => {
      const fa = partFigures(a.part, ship)[keyIndex];
      const fb = partFigures(b.part, ship)[keyIndex];
      if (!fa || !fb) return 0;
      // Sorted so the best of the kind is on top: more DPS, less spool.
      return fa[3] ? fa[1] - fb[1] : fb[1] - fa[1];
    });

  const head = sameport ? panel.querySelector('.panel-head') : el('div', 'panel-head');
  head.textContent = '';
  head.append(el('div', 'panel-title', `${garageWord(port?.group || garageOptions.port.kinds[0])} · ${garagePortName(garageOptions.port.hardpoint)}`));
  const sizes = garageOptions.port.minSize === garageOptions.port.maxSize ? `size ${garageOptions.port.maxSize}` : `sizes ${garageOptions.port.minSize}–${garageOptions.port.maxSize}`;
  const many = siblingsOf(garageOptions.port.portId).length;
  head.append(el('div', 'panel-sub', `${sizes}${many > 1 ? ` · ${many} ports alike, fitted together` : ''} · now fitted: ${fittedPart?.name || 'nothing'}${garageOptions.pricesKnown ? '' : ' · prices need UEX (Settings)'}${garageOptions.marketKnown ? '' : ' · player listings need the Player marketplace feed (Settings)'}`));
  if (!sameport) panel.append(head);

  const countText = `${rows.length} of ${garageOptions.options.length} fit${terminalOnly ? ' · terminal aUEC only' : ''} · sorted by ${partFigures(fittedPart || garageOptions.options[0]?.part, ship)[0]?.[0] || 'name'}`;
  let list;
  if (sameport) {
    panel.querySelector('.bench-count').textContent = countText;
    list = panel.querySelector('.candidates');
    list.textContent = '';
  } else {
    const tools = el('div', 'panel-tools');
    const search = el('input', 'search bench-search');
    search.type = 'search';
    search.placeholder = 'Filter by name or maker…';
    search.value = garageOptions.filter || '';
    search.addEventListener('input', () => { garageOptions.filter = search.value; renderBenchPanel(); });
    tools.append(search);
    tools.append(el('span', 'muted bench-count', countText));
    panel.append(tools);
    list = el('div', 'candidates');
    panel.append(list);
  }

  if (!rows.length) {
    list.append(el('p', 'muted', terminalOnly
      ? 'No terminal aUEC seller is recorded for a compatible replacement.'
      : 'Nothing in the reference fits this port.'));
    return;
  }

  const fittedFigures = partFigures(fittedPart, ship);

  for (const option of rows) {
    const part = option.part;
    const isCurrent = part.class === current;
    const isStock = part.class === port?.stockClass;

    const rowEl = el('div', `candidate${isCurrent ? ' fitted' : ''}`);
    rowEl.append(partMark(part));

    const mid = el('div');
    const name = el('div', 'c-name', part.name);
    name.append(partChip(part));
    const componentClass = componentClassChip(option.componentClass);
    if (componentClass) name.append(componentClass);
    const stealth = stealthPickChip(part, garageOptions.options.map((choice) => choice.part));
    if (stealth) name.append(stealth);
    const pip = pipChip(part, fittedPart);
    if (pip) name.append(pip);
    mid.append(name);
    mid.append(el('div', 'c-maker', part.manufacturer || part.makerCode || ''));

    // Each figure beside how it compares with what is in the port now, coloured
    // by whether that is better for the figure: less IR good, less DPS not.
    const figures = el('div', 'c-figures');
    partFigures(part, ship).forEach(([label, value, text, lowerIsBetter], i) => {
      const span = el('span');
      span.append(el('b', null, text), document.createTextNode(` ${label}`));
      const ref = fittedFigures[i];
      if (ref && !isCurrent && Number.isFinite(ref[1]) && Math.abs(ref[1] - value) > 1e-9) {
        const better = lowerIsBetter ? value < ref[1] : value > ref[1];
        const diff = value - ref[1];
        span.append(el('span', better ? 'd-up' : 'd-down', ` ${diff > 0 ? '+' : '−'}${fmtSmart(Math.abs(diff))}`));
      }
      figures.append(span);
    });
    mid.append(figures);

    const shop = el('div', 'c-shop');
    if (option.shops && option.shops.length) {
      const best = option.shops[0];
      shop.append(acquisitionChip('terminal', 'Terminal aUEC', 'Known NPC terminal seller from the UEX market feed.'));
      shop.append(el('b', null, `${fmtInt(best.price)} aUEC`));
      shop.append(document.createTextNode(` · ${best.terminal}${best.place ? `, ${best.place}` : ''}${option.shops.length > 1 ? ` +${option.shops.length - 1}` : ''}`));
    } else if (garageOptions.pricesKnown) {
      if (option.craftable) {
        shop.append(acquisitionChip('craft', 'Blueprint recipe', 'The installed game data contains a recipe; see Crafting for its materials and whether you own the blueprint.'));
        shop.append(document.createTextNode(' No terminal aUEC seller recorded.'));
      } else {
        shop.append(acquisitionChip('unlisted', 'No terminal seller', 'No NPC terminal seller is recorded in the UEX market feed.'));
      }
    }
    // A player offering it is a third route, and a different kind of answer:
    // one person's ask this week, with the deal made on UEX, not a counter.
    if (option.listings && option.listings.length) {
      if (shop.childElementCount) shop.append(el('br'));
      shop.append(listingLine(option.listings[0], option.listings.length - 1));
    }
    mid.append(shop);
    rowEl.append(mid);

    const act = el('div', 'c-act');
    if (isCurrent) {
      act.append(el('span', 'state', isStock ? 'Stock' : 'Fitted'));
    } else {
      const fit = el('button', 'ghost tiny', isStock ? 'Back to stock' : 'Fit');
      fit.type = 'button';
      // Fitting from this list is an intentional purchase decision. A known
      // seller lets it become its own shopping line; unknown sellers stay a
      // useful bench comparison without leaving an un-routable list behind.
      const autoShop = !isStock && option.shops?.length ? { name: part.name, shop: option.shops[0] } : null;
      fit.addEventListener('click', () => fitPart(garageOptions.port.portId, isStock ? null : part.class, autoShop).catch(() => {}));
      act.append(fit);
    }
    rowEl.append(act);

    list.append(rowEl);
  }
}

/** What is in a port now: the swap if there is one, else stock. */
function currentClassOf(port) {
  if (!port) return null;
  return Object.prototype.hasOwnProperty.call(garageSwaps, port.portId) ? garageSwaps[port.portId] : port.stockClass;
}

/**
 * Puts a part in a port - and in every port folded into the same bench row,
 * since a row of sixteen missiles is one decision. A null class takes them
 * back to stock, and a bench with nothing changed is the stock sheet again,
 * deltas and all.
 */
async function fitPart(portId, cls, autoShop = null) {
  const portIds = siblingsOf(portId);
  for (const id of portIds) {
    if (cls === null) delete garageSwaps[id];
    else garageSwaps[id] = cls;
  }
  await refitGarage();

  // A folded row may represent sixteen missile ports, but it is still one
  // shopping decision and one shopping-list line with the matching count.
  // Every other edit - a part with no seller, a port put back to stock -
  // reconciles the list the Garage already keeps, so a purchase undone on
  // the bench does not stay on the Shopping page.
  if (autoShop && cls !== null) {
    await addFittedPartToShopping(portIds, autoShop);
  } else {
    await reconcileBenchShopping();
  }
}

/* One goal, one honest measure. A DPS fit does not silently replace coolers,
 * and a stealth fit only scores components whose two signatures are known. */
const GARAGE_OPTIMISE_GOALS = {
  stealth: 'stealth', alpha: 'alpha DPS', sustained: 'sustained DPS', missile: 'missile damage', shield: 'shield HP',
  quantumSpeed: 'quantum speed', quantumRange: 'quantum range', cooling: 'cooling', power: 'power headroom',
};

function optimiseScore(part, goal, ship) {
  if (goal === 'stealth') {
    if (!Number.isFinite(part.em) || !Number.isFinite(part.ir)) return null;
    return -(part.em + part.ir);
  }
  if (goal === 'alpha') return Number.isFinite(part.weapon?.alpha) ? part.weapon.alpha : null;
  if (goal === 'sustained') return Number.isFinite(part.weapon?.sustainedDps) ? part.weapon.sustainedDps : null;
  if (goal === 'missile') return Number.isFinite(part.missile?.damage) ? part.missile.damage : null;
  if (goal === 'shield') return Number.isFinite(part.shield?.hp) ? part.shield.hp : null;
  if (goal === 'quantumSpeed') return Number.isFinite(part.quantum?.speed) ? part.quantum.speed : null;
  if (goal === 'quantumRange') {
    if (!Number.isFinite(part.quantum?.fuelRate) || part.quantum.fuelRate <= 0 || !Number.isFinite(ship.quantumFuel)) return null;
    return ship.quantumFuel / part.quantum.fuelRate;
  }
  if (goal === 'cooling') return part.type === 'Cooler' && Number.isFinite(part.coolantGen) ? part.coolantGen : null;
  if (goal === 'power') return part.type === 'PowerPlant' && Number.isFinite(part.powerGen) ? part.powerGen : null;
  return null;
}

async function optimiseGarage() {
  if (!garageClass || !garageStock) return;
  const button = $('#garage-optimise');
  const status = $('#garage-optimise-status');
  const goal = $('#garage-optimise-goal').value;
  const buyableOnly = $('#garage-optimise-buyable').checked;
  // The rows as the bench shows them - the current fit - so a cooler changed
  // apart from its twin is decided on its own.
  const rows = benchRows(garageBenchPorts.length ? garageBenchPorts : (garageStock.ports || []).filter((p) => BENCH_KINDS.includes(p.group)));
  const cls = garageClass;
  button.disabled = true;
  status.textContent = `Finding the best ${GARAGE_OPTIMISE_GOALS[goal] || 'fit'}…`;

  let changed = 0;
  let unavailable = 0;
  try {
    for (const row of rows) {
      const options = garageOptions?.port?.portId === row.portIds[0]
        ? garageOptions
        : await getJson(`/api/garage/${encodeURIComponent(garageClass)}/options?port=${encodeURIComponent(row.portIds[0])}`).catch(() => null);
      if (!options) { unavailable += row.portIds.length; continue; }
      // The ship changed under the optimiser: its choices belong to the old bench.
      if (cls !== garageClass) return;

      const ranked = (options.options || [])
        .filter((option) => !buyableOnly || option.shops?.length)
        .map((option) => ({ option, score: optimiseScore(option.part, goal, garageStock.ship) }))
        .filter((entry) => Number.isFinite(entry.score))
        .sort((a, b) => b.score - a.score || a.option.part.name.localeCompare(b.option.part.name));
      if (!ranked.length) continue; // This port does not affect the selected goal.

      const best = ranked[0].option.part;
      if (best.class === currentClassOf(row)) continue;
      for (const id of row.portIds) {
        if (best.class === (garageStock.ports || []).find((p) => p.portId === id)?.stockClass) delete garageSwaps[id];
        else garageSwaps[id] = best.class;
      }
      changed += row.portIds.length;
    }

    if (changed) { await refitGarage(); await reconcileBenchShopping(); }
    const scope = buyableOnly ? ' from known terminal aUEC sellers' : '';
    status.textContent = changed
      ? `Optimised ${changed} port${changed === 1 ? '' : 's'} for ${GARAGE_OPTIMISE_GOALS[goal]}${scope}. Review the sheet, then add the changed parts to Shopping when you are ready to buy.`
      : `Nothing on this fit changed for ${GARAGE_OPTIMISE_GOALS[goal]}${scope}.`;
    if (unavailable) status.textContent += ` ${unavailable} port${unavailable === 1 ? '' : 's'} could not be read.`;
  } finally {
    button.disabled = false;
  }
}

/* ---------- saved builds ---------- */

/** The builds saved for the ship on the bench, the one open for editing, and what deltas are measured from. */
let garageBuilds = [];
let garageOpenBuild = null;
let garageCompare = '';
const garageSheetCache = new Map();

/** Opens the Garage on a ship from elsewhere - the Fleet card's button. */
function openGarageFor(cls) {
  garageClass = cls;
  showView('garage');
}

async function loadBuilds() {
  const cls = garageClass;
  let builds;
  try {
    builds = await getJson(`/api/garage/builds?ship=${encodeURIComponent(cls)}`);
  } catch {
    builds = [];
  }
  // Another ship's builds must not land on this bench.
  if (cls !== garageClass) return;
  garageBuilds = builds;
  renderBuilds();
}

function renderBuilds() {
  const box = $('#garage-builds');
  box.textContent = '';
  box.hidden = garageBuilds.length === 0;

  for (const build of garageBuilds) {
    const chip = el('span', `build-chip${build.id === garageOpenBuild ? ' open' : ''}`);
    chip.dataset.build = build.id;
    chip.append(el('span', null, build.name));
    const n = Object.keys(build.swaps || {}).length;
    chip.append(el('span', 'meta', `${n} part${n === 1 ? '' : 's'} · ${relative(build.updatedAt)}`));
    chip.addEventListener('click', () => openBuild(build.id).catch(() => {}));

    const drop = el('button', 'drop', '×');
    drop.type = 'button';
    drop.title = `Delete "${build.name}"`;
    drop.addEventListener('click', (e) => { e.stopPropagation(); deleteBuild(build.id).catch(() => {}); });
    chip.append(drop);
    box.append(chip);
  }

  const compare = $('#garage-compare');
  const keep = garageCompare;
  compare.textContent = '';
  const stock = el('option', null, 'Stock');
  stock.value = '';
  compare.append(stock);
  for (const build of garageBuilds) {
    const option = el('option', null, build.name);
    option.value = build.id;
    compare.append(option);
  }
  compare.value = garageBuilds.some((b) => b.id === keep) ? keep : '';
  garageCompare = compare.value;

  $('#garage-update').hidden = !garageOpenBuild;
}

async function openBuild(id) {
  const build = garageBuilds.find((b) => b.id === id);
  if (!build) return;
  garageOpenBuild = id;
  garageSwaps = { ...(build.swaps || {}) };
  await refitGarage();
}

async function saveBuild(name) {
  const res = await fetch('/api/garage/builds', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ shipClass: garageClass, name, swaps: garageSwaps }),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const build = await res.json();
  garageBuilds.unshift(build);
  garageOpenBuild = build.id;
  renderBuilds();
}

/** Writes the bench's swaps into the build that is open. */
async function updateBuild() {
  if (!garageOpenBuild) return;
  const res = await fetch(`/api/garage/builds/${encodeURIComponent(garageOpenBuild)}`, {
    method: 'PUT', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ swaps: garageSwaps }),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const build = await res.json();
  garageBuilds = garageBuilds.map((b) => (b.id === build.id ? build : b));
  garageSheetCache.delete(build.id);
  renderBuilds();
}

async function deleteBuild(id) {
  const res = await fetch(`/api/garage/builds/${encodeURIComponent(id)}`, { method: 'DELETE' });
  if (!res.ok && res.status !== 404) throw new Error(`HTTP ${res.status}`);
  garageBuilds = garageBuilds.filter((b) => b.id !== id);
  garageSheetCache.delete(id);
  if (garageOpenBuild === id) garageOpenBuild = null;
  if (garageCompare === id) garageCompare = '';
  renderBuilds();
  await refitGarage();
}

/** The sheet for a set of swaps, asked of the server once per distinct fit. */
async function sheetFor(swaps) {
  if (!Object.keys(swaps).length) return garageStock;
  const key = JSON.stringify(Object.entries(swaps).sort());
  if (garageSheetCache.has(key)) return garageSheetCache.get(key);

  const res = await fetch(`/api/garage/${encodeURIComponent(garageClass)}/sheet`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ swaps }),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);

  const data = { ...(await res.json()), ship: garageStock.ship };
  garageSheetCache.set(key, data);
  return data;
}

/**
 * Redraws the sheet for the bench's swaps, with the struck figures measured
 * from stock or from the build chosen under "Compare against" - which is how
 * two builds are set side by side without a second sheet on the page.
 */
async function refitGarage() {
  if (!garageClass || !garageStock) return;
  const request = ++refitRequest;
  const cls = garageClass;

  const current = await sheetFor(garageSwaps);
  const against = garageBuilds.find((b) => b.id === garageCompare);
  const reference = against ? await sheetFor(against.swaps || {}) : garageStock;
  // A newer refit, or another ship, has the bench now; this sheet is stale.
  if (request !== refitRequest || cls !== garageClass) return;

  garageSheet = current.sheet;
  renderGarage(current, reference === current ? null : reference);
  renderBench(current);
  renderBenchPanel();
  renderBuilds();
}

async function resetGarage() {
  garageSwaps = {};
  garagePhotoApplied = false;
  $('#garage-optimise-status').textContent = '';
  await refitGarage();
  renderGaragePhoto();
  await reconcileBenchShopping();
}

$('#garage-reset')?.addEventListener('click', () => resetGarage().catch(() => {}));
$('#garage-update')?.addEventListener('click', () => updateBuild().catch(() => {}));
$('#garage-save')?.addEventListener('click', () => {
  const form = $('#garage-save-form');
  form.hidden = !form.hidden;
  if (!form.hidden) $('#garage-save-name').focus();
});
$('#garage-save-cancel')?.addEventListener('click', () => { $('#garage-save-form').hidden = true; });
$('#garage-save-form')?.addEventListener('submit', (e) => {
  e.preventDefault();
  const name = $('#garage-save-name').value.trim();
  $('#garage-save-form').hidden = true;
  $('#garage-save-name').value = '';
  saveBuild(name || 'Untitled build').catch(() => {});
});
onInput('#garage-compare', () => { garageCompare = $('#garage-compare').value; refitGarage().catch(() => {}); });

/**
 * The bench's changes as a shopping list. The server writes the job and
 * proposes the stop that sells the most of it; this says what it did and
 * links to the list, and nothing else - from here it is the Shopping page's
 * flow, the Now page's, the MFD's.
 */
/**
 * The list the Garage keeps for this bench, brought up to date with what is
 * on it now and never started here: a fit put back to stock removes the
 * list rather than leaving a purchase nobody wants on the Shopping page.
 */
async function reconcileBenchShopping() {
  if (!garageClass) return;
  await shopForBench(true);
}

async function shopForBench(onlyIfExists = false) {
  const result = $('#garage-shop-result');
  result.hidden = true;
  if (!garageClass) return;
  if (!onlyIfExists && !Object.keys(garageSwaps).length) return;

  const open = garageBuilds.find((b) => b.id === garageOpenBuild);
  const title = open ? open.name : `${garageStock?.ship?.name || garageClass} fit`;

  const res = await fetch(`/api/garage/${encodeURIComponent(garageClass)}/shop`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ swaps: garageSwaps, title, onlyIfExists }),
  });

  if (!res.ok) {
    const problem = await res.json().catch(() => null);
    result.textContent = '';
    result.hidden = false;
    result.append(el('span', 'muted', problem?.message || 'The list could not be written.'));
    return;
  }

  const { job, proposal, created, consolidated, removed, removedTitle, destinationKept } = await res.json();

  // Nothing kept and nothing to keep: a reconcile with no list says nothing.
  if (!job) {
    if (!removed) return;
    result.textContent = '';
    result.hidden = false;
    result.append(el('span', 'muted', `The bench is back to stock, so "${removedTitle}" was taken off Shopping.`));
    return;
  }

  result.textContent = '';
  result.hidden = false;
  const items = (job.items || []).reduce((n, i) => n + (i.needed || 1), 0);

  const line = el('span');
  line.append(document.createTextNode(`${created === false ? 'Updated' : 'Added'} "${job.title}" - ${items} part${items === 1 ? '' : 's'} on ${job.items.length} line${job.items.length === 1 ? '' : 's'}. `));
  const link = el('a', null, 'Open Shopping');
  link.href = '#jobs';
  link.addEventListener('click', (e) => { e.preventDefault(); showView('jobs'); });
  line.append(link);
  result.append(line);
  if (consolidated) result.append(el('span', 'muted', ` Consolidated ${consolidated} earlier Garage list${consolidated === 1 ? '' : 's'}.`));

  // The stop, and what it lacks. "Nowhere" is said rather than left blank:
  // with UEX off there is no answer, and without a counter the list is still
  // a list.
  if (proposal.terminal) {
    const where = `${proposal.terminal}${proposal.place ? `, ${proposal.place}` : ''}`;
    // A destination the pilot chose on Shopping is theirs; the proposal is
    // offered beside it, not written over it.
    let note = destinationKept
      ? `Destination kept as ${job.destination} (chosen on Shopping). UEX would propose ${where} - ${proposal.covered} of ${proposal.of} line${proposal.of === 1 ? '' : 's'}`
      : `Destination: ${where} - ${proposal.covered} of ${proposal.of} line${proposal.of === 1 ? '' : 's'}`;
    if (proposal.total > 0) note += `, ${fmtInt(proposal.total)} aUEC`;
    if (proposal.missing?.length) note += `. Not sold there: ${proposal.missing.join(', ')}`;
    result.append(el('span', 'muted', note + '.'));
  } else {
    result.append(el('span', 'muted', proposal.pricesKnown
      ? 'No terminal UEX knows sells any of it; the list has no destination.'
      : 'Destinations need UEX prices (Settings); the list was written without one.'));
  }
}

/**
 * A direct Fit should make its buyable component actionable straight away,
 * but it is still the ship's one evolving fit. Reposting the whole bench lets
 * the server update that fit instead of leaving a stack of one-part lists.
 */
async function addFittedPartToShopping() {
  await shopForBench();
}

$('#garage-shop')?.addEventListener('click', () => shopForBench().catch(() => {}));
$('#garage-optimise')?.addEventListener('click', () => optimiseGarage().catch(() => {}));
$('#garage-optimise-buyable')?.addEventListener('change', () => {
  if (garageOptions) renderBenchPanel();
});

onInput('#garage-mine', () => { const v = $('#garage-mine').value; if (v) openGarage(v).catch(() => {}); });
onInput('#garage-all', () => { const v = $('#garage-all').value; if (v) openGarage(v).catch(() => {}); });
onInput('#servers-troubled', renderServers);

/**
 * The one-line version of the price chart, for the expanded Market row.
 *
 * No axes and no grid: at this size a gridline is noise, and the two numbers
 * that matter - the range it moved in, and how long that covers - read better
 * as text beside it than as labels inside it. Anything more belongs on the
 * page the button next to it opens.
 */
async function drawDetailSpark(strip, commodity) {
  // One counter per side, not the page's four. Every counter is a separate
  // request to UEX, and expanding a row is the ordinary way to read this table
  // - somebody comparing twenty commodities should not cost a volunteer-run
  // API a hundred and sixty requests to draw twenty thumbnails. Opening the
  // full page later widens the sample; opening it first makes this free.
  const trend = await getJson(
    `/api/uex/history?commodity=${encodeURIComponent(commodity)}&perSide=1`);

  const daily = dailyMarket(trend).filter((d) => d.bestSell > 0);

  if (daily.length < 2) {
    strip.remove();
    return;
  }

  const values = daily.map((d) => d.bestSell);
  const low = Math.min(...values);
  const high = Math.max(...values);
  const span = Math.max(1, high - low);
  const days = Math.round((daily[daily.length - 1].t - daily[0].t) / 86400000);

  const svg = svgEl('svg', {
    class: 'spark', viewBox: '0 0 240 34', preserveAspectRatio: 'none',
    role: 'img', 'aria-label': `${commodity} price over the last ${days} days`,
  });

  svg.append(svgEl('path', {
    d: daily.map((d, i) =>
      `${i ? 'L' : 'M'} ${(i / (daily.length - 1) * 238 + 1).toFixed(1)} `
      + `${(31 - ((d.bestSell - low) / span) * 28).toFixed(1)}`).join(' '),
    fill: 'none', stroke: '#35c8f0', 'stroke-width': '1.5',
    'stroke-linejoin': 'round', 'stroke-linecap': 'round',
  }));

  strip.append(svg);

  // What it says depends on what came back, not on what was asked for: this
  // asks for one counter per side, but a wider sample already cached by the
  // commodity page is reused, and then the line really is a best-of.
  const from = trend.sampled > 1
    ? `best of ${trend.sampled} counters each day`
    : 'the busiest counter';

  strip.append(el('span', 'muted',
    `${money(low)} – ${money(high)} over ${days} days, ${from}`));
}

/**
 * Cargo earnings over time, as running totals.
 *
 * Deliberately cumulative. A hold is sold a handful of times a month, so a line
 * of per-week takings is mostly zero with occasional spikes - which reads as a
 * business collapsing between runs rather than as one being run occasionally.
 * A running total only ever goes up, and the gap between the two lines is the
 * number a hauler actually wants.
 *
 * Both lines start at zero on the day before the first trade, so a single
 * receipt still draws a line rather than a dot the chart cannot scale.
 */
function drawCargoEarnings(trades) {
  const svg = $('#cargo-chart');
  if (!svg) return;

  const ordered = [...trades].sort((a, b) => Date.parse(a.at) - Date.parse(b.at));

  const running = (side) => {
    const rows = ordered.filter((t) => (side === 'sell' ? t.isSell : !t.isSell));
    if (!rows.length) return [];

    let total = 0;
    const start = Date.parse(rows[0].at) - 86400000;

    return [{ t: start, v: 0 }, ...rows.map((t) => {
      total += Number(t.amount) || 0;
      return { t: Date.parse(t.at), v: total };
    })];
  };

  const series = [
    { label: 'Earned selling cargo', points: running('sell') },
    { label: 'Spent buying it', points: running('buy') },
  ];

  timeChart(svg, series, (v) => `${Math.round(v / 1000).toLocaleString()}k`);
  chartKey('#cargo-chart-key', series);
}

/* ---------- one commodity, in full ---------- */

const CHART_COLOURS = ['#35c8f0', '#ffb454', '#7fe4ff', '#ff7a8a'];

/**
 * A multi-line time chart.
 *
 * Days are the x axis rather than sample index: counters report when they feel
 * like it, so plotting by index would stretch a quiet fortnight to the same
 * width as a busy afternoon and invent a trend out of the reporting rate.
 */
function timeChart(svg, series, format) {
  svg.textContent = '';

  const drawable = drawableSeries(series);

  if (!drawable.length) {
    const text = svgEl('text', {
      x: 500, y: 110, 'text-anchor': 'middle', class: 'empty-note',
    });
    text.textContent = 'NOT ENOUGH HISTORY YET';
    svg.append(text);
    return;
  }

  const all = drawable.flatMap((s) => s.points);
  const times = all.map((p) => p.t);
  const values = all.map((p) => p.v);

  const t0 = Math.min(...times);
  const t1 = Math.max(...times);
  const span = Math.max(1, t1 - t0);

  // Zero is included so a line that halves looks halved. Starting the axis at
  // the lowest value makes every wobble look like a crash.
  const top = Math.max(...values, 0);
  const bottom = Math.min(...values, 0);
  const height = Math.max(1, top - bottom);

  const x = (t) => 46 + ((t - t0) / span) * 930;
  const y = (v) => 196 - ((v - bottom) / height) * 170;

  for (const value of [bottom, (bottom + top) / 2, top]) {
    svg.append(svgEl('line', { x1: 46, y1: y(value), x2: 976, y2: y(value), class: 'grid' }));
    const label = svgEl('text', { x: 4, y: y(value) + 4, class: 'axis' });
    label.textContent = format(value);
    svg.append(label);
  }

  for (const [edge, anchor] of [[t0, 'start'], [t1, 'end']]) {
    const label = svgEl('text', { x: x(edge), y: 214, 'text-anchor': anchor, class: 'axis' });
    label.textContent = new Date(edge).toLocaleDateString([], { month: 'short', day: '2-digit' });
    svg.append(label);
  }

  drawable.forEach((line, i) => {
    const colour = CHART_COLOURS[i % CHART_COLOURS.length];
    const d = line.points
      .map((p, n) => `${n ? 'L' : 'M'} ${x(p.t).toFixed(1)} ${y(p.v).toFixed(1)}`)
      .join(' ');

    svg.append(svgEl('path', {
      d, fill: 'none', stroke: colour, 'stroke-width': '2',
      'stroke-linejoin': 'round', 'stroke-linecap': 'round',
    }));
  });
}

/**
 * The lines a chart actually draws. Shared with the key because colours are
 * handed out by position: count the skipped lines on one side only and every
 * swatch names the line above it.
 */
function drawableSeries(series) {
  return series.filter((s) => s.points.length > 1);
}

/** The key under a chart: a line has no meaning without one. */
function chartKey(container, series) {
  const box = $(container);
  box.textContent = '';

  drawableSeries(series).forEach((line, i) => {
    const entry = el('span');
    const swatch = el('i');
    swatch.style.background = CHART_COLOURS[i % CHART_COLOURS.length];
    entry.append(swatch, document.createTextNode(line.label));
    box.append(entry);
  });
}

/**
 * Rolls per-counter history up into one series per question.
 *
 * Each counter is carried forward to the day before the next report, then the
 * days are combined. Without the carry-forward a day on which only two of eight
 * counters reported would read as demand collapsing and recovering, which is a
 * story about UEX's contributors rather than about the market.
 */
function dailyMarket(history) {
  const days = new Map();
  const DAY = 86400000;

  const counters = history.series
    .filter((terminal) => terminal.points.length)
    .map((terminal) => terminal.points.map((p) => ({ ...p, day: Math.floor(Date.parse(p.at) / DAY) })));

  if (!counters.length) return [];

  for (const points of counters) {
    const last = points[points.length - 1].day;

    let i = 0;
    let held = null;

    for (let day = points[0].day; day <= last; day++) {
      while (i < points.length && points[i].day <= day) held = points[i++];

      const bucket = days.get(day) || { bestSell: 0, bestBuy: 0, demand: 0, stock: 0, counters: 0 };
      if (held.sell > 0) bucket.bestSell = Math.max(bucket.bestSell, held.sell);
      if (held.buy > 0) bucket.bestBuy = bucket.bestBuy ? Math.min(bucket.bestBuy, held.buy) : held.buy;
      bucket.demand += held.demand;
      bucket.stock += held.stock;
      bucket.counters += 1;
      days.set(day, bucket);
    }
  }

  return [...days.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([day, v]) => ({
      t: day * DAY,
      bestSell: v.bestSell,
      bestBuy: v.bestBuy,
      counters: v.counters,

      // Per reporting counter rather than summed. Counters enter and leave
      // UEX's sample - on this install's Iron, eight report at the start and
      // five by the end - so a total slopes down as reporting thins, which is
      // the story about UEX's contributors the carry-forward above exists to
      // avoid. Clipping to the days all eight cover would say it honestly too,
      // and would throw away the most recent fortnight to do it.
      demand: v.counters ? v.demand / v.counters : 0,
      stock: v.counters ? v.stock / v.counters : 0,
    }));
}

/** What the page is showing, so Back and a redraw know where they are. */
let openCommodityName = null;

/**
 * The full picture for one commodity.
 *
 * The history is a request per counter, so it happens here - on the click that
 * opens the page - rather than anywhere a page merely loads.
 */
async function openCommodity(name) {
  openCommodityName = name;
  showView('commodity');

  // showView wrote #commodity; the subject belongs in the link too.
  const fragment = `#commodity/${encodeURIComponent(name)}`;
  if (location.hash !== fragment) history.replaceState(null, '', fragment);

  $('#commodity-name').textContent = name;
  $('#commodity-sub').textContent = 'Asking UEX what this has been doing…';

  // A link straight into this page arrives before Market has ever been opened,
  // so the catalogue its headline figures come from is not loaded yet.
  if (!marketEntries.length) await loadMarket().catch(() => {});

  const entry = marketEntries.find((e) => e.name === name);

  tiles('#commodity-summary', [
    ['Best sell now', entry?.uex?.bestSell > 0 ? money(entry.uex.bestSell) : '—'],
    ['15-day average', entry?.uex?.avgSell > 0 ? money(entry.uex.avgSell) : '—'],
    ['You have sold', entry?.myScuSold ? `${entry.myScuSold.toLocaleString()} SCU` : '—'],
    ['It earned you', entry?.myRevenue ? money(entry.myRevenue) : '—'],
  ]);

  renderCommodityCounters(await terminalsFor(name).catch(() => []), entry);
  renderCommodityReceipts(name);

  // Named "trend", not "history": a local called history shadows window.history
  // for this whole function, and the fragment is written above it.
  let trend;
  try {
    trend = await getJson(`/api/uex/history?commodity=${encodeURIComponent(name)}`);
  } catch {
    $('#commodity-sub').textContent = 'UEX could not be reached, so no history is drawn.';
    return;
  }

  // Racing clicks: the reader has moved on, and this answer is for a page that
  // is no longer open.
  if (openCommodityName !== name) return;

  const daily = dailyMarket(trend);

  $('#commodity-sub').textContent = trend.sampled
    ? `${entry?.groups?.join(', ') || 'Commodity'} · history from the ${trend.sampled} busiest `
      + `of ${trend.terminals} counters that trade it, by demand and by stock.`
    : trend.terminals
      ? `Live UEX quotes are available at ${trend.terminals} counters, but no price-history samples loaded. `
        + 'The counter tables above are still the current report.'
      : 'No UEX market counters are currently reported for this commodity.';

  const priceSeries = [
    { label: 'Best price paid to you', points: daily.filter((d) => d.bestSell > 0).map((d) => ({ t: d.t, v: d.bestSell })) },
    { label: 'Cheapest price charged to you', points: daily.filter((d) => d.bestBuy > 0).map((d) => ({ t: d.t, v: d.bestBuy })) },
  ];

  timeChart($('#commodity-price-chart'), priceSeries, (v) => Math.round(v).toLocaleString());
  chartKey('#commodity-price-key', priceSeries);

  // Only days where both ends are known: a margin needs a buy price as well as
  // a sell one, and subtracting from zero would draw the sale price again under
  // a name that means something else.
  const marginSeries = [{
    label: 'Margin per SCU',
    points: daily.filter((d) => d.bestSell > 0 && d.bestBuy > 0)
      .map((d) => ({ t: d.t, v: d.bestSell - d.bestBuy })),
  }];

  timeChart($('#commodity-margin-chart'), marginSeries, (v) => Math.round(v).toLocaleString());
  chartKey('#commodity-margin-key', marginSeries);

  // One line per counter, capped at the palette: past four the lines start
  // repeating colours and the chart stops being readable.
  const counterSeries = trend.series
    .map((s) => ({
      label: s.terminal,
      points: s.points.filter((p) => p.sell > 0)
        .map((p) => ({ t: Date.parse(p.at), v: p.sell })),
    }))
    .filter((s) => s.points.length > 1)
    .slice(0, CHART_COLOURS.length);

  timeChart($('#commodity-counter-chart'), counterSeries, (v) => Math.round(v).toLocaleString());
  chartKey('#commodity-counter-key', counterSeries);

  const scuSeries = [
    { label: 'Demand — SCU the average counter will take', points: daily.map((d) => ({ t: d.t, v: d.demand })) },
    { label: 'Supply — SCU on the average shelf', points: daily.map((d) => ({ t: d.t, v: d.stock })) },
  ];

  timeChart($('#commodity-scu-chart'), scuSeries, (v) => Math.round(v).toLocaleString());
  chartKey('#commodity-scu-key', scuSeries);
}

/** The two counter tables: where a hold empties, and where it fills. */
function renderCommodityCounters(rows, entry) {
  const sells = rows.filter((r) => r.sell > 0).sort((a, b) => b.sell - a.sell);
  const buys = rows.filter((r) => r.buy > 0).sort((a, b) => a.buy - b.buy);

  const best = sells.length ? sells[0].sell : 0;
  const cheapest = buys.length ? buys[0].buy : 0;

  fillCounterTable('#commodity-sell-table', sells, (r) => [
    money(r.sell),
    r.sellScu ? `${Math.round(r.sellScu).toLocaleString()} SCU` : '—',
    best && r.sell < best ? `−${money(best - r.sell)}` : 'best',
  ], (r) => best && r.sell < best);

  fillCounterTable('#commodity-buy-table', buys, (r) => [
    money(r.buy),
    r.buyScu ? `${Math.round(r.buyScu).toLocaleString()} SCU` : '—',
    cheapest && r.buy > cheapest ? `+${money(r.buy - cheapest)}` : 'cheapest',
  ], (r) => cheapest && r.buy > cheapest);

  // Unused here, but keeps the signature honest about what it was given.
  void entry;
}

function fillCounterTable(selector, rows, cells, isWorse) {
  const body = $(selector).querySelector('tbody');
  body.textContent = '';

  if (!rows.length) {
    const tr = el('tr');
    const td = el('td', 'muted', 'No counter known to trade it this way.');
    td.colSpan = 5;
    tr.append(td);
    body.append(tr);
    return;
  }

  for (const row of rows) {
    const tr = el('tr');
    tr.append(el('td', null, row.terminal));

    const [price, volume, delta] = cells(row);
    tr.append(el('td', 'num', price));
    tr.append(el('td', 'num', volume));
    tr.append(el('td', `num ${isWorse(row) ? 'outward' : 'inward'}`, delta));

    tr.append(el('td', 'muted', row.seen ? dateOf(new Date(row.seen * 1000).toISOString()) : '—'));
    body.append(tr);
  }
}

/** What this install actually paid and was paid for the thing. */
async function renderCommodityReceipts(name) {
  const body = $('#commodity-mine-table').querySelector('tbody');
  body.textContent = '';

  let trades = [];
  try {
    trades = (await getJson('/api/commodities?days=0')).filter((t) => t.commodity === name);
  } catch { /* the tables above still stand on their own */ }

  if (!trades.length) {
    const tr = el('tr');
    const td = el('td', 'muted', 'You have not traded this one.');
    td.colSpan = 6;
    tr.append(td);
    body.append(tr);
    return;
  }

  for (const trade of trades.sort((a, b) => new Date(b.at) - new Date(a.at))) {
    const tr = el('tr');
    tr.append(el('td', null, dateOf(trade.at)));
    tr.append(el('td', null, trade.isSell ? 'Sold' : 'Bought'));
    tr.append(tdPlace(trade.place));
    tr.append(el('td', 'num', String(trade.scu)));
    tr.append(el('td', `num ${trade.isSell ? 'inward' : 'outward'}`, money(trade.amount)));
    tr.append(el('td', 'num muted', money(trade.unitPrice)));
    body.append(tr);
  }
}

$('#commodity-back')?.addEventListener('click', () => showView('market'));

/* ---------- outfitting ---------- */

/** Which shop carries the most of the kit you were wearing when you died. */
async function loadOutfitting() {
  const block = $('#outfitting');
  if (!block) return;

  let data;
  try {
    data = await getJson('/api/outfitting');
  } catch {
    block.hidden = true;
    return;
  }

  if (!data.shops.length) {
    block.hidden = true;
    return;
  }

  tiles('#outfitting-summary', [
    ['Kit worn', `${data.priced} of ${data.kitSize} priced`],
    ['Cheapest anywhere', money(data.cheapest)],
    ['Best single shop', `${data.shops[0].covers} of ${data.kitSize} items`],
  ]);

  const body = $('#outfitting-table tbody');
  body.textContent = '';

  for (const shop of data.shops) {
    const tr = el('tr');
    tr.append(tdPlace(shop.terminal));
    tr.append(el('td', 'num', `${shop.covers} of ${data.kitSize}`));

    const cost = el('td', 'num outward', money(shop.total));
    cost.title = shop.items.map((i) => `${i.item} — ${Math.round(i.price).toLocaleString()} aUEC`).join('\n');
    tr.append(cost);

    // The whole point of knowing: put the trip on a list.
    const action = el('td', 'num');
    const add = el('button', 'ghost track', '+ list');
    add.title = `Add everything ${shop.terminal} carries to your shopping list`;

    add.addEventListener('click', async () => {
      add.disabled = true;
      for (const item of shop.items)
        await fetch('/api/jobs/collect', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name: item.item, needed: 1, unit: '' }),
        }).catch(() => {});

      add.textContent = '✓ added';
    });

    action.append(add);
    tr.append(action);
    body.append(tr);
  }

  block.hidden = false;
}

/* ---------- jobs ---------- */

/**
 * The jobs page: contracts the logs already know about, plus the player's own
 * crafting jobs and shopping lists - which check themselves against the stash,
 * because knowing what is still missing is the whole point of a list.
 */
async function loadJobs() {
  await Promise.all([loadJobContracts(), loadJobList(), fillBlueprintGoals()]);
}

/**
 * The goal picker: blueprints the game has actually given you, so a craft can
 * be started from the page where progress is tracked rather than by hunting
 * the catalogue. Everything else in the catalogue stays available below it,
 * because a blueprint you have not been given is still worth planning for.
 */
async function fillBlueprintGoals() {
  const select = $('#jobs-blueprint');
  if (!select || !craftingCatalogue.length) return;

  const previous = select.value;
  const owned = craftingCatalogue.filter((b) => b.owned);
  const rest = craftingCatalogue.filter((b) => !b.owned && b.materials.length);

  select.textContent = '';

  if (owned.length) {
    const group = document.createElement('optgroup');
    group.label = `Yours (${owned.length})`;
    for (const bp of owned) group.append(new Option(bp.output, bp.output));
    select.append(group);
  }

  const others = document.createElement('optgroup');
  others.label = owned.length ? 'Everything else' : 'Blueprints';
  for (const bp of rest.slice(0, 400)) others.append(new Option(bp.output, bp.output));
  select.append(others);

  if (previous) select.value = previous;
}

$('#jobs-plan')?.addEventListener('click', async (e) => {
  const output = $('#jobs-blueprint').value;
  const bp = craftingCatalogue.find((b) => b.output === output);
  if (!bp) return;

  e.currentTarget.disabled = true;

  try {
    await fetch('/api/jobs', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: `Craft ${bp.output}`,
        kind: 'craft',
        source: `${bp.output} blueprint · ${craftTime(bp.craftSeconds)} to craft`
          + (bp.owned ? ' · in your library' : ''),
        items: parseJobItems(bp.materials.join('\n')),
      }),
    });
    await loadJobList();
  } finally {
    e.currentTarget.disabled = false;
  }
});

/**
 * The pinned job on the Now page - and so in the overlay, where what is still
 * missing is worth having in the corner of the screen while flying.
 */
async function renderPinnedJob(jobs) {
  const card = $('#now-job-card');
  if (!card) return;

  const job = (jobs ?? await getJson('/api/jobs').catch(() => [])).find((j) => j.pinned && !j.done);

  if (!job) {
    card.hidden = true;
    return;
  }

  $('#now-job-title').textContent = job.title;

  const progress = $('#now-job-progress');
  progress.textContent = '';
  progress.append(jobProgress(job.haveCount, job.totalCount,
    `${job.haveCount} of ${job.totalCount} in hand`));

  // What is still missing, which is the only part worth reading mid-flight.
  const list = $('#now-job-items');
  list.textContent = '';

  const missing = job.items.filter((i) => !i.have);

  if (!missing.length) {
    list.append(el('li', 'inward', 'Everything on this list is in hand.'));
  } else {
    for (const item of missing.slice(0, 6)) {
      const li = el('li');
      li.append(el('span', 'n', item.name
        + (item.needed > 0 ? ` ${item.needed}${item.unit ? ` ${item.unit}` : ''}` : '')));

      if (item.buyAt) li.append(el('span', 'muted', `buy at ${item.buyAt}`));
      list.append(li);
    }

    if (missing.length > 6)
      list.append(el('li', 'muted', `+${missing.length - 6} more`));
  }

  card.hidden = false;
}

/**
 * Where the Shopping page should scroll once its contracts have rendered.
 * Set by a button that promised the run rather than the page, and spent on
 * the next load so a later tab click lands at the top as usual.
 */
let jobsLandOn = null;

/** Scroll to the panel a button promised, once it has something to show. */
function landOnJobs() {
  if (!jobsLandOn) return;
  $(jobsLandOn)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  jobsLandOn = null;
}

async function loadJobContracts() {
  const host = $('#jobs-contracts');
  host.textContent = '';

  // Contracts do not survive a game restart, so an "in progress" contract
  // from a session that has ended is a ghost. Only the running session's
  // contracts are real - with the game closed, there are none.
  let live = null;
  try {
    live = await getJson('/api/now');
  } catch { /* server not answering; treat as not playing */ }

  if (!live?.inGame) {
    host.append(el('p', 'muted',
      'Nothing active — the game is not running. Contracts are dropped when you leave, '
      + 'so only a live session can have any.'));
    landOnJobs();
    return;
  }

  let rows = [];
  let plan = null;
  try {
    [rows, plan] = await Promise.all([
      getJson('/api/contracts?days=2'),
      getJson('/api/haul/plan').catch(() => null),
    ]);
  } catch { /* nothing to show */ }

  // This session only: anything taken before it started belongs to the past.
  const since = live.sessionStarted ? new Date(live.sessionStarted).getTime() : 0;
  const open = rows.filter((c) =>
    c.outcome === 'InProgress' && new Date(c.at).getTime() >= since);

  if (!open.length && !plan?.contracts?.length) {
    host.append(el('p', 'muted', 'No contract open in this session.'));
    landOnJobs();
    return;
  }

  if (plan?.contracts?.length) renderHaulPlan(host, plan);

  // Everything that is not a haul keeps its plain card; the hauls are on
  // the run above, with their legs.
  //
  // A haul only gives up its plain card to a run that actually put it on
  // screen. The two lists come from different places - the cards from
  // /api/contracts, the run from /api/haul/plan - so when the run request
  // fails, or simply does not carry a contract the cards do, dropping every
  // haul here left the panel completely empty: no run, no cards, and no
  // message either, because the "No contract open" line above only appears
  // when there is nothing open at all.
  const planned = new Set((plan?.contracts || []).map((c) => c.title));

  for (const contract of open.filter((c) => !c.hauling || !planned.has(c.name))) {
    const card = el('article', 'job-card');

    const head = el('div', 'job-head');
    head.append(el('b', null, contract.name || `${contract.issuer} · ${contract.type}`));
    if (contract.difficulty) head.append(el('span', 'job-kind', contract.difficulty));
    card.append(head);

    const sub = [contract.issuer, contract.type, contract.system, `taken ${relative(contract.at)}`]
      .filter(Boolean).join(' · ');
    card.append(el('div', 'muted', sub));

    if (contract.steps > 0) {
      card.append(jobProgress(contract.stepsDone, contract.steps,
        `${contract.stepsDone} of ${contract.steps} objectives done`));
    }

    host.append(card);
  }

  landOnJobs();
}

/**
 * Every open hauling contract on one route: what each one is known to
 * want, from its title or from a screenshot of its card, then the stops in
 * an order the pilot can rewrite once it is a flight plan.
 *
 * What the plan cannot see is said in words next to the thing it cannot see,
 * because a route with a pickup silently missing is worse than no route.
 */
/**
 * Something to say about the run the next time it is drawn - set when the
 * server refuses a stale one. It cannot live on the button, because showing
 * the pilot the run that now exists means re-rendering the panel the button
 * is in.
 */
let haulPlanNotice = null;

function renderHaulPlan(host, plan) {
  const section = el('div', 'haul-plan');
  section.append(el('h3', 'spaced', 'Hauling run'));

  if (haulPlanNotice) {
    section.append(el('p', 'outward caption', haulPlanNotice));
    haulPlanNotice = null;
  }

  const read = plan.contracts.filter((c) => c.source === 'screenshot').length;
  const summary = [
    `${plan.contracts.length} contract${plan.contracts.length === 1 ? '' : 's'}`,
    `${read} with the card read`,
    plan.knownScu > 0
      ? `${plan.knownScu} SCU remaining${read < plan.contracts.length ? ' known (a floor)' : ''}`
      : null,
    plan.ship && plan.shipScu ? `${plan.ship} holds ${plan.shipScu} SCU` : null,
  ].filter(Boolean).join(' · ');
  section.append(el('p', 'muted caption', summary));

  section.append(el('p', 'muted haul-origin', plan.start
    ? `Route from ${plan.start.name}${plan.start.body ? ` · ${plan.start.body}` : ''} (last known location${plan.locationConfidence ? `, ${plan.locationConfidence.toLowerCase()} confidence` : ''}${plan.travelling ? ', in transit' : ''}). Pickups first, grouped by body and system; distances are not known.`
    : 'Current location unknown — this route cannot choose a nearby starting stop.'));
  section.append(el('p', 'muted caption',
    'Cargo below is projected after completing each stop, assuming the listed pickups still need collecting. It is not a live inventory of your hold.'));

  if (plan.knownScu > 0 && plan.shipScu && plan.knownScu > plan.shipScu) {
    section.append(el('p', 'outward caption',
      `${plan.knownScu} SCU is more than the ${plan.ship} holds — two trips, or another hull.`));
  }

  for (const c of plan.contracts) {
    const card = el('article', 'job-card haul-contract');

    const head = el('div', 'job-head');
    head.append(el('b', null, c.title));
    const source = c.source === 'screenshot' ? 'card read' : c.source === 'title' ? 'title only' : 'unread';
    head.append(el('span', 'job-kind', source));
    if (c.commodity) head.append(el('span', 'muted', c.commodity));
    card.append(head);

    if (c.legs.length) {
      const legs = el('ul', 'haul-legs');
      for (const leg of c.legs) {
        const from = leg.pickup
          ? `${leg.pickup}${leg.pickupBody ? ` (${leg.pickupBody})` : ''}`
          : 'pickup not known';
        const to = leg.delivery
          ? `${leg.delivery}${leg.deliveryBody ? ` (${leg.deliveryBody})` : ''}`
          : 'drop-off not known';
        const scu = leg.scu != null ? ` · ${leg.scuDone || 0}/${leg.scu} SCU` : '';
        legs.append(el('li', leg.pickup && leg.delivery ? null : 'muted', `${from} → ${to}${scu}`));
      }
      card.append(legs);
    }

    if (c.scu != null) {
      const remaining = c.remainingScu != null ? c.remainingScu : c.scu;
      const delivered = c.scuDone || 0;
      card.append(el('div', 'muted haul-progress',
        `${c.scu} SCU contracted · ${remaining} remaining${delivered ? ` · ${delivered} delivered` : ''}`));
    }

    if (c.pickups > 0 || c.deliveries > 0) {
      const bits = [];
      if (c.pickups > 0) bits.push(`${c.pickupsDone} of ${c.pickups} pickup${c.pickups === 1 ? '' : 's'} done`);
      if (c.deliveries > 0) bits.push(`${c.deliveriesDone} of ${c.deliveries} drop-off${c.deliveries === 1 ? '' : 's'} done`);
      card.append(el('div', 'muted haul-progress', bits.join(' · ')));
    }

    if (c.note) card.append(el('div', 'muted haul-note', c.note));
    if (c.shot) card.append(el('div', 'muted haul-note', `read from ${c.shot}`));

    section.append(card);
  }

  if (plan.stops.length) {
    const table = el('table', 'job-items haul-stops');
    const body = el('tbody');

    plan.stops.forEach((stop, i) => {
      const tr = el('tr', 'have');
      tr.append(el('td', 'job-mark', String(i + 1)));

      const where = el('td');
      where.append(el('b', null, stop.place));
      if (stop.body) where.append(el('span', 'muted', ` · ${stop.body}`));
      if (!stop.placeId) where.append(el('span', 'muted', ' · not on the map'));
      tr.append(where);

      const what = el('td');
      for (const a of stop.actions) {
        const scu = a.scu != null ? `${a.scu} SCU ` : '';
        const delivered = a.scuDone ? ` (${a.scuDone} delivered)` : '';
        what.append(el('div', a.kind === 'load' ? 'haul-load' : 'haul-unload',
          `${a.kind} ${scu}${a.commodity || 'cargo'}${delivered} — ${a.contractTitle}${a.note ? ` (${a.note})` : ''}`));
      }
      if (stop.aboard?.length) {
        const cargo = stop.aboard.map((item) => {
          if (item.amountUnknown) return item.knownScu > 0
            ? `${item.commodity} at least ${item.knownScu} SCU`
            : `${item.commodity} quantity not yet known`;
          return `${item.commodity} ${item.knownScu} SCU`;
        }).join(' · ');
        what.append(el('div', 'muted haul-aboard', `projected aboard after this stop: ${cargo}`));
        for (const item of stop.aboard.filter((item) => item.amountUnknown)) {
          what.append(el('div', 'muted haul-cargo-note', item.note
            || `The amount of ${item.commodity} at each pickup was not read. Check this contract's cargo details before loading.`));
        }
      }
      if (stop.note) what.append(el('div', 'muted', stop.note));
      tr.append(what);

      body.append(tr);
    });

    table.append(body);
    section.append(table);

    const actions = el('div', 'haul-actions');
    const make = el('button', 'ghost haul-make', 'Make it the flight plan');
    make.title = 'Write these stops into a tracked flight plan, with the loads and unloads at each';
    make.addEventListener('click', async () => {
      make.disabled = true;
      try {
        // The run this button was drawn for, so the server commits the stops
        // that were read rather than the ones that exist by the time the
        // click arrives.
        const result = await fetch('/api/haul/plan/trip', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ planId: plan.planId || null }),
        }).then((r) => r.json());
        if (result?.id) {
          make.textContent = `✓ ${result.title} — ${result.stops} stops, tracked`;
          if (typeof loadTrips === 'function') loadTrips().catch(() => {});
        } else {
          make.textContent = result?.message || 'could not plan';
          make.disabled = false;

          // The run moved under it: show the new one rather than leave the
          // stale stops on screen next to a message about them. The message
          // goes with it - re-rendering the panel takes this button, and its
          // text, with it.
          if (result?.planId) {
            haulPlanNotice = result.message;
            loadJobContracts().catch(() => {});
          }
        }
      } catch {
        make.textContent = 'failed';
        make.disabled = false;
      }
    });
    actions.append(make);
    section.append(actions);
    section.append(el('p', 'muted caption',
      'Arrival marks the stop reached. Load and unload actions stay manual: the log does not identify which named contract leg changed.'));
  }

  for (const note of plan.notes || []) section.append(el('p', 'muted caption', note));

  host.append(section);
}

/**
 * A "track this" button for any catalogue row: one click puts the thing on
 * the list the player is filling - the pinned job, else the newest open list,
 * else a new one - and says where it went.
 */
function trackButton(name, needed = 1, unit = '') {
  const button = el('button', 'ghost track', '+ list');
  button.title = `Add ${name} to your shopping list`;

  button.addEventListener('click', async () => {
    button.disabled = true;

    try {
      const result = await fetch('/api/jobs/collect', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name, needed, unit }),
      }).then((r) => r.json());

      button.textContent = '✓ added';
      button.title = `On "${result.title}"`;
    } catch {
      button.textContent = 'failed';
      button.disabled = false;
    }
  });

  return button;
}

/** The shared progress bar: done over total, with its own wording. */
/**
 * What a job needs, and where each of it is.
 *
 * Shared by the reader's own cards and by imported ones. The stash and loadout
 * columns are about the reader either way, which is the whole value of seeing
 * somebody else's list: "Bob needs four Agricium" reads very differently beside
 * "and you have some at Port Tressler".
 */
function jobLines(job) {
  const table = el('table', 'job-items');
  const body = el('tbody');

  for (const item of job.items) {
    const tr = el('tr', item.have ? 'have' : null);

    const need = item.needed > 0
      ? `${item.needed}${item.unit ? ` ${item.unit}` : ''}`
      : '';
    tr.append(el('td', 'job-mark', item.have ? '✓' : '·'));
    tr.append(el('td', null, item.name));
    tr.append(el('td', 'num muted', need));

    // Where it is, or where to buy what is missing.
    const whereCell = el('td', 'muted');

    if (item.inventoryUnconfirmed) {
      whereCell.append(el('span', 'note-inline', 'seen in inventory — not counted'));
      if (item.where.length) {
        whereCell.append(document.createTextNode(' · '));
        whereCell.append(placeLink(item.where[0]));
      }
    } else if (item.wornNow) {
      whereCell.textContent = 'worn now';
    } else if (item.where.length) {
      whereCell.append(placeLink(item.where[0]));
      if (item.where.length > 1) {
        const more = el('span', 'note-inline', ` +${item.where.length - 1}`);
        more.title = item.where.slice(1).join('\n');
        whereCell.append(more);
      }
    } else if (item.buyAt) {
      whereCell.append(el('span', 'note-inline', 'buy at '));
      whereCell.append(placeLink(item.buyAt));
    } else {
      whereCell.textContent = '—';
    }
    tr.append(whereCell);

    tr.append(el('td', item.buyPrice ? 'num' : 'num muted',
      item.buyPrice ? money(item.buyPrice) : '—'));

    body.append(tr);
  }

  table.append(body);
  return table;
}

/**
 * The mark on anything that came out of somebody else's file.
 *
 * Names them rather than saying "imported": the reader knows the difference
 * between a list from the friend they fly with and one from a stranger, and
 * the app does not.
 */
function importedChip(from) {
  const chip = el('span', 'job-kind from-a-file', `from ${from.handle || 'a file'}`);
  chip.title = `Imported ${dateOf(from.importedAt)} from a shared file. Not your data.`
    + (from.note ? `\n${from.note}` : '');
  return chip;
}

/**
 * The one thing an imported card can do.
 *
 * It posts to the ordinary authoring endpoint, so the copy is minted a fresh
 * local id through the normal path with the normal checks - the only route by
 * which somebody else's data becomes yours, and a deliberate one.
 *
 * A new list rather than merged into one you have: adding another person's 96
 * SCU to a line you already had produces a number you never chose.
 */
function copyToMine(job) {
  const copy = el('button', 'ghost tiny', 'Copy to my lists');
  copy.title = 'Makes your own copy. Theirs stays where it is.';

  copy.addEventListener('click', async () => {
    copy.disabled = true;

    try {
      await fetch('/api/jobs', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: job.title,
          kind: job.kind,
          source: `copied from ${job.imported.handle || 'a shared file'}`,
          items: job.items.map((i) => ({ name: i.name, needed: i.needed, unit: i.unit })),
        }),
      });
    } finally {
      copy.disabled = false;
    }

    loadJobList();
  });

  return copy;
}

function jobProgress(done, total, label) {
  const wrap = el('div', 'job-progress');
  const track = el('div', 'job-track');
  const fill = el('div', 'job-fill');

  fill.style.width = `${total > 0 ? Math.round((done / total) * 100) : 0}%`;
  if (done >= total && total > 0) fill.classList.add('full');

  track.append(fill);
  wrap.append(track);
  wrap.append(el('span', 'muted', label));
  return wrap;
}

async function loadJobList() {
  const host = $('#jobs-list');
  const craftHost = $('#blueprint-jobs');
  host.textContent = '';
  if (craftHost) craftHost.textContent = '';

  let jobs = [];
  try {
    jobs = await getJson(`/api/jobs${importedQuery()}`);
  } catch { /* server down; the page still shows contracts */ }

  renderPinnedJob(jobs);
  refreshMapFocusContext(mapFocusFilter === 'shopping' || mapFocusFilter === 'stash').catch(() => {});
  reloadPilotBriefing().catch(() => {});

  // Shopping and crafting are different work, so they live on different
  // pages; the cards themselves are identical.
  const lists = jobs.filter((j) => j.kind !== 'craft');
  const builds = jobs.filter((j) => j.kind === 'craft');

  if (!lists.length) {
    host.append(el('p', 'muted',
      'No lists yet. Start one here, or add anything from Market, Parts or Mining with "+ list".'));
  }

  if (craftHost && !builds.length) {
    craftHost.append(el('p', 'muted',
      'No builds planned. Pick a blueprint above, or hit Plan on Reference → Crafting.'));
  }

  for (const job of jobs) {
    const card = el('article', job.done ? 'job-card done' : 'job-card');
    if (job.imported) card.classList.add('from-a-file');

    const head = el('div', 'job-head');
    head.append(el('b', null, job.title));
    head.append(el('span', 'job-kind', job.kind === 'craft' ? 'craft' : 'list'));
    if (job.imported) head.append(importedChip(job.imported));

    // An imported card carries no control that changes anything.
    //
    // Not only because it is somebody else's: the id it arrives under would
    // address one of yours. Ids are minted per install with no namespace, so a
    // file exported from this machine and read back holds ids identical to your
    // own, and every button here builds its URL out of one. The server prefixes
    // them so those routes miss, and this leaves them undrawn as well - a
    // button that 404s is still a button somebody pressed expecting something.
    if (job.imported) {
      head.append(el('span', 'spacer'));
      head.append(copyToMine(job));
      card.append(head);
      card.append(jobProgress(job.haveCount, job.totalCount,
        `you have ${job.haveCount} of the ${job.totalCount} things this needs`));
      card.append(jobLines(job));

      // The same split as any other card: a build belongs on Crafting whoever
      // wrote it.
      (job.kind === 'craft' && craftHost ? craftHost : host).append(card);
      continue;
    }

    // Where this list is for, changeable here because it is a plan rather than
    // a fact: the run you meant on Tuesday is not the run you fly on Friday.
    const where = el('select', 'select job-place-edit');
    where.title = 'Where you mean to shop';
    fillPlaceOptions(where, job.destinationId || job.destination || '');

    where.addEventListener('change', async () => {
      const picked = pickedPlace(where);

      await fetch(`/api/jobs/${job.id}/destination`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ place: picked.name, placeId: picked.id }),
      });

      loadJobList();
    });

    head.append(where);

    const spacer = el('span', 'spacer');
    head.append(spacer);

    // Pinning puts the job on Now, which is also what the overlay shows.
    const pin = el('button', job.pinned ? 'ghost on' : 'ghost', job.pinned ? 'On Now' : 'Pin to Now');
    pin.title = job.pinned
      ? 'Showing on the Now page and in the overlay'
      : 'Show this job on the Now page and in the overlay';

    pin.addEventListener('click', async () => {
      await fetch(`/api/jobs/${job.id}/pin`, { method: 'POST' });
      loadJobList();
    });
    head.append(pin);

    const toggle = el('button', 'ghost', job.done ? 'Reopen' : 'Mark done');
    toggle.addEventListener('click', async () => {
      await fetch(`/api/jobs/${job.id}/toggle`, { method: 'POST' });
      loadJobList();
    });
    head.append(toggle);

    // A list knows where its missing things are sold, which is a shopping trip
    // waiting to be flown - once the player has said which seller they meant.
    const shop = el('button', 'ghost', 'Plan trip');
    shop.title = 'Turn what is still missing into a flight plan';
    shop.addEventListener('click', () => planShoppingTrip(job, card));
    head.append(shop);

    const remove = el('button', 'ghost danger', 'Delete');
    remove.addEventListener('click', async () => {
      await fetch(`/api/jobs/${job.id}`, { method: 'DELETE' });
      loadJobList();
    });
    head.append(remove);
    card.append(head);

    if (job.source) card.append(el('div', 'muted', `from ${job.source}`));

    card.append(jobProgress(job.haveCount, job.totalCount,
      `${job.haveCount} of ${job.totalCount} in hand`));

    card.append(jobLines(job));
    (job.kind === 'craft' && craftHost ? craftHost : host).append(card);
  }
}

/**
 * Parses a written list into job items: "Hadanite 23", "Agricium 1.16 SCU",
 * or a bare name. Quantities are optional - a list of names is still a list.
 */
function parseJobItems(text) {
  return text.split('\n')
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      const match = line.match(/^(.*?)[\s·x×]*?([\d.]+)\s*(SCU|scu)?$/);

      if (match && match[1].trim()) {
        return {
          name: match[1].replace(/[\s×x·]+$/, '').trim(),
          needed: Number(match[2]) || 0,
          unit: match[3] ? 'SCU' : '',
        };
      }

      return { name: line, needed: 0, unit: '' };
    });
}

/**
 * Fills a picker with every place the app knows, and selects one.
 *
 * Picked rather than typed: these are places the app already knows by name -
 * from the game's own data and from where you have actually been - so making
 * someone spell "CRU-L4 Shallow Fields Station" is asking them to guess at
 * something already on the screen. Somewhere you have visited heads the list,
 * because a run is usually to a place you have flown to before.
 *
 * @param selected The place id to select, or a plain name for a destination
 *   saved before this was a picker.
 */
function fillPlaceOptions(select, selected) {
  if (!select) return;

  select.textContent = '';

  const anywhere = document.createElement('option');
  anywhere.value = '';
  anywhere.textContent = 'Anywhere — no particular stop';
  select.append(anywhere);

  const been = atlas.filter((l) => l.visits > 0).sort((a, b) => b.visits - a.visits);
  const rest = atlas.filter((l) => !l.visits).sort((a, b) => a.name.localeCompare(b.name));

  const add = (label, places) => {
    if (!places.length) return;

    const group = document.createElement('optgroup');
    group.label = label;

    for (const place of places) {
      const option = document.createElement('option');
      option.value = place.rawId;
      option.textContent = place.system ? `${place.name} · ${place.system}` : place.name;
      group.append(option);
    }

    select.append(group);
  };

  add('Where you have been', been);
  add('Everywhere else', rest);

  if (!selected) {
    select.value = '';
    return;
  }

  select.value = selected;

  // A destination saved as free text, from before this was a picker, or a
  // place this atlas cannot name. Kept rather than silently dropped.
  if (select.value !== selected) {
    const kept = document.createElement('option');
    kept.value = selected;
    kept.textContent = selected;
    select.append(kept);
    select.value = selected;
  }
}

/** What a picked option means: its id, and the name to store beside it. */
const pickedPlace = (select) => {
  const id = select.value;
  if (!id) return { name: null, id: null };

  const place = atlas.find((l) => l.rawId === id);
  return { name: place?.name ?? id, id: place ? id : null };
};

/**
 * The things this install knows how to buy, fetched once.
 *
 * Offered as a picker beside the free-text box rather than instead of it: the
 * box is still the list, and this is a way to put a correctly spelled line in
 * it. Only what can actually be bought is listed, because a line nothing sells
 * is a line no plan can route.
 */
let catalogue = null;

async function fillItemOptions(select) {
  if (!select || select.childElementCount) return;

  const placeholder = document.createElement('option');
  placeholder.value = '';
  placeholder.textContent = 'Add something we know…';
  select.append(placeholder);

  catalogue ??= await getJson('/api/shopping/catalogue').catch(() => ({ commodities: [], items: [] }));

  const add = (label, names) => {
    if (!names?.length) return;

    const group = document.createElement('optgroup');
    group.label = label;

    for (const name of names) {
      const option = document.createElement('option');
      option.value = name;
      option.textContent = name;
      group.append(option);
    }

    select.append(group);
  };

  add('Cargo', catalogue.commodities);
  add('Ship parts and gear', catalogue.items);
}

$('#jobs-new')?.addEventListener('click', () => {
  const form = $('#job-form');
  form.hidden = !form.hidden;
  fillPlaceOptions($('#job-place'), '');
  fillItemOptions($('#job-add'));
  if (!form.hidden) $('#job-title').focus();
});

// Picking a name writes it into the box, where it can be given a quantity like
// any other line. The box stays the list; this only spells things.
$('#job-add')?.addEventListener('change', () => {
  const picked = $('#job-add').value;
  if (!picked) return;

  const box = $('#job-items');
  const lines = box.value.split('\n').filter((l) => l.trim());

  if (!lines.some((l) => l.trim().toLowerCase().startsWith(picked.toLowerCase())))
    lines.push(picked);

  box.value = `${lines.join('\n')}\n`;
  $('#job-add').value = '';
  box.focus();
});

$('#job-cancel')?.addEventListener('click', () => { $('#job-form').hidden = true; });

$('#job-form')?.addEventListener('submit', async (e) => {
  e.preventDefault();

  const items = parseJobItems($('#job-items').value);
  if (!items.length) return;

  const picked = pickedPlace($('#job-place'));

  await fetch('/api/jobs', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      title: $('#job-title').value,
      kind: 'list',
      items,

      // The name is what the card shows; the id is what a plan draws with.
      destination: picked.name,
      destinationId: picked.id,
    }),
  });

  $('#job-title').value = '';
  $('#job-items').value = '';
  $('#job-place').value = '';
  $('#job-form').hidden = true;
  loadJobList();
});

/* ---------- checklists ---------- */

// These are authored preparation, deliberately separate from a shopping list:
// "set a med bed" is useful on Now even though no shop, inventory event or log
// parser can prove it has happened.
let checklists = [];

const checklistDue = (dueAt) => dueAt
  ? new Date(dueAt).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' })
  : '';

async function checklistCall(url, method = 'POST', body = null) {
  await fetch(url, {
    method,
    headers: body ? { 'Content-Type': 'application/json' } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });
  await loadChecklists();
}

function showChecklistAttachment(attachment) {
  if (attachment.kind === 'location') {
    const button = el('button', 'checklist-attachment place-link', `⌖ ${attachment.label}`);
    button.title = 'Show this place on the map';
    button.addEventListener('click', () => briefingMap(attachment.placeId, attachment.target || attachment.label));
    return button;
  }

  if (attachment.kind === 'commodity') {
    const button = el('button', 'checklist-attachment', `◇ ${attachment.label}`);
    button.title = 'Open this commodity';
    button.addEventListener('click', () => openCommodity(attachment.target || attachment.label));
    return button;
  }

  if (attachment.kind === 'item') {
    const button = el('button', 'checklist-attachment', `▦ ${attachment.label}`);
    button.title = 'Find this item in Parts';
    button.addEventListener('click', () => {
      showView('parts');
      $('#parts-search').value = attachment.target || attachment.label;
      renderPartsRef();
    });
    return button;
  }

  if (attachment.kind === 'url' && /^https?:\/\//i.test(attachment.target || '')) {
    const link = el('a', 'checklist-attachment', `↗ ${attachment.label}`);
    link.href = attachment.target;
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    return link;
  }

  return el('span', 'checklist-attachment', `• ${attachment.label}`);
}

function checklistItemRow(list, item, compact = false) {
  // Bought since the line was written. Shown as done rather than ticked in the
  // store: the list belongs to whoever wrote it, and a name matching a receipt
  // is something the logs observed about it, not licence to edit it.
  const bought = !item.done && item.bought;

  const row = el('li',
    `checklist-item${item.done ? ' done' : ''}${bought ? ' bought' : ''}`);
  const check = document.createElement('input');
  check.type = 'checkbox';
  check.checked = item.done;
  check.title = item.done ? 'Reopen task' : 'Mark task done';
  check.addEventListener('change', () => checklistCall(`/api/checklists/${list.id}/items/${item.id}/toggle`));
  row.append(check);

  const main = el('div', 'checklist-item-main');
  main.append(el('div', 'checklist-item-text', item.text));
  if (!compact && item.note) main.append(el('div', 'muted checklist-note', item.note));
  if (item.dueAt) main.append(el('div', 'checklist-due', `◷ ${checklistDue(item.dueAt)}`));

  if (bought) {
    const note = el('div', 'checklist-bought', `bought ${dayOf(item.bought)}`);
    note.title = 'Your logs show this was bought after you wrote this line. '
      + 'Tick it to take it off for good.';
    main.append(note);
  }

  const attachments = item.attachments || [];
  if (attachments.length) {
    const links = el('div', 'checklist-attachments');
    for (const attachment of attachments) links.append(showChecklistAttachment(attachment));
    main.append(links);
  }
  row.append(main);

  if (!compact) {
    const remove = el('button', 'ghost tiny', '×');
    remove.title = 'Remove task';
    remove.addEventListener('click', () => checklistCall(`/api/checklists/${list.id}/items/${item.id}`, 'DELETE'));
    row.append(remove);
  }
  return row;
}

function renderPinnedChecklist(lists = checklists) {
  const card = $('#now-checklist-card');

  // Imported rows arrive with pinned forced false, so this cannot pick one up -
  // but Now is the one card where being wrong would be loudest, so it says so.
  const list = lists.find((entry) => entry.pinned && !entry.imported);
  if (!card) return;

  if (!list) {
    card.hidden = true;
    return;
  }

  $('#now-checklist-title').textContent = list.title;
  const done = list.items.filter((item) => item.done).length;
  const progress = $('#now-checklist-progress');
  progress.textContent = '';
  progress.append(jobProgress(done, list.items.length, `${done} of ${list.items.length} done`));

  const host = $('#now-checklist-items');
  host.textContent = '';
  const open = list.items.filter((item) => !item.done);
  for (const item of open.slice(0, 5)) host.append(checklistItemRow(list, item, true));
  if (open.length > 5) host.append(el('li', 'muted', `+${open.length - 5} more`));
  if (!open.length) host.append(el('li', 'inward', 'Everything is checked off.'));

  $('#now-checklist-open').onclick = () => showView('checklists');
  card.hidden = false;
}

function checklistComposer(list) {
  const form = el('form', 'checklist-composer');
  const task = document.createElement('input');
  task.type = 'text';
  task.placeholder = 'Add a task, e.g. bring tractor beam';
  task.required = true;
  form.append(task);

  const fields = el('div', 'checklist-fields');
  const place = document.createElement('select');
  place.className = 'select';
  place.title = 'Optional map location';
  fillPlaceOptions(place, '');
  fields.append(place);

  const item = document.createElement('input');
  item.type = 'search';
  item.className = 'search';
  item.setAttribute('list', 'checklist-catalogue');
  item.placeholder = 'Optional commodity, part or gear';
  item.title = 'Optional commodity, part or gear reference';
  fields.append(item);
  fillChecklistReferenceOptions();

  const due = document.createElement('input');
  due.type = 'datetime-local';
  due.className = 'search';
  due.title = 'Optional date and time';
  fields.append(due);
  form.append(fields);

  const detail = el('div', 'checklist-fields');
  const note = document.createElement('input');
  note.type = 'text';
  note.className = 'search';
  note.placeholder = 'Optional note';
  detail.append(note);
  const url = document.createElement('input');
  url.type = 'url';
  url.className = 'search';
  url.placeholder = 'Optional https:// link';
  detail.append(url);
  form.append(detail);

  const add = el('button', 'ghost', 'Add task');
  form.append(add);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const where = pickedPlace(place);
    const attachments = [];
    if (where.name) attachments.push({ kind: 'location', label: where.name, target: where.name, placeId: where.id });
    const reference = item.value.trim();
    if (reference) {
      // The catalogue is filled lazily, so submitting before it lands would
      // decide "not a commodity" from an empty list and file a real commodity
      // as an item - which sends the attachment into the Parts search.
      await fillChecklistReferenceOptions();
      const commodity = catalogue?.commodities?.includes(reference);
      attachments.push({ kind: commodity ? 'commodity' : 'item', label: reference, target: reference });
    }
    if (url.value.trim()) attachments.push({ kind: 'url', label: url.value.trim(), target: url.value.trim() });

    add.disabled = true;
    try {
      await checklistCall(`/api/checklists/${list.id}/items`, 'POST', {
        text: task.value,
        dueAt: due.value ? new Date(due.value).toISOString() : null,
        note: note.value,
        attachments,
      });
    } finally {
      // A success re-renders this form away, but a failed request leaves it on
      // screen - and without this, with a button that never comes back.
      add.disabled = false;
    }
  });
  return form;
}

let catalogueFill = null;

/** One shared searchable catalogue: duplicating thousands of options per list makes adding a task sluggish. */
function fillChecklistReferenceOptions() {
  const list = $('#checklist-catalogue');
  if (!list || list.childElementCount) return Promise.resolve();

  // The guard above cannot do this alone. renderChecklists starts one of these
  // per list without awaiting, so with three lists all three would pass an
  // empty datalist and each append the whole catalogue. Share the one fill,
  // and let a later composer retry the fetch if nothing landed.
  catalogueFill ??= (async () => {
    // A failed fetch is not cached as an empty catalogue: this is the one
    // caller that can be asked again, so let the next composer retry.
    const loaded = catalogue ?? await getJson('/api/shopping/catalogue').catch(() => null);
    if (!loaded) {
      catalogueFill = null;
      return;
    }

    catalogue = loaded;
    for (const name of [...(catalogue.commodities || []), ...(catalogue.items || [])]) {
      const option = document.createElement('option');
      option.value = name;
      list.append(option);
    }
  })();

  return catalogueFill;
}

function renderChecklists(lists) {
  const host = $('#checklists-list');
  if (!host) return;
  host.textContent = '';

  if (!lists.length) {
    host.append(el('p', 'muted', 'No checklists yet. Make one for a departure, an operation, or anything you do not want to forget.'));
    return;
  }

  for (const list of lists) {
    const card = el('article', 'checklist-card');
    const head = el('div', 'job-head');
    head.append(el('b', null, list.title));
    if (list.pinned) head.append(el('span', 'job-kind owned', 'on Now'));
    head.append(el('span', 'spacer'));

    const pin = el('button', list.pinned ? 'ghost on' : 'ghost', list.pinned ? 'On Now' : 'Pin to Now');
    pin.title = 'Only one checklist is shown on Now and in the overlay';
    pin.addEventListener('click', () => checklistCall(`/api/checklists/${list.id}/pin`));
    head.append(pin);
    const remove = el('button', 'ghost danger', 'Delete');
    remove.addEventListener('click', () => checklistCall(`/api/checklists/${list.id}`, 'DELETE'));
    head.append(remove);
    card.append(head);

    const done = list.items.filter((item) => item.done).length;
    card.append(jobProgress(done, list.items.length, `${done} of ${list.items.length} done`));
    const items = el('ul', 'checklist-items');
    for (const entry of list.items) items.append(checklistItemRow(list, entry));
    if (!list.items.length) items.append(el('li', 'muted', 'No tasks yet — add the first thing you want to remember.'));
    card.append(items, checklistComposer(list));
    host.append(card);
  }
}

async function loadChecklists() {
  checklists = await getJson(`/api/checklists${importedQuery()}`).catch(() => []);
  renderChecklists(checklists);
  renderPinnedChecklist(checklists);
}

$('#checklist-create')?.addEventListener('click', async () => {
  const title = $('#checklist-title');
  if (!title.value.trim()) {
    title.focus();
    return;
  }
  await checklistCall('/api/checklists', 'POST', { title: title.value });
  title.value = '';
});

/* ---------- StarStrings ---------- */

/**
 * MrKraken's text mod, installed on request.
 *
 * Kept at arm's length on purpose. This app is read-only everywhere else, and
 * this one card writes into somebody's game install, so the page says exactly
 * which two files it writes, offers to take them back out, and never touches
 * anything without a click. The state it shows is what is on disk rather than
 * what we once did: a game patch can drop the localisation file back without
 * telling anyone, and "installed" has to mean the files are still there.
 */
async function loadStarStrings(check = false) {
  const status = $('#starstrings-status');
  if (!status) return;

  const state = await getJson(`/api/starstrings${check ? '?check=true' : ''}`).catch(() => null);

  if (!state) {
    status.textContent = 'Could not read the install state.';
    return;
  }

  $('#starstrings-remove').hidden = !state.installed;
  $('#starstrings-install').textContent = state.installed ? 'Reinstall' : 'Install';

  const bits = [];

  if (state.installed) {
    bits.push(`Installed: ${state.release || 'unknown build'}`);
    if (state.installedAt) bits.push(`put in place ${relative(state.installedAt)}`);
  } else if (state.displaced) {
    bits.push('Installed by this app, but the files are gone — a game patch will do that. Install again to put it back.');
  } else {
    bits.push('Not installed.');
  }

  if (state.latest) {
    bits.push(state.newer
      ? `A newer build is out: ${state.latest.name}. Install to take it.`
      : `Newest build: ${state.latest.name}${state.installed ? ' — you have it' : ''}`);
  }

  if (!state.gameRoot) bits.push('No game folder found, so there is nowhere to install it.');

  status.textContent = bits.join(' · ');
  $('#starstrings-install').disabled = !state.gameRoot;
}

/**
 * What marking the game's text would change, and the state of the one that is
 * installed.
 *
 * Shows the plan before anything is written, because the file lands in someone
 * else's game folder: the counts, where the text is being built from, and a
 * sample of the actual renames. The caveat is permanent rather than shown on a
 * short list - a tidy table of names is exactly what gets mistaken for a
 * complete rarity rating, and this is a floor over two incomplete sources.
 */
/**
 * Puts the stored marking choices onto the page.
 *
 * The level only matters while colour is on, so it is disabled rather than
 * hidden when it is off - a control that vanishes reads as a bug, and one that
 * greys out reads as a consequence.
 */
function applyLabelOptions(options) {
  const facts = $('#label-facts');
  const colour = $('#label-colour');
  const level = $('#label-level');
  if (!facts || !colour || !level) return;

  facts.checked = options ? options.facts !== false : true;
  colour.checked = !!(options && options.colour);
  level.value = String((options && options.level) || 3);
  level.disabled = !colour.checked;
}

/** Stores a marking choice, and says what it does not do. */
async function saveLabelOptions() {
  const body = {
    colour: $('#label-colour').checked,
    level: Number($('#label-level').value) || 3,
    facts: $('#label-facts').checked,
  };

  $('#label-level').disabled = !body.colour;

  await fetch('/api/labels/options', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  }).catch(() => {});

  // Changing a mark does not touch the game folder. Saying so is the difference
  // between a preference and a surprise.
  const note = $('#label-options-note');
  if (note) {
    note.textContent = 'Saved. Install again to write it into the game, then restart the game.';
    note.hidden = false;
  }

  await loadTextOverlay().catch(() => {});
}

for (const id of ['#label-facts', '#label-colour', '#label-level']) {
  $(id)?.addEventListener('change', () => { saveLabelOptions().catch(() => {}); });
}

async function loadTextOverlay() {
  const status = $('#textoverlay-status');
  if (!status) return;

  const state = await getJson('/api/labels').catch(() => null);

  if (!state) {
    status.textContent = 'Could not read the game text.';
    return;
  }

  applyLabelOptions(state.options);

  $('#textoverlay-remove').hidden = !state.installed;
  $('#textoverlay-install').textContent = state.installed ? 'Rebuild and install' : 'Install';
  $('#textoverlay-install').disabled = !!state.problem;

  if (state.problem) {
    status.textContent = state.problem;
    tiles('#textoverlay-summary', []);
    $('#textoverlay-table tbody').textContent = '';
    return;
  }

  tiles('#textoverlay-summary', [
    ['Would be marked', state.marked],
    ['Something sells', state.sold],
    ['Size or class marked', state.annotated],
    ['Not gear you shop for', state.skipped],
  ]);

  // Which file it builds on decides whether another mod survives, so it is
  // stated rather than assumed.
  $('#textoverlay-source').textContent = state.baseSource === 'StarStrings'
    ? 'Built on top of the StarStrings text, so both survive.'
    : "Built on the game's own text.";

  labelChanges = state.changes || [];
  renderLabelChanges();

  const bits = [];
  if (state.installed) {
    bits.push(`Installed${state.installedAt ? ` ${relative(state.installedAt)}` : ''}`);
    if (state.layered) bits.push('layered over StarStrings');
    bits.push('restart Star Citizen to see it');
  } else {
    bits.push('Nothing is written until you install.');
  }

  status.textContent = bits.join(' · ');
}

/* Kept so typing in the box re-renders without asking the server to rebuild the
   whole localisation file again. */
let labelChanges = [];

/** The table is thousands of rows; rendering caps so typing stays quick. */
const LABELS_CAP = 400;

/**
 * The rows a search term matches.
 *
 * Searched across all three columns, because all three are things somebody
 * would look for: the name they are holding, the kind of thing it is, and the
 * mark itself - "[S2B]" or "[*]" - which is how you answer "what does the star
 * actually get put on?" without reading four thousand rows.
 */
function matchingLabelChanges(term) {
  const wanted = (term || '').trim().toLowerCase();
  if (!wanted) return labelChanges;

  return labelChanges.filter((line) =>
    line.was.toLowerCase().includes(wanted)
    || line.becomes.toLowerCase().includes(wanted)
    || (line.category || '').toLowerCase().includes(wanted));
}

function renderLabelChanges() {
  const body = $('#textoverlay-table tbody');
  if (!body) return;

  const term = $('#labels-search')?.value || '';
  const rows = matchingLabelChanges(term);

  body.textContent = '';

  for (const line of rows.slice(0, LABELS_CAP)) {
    const tr = el('tr');
    tr.append(el('td', null, line.was));
    tr.append(el('td', 'muted', line.category));
    tr.append(el('td', null, line.becomes));
    body.append(tr);
  }

  const counter = $('#labels-count');
  if (!counter) return;

  if (labelChanges.length === 0) {
    counter.textContent = '';
    return;
  }

  // The total is what the page is answering for, so it is always said - a bare
  // "400 rows" would read as the whole plan when it is a tenth of it.
  if (rows.length === 0) {
    counter.textContent = `Nothing matches "${term.trim()}" among ${labelChanges.length.toLocaleString()} renames.`;
  } else if (rows.length > LABELS_CAP) {
    counter.textContent =
      `Showing ${LABELS_CAP} of ${rows.length.toLocaleString()} matches, `
      + `out of ${labelChanges.length.toLocaleString()} renames — narrow the search to see the rest.`;
  } else if (term.trim()) {
    counter.textContent =
      `${rows.length.toLocaleString()} of ${labelChanges.length.toLocaleString()} renames match.`;
  } else {
    counter.textContent = `${labelChanges.length.toLocaleString()} renames.`;
  }
}

function initTextOverlay() {
  const install = $('#textoverlay-install');
  if (!install) return;

  onInput('#labels-search', renderLabelChanges);

  install.addEventListener('click', async () => {
    $('#textoverlay-status').textContent = 'Writing…';

    const answer = await fetch('/api/labels/install', { method: 'POST' })
      .then((r) => r.json())
      .catch(() => ({ problem: 'The write did not finish.' }));

    if (answer.problem) {
      $('#textoverlay-status').textContent = answer.problem;
      return;
    }

    await loadTextOverlay();
    alertLine($('#textoverlay-status').parentElement, 'Installed. Restart Star Citizen to see it.');
  });

  $('#textoverlay-remove').addEventListener('click', async () => {
    $('#textoverlay-status').textContent = 'Putting the old text back…';
    // A removal that could not put the old file back leaves the marks installed,
    // so saying "removed" would be a lie the page then contradicts on reload.
    const answer = await fetch('/api/labels/remove', { method: 'POST' })
      .then((r) => r.json())
      .catch(() => ({ problem: 'The removal could not be started.' }));

    if (answer.problem) $('#textoverlay-status').textContent = answer.problem;

    await loadTextOverlay();
  });
}

function initStarStrings() {
  const install = $('#starstrings-install');
  if (!install) return;

  $('#starstrings-check').addEventListener('click', async () => {
    $('#starstrings-status').textContent = 'Asking GitHub…';
    await loadStarStrings(true);
  });

  install.addEventListener('click', async () => {
    install.disabled = true;
    $('#starstrings-status').textContent = 'Downloading and writing…';

    const answer = await fetch('/api/starstrings/install', { method: 'POST' })
      .then((r) => r.json())
      .catch(() => ({ problem: 'The install could not be started.' }));

    install.disabled = false;

    if (answer.problem) {
      $('#starstrings-status').textContent = answer.problem;
      return;
    }

    await loadStarStrings(true);
    await loadTextOverlay().catch(() => {});

    // Both write the same file, so the marks are laid over StarStrings' table
    // again rather than being quietly lost under it. Stated on a line that
    // stays, not a notice that fades: a second thing changing on one click is
    // exactly what somebody will want to re-read.
    const note = $('#starstrings-note');
    note.textContent = answer.relabelled
      ? 'Installed, and your item labels were put back on top of it. '
        + 'Restart Star Citizen to see them.'
      : 'Installed. Restart Star Citizen to see it.';
    note.hidden = false;
  });

  $('#starstrings-remove').addEventListener('click', async () => {
    await fetch('/api/starstrings/remove', { method: 'POST' }).catch(() => {});
    await loadStarStrings();
  });

  loadStarStrings();
}

/* ---------- logbook ---------- */


/**
 * The logbook page: one merged timeline of what the pilot actually did -
 * sessions, trades, purchases, first-seen loot - straight from /api/logbook.
 */
async function loadLogbook() {
  const days = Number($('#logbook-period').value) || 0;
  const rows = await getJson(`/api/logbook?days=${days}`);

  const feed = $('#logbook-feed');
  feed.textContent = '';

  if (!rows.length) {
    feed.append(el('li', 'empty', 'Nothing in that range.'));
    return;
  }

  for (const row of rows) {
    const li = el('li');

    const when = new Date(row.at);
    const stamp = `${dateOf(row.at)} · ${when.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;
    li.append(el('span', 't', stamp));

    li.append(el('span', `k ${row.kind}`, row.kind));

    // Item-ish lines pretty their class names; a session line is prose.
    const text = row.kind === 'session' ? row.what : prettyItem(row.what);
    li.append(el('span', 'd what', text));

    if (row.place) {
      const place = el('span', 'd');
      place.append(placeLink(row.place));
      li.append(place);
    }

    if (row.detail) li.append(el('span', 'd detail', row.detail));

    if (row.amount != null && row.amount !== 0) {
      const inward = Number(row.amount) > 0;
      li.append(el('span', `amt ${inward ? 'inward' : 'outward'}`,
        `${inward ? '+' : '−'}${money(Math.abs(row.amount))}`));
    }

    feed.append(li);
  }
}

onInput('#logbook-period', loadLogbook);

/* ---------- assets ---------- */

let assetsData = null;

/**
 * Ships struck off the asset count. The fleet is inferred from the logs, so
 * rentals and ships since sold appear in it; which of those the player truly
 * owns is something only they know, so it is their tick-box, kept per-browser.
 */
let excludedShips = new Set();
try {
  excludedShips = new Set(JSON.parse(localStorage.getItem('qw-assets-excluded') || '[]'));
} catch { /* private mode; exclusions just will not stick */ }

/** A personal short-list, independent of the roster tick and kept in this browser. */
let favouriteShips = new Set();
try {
  favouriteShips = new Set(JSON.parse(localStorage.getItem('qw-favourite-ships') || '[]'));
} catch { /* private mode; favourites just will not stick */ }

// A comparison is deliberately temporary: it is a way to reach a useful
// Hangar view, not another roster the pilot has to maintain.
let hangarComparison = new Set();
const RECENTLY_FLOWN_MS = 7 * 24 * 60 * 60 * 1000;
let hangarPreviewShips = null;

function isRecentlyFlown(ship) {
  return Date.now() - new Date(ship.lastFlown).getTime() <= RECENTLY_FLOWN_MS;
}

async function loadAssets() {
  assetsData = await getJson('/api/assets');
  renderAssets();

  // Prices arrive after the roster first renders; redraw it with them in.
  if (libraryStats) renderFleet(libraryStats);
}

/**
 * The asset side of the blended Fleet page: the "other assets" strip and the
 * stash table. The roster and fleet value live in renderFleet/renderFleetShips.
 */
function renderAssets() {
  const assets = assetsData;
  if (!assets) return;

  // Totals are recomputed here rather than trusted from the server, because
  // exclusion is a client-side choice.
  const counted = assets.fleet.filter((s) => !excludedShips.has(s.name));
  const fleetValue = counted.reduce((sum, s) => sum + (s.price ? Number(s.price.price) : 0), 0);

  const total = fleetValue + Number(assets.loadoutValue) + Number(assets.stashValue);

  tiles('#assets-summary', assets.priced
    ? [
        ['Estimated worth*', money(total)],
        ['Kit worn', `${money(assets.loadoutValue)} (${assets.loadoutPriced}/${assets.loadoutItems})`],
        ['Stashed', money(assets.stashValue)],
        ['Claim exposure*', money(assets.claimExposure)],
      ]
    : [['Estimated worth', 'needs Settings → community dataset + UEX']]);

  const stashBody = $('#assets-stash tbody');
  stashBody.textContent = '';

  for (const s of [...assets.stash].sort((a, b) => b.value - a.value)) {
    const tr = el('tr');
    tr.append(tdPlace(s.location));
    tr.append(el('td', 'num', String(s.items)));
    tr.append(el('td', 'num muted', String(s.priced)));
    tr.append(el('td', 'num inward', s.value > 0 ? money(s.value) : '—'));
    stashBody.append(tr);
  }
}

/* ---------- settings ---------- */

/**
 * The Settings page: the overlay switch, the community dataset, the cache.
 * Everything here re-reads its state from the server on every render, so the
 * page cannot disagree with the tray menu or another browser tab for long.
 */
async function renderSettings() {
  // Overlay - only offered when the server is hosted inside QuantumWake.exe.
  try {
    const overlay = await getJson('/api/overlay');
    const toggle = $('#overlay-toggle');

    toggle.hidden = !overlay.available;
    $('#overlay-unavailable').hidden = overlay.available;
    $('#overlay-copy').hidden = !overlay.available;

    if (overlay.available) {
      toggle.textContent = overlay.visible ? 'Overlay is on — hide it' : 'Show the overlay';
      toggle.classList.toggle('on', overlay.visible);
      toggle.dataset.visible = String(overlay.visible);
    }
  } catch { /* server unreachable; the page will retry on next visit */ }

  // Community dataset.
  try {
    const community = await getJson('/api/community');

    $('#settings-community-enable').hidden = community.enabled;
    $('#settings-community-refresh').hidden = !community.enabled;
    $('#settings-community-disable').hidden = !community.enabled;

    // The dump it was made from, not only the day it was fetched: a fetch date
    // says when this machine asked, which is not how old the data is - the dump
    // for a patch lands days after the patch does.
    $('#settings-community-status').textContent = community.enabled
      ? [`${community.commodities} commodities`,
         community.dump ? `dumped for ${community.dump}` : 'dump unknown',
         `fetched ${community.fetchedAt ? dateOf(community.fetchedAt) : '—'}`].join(' · ')
      : 'not downloaded';

    const behind = $('#settings-community-behind');
    behind.hidden = !community.behind;

    if (community.behind) {
      behind.textContent = `Your logs are on build ${community.playing}, and this data was made`
        + ` from ${community.dump}. Anything that patch added — ships, items,`
        + ' commodities — has no name here until you refresh.';
    }
  } catch { /* as above */ }

  // UEX.
  try {
    const uex = await getJson('/api/uex');

    $('#uex-enable').hidden = uex.enabled;
    $('#uex-refresh').hidden = !uex.enabled;
    $('#uex-disable').hidden = !uex.enabled;

    $('#uex-status').textContent = uex.enabled
      ? `${uex.prices} commodities priced, fetched ${uex.fetchedAt ? dateOf(uex.fetchedAt) : '—'}`
      : 'not fetched';

    $('#uex-preview').hidden = !(uex.enabled && uex.hasCredentials);
    $('#uex-save-creds').textContent = uex.hasCredentials ? 'Replace keys' : 'Save keys';
  } catch { /* as above */ }

  await renderUexAuto();
  await renderUexFeeds();
  await renderSignals();
  await renderExportPreview();
  await renderBackupPreview();
  await renderDiagnostics();
  await renderDiagnosticTrace();
}

/* ---------- files other pilots have shared ---------- */

let importBatches = [];

/**
 * Whether pages show imported rows beside the reader's own, and whose.
 *
 * One switch for the whole app rather than one per page: the question somebody
 * asks is "am I looking at Bob's things or mine", never "am I looking at Bob's
 * jobs but my own checklists". Off by default, because importing a friend's
 * forty jobs and finding your own page now has forty-three cards on it is an
 * ambush by a feature used once.
 */
let showImported = 'none';

try {
  showImported = localStorage.getItem('qw-show-imported') || 'none';
} catch { /* private browsing; the default is the safe one anyway */ }

/**
 * The suffix every list endpoint takes, so no page has to remember the name.
 *
 * Empty when nothing is being shown, which is the ordinary case: the request
 * then goes out exactly as it did before this feature existed, and the server
 * default and the client default cannot drift apart.
 */
function importedQuery() {
  return showImported === 'none' ? '' : `?imported=${encodeURIComponent(showImported)}`;
}

function setShowImported(value) {
  showImported = value || 'none';

  try {
    localStorage.setItem('qw-show-imported', showImported);
  } catch { /* as above */ }

  // Everything that can carry an imported row re-reads itself.
  loadJobs().catch(() => {});
  loadChecklists().catch(() => {});
  loadTrips?.().catch(() => {});
  renderSharedReceipts().catch(() => {});
  renderSharedBlueprints().catch(() => {});
  renderSharedPoints().catch(() => {});
}

/**
 * The control that turns other people's rows on.
 *
 * Drawn only when there is something to show. An empty dropdown offering to
 * filter by nobody is a worse answer than no dropdown.
 */
function renderImportedFilter() {
  const host = $('#imports-filter');
  if (!host) return;

  host.textContent = '';

  const usable = importBatches.filter((b) => b.readable && !b.hidden && b.classes.length);
  if (!usable.length) return;

  host.append(el('label', 'muted', 'Show shared rows on my pages: '));

  const select = el('select', 'select');
  const options = [['none', 'no'], ['all', 'from everyone']];
  for (const batch of usable) options.push([batch.id, `only ${batch.handle || batch.sourceName}`]);

  for (const [value, label] of options) {
    const option = document.createElement('option');
    option.value = value;
    option.textContent = label;
    select.append(option);
  }

  select.value = options.some(([v]) => v === showImported) ? showImported : 'none';
  select.addEventListener('change', () => setShowImported(select.value));
  host.append(select);
}

/** A tally, with the zeroes left out. */
function countLine(counts) {
  const parts = [];
  if (counts.receipts) parts.push(`${counts.receipts.toLocaleString()} trades`);
  if (counts.blueprints) parts.push(`${counts.blueprints} blueprints`);
  if (counts.jobs) parts.push(`${counts.jobs} jobs`);
  if (counts.checklists) parts.push(`${counts.checklists} checklists`);
  if (counts.trips) parts.push(`${counts.trips} flight plans`);
  if (counts.runActions) parts.push(`${counts.runActions} run-sheet lines`);
  if (counts.points) parts.push(`${counts.points} point${counts.points === 1 ? '' : 's'} of interest`);
  return parts.join(' · ');
}

/**
 * One imported file.
 *
 * Says when it was written as well as when it was imported, because a file
 * taken this morning can hold a price from March and the older date is the one
 * that decides whether the numbers are worth anything.
 */
function importCard(batch) {
  const card = el('article', 'import-card');

  const head = el('div', 'job-head');
  head.append(el('b', null, batch.handle || 'Someone'));
  if (batch.note) head.append(el('span', 'job-kind', batch.note));
  if (!batch.readable) head.append(el('span', 'job-kind danger', 'cannot be read'));
  if (batch.hidden) head.append(el('span', 'job-kind', 'hidden'));
  head.append(el('span', 'spacer'));

  const hide = el('button', 'ghost tiny', batch.hidden ? 'Show' : 'Hide');
  hide.title = 'Hiding keeps the file. Removing does not.';
  hide.addEventListener('click', () => importCall(`/api/imports/${batch.id}/hide`));
  head.append(hide);

  const remove = el('button', 'ghost danger tiny', 'Remove');
  remove.title = 'Takes this file away completely. Your own work is not touched.';
  remove.addEventListener('click', () => importCall(`/api/imports/${batch.id}`, 'DELETE'));
  head.append(remove);
  card.append(head);

  card.append(el('div', 'muted', `${batch.sourceName} — imported ${dateOf(batch.importedAt)}, `
    + `written ${dateOf(batch.exportedAt)} by Quantum Wake ${batch.producerVersion}`));

  const held = countLine(batch.counts);
  card.append(el('div', 'import-counts', held || 'Nothing left in this file.'));

  // Kept for ever and said plainly: "why does this show 41 when his file said
  // 43" has to be answerable a month later.
  const dropped = countLine(batch.rejected);
  if (dropped) card.append(el('div', 'muted', `Could not be read: ${dropped}.`));

  const cut = countLine(batch.truncated);
  if (cut) card.append(el('div', 'muted', `Too many to keep, so left out: ${cut}.`));

  if (!batch.readable) {
    card.append(el('div', 'muted', `This file is in format ${batch.formatVersion}, which this `
      + 'build does not read. It is kept rather than dropped, since the copy you were sent may '
      + 'be the only one. Update Quantum Wake, or remove it.'));
  }

  if (batch.classes.length) {
    const row = el('div', 'import-classes');
    const named = [['receipts', 'trades'], ['blueprints', 'blueprints'], ['authored', 'jobs and lists'], ['points', 'points of interest']];

    for (const [key, label] of named) {
      if (!batch.classes.includes(key)) continue;
      const drop = el('button', 'ghost tiny', `Remove the ${label}`);
      drop.addEventListener('click', () => importCall(`/api/imports/${batch.id}/${key}`, 'DELETE'));
      row.append(drop);
    }

    card.append(row);
  }

  return card;
}

function renderImports(payload) {
  const host = $('#imports-list');
  if (!host) return;

  importBatches = payload.batches || [];
  host.textContent = '';

  if (payload.quarantined) {
    host.append(el('p', 'muted', 'An earlier imports file could not be read. It was kept as '
      + `${payload.quarantined} rather than overwritten, because the files it held came from `
      + 'other people.'));
  }

  if (!importBatches.length) {
    host.append(el('p', 'muted', 'No shared files yet. Open one a friend sent you — it stays '
      + 'separate from your own history, and you can remove it whenever you like.'));
    return;
  }

  for (const batch of importBatches) host.append(importCard(batch));
  renderImportedFilter();
}

async function loadImports() {
  renderImports(await getJson('/api/imports').catch(() => ({ batches: [] })));
}

async function importCall(url, method = 'POST') {
  try {
    await fetch(url, { method });
  } finally {
    await loadImports();
  }
}

/**
 * Reads a file the user picked and offers it to the server.
 *
 * The text travels in a JSON body rather than as multipart: nothing else here
 * posts multipart, FileReader hands back the string for nothing, and the size
 * check stays one question about how many bytes arrived.
 */
async function importFile(file) {
  $('#imports-status').textContent = `Reading ${file.name}…`;

  const text = await new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = (event) => resolve(event.target.result);
    reader.readAsText(file);
  });

  await sendImport(text, file.name, false);
}

async function sendImport(text, sourceName, force) {
  const status = $('#imports-status');

  const response = await fetch(`/api/imports${force ? '?force=true' : ''}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ document: text, sourceName }),
  });

  const answer = await response.json().catch(() => null);

  // Already held. Asked rather than duplicated, because a double-clicked picker
  // and a deliberate re-import after a purge look identical from here.
  if (response.status === 409 && answer && answer.batch) {
    const already = answer.batch;
    status.textContent = `You imported this on ${dateOf(already.importedAt)} — `
      + `${countLine(already.counts) || 'nothing left in it'}. `;

    const again = el('button', 'ghost tiny', 'Import it again anyway');
    again.addEventListener('click', () => sendImport(text, sourceName, true).catch(() => {}));
    status.append(again);
    return;
  }

  if (!response.ok) {
    status.textContent = (answer && answer.message) || 'That file could not be read.';
    return;
  }

  status.textContent = `Imported ${countLine(answer.batch.counts) || 'nothing'} from `
    + `${answer.batch.handle || 'someone'}.`;

  await loadImports();
}

$('#imports-pick')?.addEventListener('click', () => $('#imports-file')?.click());

$('#imports-file')?.addEventListener('change', (event) => {
  const file = event.target.files && event.target.files[0];
  if (!file) return;

  importFile(file)
    .catch(() => { $('#imports-status').textContent = 'That file could not be read.'; })
    // Cleared so that picking the same file twice still fires a change.
    .finally(() => { event.target.value = ''; });
});

$('#imports-clear')?.addEventListener('click', () => {
  $('#imports-status').textContent = '';
  importCall('/api/imports', 'DELETE').catch(() => {});
});

/**
 * Trades and blueprints from other people's files, in their own sections.
 *
 * Kept out of the pages' own payloads on purpose. Cargo computes four totals
 * from /api/commodities and the Blueprints picker feeds "Set as goal" from
 * /api/blueprints/owned; mixing imported rows into either would mean
 * remembering to filter in five places, and the one that gets forgotten
 * produces lifetime earnings counting somebody else's sales, or a build plan
 * for a blueprint the reader does not hold.
 */
async function renderSharedReceipts() {
  const host = $('#cargo-shared');
  if (!host) return;

  host.textContent = '';
  if (showImported === 'none') return;

  const rows = await getJson(`/api/imports/receipts${importedQuery()}`).catch(() => []);
  if (!rows.length) return;

  const card = el('section', 'shared-block');
  card.append(el('h3', null, 'Trades from shared files'));
  card.append(el('p', 'muted', 'Other people’s receipts, kept out of your own totals '
    + 'above. Prices are what they were quoted, where and when they say.'));

  const table = el('table', 'data');
  const head = el('thead');
  const headRow = el('tr');
  for (const label of ['When', 'Who', 'Commodity', 'Place', 'SCU', 'Per SCU']) {
    headRow.append(el('th', label === 'SCU' || label === 'Per SCU' ? 'num' : null, label));
  }
  head.append(headRow);
  table.append(head);

  const body = el('tbody');

  for (const row of rows.slice(0, 200)) {
    const tr = el('tr');
    tr.append(el('td', 'muted', dateOf(row.at)));
    tr.append(el('td', null, row.imported.handle || 'someone'));

    // A name this install cannot resolve is not an error: their dataset knew
    // something ours does not, or the other way round.
    tr.append(el('td', row.commodity ? null : 'muted', row.commodity || 'unnamed'));
    tr.append(el('td', 'muted', row.place));
    tr.append(el('td', 'num', row.scu.toLocaleString()));
    tr.append(el('td', 'num', money(row.unitPrice)));
    body.append(tr);
  }

  table.append(body);
  card.append(table);

  if (rows.length > 200) {
    card.append(el('p', 'muted', `Showing the newest 200 of ${rows.length.toLocaleString()}.`));
  }

  host.append(card);
}

async function renderSharedBlueprints() {
  const host = $('#blueprints-shared');
  if (!host) return;

  host.textContent = '';
  if (showImported === 'none') return;

  const rows = await getJson(`/api/imports/blueprints${importedQuery()}`).catch(() => []);
  if (!rows.length) return;

  const card = el('section', 'shared-block');
  card.append(el('h3', null, 'Held by others'));
  card.append(el('p', 'muted', 'Blueprints the files you have been sent say somebody holds. '
    + 'They are not in the picker above, because you cannot craft from someone else’s '
    + 'library — this answers who to ask.'));

  const list = el('ul', 'shared-blueprints');

  // Grouped by name, so "who can craft this" is one line rather than a list to
  // read across. That is the question the section exists to answer.
  const byName = new Map();

  for (const row of rows) {
    const holders = byName.get(row.name) || [];
    const who = row.imported.handle || 'someone';
    if (!holders.includes(who)) holders.push(who);
    byName.set(row.name, holders);
  }

  for (const [name, holders] of [...byName.entries()].sort((a, b) => a[0].localeCompare(b[0]))) {
    const line = el('li');
    line.append(el('b', null, name));
    line.append(el('span', 'muted', ` — ${holders.join(', ')}`));
    list.append(line);
  }

  card.append(list);
  host.append(card);
}

/* ---------- sharing a file of your own ---------- */

/**
 * The chosen window in days, where zero legitimately means all time.
 *
 * Read carefully because the two failure values are far apart: an empty select
 * through Number() is zero, which would quietly turn "the last week" into every
 * trade ever made and send a hundred times what was asked for.
 */
function exportDays() {
  // Empty string through Number() is zero, not NaN, so the absent case has to
  // be caught before the conversion rather than after it.
  const raw = $('#export-days')?.value;
  if (raw === undefined || raw === null || raw === '') return 7;

  const chosen = Number(raw);
  return Number.isFinite(chosen) && chosen >= 0 ? chosen : 7;
}

/** What the boxes currently say, in the shape the API takes. */
function exportChoice() {
  return {
    receipts: Boolean($('#export-receipts')?.checked),
    blueprints: Boolean($('#export-blueprints')?.checked),
    authored: Boolean($('#export-authored')?.checked),
    points: Boolean($('#export-points')?.checked),
    handle: Boolean($('#export-handle')?.checked),
    days: exportDays(),
  };
}

/**
 * What would go, before it goes.
 *
 * Counts only - the preview endpoint never returns rows. The point is that a
 * click to share follows seeing what sharing means, not that the page gets a
 * second copy of the data.
 */
async function renderExportPreview() {
  const line = $('#export-preview');
  if (!line) return;

  const choice = exportChoice();

  if (!choice.receipts && !choice.blueprints && !choice.authored && !choice.points) {
    line.textContent = 'Nothing ticked, so there is nothing to save.';
    return;
  }

  try {
    const counts = await getJson(
      `/api/export/preview?receipts=${choice.receipts}&blueprints=${choice.blueprints}`
      + `&authored=${choice.authored}&points=${choice.points}&days=${choice.days}`);

    const parts = [];
    if (choice.receipts) {
      parts.push(`${counts.receipts.toLocaleString()} ${counts.receipts === 1 ? 'trade' : 'trades'}`
        + (choice.days ? ` from the last ${choice.days === 1 ? 'day' : `${choice.days} days`}` : ', all time'));
    }
    if (choice.blueprints) parts.push(`${counts.blueprints} blueprints`);
    if (choice.authored) {
      parts.push(`${counts.jobs} jobs, ${counts.checklists} checklists, ${counts.trips} flight plans`);
    }
    if (choice.points) parts.push(`${counts.points} point${counts.points === 1 ? '' : 's'} of interest`);

    line.textContent = `Would save ${parts.join(' · ')}.`;
  } catch {
    line.textContent = '';
  }
}

/**
 * Saves the document the server built.
 *
 * A POST rather than a link, because export must not be a GET: the LAN rule
 * lets reads through, and this is the one response that hands over the whole
 * history at once. So the blob comes back from fetch and is clicked into the
 * downloads folder here.
 */
/* ---------- backup and restore ---------- */

/**
 * The file being restored and the plan for it, held between preview and apply.
 *
 * The text is kept rather than re-read because the apply has to send the same
 * bytes the plan was computed from: the server hashes what it is given and
 * refuses when it disagrees with what was approved. Reading the picker a second
 * time would be a fresh read of a file that may have changed underneath.
 */
let restoreFile = null;
let restorePlan = null;

async function renderBackupPreview() {
  const line = $('#backup-preview');
  if (!line) return;

  // A count nobody asked for must not be able to take the rest of Settings
  // down with it: everything below this on the page is more important.
  let counts;

  try {
    counts = await getJson('/api/backup/preview');
  } catch {
    line.textContent = '';
    return;
  }

  // Only what is actually there, so an empty install does not read as a list of
  // zeroes somebody has to be told to ignore.
  const parts = [
    [counts.jobs, 'job'], [counts.checklists, 'checklist'], [counts.trips, 'flight plan'],
    [counts.miningRuns, 'mining haul'], [counts.notes, 'map note'],
    [counts.kits, 'kit'], [counts.pins, 'point of interest', 'points of interest'],
  ].filter(([n]) => n > 0).map(([n, word, plural]) => `${n} ${n === 1 ? word : (plural || `${word}s`)}`);

  if (counts.goal) parts.push('your goal');
  if (counts.wipe) parts.push('your wipe line');

  line.textContent = parts.length
    ? `Would save ${parts.join(', ')}.`
    : 'Nothing typed yet — a backup would be empty.';
}

async function saveBackup() {
  const button = $('#backup-save');
  const status = $('#backup-status');

  button.disabled = true;
  status.textContent = 'Building the file…';

  let url = null;

  try {
    const response = await fetch('/api/backup');

    if (!response.ok) {
      status.textContent = 'The backup could not be built.';
      return;
    }

    const name = /filename="?([^";]+)"?/i.exec(
      response.headers.get('content-disposition') || '')?.[1] || 'quantumwake-backup.json';

    const blob = await response.blob();
    url = URL.createObjectURL(blob);

    const link = el('a');
    link.href = url;
    link.download = name;
    link.click();

    status.textContent = `Saved ${name} — ${Math.round(blob.size / 1024).toLocaleString()} KB.`;
  } catch {
    status.textContent = 'The backup could not be built.';
  } finally {
    // Revoking frees the blob; doing it before the click lands cancels the save.
    if (url) setTimeout(() => URL.revokeObjectURL(url), 30000);
    button.disabled = false;
  }
}

/**
 * Why each kind of line is on the list, in the reader's terms.
 *
 * "Conflict" is the code's word and would be the wrong one here: nothing has
 * gone wrong, the copy on this machine is simply newer, and the reader is being
 * asked whether to overwrite their own more recent work.
 */
const RESTORE_WHY = {
  Add: 'not on this machine',
  Replace: 'yours is older',
  Conflict: 'yours is newer',
  Deleted: 'you deleted this',
  Same: 'already the same',
};

async function planRestore(text) {
  const status = $('#backup-status');
  status.textContent = 'Reading the file…';

  const response = await fetch('/api/backup/plan', { method: 'POST', body: text });
  const body = await response.json().catch(() => null);

  if (!response.ok) {
    status.textContent = body?.problem || 'That file could not be read.';
    return;
  }

  restoreFile = text;
  restorePlan = body;
  status.textContent = '';
  renderRestorePlan();
}

function renderRestorePlan() {
  const panel = $('#backup-plan');
  panel.hidden = !restorePlan;
  if (!restorePlan) return;

  const acting = restorePlan.lines.filter((line) => line.action !== 'Same');

  const summary = $('#backup-plan-summary');
  summary.textContent = '';

  const counts = [
    [restorePlan.adds, 'to bring back'],
    [restorePlan.replaces, 'to replace'],
    [restorePlan.conflicts, 'newer here'],
    [restorePlan.deleted, 'you deleted'],
    [restorePlan.unchanged, 'already the same'],
  ].filter(([n]) => n > 0);

  for (const [n, word] of counts) {
    const tile = el('span', 'restore-count');
    tile.append(el('b', null, String(n)));
    tile.append(el('span', 'muted', ` ${word}`));
    summary.append(tile);
  }

  // Said even when it is zero-shaped news: "what happened to my pins" is a
  // question somebody will ask of a screen that rewrote their jobs.
  if (restorePlan.ignored > 0) {
    summary.append(el('span', 'restore-count muted',
      `${restorePlan.ignored} pinned or tracked — left alone either way`));
  }

  const body = $('#backup-plan-table').querySelector('tbody');
  body.textContent = '';

  for (const line of acting) {
    const row = el('tr');

    const cell = el('td');
    const box = el('input');
    box.type = 'checkbox';
    box.checked = line.takenByDefault;
    box.dataset.key = line.key;
    box.title = line.takenByDefault ? 'Untick to leave this alone' : 'Tick to take the copy in the file';
    cell.append(box);
    row.append(cell);

    const what = el('td');
    what.append(el('span', null, line.label));
    what.append(el('span', 'note-inline muted', ` ${RESTORE_WHY[line.action] || line.action}`));
    row.append(what);

    row.append(el('td', 'muted', line.store));
    row.append(el('td', 'muted', line.yours ? dateOf(line.yours) : '—'));
    row.append(el('td', 'muted', line.theirs ? dateOf(line.theirs) : '—'));

    body.append(row);
  }

  // Nothing to do is worth saying outright, rather than showing an empty table
  // above a button that would do nothing.
  $('#backup-apply').disabled = acting.length === 0;

  if (acting.length === 0) {
    summary.append(el('span', 'restore-count muted',
      'Nothing to do — this file matches what you have.'));
  }
}

async function applyRestore() {
  const button = $('#backup-apply');
  const status = $('#backup-status');

  // Sent as exceptions to the plan's own defaults, so approving it untouched
  // sends nothing at all - and a line this page did not know how to draw cannot
  // arrive unanswered and be read as a refusal.
  const take = [];
  const leave = [];

  for (const box of $('#backup-plan-table').querySelectorAll('input')) {
    const line = restorePlan.lines.find((l) => l.key === box.dataset.key);
    if (!line) continue;

    if (box.checked && !line.takenByDefault) take.push(line.key);
    if (!box.checked && line.takenByDefault) leave.push(line.key);
  }

  button.disabled = true;
  status.textContent = 'Restoring…';

  // Built the way the rest of the app builds a query, rather than through
  // URLSearchParams: the keys are store:id pairs and both halves need escaping.
  let query = `hash=${encodeURIComponent(restorePlan.hash)}`;
  if (take.length) query += `&take=${encodeURIComponent(take.join(','))}`;
  if (leave.length) query += `&leave=${encodeURIComponent(leave.join(','))}`;

  try {
    const response = await fetch(`/api/backup/restore?${query}`, { method: 'POST', body: restoreFile });
    const body = await response.json().catch(() => null);

    if (!response.ok) {
      status.textContent = body?.problem || 'Nothing was restored.';
      return;
    }

    // A refused write is not a smaller restore. Saying "nothing was restored"
    // over a half-finished one is the most misleading thing this screen could
    // do, so a failure says what it was and whether it went back.
    if (body.failed) {
      status.textContent = body.rolledBack
        ? 'A file could not be written, so nothing was restored — everything was put back as it was.'
        : 'A file could not be written, and not all of it could be put back. '
          + 'Check your jobs, plans and mining log before restoring again.';
      return;
    }

    status.textContent = body.restored === 0
      ? 'Nothing was restored — every line was left alone.'
      : `Restored ${body.restored} record${body.restored === 1 ? '' : 's'}.`
        + (body.skipped ? ` Left ${body.skipped} alone.` : '');

    closeRestore();
    await renderBackupPreview().catch(() => {});
  } catch {
    status.textContent = 'Nothing was restored.';
  } finally {
    button.disabled = false;
  }
}

function closeRestore() {
  restoreFile = null;
  restorePlan = null;
  $('#backup-plan').hidden = true;
  $('#backup-file').value = '';
}

$('#backup-save')?.addEventListener('click', () => saveBackup().catch(() => {}));
$('#backup-pick')?.addEventListener('click', () => $('#backup-file').click());
$('#backup-cancel')?.addEventListener('click', closeRestore);
$('#backup-apply')?.addEventListener('click', () => applyRestore().catch(() => {}));

$('#backup-file')?.addEventListener('change', async (event) => {
  const file = event.target.files?.[0];
  if (!file) return;

  try {
    await planRestore(await file.text());
  } catch {
    $('#backup-status').textContent = 'That file could not be read.';
  }
});

/* ---------- shareable recaps ---------- */

let shareReportData = null;

function shareChoice() {
  return {
    session: Boolean($('#share-session')?.checked),
    fleet: Boolean($('#share-fleet')?.checked),
    trade: Boolean($('#share-trade')?.checked),
    handle: Boolean($('#share-handle')?.checked),
  };
}

function shareMetric(label, value) {
  const metric = el('div', 'share-metric');
  metric.append(el('div', 'share-metric-value', value));
  metric.append(el('div', 'share-metric-label', label));
  return metric;
}

function shareSection(title, sources, detail = '') {
  const section = el('section', 'share-section');
  const head = el('div', 'share-section-head');
  head.append(el('h3', null, title));
  head.append(sourceMarks(sources));
  section.append(head);
  if (detail) section.append(el('p', 'share-section-detail', detail));
  return section;
}

function shareList(rows, empty) {
  const list = el('ul', 'share-list');
  if (!rows.length) list.append(el('li', 'muted', empty));
  for (const row of rows) {
    const item = el('li');
    item.append(el('span', null, row.label));
    if (row.detail) item.append(el('span', 'muted', row.detail));
    if (row.value) item.append(el('b', row.className || '', row.value));
    list.append(item);
  }
  return list;
}

/** A frozen recap uses only evidence already held locally by the app. */
async function buildShareReport() {
  const choice = shareChoice();
  if (!choice.session && !choice.fleet && !choice.trade)
    throw new Error('Choose at least one section for the recap.');

  const report = { choice, madeAt: new Date().toISOString() };
  const needsSessions = choice.session || choice.handle;
  const sessions = needsSessions ? await getJson('/api/sessions') : [];
  const latest = [...sessions].sort((a, b) => new Date(b.startedAt) - new Date(a.startedAt))[0] || null;

  if (choice.handle) report.handle = latest?.handle || '';
  if (choice.session && latest) {
    const detail = await getJson(`/api/sessions/${encodeURIComponent(latest.id)}`).catch(() => null);
    report.session = { summary: latest, detail };
  } else if (choice.session) report.session = { summary: null, detail: null };

  if (choice.fleet) report.fleet = await getJson('/api/fleet').catch(() => null);

  if (choice.trade) {
    const [earnings, market] = await Promise.all([
      getJson('/api/earnings?days=30').catch(() => null),
      getJson('/api/market').catch(() => []),
    ]);
    report.trade = { earnings, market };
  }

  return report;
}

function renderShareReport(report) {
  const host = $('#share-report');
  if (!host) return;
  host.textContent = '';

  const head = el('header', 'share-report-head');
  const title = el('div');
  title.append(el('div', 'share-kicker', 'QUANTUM WAKE · PILOT RECAP'));
  title.append(el('h2', null, report.handle ? `${report.handle}'s recent flight` : 'Recent flight recap'));
  title.append(el('p', 'muted', `Snapshot made ${new Date(report.madeAt).toLocaleString()}. It does not update after it is shared.`));
  head.append(title);
  head.append(sourceMarks(['logs']));
  host.append(head);

  if (report.session) renderShareSession(host, report.session);
  if (report.fleet) renderShareFleet(host, report.fleet);
  if (report.trade) renderShareTrade(host, report.trade);

  host.append(el('p', 'share-limits',
    'Source labels name the evidence behind each section. Trading is limited to commodity movements the game log records; it is not total income.'));
}

function renderShareSession(host, session) {
  const summary = session.summary;
  const section = shareSection('Latest session', ['logs'],
    'What the game log recorded during the most recent session.');
  if (!summary) {
    section.append(el('p', 'muted', 'No completed session has been recorded yet.'));
    host.append(section);
    return;
  }

  const detail = session.detail;
  const route = detail ? sessionRoute(detail) : [];
  const ships = detail ? (detail.ships || []).map((ship) => ship.displayName || ship.model).filter(Boolean) : [];
  const metrics = el('div', 'share-metrics');
  metrics.append(
    shareMetric('In game', duration(summary.inGame)),
    shareMetric('Ship', ships.join(' · ') || summary.primaryShip || 'On foot'),
    shareMetric('Route points', String(route.length || summary.locations || 0)),
    shareMetric('Contracts', String(summary.contracts || 0)),
    shareMetric('Deaths', String(summary.deaths || 0)),
  );
  section.append(metrics);

  section.append(el('h4', null, 'Recorded route'));
  section.append(shareList(route.slice(0, 8).map((place) => ({
    label: place.displayName,
    detail: [place.body, place.system].filter(Boolean).join(' · ') || place.routeKind,
    value: shortTimeOf(place.at),
  })), 'No named locations were written in this session.'));
  host.append(section);
}

function renderShareFleet(host, fleet) {
  const section = shareSection('Fleet snapshot', ['logs'],
    'Ships flown by this account; it does not claim to be the game entitlement roster.');
  if (!fleet) {
    section.append(el('p', 'muted', 'The fleet summary could not be read.'));
    host.append(section);
    return;
  }

  const ships = [...(fleet.flown || [])].sort((a, b) => (b.sorties || 0) - (a.sorties || 0));
  const seconds = ships.reduce((sum, ship) => sum + toSeconds(ship.estimatedTime || ship.timeAboard || '00:00:00'), 0);
  const metrics = el('div', 'share-metrics');
  metrics.append(
    shareMetric('Game entitlement', fleet.owned === null || fleet.owned === undefined ? '—' : String(fleet.owned)),
    shareMetric('Ships flown', String(ships.length)),
    shareMetric('Total sorties', String(ships.reduce((sum, ship) => sum + (ship.sorties || 0), 0))),
    shareMetric('Time aboard', `~${duration(seconds)}`),
  );
  section.append(metrics);
  section.append(el('h4', null, 'Most flown'));
  section.append(shareList(ships.slice(0, 6).map((ship) => ({
    label: ship.name,
    detail: ship.lastFlown ? `last flown ${dateOf(ship.lastFlown)}` : '',
    value: `${ship.sorties || 0} sortie${ship.sorties === 1 ? '' : 's'}`,
  })), 'No ship flights have been recorded.'));
  host.append(section);
}

function renderShareTrade(host, trade) {
  const section = shareSection('Trading snapshot · last 30 days', ['logs'],
    'Commodity movements the game log recorded. Contract rewards, bounties and fees are not included.');
  const rate = trade.earnings?.window;
  const rows = [...(trade.market || [])].filter((row) => row.myTrades > 0)
    .sort((a, b) => (b.myRevenue || 0) - (a.myRevenue || 0));
  const metrics = el('div', 'share-metrics');
  metrics.append(
    shareMetric('Recorded profit', rate ? money(rate.earned) : '—'),
    shareMetric('Trading rate', rate?.perHour > 0 ? `${money(rate.perHour)}/h` : 'No rate yet'),
    shareMetric('In-game hours', rate ? hoursOf(rate.inGame) : '—'),
    shareMetric('Commodities moved', String(rows.length)),
  );
  section.append(metrics);
  section.append(el('h4', null, 'Largest recorded sales'));
  section.append(shareList(rows.slice(0, 6).map((row) => ({
    label: row.name,
    detail: `${row.myScuSold || 0} SCU sold · ${row.myTrades || 0} trip${row.myTrades === 1 ? '' : 's'}`,
    value: money(row.myRevenue || 0),
    className: 'inward',
  })), 'No commodity movements were recorded in this window.'));
  host.append(section);
}

function shareReportDocument() {
  const report = $('#share-report');
  if (!shareReportData || !report) return null;
  const content = report.cloneNode(true);
  return '<!doctype html><html lang="en"><head><meta charset="utf-8">'
    + '<meta name="viewport" content="width=device-width, initial-scale=1">'
    + '<title>Quantum Wake pilot recap</title><style>' + shareReportCss() + '</style></head><body>'
    + content.outerHTML + '</body></html>';
}

function shareReportCss() {
  return 'body{margin:0;background:#070c14;color:#dcebf7;font:14px/1.5 system-ui,Segoe UI,sans-serif}.share-report{max-width:960px;margin:32px auto;padding:28px;background:linear-gradient(150deg,#101d2c,#070c14);border:1px solid #2c526d}.share-report-head,.share-section-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start}.share-kicker{color:#8be7ff;font:700 11px ui-monospace,Consolas,monospace;letter-spacing:2px}.share-report h2{margin:4px 0;font-size:30px}.share-report h3{margin:0;color:#8be7ff;font-size:18px}.share-report h4{margin:20px 0 7px;font-size:12px;letter-spacing:1px;text-transform:uppercase;color:#7691a8}.muted,.share-section-detail{color:#9ab0c3}.data-sources{display:flex;gap:4px;flex-wrap:wrap}.data-source{border:1px solid #2c526d;padding:2px 5px;font:10px ui-monospace,Consolas,monospace;letter-spacing:.7px;color:#8be7ff}.game-install{color:#7ee3a5}.screenshot-ocr,.data-source-qualifier{color:#ffbc66}.community-data{color:#c59cff}.share-section{margin-top:22px;padding-top:18px;border-top:1px solid #24445b}.share-metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:9px;margin-top:14px}.share-metric{padding:10px;background:#0a1420;border-left:2px solid #35c8f0}.share-metric-value{font-size:16px;font-weight:700}.share-metric-label{font-size:10px;color:#9ab0c3;text-transform:uppercase;letter-spacing:.8px}.share-list{list-style:none;padding:0;margin:0}.share-list li{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:12px;padding:6px 0;border-bottom:1px solid #172b3b}.share-list b{white-space:nowrap}.inward{color:#7ee3a5}.share-limits{margin:25px 0 0;color:#9ab0c3;font-size:12px}@media print{body{background:#fff;color:#14202b}.share-report{margin:0;max-width:none;border:0;background:#fff}.share-report h3,.share-kicker{color:#126b91}.share-section{border-color:#b8cbd6}.share-metric{background:#eef5f8;border-color:#126b91}.muted,.share-section-detail,.share-metric-label,.share-limits{color:#50616c}.data-source{color:#126b91;border-color:#8ca6b4}.share-list li{border-color:#d6e1e7}}';
}

async function openShareReport() {
  const status = $('#share-status');
  if (status) status.textContent = 'Building recap…';
  try {
    shareReportData = await buildShareReport();
    renderShareReport(shareReportData);
    if (status) status.textContent = '';
    showView('share');
  } catch (error) {
    if (status) status.textContent = error.message || 'The recap could not be built.';
  }
}

function saveShareReport() {
  const html = shareReportDocument();
  if (!html) return;
  const stamp = new Date().toISOString().slice(0, 10);
  const url = URL.createObjectURL(new Blob([html], { type: 'text/html;charset=utf-8' }));
  const link = el('a');
  link.href = url;
  link.download = `quantumwake-pilot-recap-${stamp}.html`;
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 30000);
}

$('#share-open')?.addEventListener('click', () => openShareReport());
$('#share-back')?.addEventListener('click', () => showView('settings'));
// The print stylesheet is scoped to this class rather than to the page, so
// Ctrl+P on Sessions or Fleet prints that page and not a blank one - or a
// recap left over from earlier.
$('#share-print')?.addEventListener('click', () => {
  document.body.classList.add('printing-share');
  const done = () => document.body.classList.remove('printing-share');
  window.addEventListener('afterprint', done, { once: true });
  window.print();
  // Browsers without afterprint, and the stub document: never leave it set.
  setTimeout(done, 1000);
});
$('#share-save-html')?.addEventListener('click', () => saveShareReport());

async function saveExport() {
  const button = $('#export-save');
  const status = $('#export-status');
  const choice = exportChoice();

  if (!choice.receipts && !choice.blueprints && !choice.authored && !choice.points) {
    status.textContent = 'Tick at least one thing first.';
    return;
  }

  button.disabled = true;
  status.textContent = 'Building the file…';

  let url = null;

  try {
    const response = await fetch('/api/export', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(choice),
    });

    if (!response.ok) {
      const problem = await response.json().catch(() => null);
      status.textContent = problem?.message || 'The file could not be built.';
      return;
    }

    // The server names it; the header is where that name is.
    const name = /filename="?([^";]+)"?/i.exec(
      response.headers.get('content-disposition') || '')?.[1] || 'quantumwake-export.json';

    const blob = await response.blob();
    url = URL.createObjectURL(blob);

    const link = el('a');
    link.href = url;
    link.download = name;
    link.click();

    status.textContent = `Saved ${name} — ${Math.round(blob.size / 1024).toLocaleString()} KB.`;
  } catch {
    status.textContent = 'The file could not be built.';
  } finally {
    // Revoking frees the blob; doing it before the click lands cancels the save.
    if (url) setTimeout(() => URL.revokeObjectURL(url), 30000);
    button.disabled = false;
  }
}

for (const id of ['#export-receipts', '#export-blueprints', '#export-authored', '#export-points', '#export-days']) {
  $(id)?.addEventListener('change', () => renderExportPreview().catch(() => {}));
}

$('#export-save')?.addEventListener('click', () => saveExport().catch(() => {}));

/**
 * Which signals are still arriving, and when each last did.
 *
 * The date is the point. Every telemetry removal so far has looked, from in
 * here, exactly like a quiet week - so the table leads with when a thing last
 * happened, and marks the rows that have gone quiet rather than leaving the
 * reader to compare eighteen dates by eye.
 *
 * "Quiet" is measured against this install's own last session, not against
 * today: someone coming back after a month away should not be told that
 * everything broke while they were gone.
 */
async function renderSignals() {
  const table = $('#signals-table');
  if (!table) return;

  let rows;
  try {
    rows = await getJson('/api/signals');
  } catch {
    return;
  }

  const body = table.querySelector('tbody');
  body.textContent = '';

  const played = Math.max(...rows.map((r) => (r.lastSeen ? Date.parse(r.lastSeen) : 0)), 0);
  const QUIET = 21 * 86400000;

  let group = null;

  for (const row of rows) {
    if (row.group !== group) {
      group = row.group;

      const head = el('tr', 'group-row');
      const cell = el('td', 'muted', group);
      cell.colSpan = 4;
      head.append(cell);
      body.append(head);
    }

    const seen = row.lastSeen ? Date.parse(row.lastSeen) : null;
    const quiet = seen !== null && played - seen > QUIET;

    const tr = el('tr');
    tr.append(el('td', null, row.name));
    tr.append(el('td', row.total ? 'num' : 'num muted', row.total ? row.total.toLocaleString() : '—'));
    tr.append(el('td', row.sessions ? 'num' : 'num muted', row.sessions || '—'));

    const last = el('td', seen === null ? 'muted' : (quiet ? 'outward' : 'muted'));
    last.textContent = seen === null ? 'never' : `${dateOf(row.lastSeen)}${quiet ? ' · gone quiet' : ''}`;
    tr.append(last);

    if (row.note) tr.title = row.note;
    body.append(tr);
  }
}

/**
 * The automatic refresh switch.
 *
 * Disabled rather than hidden while UEX is off: a switch that vanishes reads as
 * a feature that does not exist, whereas a greyed one with a reason reads as a
 * door you have not opened yet. The note carries the interval and the last
 * attempt, because "automatic" without a period is a promise with no shape.
 */
async function renderUexAuto() {
  const toggle = $('#uex-auto-toggle');
  const note = $('#uex-auto-note');
  if (!toggle) return;

  try {
    const auto = await getJson('/api/uex/auto');

    toggle.checked = auto.automatic;
    toggle.disabled = !auto.uexEnabled;

    if (!auto.uexEnabled) {
      note.textContent = 'fetch prices first';
      return;
    }

    const every = `every ${auto.staleAfterHours} hours`;

    note.textContent = auto.automatic
      ? (auto.lastCheckedAt ? `${every} · last tried ${dateOf(auto.lastCheckedAt)}` : every)
      : `off · prices stay as fetched`;
  } catch { /* Settings redraws on its next visit */ }
}

$('#uex-auto-toggle')?.addEventListener('change', async (e) => {
  const toggle = e.currentTarget;

  try {
    await fetch(`/api/uex/auto/answer?automatic=${toggle.checked}`, { method: 'POST' });
  } catch {
    toggle.checked = !toggle.checked;
  }

  await renderUexAuto();
});

/**
 * The optional UEX feeds, each with its own switch: they serve different
 * pages, so a trader and a miner should not have to take each other's bytes.
 */
async function renderUexFeeds() {
  const list = $('#uex-feed-list');
  if (!list) return;

  let feeds;
  try {
    feeds = await getJson('/api/uex/feeds');
  } catch {
    return;
  }

  list.textContent = '';

  for (const feed of feeds) {
    const row = el('div', 'uex-feed');

    const head = el('div', 'uex-feed-head');
    head.append(el('b', null, feed.title));
    head.append(el('span', 'cost', feed.cost));
    row.append(head);

    row.append(el('div', 'muted feed-copy', feed.description));

    const actions = el('div', 'uex-feed-actions');
    const button = el('button', 'ghost', feed.enabled ? 'Refresh' : 'Fetch');
    const status = el('span', 'muted');

    status.textContent = feed.enabled
      ? `on · fetched ${feed.fetchedAt ? ago(feed.fetchedAt) : '—'}`
      : 'off';

    button.addEventListener('click', () =>
      uexAction(`/api/uex/feeds/${feed.key}/enable`, status, button));

    actions.append(button);

    if (feed.enabled) {
      const drop = el('button', 'ghost', 'Drop');
      drop.addEventListener('click', () =>
        uexAction(`/api/uex/feeds/${feed.key}/disable`, status, drop));
      actions.append(drop);
    }

    actions.append(status);
    row.append(actions);
    list.append(row);
  }
}

async function uexAction(path, statusNode, button) {
  button.disabled = true;
  statusNode.textContent = 'working…';

  try {
    const result = await fetch(path, { method: 'POST' });
    if (!result.ok) throw new Error((await result.json()).title || result.statusText);
    statusNode.textContent = '';
  } catch (e) {
    statusNode.textContent = `failed: ${e.message}`;
  } finally {
    button.disabled = false;
    renderSettings();
    loadMarket().catch(() => {});
  }
}

$('#uex-enable').addEventListener('click', (e) => uexAction('/api/uex/enable', $('#uex-status'), e.currentTarget));
$('#uex-refresh').addEventListener('click', (e) => uexAction('/api/uex/enable', $('#uex-status'), e.currentTarget));
$('#uex-disable').addEventListener('click', (e) => uexAction('/api/uex/disable', $('#uex-status'), e.currentTarget));

$('#uex-save-creds').addEventListener('click', async (e) => {
  const button = e.currentTarget;
  button.disabled = true;

  try {
    await fetch('/api/uex/credentials', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ token: $('#uex-token').value, secret: $('#uex-secret').value }),
    });

    $('#uex-token').value = '';
    $('#uex-secret').value = '';
  } finally {
    button.disabled = false;
    renderSettings();
  }
});

/**
 * The two-step report: preview says exactly what would be sent and to which
 * terminals; only the second button transmits anything.
 */
$('#uex-preview').addEventListener('click', async () => {
  const status = $('#uex-push-status');

  try {
    const rows = await getJson('/api/uex/pushable');
    const matched = rows.filter((r) => r.terminalId && r.commodityId);
    const terminals = new Set(matched.map((r) => r.terminalName));
    const skipped = rows.length - matched.length;

    status.textContent = matched.length
      ? `${matched.length} price${matched.length === 1 ? '' : 's'} across `
        + `${terminals.size} terminal${terminals.size === 1 ? '' : 's'}`
        + (skipped ? ` · ${skipped} skipped (place not matched to a UEX terminal)` : '')
      : rows.length
        ? `nothing sendable: ${rows.length} sale${rows.length === 1 ? '' : 's'} but no place matched a UEX terminal`
        : 'no named sales in the last 30 days';

    $('#uex-send').hidden = matched.length === 0;
  } catch (e) {
    status.textContent = `failed: ${e.message}`;
  }
});

$('#uex-send').addEventListener('click', async (e) => {
  const button = e.currentTarget;
  const status = $('#uex-push-status');

  button.disabled = true;
  status.textContent = 'sending…';

  try {
    const result = await fetch('/api/uex/push', { method: 'POST' });
    const body = await result.json();
    if (!result.ok) throw new Error(body.title || result.statusText);

    status.textContent = body.results.join(' · ') || 'nothing sent';
    button.hidden = true;
  } catch (err) {
    status.textContent = `failed: ${err.message}`;
  } finally {
    button.disabled = false;
  }
});

$('#overlay-toggle').addEventListener('click', async (e) => {
  const next = e.currentTarget.dataset.visible !== 'true';

  try {
    await fetch(`/api/overlay?visible=${next}`, { method: 'POST' });
  } finally {
    renderSettings();
  }
});

$('#settings-community-enable').addEventListener('click', (e) =>
  setCommunity(true, $('#settings-community-status'), e.currentTarget));

$('#settings-community-disable').addEventListener('click', (e) =>
  setCommunity(false, $('#settings-community-status'), e.currentTarget));

$('#settings-rescan').addEventListener('click', async (e) => {
  const button = e.currentTarget;
  const status = $('#settings-rescan-status');

  button.disabled = true;
  status.textContent = rescanLine({ running: true });

  // The page's bar is at the top of the document and this button is near the
  // bottom of a long Settings page, so from here it is off-screen. The count is
  // repeated beside the button that started it.
  const poll = setInterval(async () => {
    try {
      status.textContent = rescanLine(await getJson('/api/scan/status'));
    } catch { /* the result below is the answer that matters */ }
  }, 500);

  try {
    const result = await getJson2('/api/scan?force=true');
    status.textContent = `${result.sessions} sessions from a full re-read`;

    // The re-read is what the button promised, and it is already done. A reload
    // that fails afterwards leaves the views stale, which is a smaller problem
    // than telling somebody their rescan failed when it did not.
    await loadHistory().catch(() => {});
  } catch (err) {
    status.textContent = `failed: ${err.message}`;
  } finally {
    clearInterval(poll);
    button.disabled = false;
  }
});

/**
 * What the Settings line says while a forced rescan runs.
 *
 * Files rather than a percentage: this is a re-read of every backup, and "112
 * of 160" says how much is left in a way "70%" does not.
 */
function rescanLine(scan) {
  return scan.running && scan.total > 0
    ? `${scan.done} / ${scan.total} logs · ${scan.elapsedSeconds}s`
    : 'rescanning…';
}

/** POST that expects JSON back; getJson is GET-only. */
async function getJson2(url) {
  const response = await fetch(url, { method: 'POST' });
  if (!response.ok) throw new Error(`${url} -> ${response.status}`);
  return response.json();
}

function renderCommodities(trades) {
  const sells = trades.filter((t) => t.isSell);
  const buys = trades.filter((t) => !t.isSell);

  const revenue = sells.reduce((total, t) => total + Number(t.amount), 0);
  const scuSold = sells.reduce((total, t) => total + t.scu, 0);
  const outlay = buys.reduce((total, t) => total + Number(t.amount), 0);

  // What better selling would have earned: the gap between each sale's unit
  // price and UEX's best, over the sold volume. Zero rows when UEX is off.
  const leftOnTable = sells
    .filter((t) => t.uexBestSell > 0 && Number(t.uexBestSell) > Number(t.unitPrice))
    .reduce((total, t) => total + (Number(t.uexBestSell) - Number(t.unitPrice)) * t.scu, 0);

  const cargoTiles = [
    ['Revenue', money(revenue)],
    ['SCU sold', scuSold.toLocaleString()],
    ['Average per SCU', scuSold ? money(revenue / scuSold) : '—'],
    ['Cargo bought', money(outlay)],
    ['Sales', sells.length],
    ['Best sale', sells.length ? money(Math.max(...sells.map((t) => Number(t.amount)))) : '—'],
  ];

  if (sells.some((t) => t.uexBestSell > 0))
    cargoTiles.push(['Left on the table*', money(leftOnTable)]);

  tiles('#cargo-summary', cargoTiles);

  // Revenue by place, with the volume that produced it.
  const byShop = new Map();
  for (const trade of sells) {
    const current = byShop.get(trade.place) || { amount: 0, scu: 0 };
    current.amount += Number(trade.amount);
    current.scu += trade.scu;
    byShop.set(trade.place, current);
  }

  drawCargoEarnings(trades);

  bars('#cargo-shops',
    [...byShop.entries()]
      .sort((a, b) => b[1].amount - a[1].amount)
      .map(([shop, v]) => ({ label: shop, value: v.amount, note: `${v.scu} SCU` })),
    money);

  const body = $('#cargo-table tbody');
  body.textContent = '';

  if (!trades.length) {
    const tr = el('tr');
    const td = el('td', 'muted', 'No cargo trades in that range.');
    td.colSpan = 8;
    tr.append(td);
    body.append(tr);
    return;
  }

  const anyBest = trades.some((t) => t.uexBestSell > 0);
  $('#cargo-best-col').hidden = !anyBest;

  for (const trade of trades) {
    const tr = el('tr');
    tr.append(el('td', null, dateOf(trade.at)));
    tr.append(el('td', null, trade.isSell ? 'Sold' : 'Bought'));
    tr.append(el('td', trade.commodity ? null : 'muted', trade.commodity ?? '—'));
    tr.append(tdPlace(trade.place));
    tr.append(el('td', 'num', String(trade.scu)));
    tr.append(el('td', `num ${trade.isSell ? 'inward' : 'outward'}`, money(trade.amount)));
    tr.append(el('td', 'num muted', money(trade.unitPrice)));

    if (anyBest) {
      const cell = el('td', 'num');

      if (trade.uexBestSell > 0) {
        const delta = ((Number(trade.unitPrice) - Number(trade.uexBestSell)) / Number(trade.uexBestSell)) * 100;
        cell.className = `num ${delta >= -3 ? 'inward' : 'outward'}`;
        cell.textContent = `${delta >= 0 ? '+' : ''}${delta.toFixed(0)}%`;
        cell.title = `UEX best sell today: ${money(trade.uexBestSell)}/SCU`;
      } else {
        cell.className = 'num muted';
        cell.textContent = '—';
      }

      tr.append(cell);
    }

    body.append(tr);
  }
}

/* ---------- shared widgets ---------- */

/**
 * Every table sorts by clicking its headers. One generic pass over the DOM
 * rather than per-page wiring, so a table added next month is sortable for
 * free. Numbers sort as numbers, dates as dates, everything else as text;
 * re-rendering (a period change, a rescan) resets to the page's own order.
 */
function makeTablesSortable() {
  for (const table of document.querySelectorAll('main table')) {
    [...table.querySelectorAll('thead th')].forEach((th, index) => {
      if (!th.textContent.trim()) return;

      th.classList.add('sortable');
      th.title = 'Sort';

      th.addEventListener('click', () => {
        const descending = !th.classList.contains('sort-desc');

        for (const other of table.querySelectorAll('thead th'))
          other.classList.remove('sort-asc', 'sort-desc');
        th.classList.add(descending ? 'sort-desc' : 'sort-asc');

        const body = table.tBodies[0];
        if (!body) return;

        // Empty-state rows span the table and stay where they are.
        const rows = [...body.rows].filter((r) => r.cells.length > 1);

        rows.sort((a, b) => compareCells(a, b, index) * (descending ? -1 : 1));
        rows.forEach((r) => body.append(r));
      });
    });
  }
}

function compareCells(rowA, rowB, index) {
  const a = (rowA.cells[index]?.textContent ?? '').trim();
  const b = (rowB.cells[index]?.textContent ?? '').trim();

  // Dates first: "Aug 17, 2026" parsed numerically would sort by day-of-month.
  const dateish = /^[A-Z][a-z]{2} \d{1,2}, \d{4}/;
  if (dateish.test(a) && dateish.test(b))
    return Date.parse(a) - Date.parse(b);

  const numA = parseFloat(a.replace(/[^0-9.-]/g, ''));
  const numB = parseFloat(b.replace(/[^0-9.-]/g, ''));
  if (Number.isFinite(numA) && Number.isFinite(numB) && /\d/.test(a) && /\d/.test(b))
    return numA - numB;

  return a.localeCompare(b);
}

makeTablesSortable();

/* ---------- what contracts paid ---------- */

/**
 * What the game said your contracts paid, and how little of it that is.
 *
 * The figure and its explanation come from the same call on purpose. A tile
 * summing the ledger itself and a "why?" answered by the server would be two
 * readings of one number, and the day they disagreed the page would be arguing
 * with itself.
 */
async function renderContractsPaid(stats) {
  const note = $('#contract-paid-note');
  if (!note) return;

  let paid;

  try {
    paid = await getJson('/api/explain?figure=contracts.paid&days=0');
  } catch {
    note.hidden = true;
    return;
  }

  // Nothing priced is not nothing earned, and a zero here would say the second.
  if (!paid.records.length) {
    note.hidden = false;
    note.textContent = 'The game has never stated what one of your contracts paid. '
      + 'It prices a completion only now and then, and only for hauling.';
    return;
  }

  const strip = $('#contract-summary');

  const tile = el('div', 'tile');
  tile.append(el('div', 'n', money(paid.value)));
  tile.append(el('div', 'l', 'Stated payouts'));

  // The strip's shared panel is the last child tiles() appended.
  const panel = strip.children[strip.children.length - 1];
  explainable(tile, panel, 'contracts.paid', 0);

  // Appended, then the panel is appended again to move it back to last.
  // Appending a node that already has a parent moves it, in a browser and in
  // the test DOM alike, so the explanation stays the row under the tiles.
  strip.append(tile);
  strip.append(panel);

  note.hidden = false;
  note.textContent = `From ${paid.records.length} of your ${stats.contractsCompleted} completed `
    + 'contracts — the only ones the game put a price on. A floor, not your contract income.';
}

/* ---------- why this number ---------- */

/**
 * Attaches "why?" to a figure, and folds the answer under it.
 *
 * Folded by default because a number nobody is questioning does not want three
 * lines of provenance beneath it - and a number somebody is questioning wants
 * all of them. The same trade the run review panel settled on.
 *
 * The wording all comes from the server. A page that reworded a rule would be a
 * second copy of it, and the two would drift apart in exactly the direction
 * that makes a caveat stop being true.
 */
function explainable(tile, panel, figure, days = 0) {
  const why = el('button', 'why', '?');
  why.type = 'button';
  why.title = 'Where this number came from';
  why.setAttribute('aria-label', 'Where this number came from');

  why.addEventListener('click', async () => {
    // One panel for the whole strip, so pressing a second question swaps the
    // answer rather than opening a competing one.
    if (!panel.hidden && panel.dataset.figure === figure) {
      panel.hidden = true;
      return;
    }

    panel.hidden = false;
    panel.dataset.figure = figure;
    panel.textContent = 'Working it out…';

    await fillExplanation(panel, figure, days);
  });

  tile.append(why);
  return tile;
}

async function fillExplanation(panel, figure, days) {
  let explained;

  try {
    explained = await getJson(`/api/explain?figure=${encodeURIComponent(figure)}&days=${days}`);
  } catch {
    // A figure this build cannot explain says so. Silence would read as "there
    // is nothing behind this number", which is a much bigger claim.
    panel.textContent = '';
    panel.append(el('div', 'why-rule', 'Nothing here knows how to explain that one yet.'));
    return;
  }

  panel.textContent = '';
  panel.append(el('div', 'why-rule', explained.rule));

  for (const line of explained.excluded) panel.append(el('div', 'why-excluded', line));

  // Empty is a real answer and a different one from "no records matched", so
  // it is worded rather than left as a blank space under the exclusions.
  if (!explained.records.length) {
    panel.append(el('div', 'why-rule muted',
      'This figure has no underlying records — only the rule above.'));
    return;
  }

  const list = el('div', 'why-records');

  // A long list is folded to a readable head; the count says what is under it,
  // so a page of four hundred receipts does not bury the rule that matters.
  for (const record of explained.records.slice(0, 12)) {
    const row = el('div', 'why-record');
    row.append(el('span', 'muted', dateOf(record.at)));
    row.append(el('span', null, record.where ? `${record.what} at ${record.where}` : record.what));
    row.append(el('span', 'amount', record.amount === null ? '' : money(record.amount)));
    list.append(row);
  }

  if (explained.records.length > 12) {
    list.append(el('div', 'why-rule muted',
      `and ${(explained.records.length - 12).toLocaleString()} more.`));
  }

  panel.append(list);
}

function tiles(container, entries) {
  const node = $(container);
  node.textContent = '';

  /*
   * The explanation lives under the strip rather than inside a tile, and that
   * is not decoration. The strip is a grid, so a panel inside one tile stretches
   * every other tile to match it - three empty boxes as tall as the answer - and
   * a paragraph of provenance in a 155px column wraps every line to three.
   */
  const panel = el('div', 'why-panel');
  panel.hidden = true;

  for (const [label, value, figure, days] of entries) {
    const tile = el('div', 'tile');
    tile.append(el('div', 'n', String(value)));
    tile.append(el('div', 'l', label));

    // Only the figures the server can actually answer for. A control on
    // everything would promise an explanation for numbers nobody has written
    // one down for yet.
    if (figure) explainable(tile, panel, figure, days || 0);

    node.append(tile);
  }

  node.append(panel);
}

/* Manufacturer prefixes as they appear in vehicle ids. */
/**
 * Manufacturer codes to names. The hand-typed entries are the fallback and
 * the source of logo files; the community dataset's full table is merged over
 * them at boot when it is enabled, so every code the game knows resolves.
 */
const MANUFACTURERS = {
  DRAK: 'Drake Interplanetary', ANVL: 'Anvil Aerospace', RSI: 'Roberts Space Industries',
  MISC: 'MISC', ORIG: 'Origin Jumpworks', AEGS: 'Aegis Dynamics',
  CRUS: 'Crusader Industries', CNOU: 'Consolidated Outland', TMBL: 'Tumbril',
  ESPR: 'Esperia', BANU: 'Banu', KRIG: 'Kruger Intergalactic',
  ARGO: 'ARGO Astronautics', AOPO: 'Aopoa', GATS: 'Gatac', MRAI: 'Mirai',
};

/** The codes with a local logo image; the merged map must not grow this set. */
const MANUFACTURER_LOGOS = new Set(Object.keys(MANUFACTURERS));

/**
 * Every way a ship name can announce its maker, to the code that names its
 * logo file.
 *
 * Ship names used to arrive as log ids - "DRAK Corsair" - so the first word
 * was the code and the logo lookup was a dictionary hit. Once the community
 * dataset started resolving real names, the same ship reads "Drake Corsair"
 * and that lookup quietly missed for every maker whose code is not also its
 * name, which is most of them: RSI and MISC kept their badges and nobody else
 * did. So codes AND names, longest match first, because "Consolidated Outland"
 * must beat "Consolidated".
 */
let makerAliases = new Map();

function buildMakerAliases() {
  makerAliases = new Map();

  for (const [code, name] of Object.entries(MANUFACTURERS)) {
    makerAliases.set(code.toLowerCase(), code);
    makerAliases.set(name.toLowerCase(), code);
    makerAliases.set(name.split(' ')[0].toLowerCase(), code);
  }
}

buildMakerAliases();

/** Splits a ship name into its maker and the model that follows. */
/*
 * A colour per maker for the silhouettes. Cosmetic and said to be: the game's
 * vehicle icons are white shapes, and a maker's colour on one is a hint at
 * whose ship it is, not the ship's finish - that is what the paint choice is
 * for. Chosen to read on the dark deck, nothing more.
 */
const MAKER_TINTS = {
  AEGS: '#7fc4b0', ANVL: '#8fd18a', AOPO: '#b6dc9a', ARGO: '#f0cf5a', BANU: '#d8b97c',
  CNOU: '#f0a45c', CRUS: '#e6ecf2', DRAK: '#f0954a', ESPR: '#c7b8e6', GAMA: '#a9c4e0',
  GRIN: '#e2cf5a', KRIG: '#f2b05c', MISC: '#9adcf2', MRAI: '#d7dfe4', ORIG: '#e8d79a',
  RSI: '#a9d0f5', TMBL: '#d3bd8f', VNCL: '#e56b66', XIAN: '#9fd9a8', XNAA: '#9fd9a8',
};

function makerTint(code) {
  return MAKER_TINTS[code] || '#7fe4ff';
}

/** The paint the pilot chose per hull, in this browser - the same home as the roster tick. */
let shipPaints = {};
try {
  shipPaints = JSON.parse(localStorage.getItem('qw-ship-paints') || '{}') || {};
} catch { /* private browsing; a silhouette is the honest default anyway */ }

// The first pictured paint is useful as a stand-in, but some pilots prefer the
// neutral maker tint until they have explicitly chosen their own paint.
let shipPictureStyle = 'paint';
try {
  shipPictureStyle = localStorage.getItem('qw-ship-picture-style') === 'tint' ? 'tint' : 'paint';
} catch { /* private browsing keeps the default */ }

/** The pilot's word for "no paint, the silhouette" - distinct from never having picked. */
const SILHOUETTE = 'silhouette';

function rememberShipPaint(vehicleClass, paintItem) {
  if (paintItem) shipPaints[vehicleClass] = paintItem;
  else delete shipPaints[vehicleClass];
  try { localStorage.setItem('qw-ship-paints', JSON.stringify(shipPaints)); } catch { /* as above */ }
}

/** The paints the game pictures for a hull, fetched once per hull for the page. */
const hullPaints = new Map();
const resolvedHullPaints = new Map();
function paintsForHull(vehicleClass) {
  if (!hullPaints.has(vehicleClass)) {
    hullPaints.set(vehicleClass, getJson(`/api/fleet/paints/${encodeURIComponent(vehicleClass)}`)
      .catch(() => [])
      .then((paints) => {
        resolvedHullPaints.set(vehicleClass, paints);
        return paints;
      }));
  }
  return hullPaints.get(vehicleClass);
}

/** The paint a scale drawing can show without claiming to know a ship's finish. */
function hangarPaintFor(ship) {
  const chosen = shipPaints[ship.className];
  if (chosen && chosen !== SILHOUETTE) return chosen;
  if (chosen === SILHOUETTE || shipPictureStyle !== 'paint') return null;
  return resolvedHullPaints.get(ship.className)?.[0]?.item || null;
}

/**
 * Every ship picture drawn this page load, so a paint picked anywhere is
 * seen everywhere the hull is pictured. Boxes a re-render has discarded are
 * dropped as they are found, so the set stays the size of the page.
 */
const shipPictureBoxes = new Set();

function redrawShipPictures(vehicleClass) {
  for (const box of shipPictureBoxes) {
    if (box.isConnected === false) { shipPictureBoxes.delete(box); continue; }
    if (box.dataset.className === vehicleClass) box.redraw?.();
  }
}

/**
 * The ship's picture on its card: the game's own render of the hull in the
 * paint the pilot chose, or the game's silhouette tinted by maker. A small
 * button opens the paints the game pictures for that hull. Until the pilot
 * picks, the first paint the game lists stands in - and says it is standing
 * in, because which paint a ship wears is not in the logs.
 */
function shipPicture(ship, maker, options = {}) {
  const box = el('div', 'ship-picture');
  let chosen = shipPaints[ship.className];
  // Unpicked: the first paint the game lists - the default livery when the
  // files hold one - once known; null means "none".
  let standIn = null;
  let failed = false;

  const draw = () => {
    box.textContent = '';
    const wanted = chosen === undefined && shipPictureStyle === 'paint'
      ? standIn?.item : chosen === SILHOUETTE ? null : chosen;
    const paint = failed ? null : wanted;

    if (paint) {
      // A paint render stands alone. The silhouette is the honest fallback if
      // it fails; layering both draws two differently posed ships at once.
      const render = el('div', 'ship-render-wrap');
      const img = document.createElement('img');
      img.className = 'ship-render';
      img.src = `/api/fleet/paints/${encodeURIComponent(paint)}/render`;
      img.alt = '';
      img.loading = 'lazy';
      img.title = chosen
        ? `${ship.name} in the paint you chose — the game's own picture`
        : standIn?.photographed
          ? `${ship.name} in ${standIn.name}, the paint a loadout screenshot showed it wearing on ${new Date(standIn.photographed.shotAt).toLocaleDateString()} — the game's own picture; Paint… to choose another`
          : standIn?.stock
            ? `${ship.name} in its default livery — the game's own picture; Paint… to choose another`
            : `${ship.name} in the first paint the game pictures for it — the files hold no picture of its default livery; Paint… to choose`;
      if (options.onPreview) {
        img.classList.add('ship-picture-clickable');
        img.title += '; click for this ship\'s flight summary';
        img.addEventListener('click', options.onPreview);
      }
      // Shown as the silhouette for now, the pick kept: a render that fails once -
      // the server still converting, a request dropped - is not a retired paint.
      img.addEventListener('error', () => { failed = true; draw(); });
      render.append(img);
      box.append(render);
    } else {
      const outline = el('div', 'ship-outline');
      outline.style.setProperty('--tint', makerTint(maker.code));
      outline.style.setProperty('--outline', `url("/api/fleet/icons/${encodeURIComponent(ship.className)}")`);
      outline.title = `${ship.name} — the game's silhouette, tinted ${maker.name}'s colour; ${options.onPreview ? 'click for this ship\'s flight summary' : 'see the fleet to scale on Hangar'}`;
      outline.addEventListener('click', options.onPreview || (() => showView('hangar')));

      // The mask cannot say whether the file exists; an Image can.
      if (typeof Image === 'function') {
        const probe = new Image();
        probe.addEventListener('error', () => outline.remove());
        probe.src = `/api/fleet/icons/${encodeURIComponent(ship.className)}`;
      }
      box.append(outline);
    }

    const pick = el('button', 'ghost tiny ship-paint', chosen ? 'Paint' : 'Paint…');
    pick.type = 'button';
    pick.title = 'Choose the paint this ship wears, from the ones the game pictures';
    pick.addEventListener('click', () => openPaintChooser(ship, box, pick));
    box.append(pick);
  };

  draw();

  // Nothing picked yet: the silhouette shows while the first paint is looked
  // up, and the render replaces it once the list is in. A pick made in the
  // meantime wins - the lookup redraws only if the box is still unpicked.
  if (chosen === undefined && shipPictureStyle === 'paint' && ship.className) {
    paintsForHull(ship.className).then((paints) => {
      standIn = paints[0] || null;
      if (standIn && chosen === undefined) draw();
    });
  }

  // The chooser redraws every box of this hull, wherever each sits - the
  // Fleet card, the Hangar card, the Garage's model - rather than only its
  // own. Fleet does not re-render on entry, and a pick made on the Garage
  // used to reach its card only after a reload.
  box.redraw = () => { chosen = shipPaints[ship.className]; failed = false; draw(); };
  box.dataset.className = ship.className || '';
  shipPictureBoxes.add(box);
  return box;
}

async function openPaintChooser(ship, box, button) {
  button.disabled = true;

  // An empty list is what the fetch resolves to when the server cannot say.
  const paints = await paintsForHull(ship.className);

  const select = document.createElement('select');
  select.className = 'select ship-paint-select';
  select.setAttribute('aria-label', `Paint for ${ship.name}`);
  select.append(new Option('Silhouette, tinted by maker', SILHOUETTE));
  const unpicked = !shipPaints[ship.className];
  paints.forEach((paint, i) => select.append(new Option(
    paint.photographed
      ? `${paint.name} (photographed ${new Date(paint.photographed.shotAt).toLocaleDateString()}${i === 0 && unpicked ? ', shown until you pick' : ''})`
      : i === 0 && unpicked ? `${paint.name} (shown until you pick)` : paint.name,
    paint.item)));
  if (!paints.length) select.append(new Option('The game pictures no paint for this hull', '', false, false));
  // Unpicked shows the first paint, so that is where the list opens.
  select.value = shipPaints[ship.className] || paints[0]?.item || SILHOUETTE;

  select.addEventListener('change', () => {
    rememberShipPaint(ship.className, select.value || null);
    redrawShipPictures(ship.className);
    renderHangar();
  });

  // The select takes the button's place in the box.
  const box2 = button.parentElement;
  button.remove();
  box2?.append(select);
  select.focus?.();
}

function makerOf(shipName) {
  const words = String(shipName).trim().split(/\s+/);

  for (let take = Math.min(3, words.length); take >= 1; take--) {
    const code = makerAliases.get(words.slice(0, take).join(' ').toLowerCase());

    if (code) {
      return {
        code,
        name: MANUFACTURERS[code] || code,
        model: words.slice(take).join(' ') || shipName,
      };
    }
  }

  return { code: null, name: words[0], model: words.slice(1).join(' ') || shipName };
}

/** The active ship deserves the same manufacturer mark as the Fleet page. */
function renderNowShip(shipName) {
  $('#now-ship').textContent = shipName || '—';

  const badge = $('#now-ship-logo');
  badge.textContent = '';
  const maker = shipName && makerOf(shipName);
  const hasLogo = maker?.code && MANUFACTURER_LOGOS.has(maker.code);
  badge.hidden = !hasLogo;
  if (!hasLogo) return;

  const image = document.createElement('img');
  image.src = `assets/manufacturers/${maker.code}.png`;
  image.alt = maker.name;
  image.title = maker.name;
  badge.append(image);
}

async function loadManufacturers() {
  try {
    const table = await getJson('/api/manufacturers');
    for (const [code, name] of Object.entries(table))
      if (!MANUFACTURERS[code]) MANUFACTURERS[code] = name;

    // The new names are new ways for a ship to announce its maker.
    buildMakerAliases();
  } catch { /* community data off; the fallback covers the common fleet */ }
}

const money = (n) => `${Math.round(Number(n) || 0).toLocaleString()} aUEC`;

/* ---------- fleet ---------- */

/* Kept so the filter controls can re-render without another fetch. */
let libraryStats = null;

/* A named Vehicle Loadout Manager reading proves that this hull was available
 * to fit, even when the log never saw it leave a pad. Keep that evidence in
 * the Fleet roster rather than letting a later Fleet Manager photograph make
 * the hull disappear. It is deliberately separate from libraryStats: the
 * latter is the flight-log aggregate and must not acquire invented sorties. */
let photographedFleetShips = [];

function fleetRoster(stats) {
  const known = new Set((stats?.ships || []).map((ship) => ship.name.toLowerCase()));
  return [
    ...(stats?.ships || []),
    ...photographedFleetShips.filter((ship) => !known.has(ship.name.toLowerCase()))
  ];
}

function renderFleet(stats) {
  libraryStats = stats;
  const roster = fleetRoster(stats);

  // Unticked ships are not owned - a rental, or since sold - so every total
  // ignores them. Flight time and sorties still count: those happened.
  const owned = roster.filter((s) => !excludedShips.has(s.name));

  // The game's entitlement count bundles ships and ground vehicles into one
  // number and never names them, so it is labelled as its own thing rather
  // than pretending to agree with the ticked roster.
  const fleetTiles = [
    ['Owned per game*', stats.fleetSize ?? '—'],
    ['Roster ticked', `${owned.length} of ${roster.length}`],
    ['Total flights', owned.reduce((sum, s) => sum + s.sorties, 0)],
    ['Time aboard', `~${duration(owned.reduce((sum, s) => sum + toSeconds(s.estimatedTime), 0))}`],
  ];

  if (assetsData?.priced) {
    const value = owned.reduce((sum, s) => sum + shipPriceOf(s.name), 0);
    fleetTiles.push(['Fleet value*', money(value)]);
  }

  tiles('#fleet-summary', fleetTiles);

  drawFleetChart(stats.fleetHistory || []);
  renderFleetShips();
  renderShipPlan();
  refreshTradeAdvice(nowState?.location).catch(() => {});
  // The briefing's trade leads are gated on the plan too, and its refresh is
  // keyed on place and ship - so the roster landing has to wake it, or the
  // leads stay as the first tick left them until the pilot moves.
  reloadPilotBriefing().catch(() => {});
}

/** UEX price for one roster ship, 0 when unpriced or assets are off. */
function shipPriceOf(name) {
  const row = assetsData?.fleet?.find((f) => f.name === name);
  return row?.price ? Number(row.price.price) : 0;
}

/** The compare button lives in the Fleet controls, while each card owns its selection. */
function renderFleetComparison() {
  const box = $('#fleet-compare');
  if (!box) return;

  box.textContent = '';
  if (hangarComparison.size < 2) {
    box.append(el('span', 'muted', `Compare ${hangarComparison.size}/2`));
    return;
  }

  const open = el('button', 'ghost fleet-compare-open', 'Compare in Hangar');
  open.type = 'button';
  open.title = `Draw ${[...hangarComparison].join(' and ')} to one scale`;
  open.addEventListener('click', () => {
    const mode = $('#hangar-mode');
    if (mode) mode.value = 'scale';
    showView('hangar');
  });
  box.append(open);
}

/** Loads dimensions only for a preview: Fleet itself needs no game-data request to list flights. */
async function hangarPreviewFor(ship) {
  if (!hangarPreviewShips) {
    hangarPreviewShips = getJson('/api/fleet/hangar')
      .then((data) => data?.ships || [])
      .catch(() => []);
  }
  return (await hangarPreviewShips).find((s) => s.className === ship.className || s.name === ship.name) || null;
}

function toggleShipPreview(ship, card) {
  const body = card.querySelector('.ship-body');
  const existing = body?.querySelector('.ship-preview');
  if (existing) {
    existing.remove();
    return;
  }
  if (!body) return;

  const preview = el('div', 'ship-preview', ship.photographedAt
    ? `fit photographed ${relative(ship.photographedAt)} · no flights logged.`
    : `${ship.sorties} sortie${ship.sorties === 1 ? '' : 's'} · ~${duration(toSeconds(ship.estimatedTime))} aboard · last flown ${relative(ship.lastFlown)}.`);
  body.append(preview);

  hangarPreviewFor(ship).then((sized) => {
    // The card may have been redrawn by a filter while the game-data request
    // was in flight; never put a late answer into a discarded preview.
    if (preview.parentElement !== body) return;
    preview.textContent += sized?.length > 0
      ? ` ${sized.length} × ${sized.beam} × ${sized.height} m from the installed vehicle table.`
      : ' This install has no measured size for it.';
  });
}

/** Applies the roster controls without changing what the flight log says. */
function renderFleetShips() {
  const grid = $('#fleet-ships');
  const vehicleGrid = $('#fleet-vehicles');
  grid.textContent = '';
  vehicleGrid.textContent = '';

  if (!libraryStats) return;

  const term = ($('#fleet-search').value || '').trim().toLowerCase();
  const days = Number($('#fleet-period').value) || 0;
  const cutoff = days ? Date.now() - days * 86400000 : null;
  const filter = $('#fleet-filter')?.value || 'all';
  const picture = $('#fleet-picture');
  if (picture) picture.value = shipPictureStyle;

  // Unticked ships stay on the page, struck through - this is where the tick
  // lives, so hiding them would make the choice irreversible. They sort to
  // the back and count for nothing.
  const roster = fleetRoster(libraryStats);
  const ships = roster.filter((s) => {
    const grounded = s.reference && !s.reference.isSpaceship;
    if (term && !s.name.toLowerCase().includes(term)) return false;
    if (cutoff && new Date(s.lastFlown).getTime() < cutoff) return false;
    if (filter === 'favourites' && !favouriteShips.has(s.name)) return false;
    if (filter === 'recent' && !isRecentlyFlown(s)) return false;
    if (filter === 'ships' && grounded) return false;
    if (filter === 'ground' && !grounded) return false;
    return true;
  }).sort((a, b) =>
    Number(excludedShips.has(a.name)) - Number(excludedShips.has(b.name))
    || Number(favouriteShips.has(b.name)) - Number(favouriteShips.has(a.name)));

  // Ships and ground vehicles part ways on the community reference; anything
  // unmatched is assumed to fly.
  const vehicles = ships.filter((s) => s.reference && !s.reference.isSpaceship);
  $('#fleet-vehicles-title').hidden = vehicles.length === 0;

  if (!ships.length) {
    grid.append(el('p', 'muted',
      roster.length ? 'No ships match that filter.' : 'No ships recorded yet.'));
    return;
  }

  renderFleetComparison();

  for (const ship of ships) {
    const grounded = ship.reference && !ship.reference.isSpaceship;
    const off = excludedShips.has(ship.name);

    const maker = makerOf(ship.name);
    const card = el('article', off ? 'ship-card excluded' : 'ship-card');

    // The Owned tick: untick a rental or a ship since sold and it leaves
    // every total on this page. Remembered per browser.
    const tick = el('label', 'own-tick');
    const box = document.createElement('input');
    box.type = 'checkbox';
    box.checked = !off;
    box.title = off ? 'Not owned - tick to count it again' : 'Owned - untick if rented or sold';

    box.addEventListener('change', () => {
      if (box.checked) excludedShips.delete(ship.name);
      else {
        excludedShips.add(ship.name);
        // A comparison promises two ships on the Hangar deck. Leaving an
        // excluded ship selected would quietly turn it into a one-ship view.
        hangarComparison.delete(ship.name);
      }
      try {
        localStorage.setItem('qw-assets-excluded', JSON.stringify([...excludedShips]));
      } catch { /* fine */ }
      renderFleet(libraryStats);
      renderAssets();
    });

    tick.append(box);
    card.append(tick);

    const favourite = el('button', favouriteShips.has(ship.name) ? 'ghost ship-favourite active' : 'ghost ship-favourite', favouriteShips.has(ship.name) ? '★' : '☆');
    favourite.type = 'button';
    favourite.title = favouriteShips.has(ship.name) ? 'Favourite — click to remove' : 'Favourite this ship';
    favourite.addEventListener('click', () => {
      if (favouriteShips.has(ship.name)) favouriteShips.delete(ship.name);
      else favouriteShips.add(ship.name);
      try { localStorage.setItem('qw-favourite-ships', JSON.stringify([...favouriteShips])); } catch { /* fine */ }
      renderFleetShips();
    });
    card.append(favourite);

    const badge = el('div', 'ship-logo');
    if (maker.code && MANUFACTURER_LOGOS.has(maker.code)) {
      const img = document.createElement('img');
      img.src = `assets/manufacturers/${maker.code}.png`;
      img.alt = maker.name;
      img.loading = 'lazy';
      badge.append(img);
    } else {
      badge.append(el('span', 'ship-logo-text', maker.code || maker.name));
    }
    card.append(badge);

    // The ship's picture: the paint the pilot chose, painted, or the game's
    // silhouette tinted by maker. A missing silhouette takes the frame out
    // rather than leaving it broken - not every hull has one in the files.
    if (ship.className) card.append(shipPicture(ship, maker, { onPreview: () => toggleShipPreview(ship, card) }));

    const body = el('div', 'ship-body');
    body.append(el('div', 'ship-name', maker.model));
    body.append(el('div', 'ship-maker', maker.name));

    const stat = el('div', 'ship-stats');
    stat.append(el('b', null, String(ship.sorties)));
    stat.append(el('span', null, ` flight${ship.sorties === 1 ? '' : 's'}`));

    const seconds = toSeconds(ship.estimatedTime);
    if (seconds > 0) stat.append(el('span', 'note-inline', ` · ~${duration(seconds)}`));

    body.append(stat);
    body.append(el('div', 'ship-seen', ship.photographedAt
      ? `fit photographed ${relative(ship.photographedAt)} · no flights logged`
      : `last flown ${relative(ship.lastFlown)}`));

    const statuses = el('div', 'ship-status');
    if (favouriteShips.has(ship.name)) statuses.append(el('span', 'ship-status-mark favourite', '★ favourite'));
    if (isRecentlyFlown(ship)) statuses.append(el('span', 'ship-status-mark recent', '● flown this week'));
    if (off) statuses.append(el('span', 'ship-status-mark excluded', '⊘ out of Hangar'));
    if (statuses.children.length) body.append(statuses);

    // Community reference, when enabled and matched: what the ship is for and
    // what losing one costs.
    if (ship.reference) {
      const r = ship.reference;
      const bits = [];

      if (r.role && r.career && r.role !== r.career) bits.push(`${r.career} · ${r.role}`);
      else if (r.role || r.career) bits.push(r.role || r.career);
      if (r.crew > 0) bits.push(`crew ${r.crew}`);

      if (bits.length)
        body.append(el('div', 'ship-ref', bits.join(' · ')));

      if (r.expeditedCost > 0) {
        body.append(el('div', 'ship-ref muted',
          `claim: expedite ${money(r.expeditedCost)}`
          + (r.standardClaimTime ? ` · ~${Math.round(r.standardClaimTime)}m wait` : '')));
      }
    }

    // The blended-in asset side: what buying one costs in game, when the
    // price tables know it.
    const assetRow = assetsData?.fleet?.find((f) => f.name === ship.name);

    if (assetsData?.priced) {
      body.append(assetRow?.price
        ? el('div', 'ship-price', `${money(assetRow.price.price)} · ${assetRow.price.terminal}`)
        : el('div', 'ship-price muted', 'not sold in game'));
    }

    // A rentable model might be a rental rather than yours; the card says so
    // and leaves the tick to the only person who knows.
    if (assetRow?.rental) {
      const hint = el('div', 'ship-rental muted',
        `rentable ${money(assetRow.rental.price)} at ${assetRow.rental.terminal}`);
      hint.title = 'If this one was rented, untick it above';
      body.append(hint);
    }

    // Ground vehicles have no ports anyone sells parts for, so the offer is
    // made only where it can be kept.
    if (!grounded) {
      const garage = el('button', 'ghost ship-upgrade', 'Garage');
      garage.title = `${ship.name}'s numbers, what fits it, and what a part would change`;
      garage.addEventListener('click', () => openGarageFor(ship.className || ship.name));
      body.append(garage);
    }

    const compare = el('button', hangarComparison.has(ship.name) ? 'ghost tiny ship-compare active' : 'ghost tiny ship-compare', hangarComparison.has(ship.name) ? 'Selected to compare' : 'Compare');
    compare.type = 'button';
    compare.disabled = off || !!ship.photographedAt;
    compare.title = off
      ? 'Tick this ship as owned before comparing it in Hangar'
      : ship.photographedAt
        ? 'A photographed fit has no flight or size record to compare in Hangar'
      : 'Select this ship and one other, then compare them in Hangar';
    compare.addEventListener('click', () => {
      if (hangarComparison.has(ship.name)) hangarComparison.delete(ship.name);
      else {
        if (hangarComparison.size === 2) hangarComparison.clear();
        hangarComparison.add(ship.name);
      }
      renderFleetShips();
    });
    body.append(compare);

    card.append(body);
    (grounded ? vehicleGrid : grid).append(card);
  }
}

/* ---------- what fits a ship, and where it is sold ---------- */

/** "3 days ago", "2 months ago" - easier to scan than a date. */
function relative(iso) {
  if (!iso) return 'unknown';

  const days = Math.floor((Date.now() - new Date(iso).getTime()) / 86400000);
  if (days <= 0) return 'today';
  if (days === 1) return 'yesterday';
  if (days < 30) return `${days} days ago`;

  const months = Math.round(days / 30);
  return months <= 1 ? 'a month ago' : `${months} months ago`;
}

/** Step chart of owned-vehicle count over time. */
function drawFleetChart(history) {
  const svg = $('#fleet-chart');
  svg.textContent = '';

  if (history.length < 2) {
    const text = svgEl('text', { x: 500, y: 110, 'text-anchor': 'middle', class: 'map-label' });
    text.textContent = 'NOT ENOUGH DATA YET';
    svg.append(text);
    return;
  }

  const max = Math.max(...history.map((p) => p.vehicles));
  const min = Math.min(...history.map((p) => p.vehicles));
  const span = Math.max(1, max - min);

  const x = (i) => 30 + (i / (history.length - 1)) * 940;
  const y = (v) => 190 - ((v - min) / span) * 150;

  // Baseline and top gridlines.
  for (const value of [min, max]) {
    svg.append(svgEl('line', {
      x1: 30, y1: y(value), x2: 970, y2: y(value),
      stroke: 'rgba(53,200,240,.12)', 'stroke-width': '1',
    }));
    const label = svgEl('text', { x: 8, y: y(value) + 4, class: 'map-label' });
    label.textContent = String(value);
    svg.append(label);
  }

  // Fleet size only ever steps up, so a step line is the honest shape.
  let path = `M ${x(0)} ${y(history[0].vehicles)}`;
  history.forEach((point, i) => {
    if (i === 0) return;
    path += ` L ${x(i)} ${y(history[i - 1].vehicles)} L ${x(i)} ${y(point.vehicles)}`;
  });

  svg.append(svgEl('path', {
    d: path, fill: 'none', stroke: '#35c8f0', 'stroke-width': '2', filter: 'url(#glow)',
  }));

  history.forEach((point, i) => {
    if (i % Math.ceil(history.length / 40) !== 0) return;
    svg.append(svgEl('circle', { cx: x(i), cy: y(point.vehicles), r: 2.5, fill: '#7fe4ff' }));
  });

  // Reuse the map's glow filter definition.
  const defs = svgEl('defs');
  const glow = svgEl('filter', { id: 'glow', x: '-60%', y: '-60%', width: '220%', height: '220%' });
  glow.append(svgEl('feGaussianBlur', { stdDeviation: '2.4', result: 'b' }));
  const merge = svgEl('feMerge');
  merge.append(svgEl('feMergeNode', { in: 'b' }));
  merge.append(svgEl('feMergeNode', { in: 'SourceGraphic' }));
  glow.append(merge);
  defs.append(glow);
  svg.prepend(defs);
}

/* ---------- spending ---------- */

function renderSpending(stats) {
  const net = Number(stats.net) || 0;

  tiles('#spend-summary', [
    ['Cargo income', money(stats.income)],
    ['Item spend', money(stats.spend)],
    ['Cargo spend', money(stats.commoditySpend)],
    [net >= 0 ? 'Net gain' : 'Net loss', money(Math.abs(net))],
    ['Purchases', stats.purchaseCount],
    ['Cargo trades', stats.tradeCount],
  ]);

  if (stats.tradeShops && stats.tradeShops.length) {
    bars('#trade-chart',
      stats.tradeShops.map((s) => ({
        label: s.name,
        value: Number(s.total),
        note: `${s.quantity} SCU`,
      })),
      money);
  } else {
    $('#trade-chart').textContent = '';
    $('#trade-chart').append(el('p', 'muted', 'No commodity sales recorded yet.'));
  }

  bars('#shops-chart',
    stats.shops.slice(0, 15).map((s) => ({ label: s.name, value: s.count })),
    (v) => `${v} buy${v === 1 ? '' : 's'}`);

  bars('#items-chart',
    stats.items.slice(0, 20).map((i) => ({
      label: i.name,
      value: Number(i.total),
      note: i.quantity > 1 ? `×${i.quantity}` : null,
    })),
    money);
}

/* ---------- loadout ---------- */

/**
 * Slot glyphs, drawn in the HUD's own line style.
 *
 * Not from the Fankit - it carries logos and wallpapers, not equipment icons -
 * and not lifted from the game files, which the Fankit Agreement does not
 * cover. Original 24x24 strokes on currentColor, so they follow the theme.
 */
const SLOT_ICONS = {
  helmet: 'M5 17v-4a7 7 0 0 1 14 0v4l-2 2H7z M8.5 13h7',
  torso: 'M7 4 4 7v7l3 6h10l3-6V7l-3-3z M9 12l3 3 3-3 M12 4v3',
  arms: 'M5 19v-7a7 7 0 0 1 7-7h7 M9 19v-4a5 5 0 0 1 5-5h5',
  legs: 'M8 4v7l-2 9 M16 4v7l2 9 M8 4h8 M12 11v9',
  undersuit: 'M12 8a2.5 2.5 0 1 0 0-5 2.5 2.5 0 0 0 0 5z M6 20v-2a6 6 0 0 1 12 0v2',
  backpack: 'M7 8h10v12H7z M9 8V6a3 3 0 0 1 6 0v2 M9 15h6',
  rifle: 'M2 11h12l1-3h4v3h3v2h-8l-1 3h-3l1-3H8l-1 3H4l1-3H2z',
  pistol: 'M4 9h14v4h-4l-1 5h-4l1-5H4z M16 9V7',
  magazine: 'M9 4h7l-1 8c-.3 2-1.2 4-3.2 4H9z M10 8h5',
  optic: 'M10 16a4 4 0 1 0 0-8 4 4 0 0 0 0 8z M10 14a2 2 0 1 0 0-4 2 2 0 0 0 0 4z M14 12h7',
  attachment: 'M4 10h12v4H4z M16 11h4v2h-4 M7 10V8h6v2',
  grenade: 'M9 9h6v7a3 3 0 0 1-3 3 3 3 0 0 1-3-3z M10 9V6h4v3 M14 5a2.5 2.5 0 1 1 5 0',
  medical: 'M10 4h4v6h6v4h-6v6h-4v-6H4v-4h6z',
  tool: 'M13 6a4 4 0 0 1 6-3l-3 3 2 2 3-3a4 4 0 0 1-5 5L8 18l-2-2z',
  light: 'M8 3h6v3l-2 3v11h-2V9L8 6z M16 5h3 M16 9h5 M16 13h3',
  mobiglas: 'M8 8h8v8H8z M4 10v4 M20 10v4 M10 11h4',
  shirt: 'M8 4 4 7l2 3 2-1v11h8V9l2 1 2-3-4-3a4 4 0 0 1-8 0z',
  box: 'M4 8l8-4 8 4v8l-8 4-8-4z M4 8l8 4 8-4 M12 12v8',
  diamond: 'M12 3l7 9-7 9-7-9z M12 8l3 4-3 4-3-4z',
};

/** Slot first, category as the fallback, diamond when nothing matches. */
function slotIconKey(slot) {
  const name = `${(slot.port || '')} ${(slot.label || '')}`.toLowerCase();

  const byName = [
    ['helmet', 'helmet'], ['undersuit', 'undersuit'], ['backpack', 'backpack'],
    ['core', 'torso'], ['torso', 'torso'], ['chest', 'torso'],
    ['arms', 'arms'], ['shoulder', 'arms'], ['legs', 'legs'],
    ['sidearm', 'pistol'], ['pistol', 'pistol'],
    ['magazine', 'magazine'], ['optic', 'optic'], ['scope', 'optic'],
    ['barrel', 'attachment'], ['underbarrel', 'attachment'],
    ['grenade', 'grenade'], ['medpen', 'medical'], ['oxypen', 'medical'],
    ['multitool', 'tool'], ['tool', 'tool'],
    ['flashlight', 'light'], ['light', 'light'], ['mobiglas', 'mobiglas'],
    ['wep', 'rifle'], ['weapon', 'rifle'],
  ];

  for (const [needle, icon] of byName)
    if (name.includes(needle)) return icon;

  return {
    'Weapons': 'rifle',
    'Weapon attachments': 'attachment',
    'Throwables': 'grenade',
    'Armour': 'torso',
    'Medical': 'medical',
    'Utility': 'tool',
    'Carried': 'box',
    'Appearance': 'shirt',
  }[slot.category] ?? 'diamond';
}

function slotIconSvg(slot) {
  const path = SLOT_ICONS[slotIconKey(slot)] ?? SLOT_ICONS.diamond;

  return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" '
    + 'stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" '
    + `aria-hidden="true"><path d="${path}"/></svg>`;
}

/**
 * A character screen needs a stable centre, not a wall of interchangeable
 * cards. Slots still come from the log and may grow in future game patches,
 * so the figure is a visual anchor only: every observed slot remains a real,
 * named card on one of its two sides.
 */
function loadoutPlacement(slot) {
  const name = `${slot.port || ''} ${slot.label || ''} ${slot.category || ''}`.toLowerCase();

  if (/helmet/.test(name)) return 'head';
  if (/undersuit/.test(name)) return 'base';
  if (/(core|torso|chest)/.test(name)) return 'core';
  if (/backpack/.test(name)) return 'back';
  if (/(arm|glove|shoulder)/.test(name)) return 'arms';
  if (/(leg|shoe|boot)/.test(name)) return 'legs';
  return null;
}

/* The core is the player's main armour signal.  The log does not promise an
   armour tier, so only an explicit catalogue/type name changes the profile. */
function loadoutArmorProfile(equipped) {
  const core = equipped.find((slot) => loadoutPlacement(slot) === 'core');
  const hasUndersuit = equipped.some((slot) => loadoutPlacement(slot) === 'base');
  const signal = core
    ? [core.port, core.label, ...core.items.flatMap((item) => [
      item.name, item.reference?.name, item.reference?.type, item.reference?.subType,
    ])].filter(Boolean).join(' ').toLowerCase()
    : '';

  if (/super[ _-]*heavy/.test(signal))
    return { id: 'super-heavy', label: 'Super-heavy', art: 'assets/loadout-pilot-super-heavy-v1.png' };
  if (/\bheavy\b/.test(signal))
    return { id: 'heavy', label: 'Heavy', art: 'assets/loadout-pilot-heavy-v1.png' };
  if (/\bmedium\b/.test(signal))
    return { id: 'medium', label: 'Medium', art: 'assets/loadout-pilot-v1.png' };
  if (/\blight\b/.test(signal))
    return { id: 'light', label: 'Light', art: 'assets/loadout-pilot-light-v1.png' };

  // An undersuit is the base layer, not the lightest armour tier. It remains
  // visible until the log can actually classify a core as light or heavier.
  if (hasUndersuit)
    return { id: 'undersuit', label: 'Undersuit', art: 'assets/loadout-pilot-undersuit-v1.png' };

  return { id: 'neutral', label: 'Unclassified', art: 'assets/loadout-pilot-v1.png' };
}

function loadoutFigure(equipped) {
  const observed = new Set(equipped.map(loadoutPlacement));
  const profile = loadoutArmorProfile(equipped);
  const observedZones = ['head', 'core', 'base', 'back', 'arms', 'legs']
    .filter((part) => observed.has(part));
  const observedParts = ['head', 'core', 'base', 'back', 'arms', 'legs']
    .filter((part) => observed.has(part))
    .map((part) => `loadout-has-${part}`)
    .join(' ');
  const figure = el('div', `loadout-figure loadout-profile-${profile.id} ${observedParts}`);
  figure.innerHTML = `
    <div class="loadout-figure-tag">${profile.label.toUpperCase()} ARMOUR PROFILE</div>
    <div class="loadout-figure-status"><b>${observedZones.length}/6</b> BODY ZONES OBSERVED</div>
    <div class="loadout-pilot-frame">
      <img class="loadout-pilot-art" src="${profile.art}" alt="" />
      <span class="loadout-pilot-zone loadout-pilot-zone-head"></span>
      <span class="loadout-pilot-zone loadout-pilot-zone-core"></span>
      <span class="loadout-pilot-zone loadout-pilot-zone-base"></span>
      <span class="loadout-pilot-zone loadout-pilot-zone-back"></span>
      <span class="loadout-pilot-zone loadout-pilot-zone-arms"></span>
      <span class="loadout-pilot-zone loadout-pilot-zone-legs"></span>
    </div>
    <div class="loadout-figure-key"><span>HEAD</span><span>CORE</span><span>BASE</span><span>PACK</span><span>OBSERVED ZONES LIT</span></div>`;
  return figure;
}

/** The community catalogue is optional, so every detail has an honest fallback. */
function loadoutItemName(item) {
  return item.reference?.name || prettyItem(item.name);
}

function loadoutItemFacts(item) {
  const ref = item.reference;
  if (!ref)
    return { text: 'Game-log item class only', known: false };

  const facts = [];
  if (ref.manufacturer) facts.push(ref.manufacturer);
  const kind = [ref.type, ref.subType].filter(Boolean).join(' / ');
  if (kind) facts.push(kind);
  if (ref.size > 0) facts.push(`S${ref.size}`);
  if (ref.grade > 0) facts.push(`Grade ${gradeLetter(ref.grade)}`);
  return { text: facts.join(' · ') || 'Catalogue entry has no extra specification', known: true };
}

function loadoutSlotContents(slot, compact = false) {
  const body = el('div', 'slot-body');
  body.append(el('div', 'slot-category', slot.category || 'Other'));

  const label = slot.slotCount > 1
    ? `${slot.label || slot.port} · ${slot.slotCount} slots`
    : slot.label || slot.port;
  body.append(el('div', 'card-label', label));

  for (const item of slot.items) {
    const line = el('div', 'slot-current');
    line.append(el('span', null, loadoutItemName(item)));
    if (item.count > 1) line.append(el('span', 'slot-multi', ` ×${item.count}`));
    body.append(line);

    const facts = loadoutItemFacts(item);
    body.append(el('div', facts.known ? 'slot-spec' : 'slot-spec slot-spec-unknown', facts.text));
  }

  if (!compact && slot.currentSeen)
    body.append(el('div', 'slot-when', `last observed ${relative(slot.currentSeen)}`));
  return body;
}

function loadoutItemInspect(slot) {
  const inspect = el('div', 'loadout-item-inspect');
  inspect.setAttribute('role', 'tooltip');
  inspect.append(el('div', 'loadout-inspect-eyebrow', `Inspect · ${slot.label || slot.port}`));

  for (const item of slot.items) {
    const entry = el('div', 'loadout-inspect-entry');
    entry.append(el('strong', null, loadoutItemName(item)));
    if (item.count > 1) entry.append(el('span', 'slot-multi', ` ×${item.count}`));
    const facts = loadoutItemFacts(item);
    entry.append(el('div', facts.known ? 'slot-spec' : 'slot-spec slot-spec-unknown', facts.text));
    inspect.append(entry);
  }

  if (slot.currentSeen)
    inspect.append(el('div', 'loadout-inspect-seen', `Last observed ${relative(slot.currentSeen)}`));
  return inspect;
}

function loadoutEquipSlot(slot, placement) {
  const card = el('article', `loadout-slot loadout-equip-slot loadout-equip-${placement}`);
  card.dataset.category = slot.category || 'Other';
  card.tabIndex = 0;
  card.setAttribute('aria-label', `Inspect ${slot.label || slot.port}`);

  const icon = el('div', 'slot-icon');
  icon.innerHTML = slotIconSvg(slot);
  card.append(icon);
  card.append(loadoutSlotContents(slot, true));
  card.append(loadoutItemInspect(slot));
  return card;
}

function loadoutInventorySlot(slot) {
  const card = el('article', 'loadout-slot loadout-inventory-slot');
  card.dataset.category = slot.category || 'Other';
  card.tabIndex = 0;
  card.setAttribute('aria-label', `Inspect ${slot.label || slot.port}`);
  const icon = el('div', 'slot-icon');
  icon.innerHTML = slotIconSvg(slot);
  card.append(icon);
  card.append(loadoutSlotContents(slot));
  card.append(loadoutItemInspect(slot));
  return card;
}

/* A readiness strip is a briefing on the same observed kit as the cards, not
   a live-inventory verdict. Keep it outside the search result so looking for
   one attachment does not make the rest of the recorded kit disappear. */
function loadoutReadiness(slots, completeSighting) {
  const strip = el('section', 'loadout-readiness');
  strip.setAttribute('aria-label', 'Observed kit readiness');
  const zones = [
    ['head', 'Head'], ['core', 'Core'], ['base', 'Base'],
    ['back', 'Pack'], ['arms', 'Arms'], ['legs', 'Legs'],
  ];
  const observed = new Set(slots.map(loadoutPlacement));
  const observedZones = zones.filter(([id]) => observed.has(id));
  const unseenZones = zones.filter(([id]) => !observed.has(id)).map(([, label]) => label);
  const weaponItems = slots
    .filter((slot) => /weapon/i.test(slot.category || ''))
    .flatMap((slot) => slot.items || []);
  const consumableSlots = slots
    .filter((slot) => /medical|throwable/i.test(slot.category || ''));
  const itemCount = (items) => items.reduce((total, item) => total + (Number(item.count) || 1), 0);
  const consumables = consumableSlots.map((slot) =>
    `${itemCount(slot.items || [])} ${slot.label || slot.category}`.toLowerCase());
  const latestSlotSighting = slots.map((slot) => slot.currentSeen).filter(Boolean).sort().at(-1);
  const sighting = completeSighting || latestSlotSighting;

  const add = (label, value, note, state = '') => {
    const card = el('div', `loadout-readiness-card ${state}`.trim());
    card.append(el('div', 'loadout-readiness-label', label));
    card.append(el('strong', null, value));
    card.append(el('span', null, note));
    strip.append(card);
  };

  add('Coverage', `${observedZones.length}/6 zones observed`,
    unseenZones.length ? `Not observed: ${unseenZones.join(' · ')}` : 'Every body zone was observed',
    unseenZones.length ? 'partial' : 'complete');
  add('Weapons', weaponItems.length
    ? `${weaponItems.length} weapon${weaponItems.length === 1 ? '' : 's'} observed`
    : 'No weapon observed', weaponItems.length
    ? weaponItems.slice(0, 2).map(loadoutItemName).join(' · ')
    : 'The log has no weapon attachment for this kit');
  add('Consumables', consumables.length
    ? `${itemCount(consumableSlots.flatMap((slot) => slot.items || []))} carried`
    : 'No consumables observed', consumables.length
    ? consumables.join(' · ')
    : 'The log has no medical or throwable attachment for this kit');
  add('Sighting', sighting ? `Observed ${relative(sighting)}` : 'No sighting time recorded',
    sighting ? 'Latest complete kit when available' : 'Individual cards may still carry a time');
  return strip;
}

function renderLoadout(stats) {
  libraryStats = stats;

  const host = $('#loadout-grid');
  host.textContent = '';

  if (!stats.loadout || !stats.loadout.length) {
    host.append(el('p', 'muted', 'No attachment events recorded yet.'));
    return;
  }

  const term = ($('#loadout-search').value || '').trim().toLowerCase();

  // Match on the slot name or what currently occupies it. There is no hidden
  // history in this view: this is the kit the log most recently saw, not an
  // inventory the game never exposed to us.
  const slots = stats.loadout.filter((slot) => !term
    || (slot.label || slot.port).toLowerCase().includes(term)
    || slot.items.some((item) => item.name.toLowerCase().includes(term)));

  if (!slots.length) {
    host.append(el('p', 'muted', 'Nothing matches that search.'));
    return;
  }

  const screen = el('section', 'loadout-character');
  const head = el('div', 'loadout-character-head');
  const meta = stats.loadoutAsOf
    ? `Last complete sighting ${relative(stats.loadoutAsOf)}`
    : 'Each card says when the log last saw it.';
  head.append(el('div', 'loadout-eyebrow', term ? `${slots.length} matching slots` : `${slots.length} observed slots`));
  head.append(el('p', 'muted', meta));
  screen.append(head);
  screen.append(el('p', 'loadout-overview',
    'Wearable kit sits around the pilot. Stowed weapons, supplies and tools sit in the Field Kit. '
    + 'Everything here is the latest equipment the log observed, not a live game inventory.'));
  screen.append(loadoutReadiness(stats.loadout, stats.loadoutAsOf));

  const sheet = el('div', 'loadout-sheet');
  const avatarRig = el('div', 'loadout-avatar-rig');
  const left = el('div', 'loadout-equipment loadout-equipment-left');
  const right = el('div', 'loadout-equipment loadout-equipment-right');
  const field = el('aside', 'loadout-field-kit');
  const fieldHead = el('div', 'loadout-field-head');
  fieldHead.append(el('div', 'loadout-eyebrow', 'Field kit'));
  const stowedCount = slots.filter((slot) => !loadoutPlacement(slot)).length;
  fieldHead.append(el('span', 'group-meta', `${stowedCount} stowed slot${stowedCount === 1 ? '' : 's'}`));
  field.append(fieldHead);
  const inventory = el('div', 'loadout-inventory-grid');

  const equipped = slots.filter((slot) => loadoutPlacement(slot));
  const leftSlots = equipped.filter((slot) => ['head', 'base', 'arms'].includes(loadoutPlacement(slot)));
  const rightSlots = equipped.filter((slot) => !leftSlots.includes(slot));

  for (const slot of leftSlots)
    left.append(loadoutEquipSlot(slot, loadoutPlacement(slot)));
  for (const slot of rightSlots)
    right.append(loadoutEquipSlot(slot, loadoutPlacement(slot)));
  for (const slot of slots.filter((slot) => !loadoutPlacement(slot)))
    inventory.append(loadoutInventorySlot(slot));

  // A sparse log is normal. Keep both sides balanced rather than making a
  // character frame lean just because one attachment type was never logged.
  if (!left.childElementCount) left.append(el('div', 'loadout-empty-slot', 'No observed body slots'));
  if (!right.childElementCount) right.append(el('div', 'loadout-empty-slot', 'No observed body slots'));
  if (!inventory.childElementCount) inventory.append(el('p', 'muted', 'No stowed kit observed.'));

  avatarRig.append(left, loadoutFigure(equipped), right);
  field.append(inventory);
  sheet.append(avatarRig, field);
  screen.append(sheet);
  host.append(screen);
}

/**
 * Builds a list that shows `limit` items and reveals the rest on click.
 * Truncation is skipped while a search is active, since the user has already
 * narrowed the set and hiding matches would be perverse.
 */
function expandableList(card, items, limit, renderItem, expanded) {
  const list = el('ul', 'slot-list');

  items.forEach((item, index) => {
    const li = renderItem(item);
    if (!expanded && index >= limit) li.classList.add('extra');
    list.append(li);
  });

  card.append(list);

  if (expanded || items.length <= limit)
    return;

  const hidden = items.length - limit;
  const toggle = el('button', 'more-toggle', `show ${hidden} more`);

  toggle.addEventListener('click', () => {
    const showing = list.classList.toggle('show-all');
    toggle.textContent = showing ? 'show less' : `show ${hidden} more`;
  });

  card.append(toggle);
}

/** A category heading with a count on the right. */
const prettyItem = (name) => name.replace(/_/g, ' ');

/* ---------- stash ---------- */

/**
 * "Everything ever seen" unions every listing instead of trusting the newest.
 * It matters because a listing is only a page: glancing at one tab of an
 * inventory replaces a full browse, and the place looks emptied. Fetched
 * separately, since the server decides which view to build.
 */
let stashEverSeen = null;

async function renderStash(stats) {
  libraryStats = stats;

  const grid = $('#stash-grid');
  grid.textContent = '';

  if ($('#stash-ever')?.checked) {
    if (!stashEverSeen) {
      try {
        stashEverSeen = await getJson('/api/stash?everSeen=true');
      } catch {
        stashEverSeen = [];
      }
    }

    stats = { ...stats, stash: stashEverSeen };
  }

  if (!stats.stash || !stats.stash.length) {
    grid.append(el('p', 'muted',
      'Nothing recorded yet. Open a local inventory in game and it will appear here.'));
    return;
  }

  const term = ($('#stash-search').value || '').trim().toLowerCase();
  const days = Number($('#stash-period').value) || 0;
  const cutoff = days ? Date.now() - days * 86400000 : null;
  const latestOnly = $('#stash-latest').checked;

  // The same item often sits in several stashes. When asked, keep only the
  // place it was most recently seen, so "where is my MedPen" has one answer.
  const newestPlace = new Map();

  if (latestOnly) {
    for (const place of stats.stash) {
      for (const group of place.groups) {
        for (const item of group.items) {
          const seen = new Date(item.lastSeen).getTime();
          const best = newestPlace.get(item.name);
          if (!best || seen > best.seen) newestPlace.set(item.name, { seen, place: place.locationId });
        }
      }
    }
  }

  // Searching by place keeps the whole location; searching by item narrows to
  // the matching items, so "where is my sniper" answers in one glance. The
  // period filter always applies per item, since a location's most recent visit
  // says nothing about when a particular item was last seen in it.
  const places = stats.stash
    .map((place) => {
      const placeHit = term && place.name.toLowerCase().includes(term);

      const groups = place.groups
        .map((g) => ({
          ...g,
          items: g.items.filter((i) => {
            if (cutoff && new Date(i.lastSeen).getTime() < cutoff) return false;
            if (term && !placeHit && !i.name.toLowerCase().includes(term)) return false;
            if (latestOnly && newestPlace.get(i.name)?.place !== place.locationId) return false;
            return true;
          }),
        }))
        .filter((g) => g.items.length);

      if (!groups.length) return null;

      return {
        ...place,
        groups,
        itemCount: groups.reduce((n, g) => n + g.items.length, 0),
        // Recomputed from what survived the filter, so a narrowed view does not
        // keep quoting the whole stash's volume.
        microScu: groups.reduce(
          (n, g) => n + g.items.reduce((v, i) => v + (i.microScu || 0), 0), 0),
      };
    })
    .filter(Boolean);

  if (!places.length) {
    grid.append(el('p', 'muted', 'Nothing matches that search.'));
    return;
  }

  for (const place of places) {
    const card = el('article', 'card');
    { const label = el('div', 'card-label'); label.append(placeLink(place.name)); card.append(label); }
    // Volume as well as a count. A count says how much stuff; this says whether
    // it fits, which is the question a hold asks. Only 9,000 of the install's
    // items carry a real one, so it is left off rather than shown as nothing.
    const measured = place.microScu > 0 ? ` · ${volume(place.microScu)}` : '';

    card.append(el('div', 'sub',
      `${place.itemCount} item types${measured} · last seen ${dateOf(place.lastSeen)}`));

    for (const group of place.groups) {
      const head = el('div', 'stash-group');
      head.append(el('span', 'stash-group-name', group.category));
      head.append(el('span', 'slot-count', String(group.items.length)));
      card.append(head);

      expandableList(card, group.items, 8, (item) => {
        const li = el('li');
        li.append(el('span', 'slot-item', prettyItem(item.name)));
        li.append(el('span', 'slot-count', relative(item.lastSeen)));
        return li;
      }, Boolean(term));
    }

    grid.append(card);
  }
}

/* ---------- map ---------- */

const SVG_NS = 'http://www.w3.org/2000/svg';
const svgEl = (tag, attrs = {}) => {
  const node = document.createElementNS(SVG_NS, tag);
  for (const [key, value] of Object.entries(attrs)) node.setAttribute(key, value);
  return node;
};

/**
 * Renders visited places as a system topology map.
 *
 * This is deliberately not a positional radar: Star Citizen logs no player
 * coordinates, so bodies are laid out on fixed rings and each location is
 * clustered around the body it belongs to. Node size encodes visit count.
 */
/* ---------- map ---------- */

/**
 * Every place in the game, visited or not, with the layout worked out once.
 * Positions are cached by raw id so the live marker and "centre on me" can find
 * a node without re-running the layout.
 */
let atlas = [];
const nodeAt = new Map();

// A system view is the honest default: its bodies preserve the bearings and
// relative distances supplied by the community starmap. The network is useful
// for planning jump legs, but says out loud that its triangle has no scale.
const MAP_MODE_KEY = 'qw-map-mode';
const MAP_SYSTEM_KEY = 'qw-map-system';

function mapMode() { return $('#map-mode')?.value || 'system'; }
function mapSystem() { return $('#map-system')?.value || ''; }

function preferredMapSystem() {
  const here = hereId && atlas.find((location) => location.rawId === hereId)?.system;
  return here && SYSTEM_COLOURS[here] ? here : 'Stanton';
}

function currentMapLocation() {
  return hereId ? atlas.find((location) => location.rawId === hereId) || null : null;
}

// This remains visible even when the selected system is not the player's. A
// one-system map is less misleading than a whole-system schematic, but should
// never turn "where am I?" into a hidden state.
function updateHereControl() {
  const control = $('#map-here');
  const label = $('#map-here-label');
  if (!control || !label) return;

  const here = currentMapLocation();
  control.disabled = !here;
  control.classList.toggle('located', !!here);
  label.textContent = here ? `You · ${here.name}` : 'Location unknown';

  if (!here) control.title = 'The live log has not named your location yet';
  else if (mapMode() === 'network') control.title = `Show ${here.name} in ${here.system}`;
  else if (mapSystem() !== here.system) control.title = `Show ${here.name} in ${here.system}`;
  else control.title = `Centre on ${here.name}`;
}

/** Makes the player's system and place visible without changing filters. */
function focusHere() {
  const here = currentMapLocation();
  if (!here) return false;

  if (here.system && SYSTEM_COLOURS[here.system]
    && (mapMode() !== 'system' || mapSystem() !== here.system)) {
    $('#map-mode').value = 'system';
    $('#map-system').value = here.system;
    syncMapModeControls();
    try {
      localStorage.setItem(MAP_MODE_KEY, 'system');
      localStorage.setItem(MAP_SYSTEM_KEY, here.system);
    } catch { /* private mode */ }
    drawMap();
  }

  return centreOn(here.rawId);
}

function syncMapModeControls() {
  const mode = $('#map-mode');
  const system = $('#map-system');
  if (!mode || !system) return;

  const systems = [...new Set(atlas.map((location) => location.system)
    .filter((name) => SYSTEM_COLOURS[name]))].sort();

  if (!system.dataset.filled || [...system.options].map((option) => option.value).join('|') !== systems.join('|')) {
    const selected = system.value || preferredMapSystem();
    system.textContent = '';
    for (const name of systems) system.append(new Option(name, name));
    system.value = systems.includes(selected) ? selected : (systems[0] || '');
    system.dataset.filled = '1';
  }

  system.hidden = mode.value !== 'system';
  const note = $('#map-mode-note');
  if (note) note.textContent = mode.value === 'system'
    ? `${system.value || 'This system'}: real body bearings and relative orbit distances. Bodies without a community coordinate are amber and explicitly unpositioned.`
    : 'Jump network: systems and jump connections only — schematic, not to scale. Select a system to inspect its bodies and locations.';
  updateHereControl();
}

// Service data is intentionally a set of place ids, not a claim about every
// facility at a location. UEX can identify counters, fuel prices and clinics;
// it cannot identify repair pads, so repair never becomes a reassuringly empty
// map filter.
const SERVICE_META = {
  shop: { icon: '▦', label: 'Shops' },
  refuel: { icon: '⛽', label: 'Refuel' },
  clinic: { icon: '✚', label: 'Clinic' },
  repair: { icon: '⚙', label: 'Repair' },
};
const mapServicesByPlace = new Map();
let mapServiceFilter = '';
let mapFocusFilter = '';
const mapShoppingIds = new Set();
const mapStashIds = new Set();
let mapNotes = [];
const mapNoteIds = new Set();
const MAP_SAVED_VIEW_KEY = 'qw-map-saved-view';
const MAP_LABEL_DENSITY_KEY = 'qw-map-label-density';

const serviceKey = (name) => ({
  Shops: 'shop',
  'Trade counter': 'shop',
  Refuel: 'refuel',
  Clinic: 'clinic',
  Repair: 'repair',
}[name] || '');

const servicesAt = (location) => mapServicesByPlace.get(location.rawId) || [];

/**
 * What the game itself says a place has, by place name.
 *
 * Deliberately not merged into the service badges above. Those are UEX's
 * account of where you can actually trade today; this is the star map's own
 * list of facilities, and the two disagree usefully often. Keyed by name
 * because that is what the star map keys it by - there is no map id in the
 * game's own data to join on.
 */
const amenitiesByPlace = new Map();
let mapAmenityFilter = '';

/**
 * Whether the install has been read yet.
 *
 * Kept because "empty" and "broken" look identical for the half minute the
 * first read takes, and several pages resolved that ambiguity by suggesting a
 * 110 MB download to fix a wait.
 */
let gameDataState = null;

async function loadGameData() {
  const state = await getJson('/api/gamedata').catch(() => null);
  const was = gameDataState?.state;
  gameDataState = state;

  // Still reading means still changing, so the page comes back for the answer
  // rather than leaving a count that was true a moment ago. Scheduled up here
  // because the early return below skips it on any page whose panel is absent,
  // and this poll is the only thing that notices the reading has finished.
  if (state?.state === 'reading') setTimeout(() => { loadGameData().catch(() => {}); }, 3000);

  // Parts, Mining and Crafting are fetched once, at startup. On a cold install
  // that is half a minute before the game files have been read, so they came
  // back empty and stayed empty until the browser was reloaded: the app looked
  // like it held no data rather than like it was still reading. Refill them the
  // moment there is something to fetch.
  if (state?.state === 'ready' && was && was !== 'ready') {
    loadPartsRef().catch((e) => console.error('parts refill', e));
    loadMiningRef().catch((e) => console.error('mining refill', e));
    loadCraftingRef().catch((e) => console.error('crafting refill', e));
    loadMiningPlaces().catch(() => {});

    // The map is on the same footing and was missed: its places come from the
    // install's own gazetteer, and the amenities filter is built entirely from
    // it. Both loaded once at startup, so a cold start left the map holding
    // whatever had been read by then.
    loadAtlas().catch((e) => console.error('map refill', e));
    loadMapAmenities().catch(() => {});
  }

  const label = $('#gamedata-state');
  const problem = $('#gamedata-problem');
  if (!label) return state;

  label.textContent = {
    reading: state?.seconds ? `reading… ${Math.round(state.seconds)}s` : 'reading…',
    ready: 'ready',
    failed: 'could not be read',
    noinstall: 'no install found',
  }[state?.state] || '';

  if (problem) {
    problem.textContent = state?.problem || '';
    problem.hidden = !state?.problem;
  }

  const counts = state?.counts || {};
  const count = (n) => (n || 0).toLocaleString();

  // The Settings copy quotes install figures to compare the two sources. They
  // move with every patch, so they are filled from the counts rather than typed
  // into the page and left to rot - three of them were already out of date.
  const quote = (id, n) => { const node = $(id); if (node && n) node.textContent = n.toLocaleString(); };
  quote('#settings-install-items', counts.items);
  quote('#settings-install-deposits', counts.deposits);
  quote('#settings-install-spawnplaces', counts.spawnplaces);

  tiles('#gamedata-counts', [
    ['Commodities', count(counts.commodities)],
    ['Items', count(counts.items)],
    ['Recipes', count(counts.recipes)],
    ['Deposits', count(counts.deposits)],
    ['Places', count(counts.places)],
  ]);

  return state;
}

/** What to say to a page that has nothing to show yet. */
function gameDataExcuse() {
  if (gameDataState?.state === 'reading') {
    return 'Still reading your game files — this takes about half a minute after a patch.';
  }

  if (gameDataState?.state === 'noinstall') return 'No game install was found.';
  if (gameDataState?.state === 'failed') return gameDataState.problem;

  return null;
}

async function loadMapAmenities() {
  const select = $('#map-amenity');
  if (!select || amenitiesByPlace.size) return;

  const places = await getJson('/api/map/amenities').catch(() => []);
  const counts = new Map();

  for (const place of places) {
    amenitiesByPlace.set(place.place.toLowerCase(), place.amenities);
    for (const amenity of place.amenities) counts.set(amenity, (counts.get(amenity) || 0) + 1);
  }

  // Rarest first: a facility six places have is the one worth searching for,
  // and one that 231 places have barely narrows anything.
  for (const [amenity, count] of [...counts].sort((a, b) => a[1] - b[1] || a[0].localeCompare(b[0])))
    select.append(new Option(`${amenity} (${count})`, amenity));
}

/** Whether the game lists a facility at a place, matched on the readable name. */
const hasAmenity = (location, amenity) =>
  (amenitiesByPlace.get((location.name || '').toLowerCase()) || []).includes(amenity);

// Service is a property of a place, not its identity. Badges sit outside the
// location glyph so a clinic at a station still reads as a station first.
function drawServiceBadges(group, x, y, radius, services) {
  const badges = svgEl('g', { class: 'map-service-badges' });
  const badgeRadius = Math.max(3.2, radius * .42);
  const orbit = radius + badgeRadius + 3;

  services.forEach((service, index) => {
    const angle = -Math.PI / 2 + (index - (services.length - 1) / 2) * .76;
    const bx = x + Math.cos(angle) * orbit;
    const by = y + Math.sin(angle) * orbit;
    const badge = svgEl('g', { class: `map-service-badge ${service}` });
    badge.append(svgEl('circle', { cx: bx, cy: by, r: badgeRadius }));

    if (service === 'shop') {
      badge.append(svgEl('rect', {
        x: bx - badgeRadius * .52, y: by - badgeRadius * .52,
        width: badgeRadius * 1.04, height: badgeRadius * 1.04, class: 'service-glyph',
      }));
      badge.append(svgEl('line', { x1: bx, y1: by - badgeRadius * .52, x2: bx, y2: by + badgeRadius * .52, class: 'service-glyph' }));
    } else if (service === 'refuel') {
      badge.append(svgEl('path', {
        d: `M ${bx} ${by - badgeRadius * .68} C ${bx + badgeRadius * .56} ${by - badgeRadius * .14}, ${bx + badgeRadius * .42} ${by + badgeRadius * .56}, ${bx} ${by + badgeRadius * .62} C ${bx - badgeRadius * .42} ${by + badgeRadius * .56}, ${bx - badgeRadius * .56} ${by - badgeRadius * .14}, ${bx} ${by - badgeRadius * .68} Z`,
        class: 'service-glyph',
      }));
    } else if (service === 'clinic') {
      badge.append(svgEl('path', {
        d: `M ${bx - badgeRadius * .22} ${by - badgeRadius * .64} H ${bx + badgeRadius * .22} V ${by - badgeRadius * .22} H ${bx + badgeRadius * .64} V ${by + badgeRadius * .22} H ${bx + badgeRadius * .22} V ${by + badgeRadius * .64} H ${bx - badgeRadius * .22} V ${by + badgeRadius * .22} H ${bx - badgeRadius * .64} V ${by - badgeRadius * .22} H ${bx - badgeRadius * .22} Z`,
        class: 'service-glyph',
      }));
    } else {
      badge.append(svgEl('path', {
        d: `M ${bx - badgeRadius * .58} ${by} H ${bx + badgeRadius * .58} M ${bx} ${by - badgeRadius * .58} V ${by + badgeRadius * .58}`,
        class: 'service-glyph',
      }));
    }

    const title = svgEl('title');
    title.textContent = SERVICE_META[service]?.label || service;
    badge.append(title);
    badges.append(badge);
  });

  group.append(badges);
}

// A small bookmark sits outside the location glyph: a personal note changes
// neither the place kind nor the UEX service facts already drawn around it.
function drawMapNoteBadge(group, x, y, radius) {
  const badge = svgEl('g', { class: 'map-note-badge', 'pointer-events': 'none' });
  const size = Math.max(3.2, radius * .48);
  const bx = x + radius + size + 2;
  const by = y + radius + size + 1;
  badge.append(svgEl('path', {
    d: `M ${bx} ${by - size} L ${bx + size} ${by} L ${bx} ${by + size} L ${bx - size} ${by} Z`,
  }));
  const title = svgEl('title');
  title.textContent = 'Personal map note';
  badge.append(title);
  group.append(badge);
}

function showServiceBadges(location, highlighted) {
  return servicesAt(location).length > 0
    && (isDetailed() || highlighted || !!mapServiceFilter || !!mapFocusFilter);
}

function selectMapService(service, openMap = false, redraw = true) {
  mapServiceFilter = service || '';
  for (const button of $$('#map-service-filter button'))
    button.classList.toggle('active', button.dataset.service === mapServiceFilter);

  if (openMap) showView('map');
  if (redraw) drawMap();
}

function planPlaceIds() {
  return new Set((tracked()?.stops || []).map((stop) => stop.placeId).filter(Boolean));
}

function mapFocusIds() {
  if (mapFocusFilter === 'plan') return planPlaceIds();
  if (mapFocusFilter === 'shopping') return mapShoppingIds;
  if (mapFocusFilter === 'stash') return mapStashIds;
  if (mapFocusFilter === 'notes') return mapNoteIds;
  return null;
}

function selectMapFocus(focus, redraw = true) {
  mapFocusFilter = focus || '';
  for (const button of $$('#map-focus-filter button'))
    button.classList.toggle('active', button.dataset.focus === mapFocusFilter);
  if (redraw) drawMap();
}

function mapLabelDensity() { return $('#map-label-density')?.value || 'auto'; }

function saveMapView() {
  const saved = {
    mode: mapMode(), system: mapSystem(), service: mapServiceFilter, focus: mapFocusFilter,
    visited: $('#map-visited-only').checked, goods: $('#map-goods').checked,
    labels: mapLabelDensity(), search: $('#map-search').value,
  };
  try { localStorage.setItem(MAP_SAVED_VIEW_KEY, JSON.stringify(saved)); } catch { /* private mode */ }

  const button = $('#map-save-preset');
  button.textContent = 'Saved';
  button.title = 'Saved view updated';
}

function applyMapPreset(name) {
  let preset = null;
  if (name === 'saved') {
    try { preset = JSON.parse(localStorage.getItem(MAP_SAVED_VIEW_KEY) || 'null'); } catch { /* private mode */ }
    if (!preset) return;
  } else if (name === 'plan') {
    preset = { focus: 'plan' };
  } else if (name === 'shopping') {
    preset = { focus: 'shopping', goods: true };
  } else if (name === 'services') {
    preset = { service: 'refuel', goods: false };
  } else if (name === 'visited') {
    preset = { visited: true, focus: '' };
  } else return;

  if (preset.mode) $('#map-mode').value = preset.mode;
  if (preset.system) $('#map-system').value = preset.system;
  if (typeof preset.visited === 'boolean') $('#map-visited-only').checked = preset.visited;
  if (typeof preset.goods === 'boolean') $('#map-goods').checked = preset.goods;
  if (preset.labels) $('#map-label-density').value = preset.labels;
  if (typeof preset.search === 'string') $('#map-search').value = preset.search;
  selectMapService(preset.service || '', false, false);
  selectMapFocus(preset.focus || '', false);
  syncMapModeControls();
  drawMap();
}

function atlasPlaceId(name) {
  if (!name) return null;
  const clean = String(name).toLowerCase().replace(/[^a-z0-9]/g, '');
  if (clean.length < 4) return null;
  return atlas.find((place) => {
    const candidate = `${place.name} ${place.rawId}`.toLowerCase().replace(/[^a-z0-9]/g, '');
    return candidate === clean || candidate.includes(clean) || clean.includes(candidate);
  })?.rawId || null;
}

// Jobs give us destinations and sellers; stash remembers presence by place.
// Both are useful focus layers, but neither is a live inventory or stock claim.
async function refreshMapFocusContext(redraw = false) {
  const [jobs, stats] = await Promise.all([
    getJson('/api/jobs').catch(() => []),
    getJson('/api/stats').catch(() => null),
  ]);

  mapShoppingIds.clear();
  for (const job of jobs.filter((job) => !job.done)) {
    if (job.destinationId) mapShoppingIds.add(job.destinationId);
    else if (job.destination) {
      const destination = atlasPlaceId(job.destination);
      if (destination) mapShoppingIds.add(destination);
    }

    for (const item of job.items || []) {
      if (item.have) continue;
      const seller = atlasPlaceId(item.buyAt);
      if (seller) mapShoppingIds.add(seller);
    }
  }

  mapStashIds.clear();
  for (const place of stats?.stash || []) {
    const id = atlasPlaceId(place.name);
    if (id) mapStashIds.add(id);
  }

  if (redraw && atlas.length) drawMap();
}

/** Non-null while a commodity search is active: the rawIds to light up. */
let highlightIds = null;

/**
 * Whether the map keeps itself centred on the live marker. Persisted: someone
 * who plays with the map on a second monitor wants this every session.
 */
let followHere = false;
try { followHere = localStorage.getItem('qw-map-follow') === '1'; } catch { /* private mode */ }

/** Where the player is, kept in step with the live feed. */
let hereId = null;

const SYSTEM_COLOURS = { Stanton: '#ffdc9a', Pyro: '#ff8f66', Nyx: '#9fb8ff' };

/** Jump lanes, drawn between the stars they connect. */
const JUMP_LANES = [
  ['Stanton', 'Pyro'],
  ['Pyro', 'Nyx'],
  ['Stanton', 'Nyx'],
];

/**
 * How far a body's sites reach, given how many it has.
 *
 * The phyllotaxis spacing that fits at system scale is far too tight once the
 * dots are big enough to read: a well-visited site is 17 units across on its
 * own while neighbours sit 5.2 apart, so microTech's twenty-two piled into
 * each other however far you zoomed in. Zoomed in the whole cluster opens up,
 * which is exactly when there is room for it - the same trade the bodies
 * themselves make.
 */
const clusterRadius = (count) =>
  (count <= 1 ? 14 : 13 + 5.2 * Math.sqrt(count - 1)) * (isDetailed() ? 2.1 : 1);

/**
 * Works out where each star sits and how far its bodies orbit, from what the
 * system actually contains.
 *
 * A fixed orbit cannot work once every location is on the map rather than only
 * the visited handful: microTech alone carries over a hundred sites, and its
 * cluster spilled straight over Calliope's next door. Each system is therefore
 * sized so neighbouring clusters clear each other with room for their labels,
 * which makes Stanton's disc several times Nyx's.
 *
 * Systems are then laid out as a triangle rather than a row - that is the real
 * topology, since Stanton, Pyro and Nyx each have a jump point to the other
 * two, and three discs in a line make a map that is all width and no height.
 */
function layoutSystems(grouped) {
  const layout = {};

  for (const [system, bodies] of Object.entries(grouped)) {
    if (system === 'other' || !bodies.size) continue;

    const reach = Math.max(...[...bodies.values()].map((sites) => clusterRadius(sites.length)));
    const spacing = reach * 2 + 34;
    const orbit = Math.max(190, (spacing * bodies.size) / (2 * Math.PI));

    layout[system] = {
      orbit,
      reach,
      radius: orbit + reach + 34,
      colour: SYSTEM_COLOURS[system] || '#9fb8ff',
    };
  }

  // Stanton and Pyro share the top row; anything else goes underneath.
  const pad = 70;
  const gap = 90;
  const top = ['Stanton', 'Pyro'].filter((s) => layout[s]);
  const rest = Object.keys(layout).filter((s) => !top.includes(s));

  const rowHeight = top.length ? Math.max(...top.map((s) => layout[s].radius)) : 0;
  let x = pad;

  for (const system of top) {
    layout[system].x = x + layout[system].radius;
    layout[system].y = pad + rowHeight;
    x = layout[system].x + layout[system].radius + gap;
  }

  const rowWidth = Math.max(pad, x - gap);
  let y = top.length ? pad + rowHeight * 2 + gap : pad;

  for (const system of rest) {
    layout[system].x = Math.max(rowWidth / 2, pad + layout[system].radius);
    layout[system].y = y + layout[system].radius;
    y = layout[system].y + layout[system].radius + gap;
  }

  const width = Math.max(rowWidth, ...Object.values(layout).map((s) => s.x + s.radius)) + pad;
  const height = Math.max(y - gap, pad + rowHeight * 2) + pad;

  return { layout, width, height };
}

let SYSTEM_LAYOUT = {};
let HOME_VIEW = { x: 0, y: 0, w: 1340, h: 1240 };
let view = { ...HOME_VIEW };

/**
 * Label size in map units, chosen so text keeps a constant size on screen
 * however far the view is zoomed. Without this, zooming in magnifies the labels
 * along with everything else and they pile into each other.
 */
const labelSize = (scale = 1) => (view.w / HOME_VIEW.w) * 9.5 * scale;

async function loadAtlas() {
  const [data, servicePlaces] = await Promise.all([
    getJson('/api/map'),
    getJson('/api/map/services').catch(() => []),
  ]);
  atlas = data.nodes || [];
  bodyPositions = data.positions || {};
  mapServicesByPlace.clear();
  for (const place of servicePlaces)
    mapServicesByPlace.set(place.placeId, place.services || []);
  await refreshMapFocusContext();
  syncMapModeControls();
  drawMap();

  // A detail card can stay open while the history refreshes. Its facts should
  // catch up when the supporting service map does.
  if (mapInfoLocation) renderMapInfoServices(mapInfoLocation);
}

/** Real body coordinates per system, when the community dataset supplies them. */
let bodyPositions = {};

/**
 * Where each of a system's bodies sits on its disc.
 *
 * With real coordinates the answer is geometry: the true bearing from the
 * star, distance compressed by a square root so the outer planets do not push
 * the inner ones into the star. But raw geometry has a catch at system scale —
 * a moon sits so close to its planet that both land on the same pixel and
 * their site clusters pile up. So bodies are first grouped by proximity, the
 * group anchored at its true position, and the moons fanned on a short local
 * ring around their planet, which is how the game's own starmap solves it too.
 * Systems without coordinates keep the even ring the map has always drawn.
 *
 * Returns a Map of body name → {x, y, angle}; sizeOf gives each body's
 * cluster radius so a moon lands clear of its planet's spread of sites.
 */
function bodyLayout(system, present, centre, sizeOf) {
  const placements = new Map();
  const real = bodyPositions[system.toLowerCase()] || {};
  const lookup = (name) => {
    const key = Object.keys(real).find((k) => k.toLowerCase() === name.toLowerCase());
    return key && (real[key].x || real[key].y) ? real[key] : null;
  };

  // Zoomed in, the bodies move apart: every site carries a label at that
  // range and the names need the room. applyView anchors the view across the
  // redraw so the spread happens around what the eye is on.
  const spread = isDetailed() ? 1.6 : 1;
  const orbit = centre.orbit * spread;
  const physical = mapMode() === 'system';

  if (!present.some((name) => lookup(name))) {
    present.forEach((bodyName, index) => {
      const angle = (index / Math.max(1, present.length)) * Math.PI * 2 - Math.PI / 2;
      placements.set(bodyName, {
        x: centre.x + Math.cos(angle) * orbit,
        y: centre.y + Math.sin(angle) * orbit,
        angle, positioned: false,
        from: { x: centre.x, y: centre.y },
      });
    });
    return placements;
  }

  const maxR = Math.max(1, ...Object.values(real).map((b) => Math.hypot(b.x, b.y)));

  // Bodies within 6% of the system's radius of each other are one group: a
  // planet and its moons. First member in orbit order is the planet.
  const groups = [];
  let orphanIndex = 0;

  for (const bodyName of present) {
    const pos = lookup(bodyName);

    if (pos) {
      const near = groups.find((g) => g.pos
        && Math.hypot(g.pos.x - pos.x, g.pos.y - pos.y) < maxR * 0.06);
      if (near) { near.members.push(bodyName); continue; }
    }

    groups.push({ members: [bodyName], pos });
  }

  for (const group of groups) {
    let angle;
    let gx;
    let gy;

    if (group.pos) {
      angle = Math.atan2(group.pos.y, group.pos.x);
      const fraction = Math.hypot(group.pos.x, group.pos.y) / maxR;
      // A local system map can retain the actual radial relationship. The
      // older all-systems view compresses it because it has to fit several
      // dense systems in one frame without pretending their frames share scale.
      const radius = orbit * (physical ? fraction : 0.3 + 0.7 * Math.sqrt(fraction));
      gx = centre.x + Math.cos(angle) * radius;
      gy = centre.y + Math.sin(angle) * radius;
    } else {
      // No coordinates for this body — park it on the outer ring, stepping
      // around so uncharted bodies do not stack on one another.
      angle = Math.PI / 3 + (orphanIndex++) * (Math.PI / 2.5);
      gx = centre.x + Math.cos(angle) * orbit * 1.1;
      gy = centre.y + Math.sin(angle) * orbit * 1.1;
    }

    group.members.forEach((bodyName, index) => {
      if (index === 0) {
        placements.set(bodyName, {
          x: gx, y: gy, angle, positioned: Boolean(group.pos), from: { x: centre.x, y: centre.y },
        });
        return;
      }

      // Moons fan across the outward-facing half so they stay clear of the
      // star and of the planet's own label, spaced past both clusters.
      const arc = angle + (index - (group.members.length) / 2) * (Math.PI / 3.2);
      const gap = (sizeOf(group.members[0]) + sizeOf(bodyName) + 34) * (spread > 1 ? 1.25 : 1);

      placements.set(bodyName, {
        x: gx + Math.cos(arc) * gap,
        y: gy + Math.sin(arc) * gap,
        angle: arc, positioned: Boolean(group.pos),
        from: { x: gx, y: gy },
      });
    });
  }

  return placements;
}

/**
 * True once the view is close enough for every node to carry a label, rather
 * than only the ones with visit history. Held as a fraction of the whole map so
 * it still means the same thing when the layout resizes.
 */
const isDetailed = () => view.w < HOME_VIEW.w * 0.34;

/** Applies the current pan/zoom to the SVG, redrawing when detail changes. */
function applyView() {
  const map = $('#starmap');
  const wasDetailed = map.dataset.detailed === 'true';
  const detailed = isDetailed();

  map.setAttribute('viewBox', `${view.x} ${view.y} ${view.w} ${view.h}`);
  map.dataset.detailed = String(detailed);

  // Labels appear on zoom-in, so crossing the threshold means redrawing. The
  // redraw calls back into applyView, but the flag now matches, so it stops.
  // The detailed layout also spreads bodies apart to give the names room, so
  // the node nearest mid-view is re-found afterwards and the view shifted to
  // keep it exactly where the eye left it.
  if (detailed !== wasDetailed && atlas.length) {
    // Anchor on where the eye is headed: the glide's destination when one is
    // in flight, the current centre otherwise.
    const goal = viewAnimTarget ?? view;
    const cx = goal.x + goal.w / 2;
    const cy = goal.y + goal.h / 2;
    let anchor = null;
    let nearest = Infinity;

    for (const [id, p] of nodeAt) {
      const d = (p.x - cx) ** 2 + (p.y - cy) ** 2;
      if (d < nearest) {
        nearest = d;
        anchor = { id, x: p.x, y: p.y };
      }
    }

    drawMap();

    const moved = anchor && nodeAt.get(anchor.id);
    if (moved && (moved.x !== anchor.x || moved.y !== anchor.y)) {
      const dx = moved.x - anchor.x;
      const dy = moved.y - anchor.y;

      view.x += dx;
      view.y += dy;

      // A glide in progress must move with the world, or it lands where its
      // destination used to be.
      if (viewAnimFrom) {
        viewAnimFrom.x += dx;
        viewAnimFrom.y += dy;
        viewAnimTarget.x += dx;
        viewAnimTarget.y += dy;
      }

      map.setAttribute('viewBox', `${view.x} ${view.y} ${view.w} ${view.h}`);
    }
  }
}

/**
 * Eases the viewport towards a target rectangle. A cut to a new view loses the
 * reader - the glide is what tells them where on the map they went. Cancelled
 * the moment the user pans or zooms by hand, so the map never fights them.
 */
let viewAnimation = null;

// Endpoints live outside the closure so a mid-flight layout change (the
// detailed zoom spreads bodies apart) can shift them with the world instead
// of letting the glide land on stale coordinates.
let viewAnimFrom = null;
let viewAnimTarget = null;

function animateViewTo(target, ms = 420) {
  cancelAnimationFrame(viewAnimation);

  viewAnimFrom = { ...view };
  viewAnimTarget = { ...target };
  const start = performance.now();
  const ease = (t) => 1 - Math.pow(1 - t, 3);

  const step = (now) => {
    const k = ease(Math.min(1, (now - start) / ms));
    const from = viewAnimFrom;
    const to = viewAnimTarget;

    view = {
      x: from.x + (to.x - from.x) * k,
      y: from.y + (to.y - from.y) * k,
      w: from.w + (to.w - from.w) * k,
      h: from.h + (to.h - from.h) * k,
    };
    applyView();

    if (k < 1) viewAnimation = requestAnimationFrame(step);
    else viewAnimFrom = viewAnimTarget = null;
  };

  viewAnimation = requestAnimationFrame(step);
}

/**
 * Moves the view so a place sits in the middle, zooming in if the map is still
 * showing the whole system.
 */
function centreOn(rawId, zoom = true) {
  const point = nodeAt.get(rawId);
  if (!point) return false;

  const close = HOME_VIEW.w * 0.28;
  const w = zoom && view.w > close ? close : view.w;
  const h = zoom && view.w > close ? close * (HOME_VIEW.h / HOME_VIEW.w) : view.h;

  animateViewTo({ x: point.x - w / 2, y: point.y - h / 2, w, h });
  return true;
}

/**
 * Frames the current search matches: the answer to "where is it?" should not
 * require finding the lit dots on a full-width map by eye. Runs once per new
 * term so it never fights a pan the user makes while the term stands, and
 * glides home when the search is cleared.
 */
let lastFitTerm = null;

function fitToHighlights(term) {
  if (term === lastFitTerm) return;
  const hadTerm = Boolean(lastFitTerm);
  lastFitTerm = term;

  if (!term || !highlightIds || highlightIds.size === 0) {
    if (hadTerm && !term) animateViewTo(HOME_VIEW);
    return;
  }

  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;

  for (const id of highlightIds) {
    const p = nodeAt.get(id);
    if (!p) continue;
    minX = Math.min(minX, p.x);
    minY = Math.min(minY, p.y);
    maxX = Math.max(maxX, p.x);
    maxY = Math.max(maxY, p.y);
  }

  if (minX === Infinity) return;

  const padX = Math.max((maxX - minX) * 0.22, HOME_VIEW.w * 0.07);
  const padY = Math.max((maxY - minY) * 0.22, HOME_VIEW.h * 0.07);

  let w = maxX - minX + padX * 2;
  let h = maxY - minY + padY * 2;

  // Preserve the map's aspect so the frame is a zoom, not a stretch.
  const aspect = HOME_VIEW.h / HOME_VIEW.w;
  if (h < w * aspect) h = w * aspect;
  else w = h / aspect;

  // Clamped both ways: never wider than home, and never closer than the
  // "centre on" zoom - a single match filling the frame reads as an error.
  w = Math.max(Math.min(w, HOME_VIEW.w), HOME_VIEW.w * 0.26);
  h = Math.max(Math.min(h, HOME_VIEW.h), HOME_VIEW.h * 0.26);

  animateViewTo({
    x: (minX + maxX) / 2 - w / 2,
    y: (minY + maxY) / 2 - h / 2,
    w,
    h,
  });
}

/**
 * Marks the player's current place, and is safe to call before the map has been
 * drawn - the marker is re-applied on every draw from {@link hereId}.
 */
function setHere(rawId) {
  const changed = (rawId || null) !== hereId;
  hereId = rawId || null;

  /*
   * Only when it actually moves.
   *
   * The live feed repeats the same place every second, and this used to redraw
   * on every one of them. The marker's pulse is an SVG animation of a growing
   * ring over 2.2 seconds, and rebuilding the element restarts it - so it got
   * a fifth of the way out, was replaced, and started again. The marker was
   * there the whole time and never appeared to pulse, which is worse than not
   * being drawn: it looks like a dead dot rather than a missing feature.
   */
  if (changed || !$('#starmap').querySelector('.map-here'))
    drawHere();

  updateHereControl();

  // Follow mode: the map pans itself as the player moves, so a second monitor
  // shows the journey without being touched.
  if (followHere && changed && hereId)
    centreOn(hereId);
}

/** Where the live feed says the player is quantum-travelling to, if anywhere. */
let travelId = null;

/**
 * Marks a jump in progress, and is safe to call before the map is drawn.
 *
 * The same rule as the here-marker: only rebuild when the destination changes,
 * or the marching dashes restart every time the feed repeats itself and the
 * line looks painted on.
 */
function setTravel(rawId) {
  const changed = (rawId || null) !== travelId;
  travelId = rawId || null;

  if (changed || (travelId && !$('#starmap').querySelector('.map-travel')))
    drawTravel();
}

/**
 * The line from where you are to where you are headed.
 *
 * The map has always known both ends - the live feed names the destination the
 * moment the drive spools - and drew neither as a journey. A jump is the one
 * time the map can show something happening rather than something recorded, so
 * it gets a marching dashed vector and a ring waiting at the far end.
 */
function drawTravel() {
  const map = $('#starmap');
  map.querySelectorAll('.map-travel').forEach((n) => n.remove());

  const from = hereId && nodeAt.get(hereId);
  const to = travelId && nodeAt.get(travelId);

  // Either end can be a place the map cannot draw - an unmapped outpost, or a
  // destination in a system this atlas has no layout for. A half-drawn vector
  // pointing at nothing would be worse than none.
  if (!from || !to) return;

  const zoom = view.w / HOME_VIEW.w;
  const group = svgEl('g', { class: 'map-travel' });

  const line = svgEl('line', {
    x1: from.x, y1: from.y, x2: to.x, y2: to.y,
    class: 'travel-line',
    'stroke-width': 1.5 * zoom,
    'stroke-dasharray': `${7 * zoom} ${5 * zoom}`,
    filter: 'url(#glow)',
  });

  line.append(svgEl('animate', {
    attributeName: 'stroke-dashoffset',
    values: `${12 * zoom};0`,
    dur: '0.85s',
    repeatCount: 'indefinite',
  }));

  group.append(line);

  const target = svgEl('circle', {
    cx: to.x, cy: to.y, r: 11 * zoom,
    class: 'travel-target',
    'stroke-width': 1.3 * zoom,
  });

  target.append(svgEl('animate', {
    attributeName: 'r',
    values: `${9 * zoom};${19 * zoom}`,
    dur: '1.6s',
    repeatCount: 'indefinite',
  }));

  target.append(svgEl('animate', {
    attributeName: 'opacity', values: '.8;0', dur: '1.6s', repeatCount: 'indefinite',
  }));

  group.append(target);
  map.append(group);
}

// The jump map has deliberately no place nodes. It can still locate the player
// honestly at system level, which makes its otherwise abstract graph useful
// without pretending it knows a position inside that system.
function drawNetworkHere(map) {
  const here = currentMapLocation();
  const point = here?.system && SYSTEM_LAYOUT[here.system];
  if (!point) return;

  const group = svgEl('g', { class: 'map-here' });
  group.append(svgEl('circle', {
    cx: point.x, cy: point.y, r: point.radius + 15, class: 'here-ring', 'stroke-width': '2',
  }));
  group.append(svgEl('circle', { cx: point.x, cy: point.y, r: 6, class: 'here-dot', 'stroke-width': '1.4' }));

  const pulse = svgEl('circle', {
    cx: point.x, cy: point.y, r: point.radius + 12, class: 'here-pulse', 'stroke-width': '1.2',
  });
  pulse.append(svgEl('animate', {
    attributeName: 'r', values: `${point.radius + 10};${point.radius + 30}`, dur: '2.2s', repeatCount: 'indefinite',
  }));
  pulse.append(svgEl('animate', {
    attributeName: 'opacity', values: '.65;0', dur: '2.2s', repeatCount: 'indefinite',
  }));
  group.append(pulse);

  const label = svgEl('text', {
    x: point.x, y: point.y - point.radius - 26, 'text-anchor': 'middle',
    class: 'map-label here-label', style: `font-size:${labelSize(0.85)}px`,
  });
  label.textContent = `YOU · ${here.name}`;
  group.append(label);
  map.append(group);
}

function drawHere() {
  const map = $('#starmap');
  map.querySelectorAll('.map-here').forEach((n) => n.remove());

  if (mapMode() === 'network') {
    drawNetworkHere(map);
    return;
  }

  const point = hereId && nodeAt.get(hereId);
  updateHereControl();
  if (!point) return;

  // Two rings: a steady one to read against the dot, and an expanding pulse.
  // Sized in map units against the current zoom so the marker stays the same
  // size on screen however far in the view is.
  const zoom = view.w / HOME_VIEW.w;
  const ring = 15 * zoom;
  const group = svgEl('g', { class: 'map-here' });

  group.append(svgEl('circle', {
    cx: point.x, cy: point.y, r: ring, class: 'here-ring', 'stroke-width': 1.6 * zoom,
  }));
  group.append(svgEl('line', {
    x1: point.x - ring - 5 * zoom, y1: point.y, x2: point.x + ring + 5 * zoom, y2: point.y,
    class: 'here-tick', 'stroke-width': zoom,
  }));
  group.append(svgEl('line', {
    x1: point.x, y1: point.y - ring - 5 * zoom, x2: point.x, y2: point.y + ring + 5 * zoom,
    class: 'here-tick', 'stroke-width': zoom,
  }));
  group.append(svgEl('circle', {
    cx: point.x, cy: point.y, r: 4 * zoom, class: 'here-dot', 'stroke-width': zoom,
  }));

  const pulse = svgEl('circle', {
    cx: point.x, cy: point.y, r: ring, class: 'here-pulse', 'stroke-width': zoom,
  });
  pulse.append(svgEl('animate', {
    attributeName: 'r', values: `${13 * zoom};${30 * zoom}`, dur: '2.2s', repeatCount: 'indefinite',
  }));
  pulse.append(svgEl('animate', {
    attributeName: 'opacity', values: '.65;0', dur: '2.2s', repeatCount: 'indefinite',
  }));
  group.append(pulse);

  const label = svgEl('text', {
    x: point.x + ring + 16 * zoom, y: point.y - ring - 15 * zoom, 'text-anchor': 'start',
    class: 'map-label here-label', style: `font-size:${labelSize(0.85)}px`,
  });
  // The place already owns the node's usual label. A short, offset callout
  // makes the live marker legible without printing the same place name twice
  // on top of itself.
  label.textContent = 'YOU ARE HERE';
  group.append(svgEl('line', {
    x1: point.x + ring * .62, y1: point.y - ring * .62,
    x2: point.x + ring + 10 * zoom, y2: point.y - ring - 11 * zoom,
    class: 'here-leader', 'stroke-width': zoom,
  }));
  group.append(label);

  map.append(group);
}

/** Wheel zoom, drag pan, and the toolbar. Wired once. */
function initMap() {
  const map = $('#starmap');

  map.addEventListener('wheel', (e) => {
    e.preventDefault();
    cancelAnimationFrame(viewAnimation);

    // Zoom about the cursor rather than the centre, so the place being
    // inspected stays under the pointer.
    const box = map.getBoundingClientRect();
    const fx = (e.clientX - box.left) / box.width;
    const fy = (e.clientY - box.top) / box.height;

    const factor = e.deltaY > 0 ? 1.15 : 1 / 1.15;
    const w = Math.min(HOME_VIEW.w * 1.6, Math.max(HOME_VIEW.w * 0.05, view.w * factor));
    const h = w * (HOME_VIEW.h / HOME_VIEW.w);

    view.x += (view.w - w) * fx;
    view.y += (view.h - h) * fy;
    view.w = w;
    view.h = h;
    applyView();
  }, { passive: false });

  let drag = null;

  /*
   * Pressing is not yet dragging.
   *
   * The map captures the pointer so a drag that leaves the window still pans,
   * and capturing on pointerdown looked like the place to do it. It is not:
   * while an element holds the capture, the browser delivers the click to that
   * element rather than to whatever is under the cursor - so every click meant
   * for a place was delivered to the map, and no place ever opened its card,
   * its trade panel, or went onto a plan. The map has been unclickable with a
   * real mouse since it was written; only a synthetic click dispatched
   * straight at a node ever worked, which is how it passed its own tests.
   *
   * So the capture waits for movement. Below the slop a press is a click and
   * is left entirely alone; past it the drag begins and takes the pointer.
   */
  const DRAG_SLOP = 4;

  map.addEventListener('pointerdown', (e) => {
    cancelAnimationFrame(viewAnimation);
    drag = { x: e.clientX, y: e.clientY, vx: view.x, vy: view.y, moving: false };
  });

  map.addEventListener('pointermove', (e) => {
    if (!drag) return;

    if (!drag.moving) {
      if (Math.hypot(e.clientX - drag.x, e.clientY - drag.y) < DRAG_SLOP)
        return;

      drag.moving = true;
      map.setPointerCapture?.(e.pointerId);
      map.classList.add('dragging');
    }

    const box = map.getBoundingClientRect();
    view.x = drag.vx - ((e.clientX - drag.x) / box.width) * view.w;
    view.y = drag.vy - ((e.clientY - drag.y) / box.height) * view.h;
    applyView();
  });

  const endDrag = (e) => {
    if (!drag) return;

    if (drag.moving) {
      map.releasePointerCapture?.(e.pointerId);
      map.classList.remove('dragging');
    }

    drag = null;
  };

  map.addEventListener('pointerup', endDrag);
  map.addEventListener('pointercancel', endDrag);

  $('#map-reset').addEventListener('click', () => animateViewTo(HOME_VIEW));

  $('#map-here').addEventListener('click', focusHere);
  $('#map-visited-only').addEventListener('change', () => drawMap());
  $('#map-shade').addEventListener('change', () => drawMap());
  const mode = $('#map-mode');
  const system = $('#map-system');
  try {
    mode.value = localStorage.getItem(MAP_MODE_KEY) || 'system';
    system.value = localStorage.getItem(MAP_SYSTEM_KEY) || '';
  } catch { /* private mode */ }
  mode.addEventListener('change', () => {
    syncMapModeControls();
    try { localStorage.setItem(MAP_MODE_KEY, mode.value); } catch { /* fine */ }
    drawMap();
  });
  system.addEventListener('change', () => {
    try { localStorage.setItem(MAP_SYSTEM_KEY, system.value); } catch { /* fine */ }
    drawMap();
  });
  for (const button of $$('#map-service-filter button'))
    button.addEventListener('click', () => selectMapService(button.dataset.service));
  for (const button of $$('#map-focus-filter button'))
    button.addEventListener('click', () => selectMapFocus(button.dataset.focus));

  loadMapAmenities().catch(() => {});

  $('#map-amenity')?.addEventListener('change', (event) => {
    mapAmenityFilter = event.target.value;
    drawMap();
  });

  const labelDensity = $('#map-label-density');
  try { labelDensity.value = localStorage.getItem(MAP_LABEL_DENSITY_KEY) || 'auto'; } catch { /* private mode */ }
  labelDensity.addEventListener('change', () => {
    try { localStorage.setItem(MAP_LABEL_DENSITY_KEY, labelDensity.value); } catch { /* private mode */ }
    drawMap();
  });

  $('#map-preset').addEventListener('change', (event) => applyMapPreset(event.target.value));
  $('#map-save-preset').addEventListener('click', saveMapView);
  initCargoPanel();
  onInput('#map-search', () => { drawMap(); renderSearchResults(); });

  // Escape clears the search and glides home; clicking anywhere else just
  // closes the suggestion list.
  $('#map-search').addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      e.target.value = '';
      $('#map-results').hidden = true;
      drawMap();
    }
  });

  document.addEventListener('click', (e) => {
    if (!e.target.closest('.map-search-box')) $('#map-results').hidden = true;
  });

  const follow = $('#map-follow');
  follow.classList.toggle('active', followHere);

  follow.addEventListener('click', () => {
    followHere = !followHere;
    follow.classList.toggle('active', followHere);
    try { localStorage.setItem('qw-map-follow', followHere ? '1' : '0'); } catch { /* fine */ }

    if (followHere && hereId) centreOn(hereId);
  });

  // Clicking empty map space dismisses the detail card.
  map.addEventListener('click', closeEntity);

  // The Goods checkbox: one switch for goods on hover tips and on the detail
  // card, remembered per browser.
  const goodsToggle = $('#map-goods');
  try { goodsToggle.checked = localStorage.getItem('qw-map-sold') === '1'; } catch { /* fine */ }

  goodsToggle.addEventListener('change', () => {
    try { localStorage.setItem('qw-map-sold', goodsToggle.checked ? '1' : '0'); } catch { /* fine */ }
    renderMapInfoSold();
  });

  // Keyboard zoom for anyone without a wheel: +/- around the view centre.
  document.addEventListener('keydown', (e) => {
    if (!$('#view-map').classList.contains('active')) return;
    if (e.target.matches('input, select, textarea')) return;

    if (e.key === '+' || e.key === '=' || e.key === '-') {
      const factor = e.key === '-' ? 1.25 : 1 / 1.25;
      const w = Math.min(HOME_VIEW.w * 1.6, Math.max(HOME_VIEW.w * 0.05, view.w * factor));
      const h = w * (HOME_VIEW.h / HOME_VIEW.w);
      view.x += (view.w - w) / 2;
      view.y += (view.h - h) / 2;
      view.w = w;
      view.h = h;
      applyView();
      e.preventDefault();
    }
  });
}

/**
 * Flies to a named place: the map view, centred, detail card open. Falls back
 * to a highlight search when the name is not an exact atlas match - a quantum
 * destination or a shop name still lights whatever answers to it.
 */
function jumpToPlace(name) {
  const wanted = String(name).trim();
  const entry = atlas.find((l) => l.name.toLowerCase() === wanted.toLowerCase());

  $('#map-search').value = entry ? '' : wanted;
  $('#map-results').hidden = true;
  if (entry?.system && SYSTEM_COLOURS[entry.system]) {
    $('#map-mode').value = 'system';
    $('#map-system').value = entry.system;
    syncMapModeControls();
  }
  showView('map');
  drawMap();

  if (entry) {
    centreOn(entry.rawId);
    showMapInfo(entry);
  }
}

/**
 * A place name that flies to the map when clicked. Used everywhere a location
 * appears in a table or card, so "where is that?" is always one click.
 */
function placeLink(name) {
  const link = el('button', 'place-link', name);
  link.type = 'button';
  link.title = 'Show on the map';
  link.addEventListener('click', (e) => {
    e.stopPropagation();
    jumpToPlace(name);
  });
  return link;
}

/** A table cell holding a place link, or a plain dash when there is nothing. */
function tdPlace(name, cls = null) {
  const td = el('td', cls);
  if (name && name !== '—' && name !== '?') td.append(placeLink(name));
  else td.textContent = name || '—';
  return td;
}

/**
 * The suggestion list under the search box: the top place-name matches, most
 * visited first. Highlighting shows WHERE matches are; this list is for
 * jumping straight to ONE of them by name.
 */
function renderSearchResults() {
  const box = $('#map-results');
  if (!box) return;

  const term = ($('#map-search')?.value || '').trim().toLowerCase();

  if (!term) {
    box.hidden = true;
    return;
  }

  const matches = atlas
    .filter((l) => l.name.toLowerCase().includes(term))
    .sort((a, b) => b.visits - a.visits || a.name.localeCompare(b.name))
    .slice(0, 6);

  // Commodities belong here too: without them there was no way to learn that
  // the thing you wanted is spelled "Medical Supplies", and the search looked
  // broken when it was only being literal.
  const goods = marketEntries
    .filter((e) => e.name.toLowerCase().includes(term) && (e.sold.length || e.bought.length))
    .sort((a, b) => a.name.length - b.name.length)
    .slice(0, 6);

  box.textContent = '';

  if (matches.length === 0 && goods.length === 0) {
    box.hidden = true;
    return;
  }

  for (const match of matches) {
    const row = el('button', 'map-result');
    row.type = 'button';
    row.append(el('span', 'name', match.name));
    row.append(el('span', 'where',
      [match.body, match.system].filter(Boolean).join(' · ') || 'unmapped'));

    row.addEventListener('click', () => {
      box.hidden = true;
      centreOn(match.rawId);
      showMapInfo(match);
    });

    box.append(row);
  }

  for (const good of goods) {
    const row = el('button', 'map-result');
    row.type = 'button';
    row.append(el('span', 'name good', good.name));
    row.append(el('span', 'where',
      `commodity · ${good.sold.length} sellers`));

    row.addEventListener('click', () => {
      box.hidden = true;
      $('#map-search').value = good.name;
      drawMap();
    });

    box.append(row);
  }

  box.hidden = false;
}

/* ---------- commodity shading ---------- */

/**
 * In commodity mode the highlight can carry a second dimension: UEX terminal
 * prices grade each lit place by how good it is - best sell price (or, when
 * asked, how much SCU it takes), and for a buy: search the cheapest price or
 * deepest stock. The legend swaps to the gradient while this is on.
 */
let shadeRows = { name: null, rows: null };
let shadeScale = null;
const nodeShade = new Map();
let mapPriceFreshness = null;

function priceFreshness(seenAt) {
  const at = Date.parse(seenAt || '');
  if (!Number.isFinite(at)) return null;
  const hours = Math.max(0, (Date.now() - at) / 3600000);
  return hours > 14 * 24
    ? { state: 'stale', label: `UEX report ${Math.floor(hours / 24)}d old` }
    : hours > 72
      ? { state: 'aging', label: `UEX report ${Math.floor(hours / 24)}d old` }
      : { state: 'fresh', label: `UEX report ${Math.max(1, Math.round(hours))}h old` };
}

const SHADE_STOPS = ['#24543f', '#4fd48a', '#ffe08a'];

/*
 * The colour of a place that has nothing to do with the chosen commodity.
 *
 * Slate rather than its own kind colour: with a commodity picked the map stops
 * being a map of kinds and becomes a map of one price, and a station left
 * cyan among a scale running green to gold reads as a value on that scale when
 * it is not one. Every mark takes the grade or takes this.
 */
const NO_TRADE = '#42525f';


/** Interpolates the poor-to-best ramp; 1 is the gold end. */
function shadeColour(t) {
  const seg = t < 0.5 ? [SHADE_STOPS[0], SHADE_STOPS[1]] : [SHADE_STOPS[1], SHADE_STOPS[2]];
  const k = t < 0.5 ? t * 2 : (t - 0.5) * 2;

  const mix = (i) => {
    const a = parseInt(seg[0].slice(1 + i * 2, 3 + i * 2), 16);
    const b = parseInt(seg[1].slice(1 + i * 2, 3 + i * 2), 16);
    return Math.round(a + (b - a) * k);
  };

  return `rgb(${mix(0)},${mix(1)},${mix(2)})`;
}

function terminalMatchesPlace(terminal, place) {
  const t = terminal.toLowerCase().replace(/[^a-z0-9]/g, '');
  const p = place.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (t.length < 4 || p.length < 4) return false;
  return t.includes(p) || p.includes(t);
}

/**
 * Builds the per-node metric for the current search, fetching the commodity's
 * terminal rows on first sight and redrawing once they land.
 */
function prepareShading(term, sites) {
  nodeShade.clear();
  shadeScale = null;
  mapPriceFreshness = null;

  const shadeSelect = $('#map-shade');
  shadeSelect.hidden = !sites;
  if (!sites || !highlightIds) return;

  const buying = term.startsWith('buy:');
  const name = (buying ? term.slice(4) : term).trim();
  const entry = marketEntries.find((e) => e.name.toLowerCase() === name);
  if (!entry) return;

  if (shadeSelect.value !== 'mine') mapPriceFreshness = priceFreshness(entry.uex?.seenAt);

  // Shading by your own receipts needs no fetch and works with UEX off: the
  // question it answers is "where did I do best with this", not "what is it
  // worth today". Both are useful; only the player knows which they meant.
  if (shadeSelect.value === 'mine') {
    shadeFromReceipts(entry.name, buying);
    return;
  }

  if (shadeRows.name !== entry.name) {
    shadeRows = { name: entry.name, rows: null };

    getJson(`/api/uex/market?commodity=${encodeURIComponent(entry.name)}`)
      .then((rows) => {
        if (shadeRows.name === entry.name) {
          shadeRows.rows = rows;
          drawMap();
        }
      })
      .catch(() => { /* UEX off or unreachable; highlight stays ungraded */ });

    return;
  }

  if (!shadeRows.rows?.length) return;

  const byScu = shadeSelect.value === 'scu';

  const metricOf = (row) => {
    if (buying) return byScu ? row.buyScu : row.buy;
    return byScu ? row.sellScu : row.sell;
  };

  // Lower is better only for a buy price; capacity and sell price want big.
  const invert = buying && !byScu;

  for (const id of highlightIds) {
    const place = atlas.find((l) => l.rawId === id);
    if (!place) continue;

    // The server resolves each terminal to a place; the name match is only for
    // rows it could not place, which would otherwise shade nothing at all.
    const matched = shadeRows.rows.filter((r) => metricOf(r) > 0
      && (r.placeId ? r.placeId === id : terminalMatchesPlace(r.terminal, place.name)));

    if (!matched.length) continue;

    const value = invert
      ? Math.min(...matched.map(metricOf))
      : Math.max(...matched.map(metricOf));

    nodeShade.set(id, { value });
  }

  if (nodeShade.size === 0) return;

  const values = [...nodeShade.values()].map((s) => s.value);
  const min = Math.min(...values);
  const max = Math.max(...values);

  for (const shade of nodeShade.values()) {
    const t = max === min ? 1 : (shade.value - min) / (max - min);
    shade.colour = shadeColour(invert ? 1 - t : t);
  }

  shadeScale = {
    min,
    max,
    invert,
    unit: byScu ? 'SCU' : 'aUEC/SCU',
    label: buying
      ? (byScu ? 'stock on offer' : 'buy price, cheapest is gold')
      : (byScu ? 'sell capacity' : 'sell price, best is gold'),
  };
}

/* ---------- cargo panel ---------- */

/**
 * Every cargo receipt this install holds, fetched once.
 *
 * The catalogue and UEX say what a commodity is worth *now*; these say what the
 * player was actually paid, and where. Both belong in the same panel, because
 * the question - is this still the run it was last week? - needs the two side
 * by side. A few hundred receipts is nothing to loop over, and the panel
 * changes commodity, side and window often enough that a round trip per twiddle
 * would be the slow part.
 */
let cargoReceipts = [];

/** What the panel is showing. */
const cargo = {
  name: null,
  buying: false,
  days: 0,

  /** Set when the panel is showing one station rather than one commodity. */
  place: null,
};

async function loadCargoReceipts() {
  cargoReceipts = (await getJson('/api/commodities?days=0'))
    .filter((t) => t.commodity && t.unitPrice > 0);

  if (!$('#cargo-panel').hidden) drawMap();
}

/** Receipts inside the panel's window. */
function receiptsInWindow() {
  const cutoff = cargo.days ? Date.now() - cargo.days * 86400000 : null;
  return cutoff ? cargoReceipts.filter((t) => new Date(t.at).getTime() >= cutoff) : cargoReceipts;
}

/** The catalogue entry a search term names, or null when it names a place. */
function commodityEntry(term) {
  const name = (term.startsWith('buy:') ? term.slice(4) : term).trim();
  return marketEntries.find((e) => e.name.toLowerCase() === name) || null;
}

/**
 * One row per place for a commodity on one side of the counter.
 *
 * Best is side-aware - the most you were paid selling, the least you paid
 * buying - and the average is weighted by volume rather than by receipt, so one
 * 320 SCU run does not count the same as one 2 SCU top-up.
 */
function receiptsFor(name, buying) {
  const byPlace = new Map();

  for (const trade of receiptsInWindow()) {
    if (trade.commodity !== name || trade.isSell === buying) continue;

    const key = trade.placeId || trade.place;
    let row = byPlace.get(key);

    if (!row) {
      row = {
        id: trade.placeId, name: trade.place,
        trades: 0, scu: 0, amount: 0, best: 0, average: 0, latest: 0, latestAt: null,
      };
      byPlace.set(key, row);
    }

    row.trades += 1;
    row.scu += trade.scu;
    row.amount += Number(trade.amount);

    row.best = row.trades === 1
      ? trade.unitPrice
      : (buying ? Math.min(row.best, trade.unitPrice) : Math.max(row.best, trade.unitPrice));

    if (!row.latestAt || new Date(trade.at) > new Date(row.latestAt)) {
      row.latestAt = trade.at;
      row.latest = trade.unitPrice;
    }
  }

  for (const row of byPlace.values()) row.average = row.scu ? row.amount / row.scu : 0;

  return [...byPlace.values()].sort((a, b) => (buying ? a.best - b.best : b.best - a.best));
}

/** Keeps the toolbar's controls in step with the search term driving them. */
function syncCargoControls() {
  for (const button of $$('#map-side button')) {
    button.classList.toggle('active', (button.dataset.side === 'buy') === cargo.buying);
  }
}

/**
 * Shows, hides or refills the panel for whatever the map is currently showing.
 * Called from drawMap, so the panel can never disagree with the shading.
 */
function syncCargoPanel(term, sites) {
  const entry = sites ? commodityEntry(term) : null;

  cargo.name = entry ? entry.name : null;
  cargo.buying = term.startsWith('buy:');

  $('#map-side').hidden = !entry;
  $('#map-window').hidden = !entry && !cargo.place;
  syncCargoControls();

  // A flight plan holds the panel until it is closed: it is the thing being
  // worked on, and a redraw must not pull it out from under the player.
  if (cargo.trip) {
    renderTripPanel();
    return;
  }

  if (cargo.place) {
    renderStationPanel();
    return;
  }

  if (!entry) {
    $('#cargo-panel').hidden = true;
    return;
  }

  renderCommodityPanel(entry);
}

function cargoPanelHead(kicker, title) {
  $('#cargo-kicker').textContent = kicker;
  $('#cargo-title').textContent = title;
  $('#cargo-panel').hidden = false;

  const body = $('#cargo-body');
  body.textContent = '';
  return body;
}

const windowWord = () =>
  (PERIODS.find((p) => p.days === cargo.days)?.label || 'All time').toLowerCase();

function renderCommodityPanel(entry) {
  const body = cargoPanelHead(cargo.buying ? 'Commodity · buying' : 'Commodity · selling', entry.name);

  // What the market says today, from the rows the shading already fetched.
  body.append(el('div', 'cargo-h', cargo.buying ? 'Cheapest terminals' : 'Best terminals'));

  if (shadeRows.name === entry.name && shadeRows.rows?.length) {
    const priceOf = (row) => (cargo.buying ? row.buy : row.sell);
    const scuOf = (row) => (cargo.buying ? row.buyScu : row.sellScu);

    const rows = shadeRows.rows
      .filter((r) => priceOf(r) > 0)
      .sort((a, b) => (cargo.buying ? priceOf(a) - priceOf(b) : priceOf(b) - priceOf(a)))
      .slice(0, 10);

    const values = rows.map(priceOf);
    const lo = Math.min(...values);
    const hi = Math.max(...values);

    for (const row of rows) {
      const t = hi === lo ? 1 : (priceOf(row) - lo) / (hi - lo);

      body.append(cargoRow({
        colour: shadeColour(cargo.buying ? 1 - t : t),
        name: row.terminal,
        sub: `${Math.round(scuOf(row)).toLocaleString()} SCU ${cargo.buying ? 'in stock' : 'of demand'}`,
        value: priceOf(row),
        onClick: () => centreOnTerminal(row.terminal, row.placeId),
      }));
    }
  } else {
    body.append(el('div', 'cargo-empty', shadeRows.name === entry.name
      ? 'No live prices for this commodity. UEX may be off — see Settings.'
      : 'Fetching live prices…'));
  }

  // What the player was actually paid, which the market cannot tell them.
  const mine = receiptsFor(entry.name, cargo.buying);
  body.append(el('div', 'cargo-h', `Your receipts · ${windowWord()}`));

  if (!mine.length) {
    body.append(el('div', 'cargo-empty',
      `You have never ${cargo.buying ? 'bought' : 'sold'} this in that window.`));
  }

  const best = mine.length ? mine[0].best : 0;
  const worst = mine.length ? mine[mine.length - 1].best : 0;

  for (const row of mine) {
    const span = Math.abs(best - worst);
    const t = span === 0 ? 1 : Math.abs(row.best - worst) / span;

    body.append(cargoRow({
      colour: shadeColour(cargo.buying ? 1 - t : t),
      name: row.name,
      sub: `${row.trades} receipt${row.trades === 1 ? '' : 's'} · ${row.scu.toLocaleString()} SCU`
        + ` · avg ${Math.round(row.average).toLocaleString()} · ${dayOf(row.latestAt)}`,
      value: row.best,
      onClick: () => {
        if (row.id) centreOn(row.id);
        showStation(row.id, row.name);
      },
    }));
  }

  const history = receiptsInWindow().filter((t) => t.commodity === entry.name);
  body.append(el('div', 'cargo-h', `Trade history · ${history.length}`));
  cargoHistory(body, history, (t) => t.place);
}

/**
 * One station's trade, opened by double-clicking it.
 *
 * The detail card answers "what is this place"; this answers "what moves
 * through it" - which the card has no room for once a station has a dozen
 * commodities on each side of the counter.
 */
function renderStationPanel() {
  const place = cargo.place;
  const key = place.id || place.name;
  const body = cargoPanelHead('Station', place.name);

  const at = receiptsInWindow().filter((t) => (t.placeId || t.place) === key);

  const add = el('button', 'ghost tiny wide', 'Add as a stop');
  add.title = 'Put this place on the flight plan';
  add.addEventListener('click', () => addStop(place.id, place.name, null));
  body.append(add);

  cargoSection(body, 'Accepts · you sold here', at.filter((t) => t.isSell), false);
  cargoSection(body, 'Offers · you bought here', at.filter((t) => !t.isSell), true);

  // The catalogue's own answer, which covers commodities never traded here.
  const catalogue = place.location ? commoditiesSoldAt(place.location) : [];

  if (catalogue.length) {
    body.append(el('div', 'cargo-h', `Catalogue says it sells · ${catalogue.length}`));

    const list = el('div', 'cargo-goods');
    list.textContent = catalogue.slice(0, 24).join(', ')
      + (catalogue.length > 24 ? `, +${catalogue.length - 24} more` : '');
    body.append(list);
  }

  body.append(el('div', 'cargo-h', `Trade history · ${at.length}`));
  cargoHistory(body, at, (t) => t.commodity);
}

/** One side of a station's counter, grouped by commodity. */
function cargoSection(body, title, trades, buying) {
  body.append(el('div', 'cargo-h', title));

  if (!trades.length) {
    body.append(el('div', 'cargo-empty', 'Nothing on record in that window.'));
    return;
  }

  const byName = new Map();

  for (const trade of trades) {
    const row = byName.get(trade.commodity)
      || { name: trade.commodity, trades: 0, scu: 0, amount: 0, latestAt: null };

    row.trades += 1;
    row.scu += trade.scu;
    row.amount += Number(trade.amount);
    if (!row.latestAt || new Date(trade.at) > new Date(row.latestAt)) row.latestAt = trade.at;

    byName.set(trade.commodity, row);
  }

  for (const row of [...byName.values()].sort((a, b) => b.scu - a.scu)) {
    body.append(cargoRow({
      colour: buying ? '#ffab3d' : '#4fd48a',
      name: row.name,
      sub: `${row.trades} receipt${row.trades === 1 ? '' : 's'} · ${row.scu.toLocaleString()} SCU`
        + ` · ${dayOf(row.latestAt)}`,
      value: row.amount / (row.scu || 1),

      // Drilling into a commodity from a station shades the whole map for it,
      // so the next question - where else does this go - is already answered.
      onClick: () => searchCommodity(row.name, buying),
    }));
  }
}

function cargoRow({ colour, name, sub, value, onClick }) {
  const row = el('div', 'cargo-row');

  const swatch = el('span', 'swatch');
  swatch.style.background = colour;
  row.append(swatch);

  const middle = el('div', 'cargo-row-main');
  middle.append(el('div', 'name', name));
  middle.append(el('div', 'sub', sub));
  row.append(middle);

  const price = el('div', 'price', Math.round(Number(value) || 0).toLocaleString());
  price.append(el('span', 'u', 'aUEC / SCU'));
  row.append(price);

  if (onClick) {
    row.tabIndex = 0;
    row.addEventListener('click', onClick);
    row.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        onClick();
      }
    });
  }

  return row;
}

/** The receipt list: newest first, capped so a long history stays scrollable. */
function cargoHistory(body, trades, describe) {
  if (!trades.length) {
    body.append(el('div', 'cargo-empty', 'No trades in that window.'));
    return;
  }

  for (const trade of trades.slice(0, 30)) {
    const line = el('div', `cargo-line ${trade.isSell ? 'sell' : 'buy'}`);
    line.append(el('span', 'when', dayOf(trade.at)));
    line.append(el('span', 'what',
      `${trade.isSell ? 'Sold' : 'Bought'} ${trade.scu} SCU · ${describe(trade)}`));
    line.append(el('span', 'rate', Math.round(trade.unitPrice).toLocaleString()));
    body.append(line);
  }

  if (trades.length > 30) {
    body.append(el('div', 'cargo-empty', `+ ${trades.length - 30} older, on the Cargo page.`));
  }
}

/** Opens the panel on one station. */
function showStation(rawId, name) {
  const location = atlas.find((l) => l.rawId === rawId);

  cargo.trip = false;
  cargo.place = { id: rawId, name: name || location?.name || rawId, location };
  $('#map-window').hidden = false;
  closeEntity();
  renderStationPanel();
}

/** Puts a commodity in the search box, which is what drives the whole map. */
function searchCommodity(name, buying) {
  cargo.trip = false;
  cargo.place = null;
  $('#map-search').value = buying ? `buy:${name}` : name;
  $('#map-results').hidden = true;
  drawMap();
}

/**
 * Centres on the atlas place a UEX terminal name belongs to.
 *
 * Terminal names are not atlas names - "TDD, Area 18" against "Area18" - so
 * this uses the same loose match the shading joins on, and simply does nothing
 * when the map cannot name the place.
 */
function centreOnTerminal(terminal, placeId) {
  const match = placeId
    ? atlas.find((l) => l.rawId === placeId)
    : atlas.find((l) => terminalMatchesPlace(terminal, l.name));

  if (!match) return;

  centreOn(match.rawId);
  showStation(match.rawId, match.name);
}

/** The panel's own controls. Wired once, from initMap. */
function initCargoPanel() {
  $('#map-side').addEventListener('click', (e) => {
    const button = e.target.closest('button');
    if (!button || !cargo.name) return;

    // The search box is the single source of truth for which side the map is
    // showing, so the toggle rewrites the term rather than keeping its own flag.
    searchCommodity(cargo.name, button.dataset.side === 'buy');
  });

  $('#map-window').addEventListener('change', (e) => {
    cargo.days = Number(e.target.value) || 0;
    drawMap();
  });

  $('#map-plan').addEventListener('click', () => {
    showTripPanel();
    drawMap();
  });

  $('#cargo-close').addEventListener('click', () => {
    if (!cargo.trip && cargo.place && cargo.name) {
      cargo.place = null;
      drawMap();
      return;
    }

    cargo.trip = false;
    cargo.place = null;
    $('#cargo-panel').hidden = true;
    $('#map-window').hidden = true;
  });
}

/**
 * Grades the lit places by what the player was paid at them, as the offline
 * alternative to UEX's view of today.
 */
function shadeFromReceipts(name, buying) {
  const rows = receiptsFor(name, buying).filter((r) => r.id);
  if (!rows.length) return;

  // A place you have traded at is an answer even when the catalogue has never
  // heard of it, so receipts light their own nodes rather than only grading
  // the ones the catalogue lit.
  for (const row of rows) {
    highlightIds.add(row.id);
    nodeShade.set(row.id, { value: row.best });
  }

  const values = rows.map((r) => r.best);
  const min = Math.min(...values);
  const max = Math.max(...values);

  for (const shade of nodeShade.values()) {
    const t = max === min ? 1 : (shade.value - min) / (max - min);
    shade.colour = shadeColour(buying ? 1 - t : t);
  }

  shadeScale = {
    min,
    max,
    invert: buying,
    unit: 'aUEC/SCU',
    label: buying
      ? `your buy price, ${windowWord()}, cheapest is gold`
      : `your sell price, ${windowWord()}, best is gold`,
    plain: 'no receipt of yours here',
  };
}

/* ---------- flight plans ---------- */

/**
 * The player's own routes: where they mean to go, in order.
 *
 * Everything else on this page is observed or downloaded. A plan is authored,
 * so it lives on the server rather than in the browser - the overlay is a
 * second window onto the same session, and a plan that existed in only one of
 * them would be worse than none.
 */
let trips = [];

/** The plan the Now card and the map are following. */
const tracked = () => trips.find((t) => t.tracked) || null;

/** Where to go now, or what remains to do after reaching the current stop. */
const nextStop = (trip) => trip?.stops.find((s) =>
  !s.done || (s.actions || []).some((action) => !action.done)) || null;

async function loadTrips() {
  trips = await getJson(`/api/trips${importedQuery()}`);
  renderTripCard();
  reloadPilotBriefing().catch(() => {});
  if (!$('#cargo-panel').hidden && cargo.trip) renderTripPanel();
  // A plan can itself be the active map layer; rebuild then so adding,
  // reordering, or crossing off a stop never leaves a ghost destination.
  if (mapFocusFilter === 'plan') drawMap();
  else drawTripPath();
}

/** POST/DELETE against the trip API, then re-read: plans are small. */
async function tripCall(url, method = 'POST') {
  await fetch(url, { method });
  await loadTrips();
}

/** A run sheet is authored work, so checks and edits use the same small trip API. */
async function runActionCall(url, method = 'POST', body = null) {
  const options = { method };
  if (body) {
    options.headers = { 'Content-Type': 'application/json' };
    options.body = JSON.stringify(body);
  }
  await fetch(url, options);
  await loadTrips();
}

const runActionLabel = (kind) => ({
  load: 'Load', unload: 'Unload', buy: 'Buy', sell: 'Sell', collect: 'Collect',
  refuel: 'Refuel', repair: 'Repair', do: 'Do',
}[kind] || 'Do');

function runActionRow(trip, stop, action, editable = false) {
  const row = el('div', `run-action${action.done ? ' done' : ''}`);
  const check = document.createElement('input');
  check.type = 'checkbox';
  check.checked = !!action.done;
  check.title = action.done ? 'Mark as still to do' : 'Mark action complete';
  check.addEventListener('change', () =>
    runActionCall(`/api/trips/${trip.id}/stops/${stop.id}/actions/${action.id}/toggle`));
  row.append(check);

  const text = el('span', 'run-action-text');
  text.append(el('b', null, runActionLabel(action.kind)));
  text.append(document.createTextNode(` · ${action.text}`));
  if (action.quantity !== null && action.quantity !== undefined) {
    const quantity = Number(action.quantity).toLocaleString();
    text.append(el('span', 'run-action-quantity', `${quantity}${action.unit ? ` ${action.unit}` : ''}`));
  }
  row.append(text);

  if (editable) {
    const remove = el('button', 'ghost tiny', '×');
    remove.title = 'Remove this action';
    remove.addEventListener('click', () =>
      runActionCall(`/api/trips/${trip.id}/stops/${stop.id}/actions/${action.id}`, 'DELETE'));
    row.append(remove);
  }

  return row;
}

function runActionForm(trip, stop) {
  const form = el('div', 'run-action-form');
  const kind = document.createElement('select');
  kind.className = 'select';
  for (const value of ['load', 'unload', 'buy', 'sell', 'collect', 'refuel', 'repair', 'do'])
    kind.append(new Option(runActionLabel(value), value));

  const text = document.createElement('input');
  text.type = 'text';
  text.className = 'search';
  text.placeholder = 'What needs doing?';

  const quantity = document.createElement('input');
  quantity.type = 'number';
  quantity.className = 'search run-action-amount';
  quantity.placeholder = 'Qty';
  quantity.min = '0';
  quantity.step = 'any';

  const unit = document.createElement('select');
  unit.className = 'select';
  unit.append(new Option('No unit', ''));
  unit.append(new Option('SCU', 'SCU'));
  unit.append(new Option('units', 'units'));
  unit.append(new Option('aUEC', 'aUEC'));

  const save = el('button', 'ghost tiny', 'Add');
  save.addEventListener('click', () => {
    if (!text.value.trim()) {
      text.focus();
      return;
    }
    runActionCall(`/api/trips/${trip.id}/stops/${stop.id}/actions`, 'POST', {
      kind: kind.value,
      text: text.value,
      quantity: quantity.value === '' ? null : Number(quantity.value),
      unit: unit.value || null,
    });
  });

  form.append(kind, text, quantity, unit, save);
  return form;
}

/**
 * Adds a stop to whatever plan the player is filling, and says where it went.
 *
 * The map, the routes table and a shopping list all funnel through here, so a
 * stop means the same thing wherever it came from.
 */
async function addStop(placeId, place, note) {
  await fetch('/api/trips/stops', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ placeId: placeId || '', place, note: note || null }),
  });

  await loadTrips();
  showTripPanel();
}

/** Starts a plan from a list of stops - a trade run, or a shopping trip. */
async function planTrip(title, stops) {
  await fetch('/api/trips', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title, stops }),
  });

  await loadTrips();
  showView('map');
  showTripPanel();
  drawMap();
}

/* ---------- the Now card ---------- */

/**
 * The tracked plan on the Now page, and so in the overlay: where to go next,
 * then the rest of the run.
 */
function renderTripCard() {
  const card = $('#now-trip-card');
  if (!card) return;

  const trip = tracked();

  if (!trip || !trip.stops.length) {
    card.hidden = true;
    return;
  }

  const done = trip.stops.filter((s) => s.done).length;
  const next = nextStop(trip);

  $('#now-trip-title').textContent = trip.title;

  const progress = $('#now-trip-progress');
  progress.textContent = '';
  progress.append(jobProgress(done, trip.stops.length,
    `${done} of ${trip.stops.length} stops`));

  const jump = $('#now-trip-next');
  jump.textContent = '';

  if (next) {
    jump.append(el('div', 'now-trip-label', next.done ? 'At this stop' : 'Jump next'));
    jump.append(el('div', 'now-trip-where', next.place));
    if (next.note) jump.append(el('div', 'now-trip-note', next.note));
  } else {
    jump.append(el('div', 'inward', 'Every stop is crossed off. Good run.'));
  }

  // The whole path, in order, ticked as it goes - the flight plan proper.
  const list = $('#now-trip-stops');
  list.textContent = '';

  trip.stops.forEach((stop, index) => {
    list.append(tripStopRow(trip, stop, index, stop === next));
  });

  card.hidden = false;
}

/**
 * One stop, wherever it is shown. Clicking the number crosses it off; clicking
 * the name flies the map to it.
 */
function tripStopRow(trip, stop, index, isNext, editable = false) {
  const row = el('div', `trip-stop${stop.done ? ' done' : ''}${isNext ? ' next' : ''}`);

  const number = el('button', 'trip-number', stop.done ? '✓' : String(index + 1));
  number.title = stop.done ? 'Not done after all' : 'Cross this stop off';
  number.addEventListener('click',
    () => tripCall(`/api/trips/${trip.id}/stops/${stop.id}/toggle`));
  row.append(number);

  const main = el('div', 'trip-stop-main');
  const name = el('button', 'trip-place', stop.place);
  name.title = 'Show it on the map';
  name.addEventListener('click', () => {
    showView('map');
    if (stop.placeId) centreOn(stop.placeId);
    showTripPanel();
  });

  main.append(name);
  if (stop.note) main.append(el('div', 'trip-note', stop.note));
  for (const action of (stop.actions || []))
    main.append(runActionRow(trip, stop, action, editable));
  row.append(main);

  return row;
}

/* ---------- the map's trip panel ---------- */

/** Opens the side panel on the tracked plan. */
function showTripPanel() {
  cargo.place = null;
  cargo.trip = true;
  renderTripPanel();
}

function renderTripPanel() {
  const trip = tracked();
  const body = cargoPanelHead('Flight plan', trip ? trip.title : 'No plan yet');

  if (!trip || !trip.stops.length) {
    body.append(el('div', 'cargo-empty',
      'Double-click a place, or use Add stop on its card, to start a plan. '
      + 'A trade route or a shopping list can start one for you.'));

    // Finishing your only run leaves nothing tracked, and the runs you have
    // flown are exactly what you want to see at that moment - so the filed
    // list is drawn on this path too, not only when a plan is open.
    renderFiledRuns(body);
    return;
  }

  const done = trip.stops.filter((s) => s.done).length;
  body.append(jobProgress(done, trip.stops.length, `${done} of ${trip.stops.length} stops`));

  const next = nextStop(trip);

  trip.stops.forEach((stop, index) => {
    const row = tripStopRow(trip, stop, index, stop === next, true);

    // The panel is where a plan is edited; the Now card only reads it.
    const tools = el('div', 'trip-tools');

    const up = el('button', 'ghost tiny', '↑');
    up.title = 'Earlier in the run';
    up.disabled = index === 0;
    up.addEventListener('click',
      () => tripCall(`/api/trips/${trip.id}/stops/${stop.id}/move?delta=-1`));

    const down = el('button', 'ghost tiny', '↓');
    down.title = 'Later in the run';
    down.disabled = index === trip.stops.length - 1;
    down.addEventListener('click',
      () => tripCall(`/api/trips/${trip.id}/stops/${stop.id}/move?delta=1`));

    const drop = el('button', 'ghost tiny', '×');
    drop.title = 'Drop this stop';
    drop.addEventListener('click',
      () => tripCall(`/api/trips/${trip.id}/stops/${stop.id}`, 'DELETE'));

    const addAction = el('button', 'ghost tiny', '+');
    addAction.title = 'Add a run-sheet action at this stop';
    addAction.addEventListener('click', () => {
      const existing = row.querySelector('.run-action-form');
      if (existing) existing.remove();
      else row.append(runActionForm(trip, stop));
    });

    tools.append(addAction, up, down, drop);
    row.append(tools);
    body.append(row);
  });

  const actions = el('div', 'trip-actions');

  // A run has a beginning and an end and neither is guessed: the app cannot
  // tell setting off from opening the page, so it asks once and then knows.
  if (trip.archived === 'No' || trip.archived === undefined) {
    const lifecycle = el('button', trip.flying ? 'primary' : 'ghost',
      trip.flying ? 'Finish run' : 'Start run');

    lifecycle.title = trip.flying
      ? 'Stop the clock and file this run'
      : 'Start the clock — elapsed time is measured from here, not from when you wrote the plan';

    lifecycle.addEventListener('click',
      () => tripCall(`/api/trips/${trip.id}/${trip.flying ? 'finish' : 'start'}`));

    actions.append(lifecycle);
  }

  const track = el('button', 'ghost', trip.tracked ? 'Stop tracking' : 'Track');
  track.title = 'Show this plan on the Now page';
  track.addEventListener('click', () => tripCall(`/api/trips/${trip.id}/track`));
  actions.append(track);

  const scrap = el('button', 'ghost danger', 'Delete plan');
  scrap.addEventListener('click', async () => {
    await tripCall(`/api/trips/${trip.id}`, 'DELETE');
    cargo.trip = false;
    $('#cargo-panel').hidden = true;
    drawMap();
  });
  actions.append(scrap);

  body.append(actions);

  if (trip.flying) {
    body.append(el('div', 'trip-elapsed muted',
      `Running for ${spanOf(trip.elapsedSeconds)} — since you pressed Start, not since you wrote it.`));
  }

  // Other plans, so one can be picked up again without a management screen.
  const others = trips.filter((t) => t !== trip && !isFiled(t));

  if (others.length) {
    body.append(el('div', 'cargo-h', 'Other plans'));

    for (const other of others) {
      const row = el('div', 'cargo-row');
      row.append(el('span', 'swatch'));

      const main = el('div', 'cargo-row-main');
      main.append(el('div', 'name', other.title));
      main.append(el('div', 'sub',
        `${other.stops.filter((s) => s.done).length} of ${other.stops.length} stops`));
      row.append(main);

      row.tabIndex = 0;
      row.addEventListener('click', () => tripCall(`/api/trips/${other.id}/track`));
      body.append(row);
    }
  }

  renderFiledRuns(body);
}

/**
 * Runs that are out of the working list, and the two ways back.
 *
 * A run filed by the sweep and a run you finished are listed together but do
 * not read the same: one is over, the other only went quiet, and offering
 * "resume" on both would suggest the app knows which of them you meant to stop.
 */
function renderFiledRuns(body) {
  const filed = trips.filter(isFiled);
  if (!filed.length) return;

  body.append(el('div', 'cargo-h', 'Finished and filed'));

  for (const run of filed) {
    const row = el('div', 'cargo-row');
    row.append(el('span', 'swatch'));

    const main = el('div', 'cargo-row-main');
    main.append(el('div', 'name', run.title));

    const done = run.stops.filter((s) => s.done).length;
    main.append(el('div', 'sub', run.archived === 'Quiet'
      ? `${done} of ${run.stops.length} stops — filed itself after going quiet`
      : `${done} of ${run.stops.length} stops — ${spanOf(run.elapsedSeconds)}`));

    row.append(main);

    const tools = el('div', 'trip-tools');

    // Only offered on the ones the app filed on its own. A run you finished is
    // finished, and a button undoing that would make the sweep and the pilot
    // look like the same decision.
    if (run.archived === 'Quiet') {
      const resume = el('button', 'ghost tiny', 'Resume');
      resume.title = 'Put this back — it keeps the time it started';
      resume.addEventListener('click', () => tripCall(`/api/trips/${run.id}/resume`));
      tools.append(resume);
    }

    const look = el('button', 'ghost tiny', 'Review');
    look.title = 'What this run planned, against what your logs recorded';
    look.addEventListener('click', () => showRunReview(run.id).catch(() => {}));
    tools.append(look);

    const again = el('button', 'ghost tiny', 'Repeat');
    again.title = 'Fly the same route again, with nothing ticked off';
    again.addEventListener('click', () => tripCall(`/api/trips/${run.id}/repeat`));
    tools.append(again);

    row.append(tools);
    body.append(row);
  }
}

/** Out of the working list, however it got there. */
function isFiled(trip) {
  return trip.archived === 'You' || trip.archived === 'Quiet';
}

/** A duration in the shortest words that stay honest about it. */
function spanOf(seconds) {
  if (!seconds || seconds < 0) return 'no time at all';

  const minutes = Math.round(seconds / 60);
  if (minutes < 60) return `${minutes} min`;

  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;

  if (hours < 24) return rest ? `${hours}h ${rest}m` : `${hours}h`;

  const days = Math.floor(hours / 24);
  return `${days}d ${hours % 24}h`;
}

/* ---------- run review ---------- */

/**
 * What a run planned, against what the logs recorded while it ran.
 *
 * Opened from a filed run rather than living on its own page: a review is about
 * one run, and the list of runs is where you already are when you want one.
 */
async function showRunReview(id) {
  cargo.place = null;
  cargo.trip = false;

  const body = cargoPanelHead('Run review', 'Reading the logs…');

  let review;

  try {
    review = await getJson(`/api/trips/${encodeURIComponent(id)}/review`);
  } catch {
    cargoPanelHead('Run review', 'Nothing to review')
      .append(el('div', 'cargo-empty',
        'This plan has never been started, so there is nothing to compare against yet.'));
    return;
  }

  renderRunReview(review);
}

function renderRunReview(review) {
  const body = cargoPanelHead('Run review', review.title);

  const when = [
    review.startedAt ? `Started ${dateOf(review.startedAt)}` : null,
    review.elapsedSeconds ? `took ${spanOf(review.elapsedSeconds)}` : null,
  ].filter(Boolean).join(' · ');

  if (when) body.append(el('div', 'sub muted', when));

  body.append(runFigure('Money in', review.earned));
  body.append(runFigure('Money out', review.spent));

  body.append(el('div', 'cargo-h', 'Stop by stop'));

  for (const stop of review.stops) {
    const block = el('div', 'run-stop');

    const head = el('div', 'run-stop-head');
    head.append(el('span', 'name', stop.place));
    head.append(el('span', 'muted', stop.doneAt ? dateOf(stop.doneAt) : 'never reached'));
    block.append(head);

    if (stop.note) block.append(el('div', 'sub muted', stop.note));

    for (const action of stop.planned) block.append(runPlannedRow(review, stop, action));

    for (const claim of stop.claimed) {
      const row = el('div', 'run-claim');
      row.append(el('span', 'muted', claim.kind));
      row.append(el('span', null, claim.what));
      row.append(el('span', claim.amount >= 0 ? 'amount in' : 'amount out', money(claim.amount)));
      block.append(row);
    }

    // Said rather than left blank: most stops move no money, and an empty space
    // reads as a gap in the data instead of an ordinary stop.
    if (!stop.planned.length && !stop.claimed.length) {
      block.append(el('div', 'sub muted', 'Nothing planned, and no money moved here.'));
    }

    body.append(block);
  }

  if (review.unclaimed.length) {
    body.append(el('div', 'cargo-h', 'During the run, but not at a stop'));
    body.append(el('div', 'sub muted',
      'Money that moved while this run was going that no stop can account for. '
      + 'Listed rather than added in — attaching it to the nearest stop would be a guess.'));

    for (const claim of review.unclaimed) {
      const row = el('div', 'run-claim');
      row.append(el('span', 'muted', dateOf(claim.at)));
      row.append(el('span', null, `${claim.what} at ${claim.where}`));

      // Muted, not green: this money is real and is not in the figure above,
      // and colouring it like counted income would say otherwise.
      row.append(el('span', 'amount loose', money(claim.amount)));
      body.append(row);
    }
  }
}

/**
 * One figure, and the button that says where it came from.
 *
 * The explanation is folded away rather than absent: a number nobody is
 * questioning does not need three lines of provenance under it, and a number
 * somebody is questioning needs all of it.
 */
function runFigure(label, figure) {
  const block = el('div', 'run-figure');

  const head = el('div', 'run-figure-head');
  head.append(el('span', 'muted', label));
  head.append(el('span', 'run-figure-value', money(figure.value)));

  const why = el('button', 'ghost tiny', 'Why this number?');
  const detail = el('div', 'run-why');
  detail.hidden = true;

  why.addEventListener('click', () => {
    detail.hidden = !detail.hidden;
    why.textContent = detail.hidden ? 'Why this number?' : 'Hide';
  });

  head.append(why);
  block.append(head);

  detail.append(el('div', 'sub muted', figure.rule));

  for (const line of figure.excluded) detail.append(el('div', 'run-excluded', line));

  if (figure.from.length) {
    const list = el('div', 'run-from');

    for (const claim of figure.from) {
      const row = el('div', 'run-claim');
      row.append(el('span', 'muted', dateOf(claim.at)));
      row.append(el('span', null, `${claim.what} at ${claim.where}`));
      row.append(el('span', 'amount', money(claim.amount)));
      list.append(row);
    }

    detail.append(list);
  } else {
    detail.append(el('div', 'sub muted', 'No records behind this one — nothing was matched to a stop.'));
  }

  block.append(detail);
  return block;
}

/**
 * A planned action, with room to say what it actually came to.
 *
 * The estimate stays on screen beside the correction. Replacing one with the
 * other would leave nothing to compare, which is the entire reason a review
 * records both.
 */
function runPlannedRow(review, stop, action) {
  const row = el('div', 'run-planned');

  row.append(el('span', 'muted', action.kind));
  row.append(el('span', null, action.text));

  const planned = action.quantity === null || action.quantity === undefined
    ? '—'
    : `${action.quantity.toLocaleString()}${action.unit ? ` ${action.unit}` : ''}`;

  row.append(el('span', 'muted planned-was', `planned ${planned}`));

  const actual = el('input', 'run-actual');
  actual.type = 'number';
  actual.placeholder = 'actual';
  actual.title = 'What it came to. Leave empty if you have not checked.';
  if (action.actual !== null && action.actual !== undefined) actual.value = String(action.actual);

  actual.addEventListener('change', async () => {
    const value = actual.value.trim();
    const query = value === '' ? '' : `?amount=${encodeURIComponent(value)}`;

    await fetch(
      `/api/trips/${encodeURIComponent(review.tripId)}/stops/${encodeURIComponent(stop.stopId)}`
      + `/actions/${encodeURIComponent(action.id)}/actual${query}`,
      { method: 'POST' });
  });

  row.append(actual);
  return row;
}

/* ---------- saved kits ---------- */

let kits = [];
let preparing = null;

/**
 * What each holding means, in the reader's terms.
 *
 * "Seen" and "Stale" are the same fact at two ages, and both are questions. The
 * wording has to carry that: a page that says "in your stash" about a sighting
 * is making the claim this whole feature exists to avoid.
 */
const KIT_HOLDING = {
  Equipped: ['You are wearing it', false],
  Seen: ['Last seen in storage', true],
  Stale: ['Not seen for a while', true],
  Missing: ['Never seen anywhere', false],
};

async function loadKits() {
  kits = await getJson('/api/kits');
  renderKits();
}

function renderKits() {
  const list = $('#kit-list');
  if (!list) return;

  list.textContent = '';

  if (!kits.length) {
    list.append(el('p', 'muted', 'No kits yet. Save what you are wearing to make one.'));
    return;
  }

  for (const kit of kits) {
    const row = el('div', 'kit-row');

    const main = el('div', 'kit-row-main');
    main.append(el('div', 'name', kit.name));
    main.append(el('div', 'sub muted',
      `${kit.items.length} item${kit.items.length === 1 ? '' : 's'}`));
    row.append(main);

    const prepare = el('button', 'ghost tiny', 'Prepare');
    prepare.title = 'Compare this kit with what you have';
    prepare.addEventListener('click', () => prepareKit(kit.id).catch(() => {}));
    row.append(prepare);

    const drop = el('button', 'ghost tiny danger', '×');
    drop.title = 'Delete this kit';
    drop.addEventListener('click', async () => {
      await fetch(`/api/kits/${encodeURIComponent(kit.id)}`, { method: 'DELETE' });
      if (preparing?.kitId === kit.id) closeKitPrepare();
      await loadKits();
    });
    row.append(drop);

    list.append(row);
  }
}

/**
 * Saves what the character is wearing as a kit.
 *
 * Built from the loadout the page already has rather than asking the server
 * again: this is the same list on screen, and a second read could disagree with
 * what the pilot is looking at.
 */
async function saveWornAsKit() {
  const status = $('#kit-status');
  const name = $('#kit-name').value.trim();

  const items = (libraryStats?.loadout || [])
    .flatMap((slot) => slot.items || [])
    .map((item) => ({ name: item.name, quantity: item.count || 1, optional: false }));

  if (!items.length) {
    status.textContent = 'Nothing is showing in your loadout yet, so there is nothing to save.';
    return;
  }

  await fetch('/api/kits', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ name: name || 'Kit', items }),
  });

  $('#kit-name').value = '';
  status.textContent = `Saved ${items.length} item${items.length === 1 ? '' : 's'}.`;
  await loadKits();
}

async function prepareKit(id) {
  preparing = await getJson(`/api/kits/${encodeURIComponent(id)}/prepare`);
  renderKitPrepare();
}

function renderKitPrepare() {
  const panel = $('#kit-prepare');
  panel.hidden = !preparing;
  if (!preparing) return;

  $('#kit-prepare-title').textContent = `Preparing ${preparing.name}`;
  $('#kit-prepare-rule').textContent = preparing.rule;

  const body = $('#kit-prepare-table').querySelector('tbody');
  body.textContent = '';

  for (const line of preparing.lines) {
    const [words, asks] = KIT_HOLDING[line.holding] || [line.holding, false];

    const row = el('tr');

    const name = el('td');
    name.append(el('span', null, line.name));
    if (line.quantity > 1) name.append(el('span', 'note-inline muted', ` ×${line.quantity}`));
    if (line.optional) name.append(el('span', 'note-inline muted', ' optional'));
    row.append(name);

    // Where it was only matters for the lines that need answering. Equipped
    // already carries its own place in the wording, and "You are wearing it —
    // on you" says the same thing twice.
    // A known shortfall is neither a missing item nor a question. Calling one
    // medpen in a kit of four "never seen anywhere" discards the useful fact
    // that one is on the character, then leaves the pilot unable to tell why
    // the shopping list has three rather than four.
    const holding = line.short > 0
      ? `${line.held} on you · ${line.short} still needed`
      : asks && line.where ? `${words} — ${line.where}` : words;
    row.append(el('td', line.holding === 'Missing' ? 'muted want' : 'muted', holding));

    row.append(el('td', 'muted', line.lastSeen ? dateOf(line.lastSeen) : '—'));

    const answer = el('td');

    // Only the uncertain lines get a control. Offering one against something
    // the game actually reported would invite an answer the app should not
    // take, and offering one against "never seen" asks about nothing.
    if (asks) {
      const gone = el('button', 'ghost tiny');
      gone.textContent = 'I have it';
      gone.dataset.name = line.name;
      gone.dataset.gone = 'false';

      gone.addEventListener('click', () => {
        const isGone = gone.dataset.gone !== 'true';
        gone.dataset.gone = String(isGone);
        gone.textContent = isGone ? 'It is gone' : 'I have it';
        gone.classList.toggle('want', isGone);
      });

      answer.append(gone);
    } else {
      answer.append(el('span', 'muted', line.holding === 'Missing' ? 'on the list' : 'settled'));
    }

    row.append(answer);
    body.append(row);
  }
}

async function makeKitShopping() {
  const status = $('#kit-status');

  // Only what the pilot actually said is gone. Silence is left as held, which
  // is the direction that costs a trip rather than a purchase.
  const gone = Array.from($('#kit-prepare-table').querySelectorAll('button'))
    .filter((button) => button.dataset.gone === 'true')
    .map((button) => button.dataset.name);

  const query = gone.length ? `?gone=${encodeURIComponent(gone.join(','))}` : '';

  const response = await fetch(
    `/api/kits/${encodeURIComponent(preparing.kitId)}/shopping${query}`, { method: 'POST' });

  const answer = await response.json();

  status.textContent = answer.items === 0
    ? 'Nothing to buy — everything in this kit is either on you or accounted for.'
    : `Made a list of ${answer.items} item${answer.items === 1 ? '' : 's'}. It is on the Jobs page.`;

  closeKitPrepare();
  await loadJobs().catch(() => {});
}

function closeKitPrepare() {
  preparing = null;
  $('#kit-prepare').hidden = true;
}

$('#kit-from-loadout')?.addEventListener('click', () => saveWornAsKit().catch(() => {}));
$('#kit-shopping')?.addEventListener('click', () => makeKitShopping().catch(() => {}));
$('#kit-prepare-close')?.addEventListener('click', closeKitPrepare);

/* ---------- the plan on the map ---------- */

/**
 * Draws the tracked plan over the map: numbered stops in running order, joined
 * by the path between them.
 *
 * Numbers rather than colour, because the question is "where next", not "how
 * good": a plan has an order and the map has to show it. Stops the map cannot
 * place - somewhere with no engine id - are still listed in the panel, so a
 * plan is never silently short of a stop.
 */
function drawTripPath() {
  const map = $('#starmap');
  if (!map) return;

  map.querySelectorAll('.trip-layer').forEach((n) => n.remove());

  const trip = tracked();
  if (!trip) return;

  const points = trip.stops
    .map((stop, index) => ({ stop, index, at: nodeAt.get(stop.placeId) }))
    .filter((p) => p.at);

  if (!points.length) return;

  const layer = svgEl('g', { class: 'trip-layer' });
  const zoom = view.w / HOME_VIEW.w;
  const next = nextStop(trip);

  // The path first, so the numbers sit on top of it.
  for (let i = 1; i < points.length; i++) {
    const from = points[i - 1];
    const to = points[i];

    layer.append(svgEl('line', {
      x1: from.at.x, y1: from.at.y, x2: to.at.x, y2: to.at.y,
      class: `trip-leg${to.stop.done ? ' done' : ''}`,
      'stroke-width': 1.6 * zoom,
      'stroke-dasharray': `${6 * zoom} ${5 * zoom}`,
    }));
  }

  for (const point of points) {
    const badge = svgEl('g', {
      class: `trip-mark${point.stop.done ? ' done' : ''}${point.stop === next ? ' next' : ''}`,
    });

    badge.append(svgEl('circle', {
      cx: point.at.x, cy: point.at.y - 15 * zoom, r: 8 * zoom, 'stroke-width': 1.4 * zoom,
    }));

    const number = svgEl('text', {
      x: point.at.x, y: point.at.y - 15 * zoom, 'text-anchor': 'middle',
      'dominant-baseline': 'central', style: `font-size:${9 * zoom}px`,
    });

    number.textContent = point.stop.done ? '✓' : String(point.index + 1);
    badge.append(number);

    const title = svgEl('title');
    title.textContent = `Stop ${point.index + 1}: ${point.stop.place}`
      + (point.stop.note ? ` — ${point.stop.note}` : '');
    badge.append(title);

    badge.addEventListener('click', (e) => {
      e.stopPropagation();
      showTripPanel();
    });

    layer.append(badge);
  }

  map.append(layer);
}

/**
 * Opens the plan when the player lands on one of its stops.
 *
 * Arriving is the moment the stop's note matters - what was I here to buy? -
 * and the server has already crossed it off by the time this runs.
 */
let tripHere = null;

function tripArrived(locationId) {
  if (!locationId || locationId === tripHere) return;
  tripHere = locationId;

  const trip = tracked();
  if (!trip || !trip.stops.some((s) => s.placeId === locationId)) return;

  loadTrips().then(() => {
    cargo.trip = true;
    cargo.place = null;
    renderTripPanel();
  });
}

/**
 * The atlas place a UEX terminal name belongs to, or empty.
 *
 * Terminal names are not atlas names - "TDD, Area 18" against "Area18" - and
 * the server does that join once, from the atlas, so every page agrees on the
 * answer. Rows that carry a `placeId` are believed; this is only the fallback
 * for a terminal name arriving from somewhere that has not been given one.
 * A stop the map cannot place still belongs on the plan.
 */
const placeIdForTerminal = (terminal) =>
  atlas.find((l) => terminalMatchesPlace(terminal, l.name))?.rawId || '';

/**
 * Where a line on a list can be bought, cheapest first, cached for the session.
 *
 * The list's own `buyAt` is only ever the cheapest one UEX knows. That is a
 * fine default and a poor answer: the cheapest seller of a common good is
 * routinely three jumps out of the way, and the player is the only one who
 * knows what else the run has to fit around.
 *
 * A line is whatever the player wrote, so the server is asked rather than the
 * commodity market alone: "Agricium" is a trade good, "Bulwark" is a shield
 * bought from a shop counter, and a shopping list is allowed to hold both.
 */
const sellerCache = new Map();

async function sellersOf(item) {
  if (sellerCache.has(item.name)) return sellerCache.get(item.name);

  const fallback = item.buyAt
    ? [{ terminal: item.buyAt, placeId: placeIdForTerminal(item.buyAt), price: item.buyPrice || 0, scu: 0 }]
    : [];

  const found = await getJson(`/api/shopping/sellers?name=${encodeURIComponent(item.name)}`)
    .catch(() => null);

  const sellers = (found?.sellers ?? [])
    .slice(0, 12)
    .map((r) => ({
      terminal: r.terminal,
      placeId: r.placeId || placeIdForTerminal(r.terminal),
      place: r.place || '',
      system: r.system || '',
      security: r.security || 'unknown',
      price: r.price,
      scu: r.scu || 0,
      kind: r.kind,
    }));

  const answer = sellers.length ? sellers : fallback;
  sellerCache.set(item.name, answer);
  return answer;
}

/**
 * Stock is per terminal and the list says how much is wanted, so the two can
 * be compared: flying to the cheapest seller of 10 SCU to find 3 is a wasted
 * landing, and the page knew before you left.
 */
const shortStock = (seller, item) =>
  item.needed > 0 && seller.scu > 0 && seller.scu < item.needed;

/**
 * The seller a line starts on.
 *
 * A list written for a place is a decision already made, so a counter there
 * wins even when somewhere else is cheaper - that is the whole point of saying
 * where you are going. Otherwise: the cheapest that can actually fill the
 * order, else the cheapest.
 */
const defaultSeller = (sellers, item, destination) => {
  const there = destination && sellers.filter((seller) => atSameStop(seller, destination));

  if (there?.length)
    return there.find((seller) => !shortStock(seller, item)) ?? there[0];

  return sellers.find((seller) => !shortStock(seller, item)) ?? sellers[0];
};

/** Whether a seller stands at the place a list is pointed at. */
const atSameStop = (seller, destination) => {
  if (!destination) return false;

  if (destination.id && seller.placeId) return seller.placeId === destination.id;

  return !!destination.name && (
    terminalMatchesPlace(seller.terminal, destination.name)
    || (!!seller.place && terminalMatchesPlace(seller.place, destination.name)));
};

function sellerLabel(seller, item) {
  const stock = seller.scu
    ? ` · ${Math.round(seller.scu).toLocaleString()} SCU${shortStock(seller, item) ? ' — short' : ''}`
    : '';

  // Where it is and whether the law reaches it: the cheapest counter is
  // routinely the one in Pyro, and that is a decision, not a detail.
  const where = seller.system ? ` · ${seller.system}` : '';
  const risk = seller.security === 'lawless' ? ' — lawless' : '';

  return seller.price > 0
    ? `${seller.terminal} · ${money(seller.price)}${stock}${where}${risk}`
    : `${seller.terminal}${stock}${where}${risk}`;
}

/**
 * Turns what a list is still missing into a run, grouping its purchases into
 * a stop-efficient route from the sellers we know.
 *
 * One stop per terminal rather than per item, because a trip is a sequence of
 * places: three things bought at Area18 is one landing. Prices decide between
 * equally useful counters; they do not add a landing just to save a little.
 * Anything with no known seller is shown and left off rather than quietly
 * dropped.
 */
async function planShoppingTrip(job, card) {
  card.querySelectorAll('.trip-chooser').forEach((n) => n.remove());

  const missing = job.items.filter((i) => !i.have);

  if (!missing.length) {
    alertLine($('#jobs-list'), 'Everything on this list is already in hand.');
    return;
  }

  // Where this list said it was for, when it said anything.
  const destination = job.destination
    ? { name: job.destination, id: job.destinationId || '' }
    : null;

  const chooser = el('div', 'trip-chooser');

  const head = el('div', 'chooser-head');
  head.append(el('span', null, destination
    ? `Where to buy — ${destination.name} first, fewest stops after`
    : 'Where to buy — optimised for fewer stops'));
  chooser.append(head);

  const rows = el('div', 'chooser-rows');
  rows.append(el('div', 'muted', 'Looking up sellers…'));
  chooser.append(rows);
  card.append(chooser);

  const options = await Promise.all(missing.map(async (item) => ({
    item,
    sellers: await sellersOf(item),
  })));

  rows.textContent = '';

  // What the player picked, item name to terminal. Empty means "leave it off".
  const chosen = new Map();
  const foot = el('div', 'chooser-foot');
  const count = el('span', 'muted');

  const retally = () => {
    const stops = new Set([...chosen.values()].filter(Boolean));
    count.textContent = stops.size
      ? `${stops.size} stop${stops.size === 1 ? '' : 's'}`
      : 'nothing chosen';
  };

  /*
   * The same decision, seen from either end.
   *
   * By item is "where do I get this", which is how a list is written. By
   * location is "what is this landing worth", which is how a run is flown -
   * the point of a shopping list is to rotate around the map picking things
   * up, and that question cannot be answered one dropdown at a time. Both
   * write into `chosen`, so switching view never loses a choice, and the plan
   * is built from the one answer either of them wrote.
   */
  const stops = [];

  // A quoted stock figure below the list's quantity cannot fill that line.
  // When every quote is short we still show the alternatives, because the
  // player may decide a partial purchase is useful; otherwise a full seller
  // is the only one allowed into the automatic route.
  const suppliesAt = (sellers, item, terminal) => {
    const here = sellers.filter((seller) => seller.terminal === terminal);
    if (!here.length) return false;
    return here.some((seller) => !shortStock(seller, item))
      || !sellers.some((seller) => !shortStock(seller, item));
  };

  // A practical set cover: take the counter that supplies the most remaining
  // lines, then use the price of just those lines to settle a tie. It is kept
  // deliberately local to this chooser, because stock and a pilot's manual
  // selections are live UI facts rather than data worth persisting on a job.
  const optimiseStops = () => {
    stops.length = 0;
    const left = new Set(options.filter((o) => o.sellers.length).map((o) => o.item.name));

    while (left.size) {
      const best = [...new Map(options.flatMap(({ item, sellers }) => sellers.map((seller) => [seller.terminal, seller]))).values()]
        .map((seller) => ({
          seller,
          covers: options.filter(({ item, sellers }) => left.has(item.name)
            && suppliesAt(sellers, item, seller.terminal)),
        }))
        .filter((counter) => counter.covers.length)
        .sort((a, b) => Number(atSameStop(b.seller, destination)) - Number(atSameStop(a.seller, destination))
          || b.covers.length - a.covers.length
          || a.covers.reduce((sum, { item, sellers }) => {
            const seller = sellers.find((candidate) => candidate.terminal === a.seller.terminal);
            return sum + (seller?.price || 0) * Math.max(1, item.needed);
          }, 0) - b.covers.reduce((sum, { item, sellers }) => {
            const seller = sellers.find((candidate) => candidate.terminal === b.seller.terminal);
            return sum + (seller?.price || 0) * Math.max(1, item.needed);
          }, 0)
          || a.seller.terminal.localeCompare(b.seller.terminal))[0];

      if (!best) break;
      stops.push(best.seller.terminal);
      best.covers.forEach(({ item }) => left.delete(item.name));
    }

    assignFromStops();
  };

  const renderItems = () => {
    rows.textContent = '';

    for (const { item, sellers } of options) {
      const row = el('div', 'chooser-row');

      const what = el('div', 'chooser-what');
      what.append(el('div', 'name', item.name));
      what.append(el('div', 'sub', item.needed > 0
        ? `${item.needed}${item.unit ? ` ${item.unit}` : ''} needed`
        : 'any amount'));
      row.append(what);

      if (!sellers.length) {
        row.append(el('div', 'chooser-none', 'no known seller — left off'));
        rows.append(row);
        continue;
      }

      const select = el('select', 'select');

      for (const seller of sellers) {
        const option = document.createElement('option');
        option.value = seller.terminal;
        option.textContent = sellerLabel(seller, item);
        select.append(option);
      }

      const skip = document.createElement('option');
      skip.value = '';
      skip.textContent = 'Leave this one off';
      select.append(skip);

      select.value = chosen.get(item.name) ?? defaultSeller(sellers, item, destination).terminal;
      chosen.set(item.name, select.value);

      select.addEventListener('change', () => {
        chosen.set(item.name, select.value);

        // A choice made here is the player's, so a ticked stop must not
        // silently overwrite it later.
        stops.length = 0;
        retally();
      });

      row.append(select);
      rows.append(row);
    }
  };

  const renderLocations = () => {
    rows.textContent = '';

    // Every terminal any of the list can be bought at, and what it would
    // supply. Ranked by how much of the list one landing covers, then by what
    // that landing costs.
    const counters = new Map();

    for (const { item, sellers } of options)
      for (const seller of sellers) {
        const counter = counters.get(seller.terminal) || { seller, supplies: [] };

        counter.supplies.push({ item, seller });
        counters.set(seller.terminal, counter);
      }

    const ranked = [...counters.values()]
      .map((counter) => ({
        ...counter,
        cost: counter.supplies.reduce((sum, s) =>
          sum + (s.seller.price > 0 ? s.seller.price * Math.max(1, s.item.needed) : 0), 0),
        chosen: atSameStop(counter.seller, destination),
      }))

      // The place the list is for leads, whatever it carries: you are landing
      // there regardless, so what it can supply is the first question.
      .sort((a, b) => Number(b.chosen) - Number(a.chosen)
        || b.supplies.length - a.supplies.length
        || a.cost - b.cost);

    if (!ranked.length) {
      rows.append(el('div', 'muted', 'Nothing on this list has a known seller.'));
      return;
    }

    // The plan starts stop-efficient. This button returns to that answer after
    // the pilot has ticked counters by hand.
    const fewest = el('div', 'chooser-actions');
    const pack = el('button', 'ghost', 'Optimise stops');
    pack.title = 'Re-group the list into a stop-efficient route';

    pack.addEventListener('click', () => {
      optimiseStops();
      renderLocations();
      retally();
    });

    fewest.append(pack);
    rows.append(fewest);

    for (const counter of ranked) {
      const row = el('div', 'chooser-stop');

      const tick = el('label', 'stop-tick');
      const box = document.createElement('input');
      box.type = 'checkbox';
      box.checked = stops.includes(counter.seller.terminal);

      box.addEventListener('change', () => {
        const already = stops.indexOf(counter.seller.terminal);

        if (box.checked && already < 0) stops.push(counter.seller.terminal);
        else if (!box.checked && already >= 0) stops.splice(already, 1);

        assignFromStops();
        renderLocations();
        retally();
      });

      tick.append(box);
      row.append(tick);

      const what = el('div', 'stop-what');
      const name = el('div', 'name');
      name.append(el('span', null, counter.seller.terminal));

      if (counter.seller.security === 'lawless')
        name.append(el('span', 'sec sec-lawless', 'lawless'));

      what.append(name);

      // What this landing is actually for: the things it can supply, greyed
      // where a stop ticked earlier already has them.
      const supplies = el('div', 'stop-items');

      for (const { item } of counter.supplies) {
        const taken = chosen.get(item.name);
        const mine = taken === counter.seller.terminal;

        supplies.append(el('span',
          mine ? 'stop-item mine' : taken ? 'stop-item taken' : 'stop-item',
          item.name));
      }

      what.append(supplies);
      row.append(what);

      const sum = el('div', 'stop-sum');
      sum.append(el('div', null, `${counter.supplies.length} of ${options.length}`));
      if (counter.cost > 0) sum.append(el('div', 'muted', money(counter.cost)));
      if (counter.seller.system) sum.append(el('div', 'muted', counter.seller.system));
      row.append(sum);

      rows.append(row);
    }
  };

  /** Ticked stops fill the list in the order they were ticked, first come. */
  const assignFromStops = () => {
    for (const { item } of options) chosen.set(item.name, '');

    for (const terminal of stops)
      for (const { item, sellers } of options)
        if (!chosen.get(item.name) && suppliesAt(sellers, item, terminal))
          chosen.set(item.name, terminal);
  };

  const views = el('div', 'seg chooser-views');

  for (const [key, label] of [['item', 'By item'], ['location', 'By location']]) {
    const button = el('button', key === 'item' ? 'active' : null, label);

    button.addEventListener('click', () => {
      views.querySelectorAll('button').forEach((b) => b.classList.remove('active'));
      button.classList.add('active');

      if (key === 'item') {
        renderItems();
        return;
      }

      // The plan arrives here already made - by item, or by the defaults -
      // so the ticks show it rather than starting blank and quietly
      // disagreeing with the count at the bottom of the panel.
      if (!stops.length)
        for (const terminal of chosen.values())
          if (terminal && !stops.includes(terminal)) stops.push(terminal);

      renderLocations();
    });

    views.append(button);
  }

  head.append(views);

  // Do this before the first item rows render, so their selects already show
  // the grouped route instead of briefly saying every line wants its cheapest
  // counter.
  optimiseStops();
  renderItems();
  retally();

  const create = el('button', 'ghost', 'Create plan');
  create.addEventListener('click', async () => {
    const byPlace = new Map();

    for (const { item, sellers } of options) {
      const terminal = chosen.get(item.name);
      if (!terminal) continue;

      const seller = sellers.find((s) => s.terminal === terminal);
      const need = item.needed > 0
        ? `${item.name} ${item.needed}${item.unit ? ` ${item.unit}` : ''}`
        : item.name;

      const line = byPlace.get(terminal)
        || { items: [], cost: 0, priced: true, placeId: seller?.placeId || '' };

      line.items.push(need);

      if (seller?.price > 0 && item.needed > 0) line.cost += seller.price * item.needed;
      else line.priced = false;

      byPlace.set(terminal, line);
    }

    if (!byPlace.size) {
      alertLine($('#jobs-list'), 'Nothing is chosen, so there is no run to fly.');
      return;
    }

    const stops = [...byPlace.entries()].map(([place, line]) => ({
      placeId: line.placeId || placeIdForTerminal(place),
      place,

      // The estimate is only shown when every item at the stop has a price;
      // a partial total reads as the cost of the landing and is not.
      note: line.items.join(', ') + (line.priced && line.cost > 0 ? ` · ~${money(line.cost)}` : ''),
    }));

    chooser.remove();
    await planTrip(`${job.title} run`, stops);
  });

  const cancel = el('button', 'ghost', 'Cancel');
  cancel.addEventListener('click', () => chooser.remove());

  foot.append(count);
  foot.append(el('span', 'spacer'));
  foot.append(create);
  foot.append(cancel);
  chooser.append(foot);
}

/** A one-line notice under a section, for when a button cannot do its job. */
function alertLine(host, text) {
  host.querySelectorAll('.trip-alert').forEach((n) => n.remove());

  const line = el('p', 'muted trip-alert', text);
  host.prepend(line);
  setTimeout(() => line.remove(), 6000);
}

/** What the hover tip currently shows, so pointermove does not rebuild it. */
let tipKey = null;

/** Appends a capped goods line to the tip when the Goods checkbox is on. */
function appendTipGoods(tip, names) {
  if (!names.length) return;

  const shown = names.slice(0, 6).join(', ');
  tip.append(el('span', 'goods', `Sells ${shown}${names.length > 6 ? '…' : ''}`));

  // A tooltip cannot hold a hundred names, so it says where they are rather
  // than trailing off into "+109 more" with no way to see them.
  if (names.length > 6)
    tip.append(el('span', 'goods hint', `click for all ${names.length}`));
}

/** The hover tooltip: name, kind and history at the cursor, instantly. */
function showMapTip(location) {
  const tip = $('#map-tip');
  if (!tip) return;
  tipKey = `site:${location.rawId}`;

  tip.textContent = '';
  tip.append(el('strong', null, location.name));
  tip.append(el('span', 'muted', location.kind.replace(/([a-z])([A-Z])/g, '$1 $2')));
  tip.append(el('span', null, location.visits > 0
    ? `${location.visits} visit${location.visits === 1 ? '' : 's'}`
    : 'never visited'));

  // In shaded commodity mode, the number behind this node's colour.
  const shade = nodeShade.get(location.rawId);
  if (shade && shadeScale) {
    tip.append(el('span', 'price',
      `${shadeScale.invert ? 'buy at' : shadeScale.unit === 'SCU' ? 'capacity' : 'sells at'} ` +
      `${Math.round(shade.value).toLocaleString()} ${shadeScale.unit}`));
  }

  if (highlightIds?.has(location.rawId) && mapPriceFreshness)
    tip.append(el('span', `price-age ${mapPriceFreshness.state}`, mapPriceFreshness.label));

  if ($('#map-goods').checked) appendTipGoods(tip, commoditiesSoldAt(location));

  const services = servicesAt(location);
  if (services.length)
    tip.append(el('span', 'service-tip', services
      .map((service) => `${SERVICE_META[service]?.icon || '•'} ${SERVICE_META[service]?.label || service}`)
      .join(' · ')));

  tip.hidden = false;
}

/**
 * The body-level tooltip, for hovering the space a planet's cluster occupies
 * rather than one of its dots: the rollup a pilot actually wants at a glance.
 * Goods are the union across the body's sites, cached per draw - the answer
 * does not change until the map does.
 */
const bodyGoodsCache = new Map();

function showBodyTip(bodyName, system, sites) {
  const tip = $('#map-tip');
  if (!tip) return;
  tipKey = `body:${system}/${bodyName}`;

  const visited = sites.filter((s) => s.visits > 0);
  const visits = sites.reduce((sum, s) => sum + s.visits, 0);
  const last = sites.reduce((max, s) =>
    (s.lastVisit && (!max || s.lastVisit > max) ? s.lastVisit : max), null);

  tip.textContent = '';
  tip.append(el('strong', null, bodyName));
  tip.append(el('span', 'muted', system));
  tip.append(el('span', null, `${sites.length} place${sites.length === 1 ? '' : 's'} · ${visited.length} visited`));

  if (visits > 0)
    tip.append(el('span', null, `${visits} visit${visits === 1 ? '' : 's'} · last ${relative(last)}`));

  const plan = sites.filter((site) => planPlaceIds().has(site.rawId)).length;
  const shopping = sites.filter((site) => mapShoppingIds.has(site.rawId)).length;
  const stash = sites.filter((site) => mapStashIds.has(site.rawId)).length;
  const work = [
    plan && `${plan} plan stop${plan === 1 ? '' : 's'}`,
    shopping && `${shopping} shopping place${shopping === 1 ? '' : 's'}`,
    stash && `${stash} stash place${stash === 1 ? '' : 's'}`,
  ].filter(Boolean);
  if (work.length) tip.append(el('span', 'service-tip', work.join(' · ')));

  const serviceCounts = new Map();
  for (const site of sites)
    for (const service of servicesAt(site))
      serviceCounts.set(service, (serviceCounts.get(service) || 0) + 1);
  if (serviceCounts.size) {
    const summary = [...serviceCounts.entries()]
      .map(([service, count]) => `${SERVICE_META[service]?.icon || '•'} ${count} ${SERVICE_META[service]?.label || service}`)
      .join(' · ');
    tip.append(el('span', 'service-tip', summary));
  }

  if ($('#map-goods').checked) {
    if (!bodyGoodsCache.has(tipKey)) {
      const union = new Set();
      for (const site of sites)
        for (const name of commoditiesSoldAt(site)) union.add(name);
      bodyGoodsCache.set(tipKey, [...union].sort());
    }

    appendTipGoods(tip, bodyGoodsCache.get(tipKey));
  }

  tip.hidden = false;
}

function moveMapTip(e) {
  const tip = $('#map-tip');
  if (!tip || tip.hidden) return;

  const wrap = tip.parentElement.getBoundingClientRect();
  let x = e.clientX - wrap.left + 16;
  let y = e.clientY - wrap.top + 12;

  // Flip to the other side of the cursor rather than clipping at the frame.
  if (x + tip.offsetWidth > wrap.width - 8) x = e.clientX - wrap.left - tip.offsetWidth - 12;
  if (y + tip.offsetHeight > wrap.height - 8) y = e.clientY - wrap.top - tip.offsetHeight - 10;

  tip.style.left = `${x}px`;
  tip.style.top = `${y}px`;
}

function hideMapTip() {
  const tip = $('#map-tip');
  if (tip) tip.hidden = true;
  tipKey = null;
}

/**
 * Every commodity the catalogue says this place sells, via the same facility
 * tokens the map search uses - so the card and the search never disagree.
 * Token sets are cached per entry; the catalogue does not change under us.
 */
function commoditiesSoldAt(location) {
  const compact = `${location.name} ${location.rawId}`.toLowerCase().replace(/[^a-z0-9]/g, '');

  return marketEntries
    .filter((e) => {
      if (!e.sold.length) return false;
      e.soldTokens ??= facilityTokens(e.sold);
      return [...e.soldTokens].some((token) => compact.includes(token));
    })
    .map((e) => e.name)
    .sort();
}

/** Personal POIs are local notes, never an assertion about the map's telemetry. */
async function loadMapNotes() {
  mapNotes = await getJson('/api/map-notes');
  mapNoteIds.clear();
  for (const note of mapNotes) if (note.placeId) mapNoteIds.add(note.placeId);
  if (mapInfoLocation) renderMapInfoNotes(mapInfoLocation);
  if (atlas.length) drawMap();
}

async function saveMapNote(body) {
  const response = await fetch('/api/map-notes', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (!response.ok) throw new Error('Could not save note');
  await loadMapNotes();
}

async function removeMapNote(id) {
  await fetch(`/api/map-notes/${id}`, { method: 'DELETE' });
  await loadMapNotes();
}

function renderMapInfoNotes(location) {
  const host = $('#map-info-notes');
  if (!host) return;
  host.textContent = '';

  const notes = mapNotes.filter((note) => note.placeId === location.rawId);
  host.append(el('div', 'map-note-heading', notes.length ? `Your notes · ${notes.length}` : 'Personal map note'));

  for (const note of notes) {
    const card = el('div', 'map-note');
    const top = el('div', 'map-note-top');
    top.append(el('b', null, note.title));
    const remove = el('button', 'ghost tiny', '×');
    remove.title = 'Remove this map note';
    remove.addEventListener('click', () => removeMapNote(note.id));
    top.append(remove);
    card.append(top);
    if (note.note) card.append(el('div', 'map-note-text', note.note));
    if (note.tags?.length) card.append(el('div', 'map-note-tags', note.tags.join(' · ')));
    card.append(el('div', 'map-note-age', `written ${relative(note.updatedAt)}`));
    host.append(card);
  }

  const form = el('div', 'map-note-form');
  const title = document.createElement('input');
  title.type = 'text';
  title.className = 'search';
  title.placeholder = 'Title, e.g. cargo entrance';
  const detail = document.createElement('input');
  detail.type = 'text';
  detail.className = 'search';
  detail.placeholder = 'Optional note';
  const tags = document.createElement('input');
  tags.type = 'text';
  tags.className = 'search';
  tags.placeholder = 'Tags, comma separated';
  const save = el('button', 'ghost tiny', 'Save note');
  save.addEventListener('click', async () => {
    save.disabled = true;
    try {
      await saveMapNote({
        placeId: location.rawId,
        place: location.name,
        title: title.value,
        note: detail.value || null,
        tags: tags.value.split(',').map((tag) => tag.trim()).filter(Boolean),
      });
    } finally {
      save.disabled = false;
    }
  });
  form.append(title, detail, tags, save);
  host.append(form);
}

/** The place the detail card currently shows, for re-rendering on toggle. */
let mapInfoLocation = null;

/** Fills the card's sold-here list, honouring the toolbar's Goods checkbox. */
function renderMapInfoSold() {
  const list = $('#map-info-sold');
  const wanted = $('#map-goods').checked;

  if (!wanted || !mapInfoLocation) {
    list.hidden = true;
    return;
  }

  list.textContent = '';

  if (!marketEntries.length) {
    list.append(el('span', 'muted', 'Needs the community dataset (Settings).'));
  } else {
    const names = commoditiesSoldAt(mapInfoLocation);

    if (!names.length) {
      list.append(el('span', 'muted', 'Nothing known to sell here.'));
    } else {
      // The count matters when there are a hundred: the tooltip promised them
      // all, and this is where they are.
      list.append(el('div', 'sold-count muted', `${names.length} sold here · click one to light its sellers`));

      for (const name of names) {
        const chip = el('button', 'sold-chip', name);
        chip.type = 'button';
        chip.title = 'Light every place that sells this';
        chip.addEventListener('click', () => {
          $('#map-search').value = name;
          drawMap();
        });
        list.append(chip);
      }
    }
  }

  list.hidden = false;
}

/**
 * The card that opens when a node is clicked - the shared drawer, plus the
 * parts only a place on this map has.
 *
 * The name, where it is, its kind and how often you have been are the drawer's
 * own facts now, so they are not written twice. Notes, lore, amenities, the
 * sold list and the commodity-search verdict stay here: they are answers about
 * a dot on this map rather than about the place in general.
 */
async function showMapInfo(location) {
  // Claimed after openEntity, which forgets whatever was open before it.
  if (!await openEntity('place', location.rawId)) return;

  mapInfoLocation = location;

  renderMapInfoServices(location);
  renderMapInfoNotes(location);

  // In commodity mode, say which side of the search this place is on.
  const trade = $('#map-info-trade');
  if (highlightIds) {
    const sells = highlightIds.has(location.rawId);
    trade.textContent = sells ? 'sells the searched commodity' : 'does not sell it';
    trade.className = sells ? 'inward' : 'muted';
    trade.hidden = false;
  } else {
    trade.hidden = true;
  }

  renderMapInfoSold();

  // The starmap's own paragraph about this place, fetched on first open and
  // cached; the card must not wait for it.
  renderMapInfoPlace(location);
}

/**
 * What the star map itself says about a place: its paragraph, what it orbits,
 * and the services it lists.
 *
 * Fetched on first open and cached, because the card must not wait for it. The
 * amenities are deliberately separate from the service chips above: those come
 * from UEX and say where you can actually trade today, while these are what the
 * game says the place has, and the two disagree usefully often.
 */
function renderMapInfoPlace(location) {
  const loreNode = $('#map-info-lore');
  const amenityNode = $('#map-info-amenities');
  loreNode.hidden = true;
  amenityNode.hidden = true;

  if (!loreCache.has(location.name)) {
    loreCache.set(location.name,
      getJson(`/api/map/lore?name=${encodeURIComponent(location.name)}`)
        .catch(() => null));
  }

  return loreCache.get(location.name).then((found) => {
    if (!found || mapInfoLocation !== location) return;

    if (found.lore) {
      loreNode.textContent = found.lore;
      loreNode.hidden = false;
    }

    if (found.amenities?.length) {
      amenityNode.textContent = '';
      amenityNode.append(
        el('span', 'muted', found.parent ? `In ${found.parent} · has ` : 'Has '));

      for (const amenity of found.amenities) amenityNode.append(el('span', 'amenity', amenity));

      amenityNode.hidden = false;
    }
  });
}

/** Service facts on a place card use the same map-id join as the filter. */
function renderMapInfoServices(location) {
  const host = $('#map-info-services');
  const services = servicesAt(location);
  host.textContent = '';

  for (const service of services) {
    const meta = SERVICE_META[service];
    if (!meta) continue;
    const chip = el('button', 'map-service-chip');
    chip.type = 'button';
    chip.title = `Filter the map to ${meta.label.toLowerCase()}`;
    chip.append(el('span', 'service-icon', meta.icon));
    chip.append(el('span', 'service-text', meta.label));
    chip.addEventListener('click', () => selectMapService(service));
    host.append(chip);
  }

  host.hidden = host.children.length === 0;
}

/** Lore paragraphs already asked for, name to promise of text-or-null. */
const loreCache = new Map();

/**
 * Systems have no shared coordinate frame in the installed game data. Showing
 * only the jump graph makes that limitation legible instead of turning an
 * arbitrary triangle into a false atlas of planetary distances.
 */
function drawJumpNetwork(map, locations) {
  const systems = Object.keys(SYSTEM_COLOURS)
    .filter((system) => locations.some((location) => location.system === system));
  const home = { x: 0, y: 0, w: 1200, h: 760 };
  const wasHome = view.w === HOME_VIEW.w && view.h === HOME_VIEW.h
    && view.x === HOME_VIEW.x && view.y === HOME_VIEW.y;

  HOME_VIEW = home;
  if (wasHome) view = { ...home };
  SYSTEM_LAYOUT = {};

  const anchors = {
    Stanton: { x: 255, y: 240 },
    Pyro: { x: 945, y: 240 },
    Nyx: { x: 600, y: 560 },
  };

  for (const system of systems) {
    const point = anchors[system] || { x: 600, y: 380 };
    SYSTEM_LAYOUT[system] = { ...point, radius: 46, colour: SYSTEM_COLOURS[system] };
  }

  for (const [fromName, toName] of JUMP_LANES) {
    const from = SYSTEM_LAYOUT[fromName];
    const to = SYSTEM_LAYOUT[toName];
    if (!from || !to) continue;

    map.append(svgEl('line', {
      x1: from.x, y1: from.y, x2: to.x, y2: to.y,
      class: 'map-edge', 'stroke-width': '2.2', 'stroke-dasharray': '7 8', filter: 'url(#glow)',
    }));
  }

  for (const [system, point] of Object.entries(SYSTEM_LAYOUT)) {
    const group = svgEl('g', { class: 'map-network-system', tabindex: '0' });
    group.append(svgEl('circle', {
      cx: point.x, cy: point.y, r: point.radius, fill: point.colour,
      'fill-opacity': '.13', stroke: point.colour, 'stroke-width': '2', filter: 'url(#glow)',
    }));
    group.append(svgEl('circle', { cx: point.x, cy: point.y, r: 9, fill: point.colour, filter: 'url(#glow)' }));
    const label = svgEl('text', {
      x: point.x, y: point.y + 72, 'text-anchor': 'middle', class: 'map-sys-label',
      style: `font-size:${labelSize(1.6)}px`,
    });
    label.textContent = system;
    group.append(label);
    group.addEventListener('click', () => {
      $('#map-mode').value = 'system';
      $('#map-system').value = system;
      syncMapModeControls();
      drawMap();
    });
    map.append(group);
  }

  const title = svgEl('text', {
    x: home.w / 2, y: 92, 'text-anchor': 'middle', class: 'map-label',
    style: `font-size:${labelSize(1.35)}px;fill:#7796b0;letter-spacing:.18em`,
  });
  title.textContent = 'JUMP NETWORK · SCHEMATIC · NOT TO SCALE';
  map.append(title);

  $('#map-count').textContent = `${systems.length} systems · jump network`;
  drawNetworkHere(map);
  updateHereControl();
  drawLegend([]);
  applyView();
}

function drawMap() {
  const map = $('#starmap');
  map.textContent = '';
  nodeAt.clear();
  hideMapTip();
  pendingLabels.length = 0;
  claimedBoxes.length = 0;
  bodyGoodsCache.clear();

  const visitedOnly = $('#map-visited-only')?.checked;
  const term = ($('#map-search')?.value || '').trim().toLowerCase();
  const focusIds = mapFocusIds();
  const serviceIds = mapServiceFilter
    ? new Set(atlas.filter((location) => servicesAt(location).includes(mapServiceFilter))
      .map((location) => location.rawId))
    : null;

  // Any search HIGHLIGHTS rather than filters. Filtering removed the context:
  // the remaining nodes re-clustered into what looked like the whole map with
  // nothing marked, and there was no way to see WHERE the matches sat among
  // everything else. Keeping every node, dimming the rest and framing the lit
  // ones reads as an answer. A term that names a commodity lights where it
  // sells; any other term lights the places whose names match. Either search
  // wins over the visited-only toggle.
  const sites = term ? commoditySites(term) : null;

  highlightIds = null;

  // A chosen facility lights the places that have it, the same way a search
  // does, rather than filtering the rest away: seeing which twenty-four of the
  // map refine is the point, and a filtered map cannot show where they sit.
  if (mapAmenityFilter) {
    highlightIds = new Set(atlas
      .filter((l) => hasAmenity(l, mapAmenityFilter))
      .map((l) => l.rawId));
  } else if (sites) {
    highlightIds = new Set(atlas
      .filter((l) => {
        const compact = `${l.name} ${l.rawId}`.toLowerCase().replace(/[^a-z0-9]/g, '');
        return [...sites].some((token) => compact.includes(token));
      })
      .map((l) => l.rawId));
  } else if (term) {
    highlightIds = new Set(atlas
      .filter((l) => l.name.toLowerCase().includes(term) || l.rawId.toLowerCase().includes(term))
      .map((l) => l.rawId));
  }

  // An empty highlight set would dim the whole map to say "nothing"; saying it
  // in the counter and leaving the map lit is kinder.
  if (highlightIds && highlightIds.size === 0) highlightIds = null;

  prepareShading(term, sites);
  syncCargoPanel(term, sites);

  const allLocations = atlas.filter((l) =>
    // Service and visit filters answer a different question from position. The
    // player never vanishes merely because their current place lacks the
    // selected service or has not been recorded as a visit yet.
    l.rawId === hereId ||
    (!focusIds || focusIds.has(l.rawId)) &&
    (!serviceIds || serviceIds.has(l.rawId)) &&
    (term || !visitedOnly || l.visits > 0));
  const selectedSystem = mapSystem();
  const locations = mapMode() === 'system' && selectedSystem
    ? allLocations.filter((location) => location.system === selectedSystem)
    : allLocations;

  const count = $('#map-count');
  if (count) {
    const seen = atlas.filter((l) => l.visits > 0).length;
    if (mapServiceFilter && serviceIds?.size === 0)
      count.textContent = `no ${SERVICE_META[mapServiceFilter]?.label.toLowerCase() || 'service'} locations known`;
    else if (term && !highlightIds) count.textContent = 'no match';
    else if (sites) {
      // Name what was matched: the term may have been a fragment, and the
      // user should see which commodity the map decided they meant.
      const matched = matchCommodity(term.startsWith('buy:') ? term.slice(4) : term);
      const what = matched ? matched.name : term;

      count.textContent = term.startsWith('buy:')
        ? `${what} — stocked at ${highlightIds.size} places the map can name`
        : `${what} — sells at ${highlightIds.size} places the map can name`;
    }
    else if (term) count.textContent = `${highlightIds.size} place${highlightIds.size === 1 ? '' : 's'} lit`;
    else if (mapFocusFilter && focusIds?.size === 0)
      count.textContent = `no ${mapFocusFilter} locations can be placed yet`;
    else if (mapFocusFilter)
      count.textContent = `${locations.length} ${mapFocusFilter} location${locations.length === 1 ? '' : 's'} shown`;
    else if (mapServiceFilter)
      count.textContent = `${locations.length} ${SERVICE_META[mapServiceFilter]?.label.toLowerCase() || 'service'} location${locations.length === 1 ? '' : 's'} shown`;
    else if (mapMode() === 'system')
      count.textContent = `${locations.length} shown in ${selectedSystem} · ${seen} of ${atlas.length} visited`;
    else count.textContent = `${locations.length} shown · ${seen} of ${atlas.length} visited`;
  }

  // Soft glow, applied to stars and jump lanes for the HUD look.
  const defs = svgEl('defs');
  const glow = svgEl('filter', { id: 'glow', x: '-60%', y: '-60%', width: '220%', height: '220%' });
  glow.append(svgEl('feGaussianBlur', { stdDeviation: '3.4', result: 'blur' }));
  const merge = svgEl('feMerge');
  merge.append(svgEl('feMergeNode', { in: 'blur' }));
  merge.append(svgEl('feMergeNode', { in: 'SourceGraphic' }));
  glow.append(merge);
  defs.append(glow);
  map.append(defs);

  if (mapMode() === 'network') {
    drawJumpNetwork(map, allLocations);
    return;
  }

  // A sparse starfield behind everything. Deterministic - a hash of the index,
  // not Math.random - so redraws do not make the sky shimmer.
  for (let i = 0; i < 140; i++) {
    const h1 = Math.abs(Math.sin(i * 127.1 + 311.7) * 43758.5453) % 1;
    const h2 = Math.abs(Math.sin(i * 269.5 + 183.3) * 28001.8384) % 1;
    const h3 = Math.abs(Math.sin(i * 419.2 + 371.9) * 12345.6789) % 1;

    map.append(svgEl('circle', {
      cx: (h1 * 1340).toFixed(1),
      cy: (h2 * 1240).toFixed(1),
      r: (0.5 + h3 * 0.9).toFixed(2),
      class: 'map-star',
      style: `opacity:${(0.10 + h3 * 0.3).toFixed(2)}`,
    }));
  }

  const grouped = { other: [] };

  for (const location of locations) {
    if (location.system && SYSTEM_COLOURS[location.system]) {
      grouped[location.system] ??= new Map();

      const key = location.body || '—';
      if (!grouped[location.system].has(key)) grouped[location.system].set(key, []);
      grouped[location.system].get(key).push(location);
    } else {
      grouped.other.push(location);
    }
  }

  // The layout depends on what is on screen, so it is worked out per draw -
  // filtering to visited places shrinks every system.
  const sized = layoutSystems(grouped);
  SYSTEM_LAYOUT = sized.layout;

  const home = { x: 0, y: 0, w: sized.width, h: sized.height };
  const wasHome = view.w === HOME_VIEW.w && view.h === HOME_VIEW.h
    && view.x === HOME_VIEW.x && view.y === HOME_VIEW.y;

  HOME_VIEW = home;
  if (wasHome) view = { ...home };

  const maxVisits = Math.max(1, ...locations.map((l) => l.visits));
  // Visits still nudge the size, but gently. At four times the range a busy
  // outpost dwarfed a station and the map read as a jumble of sizes rather
  // than a set of places; the count lives in the tip and on the Places page,
  // where a number can be a number.
  const radiusFor = (visits) => 7 + Math.sqrt(visits / maxVisits) * 4;


  // Stars, orbit rings and system labels.
  for (const [system, centre] of Object.entries(SYSTEM_LAYOUT)) {
    map.append(svgEl('circle', {
      cx: centre.x, cy: centre.y, r: 9, fill: centre.colour, filter: 'url(#glow)',
    }));
    map.append(svgEl('circle', { cx: centre.x, cy: centre.y, r: centre.orbit, class: 'map-orbit' }));

    // Reticle ticks around each star, echoing the in-game starmap.
    for (let tick = 0; tick < 4; tick++) {
      const angle = (tick / 4) * Math.PI * 2 + Math.PI / 4;
      map.append(svgEl('line', {
        x1: centre.x + Math.cos(angle) * 22, y1: centre.y + Math.sin(angle) * 22,
        x2: centre.x + Math.cos(angle) * 31, y2: centre.y + Math.sin(angle) * 31,
        stroke: '#1e4763', 'stroke-width': '1',
      }));
    }

    const label = svgEl('text', {
      x: centre.x, y: centre.y + centre.radius - 6, 'text-anchor': 'middle',
      class: 'map-sys-label', style: `font-size:${labelSize(1.5)}px`,
    });
    label.textContent = system;
    map.append(label);
  }

  // Jump lanes, drawn star to star and stopping short of each orbit ring.
  for (const [fromName, toName] of JUMP_LANES) {
    const from = SYSTEM_LAYOUT[fromName];
    const to = SYSTEM_LAYOUT[toName];
    if (!from || !to) continue;

    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const length = Math.hypot(dx, dy) || 1;
    const ux = dx / length;
    const uy = dy / length;

    const ax = from.x + ux * (from.radius + 10);
    const ay = from.y + uy * (from.radius + 10);
    const bx = to.x - ux * (to.radius + 10);
    const by = to.y - uy * (to.radius + 10);

    // Bowed away from the midpoint so the three lanes stay distinguishable.
    const mx = (ax + bx) / 2 - uy * 26;
    const my = (ay + by) / 2 + ux * 26;

    map.append(svgEl('path', {
      d: `M ${ax} ${ay} Q ${mx} ${my} ${bx} ${by}`,
      class: 'map-edge', 'stroke-width': '1.5', 'stroke-dasharray': '5 7', filter: 'url(#glow)',
    }));

    map.append(svgEl('rect', {
      x: mx - 6, y: my - 6, width: 12, height: 12,
      fill: 'none', stroke: '#35c8f0', 'stroke-width': '1.2',
      transform: `rotate(45 ${mx} ${my})`, filter: 'url(#glow)',
    }));

    const jumpLabel = svgEl('text', {
      x: mx, y: my - 14, 'text-anchor': 'middle', class: 'map-label',
      style: `font-size:${labelSize()}px`,
    });
    jumpLabel.textContent = 'JUMP POINT';
    map.append(jumpLabel);
  }

  // Every body's hover disc goes in one layer, added before any node is
  // drawn. Appending them as each body was built put a later body's disc on
  // top of an earlier body's dots - and in SVG the thing on top takes the
  // pointer, so clicking those dots did nothing at all. Widening the clusters
  // made the discs bigger and the dead zones with them.
  const hoverLayer = svgEl('g');

  // The bodies go in a layer of their own, under everything, for the same
  // reason: drawn as each cluster was built, a later planet's disc painted over
  // an earlier one's marks. It cannot steal a click - the disc is
  // pointer-events: none - but it could still hide the places on a neighbour.
  const bodyLayer = svgEl('g');
  map.append(bodyLayer);
  map.append(hoverLayer);

  // Bodies and their locations.
  for (const [system, bodies] of Object.entries(grouped)) {
    if (system === 'other') continue;

    const centre = SYSTEM_LAYOUT[system];
    const order = SYSTEMS[system] || [];
    const present = [...bodies.keys()].sort((a, b) => {
      const ia = order.indexOf(a);
      const ib = order.indexOf(b);
      return (ia === -1 ? 99 : ia) - (ib === -1 ? 99 : ib);
    });

    const layout = bodyLayout(system, present, centre,
      (name) => clusterRadius(bodies.get(name).length));

    // Faint orbit rings through each planet, drawn under the nodes. They give
    // the disc its structure - the eye reads rings as orbits and the layout
    // stops looking like scattered dots.
    const ringRadii = new Set();

    for (const placement of layout.values()) {
      if (placement.from.x !== centre.x || placement.from.y !== centre.y) continue;
      const r = Math.round(Math.hypot(placement.x - centre.x, placement.y - centre.y));
      if (r > 12) ringRadii.add(r);
    }

    for (const r of ringRadii)
      map.append(svgEl('circle', { cx: centre.x, cy: centre.y, r, class: 'map-orbit' }));

    present.forEach((bodyName) => {
      const place = layout.get(bodyName);
      const angle = place.angle;
      const bx = place.x;
      const by = place.y;

      map.append(svgEl('line', {
        x1: place.from.x, y1: place.from.y, x2: bx, y2: by,
        stroke: 'rgba(53,200,240,.13)', 'stroke-width': '1',
      }));

      const sites = bodies.get(bodyName);
      const reach = clusterRadius(sites.length);

      // Before the sites, so their marks sit on the world rather than behind it.
      if (bodyName !== '—') drawBodyDisc(bodyLayer, bx, by, reach, system, `${system}/${bodyName}`);

      // Body names sit outside the cluster they head, so the sites below have
      // clear air to put their own labels in. They are placed first and claim
      // their box, so site labels flow around them.
      const bodyLabelX = bx + Math.cos(angle) * (reach + 16);
      const bodyLabelY = by + Math.sin(angle) * (reach + 16);
      const bodyLabelSize = labelSize(1.15);

      const bodyLabel = svgEl('text', {
        x: bodyLabelX, y: bodyLabelY,
        'text-anchor': 'middle', class: 'map-label',
        style: `fill:${!place.positioned && mapMode() === 'system' ? '#ffab3d' : '#7796b0'};font-size:${bodyLabelSize}px;letter-spacing:.14em;text-transform:uppercase`,
      });
      bodyLabel.textContent = bodyName === '—' ? ''
        : `${bodyName}${!place.positioned && mapMode() === 'system' ? ' · position unavailable' : ''}`;
      map.append(bodyLabel);

      if (bodyLabel.textContent) {
        claimedBoxes.push(labelBox(
          bodyLabelX, bodyLabelY - bodyLabelSize * 0.4, 'middle', bodyLabelSize * 1.25, bodyLabel.textContent));
      }

      // An invisible disc under the cluster: hovering the space a planet
      // occupies - rather than one of its dots, which sit on top and win the
      // pointer - shows the body's rollup tip.
      if (bodyName !== '—') {
        const bodyKey = `body:${system}/${bodyName}`;
        const bodyHover = svgEl('circle', {
          cx: bx, cy: by, r: reach + 12,
          fill: '#000', 'fill-opacity': '0', 'pointer-events': 'fill',
        });

        const bubble = () => map.querySelector(`.map-body[data-body="${system}/${bodyName}"]`);

        bodyHover.addEventListener('pointermove', (e) => {
          if (tipKey !== bodyKey) {
            showBodyTip(bodyName, system, sites);

            // Lit only while the pointer is in it: at rest the bubble is a
            // ground the eye can ignore, and under the pointer it is the
            // answer to "which of these belong together".
            bubble()?.classList.add('lit');
          }

          moveMapTip(e);
        });

        bodyHover.addEventListener('pointerleave', () => {
          bubble()?.classList.remove('lit');
          hideMapTip();
        });

        // Clicking the space between a body's places frames that body. The
        // dots themselves keep their own click - this is only the gaps, which
        // did nothing at all before.
        bodyHover.addEventListener('click', (e) => {
          e.stopPropagation();
          animateViewTo({
            x: bx - (reach + 26),
            y: by - (reach + 26),
            w: (reach + 26) * 2,
            h: (reach + 26) * 2,
          });
        });

        hoverLayer.append(bodyHover);
      }

      // Sites are spread by golden angle rather than in rings. Rings of a fixed
      // size put every twelfth node on the same spoke, which reads as spokes
      // rather than a cluster and stacks the labels on top of each other;
      // phyllotaxis fills the disc evenly at any count, and microTech alone has
      // over a hundred.
      // Every position first, then each node is told how much room it has.
      // A cluster is drawn tighter than the pad that makes a lone dot easy to
      // click, so without this the last site drawn owns every point it covers
      // and its neighbours cannot be clicked at all.
      const spots = sites.map((site, siteIndex) => {
        const spin = siteIndex * 2.39996;
        const distance = clusterRadius(siteIndex + 1);

        return { x: bx + Math.cos(spin) * distance, y: by + Math.sin(spin) * distance };
      });

      sites.forEach((site, siteIndex) => {
        const spot = spots[siteIndex];

        let nearest = Infinity;
        spots.forEach((other, j) => {
          if (j !== siteIndex) nearest = Math.min(nearest, Math.hypot(other.x - spot.x, other.y - spot.y));
        });

        drawNode(map, spot.x, spot.y, site, radiusFor(site.visits), { x: bx, y: by }, nearest / 2);
      });
    });
  }

  // Anything the resolver could not place: shown below the systems, never
  // dropped, since an unmapped place the player has been is still worth seeing.
  const perRow = Math.max(6, Math.floor(sized.width / 150));

  grouped.other.forEach((location, index) => {
    const x = 70 + (index % perRow) * 150;
    const y = sized.height + 40 + Math.floor(index / perRow) * 34;
    drawNode(map, x, y, location, radiusFor(location.visits));
  });

  if (grouped.other.length) {
    HOME_VIEW.h = sized.height + 80 + Math.ceil(grouped.other.length / perRow) * 34;
    if (wasHome) view.h = HOME_VIEW.h;
  }

  placeLabels(map);
  drawLegend(locations);
  applyView();
  drawHere();
  drawTravel();
  drawTripPath();
  fitToHighlights(term || null);
}

/* ---------- what a place looks like ---------- */

/**
 * A mark per kind, drawn in a box from -1 to 1 so size stays the caller's
 * business.
 *
 * Colour alone was carrying the whole taxonomy: nine kinds, nine dots, and a
 * legend to memorise. A shape can be read without the legend - a headframe is a
 * mine whether or not you remember that mines are brown - and the colour stays
 * exactly as it was, so anyone who had learnt it loses nothing.
 *
 * Deliberately blunt geometry. These are drawn between four and seventeen
 * pixels across, where a detailed glyph turns to mush; a silhouette that
 * survives being tiny beats one that looks good in a design tool.
 */
const KIND_SHAPES = {
  // A skyline. Two steps rather than three: at eight pixels a third is a smudge.
  City: [{ tag: 'path', attrs: { d: 'M-1 .9 L-1 -.15 L-.05 -.15 L-.05 -1 L1 -1 L1 .9 Z' } }],

  // A ring - the one shape that reads as "you dock inside it".
  Station: [{ tag: 'path', attrs: { d: 'M0 -1 A 1 1 0 1 1 0 1 A 1 1 0 1 1 0 -1 Z M0 -.42 A .42 .42 0 1 0 0 .42 A .42 .42 0 1 0 0 -.42 Z' }, evenodd: 1 }],

  // A horizontal berth: it stays distinct from an asteroid's uneven rock
  // silhouette even when a map icon is only a handful of pixels across.
  RestStop: [{ tag: 'rect', attrs: { x: -1, y: -.62, width: 2, height: 1.24, rx: .34 } }],

  // A dome on the ground.
  Outpost: [{ tag: 'path', attrs: { d: 'M-1 .55 A 1 1 0 0 1 1 .55 L1 .8 L-1 .8 Z' } }],

  // A spoil heap. Nothing on top of it - the headframe it used to carry turned
  // to mush at map size, which is the size it is always drawn at.
  Mine: [{ tag: 'polygon', attrs: { points: '0,-1 1,.85 -1,.85' } }],

  // An uneven rock: the lopsided outline is intentional, otherwise it reads
  // too much like a rest-stop berth at a glance.
  Asteroid: [{ tag: 'polygon', attrs: { points: '-.72,-.92 .5,-.72 1,.02 .42,.9 -.74,.62 -1,-.18' } }],

  // A cross: legible at any size, and nothing else on the map is one.
  Research: [{ tag: 'path', attrs: { d: 'M-.32 -1 L.32 -1 L.32 -.32 L1 -.32 L1 .32 L.32 .32 L.32 1 L-.32 1 L-.32 .32 L-1 .32 L-1 -.32 L-.32 -.32 Z' } }],

  // Cargo moving: an arrow, not a crate with a band nobody could see.
  DistributionCentre: [{ tag: 'polygon', attrs: { points: '-1,-.85 .95,0 -1,.85 -1,.3 -.15,0 -1,-.3' } }],

  // The same diamond the jump lanes wear.
  JumpPoint: [{ tag: 'polygon', attrs: { points: '0,-1 1,0 0,1 -1,0' } }],

  MissionBeacon: [{ tag: 'polygon', attrs: { points: '0,1 -1,-.85 0,-.3 1,-.85' } }],
};

/** Anything without a mark of its own keeps the dot it always had. */
const PLAIN_MARK = [{ tag: 'circle', attrs: { cx: 0, cy: 0, r: 1 } }];

/**
 * Draws a place's mark at a size.
 *
 * @param solid Somewhere with history is filled; somewhere never visited is an
 *   outline, exactly as when every kind was a circle.
 */
/**
 * Equal radius is not equal weight: a triangle inside a circle covers under
 * half of it, so the same number drew a mine that looked half the size of a
 * rest stop beside it. Each shape is nudged until they read as one set.
 */
const SHAPE_WEIGHT = {
  City: 0.92,
  Station: 1,
  RestStop: 0.95,
  Outpost: 1.05,
  Mine: 1.18,
  Asteroid: 1,
  Research: 1.06,
  DistributionCentre: 1.12,
  JumpPoint: 1.15,
  MissionBeacon: 1.15,
};

function kindMark(kind, x, y, radius, colour, solid) {
  const size = radius * (SHAPE_WEIGHT[kind] ?? 1);

  const group = svgEl('g', {
    class: 'map-mark',
    transform: `translate(${x} ${y}) scale(${size})`,
  });

  for (const part of KIND_SHAPES[kind] ?? PLAIN_MARK) {
    group.append(svgEl(part.tag, {
      ...part.attrs,

      // Line parts are strokes whatever the history: a filled orbit or shaft is
      // a blob. Everything else fills once the place has been visited.
      fill: solid ? colour : 'none',
      stroke: colour,

      // Heavy enough to survive being drawn six pixels across, which is the
      // size these are actually used at; an outline at .14 disappeared.
      'stroke-width': 0.22,
      'stroke-linejoin': 'round',
      'fill-rule': part.evenodd ? 'evenodd' : 'nonzero',
      opacity: solid ? 0.92 : 0.6,
    }));
  }

  return group;
}

/**
 * The body a cluster belongs to, drawn as the disc its places sit on.
 *
 * Planets and moons are not in the atlas at all - the game names locations, not
 * the rocks they are on - so a body was a label and nothing else, and a station
 * ended up looking larger than the planet holding it. Drawing the disc puts the
 * hierarchy back: the big quiet circle is the world, the marks on it are the
 * places you can actually go.
 */
/**
 * The bubble a body's places sit in.
 *
 * The layout is already polar - each site is placed by golden angle around its
 * body - but a ring of dots does not say "these belong to Hurston" on its own.
 * The disc does, and it is deliberately faint: it is a ground, not a thing to
 * look at. Hovering brings it up, which is when the grouping is the question
 * being asked.
 *
 * @param key Identifies the bubble so the hover area over the same body can
 *   light it without either having to know where the other one is drawn.
 */
function drawBodyDisc(layer, x, y, reach, system, key) {
  const disc = svgEl('circle', {
    cx: x, cy: y, r: reach + 7,
    class: 'map-body',
    fill: SYSTEM_COLOURS[system] || '#9fb8ff',
  });

  if (key) disc.dataset.body = key;

  layer.append(disc);
}

/**
 * @param anchor The body this site belongs to, if any. Labels are pushed away
 *   from it so a cluster fans its names outwards instead of stacking them.
 */
/**
 * How far a mark's invisible click target reaches.
 *
 * A small mark needs a pad around it to be clickable at all, but the pad must
 * stop inside the neighbour's half of the gap: SVG gives a shared point to
 * whatever was drawn last, so an overlapping pad does not make a click
 * ambiguous - it makes the covered node unclickable. In a cluster that was
 * most of them, which is why clicking a station, opening its trade panel and
 * adding it to a plan all failed on the same places. Never below the mark
 * itself, which is always its own target.
 */
const hitPad = (radius, room) => Math.max(radius + 1, Math.min(radius + 8, room));

/**
 * @param room Half the distance to the nearest neighbour, when there is one.
 *   The click pad stops there rather than reaching across it.
 */
function drawNode(map, x, y, location, radius, anchor = null, room = Infinity) {

  const colour = KIND_COLOURS[location.kind] || KIND_COLOURS.Unknown;
  const been = location.visits > 0;

  let cls = been ? 'map-node' : 'map-node unvisited';

  // In commodity mode the sellers glow and everything else recedes.
  const highlighted = highlightIds?.has(location.rawId) ?? false;
  if (highlightIds) cls += highlighted ? ' hl' : ' dim';

  const group = svgEl('g', { class: cls });

  nodeAt.set(location.rawId, { x, y });

  // The dot itself claims its square so no neighbour's label sits on it.
  claimedBoxes.push({ x0: x - radius - 1, y0: y - radius - 1, x1: x + radius + 1, y1: y + radius + 1 });

  group.append(svgEl('circle', {
    cx: x, cy: y, r: hitPad(radius, room), fill: colour, opacity: '0', class: 'hit',
  }));


  // In shaded commodity mode the ring and dot carry the price grade; a lit
  // place UEX has no price for keeps the plain green ring.
  const shade = highlighted ? nodeShade.get(location.rawId) : null;

  if (highlighted) {
    group.append(svgEl('circle', {
      cx: x, cy: y, r: radius + 5, fill: 'none',
      stroke: shade?.colour ?? '#4fd48a', 'stroke-width': '1.6', class: 'hl-ring', filter: 'url(#glow)',
    }));

    // The report age belongs to the commodity source, not the place itself.
    // Keep it on a commodity result only, so a stale UEX quote cannot make a
    // reliable visit or service fact look stale as well.
    if (mapPriceFreshness && mapPriceFreshness.state !== 'fresh') {
      group.append(svgEl('circle', {
        cx: x, cy: y, r: radius + 8, class: `map-price-age ${mapPriceFreshness.state}`,
      }));
    }
  }

  // Somewhere never visited is drawn as an outline, so the places that carry
  // history read as solid against the rest of the map. A price shade
  // overrides the kind colour - in that mode the colour IS the price, and
  // that has to hold for the whole map: a place with no price for the chosen
  // commodity goes slate, including one the catalogue lit but nobody has
  // priced. Otherwise the kind colours sit in the same picture as the scale
  // and the eye has two colour languages to read at once.
  const dotColour = shade?.colour ?? (shadeScale ? NO_TRADE : colour);

  // A price shade means the colour IS the price, so the mark keeps its shape
  // and takes the graded colour: a mine is still a mine at 1,872 aUEC.
  group.append(kindMark(location.kind, x, y, radius, dotColour, been || !!shade));

  if (showServiceBadges(location, highlighted))
    drawServiceBadges(group, x, y, radius, servicesAt(location));

  if (mapNoteIds.has(location.rawId))
    drawMapNoteBadge(group, x, y, radius);

  // A styled tooltip that appears instantly - the native <title> takes a
  // second to show and cannot be read against the game-HUD styling.
  group.addEventListener('pointerenter', () => showMapTip(location));
  group.addEventListener('pointermove', moveMapTip);
  group.addEventListener('pointerleave', hideMapTip);

  // Click for the detail card; the hit circle above makes small nodes easy to
  // land on.
  group.addEventListener('click', (e) => {
    e.stopPropagation();
    showMapInfo(location);
  });

  // Double-click for the fuller story: what this station takes and offers. The
  // card has no room for a dozen commodities on each side of the counter.
  group.addEventListener('dblclick', (e) => {
    e.stopPropagation();
    e.preventDefault();
    showStation(location.rawId, location.name);
  });

  // Labelling everything is unreadable at this density, so only places with
  // history get one until the view is zoomed in far enough to have room.
  // Search matches are the exception - a lit dot the user cannot name is not
  // an answer - but only while there are few enough for the names to have
  // air; two hundred sellers of a common ore label themselves on zoom instead.
  const nameable = highlighted && (highlightIds.size <= 40 || isDetailed());

  if ((been && radius > 7) || isDetailed() || nameable) {
    // Not drawn here: every wanted label goes through placeLabels at the end
    // of the draw, which resolves collisions instead of stacking neighbours.
    pendingLabels.push({
      group,
      x,
      y,
      radius,
      anchor,
      text: location.name.length > 24 ? `${location.name.slice(0, 23)}…` : location.name,
      priority: (highlighted ? 1_000_000 : 0) + location.visits,
      pinned: highlighted,
    });
  }

  map.append(group);
}

/* ---------- label placement ---------- */

/**
 * Labels wanted by this draw, and rectangles already spoken for (body names,
 * placed labels, the nodes themselves). Both reset per draw.
 */
const pendingLabels = [];
const claimedBoxes = [];

/** Approximate bounding box of a text laid out at x,y with the given anchor. */
function labelBox(x, y, anchorMode, size, text) {
  const width = text.length * size * 0.62;
  const height = size * 1.3;
  const x0 = anchorMode === 'start' ? x : anchorMode === 'end' ? x - width : x - width / 2;
  return { x0, y0: y - height / 2, x1: x0 + width, y1: y + height / 2 };
}

function boxesCollide(a, b) {
  return a.x0 < b.x1 && a.x1 > b.x0 && a.y0 < b.y1 && a.y1 > b.y0;
}

/**
 * Greedy label placement with collision avoidance. Names used to be placed
 * blind - radially out from the planet - which stacked neighbours on top of
 * each other the moment two sites shared a bearing. Now every label tries a
 * handful of positions around its dot, most-visited first, and a label that
 * fits nowhere is dropped: an unreadable pile names nothing, while a bare dot
 * still answers on hover and click.
 */
/**
 * How many names the map will show at the current zoom.
 *
 * Collision avoidance alone is not decluttering: it stops names overlapping,
 * but at system scale microTech still asks for twenty-two of them and the ones
 * that fit form a wall of text around the disc. So the whole view gets a
 * budget, spent on the busiest places first, and it grows with the square of
 * the zoom - zooming in is asking for detail, and that is when there is room
 * to put it. Past the detail threshold every label that fits is drawn.
 */
const labelBudget = () => {
  if (mapLabelDensity() === 'all') return Infinity;
  if (mapLabelDensity() === 'quiet') return isDetailed() ? 28 : 8;
  if (isDetailed()) return Infinity;

  const zoom = HOME_VIEW.w / view.w;
  return Math.max(12, Math.round(14 * zoom * zoom));
};

function placeLabels(map) {
  const size = labelSize();
  const budget = labelBudget();
  let spent = 0;

  pendingLabels.sort((a, b) => b.priority - a.priority);

  for (const want of pendingLabels) {
    // A search match is the answer to a question, so it is never rationed;
    // everything else queues for the budget.
    if (!want.pinned && spent >= budget) continue;

    const { x, y, radius, anchor } = want;

    const dx = anchor ? x - anchor.x : 0;
    const dy = anchor ? y - anchor.y : 0;
    const length = Math.hypot(dx, dy);
    const gap = radius + size * 0.5 + 2;

    const candidates = [];

    // The radial spot first - it is the one that fans a cluster outwards.
    if (length > 0.5) {
      candidates.push({
        x: x + (dx / length) * gap,
        y: y + (dy / length) * gap,
        anchorMode: dx >= 0 ? 'start' : 'end',
      });
    }

    candidates.push(
      { x: x + radius + 3, y, anchorMode: 'start' },
      { x: x - radius - 3, y, anchorMode: 'end' },
      { x, y: y + radius + size * 0.85, anchorMode: 'middle' },
      { x, y: y - radius - size * 0.85, anchorMode: 'middle' },
    );

    for (const spot of candidates) {
      const box = labelBox(spot.x, spot.y, spot.anchorMode, size, want.text);
      if (claimedBoxes.some((other) => boxesCollide(box, other))) continue;

      const label = svgEl('text', {
        x: spot.x,
        y: spot.y,
        'text-anchor': spot.anchorMode,
        'dominant-baseline': 'middle',
        class: 'map-label',
        style: `font-size:${size}px`,
      });
      label.textContent = want.text;
      want.group.append(label);

      claimedBoxes.push(box);
      if (!want.pinned) spent++;
      break;
    }
  }
}

function drawLegend(locations) {
  const legend = $('#map-legend');
  legend.textContent = '';

  const appendPriceFreshness = () => {
    if (!mapPriceFreshness) return;
    const item = el('div', `item price-age ${mapPriceFreshness.state}`);
    const swatch = el('span', 'swatch');
    swatch.style.background = mapPriceFreshness.state === 'stale' ? '#e85d75'
      : mapPriceFreshness.state === 'aging' ? '#ffab3d' : '#4fd48a';
    item.append(swatch, el('span', null, mapPriceFreshness.label));
    legend.append(item);
  };

  const appendServiceLegend = () => {
    const shown = new Set();
    for (const location of locations) {
      const highlighted = highlightIds?.has(location.rawId) ?? false;
      if (!showServiceBadges(location, highlighted)) continue;
      for (const service of servicesAt(location)) shown.add(service);
    }

    for (const service of shown) {
      const item = el('div', 'item');
      item.append(el('span', 'service-tip', SERVICE_META[service]?.icon || '•'));
      item.append(el('span', null, `${SERVICE_META[service]?.label || service} badge`));
      legend.append(item);
    }
  };

  // Shaded commodity mode swaps the kind legend for the price gradient: in
  // that mode colour means price, so the legend must say so.
  if (shadeScale) {
    const item = el('div', 'item');

    for (let i = 0; i <= 4; i++) {
      const swatch = el('span', 'swatch');
      swatch.style.background = shadeColour(i / 4);
      item.append(swatch);
    }

    const lo = Math.round(shadeScale.invert ? shadeScale.max : shadeScale.min).toLocaleString();
    const hi = Math.round(shadeScale.invert ? shadeScale.min : shadeScale.max).toLocaleString();
    item.append(el('span', null, `${shadeScale.label} · ${lo} → ${hi} ${shadeScale.unit}`));
    legend.append(item);

    const plain = el('div', 'item');
    const swatch = el('span', 'swatch');
    swatch.style.background = NO_TRADE;
    plain.append(swatch);
    plain.append(el('span', null, shadeScale.plain ?? 'no UEX price for it here'));
    legend.append(plain);
    appendPriceFreshness();
    appendServiceLegend();
    return;
  }

  const kinds = [...new Set(locations.map((l) => l.kind))].sort();

  for (const kind of kinds) {
    const item = el('div', 'item');

    // The legend draws the mark itself rather than a square of its colour -
    // there is no point naming a shape the key does not show.
    const swatch = document.createElementNS(SVG_NS, 'svg');
    swatch.setAttribute('viewBox', '-1.35 -1.35 2.7 2.7');
    swatch.setAttribute('class', 'swatch-mark');
    swatch.append(kindMark(kind, 0, 0, 1, KIND_COLOURS[kind] || KIND_COLOURS.Unknown, true));
    item.append(swatch);
    item.append(el('span', null, kind.replace(/([a-z])([A-Z])/g, '$1 $2')));
    legend.append(item);
  }

  appendPriceFreshness();
  appendServiceLegend();
}

/* ---------- filters ---------- */

/** Debounced so typing does not re-render on every keystroke. */
function onInput(selector, handler) {
  const node = $(selector);
  if (!node) return;

  let timer = null;
  const run = () => {
    clearTimeout(timer);
    timer = setTimeout(handler, 120);
  };

  node.addEventListener('input', run);
  node.addEventListener('change', handler);
}

/* ---------- search everything ---------- */

/**
 * Where each kind of hit goes when it is clicked.
 *
 * The four the entity drawer already describes open there; the rest are the
 * reader's own work and belong on the page that owns them. A hit with nowhere
 * to go is not offered as a link, because a result that does nothing when
 * pressed is worse than one that is plainly just an answer.
 */
const SEARCH_OPENS = {
  place: (hit) => openEntity('place', hit.id),
  ship: (hit) => openEntity('ship', hit.id),
  part: (hit) => openEntity('part', hit.id),
  commodity: (hit) => openEntity('commodity', hit.id),
  job: () => showView('jobs'),
  checklist: () => showView('checklists'),
  kit: () => showView('loadout'),
  note: () => showView('map'),
  run: () => showView('map'),
};

async function runGlobalSearch() {
  const box = $('#global-search');
  const panel = $('#global-results');
  const q = box.value.trim();

  if (q.length < 2) {
    panel.hidden = true;
    return;
  }

  const results = await getJson(`/api/search?q=${encodeURIComponent(q)}`);

  panel.hidden = false;
  panel.textContent = '';

  // Nothing matching is an answer, and saying it beats an empty frame the
  // reader has to work out for themselves.
  if (results.nothing) {
    panel.append(el('div', 'search-empty', `Nothing matches “${q}”.`));
    return;
  }

  for (const group of results.groups) {
    if (!group.hits.length) continue;

    panel.append(el('div', 'search-source', group.source));

    for (const hit of group.hits) {
      const open = SEARCH_OPENS[hit.kind];
      const row = el(open ? 'button' : 'div', 'search-hit');

      row.append(el('span', 'name', hit.name));
      row.append(el('span', 'why muted', hit.why));

      if (open) {
        row.type = 'button';
        row.addEventListener('click', () => {
          panel.hidden = true;
          box.value = '';
          open(hit);
        });
      }

      panel.append(row);
    }
  }
}

onInput('#global-search', () => runGlobalSearch().catch(() => {}));

$('#global-search')?.addEventListener('keydown', (event) => {
  // Escape puts the page back rather than leaving a panel over it.
  if (event.key === 'Escape') {
    $('#global-results').hidden = true;
    $('#global-search').value = '';
  }
});


/**
 * Re-fetches totals for one view's chosen window and re-renders just that view.
 *
 * Aggregation happens server-side, so a period change is a round trip rather
 * than a client-side filter - the browser never holds per-session detail for
 * spending, contracts or places.
 */
async function refreshForPeriod(selectId, render) {
  const days = Number($(selectId).value) || 0;

  try {
    const stats = await getJson(`/api/stats?days=${days}`);
    render(stats);
  } catch (error) {
    console.error(`period refresh failed for ${selectId}`, error);
  }
}

onInput('#fleet-search', renderFleetShips);
onInput('#fleet-period', renderFleetShips);
onInput('#fleet-filter', renderFleetShips);
$('#fleet-picture')?.addEventListener('change', () => {
  shipPictureStyle = $('#fleet-picture').value === 'tint' ? 'tint' : 'paint';
  try { localStorage.setItem('qw-ship-picture-style', shipPictureStyle); } catch { /* fine */ }
  renderFleetShips();
  renderHangar();
});

onInput('#spending-period', () => refreshForPeriod('#spending-period', renderSpending));
onInput('#contracts-period', () => refreshForPeriod('#contracts-period', renderContracts));
onInput('#places-period', () => refreshForPeriod('#places-period', renderPlaces));
onInput('#places-search', () => libraryStats && renderPlaces(libraryStats));
onInput('#ledger-period', loadLedger);
onInput('#commodities-period', loadCommodities);
onInput('#loadout-search', () => libraryStats && renderLoadout(libraryStats));
onInput('#stash-search', () => libraryStats && renderStash(libraryStats));
onInput('#stash-period', () => libraryStats && renderStash(libraryStats));
onInput('#stash-latest', () => libraryStats && renderStash(libraryStats));
$('#stash-ever')?.addEventListener('change', () => libraryStats && renderStash(libraryStats));

/* ---------- stale prices ---------- */

/**
 * Offers to renew the price table when it has gone stale.
 *
 * UEX is fetched on a click unless the automatic refresh has been turned on,
 * and a click-only table has one cost: one pulled a fortnight ago looks exactly
 * like one pulled this morning, and every margin on the page is quietly wrong.
 * So the app looks once at startup, and if the snapshot has turned a day old it
 * says so and offers the one click that fixes it.
 *
 * This is the path for everyone who left the refresh off, and it stays for
 * them: with it on the table never reaches a day old, so the offer simply never
 * fires rather than needing to know about it.
 *
 * An offer, not an alert: nothing is blocked, dismissing it lasts the day, and
 * the check runs once per load rather than on any schedule.
 */
const STALE_AFTER_HOURS = 24;
const STALE_DISMISSED = 'qw-uex-stale-dismissed';

/** Feeds enabled alongside the price table, which age at the same rate. */
let staleFeeds = [];

function dismissedToday() {
  try {
    const until = Number(localStorage.getItem(STALE_DISMISSED) || 0);
    return until > Date.now();
  } catch {
    return false;
  }
}

const hoursSince = (iso) => (Date.now() - new Date(iso).getTime()) / 3600000;

async function checkPriceAge() {
  const notice = $('#stale');
  if (!notice || dismissedToday()) return;

  let uex;
  try {
    uex = await getJson('/api/uex');
  } catch {
    return;
  }

  // Nothing to renew when the integration is off or has never been fetched:
  // the Settings page already offers to turn it on, and being nagged about a
  // feature you have not enabled is noise.
  if (!uex.enabled || !uex.fetchedAt) return;

  const age = hoursSince(uex.fetchedAt);

  staleFeeds = await getJson('/api/uex/feeds')
    .then((feeds) => feeds.filter((f) => f.enabled && (!f.fetchedAt || hoursSince(f.fetchedAt) >= STALE_AFTER_HOURS)))
    .catch(() => []);

  if (age < STALE_AFTER_HOURS && !staleFeeds.length) return;

  const parts = [`Prices last fetched ${ago(uex.fetchedAt)}`];

  if (staleFeeds.length) {
    parts.push(`${staleFeeds.length} other feed${staleFeeds.length === 1 ? '' : 's'} as old`);
  }

  parts.push('margins and best-price rankings are only as fresh as this');

  $('#stale-detail').textContent = `${parts.join(' · ')}.`;
  notice.hidden = false;
}

function initStaleNotice() {
  const notice = $('#stale');
  if (!notice) return;

  $('#stale-refresh').addEventListener('click', async (event) => {
    const button = event.currentTarget;
    button.disabled = true;
    button.textContent = 'Fetching…';

    try {
      // The prices first, then whatever else had gone stale with them: a
      // refresh that renewed half of it would leave the same problem behind.
      await fetch('/api/uex/enable', { method: 'POST' });

      for (const feed of staleFeeds) {
        await fetch(`/api/uex/feeds/${encodeURIComponent(feed.key)}/enable`, { method: 'POST' });
      }

      notice.hidden = true;
      loadMarket().catch(() => { /* the page keeps the numbers it has */ });
      renderSettings().catch(() => { /* Settings redraws on its next visit */ });
    } catch {
      button.textContent = 'Could not fetch';
    } finally {
      button.disabled = false;
    }
  });

  $('#stale-dismiss').addEventListener('click', () => {
    notice.hidden = true;

    // Until tomorrow rather than forever: the answer to "not now" is "ask me
    // again when it matters", and by then the prices are a day older still.
    try {
      localStorage.setItem(STALE_DISMISSED, String(Date.now() + 86400000));
    } catch { /* private browsing: the offer returns on the next load */ }
  });
}

/* ---------- the wipe ---------- */

/**
 * The line under the player's history, on the Settings page.
 *
 * Every total the app reports describes the account being played now, and a
 * data wipe ends one account and starts another. The date is a setting because
 * CIG decides when wipes land, and because someone looking back at an older
 * patch should be able to wind it back and see the lot.
 */
async function loadWipe() {
  const field = $('#wipe-at');
  if (!field) return;

  let wipe;
  try {
    wipe = await getJson('/api/wipe');
  } catch {
    return;
  }

  field.value = wipe.at ? new Date(wipe.at).toISOString().slice(0, 10) : '';
  $('#wipe-patch').value = wipe.patch === 'no wipe' ? '' : wipe.patch;

  for (const [name, box] of Object.entries(WIPE_SCOPES)) {
    $(box).checked = (wipe.covers || []).includes(name);
  }

  showWipeStatus(wipe);
}

/** What a wipe can take, and the box that says whether this one did. */
const WIPE_SCOPES = {
  money: '#wipe-money',
  ships: '#wipe-ships',
  inventory: '#wipe-inventory',
  history: '#wipe-history',
};

const chosenScopes = () =>
  Object.entries(WIPE_SCOPES).filter(([, box]) => $(box).checked).map(([name]) => name);

function showWipeStatus(wipe) {
  const status = $('#wipe-status');
  if (!status) return;

  if (!wipe.at) {
    status.textContent = `counting all ${(wipe.stored ?? 0).toLocaleString()} sessions`;
    return;
  }

  if (wipe.hidden === 0) {
    status.textContent = 'nothing on record from before this';
    return;
  }

  const covers = wipe.covers || [];
  const sessions = `${wipe.hidden.toLocaleString()} session${wipe.hidden === 1 ? '' : 's'} before this`;

  // A partial wipe hides nothing outright, so saying "not counted" flat would
  // be a lie: those sessions still count towards everything it did not take.
  status.textContent = covers.length === Object.keys(WIPE_SCOPES).length
    ? `${sessions} are kept but not counted`
    : `${sessions} still count, except for ${covers.join(', ')}`;
}

async function saveWipe(at, patch) {
  const status = $('#wipe-status');

  try {
    const response = await fetch('/api/wipe', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ at, patch, covers: chosenScopes() }),
    });

    if (!response.ok) throw new Error(response.statusText);

    // Every page's numbers just changed, so they are all re-read rather than
    // left to be discovered stale on the next visit.
    await loadHistory();
    await loadWipe();

    if (status) status.textContent = `${status.textContent} · saved`;
  } catch (e) {
    if (status) status.textContent = `could not save: ${e.message}`;
  }
}

function initWipe() {
  const field = $('#wipe-at');
  if (!field) return;

  $('#wipe-save').addEventListener('click', () => {
    if (!field.value) {
      $('#wipe-status').textContent = 'pick a date, or use "count everything"';
      return;
    }

    saveWipe(`${field.value}T00:00:00Z`, $('#wipe-patch').value.trim());
  });

  $('#wipe-clear').addEventListener('click', () => saveWipe(null, null));

  // A depth changed without a date is still a change worth keeping, and there
  // is no second Save button to reach for.
  for (const box of Object.values(WIPE_SCOPES)) {
    $(box).addEventListener('change', () => {
      if (field.value) saveWipe(`${field.value}T00:00:00Z`, $('#wipe-patch').value.trim());
    });
  }
}

/* ---------- new versions ---------- */

/**
 * Asks, once, whether this copy may look for a newer one.
 *
 * The app's standing promise is that it connects only when asked, and a version
 * check is a connection. So the first start puts the question on screen with
 * three answers - every start, just this once, or never - and never asks again
 * whichever way it goes. The check itself is a plain GET of a public release
 * feed: it sends nothing, and what it learns is what anyone can read.
 */
async function checkForUpdate() {
  const notice = $('#update');
  if (!notice || isOverlay) return;

  let state;
  try {
    state = await getJson('/api/updates');
  } catch {
    return;
  }

  if (!state.asked) {
    askAboutUpdates(state);
    return;
  }

  if (state.automatic) await runUpdateCheck({ quiet: true });
}

/** The question, with its three answers. */
function askAboutUpdates(state) {
  const notice = $('#update');

  $('#update-title').textContent = 'Look for a newer version?';
  $('#update-detail').textContent =
    'One request to GitHub, sending nothing about you or this machine. '
    + 'Nothing is downloaded or installed — you would get a link.';

  const actions = $('#update-actions');
  actions.textContent = '';

  const answer = async (automatic, thenCheck) => {
    await fetch(`/api/updates/answer?automatic=${automatic}`, { method: 'POST' });
    notice.hidden = true;
    renderUpdateSettings().catch(() => { /* Settings redraws on its next visit */ });
    if (thenCheck) await runUpdateCheck({ quiet: false, announce: true });
  };

  const every = el('button', 'ghost', 'Yes, every start');
  every.addEventListener('click', () => answer(true, true));

  const once = el('button', 'ghost', 'Just this once');
  once.addEventListener('click', () => answer(false, true));

  const never = el('button', 'ghost', 'No thanks');
  never.addEventListener('click', () => answer(false, false));

  actions.append(every, once, never);
  notice.hidden = false;
}

/**
 * Runs a check and says what it found.
 *
 * @param quiet Say nothing when this copy is current - true for a startup
 *   check, which nobody asked a question of, and false for a click, which is a
 *   question and deserves an answer either way.
 * @param announce Put the answer in the notice, which every view carries,
 *   rather than only in Settings' status line. A check started from the
 *   toolbar or from the notice itself can be pressed from anywhere, and
 *   "up to date" written into a panel the reader is not looking at is the
 *   same as no answer at all - which is the half of the promise above that
 *   the status line alone could not keep.
 */
async function runUpdateCheck({ quiet, announce = false }) {
  const notice = $('#update');

  let result;
  try {
    const response = await fetch('/api/updates/check', { method: 'POST' });

    // A dropped connection rejects, but a server whose own call to GitHub threw
    // answers 500 - and reading that as JSON yields null, which used to fall
    // through to result.newer and take the whole handler down with it. Both
    // failures are the same failure to the reader, so both take the same path.
    if (!response.ok) throw new Error(`the check answered ${response.status}`);

    result = await response.json();
  } catch {
    if (!quiet) $('#update-status').textContent = 'could not reach GitHub just now';
    if (announce) tellUpdateNotice('Could not reach GitHub', 'The check did not get through. Try again in a moment.');
    return;
  }

  // Awaited, and not fired off: this refreshes the Settings block from the
  // server, and the last thing it does is rewrite the very status line the
  // answer below is about to write. Left un-awaited it lands one microtask
  // later and overwrites the answer with "never checked" - which is what a
  // real browser did all along, since a fetch cannot resolve before the
  // synchronous line after it. The old engine drained it eagerly and hid this.
  await renderUpdateSettings().catch(() => { /* the toggle is still right */ });

  if (!result.newer) {
    if (!quiet) $('#update-status').textContent = `up to date — ${result.current} is the newest`;
    if (announce) tellUpdateNotice(`Quantum Wake ${result.current} is the newest`, 'Nothing to update.');
    else notice.hidden = true;
    return;
  }

  $('#update-title').textContent = `Quantum Wake ${result.latest} is out`;
  $('#update-detail').textContent = `You are running ${result.current}.`
    + (result.publishedAt ? ` Published ${dayUtc(result.publishedAt)}.` : '');

  const actions = $('#update-actions');
  actions.textContent = '';

  // Only offered when the server says this copy can actually replace itself: a
  // source build cannot, and a button that explains itself only after being
  // pressed is worse than one that was never there.
  if (result.canInstall) actions.append(updateNowButton(result));

  const open = el('button', 'ghost', result.canInstall ? 'Read the notes' : 'Open the release page');
  open.addEventListener('click', () => {
    window.open(result.url, '_blank', 'noreferrer');
    if (!result.canInstall) notice.hidden = true;
  });

  const later = el('button', 'ghost', 'Later');
  later.addEventListener('click', () => { notice.hidden = true; });

  actions.append(open, later);
  notice.hidden = false;
}

/**
 * An answer with no newer version behind it: says its piece and offers only a
 * way to dismiss itself, because there is nothing else to do about it.
 */
function tellUpdateNotice(title, detail) {
  const notice = $('#update');

  $('#update-title').textContent = title;
  $('#update-detail').textContent = detail;

  const actions = $('#update-actions');
  actions.textContent = '';

  const close = el('button', 'ghost', 'Close');
  close.addEventListener('click', () => { notice.hidden = true; });
  actions.append(close);

  notice.hidden = false;
}

/**
 * The one-click update.
 *
 * The whole thing happens on the server - fetch, check the hash GitHub
 * published, move the running file aside, put the new one in place - so this
 * only has to say what is happening and stay honest when it does not work.
 *
 * Ninety megabytes takes a while on a slow line, and a button that looks
 * unresponsive for a minute gets pressed again, so it disables itself and says
 * so rather than leaving the reader guessing.
 */
function updateNowButton(result) {
  // The size is on the button rather than in the detail line, because it is
  // part of what is being agreed to: on a metered connection ninety megabytes
  // is somebody's actual money, and finding out afterwards is too late.
  const size = result.downloadBytes
    ? ` · ${Math.round(result.downloadBytes / 1048576)} MB`
    : '';

  const install = el('button', 'ghost on', `Update to ${result.latest}${size}`);
  install.title = 'Downloads it, checks it, and restarts into the new version';

  install.addEventListener('click', async () => {
    install.disabled = true;
    install.textContent = 'Downloading…';
    $('#update-detail').textContent = 'Fetching the new version and checking it against '
      + 'what GitHub published. This can take a minute.';

    let answer;
    try {
      const response = await fetch('/api/updates/install', { method: 'POST' });
      answer = await response.json().catch(() => null);

      if (!response.ok) {
        // The server's own words: it knows whether the folder was writable,
        // the download was short, or something had the file open.
        $('#update-detail').textContent = answer?.message || 'The update could not be applied.';
        install.textContent = 'Try again';
        install.disabled = false;
        return;
      }
    } catch {
      $('#update-detail').textContent = 'The download did not finish, so nothing was replaced.';
      install.textContent = 'Try again';
      install.disabled = false;
      return;
    }

    // Two endings, and they are different promises. One restarts itself; the
    // other has already swapped the file and needs a hand.
    install.textContent = answer.restarting ? 'Restarting…' : 'Installed';
    $('#update-detail').textContent = answer.restarting
      ? `Quantum Wake ${answer.version} is installed. Restarting now.`
      : `Quantum Wake ${answer.version} is installed. Close this and start it again to use it.`;
  });

  return install;
}

/** The Settings block: the toggle, and what the last look found. */
async function renderUpdateSettings() {
  const toggle = $('#update-auto');
  if (!toggle) return;

  const state = await getJson('/api/updates');
  toggle.checked = !!state.automatic;

  const status = $('#update-status');
  if (!status) return;

  status.textContent = state.lastCheckedAt
    ? `last checked ${ago(state.lastCheckedAt)}`
    : 'never checked';
}

function initUpdates() {
  // Bound before the Settings guard: the toolbar item is on the page whether
  // or not the Settings block is, and it is the whole point of this one.
  const fromMenu = $('#menu-update-check');
  if (fromMenu) {
    fromMenu.addEventListener('click', async () => {
      // The group menu is held open by :focus-within, and this item does not
      // change view - so without letting go of the focus the menu stays hanging
      // over the answer it just asked for.
      fromMenu.blur();
      fromMenu.disabled = true;

      try {
        await runUpdateCheck({ quiet: false, announce: true });
      } finally {
        fromMenu.disabled = false;
      }
    });
  }

  const toggle = $('#update-auto');
  if (!toggle) return;

  toggle.addEventListener('change', async () => {
    await fetch(`/api/updates/answer?automatic=${toggle.checked}`, { method: 'POST' });
    renderUpdateSettings().catch(() => { /* the box already shows the choice */ });
  });

  $('#update-check').addEventListener('click', async (event) => {
    const button = event.currentTarget;
    button.disabled = true;
    $('#update-status').textContent = 'looking…';

    try {
      await runUpdateCheck({ quiet: false });
    } finally {
      button.disabled = false;
    }
  });
}

/**
 * Offers to move the wipe line when a new patch has landed since it.

 *
 * Nothing in the logs says an account was reset - there is no such line. What
 * they do say is when a patch arrived, and wipes arrive with patches, so the
 * app brings the date and the player answers the one question it cannot: did
 * that one wipe? Answering either way is remembered for that patch, so it is
 * asked once rather than every launch.
 */
const PATCH_ANSWERED = 'qw-patch-answered';

function patchAnswered(patch) {
  try {
    return (localStorage.getItem(PATCH_ANSWERED) || '').split(',').includes(patch);
  } catch {
    return false;
  }
}

function rememberPatchAnswer(patch) {
  try {
    const seen = (localStorage.getItem(PATCH_ANSWERED) || '').split(',').filter(Boolean);
    if (!seen.includes(patch)) seen.push(patch);
    localStorage.setItem(PATCH_ANSWERED, seen.join(','));
  } catch { /* private browsing: it asks again next time, which is not harmful */ }
}

/** The patch offered right now, so the buttons know what they are answering. */
let offeredPatch = null;

async function checkForWipe() {
  const notice = $('#patch');
  if (!notice) return;

  let wipe;
  try {
    wipe = await getJson('/api/wipe');
  } catch {
    return;
  }

  const found = wipe.suggested;
  if (!found || patchAnswered(found.patch)) return;

  offeredPatch = found;

  $('#patch-title').textContent = `${found.patch} arrived on ${dayUtc(found.at)}`;
  $('#patch-detail').textContent = wipe.at
    ? `Your history is counted from ${dayUtc(wipe.at)}. If that patch wiped, the line belongs there instead.`
    : 'Nothing is being held back at the moment. If that patch wiped, your totals are counting an account you no longer have.';

  notice.hidden = false;
}

function initWipePrompt() {
  const notice = $('#patch');
  if (!notice) return;

  $('#patch-wiped').addEventListener('click', async () => {
    if (!offeredPatch) return;

    rememberPatchAnswer(offeredPatch.patch);
    notice.hidden = true;

    // Straight to the full depth: a patch wipe is the ordinary kind, and the
    // Settings page is where a partial one gets its detail.
    await saveWipe(offeredPatch.at, offeredPatch.patch);
  });

  $('#patch-kept').addEventListener('click', () => {
    if (offeredPatch) rememberPatchAnswer(offeredPatch.patch);
    notice.hidden = true;
  });
}

/* Wired at load, like the other page-level controls
: neither belongs to a
   view, and both must work before anything has been rendered. */
initStaleNotice();
initWipe();
initWipePrompt();
initUpdates();
initStarStrings();
initTextOverlay();

/* ---------- scan progress ---------- */

/**
 * Polls the scan and reflects it in a progress bar.
 *
 * A cold backfill reads 400 MB across ~145 files. Previously the page simply sat
 * empty while boot() retried in silence, which is indistinguishable from being
 * broken.
 */
async function watchScan() {
  let sawRunning = false;

  for (;;) {
    let status;
    try {
      status = await getJson('/api/scan/status');
    } catch {
      await wait(1000);
      continue;
    }

    const finished = paintScan(status, sawRunning);
    sawRunning = status.running;

    // The file table follows the same poll while it is on screen, so the row
    // being parsed says so rather than the bar alone. The status is kept
    // either way, so opening the pane mid-scan draws the pass already under way.
    const wasScanning = scanNow !== null;
    scanNow = status.running ? status : null;
    if ((status.running || wasScanning) && $('#view-log')?.classList.contains('active') && logPane === 'files')
      paintScanFiles(status);

    if (finished) {
      // The bar holds on "complete" long enough to be read, then goes.
      await wait(1200);
      $('#scan').hidden = true;

      try {
        await loadHistory();
      } catch { /* the retry loop in boot covers this */ }

      // The file table is the one page that is *about* the scan that just
      // ended, so it does not wait for a click to show what it read.
      if ($('#view-log')?.classList.contains('active') && logPane === 'files')
        loadScanHistory().catch(() => {});
    }

    // Never returns. The forced rescan on the Settings page re-reads all 400 MB
    // and is by far the slowest scan there is; a watcher that stopped at the
    // end of the boot scan left that one with no bar at all, and only a
    // "rescanning…" line beside the button.
    await wait(status.running ? 400 : 1000);
  }
}

/**
 * Draws one poll of the scan status on the bar.
 *
 * Split from the loop so the transitions can be asserted: the loop is paced by
 * setTimeout, and a test has no way to advance it.
 *
 * @returns true when this is the poll that finished a scan, so the caller can
 *   retire the bar and reload the views behind it.
 */
function paintScan(status, sawRunning) {
  const panel = $('#scan');

  if (status.running) {
    panel.hidden = false;

    $('#scan-fill').style.width = `${status.percent}%`;
    $('#scan-count').textContent = `${status.done} / ${status.total} · ${status.elapsedSeconds}s`;
    $('#scan-file').textContent = status.file || '';

    $('#scan-label').textContent = status.parsed > 0
      ? `Parsing logs — ${status.parsed} new`
      : 'Checking logs…';

    return false;
  }

  // An idle server is not a finished scan. Without this the bar would announce
  // "scan complete" on the first poll of every load, for a scan that ended
  // before the page was open — or never ran.
  if (!sawRunning)
    return false;

  $('#scan-fill').style.width = '100%';
  $('#scan-label').textContent = 'Scan complete';
  $('#scan-count').textContent = `${status.parsed} parsed · ${status.elapsedSeconds}s`;
  $('#scan-file').textContent = '';

  return true;
}

/**
 * The wizard's own copy of the bar.
 *
 * The wizard is a fixed, opaque sheet over the whole page, so the bar beneath
 * it cannot be seen — and first run is the one time the scan has half a minute
 * of real work to show.
 */
function paintSetupScan(status) {
  if (status.running) {
    $('#setup-scan-fill').style.width = `${status.percent}%`;

    // Files, not events: ScanStatus counts one per log it had to parse, and a
    // wizard promising events while counting files overstated it by thousands.
    $('#setup-scan-label').textContent = status.parsed > 0
      ? `Reading logs — ${status.parsed} new`
      : 'Checking logs…';

    $('#setup-scan-count').textContent = `${status.done} / ${status.total} files`;
    return;
  }

  $('#setup-scan-fill').style.width = '100%';
  $('#setup-scan-label').textContent = 'Logs read — history ready';
  $('#setup-scan-count').textContent = '';
}

const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/* ---------- boot ---------- */

/**
 * The first-flight wizard: shown once, over everything, while the initial
 * backfill runs. It fronts the three choices that matter on day one - the
 * overlay, the community dataset, UEX prices - because they are opt-in and
 * would otherwise hide in Settings while the app looked half-empty. Applying
 * them reloads the page so every view boots with the datasets in.
 */
/* What the wizard offered for the wipe, so the submit can say which patch it
   was rather than recording the day the question was answered. */
let setupWipeOffered = null;
let setupWipePatch = 'set at first run';

async function maybeShowSetup() {

  if (isOverlay) return;

  // ?setup=1 forces the wizard - a preview that skips nothing permanent.
  if (!params.has('setup')) {
    if (isSnapshot) return;
    if ((await getJson('/api/setup')).done) return;
  }

  const panel = $('#setup');
  panel.hidden = false;

  // The overlay choice only exists when this server lives inside the app.
  try {
    const overlay = await getJson('/api/overlay');
    $('#setup-overlay-row').hidden = !overlay.available;
  } catch { $('#setup-overlay-row').hidden = true; }

  // The extra UEX feeds, offered here too - but only once UEX itself is
  // ticked, since they are useless without the core price tables.
  try {
    const feeds = await getJson('/api/uex/feeds');
    const list = $('#setup-feed-list');
    list.textContent = '';

    for (const feed of feeds) {
      const row = el('label', 'setup-feed');
      const box = document.createElement('input');
      box.type = 'checkbox';
      box.dataset.feed = feed.key;

      const text = el('div');
      text.append(el('b', null, feed.title));
      text.append(el('span', 'cost', ` ${feed.cost}`));
      text.append(el('span', null, feed.description));

      row.append(box);
      row.append(text);
      list.append(row);
    }

    // The wipe, offered before anything has been counted. It defaults to the
    // last wipe there is evidence of, not to the newest patch: a patch is not
    // a wipe - 4.9 and 4.10 both kept long-term persistence - and defaulting to
    // the newest one quietly asserted a reset that never happened, hiding every
    // session before it. The newest patch is named underneath instead, for the
    // reader whose last wipe really was that one.
    try {
      const wipe = await getJson('/api/wipe');
      const suggested = wipe.suggested;

      $('#setup-wipe').value = new Date(wipe.at || wipe.default || Date.now())
        .toISOString().slice(0, 10);

      setupWipeOffered = $('#setup-wipe').value;
      setupWipePatch = wipe.patch || 'set at first run';


      $('#setup-wipe-note').textContent = suggested
        ? `${wipe.patch} — the last wipe this install has evidence of.`
          + ` ${suggested.patch} arrived ${dayUtc(suggested.at)}; set it to then only if`
          + ' that one reset your account.'
        : `${wipe.patch} — change it if your last wipe was another one.`;
    } catch { /* the field keeps whatever the markup had */ }

    const uexBox = $('#setup-uex');

    // The feed list and the refresh switch are both conditions of taking UEX at
    // all, so they appear with it and go away with it - and the switch is
    // cleared on the way out, or unticking UEX would leave an agreement behind
    // for a thing that was never enabled.
    const syncFeeds = () => {
      $('#setup-feeds').hidden = !uexBox.checked;
      $('#setup-uex-auto-row').hidden = !uexBox.checked;

      if (!uexBox.checked) $('#setup-uex-auto').checked = false;
    };

    uexBox.addEventListener('change', syncFeeds);
    syncFeeds();
  } catch { /* no feed list; the wizard still works */ }

  const poll = setInterval(async () => {
    try {
      paintSetupScan(await getJson('/api/scan/status'));
    } catch { /* server between restarts; the next tick answers */ }
  }, 700);

  $('#setup-start').addEventListener('click', async () => {
    const button = $('#setup-start');
    const status = $('#setup-status');
    button.disabled = true;

    try {
      if (!$('#setup-overlay-row').hidden && $('#setup-overlay').checked)
        await fetch('/api/overlay?visible=true', { method: 'POST' }).catch(() => {});

      if ($('#setup-community').checked) {
        status.textContent = 'Fetching the community dataset — a minute or two…';
        await fetch('/api/community/enable', { method: 'POST' });
      }

      if ($('#setup-uex').checked) {
        status.textContent = 'Fetching UEX prices…';
        await fetch('/api/uex/enable', { method: 'POST' });

        // Extra feeds one at a time, so one failing does not take the rest.
        for (const box of $$('#setup-feed-list input:checked')) {
          status.textContent = `Fetching the ${box.dataset.feed} feed…`;
          await fetch(`/api/uex/feeds/${box.dataset.feed}/enable`, { method: 'POST' })
            .catch(() => {});
        }

        // Recorded as an answer either way: someone who read the option and
        // left it alone has declined, and should not be asked a second time.
        await fetch(
          `/api/uex/auto/answer?automatic=${$('#setup-uex-auto').checked}`,
          { method: 'POST' }).catch(() => {});
      }

      const chosenWipe = $('#setup-wipe').value;

      if (chosenWipe) {
        status.textContent = 'Setting where your history starts…';

        // Name the patch when the offered date is kept: 'set at first run' says
        // when the line was decided, which is not what the Settings page needs
        // to tell somebody months later.
        const patch = chosenWipe === setupWipeOffered ? setupWipePatch : 'set at first run';

        await fetch('/api/wipe', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ at: `${chosenWipe}T00:00:00Z`, patch }),
        }).catch(() => { /* Settings can set it later */ });
      }

      await fetch('/api/setup/done', { method: 'POST' });
      clearInterval(poll);

      // A clean reboot with everything enabled beats patching each view.
      location.reload();
    } catch {
      status.textContent = 'Something did not fetch — you can finish any of this in Settings.';
      button.disabled = false;
    }
  });
}

async function boot() {
  initNowCardCollapsers();
  initPageStatsCollapsers();

  if (isOverlay) {
    document.body.classList.add('overlay');

    // The widget's layout is chosen in the dashboard, a different browser, so
    // it is polled rather than pushed.
    applyOverlayLayout().catch(() => {});
    setInterval(() => applyOverlayLayout().catch(() => {}), 5000);
  }

  const deepCommodity = commodityFromHash();
  const requested = viewFromHash();

  if (deepCommodity) openCommodity(deepCommodity).catch(() => {});
  else if (requested) showView(requested);
  // No fragment lands on Now without a view switch, and Now is not a page
  // about prices: the notice starts as the chip there.
  else $('#stale')?.classList.add('compact');

  // ?q= pre-fills the map search, so a commodity view is a shareable link:
  // /?q=Copper#map opens the map with the sellers lit.
  const q = params.get('q');
  if (q) $('#map-search').value = q;

  initMap();

  // The current location on Now flies to the map like every other place name.
  $('#now-location').classList.add('now-jump');
  $('#now-location').title = 'Show on the map';
  $('#now-location').addEventListener('click', () => {
    const name = $('#now-location').textContent.trim();
    if (name && name !== '—') jumpToPlace(name);
  });

  try {
    const install = await getJson('/api/install');
    $('#install').textContent = `${install.channel} · ${install.backups} logs`;
    $('#about-install').textContent = `${install.channel} · ${install.backups} logs`;
  } catch {
    $('#install').textContent = 'no install found';
    $('#about-install').textContent = 'none found';

    // Nothing to read: ask where the game lives rather than showing an
    // app full of empty pages.
    if (!isOverlay) $('#no-install').hidden = false;
  }

  try {
    const info = await getJson('/api/version');

    // The build string carries the commit ("0.2.0+9c3cdf7..."); seven hash
    // characters identify it and forty just wrap the layout.
    const build = (info.build || info.version).replace(/\+([0-9a-f]{7})[0-9a-f]*$/i, '+$1');

    $('#about-version').textContent = build;
    $('#foot-version').textContent = `v${info.version}`;
    $('#foot-version').title = `Build ${build}`;
  } catch {
    $('#about-version').textContent = 'unknown';
  }

  if (!isSnapshot) {
    connectStream();
    watchScan();

    // Once per load, never on a timer: the offer to renew a price table that
    // has gone a day old, and the line the wipe draws under the history.
    checkPriceAge().catch(() => { /* prices are usable whatever their age */ });
    checkForWipe().catch(() => { /* the Settings page still carries the line */ });
    checkForUpdate().catch(() => { /* an unanswered question is not a failure */ });
  }

  renderUpdateSettings().catch(() => { /* Settings fills in on its next visit */ });

  loadWipe().catch(() => { /* Settings shows it on its next visit */ });

  maybeShowSetup().catch(() => { /* wizard is a nicety, never a blocker */ });

  // The first scan may still be running; retry until sessions appear.
  for (let attempt = 0; attempt < 30; attempt++) {
    try {
      await loadHistory();
      const count = (await getJson('/api/sessions')).length;
      if (count > 0) break;
    } catch { /* server still warming up */ }
    await wait(2000);
  }
}

boot();
